
// ═══════════════════════════════════════════════════════════
//  GLOBAL DATE DISPLAY FORMAT — DD/MM/YYYY EVERYWHERE
// ─────────────────────────────────────────────────────────────
//  Single shared formatter every display-only date in the ERP now
//  routes through. Internal storage/comparison logic (ISO
//  yyyy-mm-dd strings used for sorting, range checks, working-day
//  math, etc.) is completely untouched — this only changes what is
//  RENDERED on screen/print/PDF. Accepts a Date object, an ISO
//  yyyy-mm-dd , or a full ISO timestamp string.
// ═══════════════════════════════════════════════════════════
window.fmtDMY = function (stringinput) {
  if (!input) return '—';
  var d;
  if (input instanceof Date) {
    d = input;
  } else {
    var s = String(input);
    // Plain yyyy-mm-dd: parse as local time (avoids the UTC-midnight
    // day-shift bug that plagues `new Date('yyyy-mm-dd')`).
    d = /^\d{4}-\d{2}-\d{2}$/.test(s) ? new Date(s + 'T00:00:00') : new Date(s);
  }
  if (isNaN(d.getTime())) return String(input);
  var dd = String(d.getDate()).padStart(2, '0');
  var mm = String(d.getMonth() + 1).padStart(2, '0');
  var yyyy = d.getFullYear();
  return dd + '/' + mm + '/' + yyyy;
};
// Same as fmtDMY but appends the time (HH:MM, 24-hour) — for the
// several places that were showing "date + time" together.
window.fmtDMYTime = function (input) {
  if (!input) return '—';
  var d = (input instanceof Date) ? input : new Date(input);
  if (isNaN(d.getTime())) return String(input);
  var hh = String(d.getHours()).padStart(2, '0');
  var min = String(d.getMinutes()).padStart(2, '0');
  return window.fmtDMY(d) + ' ' + hh + ':' + min;
};

function h1OpenRecycleBin(moduleFilter){
  document.getElementById('h1rb-filter').value = moduleFilter || '';
  document.getElementById('h1rb-search').value = '';
  h1RenderRecycleBin();
  openModal('modal-h1-recyclebin');
}

function h1RecycleBinRecordLabel(entry){
  const r = entry.record || {};
  if(entry.module === 'financeFeeMaster') return r.className || entry.recordId;
  if(entry.module === 'financeTransportRoute') return r.place || entry.recordId;
  if(entry.module === 'financeFeeReceipt') return (r.rcpt ? `Receipt ${r.rcpt}` : entry.recordId) + (r.paid ? ` — ₹${r.paid}` : '');
  return entry.recordId;
}

function h1RenderRecycleBin(){
  const tbody = document.getElementById('h1rb-table-body');
  if(!tbody) return;
  const q = (document.getElementById('h1rb-search')?.value || '');
  const filter = document.getElementById('h1rb-filter')?.value || '';
  const entries = H1.recycleBin.search(q, filter || null)
    .filter(e => e.module === 'financeFeeMaster' || e.module === 'financeTransportRoute' || e.module === 'financeFeeReceipt');

  if(!entries.length){
    tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:24px;color:#aaa;">No records found.</td></tr>';
    return;
  }

  const isPrincipal = (typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'principal');

  tbody.innerHTML = entries.map(e => {
    const dt = new Date(e.deletedOn);
    return `<tr>
      <td><span class="badge badge-yellow" style="font-size:11px;">${e.moduleLabel}</span></td>
      <td>${h1RecycleBinRecordLabel(e)}</td>
      <td>${e.deletedBy || '—'} <span style="color:#999;font-size:11px;">(${e.deletedByRole||'—'})</span></td>
      <td style="font-size:12px;white-space:nowrap;">${fmtDMY(dt)}<br/><span style="color:#888;">${dt.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</span></td>
      <td style="font-size:12px;max-width:160px;overflow:hidden;text-overflow:ellipsis;">${e.reason || '—'}</td>
      <td style="white-space:nowrap;">
        <button class="btn btn-outline btn-sm" onclick="h1RestoreRecord('${e.binId}')">↩ Restore</button>
        ${isPrincipal ? `<button class="btn btn-red btn-sm" onclick="h1PermanentDeleteRecord('${e.binId}')">✕ Delete Forever</button>` : ''}
      </td>
    </tr>`;
  }).join('');
}

function h1RestoreRecord(binId){
  H1.ui.confirm('Restore this record back to its live module?', () => {
    const res = H1.recycleBin.restore(binId);
    if(res.ok){
      H1.ui.toast('Record restored.', 'ok');
      // Refresh whichever finance screens are currently mounted
      if(typeof renderFeeMaster === 'function') renderFeeMaster();
      if(typeof renderTransportMaster === 'function') renderTransportMaster();
      if(typeof renderFeeTable === 'function') renderFeeTable();
    } else {
      H1.ui.toast(res.msg || 'Restore failed.', 'error');
    }
    h1RenderRecycleBin();
  }, {title:'Restore Record'});
}

function h1PermanentDeleteRecord(binId){
  H1.ui.confirm('Permanently delete this record? This cannot be undone.', () => {
    const res = H1.recycleBin.permanentDelete(binId);
    H1.ui.toast(res.ok ? 'Record permanently deleted.' : (res.msg || 'Delete failed.'), res.ok ? 'warn' : 'error');
    h1RenderRecycleBin();
  }, {title:'Permanent Delete'});
}

function h1ExportRecycleBinCsv(){
  const q = (document.getElementById('h1rb-search')?.value || '');
  const filter = document.getElementById('h1rb-filter')?.value || '';
  const entries = H1.recycleBin.search(q, filter || null)
    .filter(e => e.module === 'financeFeeMaster' || e.module === 'financeTransportRoute' || e.module === 'financeFeeReceipt');
  H1.ui.exportCsv(entries, [
    {label:'Module', key:'moduleLabel'},
    {label:'Record', value: h1RecycleBinRecordLabel},
    {label:'Deleted By', key:'deletedBy'},
    {label:'Role', key:'deletedByRole'},
    {label:'Deleted On', key:'deletedOn'},
    {label:'Reason', key:'reason'}
  ], 'finance-recycle-bin.csv');
  H1.ui.toast('Recycle Bin exported.', 'ok');
}


