//======================================================
// DNYANANKUR ERP V15 CORE FRAMEWORK
//======================================================

const Core = {

    version: "15.0.0",

    build: "Alpha",

    initialized: false

};

const Cache = {

    students: null,
    teachers: null,
    fees: null,
    marks: null,
    users: null,
    settings: null,

    inventoryItems: null,
    inventoryPackages: null,
    inventoryBills: null,
    inventoryTransactions: null,

    feeMaster: null,

    schoolLedger: null,

    transportLedger: null

};
// School Fee Ledger row is created by assignFeeMaster() (see Financial Engine
// section). assignStudentFinance() calls assignFeeMaster(), not a separate
// createSchoolFeeLedger() — that name never had a real implementation.
function createTransportFeeLedger(student){
  // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.createTransportFeeLedger(). This
  // wrapper preserves the exact original signature/behavior for every
  // existing caller; falls back to the original inline logic below if
  // FeeService has not loaded.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
    return Dnyanankur.Services.Fee.createTransportFeeLedger(student);
  }


    if(student.transportRequired !== "yes")
        return;

    const routes = getTransportMaster();

    const route = routes.find(
        x => x.place === student.transportRoute
    );

    if(!route){
        console.warn("Transport route not found");
        return;
    }

    const ledger = getTransportFeeLedger();

    // Don't duplicate on re-register / edit (mirrors assignFeeMaster's guard)
    if(ledger.find(x => x.studentId === student.id)) return;

    let transportFee = Number(route.annualFee || 0);

    ledger.push({

        createdAt: new Date().toISOString(),

        id: "TFL" + Date.now(),

        studentId: student.id,

        academicYear: student.acyr,

        route: route.place,

        annualFee: transportFee,

        installment1: route.installment1,

        installment2: route.installment2,

        paid: 0,

        balance: transportFee,

        status: "Pending"

    });

    saveTransportFeeLedger(ledger);

    addTransportLedgerEntry({

        studentId: student.id,

        date: new Date().toISOString().split("T")[0],

        transactionType: "ASSIGNMENT",

        particular: "Transport Fee Assigned",

        debit: transportFee,

        credit: 0,

        remarks: "Transport Assignment"

    });
}

function receiveSchoolFee(
    studentId,
    amount,
    installment,
    paymentMode,
    remarks=""
){
const receiptNo = getNextReceiptNo();
const paymentDate = new Date().toISOString();

    const ledger = getSchoolFeeLedger();

    const row = ledger.find(
        x=>x.studentId===studentId
    );

    if(!row){
        // Auto-create a ledger row if missing (handles students registered before fee master was set up)
        const feeMaster = getFeeMaster();
        const student = getStudents().find(s => s.id === studentId);
        if(student) {
            const master = feeMaster.find(f => f.className === getFeeMasterClassName(student));
            if(master) {
                assignFeeMaster(student);
                receiveSchoolFee(studentId, amount, installment, paymentMode, remarks);
                return;
            }
        }
        alert("School fee ledger not found. Please ensure Fee Master has a rate for this student's class.");
        return;
    }

    amount = Number(amount);

    if(amount<=0){
        alert("Invalid amount");
        return;
    }

    // Allow overpay (advance); saveFee already warned the user
    row.paid = Number(row.paid || 0) + amount;
    row.balance = Math.max(0, Number(row.payable || 0) - row.paid);

    if(row.balance===0){
        row.status="Paid";
    }else{
        row.status="Partial";
    }

    saveSchoolFeeLedger(ledger);

    const tx = getFeeTransactions();

tx.push({

    id: "TX" + Date.now(),

    receiptNo,

    studentId,

    academicYear: row.academicYear,

    ledger: "school",

    installment,

    amount,

    paymentMode,

    remarks,

    collectedBy: currentUser?.username || "System",

    date: paymentDate

});    saveFeeTransactions(tx);
addSchoolLedgerEntry({

    studentId,

    date: paymentDate.split("T")[0],

    transactionType: "RECEIPT",

    particular: "School Fee Receipt",

    debit: 0,

    credit: amount,

    receiptNo,

    paymentMode,

    remarks

});

// PHASE-31 — FinanceService parallel write (shadow copy only).
// This is NOT a migration: feeTransactions / schoolFeeLedger above remain
// the sole source of truth for receipts, reports, and outstanding balances.
// Finance is write-only here — nothing is read back from it, and nothing
// above or below this block is changed. Any failure here is caught and
// logged; it can never undo or block the Fee save that already succeeded.
try {
    if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Finance &&
        typeof Dnyanankur.Services.Finance.financeCreateTransaction === "function") {

        var __finStudent = (typeof getStudents === 'function')
            ? getStudents().find(function (s) { return s.id === studentId; })
            : null;

        // Existing ERP payment-mode terms collapse onto Finance's three
        // instrument ledgers (Cash / Bank / UPI) — Cheque, Online, Online
        // Transfer, and Card all route through Bank.
        var __finPaymentMode = (function (mode) {
            var m = String(mode || "").trim().toLowerCase();
            if (m === "cash") return "Cash";
            if (m === "upi") return "UPI";
            return "Bank";
        })(paymentMode);

        var __finDescriptionParts = ["School Fee — Installment " + installment];
        if (row.academicYear) __finDescriptionParts.push("AY " + row.academicYear);
        if (__finStudent) {
            __finDescriptionParts.push(
                __finStudent.name + " (" + __finStudent.cls + (__finStudent.div ? " " + __finStudent.div : "") + ")"
            );
        }
        if (remarks) __finDescriptionParts.push("Remarks: " + remarks);

        Dnyanankur.Services.Finance.financeCreateTransaction({
            date: paymentDate.split("T")[0],
            time: paymentDate.split("T")[1] ? paymentDate.split("T")[1].slice(0, 8) : undefined,
            studentId: studentId,
            ledgerType: "SchoolLedger",
            transactionType: "Fee",
            referenceModule: "Fee",
            referenceId: receiptNo,
            amount: amount,
            debit: 0,
            credit: amount,
            paymentMode: __finPaymentMode,
            description: __finDescriptionParts.join(" | "),
            createdBy: currentUser?.username || "System"
        });
    }
} catch (e) {
    console.warn("[Dnyanankur:Finance] Parallel write failed — Fee collection already saved successfully; Finance shadow copy skipped.", e);
}

// CM-1.0 — notify the Communication Engine. Never sends anything directly;
// this only drops a "Receipt Generated" event onto the Event Bus, which
// the Communication Engine (if installed) turns into a Queue entry.
if (window.Dnyanankur && Dnyanankur.Event) {
    var __cmStudent = (typeof getStudents === 'function') ? getStudents().find(function(s){ return s.id === studentId; }) : null;
    Dnyanankur.Event.publish('finance.receipt.generated', {
        studentId: studentId,
        studentName: __cmStudent ? __cmStudent.name : studentId,
        className: __cmStudent ? __cmStudent.class : null,
        amount: amount,
        receiptNo: receiptNo
    }, { sourceModule: 'finance' });
}

}

function receiveTransportFee(
    studentId,
    amount,
    installment,
    paymentMode,
    remarks = ""
){

    const receiptNo = getNextReceiptNo();

    const paymentDate = new Date().toISOString();

    const ledger = getTransportFeeLedger();

    const row = ledger.find(
        x => x.studentId === studentId
    );

    if(!row){
        alert("Transport fee ledger not found. Ensure the student has transport assigned at registration and Transport Master has routes configured.");
        return;
    }

    amount = Number(amount);

    if(amount <= 0){

        alert("Invalid amount");

        return;

    }

    // Allow overpay (advance); saveFee already warned the user
    row.paid = Number(row.paid || 0) + amount;
    row.balance = Math.max(0, Number(row.annualFee || 0) - row.paid);

    if(row.balance <= 0){

        row.balance = 0;

        row.status = "Paid";

    }
    else{

        row.status = "Partial";

    }

    saveTransportFeeLedger(ledger);

    const tx = getFeeTransactions();

    tx.push({

        id: "TX" + Date.now(),

        receiptNo,

        studentId,

        academicYear: row.academicYear,

        ledger: "transport",

        installment,

        amount,

        paymentMode,

        remarks,

        collectedBy: currentUser?.username || "System",

        date: paymentDate

    });

    saveFeeTransactions(tx);

    addTransportLedgerEntry({

        studentId,

        date: paymentDate.split("T")[0],

        transactionType: "RECEIPT",

        particular: "Transport Fee Receipt",

        debit: 0,

        credit: amount,

        receiptNo,

        paymentMode,

        remarks

    });

    // PHASE-32 — FinanceService parallel write (shadow copy only).
    // Same philosophy as Phase 31: feeTransactions / transportFeeLedger above
    // remain the sole source of truth for receipts, reports, and outstanding
    // balances. Finance is write-only here — nothing is read back from it,
    // and nothing above this block is changed. Any failure here is caught
    // and logged; it can never undo or block the Transport Fee save that
    // already succeeded.
    try {
        if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Finance &&
            typeof Dnyanankur.Services.Finance.financeCreateTransaction === "function") {

            var __finStudent = (typeof getStudents === 'function')
                ? getStudents().find(function (s) { return s.id === studentId; })
                : null;

            // Existing ERP payment-mode terms collapse onto Finance's three
            // instrument ledgers (Cash / Bank / UPI) — Cheque, Online, Online
            // Transfer, and Card all route through Bank.
            var __finPaymentMode = (function (mode) {
                var m = String(mode || "").trim().toLowerCase();
                if (m === "cash") return "Cash";
                if (m === "upi") return "UPI";
                return "Bank";
            })(paymentMode);

            var __finDescriptionParts = ["Transport Fee — Installment " + installment];
            if (row.academicYear) __finDescriptionParts.push("AY " + row.academicYear);
            if (row.route) __finDescriptionParts.push("Route: " + row.route);
            if (__finStudent) {
                __finDescriptionParts.push(
                    __finStudent.name + " (" + __finStudent.cls + (__finStudent.div ? " " + __finStudent.div : "") + ")"
                );
            }
            if (remarks) __finDescriptionParts.push("Remarks: " + remarks);

            Dnyanankur.Services.Finance.financeCreateTransaction({
                date: paymentDate.split("T")[0],
                time: paymentDate.split("T")[1] ? paymentDate.split("T")[1].slice(0, 8) : undefined,
                studentId: studentId,
                ledgerType: "TransportLedger",
                transactionType: "TransportFee",
                referenceModule: "Transport",
                referenceId: receiptNo,
                amount: amount,
                debit: 0,
                credit: amount,
                paymentMode: __finPaymentMode,
                description: __finDescriptionParts.join(" | "),
                createdBy: currentUser?.username || "System"
            });
        }
    } catch (e) {
        console.warn("[Dnyanankur:Finance] Parallel write failed — Transport Fee collection already saved successfully; Finance shadow copy skipped.", e);
    }

}
function receiveInventoryPayment(
    studentId,
    amount,
    receiptNo,
    paymentMode,
    remarks = ""
){

    const paymentDate = new Date().toISOString();

    const allBills = getInventoryBills();
    const bills = allBills.filter(
        b =>
            b.studentId === studentId &&
            Number(b.balance || 0) > 0
    );

    if(bills.length === 0){
        alert("No pending inventory bills found for this student.");
        return;
    }

    let remaining = Number(amount);

    if(remaining <= 0){
        alert("Invalid amount");
        return;
    }

    bills.forEach(bill => {

        if(remaining <= 0) return;

        const due = Number(bill.balance || 0);

        const pay = Math.min(due, remaining);

        bill.paid = Number(bill.paid || 0) + pay;

        bill.balance = due - pay;

        bill.status =
            bill.balance <= 0
                ? "Paid"
                : "Partial";

        remaining -= pay;

    });

    saveInventoryBills(allBills); // Save the full array (bills are references to the same objects)

    const tx = getFeeTransactions();

    tx.push({

        id: "TX" + Date.now(),
        receiptNo,
        studentId,
        academicYear: "",
        ledger: "inventory",
        installment: "",
        amount,
        paymentMode,
        remarks,
        collectedBy: currentUser?.username || "System",
        date: paymentDate

    });

    saveFeeTransactions(tx);

    addInventoryLedgerEntry({

        studentId,
        date: paymentDate.split("T")[0],
        transactionType: "RECEIPT",
        particular: "Inventory Payment",
        debit: 0,
        credit: amount,
        receiptNo,
        paymentMode,
        remarks

    });

    // PHASE-33 — FinanceService parallel write (shadow copy only).
    // Same philosophy as Phase 31/32: feeTransactions / inventory bills above
    // remain the sole source of truth for receipts, reports, and stock
    // deduction. Finance is write-only here — nothing is read back from it,
    // and nothing above this block is changed. Any failure here is caught
    // and logged; it can never undo or block the Inventory payment that
    // already succeeded.
    try {
        if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Finance &&
            typeof Dnyanankur.Services.Finance.financeCreateTransaction === "function") {

            var __finStudent = (typeof getStudents === 'function')
                ? getStudents().find(function (s) { return s.id === studentId; })
                : null;

            // Existing ERP payment-mode terms collapse onto Finance's three
            // instrument ledgers (Cash / Bank / UPI) — Cheque, Online, Online
            // Transfer, and Card all route through Bank.
            var __finPaymentMode = (function (mode) {
                var m = String(mode || "").trim().toLowerCase();
                if (m === "cash") return "Cash";
                if (m === "upi") return "UPI";
                return "Bank";
            })(paymentMode);

            // Items actually being paid down in this transaction, drawn only
            // from the bill records already loaded above — nothing new fetched.
            var __finItemNames = [];
            bills.forEach(function (b) {
                (b.items || []).forEach(function (i) {
                    if (i && i.itemName) __finItemNames.push(i.itemName);
                });
            });

            var __finDescriptionParts = ["Inventory Sale", "Invoice " + receiptNo];
            if (__finStudent) {
                __finDescriptionParts.push(
                    __finStudent.name + " (" + __finStudent.cls + (__finStudent.div ? " " + __finStudent.div : "") + ")"
                );
            }
            if (__finItemNames.length) __finDescriptionParts.push("Items: " + __finItemNames.join(", "));
            if (remarks) __finDescriptionParts.push("Remarks: " + remarks);

            Dnyanankur.Services.Finance.financeCreateTransaction({
                date: paymentDate.split("T")[0],
                time: paymentDate.split("T")[1] ? paymentDate.split("T")[1].slice(0, 8) : undefined,
                studentId: studentId || null,
                ledgerType: "InventoryLedger",
                transactionType: "InventorySale",
                referenceModule: "Inventory",
                referenceId: receiptNo,
                amount: amount,
                debit: 0,
                credit: amount,
                paymentMode: __finPaymentMode,
                description: __finDescriptionParts.join(" | "),
                createdBy: currentUser?.username || "System"
            });
        }
    } catch (e) {
        console.warn("[Dnyanankur:Finance] Parallel write failed — Inventory payment already saved successfully; Finance shadow copy skipped.", e);
    }

}
