/* H-1 START — register Fee Master & Transport Master with the generic
   Recycle Bin engine (Phase A). idField matches each store's natural
   key: Fee Master rows are keyed by className (no separate id field
   exists in this store), Transport Master rows are keyed by id. */
if(window.H1){
  H1.recycleBin.register('financeFeeMaster', {
    label: 'Fee Master (Class Fee Structure)',
    idField: 'className',
    getArray: getFeeMaster,
    saveArray: saveFeeMaster
  });
  H1.recycleBin.register('financeTransportRoute', {
    label: 'Transport Route',
    idField: 'id',
    getArray: getTransportMaster,
    saveArray: saveTransportMaster
  });
}
/* H-1 END */

function assignFeeProfile(student){
  // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.assignFeeProfile(). This
  // wrapper preserves the exact original signature/behavior for every
  // existing caller; falls back to the original inline logic below if
  // FeeService has not loaded.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
    return Dnyanankur.Services.Fee.assignFeeProfile(student);
  }


    const feeMaster = getFeeMaster();
    const transportMaster = getTransportMaster();

    const fee = feeMaster.find(f => f.className === getFeeMasterClassName(student));

    if(!fee){
        console.warn("Fee Master not found");
        return;
    }

    let transportFee = 0;
    let transportRoute = "";

    if(student.transportRequired === "yes"){
        const route = transportMaster.find(
            r => r.place === student.transportRoute
        );

        if(route){
            transportFee = route.annualFee;
            transportRoute = route.place;
        }
    }

    let schoolFee = computeGrossSchoolFee(student.feePlan, fee);

    let discount = 0;

    if(student.concession === "teacher"){
        discount = schoolFee * 0.50;
    }

    if(student.concession === "sibling"){
        discount = schoolFee * 0.25;
    }

    if(student.rte === "Yes"){
        discount = schoolFee;
    }

    discount += Number(student.customDiscount || 0);

    let payable = schoolFee + transportFee - discount;

    if(payable < 0) payable = 0;

    const profiles = getStudentFeeProfiles();

    profiles.push({

        studentId: student.id,
        academicYear: student.acyr,
        className: student.cls,

        feePlan: student.feePlan,

        schoolFee,
        installment1: fee.installment1,
        installment2: fee.installment2,

        transportRequired: student.transportRequired,
        transportRoute,
        transportFee,

        concession: student.concession,
        customDiscount: Number(student.customDiscount || 0),

        discount,
        payable,
        paid: 0,
        balance: payable,
        status: "Pending"

    });

    saveStudentFeeProfiles(profiles);
}

// Master orchestrator for admission finance. Called once from
// registerStudent(). Creates: School Fee Ledger row (assignFeeMaster),
// Transport Fee Ledger row, Inventory Bill, and the combined Student Fee
// Profile (school + transport + concessions) used for reporting.
function assignStudentFinance(student){

    assignFeeMaster(student);

    createTransportFeeLedger(student);

    assignInventoryPackage(student);

    assignFeeProfile(student);

}
function loadTransportRoutesDropdown() {

    const sel = document.getElementById("r-route");

    if (!sel) return;

    const routes = getTransportMaster();

    const prevVal = sel.value;

    sel.innerHTML = '<option value="">None — No Transport</option>';

    routes.forEach(route => {

        sel.innerHTML += `
            <option value="${route.place}">
                ${route.place} — ₹${Number(route.annualFee||0).toLocaleString('en-IN')}/yr
            </option>
        `;

    });

    sel.value = prevVal || "";
    onRegRouteChange();

}

// Keeps "Transport Required" in sync with the Route picked at registration —
// choosing any real route auto-marks transport as required (and fetches its
// fee from Transport Master); choosing "None" clears it.
function onRegRouteChange() {
    const routeSel = document.getElementById('r-route');
    const transportSel = document.getElementById('r-transport');
    const feeDisplay = document.getElementById('r-transport-fee-display');
    const feeDetail = document.getElementById('r-transport-fee-detail');
    if(!routeSel || !transportSel) return;

    const selectedRoute = routeSel.value;
    transportSel.value = selectedRoute ? 'yes' : 'no';

    if(selectedRoute && feeDisplay && feeDetail){
        const routes = getTransportMaster();
        const route = routes.find(r => r.place === selectedRoute);
        if(route){
            feeDisplay.style.display = '';
            feeDetail.innerHTML = `
                <b>${route.place}</b><br>
                Annual Fee: <b>₹${Number(route.annualFee||0).toLocaleString('en-IN')}</b> &nbsp;|&nbsp;
                Inst 1 (Jun): <b>₹${Number(route.installment1||0).toLocaleString('en-IN')}</b> &nbsp;|&nbsp;
                Inst 2 (Dec): <b>₹${Number(route.installment2||0).toLocaleString('en-IN')}</b>
            `;
        } else {
            feeDisplay.style.display = 'none';
        }
    } else {
        if(feeDisplay) feeDisplay.style.display = 'none';
    }
    updateRegFeePreview();
}

// Syncs hidden r-concession select from the unified r-fee-plan selector
function onUnifiedPlanChange() {
    const planSel = document.getElementById('r-fee-plan');
    const concessionSel = document.getElementById('r-concession');
    const concessionNote = document.getElementById('r-concession-note');
    if(!planSel) return;
    const val = planSel.value;
    const isConcession = val.startsWith('concession_');
    if(concessionSel) {
        if(val === 'concession_teacher') concessionSel.value = 'teacher';
        else if(val === 'concession_sibling_second') concessionSel.value = 'sibling';
        else if(val === 'concession_sibling_first') concessionSel.value = 'none'; // C3 = no extra tuition discount (full annual)
        else concessionSel.value = 'none';
    }
    if(concessionNote) {
        if(isConcession) {
            concessionNote.style.display = 'block';
            concessionNote.innerHTML = '⚠️ <b>Concession requires Principal approval</b> (via Fee Approvals). Standard fees are billed until approval is granted.';
        } else {
            concessionNote.style.display = 'none';
        }
    }
    updateRegFeePreview();
}

// Live fee preview: computes tuition + transport based on class/plan/route/concession
function updateRegFeePreview() {
    const previewBox = document.getElementById('reg-fee-preview');
    const previewBody = document.getElementById('reg-fee-preview-body');
    const previewNote = document.getElementById('reg-fee-preview-note');

    if(!previewBox || !previewBody) return;

    const cls = document.getElementById('r-class') ? document.getElementById('r-class').value : '';
    if(!cls){ previewBox.style.display='none'; return; }

    const unifiedPlan = document.getElementById('r-fee-plan') ? document.getElementById('r-fee-plan').value : 'installment';
    const routeVal = document.getElementById('r-route') ? document.getElementById('r-route').value : '';
    const customDisc = Number(document.getElementById('r-custom-discount') ? document.getElementById('r-custom-discount').value : 0) || 0;
    const stream = document.getElementById('r-stream') ? document.getElementById('r-stream').value : '';

    // Resolve effective feePlan and concession from unified selector
    let feePlan = unifiedPlan;
    let concession = 'none';
    if(unifiedPlan === 'concession_teacher') { feePlan = 'annual'; concession = 'teacher'; }
    else if(unifiedPlan === 'concession_sibling_second') { feePlan = 'annual'; concession = 'sibling'; }
    else if(unifiedPlan === 'concession_sibling_first') { feePlan = 'annual'; concession = 'none'; } // C3: full annual, no tuition discount

    const isConcession = concession !== 'none';
    const isC3 = unifiedPlan === 'concession_sibling_first';

    // Get fee master
    const masters = getFeeMaster();
    let lookupCls = cls;
    if((cls === '11th' || cls === '12th') && stream) lookupCls = `11th ${stream}`;
    const master = masters.find(x => x.className === lookupCls);
    if(!master){ previewBox.style.display='none'; return; }

    const annualFee = Number(master.annualFee || 0);
    const inst1 = Number(master.installment1 || 0);
    const inst2 = Number(master.installment2 || 0);
    const lumpsum = Number(master.lumpsum || master.oneTimeFee || 0);

    // Transport figures
    let transportAnnual = 0, tI1 = 0, tI2 = 0, transportLabel = '';
    if(routeVal){
        const routes = getTransportMaster();
        const route = routes.find(r => r.place === routeVal);
        if(route){
            transportAnnual = Number(route.annualFee||0);
            tI1 = Number(route.installment1||0);
            tI2 = Number(route.installment2||0);
            transportLabel = route.place;
        }
    }

    // Build installment rows with correct combined amounts per the spec:
    // Plan 1: Tuition one-time + 1st transport installment | 2nd transport installment
    // Plan 2: Tuition inst1 + transport inst1 | Tuition inst2 + transport inst2
    // Plan 3: Annual tuition + full transport | (single payment)
    // C3: Annual + full transport (due 30 Dec)
    // C2: 25% off annual + full transport (due 30 Dec)
    // C1: 50% off annual + full transport (no due date)

    let rows = [];
    let noteHtml = '';

    if(unifiedPlan === 'lumpsum') {
        const i1 = lumpsum + tI1;
        const i2 = tI2;
        rows = [
            { label: '🎓 Tuition (One-Time Plan 1) + 1st Transport Installment', inst1: lumpsum, tInst1: tI1, total: i1, due: '15/07/2026' },
            { label: '2nd Transport Installment', inst1: 0, tInst1: tI2, total: i2, due: '30/12/2026' }
        ];
        noteHtml = `✅ <b>Plan 1</b> — Inst 1: ₹${i1.toLocaleString('en-IN')} due <b>15/07/2026</b> | Inst 2: ₹${i2.toLocaleString('en-IN')} due <b>30/12/2026</b>. Miss Inst 1 → auto-switches to Plan 2.`;
    } else if(unifiedPlan === 'installment') {
        const i1 = inst1 + tI1;
        const i2 = inst2 + tI2;
        rows = [
            { label: '🎓 Tuition Installment 1 + 1st Transport Installment', tuitAmt: inst1, transAmt: tI1, total: i1, due: '30/07/2026' },
            { label: '🎓 Tuition Installment 2 + 2nd Transport Installment', tuitAmt: inst2, transAmt: tI2, total: i2, due: '30/12/2026' }
        ];
        noteHtml = `📅 <b>Plan 2</b> — Inst 1: ₹${i1.toLocaleString('en-IN')} due <b>30/07/2026</b> | Inst 2: ₹${i2.toLocaleString('en-IN')} due <b>30/12/2026</b>. Miss Inst 1 → auto-switches to Plan 3.`;
    } else if(unifiedPlan === 'annual') {
        const total = annualFee + transportAnnual;
        rows = [
            { label: '🎓 Annual Tuition + Full Transport (No Discount)', total, due: null }
        ];
        noteHtml = `Plan 3 (Full Annual) — ₹${total.toLocaleString('en-IN')}. No deadline pressure, no discounts.`;
    } else if(isC3) {
        // C3: First child / Sibling — Full annual + full transport, due 30 Dec
        const total = annualFee + transportAnnual - customDisc;
        rows = [
            { label: '🎓 Annual Fee (C3 — First Child/Sibling) + Full Transport', total: annualFee + transportAnnual, due: '30/12/2026' }
        ];
        noteHtml = `⚠️ C3 Concession: Annual Fee ₹${annualFee.toLocaleString('en-IN')} + Transport ₹${transportAnnual.toLocaleString('en-IN')} = ₹${(annualFee+transportAnnual).toLocaleString('en-IN')} due <b>30/12/2026</b>. Requires Principal approval.`;
    } else if(unifiedPlan === 'concession_sibling_second') {
        // C2: 25% off annual tuition + full transport
        const discountedTuition = Math.round(annualFee * 0.75);
        const total = discountedTuition + transportAnnual;
        rows = [
            { label: `🎓 C2 Sibling (25% Off) — ₹${annualFee.toLocaleString('en-IN')} × 75% + Full Transport`, total, due: '30/12/2026' }
        ];
        noteHtml = `⚠️ C2 Concession: Tuition ₹${discountedTuition.toLocaleString('en-IN')} + Transport ₹${transportAnnual.toLocaleString('en-IN')} = ₹${total.toLocaleString('en-IN')} due <b>30/12/2026</b>. Requires Principal approval.`;
    } else if(unifiedPlan === 'concession_teacher') {
        // C1: 50% off annual tuition + full transport
        const discountedTuition = Math.round(annualFee * 0.50);
        const total = discountedTuition + transportAnnual;
        rows = [
            { label: `🎓 C1 Teacher's Child (50% Off) — ₹${annualFee.toLocaleString('en-IN')} × 50% + Full Transport`, total, due: null }
        ];
        noteHtml = `⚠️ C1 Concession: Tuition ₹${discountedTuition.toLocaleString('en-IN')} + Transport ₹${transportAnnual.toLocaleString('en-IN')} = ₹${total.toLocaleString('en-IN')}. No due date. Requires Principal approval.`;
    }

    const customDiscRow = customDisc > 0 ? `<tr style="color:#c0392b;">
        <td colspan="2" style="padding:6px 10px;">🔻 Manual Discount</td>
        <td style="padding:6px 10px;text-align:right;">−₹${customDisc.toLocaleString('en-IN')}</td>
        <td style="padding:6px 10px;"></td>
    </tr>` : '';

    previewBody.innerHTML = rows.map((r, i) => `
        <tr style="${i % 2 === 1 ? 'background:#f9f7f4;' : ''}">
            <td style="padding:7px 10px;" colspan="2">${r.label}${r.tuitAmt !== undefined ? ` <small style="color:#666;">(Tuition: ₹${r.tuitAmt.toLocaleString('en-IN')} + Transport: ₹${r.transAmt.toLocaleString('en-IN')})</small>` : r.inst1 !== undefined && r.tInst1 !== undefined && r.total > 0 ? ` <small style="color:#666;">(Tuition: ₹${r.inst1.toLocaleString('en-IN')} + Transport: ₹${r.tInst1.toLocaleString('en-IN')})</small>` : ''}</td>
            <td style="padding:7px 10px;text-align:right;font-weight:700;font-size:14px;color:var(--navy);">₹${r.total.toLocaleString('en-IN')}</td>
            <td style="padding:7px 10px;font-size:11.5px;color:${r.due ? '#c0392b' : '#888'};">${r.due ? '📅 Due: ' + r.due : 'No due date'}</td>
        </tr>`).join('') + customDiscRow + `
        <tr style="background:var(--navy);color:#fff;font-weight:700;">
            <td style="padding:7px 10px;border-radius:0 0 0 4px;" colspan="2">TOTAL PAYABLE</td>
            <td style="padding:7px 10px;text-align:right;">₹${Math.max(0, rows.reduce((s,r) => s+r.total, 0) - customDisc).toLocaleString('en-IN')}</td>
            <td style="padding:7px 10px;border-radius:0 0 4px 0;font-size:11px;">${routeVal ? '🚌 Route: '+transportLabel : 'No transport'}</td>
        </tr>`;

    if(previewNote) previewNote.innerHTML = noteHtml;
    previewBox.style.display = '';
}

/* ─────────────────────────────────────────────────────────────
   PLAN AUTO-SWITCH SERVICE
   Runs on every app load (and can be triggered manually).
   Checks today's date against the three fee policy deadlines
   and escalates students who haven't met the current plan's
   payment requirement.
   ───────────────────────────────────────────────────────────── */
function runPlanAutoSwitchService(){
    const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
    const policy = getFeePolicyDates();
    const deadline1 = policy.oneTimeDeadline || '2026-07-15'; // Plan 1 → Plan 2
    const deadline2 = policy.inst1Deadline   || '2026-07-30'; // Plan 2 Inst-1 → Plan 3
    const deadline3 = policy.inst2Deadline   || '2026-12-30'; // Plan 2 Inst-2 → Plan 3

    const students = getStudents();
    const schoolLedger = getSchoolFeeLedger();
    let switched = 0;

    students.forEach(student => {
        // Concession students are exempt
        if(student.concession && student.concession !== 'none' && student.concessionStatus === 'approved') return;
        if(student.rte === 'Yes') return;

        const sLedger = schoolLedger.find(x => x.studentId === student.id);
        if(!sLedger) return;
        if(sLedger.feePlan === 'annual' || sLedger.feePlan === 'concession') return; // already on plan 3 or concession

        const paid = Number(sLedger.paid || 0);

        // === PLAN 1 → PLAN 2 SWITCH ===
        if(sLedger.feePlan === 'lumpsum' && today > deadline1){
            // If total paid < Plan-1 tuition amount, escalate to Plan 2
            const plan1Amount = Number(sLedger.annualFee || 0); // lumpsum stored as annualFee
            if(paid < plan1Amount){
                sLedger.feePlan = 'installment';
                // Recalculate payable based on Plan 2 fee master data
                const masters = getFeeMaster();
                const lookupCls = getFeeMasterClassName(student);
                const master = masters.find(x => x.className === lookupCls);
                if(master){
                    const newPayable = Number(master.installment1||0) + Number(master.installment2||0);
                    sLedger.annualFee = newPayable;
                    sLedger.installment1 = master.installment1;
                    sLedger.installment2 = master.installment2;
                    sLedger.balance = Math.max(0, newPayable - paid);
                    sLedger.payable = newPayable;
                }
                sLedger.autoSwitchedFrom = 'lumpsum';
                sLedger.autoSwitchedAt = today;
                switched++;
                addAuditEntry('AUTO_PLAN_SWITCH',
                    `${student.name} (${student.cls}): Plan 1 → Plan 2 (missed 15-Jul deadline)`, '', 'system');
            }
        }

        // === PLAN 2 INST-1 → PLAN 3 SWITCH ===
        if(sLedger.feePlan === 'installment' && today > deadline2){
            const inst1Due = Number(sLedger.installment1 || 0);
            if(paid < inst1Due){
                sLedger.feePlan = 'annual';
                const masters = getFeeMaster();
                const lookupCls = getFeeMasterClassName(student);
                const master = masters.find(x => x.className === lookupCls);
                if(master){
                    const fullFee = Number(master.annualFee || 0);
                    sLedger.annualFee = fullFee;
                    sLedger.balance = Math.max(0, fullFee - paid);
                    sLedger.payable = fullFee;
                }
                sLedger.autoSwitchedFrom = sLedger.autoSwitchedFrom || 'installment';
                sLedger.autoSwitchedAt = today;
                switched++;
                addAuditEntry('AUTO_PLAN_SWITCH',
                    `${student.name} (${student.cls}): Plan 2 → Plan 3 (missed 30-Jul Inst-1 deadline)`, '', 'system');
            }
        }

        // === PLAN 2 INST-2 → PLAN 3 SWITCH (missed second instalment) ===
        if(sLedger.feePlan === 'installment' && today > deadline3){
            const totalPlan2 = Number(sLedger.installment1||0) + Number(sLedger.installment2||0);
            if(paid < totalPlan2){
                sLedger.feePlan = 'annual';
                const masters = getFeeMaster();
                const lookupCls = getFeeMasterClassName(student);
                const master = masters.find(x => x.className === lookupCls);
                if(master){
                    const fullFee = Number(master.annualFee || 0);
                    sLedger.annualFee = fullFee;
                    sLedger.balance = Math.max(0, fullFee - paid);
                    sLedger.payable = fullFee;
                }
                sLedger.autoSwitchedFrom = sLedger.autoSwitchedFrom || 'installment';
                sLedger.autoSwitchedAt = today;
                switched++;
                addAuditEntry('AUTO_PLAN_SWITCH',
                    `${student.name} (${student.cls}): Escalated to Plan 3 (missed 30-Dec Inst-2 deadline)`, '', 'system');
            }
        }
    });

    if(switched > 0){
        saveSchoolFeeLedger(schoolLedger);
        console.log(`[PlanAutoSwitch] ${switched} student(s) escalated on ${today}.`);
    }
    return switched;
}
