function renderFeeMaster(){
    const tbody = document.getElementById('fee-master-body');
    if(!tbody) return;
    const data = getFeeMaster();
    const students = getStudents();
    const schoolLedgers = getSchoolFeeLedger();
    tbody.innerHTML='';
    if(data.length === 0){
      tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;color:#888;padding:20px;">No fee structures added yet. Click "+ Add Fee Structure" or "Load 2026-27 Fee Chart".</td></tr>';
      return;
    }
    data.forEach(row=>{
      const classStudents = students.filter(s => s.cls === row.className);
      const classTotalDue = classStudents.reduce((sum, s) => {
        const ledger = schoolLedgers.find(l => l.studentId === s.id);
        return sum + (ledger ? Number(ledger.payable||0) : 0);
      }, 0);
      const classCollected = classStudents.reduce((sum, s) => {
        const ledger = schoolLedgers.find(l => l.studentId === s.id);
        return sum + (ledger ? Number(ledger.paid||0) : 0);
      }, 0);
      const classBal = classTotalDue - classCollected;
      tbody.innerHTML += `<tr>
        <td><b>${row.className}</b></td>
        <td>₹${Number(row.annualFee||0).toLocaleString('en-IN')}</td>
        <td>₹${Number(row.installment1||0).toLocaleString('en-IN')} + ₹${Number(row.installment2||0).toLocaleString('en-IN')}</td>
        <td>₹${Number(row.oneTimeFee||0).toLocaleString('en-IN')}</td>
        <td><span class="badge badge-blue">${classStudents.length} students</span></td>
        <td>
          ${classStudents.length > 0 ? `<span style="color:#1a6b3c;font-size:12px;">₹${classCollected.toLocaleString('en-IN')} collected</span> | <span style="color:${classBal>0?'#c0392b':'#1a6b3c'};font-size:12px;">₹${classBal.toLocaleString('en-IN')} pending</span>` : '<span style="color:#aaa;font-size:12px;">No students</span>'}
        </td>
        <td>
          <button class="btn btn-outline btn-sm" onclick="openFeeMasterModal('${row.className}')">Edit</button>
          <button class="btn btn-red btn-sm" onclick="deleteFeeMasterRow('${row.className}')">Delete</button>
        </td>
      </tr>`;
    });
}

function openFeeMasterModal(className=null){

  document.getElementById('feemaster-edit-key').value = '';
  document.getElementById('feemaster-class').value = '';
  document.getElementById('feemaster-annual').value = '';
  document.getElementById('feemaster-inst1').value = '';
  document.getElementById('feemaster-inst2').value = '';
  document.getElementById('feemaster-onetime').value = '';

  if(className){
    const row = getFeeMaster().find(x => x.className === className);
    if(row){
      document.getElementById('feemaster-edit-key').value = row.className;
      document.getElementById('feemaster-class').value = row.className;
      document.getElementById('feemaster-annual').value = row.annualFee;
      document.getElementById('feemaster-inst1').value = row.installment1;
      document.getElementById('feemaster-inst2').value = row.installment2;
      document.getElementById('feemaster-onetime').value = row.oneTimeFee;
    }
  }

  openModal('modal-feemaster');
}

function saveFeeMasterRow(){

  const editKey = document.getElementById('feemaster-edit-key').value;
  const className = document.getElementById('feemaster-class').value;

  if(!className){
    alert('Please select a class.');
    return;
  }

  /* H-1 START — VALIDATION: fee amounts must be valid non-negative numbers.
     (item 1: "Invalid fees"). Kept as alert(), matching this modal's
     existing validation pattern immediately above, so behavior/UX for
     this form doesn't change — only the new checks are added. */
  const annualFeeEl = document.getElementById('feemaster-annual');
  const inst1El = document.getElementById('feemaster-inst1');
  const inst2El = document.getElementById('feemaster-inst2');
  const oneTimeEl = document.getElementById('feemaster-onetime');
  const feeFields = [
    ['Annual Fee', annualFeeEl.value],
    ['Installment 1', inst1El.value],
    ['Installment 2', inst2El.value],
    ['One Time Fee', oneTimeEl.value]
  ];
  for(const [label, val] of feeFields){
    if(val !== '' && !H1.validate.isNonNegativeNumber(val)){
      alert(`${label} must be a valid non-negative amount.`);
      return;
    }
  }
  /* H-1 END */

  const data = getFeeMaster();

  const row = {
    className: className,
    annualFee: Number(document.getElementById('feemaster-annual').value || 0),
    installment1: Number(document.getElementById('feemaster-inst1').value || 0),
    installment2: Number(document.getElementById('feemaster-inst2').value || 0),
    oneTimeFee: Number(document.getElementById('feemaster-onetime').value || 0)
  };

  /* H-1 START — capture previous row (for audit old/new value) */
  let __h1PrevRow = null;
  /* H-1 END */

  if(editKey){
    const index = data.findIndex(x => x.className === editKey);
    if(index > -1){
      __h1PrevRow = data[index]; // H-1
      data[index] = row;
    } else {
      data.push(row);
    }
  } else {
    const existingIndex = data.findIndex(x => x.className === className);
    if(existingIndex > -1){
      if(!confirm(`A fee structure for "${className}" already exists. Overwrite it?`)) return;
      __h1PrevRow = data[existingIndex]; // H-1
      data[existingIndex] = row;
    } else {
      data.push(row);
    }
  }

  saveFeeMaster(data);

  /* H-1 START — AUDIT TRAIL (item 6) */
  if(typeof addAuditEntry === 'function'){
    addAuditEntry(
      __h1PrevRow ? 'FEEMASTER_UPDATE' : 'FEEMASTER_CREATE',
      `Fee structure ${__h1PrevRow ? 'updated' : 'created'} for class "${className}"`,
      __h1PrevRow ? JSON.stringify(__h1PrevRow) : '',
      JSON.stringify(row)
    );
  }
  H1.ui.toast(`Fee structure for "${className}" saved.`, 'ok');
  /* H-1 END */

  closeModal('modal-feemaster');
  renderFeeMaster();
}

function deleteFeeMasterRow(className){

  /* H-1 START — SOFT DELETE (item 2): move to Recycle Bin instead of
     permanently removing. Principal must use the Recycle Bin to purge
     permanently. Confirmation prompt preserved from the original. */
  if(!confirm(`Move fee structure for "${className}" to Recycle Bin?`)) return;

  const data = getFeeMaster();
  const row = data.find(x => x.className === className);
  if(!row){ H1.ui.toast('Fee structure not found.', 'error'); return; }

  const reason = prompt('Reason for deletion (optional, shown in Recycle Bin):', '') || 'Not specified';

  H1.recycleBin.moveToBin('financeFeeMaster', row, reason);
  saveFeeMaster(data.filter(x => x.className !== className));
  H1.ui.toast(`Fee structure for "${className}" moved to Recycle Bin.`, 'warn');
  /* H-1 END */

  renderFeeMaster();
}

function renderTransportMaster(){
   const tbody = document.getElementById('transport-master-body');
   if(!tbody) return;
   const routes = getTransportMaster();
   const students = getStudents();
   const transportLedgers = getTransportFeeLedger();

   // Stats bar
   const statsDiv = document.getElementById('transport-master-stats');
   if(statsDiv) {
     const totalRoutes = routes.length;
     const studentsOnTransport = students.filter(s => s.transportRequired === 'yes').length;
     const totalAnnualRevenue = routes.reduce((sum, r) => {
       const routeStudents = students.filter(s => s.transportRequired==='yes' && s.transportRoute===r.place).length;
       return sum + (Number(r.annualFee||0) * routeStudents);
     }, 0);
     const totalCollected = transportLedgers.reduce((s, l) => s + Number(l.paid||0), 0);
     statsDiv.className = 'stats-row';
     statsDiv.innerHTML = [
       ['Routes', totalRoutes, '#1a3a6b'],
       ['Students on Transport', studentsOnTransport, '#1a6b3c'],
       ['Expected Revenue', '₹'+totalAnnualRevenue.toLocaleString('en-IN'), '#c9973a'],
       ['Collected', '₹'+totalCollected.toLocaleString('en-IN'), '#1a6b3c'],
     ].map(([l,v,c]) => `<div class="stats-row-item">
       <div class="sv" style="color:${c};">${v}</div>
       <div class="sl">${l}</div>
     </div>`).join('');
   }

   tbody.innerHTML='';
   if(!routes.length) {
     tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:20px;color:#888;">No routes added yet. Click "+ Add Route" or "Load 2026-27 Routes".</td></tr>';
     return;
   }
   routes.forEach(route=>{
     const routeStudents = students.filter(s => s.transportRequired==='yes' && s.transportRoute===route.place);
     const routeLedger = transportLedgers.filter(l => routeStudents.some(s => s.id === l.studentId));
     const collected = routeLedger.reduce((s,l) => s+Number(l.paid||0), 0);
     const pending = routeLedger.reduce((s,l) => s+Number(l.balance||0), 0);
     tbody.innerHTML += `<tr>
       <td><b>${route.place}</b></td>
       <td>₹${Number(route.annualFee||0).toLocaleString('en-IN')}</td>
       <td>₹${Number(route.installment1||0).toLocaleString('en-IN')}</td>
       <td>₹${Number(route.installment2||0).toLocaleString('en-IN')}</td>
       <td>
         <span class="badge badge-blue">${routeStudents.length} students</span>
         ${routeStudents.length > 0 ? `<span style="font-size:11px;color:#1a6b3c;margin-left:6px;">Coll: ₹${collected.toLocaleString('en-IN')}</span>
         <span style="font-size:11px;color:#c0392b;margin-left:4px;">Pending: ₹${pending.toLocaleString('en-IN')}</span>` : ''}
       </td>
       <td>
         <button class="btn btn-outline btn-sm" onclick="openTransportModal('${route.id}')">Edit</button>
         <button class="btn btn-red btn-sm" onclick="deleteTransportRoute('${route.id}')">Delete</button>
         ${routeStudents.length > 0 ? `<button class="btn btn-sm" style="background:#f0f7ff;border:1px solid #c3dafb;color:var(--navy);margin-left:4px;" onclick="showPage('financecenter');switchFinanceTab('transport',null)">→ Ledger</button>` : ''}
       </td>
     </tr>`;
   });
}
