function saveTransportRoute(){

const routes =
getTransportMaster();

const editId =
document.getElementById(
'transport-edit-id'
).value;

/* H-1 START — VALIDATION (item 1): place name required, fee amounts
   valid non-negative numbers. Uses alert() to match this form's
   existing (lack of) validation without introducing a new UI pattern. */
const __h1Place = document.getElementById('transport-place').value;
if(!H1.validate.required(__h1Place)){
  alert('Please enter a place / route name.');
  return;
}
const __h1Fields = [
  ['Annual Fee', document.getElementById('transport-annual').value],
  ['Installment 1', document.getElementById('transport-inst1').value],
  ['Installment 2', document.getElementById('transport-inst2').value]
];
for(const [label, val] of __h1Fields){
  if(val !== '' && !H1.validate.isNonNegativeNumber(val)){
    alert(`${label} must be a valid non-negative amount.`);
    return;
  }
}
// Duplicate route name prevention (item 5), skipping the row being edited
const __h1Dup = H1.validate.findDuplicate(routes, 'place', __h1Place, editId, 'id');
if(__h1Dup){
  alert(`A route named "${__h1Place}" already exists. Use a unique route name.`);
  return;
}
/* H-1 END */

const route = {

id:
editId || ('TR'+Date.now()),

place:
document.getElementById(
'transport-place'
).value,

annualFee:
Number(document.getElementById(
'transport-annual'
).value || 0),

installment1:
Number(document.getElementById(
'transport-inst1'
).value || 0),

installment2:
Number(document.getElementById(
'transport-inst2'
).value || 0)

};

let __h1PrevRoute = null; // H-1

if(editId){

const index =
routes.findIndex(
x=>x.id===editId
);

__h1PrevRoute = routes[index]; // H-1
routes[index]=route;

}else{

routes.push(route);

}

saveTransportMaster(routes);

/* H-1 START — AUDIT TRAIL (item 6) */
if(typeof addAuditEntry === 'function'){
  addAuditEntry(
    __h1PrevRoute ? 'TRANSPORT_ROUTE_UPDATE' : 'TRANSPORT_ROUTE_CREATE',
    `Transport route ${__h1PrevRoute ? 'updated' : 'created'}: "${route.place}"`,
    __h1PrevRoute ? JSON.stringify(__h1PrevRoute) : '',
    JSON.stringify(route)
  );
}
H1.ui.toast(`Route "${route.place}" saved.`, 'ok');
/* H-1 END */

closeModal(
'modal-transport'
);

renderTransportMaster();

}

// CM-1.0 — Transport has no live GPS/tracking feed in this ERP, so
// Bus Delay / Route Changed / Vehicle Changed are raised on demand by
// whoever is at the Transport Master screen, rather than auto-detected.
// Every route on record is offered so it can be scoped to one route or
// broadcast to all transport students.
function transportNotifyParents(){
  const routes = getTransportMaster();
  if(!routes.length){ alert('Add at least one route first.'); return; }
  const routeNames = routes.map(r=>r.place).join(', ');
  const routeChoice = prompt('Route (type exactly, or leave blank for ALL transport students):\n\nAvailable routes: '+routeNames, '');
  if(routeChoice === null) return;
  const kind = prompt('Type one: delay / route / vehicle', 'delay');
  if(!kind) return;
  const detail = prompt('Short detail for parents (e.g. "20 minutes late due to traffic"):', '') || '';
  const evtMap = { delay:'transport.bus.delay', route:'transport.route.changed', vehicle:'transport.vehicle.changed' };
  const evt = evtMap[kind.trim().toLowerCase()];
  if(!evt){ alert('Unrecognised type — use delay, route or vehicle.'); return; }

  const students = (typeof getStudents === 'function') ? getStudents() : [];
  const affected = students.filter(s => s.transport && (!routeChoice || s.transportRoute === routeChoice));
  if(!affected.length){ alert('No transport students matched that route.'); return; }
  if(!(window.Dnyanankur && Dnyanankur.Event)){ alert('Communication Engine is not loaded.'); return; }

  affected.forEach(function(s){
    Dnyanankur.Event.publish(evt, { studentId: s.id, studentName: s.name, className: s.class, detail: detail }, { sourceModule: 'transport' });
  });
  alert('Queued for '+affected.length+' student(s) — awaiting Principal approval in Communication → Approval Queue.');
}

function deleteTransportRoute(id){

/* H-1 START — SOFT DELETE (item 2): move to Recycle Bin instead of
   permanently removing. */
if(!confirm(
'Move this route to Recycle Bin?'
)) return;

const routes = getTransportMaster();
const route = routes.find(x=>x.id===id);
if(!route){ H1.ui.toast('Route not found.', 'error'); return; }

const reason = prompt('Reason for deletion (optional, shown in Recycle Bin):', '') || 'Not specified';
H1.recycleBin.moveToBin('financeTransportRoute', route, reason);

saveTransportMaster(routes.filter(x=>x.id!==id));
H1.ui.toast(`Route "${route.place}" moved to Recycle Bin.`, 'warn');
/* H-1 END */

renderTransportMaster();

}

