function loadPackageItemDropdown(){

    const select = document.getElementById("pkg-item-select");

    if(!select) return;

    const items = getInventoryItems();

    select.innerHTML = "";

    items.forEach(item => {

        select.innerHTML += `
            <option value="${item.id}">
                ${item.name} (₹${item.price})
            </option>
        `;
    });

}
function renderPackageItems(){

    const tbody = document.getElementById("package-items-body");

    if(!tbody) return;

    let total = 0;

    tbody.innerHTML = "";

    currentPackageItems.forEach((item, index) => {

        const itemData = getInventoryItems()
            .find(x => x.id === item.itemId);

        const name = itemData ? itemData.name : "Unknown";
        const rate = itemData ? Number(itemData.price) : 0;
        const qty = Number(item.qty);

        const itemTotal = rate * qty;

        total += itemTotal;

        const remaining = qty - (item.issued || 0);

tbody.innerHTML += `
<tr>
    <td>${name}</td>
    <td>${qty}</td>
    <td>${item.issued || 0}</td>
    <td>${remaining}</td>
    <td>${item.optional ? "✔" : "—"}</td>
    <td>₹${itemTotal}</td>
    <td>
        <button onclick="removePackageItem(${index})">
            ❌
        </button>
    </td>
</tr>
`;
    });

    document.getElementById("pkg-price").value = total;
        }
function addPackageItem(){

    const select = document.getElementById("pkg-item-select");
    const qtyInput = document.getElementById("pkg-item-qty");
    const optional = document.getElementById("pkg-item-optional");

    const itemId = select.value;
    const qty = Number(qtyInput.value || 1);

    if(!itemId){
        alert("Select an item");
        return;
    }

    const existing = currentPackageItems.find(x => x.itemId === itemId);

    if(existing){

        existing.qty += qty;

    }else{

        currentPackageItems.push({
            itemId,
            qty,
            issued: 0,
            optional: optional ? optional.checked : false
        });
    }

    renderPackageItems();
}function removePackageItem(index){

    currentPackageItems.splice(index, 1);

    renderPackageItems();
}
