// =====================================
// PACKAGE ITEM HELPERS
// =====================================

function getPackageById(id){

    return getInventoryPackages()
        .find(x => x.id === id);

}

function savePackageItems(packageId, items){

    const packages =
        getInventoryPackages();

    const pkg =
        packages.find(x => x.id === packageId);

    if(!pkg) return;

    pkg.items = items;

    pkg.totalPrice =
        items.reduce(
            (t,i)=>t+Number(i.total||0),
            0
        );

    pkg.price = pkg.totalPrice;

    saveInventoryPackages(packages);

}

function calculatePackageTotal(items){

    return items.reduce(

        (sum,item)=>

            sum + Number(item.total || 0),

        0

    );

}
// =====================================
// PACKAGE ITEM ENGINE
// =====================================

function getPackageItems(packageId){

    const pkg = getPackageById(packageId);

    return pkg?.items || [];

}

function addItemToPackage(

    packageId,

    itemId,

    qty

){

    qty = Number(qty || 1);

    const item = getInventoryItems()
        .find(x=>x.id===itemId);

    if(!item){

        alert("Inventory item not found.");

        return;

    }

    const items =
        getPackageItems(packageId);

    const existing =
        items.find(x=>x.itemId===itemId);

    if(existing){

        existing.qty += qty;

        existing.total =
            existing.qty * existing.price;

    }

    else{

        items.push({

            itemId:item.id,

            itemName:item.name,

            qty,

            price:Number(item.price),

            total:
                qty * Number(item.price)

        });

    }

    savePackageItems(
        packageId,
        items
    );

}

function removeItemFromPackage(

    packageId,

    itemId

){

    const items =
        getPackageItems(packageId)
        .filter(x=>x.itemId!==itemId);

    savePackageItems(
        packageId,
        items
    );

}



// ======================================
// CREATE INVENTORY BILL FOR NEW ADMISSION
// ======================================

function assignInventoryPackage(student){

    const classPackages = getInventoryClassMap();

    const pkg = classPackages.find(
        p=>p.className===student.cls
    );

    if(!pkg) return;

    const packages = getInventoryPackages();

    const packageData = packages.find(
        p=>p.id===pkg.packageId
    );

    if(!packageData) return;

    let amount = 0;

    const items=[];

    packageData.items.forEach(item=>{

        amount += Number(item.total || 0);

        items.push(item);

    });

    // Build the same items snapshot shape the manual "Generate Bill" flow uses
    // (itemName/qty/price/total/issued) so issue tracking, receipts, and bill
    // tables that read these fields work identically for auto-assigned bills.
    const itemsSnapshot = items.map(i => ({
        itemId: i.itemId,
        itemName: i.itemName || i.name || '',
        qty: Number(i.qty || 0),
        price: Number(i.price || 0),
        total: Number(i.total || 0),
        issued: 0
    }));

    const billReceiptNo = getNextInventoryReceiptNo();

    const bills = getInventoryBills();

    const newBill = {

        id:"INV"+Date.now(),

        type: "Inventory",

        receiptNo: billReceiptNo,

        studentId:student.id,

        studentName: student.name,

        packageId:packageData.id,

        packageName: packageData.name,

        className:student.cls,

        items: itemsSnapshot,

        amount,

        paid:0,

        balance:amount,

        status:"Pending",

        date: today(),

        createdAt:new Date().toISOString()

    };

    bills.push(newBill);

    saveInventoryBills(bills);

    // Mirror into the dedicated inventory ledger (so it also shows up
    // wherever getInventoryLedger() is read) AND the unified student ledger.
    addInventoryLedgerEntry({

        studentId:student.id,

        date: today(),

        transactionType:"ASSIGNMENT",

        particular:"Inventory Package Assigned — " + packageData.name,

        debit:amount,

        credit:0,

        billNo: billReceiptNo,

        remarks:"Automatic Package Assignment"

    });

    // Package history entry
    addPackageHistoryEntry({
        studentId: student.id,
        studentName: student.name,
        packageId: packageData.id,
        packageName: packageData.name,
        action: 'AUTO-ASSIGNED',
        billId: bills[bills.length - 1].id,
        remarks: 'Assigned during admission'
    });

}
