// Mark structure: FA1+SA1=100 (except Nursery which is FA1+IA1+SA1)
function getMarkStructure(cls) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.getMarkStructure().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.getMarkStructure(cls);
  }
  // Custom per-class override, set via Subject Mapping → "Report Card Marks
  // Split". Always sums to 100 (enforced when saving the override), so the
  // Annual/Semester 1 Report Card's Total column never breaks.
  const overrides = (typeof LS !== 'undefined') ? (LS.get('class_mark_structure') || {}) : {};
  if (overrides[cls] && overrides[cls].fa1 != null) {
    const o = overrides[cls];
    return { type: getMarkStructureDefault(cls).type, fa1: o.fa1, fa2: o.fa2, ia1: o.fa2, sa1: o.sa1, total: 100 };
  }
  return getMarkStructureDefault(cls);
}

function getMarkStructureDefault(cls) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.getMarkStructureDefault().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.getMarkStructureDefault(cls);
  }
  const nursery = ['Nursery','Jr.KG','Sr.KG'];
  if (nursery.includes(cls)) {
    // fa2 kept identical to legacy ia1 (same slot, clearer name used going forward)
    return {type:'nursery', fa1:30, fa2:30, ia1:30, sa1:40, total:100};
  }
  if (cls === '11th') {
    return {type:'college', fa1:100, sa1:100, total:100};
  }
  const t1 = ['1st','2nd'];
  if (t1.includes(cls)) {
    // Unit Test 1 (30) + Unit Test 2 (30) + Semester Exam (40) = 100
    return {type:'standard', fa1:30, fa2:30, sa1:40, total:100};
  }
  // 3rd-10th: Unit Test 1 (25) + Unit Test 2 (25) + Semester Exam (50) = 100
  return {type:'standard', fa1:25, fa2:25, sa1:50, total:100};
}

// Place & Date shown on every report card's signature block — set once by
// the Principal in Examination Center → Result Processing (applies to every
// report card printed afterwards, since it's "when results were computed",
// not tied to one single exam).
function getReportPlaceDate() {
  const v = (typeof LS !== 'undefined') ? LS.get('report_place_date') : null;
  return v || { place: '', date: '' };
}

// Standard signature block for Annual/Semester 1 report cards: blank space
// left above each line for an actual pen signature, with the printed
// labels/name placed below it, and Place & Date filled from whatever the
// Principal entered in Result Processing (falls back to a blank line if
// not set yet).
function buildReportCardSignatureBlock(settings) {
  const pd = getReportPlaceDate();
  const placeDateText = (pd.place || pd.date) ? `${pd.place || '________'}, ${pd.date || '________'}` : '________________';
  return `
    <div style="margin-top:55px;font-size:12px;color:#111;">
      <div style="display:flex;justify-content:space-between;">
        <div style="border-top:1px solid #333;width:180px;padding-top:4px;">Class Teacher Sign</div>
        <div style="border-top:1px solid #333;width:180px;padding-top:4px;text-align:right;">Principal Sign<br/><b>${settings.principal}</b></div>
      </div>
      <div style="margin-top:14px;">Place &amp; Date: ${placeDateText}</div>
    </div>`;
}

function gradeFromPercent(pct) {
  // Wrapper: delegates to AcademicEngine.Calc.grade() when available,
  // falls back to original local logic otherwise.
  if (typeof AcademicEngine !== 'undefined' &&
      AcademicEngine && AcademicEngine.Calc &&
      typeof AcademicEngine.Calc.grade === 'function') {
    try {
      return AcademicEngine.Calc.grade(pct);
    } catch (e) {
      console.warn('[gradeFromPercent] AcademicEngine.Calc.grade() failed, falling back to local logic:', e);
      // fall through to legacy logic below
    }
  }

  // --- original logic (fallback) ---
  if (pct >= 91) return 'A1';
  if (pct >= 81) return 'A2';
  if (pct >= 71) return 'B1';
  if (pct >= 61) return 'B2';
  if (pct >= 51) return 'C1';
  if (pct >= 41) return 'C2';
  if (pct >= 33) return 'D';
  return 'E';
}

function gradeColor(g) {
  if (g==='A1') return 'badge-green';
  if (g==='A2') return 'badge-blue';
  if (g==='B1') return 'badge-yellow';
  return 'badge-red';
}

