function getTeachers() {
    // [PHASE-19] Logic moved to Dnyanankur.TeacherService.getTeachers().
    // This wrapper preserves the exact original signature/behavior for
    // every existing caller; falls back to the original inline logic
    // if TeacherService has not loaded.
    if (window.Dnyanankur && Dnyanankur.TeacherService) {
        return Dnyanankur.TeacherService.getTeachers();
    }

    if (Cache.teachers !== null) {
        return Cache.teachers;
    }
    // [Phase 13G] Migrated off direct LS.get('teachers') — now reads
    // through the Repository Layer: Repository -> DriverManager ->
    // LocalStorage Driver. Same key, same shape, same fallback to [].
    const stored = Dnyanankur.Repository.teachers.getAll();
    // Merge hardcoded defaults — stored records (custom or edited) take priority;
    // defaults only fill in teachers not already in localStorage (matched by id).
    const storedIds = new Set(stored.map(t => t.id));
    const merged = [
      ...DEFAULT_TEACHERS.filter(t => !storedIds.has(t.id)),
      ...stored
    ];
    Cache.teachers = merged;
    return Cache.teachers;
}
function saveTeachersList(t) {
    // [PHASE-19] Logic moved to Dnyanankur.TeacherService.saveTeachersList().
    if (window.Dnyanankur && Dnyanankur.TeacherService) {
        Dnyanankur.TeacherService.saveTeachersList(t);
        return;
    }

    Cache.teachers = t;
    // Only persist teachers that aren't part of the hardcoded defaults
    // (or hardcoded ones that were locally modified — those won't have id starting with 'dt-')
    const defaultIds = new Set(DEFAULT_TEACHERS.map(d => d.id));
    // We persist ALL teachers; defaults that were edited will have been re-saved with same id by openTeacherModal/saveTeacher
    // [Phase 13G] Migrated off direct LS.set('teachers', ...) — now
    // writes through the Repository Layer. replaceAll() persists the
    // whole array exactly as LS.set did (same key, same shape). Both
    // original calls are preserved as-is (the first is superseded by
    // the second, unchanged from prior behavior) so write-count and
    // ordering stay identical to the pre-migration code.
    Dnyanankur.Repository.teachers.replaceAll(t.filter(x => !defaultIds.has(x.id) || t.some(s => s.id === x.id && s !== DEFAULT_TEACHERS.find(d => d.id === x.id))));
    // Simpler: just persist everything — localStorage handles it fine (15 teachers is tiny)
    Dnyanankur.Repository.teachers.replaceAll(t);
}
