function addSchoolLedgerEntry(entry){
  // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.addSchoolLedgerEntry(). This
  // wrapper preserves the exact original signature/behavior for every
  // existing caller; falls back to the original inline logic below if
  // FeeService has not loaded.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
    return Dnyanankur.Services.Fee.addSchoolLedgerEntry(entry);
  }


    const ledger = getSchoolLedger();

   const row = {

    id: crypto.randomUUID(),

    date: entry.date || new Date().toISOString().split("T")[0],

    studentId: entry.studentId,

    transactionType: entry.transactionType || "",

    particular: entry.particular,

    debit: Number(entry.debit || 0),

    credit: Number(entry.credit || 0),

    receiptNo: entry.receiptNo || "",

    paymentMode: entry.paymentMode || "",

    remarks: entry.remarks || ""

};

    ledger.push(row);

    saveSchoolLedger(ledger);

    // ---------- Sync Student Ledger ----------
    if(typeof addStudentLedgerEntry === "function"){

   addStudentLedgerEntry({

    studentId: row.studentId,

    date: row.date,

    head: "School",

    transactionType: row.transactionType,

    particular: row.particular,

    debit: row.debit,

    credit: row.credit,

    receiptNo: row.receiptNo,

    paymentMode: row.paymentMode,

    remarks: row.remarks

});

    }

}
