// ====================================================================
// CRITICAL FIX (V18): "Engines" namespace was never declared anywhere
// in this file. Engines.Financial = {...} below was therefore throwing
// "ReferenceError: Engines is not defined" on page load, which crashed
// the ENTIRE script before initApp() or any function could run.
// This single declaration does not alter any Finance Engine logic —
// it only creates the container object so the existing code can attach
// to it as originally intended.
// ====================================================================
let Engines = {};

//======================================================
// FINANCIAL ENGINE V15
//======================================================
Engines.Financial = {

    calculateSchoolCharges(studentId) {
        // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.calculateSchoolCharges().
        // Falls back to the original inline logic below if FeeService has not loaded.
        if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
            return Dnyanankur.Services.Fee.calculateSchoolCharges(studentId);
        }

        const structures = getFeeStructures();
        const structure = structures[studentId];

        if (!structure) return 0;

        return (
            Number(structure.school || 0) +
            Number(structure.transport || 0) +
            Number(structure.stationary || 0) +
            Number(structure.uniform || 0) +
            Number(structure.tuition || 0)
        );

    },

    calculateInventoryCharges(studentId) {
        // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.calculateInventoryCharges().
        if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
            return Dnyanankur.Services.Fee.calculateInventoryCharges(studentId);
        }

        return getInventoryBills()
            .filter(b => b.studentId === studentId)
            .reduce((sum, b) => sum + Number(b.amount || 0), 0);

    },

    calculateTransportCharges(studentId) {
        // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.calculateTransportCharges().
        if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
            return Dnyanankur.Services.Fee.calculateTransportCharges(studentId);
        }

        // Phase 1
        // Will be connected to Transport Master

        return 0;

    },

    calculateDiscount(studentId) {
        // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.calculateDiscount().
        if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
            return Dnyanankur.Services.Fee.calculateDiscount(studentId);
        }

        return 0;

    },

    calculateScholarship(studentId) {
        // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.calculateScholarship().
        if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
            return Dnyanankur.Services.Fee.calculateScholarship(studentId);
        }

        return 0;

    },

    calculateLateFee(studentId) {
        // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.calculateLateFee().
        if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
            return Dnyanankur.Services.Fee.calculateLateFee(studentId);
        }

        return 0;

    }

};

