    'students':      ['principal','clerk','teacher'],
    'register':      ['principal','clerk','teacher'],
    'dashboard':     ['principal','clerk','teacher'],
    // --- Phase 16.4 Task 1: Navigation Security Audit ---
    // These four pages were previously only hidden in the sidebar
    // (via data-roles on the .nav-item) but had NO entry here, so
    // showPage('...') could be called directly (e.g. from devtools)
    // to bypass the sidebar and reach the page regardless of role.
    // Roles below are copied verbatim from each page's existing
    // sidebar data-roles attribute — this only closes the bypass,
    // it does not change who could already see the nav link.
    'accountstatements': ['principal','clerk'],
