// Phase 51 — Navigation Cleanup: these Advanced Settings screens already
// exist and are fully implemented, but live inside the Infrastructure
// engine's own nested Settings Center sub-app (Infrastructure → Settings &
// Search → Settings Center → a group → the item), 3 clicks deep. This does
// NOT create or duplicate any page — it opens Infrastructure, reveals the
// existing Settings Center mount, and jumps straight to the requested
// existing sub-page using that engine's own exposed bridges.
function openAdvSetting(subPage) {
  showPage('infrastructure');
  if (window.ERPCore && typeof window.ERPCore.navigate === 'function') {
    window.ERPCore.navigate('ss-home');
  }
  if (window.SettingsSearchBridge && typeof window.SettingsSearchBridge.showPage === 'function') {
    window.SettingsSearchBridge.showPage(subPage);
  }
}
