let currentPackageItems = [];
function openInventoryModal(id=null){

    document.getElementById('inv-edit-id').value='';

    document.getElementById('inv-name').value='';
    document.getElementById('inv-category').value='Textbooks';
    document.getElementById('inv-code').value='';
    document.getElementById('inv-price').value='';
    document.getElementById('inv-stock').value='';
    document.getElementById('inv-min-stock').value='';
    document.getElementById('inv-year').value='';
    document.getElementById('inv-notes').value='';

    if(id){

        const items=getInventoryItems();
        const item=items.find(x=>x.id===id);

        if(item){

            document.getElementById('inv-edit-id').value=item.id;
            document.getElementById('inv-name').value=item.name;
            document.getElementById('inv-category').value=item.category;
            document.getElementById('inv-code').value=item.code;
            document.getElementById('inv-price').value=item.price;
            document.getElementById('inv-stock').value=item.stock;
            document.getElementById('inv-min-stock').value=item.minStock;
            document.getElementById('inv-year').value=item.year;
            document.getElementById('inv-notes').value=item.notes || '';

        }
    }

    openModal('modal-inventory');
}

function saveInventoryItem(){

    const name=document.getElementById('inv-name').value.trim();
    const category=document.getElementById('inv-category').value;
    const code=document.getElementById('inv-code').value.trim();

    if(!name || !code){
        alert('Item Name and Item Code are required');
        return;
    }

 const items=getInventoryItems();

const editId =
    document.getElementById('inv-edit-id').value;

const duplicate = items.find(x =>
    x.code === code &&
    x.id !== editId
);

if(duplicate){
    alert('Item Code already exists');
    return;
}    const itemData={

        id: editId || ('INV'+Date.now()),

        name,
        category,
        code,

        price:Number(document.getElementById('inv-price').value||0),

        stock:Number(document.getElementById('inv-stock').value||0),

        minStock:Number(document.getElementById('inv-min-stock').value||0),

        year:
document.getElementById('inv-year').value ||
getSettings().acyr,

        notes:document.getElementById('inv-notes').value,

        updatedAt:new Date().toISOString()

    };

    if(editId){

        const index=items.findIndex(x=>x.id===editId);

        items[index]=itemData;

    }else{

        items.push(itemData);

    }

    saveInventoryItems(items);

    closeModal('modal-inventory');

    renderInventoryTable();
}

function deleteInventoryItem(id){

    if(!confirm('Delete this item?')) return;

    const items=getInventoryItems()
        .filter(x=>x.id!==id);

    saveInventoryItems(items);

    renderInventoryTable();
}

