function renderGRNTable(){

    const tbody = document.getElementById('grn-table-body');
    if(!tbody) return;

    const grns = getGRNs().slice().sort((a,b)=> new Date(b.purchaseDate)-new Date(a.purchaseDate));
    tbody.innerHTML = '';

    grns.forEach(g=>{

        const statusColor = g.status==='Completed' ? 'green' : (g.status==='Cancelled' ? 'red' : '#b8860b');

        let actions = '';
        if(g.status==='Pending'){
            actions = `
                <button onclick="confirmGRN('${g.id}')">✔ Confirm GRN</button>
                <button onclick="cancelGRN('${g.id}')">✖ Cancel</button>`;
        }else{
            actions = '—';
        }

        tbody.innerHTML += `
        <tr>
            <td>${g.id}</td>
            <td>${g.purchaseDate}</td>
            <td>${g.supplierName}</td>
            <td>${g.invoiceNo}</td>
            <td>${g.items.length}</td>
            <td style="color:${statusColor};font-weight:bold;">${g.status}</td>
            <td>${actions}</td>
        </tr>`;
    });
}

function confirmGRN(id){

    const grns = getGRNs();
    const grn = grns.find(x=>x.id===id);
    if(!grn){ alert('GRN not found'); return; }
    if(grn.status!=='Pending'){ alert('Only a Pending GRN can be confirmed'); return; }

    if(!confirm('Confirm this GRN? Stock will be updated for all items.')) return;

    const items = getInventoryItems();

    grn.items.forEach(row=>{

        const idx = items.findIndex(x=>x.id===row.itemId);
        if(idx===-1) return;

        const item = items[idx];
        const oldStock = Number(item.stock||0);
        const oldAvgCost = Number(item.avgCost || item.price || row.purchaseRate);

        // Weighted Average Cost recalculation
        const newStock = oldStock + Number(row.qty);
        const newAvgCost = newStock>0
            ? ((oldStock*oldAvgCost) + (Number(row.qty)*Number(row.purchaseRate))) / newStock
            : Number(row.purchaseRate);

        item.stock = newStock;
        item.avgCost = Number(newAvgCost.toFixed(2));
        item.lastPurchaseCost = Number(row.purchaseRate);
        if(row.sellingRate) item.lastSellingRate = Number(row.sellingRate);
        item.lastBatchNo = row.batchNo || item.lastBatchNo || '';
        item.lastExpiryDate = row.expiryDate || item.lastExpiryDate || '';

        items[idx] = item;
    });

    saveInventoryItems(items);

    grn.status = 'Completed';
    grn.completedDate = today();
    saveGRNs(grns);

    // Mark the related Purchase as Completed
    const purchases = getPurchases();
    const purchase = purchases.find(p=>p.id===grn.purchaseId);
    if(purchase){
        purchase.grnStatus = 'Completed';
        savePurchases(purchases);

        // Post the purchase value as a liability to the Supplier Payables ledger
        addSupplierPayableEntry({
            supplierId: purchase.supplierId,
            supplierName: purchase.supplierName,
            particular: 'Purchase Invoice ' + purchase.invoiceNo,
            debit: purchase.netAmount,
            refType: 'PURCHASE',
            refId: purchase.id
        });

        // PHASE-44 — FinanceService parallel write (shadow copy only).
        // Same philosophy as Phase 31/32/33/37: getPurchases/savePurchases
        // and the Supplier Payables ledger above remain the sole source of
        // truth for purchase records and what the school owes each
        // supplier. Finance is write-only here — nothing is read back
        // from it, and nothing above this block is changed. Any failure
        // here is caught and logged; it can never undo or block the GRN
        // confirmation (stock update / purchase completion / payable
        // posting) that has already succeeded above.
        //
        // Uses referenceModule "InventoryPurchase" (distinct from the
        // "Supplier" referenceModule Phase 37 uses for actual supplier
        // payments above) so this new debit-side record never collides
        // with, or gets picked up by, the existing SupplierPayment
        // reconciliation in FinanceAudit.financeAuditSupplierPayments().
        try {
            if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Finance &&
                typeof Dnyanankur.Services.Finance.financeCreateTransaction === "function") {

                var __finPurchAmount = Number(purchase.netAmount || 0);
                var __finPurchDateSrc = purchase.purchaseDate || today();
                var __finPurchTimeSrc = new Date().toISOString();
                var __finPurchTime = __finPurchTimeSrc.split("T")[1] ? __finPurchTimeSrc.split("T")[1].slice(0, 8) : undefined;

                // Existing ERP payment-mode terms collapse onto Finance's three
                // instrument ledgers (Cash / Bank / UPI) — Cheque, Online, Online
                // Transfer, and Card (and no payment mode at all, since Purchase
                // Entry captures no paymentMode field today) all route through
                // Bank. Same mapping used by Phases 31/32/33/37.
                var __finPurchMode = (function (mode) {
                    var m = String(mode || "").trim().toLowerCase();
                    if (m === "cash") return "Cash";
                    if (m === "upi") return "UPI";
                    return "Bank";
                })(purchase.paymentMode);

                var __finPurchDescParts = ["Purchase"];
                if (purchase.supplierName) __finPurchDescParts.push(purchase.supplierName);
                if (purchase.invoiceNo) __finPurchDescParts.push(purchase.invoiceNo);
                __finPurchDescParts.push(grn.id);
                if (purchase.remarks) __finPurchDescParts.push(purchase.remarks);

                Dnyanankur.Services.Finance.financeCreateTransaction({
                    date: __finPurchDateSrc,
                    time: __finPurchTime,
                    staffId: null,
                    studentId: null,
                    supplierId: purchase.supplierId,
                    ledgerType: "PurchaseLedger",
                    transactionType: "Purchase",
                    referenceModule: "InventoryPurchase",
                    referenceId: purchase.invoiceNo || grn.id,
                    amount: __finPurchAmount,
                    debit: __finPurchAmount,
                    credit: 0,
                    paymentMode: __finPurchMode,
                    description: __finPurchDescParts.join(" | "),
                    createdBy: (typeof currentUser !== "undefined" && currentUser && currentUser.username) || "System"
                });
            }
        } catch (e) {
            console.warn("[Dnyanankur:Finance] Parallel write failed — GRN confirmation already saved successfully; Finance shadow copy skipped.", e);
        }
    }

    renderGRNTable();
    renderPurchaseHistory();
    renderInventoryTable();
    renderSupplierTable();
}

function cancelGRN(id){

    const grns = getGRNs();
    const grn = grns.find(x=>x.id===id);
    if(!grn){ alert('GRN not found'); return; }
    if(grn.status!=='Pending'){
        alert('Only a Pending GRN can be cancelled. A Completed GRN has already updated stock — use Stock Adjustment if a correction is required.');
        return;
    }

    const reason = prompt('Reason for cancelling this GRN (optional):','') || '';
    if(!confirm('Cancel this GRN? The related Purchase will be marked Cancelled.')) return;

    grn.status = 'Cancelled';
    grn.cancelReason = reason;
    saveGRNs(grns);

    const purchases = getPurchases();
    const purchase = purchases.find(p=>p.id===grn.purchaseId);
    if(purchase){
        purchase.grnStatus = 'Cancelled';
        savePurchases(purchases);
    }

    renderGRNTable();
    renderPurchaseHistory();
}

function switchInventoryTab(tab){
    const tabs = [
        'stock','package','purchase','supplier','grn','billing','history',
        'issue','return','damage','lost','adjustment','pkghistory'
    ];
    tabs.forEach(t => {
        const el = document.getElementById('inventory-'+t+'-tab');
        if(el) el.style.display = 'none';
    });
    const target = document.getElementById('inventory-'+tab+'-tab');
    if(target) target.style.display = 'block';

    // Refresh data for relevant tabs
    if(tab === 'issue')       renderIssueRegister();
    if(tab === 'return')      renderReturnRegister();
    if(tab === 'damage')      renderDamageRegister();
    if(tab === 'lost')        renderLostRegister();
    if(tab === 'adjustment')  renderStockAdjustments();
    if(tab === 'pkghistory')  renderPackageHistory();
    if(tab === 'purchase')    renderPurchaseHistory();
    if(tab === 'supplier')    renderSupplierTable();
    if(tab === 'grn')         renderGRNTable();
}
