function getNextInventoryReceiptNo(){

    const acyr =
        getSettings().acyr || '2026-27';

    let counter =
        Number(
            localStorage.getItem(
                'inventoryReceiptCounter'
            ) || 0
        );

    counter++;

    localStorage.setItem(
        'inventoryReceiptCounter',
        counter
    );

    return `INV-${acyr}-${String(counter).padStart(4,'0')}`;
}

function generateInventoryBill(){

    const studentId =
        document.getElementById("billing-student").value;

    const packageId =
        document.getElementById("billing-package").value;

    if(!studentId){
        alert("Select Student");
        return;
    }

    if(!packageId){
        alert("Select Package");
        return;
    }

    const student =
        getStudents().find(s => s.id === studentId);

    const packages =
        getInventoryPackages();

    const pkg =
        packages.find(p => p.id === packageId);

    if(!student || !pkg){
        alert("Invalid Data");
        return;
    }

    // Prevent duplicate active bill for same student + package
    const existing = getInventoryBills().find(
        b => b.studentId === studentId &&
             b.packageId === packageId &&
             b.status !== 'Cancelled'
    );
    if(existing){
        alert("This student already has an active bill for this package.\nBill No: " + existing.receiptNo);
        return;
    }

    const amount = Number(pkg.totalPrice || pkg.price || 0);

    // Embed items snapshot with issued:0 for partial issue tracking
    const itemsSnapshot = (pkg.items || []).map(i => ({
        itemId: i.itemId,
        itemName: i.itemName || '',
        qty: Number(i.qty || 0),
        price: Number(i.price || 0),
        total: Number(i.total || 0),
        issued: 0
    }));

    const bill = {
        id          : "BILL" + Date.now(),
        type        : "Inventory",
        receiptNo   : getNextInventoryReceiptNo(),
        studentId   : student.id,
        studentName : student.name,
        className   : student.cls,
        packageId   : pkg.id,
        packageName : pkg.name,
        items       : itemsSnapshot,
        amount      : amount,
        paid        : 0,
        balance     : amount,
        status      : "Pending",
        date        : today(),
        createdAt   : new Date().toISOString()
    };

    const bills = getInventoryBills();
    bills.push(bill);
    saveInventoryBills(bills);

    // Reduce package stock count (package-level)
    pkg.stock = Math.max(0, Number(pkg.stock || 0) - 1);
    const pkgIndex = packages.findIndex(x => x.id === pkg.id);
    if(pkgIndex >= 0){
        packages[pkgIndex] = pkg;
        saveInventoryPackages(packages);
    }

    // NOTE: Individual item stock is reduced at ISSUE time, not billing time.
    // This separates billing from physical dispatch — correct ERP practice.

    // Package history entry
    addPackageHistoryEntry({
        studentId   : student.id,
        studentName : student.name,
        packageId   : pkg.id,
        packageName : pkg.name,
        action      : 'BILLED',
        billId      : bill.id,
        remarks     : 'Manual bill generated'
    });

    // Ledger Entry
    addInventoryLedgerEntry({
        studentId       : student.id,
        date            : today(),
        transactionType : "BILL",
        particular      : "Inventory Package - " + pkg.name,
        debit           : amount,
        credit          : 0,
        billNo          : bill.receiptNo,
        remarks         : "Inventory Bill Generated"
    });

    renderInventoryTable();
    renderPackageTable();
    renderInventoryHistory();
    loadStudentPackages();

    alert("Inventory Bill Generated Successfully\nBill No: " + bill.receiptNo);

}
// [issueInventory and issuePartialInventory — clean versions defined below]

// ============================================================
// COMPLETE ISSUE — marks entire bill as Issued
// ============================================================
function issueInventory(bill) {
    if(!bill) return;

    const bills = getInventoryBills();
    const index = bills.findIndex(b => b.id === bill.id);
    if(index === -1) return;

    // Reduce stock for each item in the package
    const pkg = getInventoryPackages().find(p => p.id === bill.packageId);
    if(pkg && pkg.items){
        const items = getInventoryItems();
        pkg.items.forEach(pkgItem => {
            const itIdx = items.findIndex(i => i.id === pkgItem.itemId);
            if(itIdx !== -1){
                const alreadyIssued = pkgItem.issued || 0;
                const remaining = Number(pkgItem.qty || 0) - alreadyIssued;
                if(remaining > 0){
                    items[itIdx].stock = Math.max(0, Number(items[itIdx].stock || 0) - remaining);
                }
                pkgItem.issued = pkgItem.qty; // mark fully issued
            }
        });
        saveInventoryItems(items);

        // Save pkg changes back
        const pkgsAll = getInventoryPackages();
        const pkgIdx2 = pkgsAll.findIndex(p => p.id === pkg.id);
        if(pkgIdx2 >= 0){ pkgsAll[pkgIdx2] = pkg; saveInventoryPackages(pkgsAll); }
    }

    bills[index].status = 'Issued';
    bills[index].issuedAt = new Date().toISOString();
    saveInventoryBills(bills);

    // Issue Register entry
    const issReg = getIssueRegister();
    issReg.push({
        id: 'ISS' + Date.now(),
        date: today(),
        billId: bill.id,
        billNo: bill.receiptNo,
        studentId: bill.studentId,
        studentName: bill.studentName,
        className: bill.className,
        itemId: '',
        itemName: 'Full Package',
        qty: '',
        type: 'COMPLETE',
        remarks: 'Full package issued'
    });
    saveIssueRegister(issReg);

    // Package history
    addPackageHistoryEntry({
        studentId: bill.studentId,
        studentName: bill.studentName,
        packageId: bill.packageId,
        packageName: bill.packageName,
        action: 'ISSUED',
        billId: bill.id,
        remarks: 'Complete issue'
    });

    addInventoryLedgerEntry({
        studentId: bill.studentId,
        date: today(),
        transactionType: 'ISSUE',
        particular: 'Inventory Issued - ' + bill.packageName,
        debit: 0,
        credit: bill.amount,
        billNo: bill.receiptNo,
        remarks: 'Stock reduced via complete package issue'
    });

    renderInventoryTable();
    renderInventoryHistory();
    renderIssueRegister();

    // CM-1.0 — notify the Communication Engine. Package name decides
    // whether this reads as "Book Distribution" or "Uniform Ready" —
    // anything else falls back to the generic Stock Notice event.
    if (window.Dnyanankur && Dnyanankur.Event) {
        const nameLC = String(bill.packageName || '').toLowerCase();
        const evt = nameLC.includes('uniform') ? 'inventory.uniform.ready'
                  : (nameLC.includes('book') || nameLC.includes('stationery')) ? 'inventory.book.distributed'
                  : 'inventory.stock.notice';
        Dnyanankur.Event.publish(evt, {
            studentId: bill.studentId, studentName: bill.studentName, className: bill.className,
            detail: bill.packageName
        }, { sourceModule: 'inventory' });
    }
}

// ============================================================
// RETURN REGISTER
// ============================================================
function recordItemReturn(billId, itemId, qty, remarks) {
    const bills = getInventoryBills();
    const bill = bills.find(b => b.id === billId);
    if(!bill){ alert('Bill not found'); return; }

    // Restore stock
    const items = getInventoryItems();
    const itIdx = items.findIndex(i => i.id === itemId);
    if(itIdx !== -1){
        items[itIdx].stock = Number(items[itIdx].stock || 0) + Number(qty);
    }
    saveInventoryItems(items);

    const retReg = getReturnRegister();
    retReg.push({
        id: 'RET' + Date.now(),
        date: today(),
        billId,
        billNo: bill.receiptNo,
        studentId: bill.studentId,
        studentName: bill.studentName,
        className: bill.className,
        itemId,
        itemName: (getInventoryItems().find(i => i.id === itemId) || {}).name || itemId,
        qty: Number(qty),
        remarks: remarks || ''
    });
    saveReturnRegister(retReg);

    addInventoryLedgerEntry({
        studentId: bill.studentId,
        date: today(),
        transactionType: 'RETURN',
        particular: 'Item Returned',
        debit: 0,
        credit: 0,
        billNo: bill.receiptNo,
        remarks: `Returned qty ${qty} — ${remarks || ''}`
    });

    renderReturnRegister();
    renderInventoryTable();
    alert('Return recorded.');
}

// ============================================================
// DAMAGE REGISTER
// ============================================================
function recordDamage(billId, itemId, qty, remarks) {
    const bills = getInventoryBills();
    const bill = bills.find(b => b.id === billId);
    if(!bill){ alert('Bill not found'); return; }

    const dmgReg = getDamageRegister();
    dmgReg.push({
        id: 'DMG' + Date.now(),
        date: today(),
        billId,
        billNo: bill.receiptNo,
        studentId: bill.studentId,
        studentName: bill.studentName,
        className: bill.className,
        itemId,
        itemName: (getInventoryItems().find(i => i.id === itemId) || {}).name || itemId,
        qty: Number(qty),
        remarks: remarks || ''
    });
    saveDamageRegister(dmgReg);

    // Damaged stock is removed permanently — no stock restore
    const items = getInventoryItems();
    const itIdx = items.findIndex(i => i.id === itemId);
    if(itIdx !== -1){
        items[itIdx].stock = Math.max(0, Number(items[itIdx].stock || 0) - Number(qty));
    }
    saveInventoryItems(items);

    renderDamageRegister();
    renderInventoryTable();
    alert('Damage recorded.');
}

// ============================================================
// LOST ITEM REGISTER
// ============================================================
function recordLostItem(billId, itemId, qty, remarks) {
    const bills = getInventoryBills();
    const bill = bills.find(b => b.id === billId);
    if(!bill){ alert('Bill not found'); return; }

    const lostReg = getLostRegister();
    lostReg.push({
        id: 'LOST' + Date.now(),
        date: today(),
        billId,
        billNo: bill.receiptNo,
        studentId: bill.studentId,
        studentName: bill.studentName,
        className: bill.className,
        itemId,
        itemName: (getInventoryItems().find(i => i.id === itemId) || {}).name || itemId,
        qty: Number(qty),
        remarks: remarks || ''
    });
    saveLostRegister(lostReg);

    // Lost = stock reduced permanently
    const items = getInventoryItems();
    const itIdx = items.findIndex(i => i.id === itemId);
    if(itIdx !== -1){
        items[itIdx].stock = Math.max(0, Number(items[itIdx].stock || 0) - Number(qty));
    }
    saveInventoryItems(items);

    renderLostRegister();
    renderInventoryTable();
    alert('Lost item recorded.');
}

// ============================================================
// STOCK ADJUSTMENT
// ============================================================
function doStockAdjustment(itemId, newQty, reason) {
    const items = getInventoryItems();
    const idx = items.findIndex(i => i.id === itemId);
    if(idx === -1){ alert('Item not found'); return; }

    const oldQty = Number(items[idx].stock || 0);
    items[idx].stock = Number(newQty);
    saveInventoryItems(items);

    const adjs = getStockAdjustments();
    adjs.push({
        id: 'ADJ' + Date.now(),
        date: today(),
        itemId,
        itemCode: items[idx].code,
        itemName: items[idx].name,
        oldQty,
        newQty: Number(newQty),
        diff: Number(newQty) - oldQty,
        reason: reason || '',
        by: (typeof currentUser !== 'undefined' ? currentUser.name : 'System')
    });
    saveStockAdjustments(adjs);

    renderInventoryTable();
    renderStockAdjustments();
    alert('Stock adjusted successfully.');
}

function saveInventoryTransaction(entry){
    const ledger = getInventoryLedger();
    ledger.push({
        id: crypto.randomUUID(),
        date: entry.date || today(),
        studentId: entry.studentId,
        type: entry.type || 'GENERAL',
        item: entry.item || '',
        debit: Number(entry.debit || 0),
        credit: Number(entry.credit || 0),
        ref: entry.ref || '',
        remarks: entry.remarks || ''
    });
    saveInventoryLedger(ledger);
}
