// PARTIAL ISSUE — per item from a specific bill
// ============================================================
function issuePartialInventory(billId, itemId, qty){
    qty = Number(qty || 1);
    if(qty <= 0){ alert('Qty must be > 0'); return; }

    const bills = getInventoryBills();
    const bill = bills.find(b => b.id === billId);
    if(!bill){ alert('Bill not found'); return; }

    const pkg = getInventoryPackages().find(p => p.id === bill.packageId);
    if(!pkg){ alert('Package not found'); return; }

    const pkgItem = pkg.items.find(i => i.itemId === itemId);
    if(!pkgItem){ alert('Item not in package'); return; }

    const remaining = Number(pkgItem.qty || 0) - Number(pkgItem.issued || 0);
    if(qty > remaining){ alert(`Only ${remaining} remaining to issue`); return; }

    // Reduce stock
    const items = getInventoryItems();
    const stockItem = items.find(i => i.id === itemId);
    if(stockItem){
        stockItem.stock = Math.max(0, Number(stockItem.stock || 0) - qty);
    }
    saveInventoryItems(items);

    // Update pkg issued count
    pkgItem.issued = Number(pkgItem.issued || 0) + qty;
    const pkgList = getInventoryPackages();
    const pkgIdx = pkgList.findIndex(p => p.id === bill.packageId);
    if(pkgIdx >= 0){ pkgList[pkgIdx] = pkg; saveInventoryPackages(pkgList); }

    // Update bill items issued count + status
    bill.items = bill.items || [];
    const billItem = bill.items.find(i => i.itemId === itemId);
    if(billItem) billItem.issued = Number(billItem.issued || 0) + qty;
    const allIssued = bill.items.every(i => Number(i.issued || 0) >= Number(i.qty || 0));
    if(allIssued) bill.status = 'Issued';
    const bIdx = bills.findIndex(b => b.id === billId);
    if(bIdx >= 0) bills[bIdx] = bill;
    saveInventoryBills(bills);

    // Issue Register entry
    const issReg = getIssueRegister();
    issReg.push({
        id: 'ISS' + Date.now(),
        date: today(),
        billId,
        billNo: bill.receiptNo,
        studentId: bill.studentId,
        studentName: bill.studentName,
        className: bill.className,
        itemId,
        itemName: (getInventoryItems().find(i => i.id === itemId) || {}).name || itemId,
        qty,
        type: 'PARTIAL',
        remarks: 'Partial issue'
    });
    saveIssueRegister(issReg);

    addInventoryLedgerEntry({
        studentId: bill.studentId,
        date: today(),
        transactionType: 'PARTIAL ISSUE',
        particular: 'Partial Item Issue',
        debit: 0,
        credit: qty,
        billNo: bill.receiptNo,
        remarks: `Item ${itemId} qty ${qty} issued partially`
    });

    renderInventoryTable();
    renderInventoryHistory();
    renderIssueRegister();
    alert('Partial issue recorded.');
}

