function bulkPrintInventoryBills(){

    const selectedIds =
      [...document.querySelectorAll(
        '.inventory-bill-checkbox:checked'
      )]
      .map(cb => cb.value);

    if(selectedIds.length===0){

        alert(
          'Select at least one receipt'
        );

        return;
    }

    const bills =
      getInventoryBills()
      .filter(x =>
        selectedIds.includes(x.id)
      );

    const settings = getSettings();
    const schoolNameForPrint = (settings.name || 'School').toUpperCase();

    let html='';

    bills.forEach(bill=>{
        const s = getStudents().find(x => x.id === bill.studentId) || {};
        const studentName = s.name || bill.studentName || '—';
        const className = (s.cls ? s.cls + ' ' + s.div : bill.className) || '—';

        html += `
        <div style="
            width:48%;
            border:2px solid #1a2a5e;
            padding:14px;
            margin:5px;
            display:inline-block;
            vertical-align:top;
            font-size:12px;
            border-radius:8px;
            font-family:Arial,sans-serif;
        ">
          <div style="text-align:center;border-bottom:1px solid #ccc;padding-bottom:8px;margin-bottom:8px;">
            <b style="font-size:14px;">${schoolNameForPrint}</b><br>
            <span style="font-size:11px;color:#555;">Inventory Receipt</span>
          </div>
          <div><b>Receipt:</b> ${bill.receiptNo||'—'}</div>
          <div><b>Student:</b> ${studentName}</div>
          <div><b>Class:</b> ${className}</div>
          <div><b>Package:</b> ${bill.packageName||'—'}</div>
          <div style="margin-top:6px;font-size:14px;font-weight:700;"><b>Amount: ₹${Number(bill.amount||0).toLocaleString('en-IN')}</b></div>
          <div><b>Date:</b> ${bill.date||'—'}</div>
          <div style="margin-top:8px;padding-top:6px;border-top:1px dashed #ccc;font-size:10px;color:#888;">Signature: ________________</div>
        </div>
        `;
    });

    // Open print window directly — don't use the hidden div (it won't be visible during print)
    const w = window.open('','_blank');
    if (!w) { alert('Please allow pop-ups for this page to enable printing.'); return; }
    w.document.write(`<!DOCTYPE html><html><head><title>Inventory Bulk Print</title>
      <style>
        *{box-sizing:border-box;margin:0;padding:0;}
        body{font-family:Arial,sans-serif;background:#fff;padding:10px;}
        @media print{body{margin:0;} @page{size:A4;margin:8mm;}}
      </style></head><body>${html}</body></html>`);
    w.document.close();
    setTimeout(()=>{ w.print(); }, 500);
}
function renderInventoryTable(){

    const tbody=document.getElementById('inventory-table-body');

    if(!tbody) return;

    let items=getInventoryItems();

    const search=
      (document.getElementById('inventory-search')?.value || '')
      .toLowerCase();

    const category=
      document.getElementById('inventory-category-filter')?.value || '';

    items=items.filter(item=>{

        const matchSearch=
            item.name.toLowerCase().includes(search) ||
            item.code.toLowerCase().includes(search);

        const matchCategory=
            !category || item.category===category;

        return matchSearch && matchCategory;

    });

    tbody.innerHTML='';

    let totalStock=0;
    let lowStock=0;
    let stockValue=0;

    items.forEach(item=>{

        totalStock += Number(item.stock);

        stockValue += Number(item.stock) * Number(item.price);

        const isLow=
            Number(item.stock)<=Number(item.minStock);

        if(isLow) lowStock++;

        tbody.innerHTML += `
        <tr>
            <td>${item.code}</td>
            <td>${item.name}</td>
            <td>${item.category}</td>
            <td>₹${item.price}</td>
            <td>${item.stock}</td>
            <td>${item.minStock}</td>
            <td>
  ${isLow
    ? '<span style="color:red;font-weight:bold;">⚠ Low Stock</span>'
    : '<span style="color:green;">✓ Available</span>'
  }
</td>
            <td>
                <button onclick="openInventoryModal('${item.id}')">
                  Edit
                </button>

                <button onclick="deleteInventoryItem('${item.id}')">
                  Delete
                </button>
            </td>
        </tr>`;
    });

    document.getElementById('inv-total-items').innerText=
        items.length;

    document.getElementById('inv-total-stock').innerText=
        totalStock;

    document.getElementById('inv-low-stock').innerText=
        lowStock;

    document.getElementById('inv-stock-value').innerText=
        '₹'+stockValue.toLocaleString();
}

function today() { return new Date().toISOString().split('T')[0]; }
