function getNextReceiptNo(){

    let last = Number(
        localStorage.getItem("lastReceiptNo") || 0
    );

    last++;

    localStorage.setItem(
        "lastReceiptNo",
        last
    );

    return "RC" + String(last).padStart(6,"0");

}

