function previewPhoto(input) {
  const file = input.files[0];
  if (file) {
    const r = new FileReader();
    r.onload = e => {
      const img = document.getElementById('r-photo-preview');
      img.src = e.target.result;
      img.style.display = 'block';
    };
    r.readAsDataURL(file);
  }
}

// ====================== STUDENT DATABASE ======================
let allStudents = [];

function renderStudentTable(list) {
  allStudents = getStudents();
  const tbody = document.getElementById('stu-table-body');
  
  // Filter for teacher
  let students = list || allStudents;
  if (currentUser && currentUser.role === 'teacher' && !currentUser.viewAll) {
    // Use classAssignments (class-div pairs like "1st-A") first; fall back to classes list
    const assignments = currentUser.classAssignments || [];
    const tClasses = Array.isArray(currentUser.classes) ? currentUser.classes : [];
    const tDivs = Array.isArray(currentUser.divs) ? currentUser.divs : [];

    if (assignments.length > 0) {
      // Filter by specific class-division pairs
      students = students.filter(s => assignments.includes(`${s.cls}-${s.div}`));
    } else if (tClasses.length > 0) {
      students = students.filter(s => tClasses.includes(s.cls));
      if (tDivs.length > 0) students = students.filter(s => tDivs.includes(s.div));
    }
  }
  
  if (!students.length) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:20px;color:#aaa;">No students found.</td></tr>';
    document.getElementById('stu-count').textContent = '0 students';
    return;
  }
  
  tbody.innerHTML = students.map(s => `
    <tr>
      <td><div style="display:flex;align-items:center;gap:8px;">
        ${s.photo ? `<img src="${s.photo}" style="width:30px;height:34px;object-fit:cover;border-radius:3px;border:1px solid #ddd;"/>` : `<div style="width:30px;height:34px;background:#e8e2d9;border-radius:3px;display:flex;align-items:center;justify-content:center;font-size:12px;color:#888;">${s.name[0]}</div>`}
        <b>${s.name}</b>
      </div></td>
      <td>${s.cls}</td><td>${s.div}</td><td>${s.roll}</td>
      <td>${s.fatherName||'—'}</td><td>${s.fatherMobile||s.motherMobile||'—'}</td>
      <td>${s.dob||'—'}</td>
      <td>
        <button class="btn btn-outline btn-sm" onclick="viewStudent('${s.id}')">View</button>
      </td>
    </tr>`).join('');
  document.getElementById('stu-count').textContent = `Showing ${students.length} student(s)`;
}

function filterStudents() {
  const q = document.getElementById('stu-search').value.toLowerCase();
  const cls = document.getElementById('stu-class-filter').value;
  const div = document.getElementById('stu-div-filter').value;
  let students = getStudents();
  if (q) students = students.filter(s => (s.name+s.roll+s.admno+s.fatherName).toLowerCase().includes(q));
  if (cls) students = students.filter(s => s.cls === cls);
  if (div) students = students.filter(s => s.div === div);
  renderStudentTable(students);
}

function viewStudent(id) {
  const s = getStudents().find(x => x.id === id);
  if (!s) return;
  currentSelectedStudentId = id;
  document.getElementById('modal-stu-name').textContent = s.name;
  document.getElementById('modal-stu-content').innerHTML = `
    <div style="display:grid;grid-template-columns:80px 1fr;gap:16px;margin-bottom:16px;">
      ${s.photo ? `<img src="${s.photo}" style="width:80px;height:90px;object-fit:cover;border-radius:6px;border:1px solid #ddd;"/>` : `<div style="width:80px;height:90px;background:#e8e2d9;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:24px;color:#888;">${s.name[0]}</div>`}
      <div>
        <p style="font-size:13px;"><b>Admission No:</b> ${s.admno||'—'} &nbsp; <b>GR No:</b> ${s.gr||'—'}</p>
        <p style="font-size:13px;"><b>Class:</b> ${s.cls} ${s.div} &nbsp; <b>Roll:</b> ${s.roll}</p>
        <p style="font-size:13px;"><b>DOB:</b> ${s.dob} &nbsp; <b>Gender:</b> ${s.gender||'—'} &nbsp; <b>Blood:</b> ${s.blood||'—'}</p>
        <p style="font-size:13px;"><b>Aadhar:</b> ${s.aadhar||'—'} &nbsp; <b>Category:</b> ${s.category||'—'}</p>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:13px;">
      <div><b>Father:</b> ${s.fatherName||'—'} (${s.fatherOcc||'—'})<br/><b>Mobile:</b> ${s.fatherMobile||'—'}</div>
      <div><b>Mother:</b> ${s.motherName||'—'} (${s.motherOcc||'—'})<br/><b>Mobile:</b> ${s.motherMobile||'—'}</div>
      <div><b>Address:</b> ${s.addr||''}, ${s.city||''}, ${s.taluka||''}, ${s.dist||''} - ${s.pin||''}</div>
      <div><b>Admission Date:</b> ${s.admdate||'—'}<br/><b>Medium:</b> ${s.medium||'—'}</div>
      <div><b>Medical:</b> ${s.medical||'None'}</div>
      <div><b>Bus:</b> ${s.bus||'—'} &nbsp; <b>Email:</b> ${s.email||'—'}</div>
    </div>
  `;
  openModal('modal-student');
}

function editStudent() {
  const s = getStudents().find(x => x.id === currentSelectedStudentId);
  if (!s) return;
  closeModal('modal-student');
  showPage('register');
  // Populate form
  setTimeout(() => {
    Object.entries({
      'r-name':s.name,'r-dob':s.dob,'r-gender':s.gender,'r-blood':s.blood,
      'r-sid':s.sid||'','r-uid':s.uid||'','r-pen':s.pen||'','r-apaar':s.apaar||'',
      'r-pob':s.placeOfBirth||'',
      'r-aadhar':s.aadhar,'r-religion':s.religion,'r-caste':s.caste,
      'r-category':s.category,'r-nationality':s.nationality||'Indian',
      'r-mothertongue':s.motherTongue||'','r-subcaste':s.subcaste||'',
      'r-coupon':s.couponType||'','r-rte':s.rte||'',
      'r-class':s.cls,'r-div':s.div,'r-roll':s.roll,'r-admno':s.admno,
      'r-admdate':s.admdate,'r-acyr':s.acyr,'r-prevschool':s.prevschool,'r-gr':s.gr,
      'r-medium':s.medium,'r-fname':s.fatherName,'r-focc':s.fatherOcc,
      'r-fmob':s.fatherMobile,'r-faadhar':s.fatherAadhar,'r-mname':s.motherName,
      'r-mocc':s.motherOcc,'r-mmob':s.motherMobile,'r-gname':s.guardian,
      'r-income':s.income,'r-email':s.email,'r-addr':s.addr,'r-city':s.city,
      'r-taluka':s.taluka,'r-dist':s.dist,'r-state':s.state,'r-pin':s.pin,
      'r-medical':s.medical,'r-emname':s.emname,'r-emnum':s.emnum,
      'r-disabled':s.disabled||'No',
      'r-fee-plan': s.concessionScheme || s.feePlan || 'installment',
      'r-custom-discount': s.customDiscount || 0,
    }).forEach(([id,val]) => { const el=document.getElementById(id); if(el) el.value=val||''; });
    if (s.photo) {
      const img=document.getElementById('r-photo-preview');
      img.src=s.photo; img.style.display='block';
    }
    // Route dropdown is populated dynamically — rebuild it first, then select the
    // student's saved route so Fee Configuration reflects their ACTUAL plan, not
    // whatever option happens to be first/default in the HTML.
    if (typeof loadTransportRoutesDropdown === 'function') loadTransportRoutesDropdown();
    const routeEl = document.getElementById('r-route');
    if (routeEl) routeEl.value = s.transportRoute || '';
    const transportEl = document.getElementById('r-transport');
    if (transportEl) transportEl.value = s.transportRequired || (s.transportRoute ? 'yes' : 'no');
    if (typeof onRegRouteChange === 'function') onRegRouteChange();
    if (typeof onUnifiedPlanChange === 'function') onUnifiedPlanChange();
    if (typeof updateRegFeePreview === 'function') updateRegFeePreview();
    // Make register button update
    document.querySelector('#page-register button.btn-primary').textContent='Update Student';
    document.querySelector('#page-register button.btn-primary').setAttribute('onclick',`updateStudent('${s.id}')`);
  }, 100);
}

function updateStudent(id) {
  const students = getStudents();
  const idx = students.findIndex(x => x.id === id);
  if (idx < 0) return;
  const photoFile = document.getElementById('r-photo').files[0];

  // Read unified plan selector and map to feePlan + concession (mirrors registerStudent())
  const unifiedPlanVal = document.getElementById('r-fee-plan') ? document.getElementById('r-fee-plan').value : (students[idx].concessionScheme || 'installment');
  let feePlanVal = unifiedPlanVal;
  let concessionVal = 'none';
  if (unifiedPlanVal === 'concession_teacher') { feePlanVal = 'annual'; concessionVal = 'teacher'; }
  else if (unifiedPlanVal === 'concession_sibling_second') { feePlanVal = 'annual'; concessionVal = 'sibling'; }
  else if (unifiedPlanVal === 'concession_sibling_first') { feePlanVal = 'annual'; concessionVal = 'none'; }
  const concessionSelEl = document.getElementById('r-concession');
  if (concessionSelEl) concessionSelEl.value = concessionVal;

  // Track whether anything finance-relevant actually changed, so we only touch the
  // ledger (and log an ADJUSTMENT entry) when it's actually necessary.
  const prevStudent = students[idx];
  const newTransportRequired = document.getElementById('r-transport') ? document.getElementById('r-transport').value : prevStudent.transportRequired;
  const newTransportRoute = document.getElementById('r-route') ? document.getElementById('r-route').value : prevStudent.transportRoute;
  const newCustomDiscount = Number(document.getElementById('r-custom-discount') ? document.getElementById('r-custom-discount').value : (prevStudent.customDiscount || 0)) || 0;
  const newCls = document.getElementById('r-class').value;
  const financeRelevantChanged = (
    prevStudent.feePlan !== feePlanVal ||
    prevStudent.concessionScheme !== unifiedPlanVal ||
    prevStudent.concession !== concessionVal ||
    Number(prevStudent.customDiscount||0) !== newCustomDiscount ||
    prevStudent.transportRequired !== newTransportRequired ||
    prevStudent.transportRoute !== newTransportRoute ||
    prevStudent.cls !== newCls ||
    prevStudent.rte !== (document.getElementById('r-rte') ? document.getElementById('r-rte').value : prevStudent.rte)
  );

  const finish = (photo) => {
    students[idx] = { ...students[idx],
      feePlan: feePlanVal,
      concessionScheme: unifiedPlanVal,
      concession: concessionVal,
      customDiscount: newCustomDiscount,
      transportRequired: newTransportRequired,
      transportRoute: newTransportRoute,
      name: document.getElementById('r-name').value.trim(),
      cls: document.getElementById('r-class').value,
      div: document.getElementById('r-div').value,
      roll: parseInt(document.getElementById('r-roll').value),
      dob: document.getElementById('r-dob').value,
      gender: document.getElementById('r-gender').value,
      blood: document.getElementById('r-blood').value,
      sid: document.getElementById('r-sid').value,
      uid: document.getElementById('r-uid').value,
      pen: document.getElementById('r-pen').value,
      apaar: document.getElementById('r-apaar').value,
      placeOfBirth: document.getElementById('r-pob').value,
      motherTongue: document.getElementById('r-mothertongue').value,
      religion: document.getElementById('r-religion').value,
      caste: document.getElementById('r-caste').value,
      subcaste: document.getElementById('r-subcaste').value,
      category: document.getElementById('r-category').value,
      nationality: document.getElementById('r-nationality').value,
      couponType: document.getElementById('r-coupon').value,
      rte: document.getElementById('r-rte').value,
      gr: document.getElementById('r-gr').value,
      medium: document.getElementById('r-medium').value,
      admno: document.getElementById('r-admno').value,
      admdate: document.getElementById('r-admdate').value,
      acyr: document.getElementById('r-acyr').value,
      prevschool: document.getElementById('r-prevschool').value,
      fatherName: document.getElementById('r-fname').value.trim(),
      fatherOcc: document.getElementById('r-focc').value,
      fatherMobile: document.getElementById('r-fmob').value,
      fatherAadhar: document.getElementById('r-faadhar').value,
      motherName: document.getElementById('r-mname').value.trim(),
      motherOcc: document.getElementById('r-mocc').value,
      motherMobile: document.getElementById('r-mmob').value,
      guardian: document.getElementById('r-gname').value,
      income: document.getElementById('r-income').value,
      email: document.getElementById('r-email').value,
      addr: document.getElementById('r-addr').value,
      city: document.getElementById('r-city').value,
      taluka: document.getElementById('r-taluka').value,
      dist: document.getElementById('r-dist').value,
      state: document.getElementById('r-state').value,
      pin: document.getElementById('r-pin').value,
      medical: document.getElementById('r-medical').value,
      emname: document.getElementById('r-emname').value,
      emnum: document.getElementById('r-emnum').value,
      disabled: document.getElementById('r-disabled').value,
      bus: document.getElementById('r-route') ? document.getElementById('r-route').value : '',
      photo: photo || students[idx].photo,
    };

    // ── CLERK / TEACHER → send edit for principal approval ────────────
    if (currentUser && (currentUser.role === 'clerk' || currentUser.role === 'teacher')) {
      const pending = LS.get('pending_student_registrations') || [];
      pending.push({
        id: 'edit_' + id + '_' + Date.now(),
        type: 'edit',
        originalId: id,
        submittedBy: currentUser.username,
        submittedAt: new Date().toISOString(),
        student: students[idx],
        status: 'pending'
      });
      LS.set('pending_student_registrations', pending);
      // Restore original data (don't apply edit until approved)
      students[idx] = getStudents().find(x => x.id === id) || students[idx];
      addAuditEntry('STUDENT_EDIT_PENDING', `Clerk submitted edit for approval: ${students[idx].name} (${students[idx].cls})`, '', currentUser.username);
      showAlert('reg-alert','success','✅ Edit submitted for Principal approval. Changes will take effect after approval from Registration Approvals.');
      clearRegForm();
      autoAdmissionNumber();
      return;
    }

    // ── PRINCIPAL → apply directly ────────────────────────────
    saveStudents(students);
    if (financeRelevantChanged) resyncStudentFeePlan(id);
    addAuditEntry('STUDENT_UPDATE', `Updated student: ${students[idx].name} (${students[idx].cls} ${students[idx].div})`, '', '');
    alert(`✅ Student Updated Successfully!\n\nName: ${students[idx].name}\nClass: ${students[idx].cls} ${students[idx].div}\n\nForm will be cleared for next registration.${financeRelevantChanged ? '\n\n💰 Fee ledger has been resynced to match the updated plan/route.' : ''}`);
    clearRegForm();
    autoAdmissionNumber();
  };
  if (photoFile) {
    const r = new FileReader();
    r.onload = e => finish(e.target.result);
    r.readAsDataURL(photoFile);
  } else finish('');
}

function deleteStudent() {
  if (!confirm('Delete this student? This cannot be undone.')) return;
  let students = getStudents();
  students = students.filter(x => x.id !== currentSelectedStudentId);
  saveStudents(students);
  closeModal('modal-student');
  renderStudentTable();
}

// ====================== MARKS ======================
let currentMarksClass = '';
let currentMarksTerm = '';
let currentMarksAssess = '';

function loadMarksSubjects() {
  const cls = document.getElementById('m-class').value;
  const struct = getMarkStructure(cls);
  // For class 11, hide Term & Assessment selectors — single exam only
  const termRow = document.getElementById('m-term') ? document.getElementById('m-term').closest('.form-group') : null;
  const assessRow = document.getElementById('m-assess') ? document.getElementById('m-assess').closest('.form-group') : null;
  if (termRow) termRow.style.display = struct.type === 'college' ? 'none' : '';
  if (assessRow) assessRow.style.display = struct.type === 'college' ? 'none' : '';
}

function loadMarksTable() {
  const cls = document.getElementById('m-class').value;
  const div = document.getElementById('m-div').value;
  const term = document.getElementById('m-term').value;
  const assess = document.getElementById('m-assess').value;
  
  if (!cls) { alert('Please select a class.'); return; }
  
  currentMarksClass = cls;
  currentMarksTerm = term;
  currentMarksAssess = assess;
  
  const subjects = getSubjects()[cls] || [];
  const struct = getMarkStructure(cls);

  // Class 11: single exam, each subject out of 100
  if (struct.type === 'college') {
    return loadMarksTable11(cls, div, subjects);
  }

  let maxMark = assess.startsWith('FA') ? struct.fa1 : struct.sa1;
  if (struct.type === 'nursery' && assess === 'FA2') maxMark = struct.ia1;

  // Restore co-scholastic area visibility (may have been hidden for 11th)
  const coSchEl = document.getElementById('coscholastic-area');
  if (coSchEl) coSchEl.style.display = '';

  // Check teacher permission
  if (currentUser.role === 'teacher' && !currentUser.viewAll) {
    const tClasses = Array.isArray(currentUser.classes) ? currentUser.classes : [];
    if (tClasses.length && !tClasses.includes(cls)) {
      alert('You do not have permission to enter marks for this class.'); return;
    }
  }
  
  let students = getStudents().filter(s => s.cls === cls && s.div === div);
  if (!students.length) { alert('No students found for this class/division.'); return; }
  
  students.sort((a,b) => a.roll - b.roll);
  
  document.getElementById('marks-table-area').style.display='block';
  document.getElementById('marks-table-title').textContent = `Marks Entry — Class ${cls} Div ${div} | Term ${term} | ${assess} (Max: ${maxMark})`;
  
  const marks = getMarks();
  
  // Header
  const thead = document.getElementById('marks-thead');
  thead.innerHTML = `<th>Roll</th><th>Name</th>` + subjects.map(sub => `<th>${sub}<br/><small>/${maxMark}</small></th>`).join('') + `<th>Total</th><th>%</th><th>Grade</th>`;
  
  // Body
  const tbody = document.getElementById('marks-tbody');
  tbody.innerHTML = students.map(s => {
    const key = `${s.id}_T${term}_${assess}`;
    const sm = marks[key] || {};
    const subInputs = subjects.map(sub => {
      const safeKey = sub.replace(/[^a-z0-9]/gi,'_');
      const val = sm[safeKey] !== undefined ? sm[safeKey] : '';
      return `<td><input type="number" min="0" max="${maxMark}" value="${val}" data-stu="${s.id}" data-sub="${safeKey}" class="mark-input" style="width:60px;padding:4px;border:1px solid #ddd;border-radius:4px;text-align:center;" oninput="calcRowTotal(this)"/></td>`;
    }).join('');
    const total = Object.values(sm).reduce((a,b) => a + (Number(b)||0), 0);
    const pct = subjects.length ? Math.round(total / (subjects.length * maxMark) * 100) : 0;
    const grade = gradeFromPercent(pct);
    return `<tr data-stu="${s.id}">
      <td>${s.roll}</td><td><b>${s.name}</b></td>${subInputs}
      <td class="row-total" style="font-weight:700;">${total||0}</td>
      <td class="row-pct">${pct||0}%</td>
      <td class="row-grade"><span class="badge ${gradeColor(grade)}">${grade}</span></td>
    </tr>`;
  }).join('');
  
  // Co-scholastic
  renderCoScholastic(students, cls, div, term);
}

function loadMarksTable11(cls, div, subjects) {
  // Permission check
  if (currentUser.role === 'teacher' && !currentUser.viewAll) {
    const tClasses = Array.isArray(currentUser.classes) ? currentUser.classes : [];
    if (tClasses.length && !tClasses.includes(cls)) {
      alert('You do not have permission to enter marks for this class.'); return;
    }
  }

  let students = getStudents().filter(s => s.cls === cls && s.div === div);
  if (!students.length) { alert('No students found for this class/division.'); return; }
  students.sort((a,b) => a.roll - b.roll);

  // For 11th we use a fixed key: {id}_11_EXAM
  currentMarksTerm = '11';
  currentMarksAssess = 'EXAM';

  document.getElementById('marks-table-area').style.display = 'block';
  document.getElementById('marks-table-title').textContent = `Marks Entry — Class ${cls} Div ${div} | Exam (Max: 100 per subject)`;

  const marks = getMarks();

  const thead = document.getElementById('marks-thead');
  thead.innerHTML = `<th>Roll</th><th>Name</th>` +
    subjects.map(sub => `<th style="font-size:11px;">${sub}<br/><small>/100</small></th>`).join('') +
    `<th>Grand<br/>Total</th><th>%</th><th>Grade</th>`;

  const tbody = document.getElementById('marks-tbody');
  tbody.innerHTML = students.map(s => {
    const key = `${s.id}_T11_EXAM`;
    const sm = marks[key] || {};
    const subInputs = subjects.map(sub => {
      const safeKey = sub.replace(/[^a-z0-9]/gi,'_');
      const val = sm[safeKey] !== undefined ? sm[safeKey] : '';
      return `<td><input type="number" min="0" max="100" value="${val}" data-stu="${s.id}" data-sub="${safeKey}" class="mark-input" style="width:55px;padding:4px;border:1px solid #ddd;border-radius:4px;text-align:center;" oninput="calcRowTotal11(this)"/></td>`;
    }).join('');
    // Grand total: sum of all non-zero subjects (up to 6 core = 600 max)
    const vals = subjects.map(sub => Number(sm[sub.replace(/[^a-z0-9]/gi,'_')])||0);
    const filled = vals.filter(v => v > 0);
    const grandTotal = vals.reduce((a,b) => a+b, 0);
    const maxTotal = filled.length ? filled.length * 100 : subjects.length * 100;
    const pct = grandTotal ? Math.round(grandTotal / (subjects.length * 100) * 100) : 0;
    const grade11 = (() => {
      if (typeof AcademicEngine !== 'undefined' && AcademicEngine && AcademicEngine.Calc &&
          typeof AcademicEngine.Calc.grade === 'function') {
        try {
          return AcademicEngine.Calc.grade(pct);
        } catch (e) {
          console.warn('[loadMarksTable11] AcademicEngine.Calc.grade() failed, falling back to local logic:', e);
        }
      }
      return pct >= 60 ? 'A' : pct >= 45 ? 'B' : pct >= 35 ? 'C' : 'D';
    })();
    return `<tr data-stu="${s.id}">
      <td>${s.roll}</td><td><b>${s.name}</b></td>${subInputs}
      <td class="row-total" style="font-weight:700;">${grandTotal||0}</td>
      <td class="row-pct">${pct||0}%</td>
      <td class="row-grade"><span class="badge ${pct>=60?'badge-green':pct>=45?'badge-blue':pct>=35?'badge-yellow':'badge-red'}">${grade11}</span></td>
    </tr>`;
  }).join('');

  // Hide co-scholastic for 11th (not needed)
  const coSchEl = document.getElementById('coscholastic-area');
  if (coSchEl) coSchEl.style.display = 'none';
}

function calcRowTotal(input) {
  const row = input.closest('tr');
  const inputs = row.querySelectorAll('.mark-input');
  let total = 0;
  const subjects = getSubjects()[currentMarksClass] || [];
  const struct = getMarkStructure(currentMarksClass);
  const maxMark = currentMarksAssess.startsWith('FA') ? struct.fa1 : struct.sa1;
  inputs.forEach(i => total += Number(i.value)||0);
  const pct = subjects.length ? Math.round(total / (subjects.length * maxMark) * 100) : 0;
  const grade = gradeFromPercent(pct);
  row.querySelector('.row-total').textContent = total;
  row.querySelector('.row-pct').textContent = pct + '%';
  row.querySelector('.row-grade').innerHTML = `<span class="badge ${gradeColor(grade)}">${grade}</span>`;
}

function calcRowTotal11(input) {
  const row = input.closest('tr');
  const inputs = row.querySelectorAll('.mark-input');
  const subjects = getSubjects()[currentMarksClass] || [];
  let total = 0;
  inputs.forEach(i => total += Number(i.value)||0);
  const pct = subjects.length ? Math.round(total / (subjects.length * 100) * 100) : 0;
  const grade = (() => {
    if (typeof AcademicEngine !== 'undefined' && AcademicEngine && AcademicEngine.Calc &&
        typeof AcademicEngine.Calc.grade === 'function') {
      try {
        return AcademicEngine.Calc.grade(pct);
      } catch (e) {
        console.warn('[calcRowTotal11] AcademicEngine.Calc.grade() failed, falling back to local logic:', e);
      }
    }
    return pct >= 60 ? 'A' : pct >= 45 ? 'B' : pct >= 35 ? 'C' : 'D';
  })();
  row.querySelector('.row-total').textContent = total;
  row.querySelector('.row-pct').textContent = pct + '%';
  row.querySelector('.row-grade').innerHTML = `<span class="badge ${pct>=60?'badge-green':pct>=45?'badge-blue':pct>=35?'badge-yellow':'badge-red'}">${grade}</span>`;
}

function autocalcMarks() {
  const struct = getMarkStructure(currentMarksClass);
  if (struct.type === 'college') {
    document.querySelectorAll('.mark-input').forEach(i => calcRowTotal11(i));
  } else {
    document.querySelectorAll('.mark-input').forEach(i => calcRowTotal(i));
  }
}

function saveMarks() {
  if (isActiveYearLocked()) { alert('🔒 The current academic year is locked. Marks cannot be edited. Ask the Principal to unlock it in Academic Years.'); return; }
  const marks = getMarks();
  const subjects = getSubjects()[currentMarksClass] || [];
  document.querySelectorAll('#marks-tbody tr').forEach(row => {
    const stuId = row.dataset.stu;
    const key = `${stuId}_T${currentMarksTerm}_${currentMarksAssess}`;
    const sm = {};
    row.querySelectorAll('.mark-input').forEach((input, idx) => {
      const sub = subjects[idx].replace(/[^a-z0-9]/gi,'_');
      sm[sub] = Number(input.value) || 0;
    });
    marks[key] = sm;
  });
  saveMarkData(marks);
  document.getElementById('marks-save-msg').innerHTML = '<span class="alert alert-success" style="display:inline-block;">✓ Marks saved successfully!</span>';
  setTimeout(() => document.getElementById('marks-save-msg').innerHTML='', 3000);
}

function renderCoScholastic(students, cls, div, term) {
  const marks = getMarks();
  const tbody = document.getElementById('coscholastic-tbody');
  const isNursery = ['Nursery','Jr.KG','Sr.KG'].includes(cls);
  
  tbody.innerHTML = students.map(s => {
    const key = `${s.id}_cosch_T${term}`;
    const c = marks[key] || {};
    const sel = (name, field, opts=['A1','A2','B']) => {
      const val = c[field] || '';
      return `<select data-stu="${s.id}" data-field="${field}" class="cosch-input" style="padding:3px;border:1px solid #ddd;border-radius:4px;font-size:12px;width:60px;">
        ${opts.map(o => `<option ${val===o?'selected':''}>${o}</option>`).join('')}
      </select>`;
    };
    const numInput = (field, placeholder='') => {
      const val = c[field] || '';
      return `<input type="text" value="${val}" placeholder="${placeholder}" data-stu="${s.id}" data-field="${field}" class="cosch-input" style="width:60px;padding:3px;border:1px solid #ddd;border-radius:4px;font-size:12px;text-align:center;"/>`;
    };
    
    const nurseryCols = isNursery ? `
      <td>${sel('social_skill','social_skill')}</td>
      <td>${sel('discipline','discipline')}</td>
      <td>${sel('activity','activity')}</td>
      <td>${sel('conversation','conversation')}</td>
    ` : `<td>—</td><td>—</td><td>—</td><td>—</td>`;
    
    return `<tr>
      <td><b>${s.roll}. ${s.name}</b></td>
      <td>${sel(s.id+'_art','art')}</td>
      <td>${sel(s.id+'_phy','phy')}</td>
      <td>${sel(s.id+'_work','work')}</td>
      ${nurseryCols}
      <td>${numInput('height','cm')}</td>
      <td>${numInput('weight','kg')}</td>
      <td>${numInput('attend','xx/yy')}</td>
    </tr>`;
  }).join('');
}

function saveCoScholastic() {
  if (isActiveYearLocked()) { alert('🔒 The current academic year is locked. Co-scholastic/attendance records cannot be edited. Ask the Principal to unlock it in Academic Years.'); return; }
  const marks = getMarks();
  const term = currentMarksTerm;
  const inputs = document.querySelectorAll('.cosch-input');
  const data = {};
  inputs.forEach(el => {
    const stuId = el.dataset.stu;
    const field = el.dataset.field;
    if (!data[stuId]) data[stuId] = {};
    data[stuId][field] = el.value;
  });
  Object.entries(data).forEach(([stuId, fields]) => {
    const key = `${stuId}_cosch_T${term}`;
    marks[key] = { ...(marks[key]||{}), ...fields };
  });
  saveMarkData(marks);
  document.getElementById('cosch-save-msg').innerHTML = '<span class="alert alert-success" style="display:inline-block;">✓ Co-scholastic saved!</span>';
  setTimeout(() => document.getElementById('cosch-save-msg').innerHTML='', 3000);
}

