// ====================== TEACHERS ======================
function renderTeacherTable() {
  const teachers = getTeachers();
  const tbody = document.getElementById('teacher-table-body');
  if (!teachers.length) {
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:20px;color:#aaa;">No teachers added yet.</td></tr>';
    return;
  }
  tbody.innerHTML = teachers.map(t => {
    const assignments = t.classAssignments && t.classAssignments.length
      ? t.classAssignments.map(a => `<span class="badge badge-blue" style="margin:1px;font-size:10px;">${a}</span>`).join(' ')
      : (Array.isArray(t.classes) && t.classes.length ? t.classes.join(', ') : '—');
    return `
    <tr>
      <td><b>${t.name}</b>${t.empid ? `<br/><span style="font-size:11px;color:#888;">ID: ${t.empid}</span>` : ''}</td>
      <td>${t.username}<br/><span style="font-size:11px;color:#888;">${t.type||''}</span></td>
      <td style="font-size:12px;">${t.qual||'—'}</td>
      <td>${t.subject||'—'}</td>
      <td>${t.mobile||'—'}</td>
      <td style="max-width:200px;">${assignments}</td>
      <td>${t.viewAll=='1'?'✅ Yes':'❌ No'}</td>
      <td>
        <button class="btn btn-outline btn-sm" onclick="openTeacherModal('${t.id}')">Edit</button>
        <button class="btn btn-red btn-sm" style="margin-left:6px;" onclick="deleteTeacher('${t.id}')">Delete</button>
      </td>
    </tr>`;
  }).join('');
}

function openTeacherModal(id) {
  document.getElementById('teacher-modal-title').textContent = id ? 'Edit Teacher' : 'Add Teacher';
  document.getElementById('t-edit-id').value = id || '';
  // Clear all fields
  ['t-name','t-username','t-password','t-mobile','t-email','t-aadhar','t-pan','t-addr',
   't-subject','t-empid','t-classes','t-divs'].forEach(i => { const el=document.getElementById(i); if(el) el.value=''; });
  const dobEl=document.getElementById('t-dob'); if(dobEl) dobEl.value='';
  const joinEl=document.getElementById('t-joining'); if(joinEl) joinEl.value='';
  document.getElementById('t-viewall').value='0';

  // Build class-division assignment grid — Nursery to 10th only
  const classes = ['Nursery','Jr.KG','Sr.KG','1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th'];
  const divs = ['A','B','C','D'];
  let existingAssignments = [];

  if (id) {
    const t = getTeachers().find(x => x.id === id);
    if (t) {
      document.getElementById('t-name').value     = t.name||'';
      document.getElementById('t-username').value = t.username||'';
      document.getElementById('t-mobile').value   = t.mobile||'';
      const emailEl=document.getElementById('t-email');   if(emailEl)  emailEl.value  = t.email||'';
      const aadEl=document.getElementById('t-aadhar');    if(aadEl)    aadEl.value    = t.aadhar||'';
      const panEl=document.getElementById('t-pan');       if(panEl)    panEl.value    = t.pan||'';
      const addrEl=document.getElementById('t-addr');     if(addrEl)   addrEl.value   = t.addr||'';
      document.getElementById('t-subject').value  = t.subject||'';
      const empEl=document.getElementById('t-empid');     if(empEl)    empEl.value    = t.empid||'';
      document.getElementById('t-classes').value  = Array.isArray(t.classes) ? t.classes.join(',') : (t.classes||'');
      document.getElementById('t-divs').value     = Array.isArray(t.divs) ? t.divs.join(',') : (t.divs||'');
      document.getElementById('t-viewall').value  = t.viewAll||'0';
      if(t.dob)     document.getElementById('t-dob').value     = t.dob;
      if(t.joining) document.getElementById('t-joining').value = t.joining;
      const gEl=document.getElementById('t-gender'); if(gEl&&t.gender)  gEl.value=t.gender;
      const qEl=document.getElementById('t-qual');   if(qEl&&t.qual)    qEl.value=t.qual;
      const mEl=document.getElementById('t-medium'); if(mEl&&t.medium)  mEl.value=t.medium;
      const tyEl=document.getElementById('t-type');  if(tyEl&&t.type)   tyEl.value=t.type;
      existingAssignments = t.classAssignments || [];
    }
  }

  // Build checkboxes — Nursery to 10th × A-D
  const grid = document.getElementById('class-assignment-grid');
  grid.innerHTML = classes.map(cls =>
    divs.map(div => {
      const key = `${cls}-${div}`;
      const checked = existingAssignments.includes(key) ? 'checked' : '';
      return `<label style="display:flex;align-items:center;gap:6px;font-size:12px;padding:5px 8px;border:1px solid #e0dcd5;border-radius:6px;cursor:pointer;background:#faf7f2;">
        <input type="checkbox" value="${key}" class="class-assign-cb" ${checked}/> ${cls} – ${div}
      </label>`;
    }).join('')
  ).join('');

  openModal('modal-teacher');
}

function saveTeacher() {
  const name     = document.getElementById('t-name').value.trim();
  const username = document.getElementById('t-username').value.trim();
  const password = document.getElementById('t-password').value;
  if (!name || !username) {
    document.getElementById('teacher-modal-msg').innerHTML='<span class="alert alert-error" style="display:inline-block;">Name and username are required.</span>';
    return;
  }

  const teachers = getTeachers();
  const editId   = document.getElementById('t-edit-id').value;
  let _syncTeacherId = editId || null; // [Phase 16.3] tracks which teacher record changed, for the profile-sync queue hook below

  const manualClasses = document.getElementById('t-classes').value.split(',').map(x=>x.trim()).filter(Boolean);
  const manualDivs    = document.getElementById('t-divs').value.split(',').map(x=>x.trim()).filter(Boolean);

  // Collect checkbox selections
  const classAssignments = [...document.querySelectorAll('.class-assign-cb:checked')].map(cb => cb.value);
  const assignedClasses  = [...new Set(classAssignments.map(a => a.split('-')[0]))];
  const assignedDivs     = [...new Set(classAssignments.map(a => a.split('-')[1]))];
  const finalClasses     = assignedClasses.length ? assignedClasses : manualClasses;
  const finalDivs        = assignedDivs.length    ? assignedDivs    : manualDivs;

  const teacherData = {
    name, username,
    mobile:   document.getElementById('t-mobile').value,
    email:    (document.getElementById('t-email')   ||{}).value||'',
    aadhar:   (document.getElementById('t-aadhar')  ||{}).value||'',
    pan:      (document.getElementById('t-pan')      ||{}).value||'',
    addr:     (document.getElementById('t-addr')     ||{}).value||'',
    dob:      (document.getElementById('t-dob')      ||{}).value||'',
    gender:   (document.getElementById('t-gender')   ||{}).value||'',
    qual:     (document.getElementById('t-qual')     ||{}).value||'',
    medium:   (document.getElementById('t-medium')   ||{}).value||'',
    joining:  (document.getElementById('t-joining')  ||{}).value||'',
    empid:    (document.getElementById('t-empid')    ||{}).value||'',
    type:     (document.getElementById('t-type')     ||{}).value||'',
    subject:  document.getElementById('t-subject').value,
    classes:  finalClasses,
    divs:     finalDivs,
    classAssignments,
    viewAll:  document.getElementById('t-viewall').value,
  };

  if (editId) {
    const idx = teachers.findIndex(x => x.id === editId);
    // Duplicate-username check (excluding self) — same rule as clerk accounts
    if (teachers.some(x => x.id !== editId && x.username === username) || getUsers().some(u => u.username === username)) {
      document.getElementById('teacher-modal-msg').innerHTML='<span class="alert alert-error" style="display:inline-block;">Username already in use by another account.</span>';
      return;
    }
    if (idx >= 0) {
      teachers[idx] = { ...teachers[idx], ...teacherData };
      if (password) teachers[idx].password = password;
    }
    addAuditEntry('USER_EDIT', `Edited teacher account: ${username}`, '', currentUser ? currentUser.username : '');
  } else {
    if (!password) {
      document.getElementById('teacher-modal-msg').innerHTML='<span class="alert alert-error" style="display:inline-block;">Password is required for a new teacher.</span>';
      return;
    }
    // Duplicate-username check against teachers AND principal/clerk accounts — usernames must be unique app-wide
    if (teachers.some(x => x.username === username) || getUsers().some(u => u.username === username)) {
      document.getElementById('teacher-modal-msg').innerHTML='<span class="alert alert-error" style="display:inline-block;">Username already in use by another account.</span>';
      return;
    }
    const newTeacherId = Date.now().toString();
    teachers.push({ id: newTeacherId, password, ...teacherData });
    _syncTeacherId = newTeacherId;
    addAuditEntry('USER_CREATE', `Created teacher account: ${username}`, '', currentUser ? currentUser.username : '');
  }
  saveTeachersList(teachers);

  // [Phase 16.3] Additive — record a profile-sync intent for this teacher
  // (local-only write to the Entity Sync Queue) and best-effort ask the
  // Migration/Auth subsystem's sync service to process it now. The Teacher
  // module still never touches public.profiles itself — see
  // Dnyanankur.Sync.EntityQueue / Dnyanankur.Sync.ProfileSyncService
  // (single-owner rule unchanged).
  try {
    if (_syncTeacherId && window.Dnyanankur && Dnyanankur.Sync && Dnyanankur.Sync.EntityQueue) {
      const savedTeacher = teachers.find(t => t.id === _syncTeacherId) || {};
      Dnyanankur.Sync.EntityQueue.enqueue('teacher', _syncTeacherId, {
        classAssignments: savedTeacher.classAssignments || [],
        classes: savedTeacher.classes || [],
        viewAll: savedTeacher.viewAll == '1' || savedTeacher.viewAll === true,
        disabled: !!savedTeacher.disabled
      }, currentUser ? currentUser.username : 'system');
      if (Dnyanankur.Sync.ProfileSyncService) Dnyanankur.Sync.ProfileSyncService.processPending();
    }
  } catch (e) { /* best-effort only — local save above already succeeded regardless */ }

  closeModal('modal-teacher');
  renderTeacherTable();
}

function deleteTeacher(id) {
  if (!confirm('Delete this teacher account?')) return;
  const t = getTeachers().find(x => x.id === id);
  saveTeachersList(getTeachers().filter(x => x.id !== id));
  if (t) addAuditEntry('USER_DELETE', `Deleted teacher account: ${t.username}`, '', currentUser ? currentUser.username : '');
  renderTeacherTable();
}

// ====================== SETTINGS ======================
function loadSettingsForm() {
  const s = getSettings();
  ['name','principal','udise','reg','addr','phone1','phone2','email'].forEach(k => {
    const el = document.getElementById('s-'+k); if(el) el.value = s[k]||'';
  });
  if (s.logo) {
    const img = document.getElementById('s-logo-preview');
    img.src = s.logo; img.style.display='block';
  }
  
  const acSettings = LS.get('academic_settings') || {};
  ['acyr','t1start','t1end','t2start','t2end','reopen'].forEach(k => {
    const el = document.getElementById('s-'+k);
    if(el) el.value = acSettings[k] || s[k] || '';
  });

  // Watermark settings
  const wmLC = document.getElementById('wm-lc');
  const wmBon = document.getElementById('wm-bon');
  const wmRC = document.getElementById('wm-rc');
  if (wmLC) wmLC.checked = s.wmLC !== false;
  if (wmBon) wmBon.checked = s.wmBon !== false;
  if (wmRC) wmRC.checked = s.wmRC === true;
  
  buildSubjectsEditor();
}

function saveSettings() {
  const s = getSettings();
  ['name','principal','udise','reg','addr','phone1','phone2','email'].forEach(k => {
    const el = document.getElementById('s-'+k); if(el) s[k] = el.value;
  });
  
  const logoFile = document.getElementById('s-logo').files[0];
  const finish = (logo) => {
    if (logo) s.logo = logo;
    LS.set('school_settings', s);
    document.getElementById('sidebar-school-name').textContent = s.name.split(' ').slice(0,3).join(' ');
    showAlert('settings-msg','success','Settings saved!');
  };
  if (logoFile) {
    const r = new FileReader(); r.onload = e => finish(e.target.result); r.readAsDataURL(logoFile);
  } else finish('');
}

function saveAcademic() {
  const data = {};
  ['acyr','t1start','t1end','t2start','t2end','reopen'].forEach(k => {
    const el = document.getElementById('s-'+k); if(el) data[k] = el.value;
  });
  LS.set('academic_settings', data);
  const s = getSettings(); s.acyr = data.acyr; s.reopen = data.reopen;
  LS.set('school_settings', s);
  showAlert('academic-msg','success','Academic settings saved!');
}

function changePrincipalPass() {
  const np = document.getElementById('s-newpass').value;
  const cp = document.getElementById('s-confpass').value;
  if (!np || np !== cp) { showAlert('pass-msg','error','Passwords do not match.'); return; }
  const users = getUsers();
  const pi = users.findIndex(x => x.role==='principal');
  if (pi >= 0) { users[pi].password = np; LS.set('users', users); }
  else { users.push({id:'principal',username:'principal',password:np,role:'principal',name:'Patil Pallavi Subhash',classes:[],viewAll:true}); LS.set('users',users); }
  showAlert('pass-msg','success','Password changed!');
}

function buildSubjectsEditor() {
  const subjects = getSubjects();
  const classes = ['Nursery','Jr.KG','Sr.KG','1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th'];
  document.getElementById('subjects-editor').innerHTML = classes.map(cls => `
    <div style="margin-bottom:12px;">
      <label style="font-size:12px;font-weight:700;color:var(--navy);">${cls}</label>
      <div style="display:flex;gap:8px;align-items:center;margin-top:4px;">
        <input type="text" id="subj-${cls.replace('.','_')}" value="${(subjects[cls]||[]).join(', ')}" style="flex:1;font-size:12px;padding:7px 10px;border:1.5px solid #ddd;border-radius:6px;"/>
        <button class="btn btn-outline btn-sm" onclick="addSubject('${cls}')">+ Add</button>
      </div>
      <p style="font-size:11px;color:#999;margin-top:2px;">Comma-separated. Edit freely.</p>
    </div>`).join('');
}

function addSubject(cls) {
  const id = `subj-${cls.replace('.','_')}`;
  const el = document.getElementById(id);
  const newSub = prompt(`Add subject to ${cls}:`);
  if (newSub && newSub.trim()) {
    el.value = el.value ? el.value + ', ' + newSub.trim() : newSub.trim();
  }
}

function saveSubjects() {
  const classes = ['Nursery','Jr.KG','Sr.KG','1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th'];
  const subjects = {};
  classes.forEach(cls => {
    const id = `subj-${cls.replace('.','_')}`;
    const el = document.getElementById(id);
    if (el) subjects[cls] = el.value.split(',').map(x=>x.trim()).filter(Boolean);
    else subjects[cls] = getSubjects()[cls]||[];
  });
  LS.set('class_subjects', subjects);
  showAlert('subjects-msg','success','Subjects saved!');
}

function previewLogo(input) {
  const file = input.files[0];
  if (file) {
    const r = new FileReader();
    r.onload = e => { const img=document.getElementById('s-logo-preview'); img.src=e.target.result; img.style.display='block'; };
    r.readAsDataURL(file);
  }
}

function switchSettingsTab(tab, el) {
  document.querySelectorAll('.settings-tab').forEach(t => t.style.display='none');
  document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
  document.getElementById('settings-'+tab).style.display='block';
  el.classList.add('active');
}

// ====================== BACKUP / RESTORE ======================
function exportBackup() {
  const allKeys = ['school_settings','academic_settings','students','teachers','users','marks','fees','student_fee_structures','class_subjects','class_teacher_appointments','academic_years','academic_year_archives','student_year_history','inactive_students'];
  const backup = { _version: 2, _date: new Date().toISOString(), _school: (getSettings().name || 'School') };
  allKeys.forEach(k => { const v = localStorage.getItem(k); if (v !== null) backup[k] = JSON.parse(v); });

  const json = JSON.stringify(backup, null, 2);
  const blob = new Blob([json], {type:'application/json'});
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  const date = new Date().toISOString().split('T')[0];
  a.href     = url;
  a.download = `DnyanankurSMS_Backup_${date}.json`;
  a.click();
  URL.revokeObjectURL(url);

  // Show confirmation
  const msg = document.getElementById('backup-export-msg');
  if (msg) { msg.style.display='block'; setTimeout(()=>msg.style.display='none',4000); }
  else alert('✅ Backup exported successfully! Save this file to your pendrive or cloud storage (Google Drive, OneDrive, etc.)');
}

function importBackup(input) {
  const file = input.files[0];
  if (!file) return;
  if (!confirm('⚠ IMPORTANT: Importing a backup will REPLACE all current data.\n\nAre you sure you want to continue?')) {
    input.value = ''; return;
  }
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const backup = JSON.parse(e.target.result);
      if (!backup._version) { alert('❌ Invalid backup file.'); return; }
      const allKeys = ['school_settings','academic_settings','students','teachers','users','marks','fees','student_fee_structures','class_subjects','class_teacher_appointments','academic_years','academic_year_archives','student_year_history','inactive_students'];
      allKeys.forEach(k => { if (backup[k] !== undefined) localStorage.setItem(k, JSON.stringify(backup[k])); });
      alert(`✅ Backup restored successfully!\nSchool: ${backup._school}\nBackup Date: ${(backup._date||'').split('T')[0]}\n\nPage will reload now.`);
      location.reload();
    } catch(err) {
      alert('❌ Failed to import backup. The file may be corrupted.\n' + err.message);
    }
  };
  reader.readAsText(file);
  input.value = '';
}

// ====================== HELPERS ======================
function openModal(id) { document.getElementById(id).classList.add('open'); }
function closeModal(id) { document.getElementById(id).classList.remove('open'); }

function showAlert(targetId, type, msg) {
  const el = document.getElementById(targetId);
  if (!el) return;
  el.className = `alert alert-${type}`;
  el.textContent = msg;
  el.style.display = 'block';
  setTimeout(() => { el.style.display='none'; }, 5000);
}

function printArea(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const w = window.open('','_blank');
  w.document.write(`<!DOCTYPE html><html><head><title>Print</title>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=DM+Sans:wght@400;600&display=swap" rel="stylesheet"/>
    <style>
      *{box-sizing:border-box;margin:0;padding:0;}
      body{font-family:'DM Sans',Arial,sans-serif;background:#fff;color:#111;}
      table{border-collapse:collapse;width:100%;}
      /* Colour-safe table headers: dark navy bg + white text — prints as dark grey in B&W */
      th{background:#1a3a6b;color:#fff;font-weight:700;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
      /* Light tint rows — almost white, shows as very light grey in B&W */
      .rc-table th{background:#1a3a6b;color:#fff;}
      .rc-table td{border:1px solid #888;}
      .badge{display:inline-block;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:700;border:1.5px solid #333;background:#f0f0f0;color:#111;}
      @page{size:A4 portrait;margin:10mm 12mm;}
      @media print{
        body{margin:0;}
        .print-area{page-break-after:always;}
        .print-area:last-child{page-break-after:avoid;}
        *{-webkit-print-color-adjust:exact;print-color-adjust:exact;}
      }
    </style>
    </head><body>${el.innerHTML}</body></html>`);
  w.document.close();
  setTimeout(()=>{w.print();},600);
}

function populateStudentSearchDropdowns() {
  const students = getStudents();
  ['bon-student','tc-student','id-student'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    sel.innerHTML = '<option value="">Select Student</option>' + students.map(s => `<option value="${s.id}">${s.name} — ${s.cls} ${s.div} Roll:${s.roll}</option>`).join('');
  });
}

function searchStudentFor(prefix) {
  const q = document.getElementById(prefix+'-search').value.toLowerCase();
  const sel = document.getElementById(prefix+'-student');
  const students = getStudents();
  const filtered = q ? students.filter(s => (s.name+s.roll+s.admno).toLowerCase().includes(q)) : students;
  sel.innerHTML = '<option value="">Select Student</option>' + filtered.map(s => `<option value="${s.id}">${s.name} — ${s.cls} ${s.div} Roll:${s.roll}</option>`).join('');
}

function loadBonafide() { /* auto on select */ }

function recalcTCLastSchool() {
  var stdEl = document.getElementById('tc-current-std');
  var lastSchoolEl = document.getElementById('tc-lastschool');
  if (!stdEl || !lastSchoolEl) return;
  var computedCls = stdEl.value || '';
  var CLS_ORD = ['Nursery','Jr.KG','Sr.KG','1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th','11th','12th'];
  var currentStdIdx = CLS_ORD.indexOf(computedCls);
  var prevStd = currentStdIdx > 0 ? CLS_ORD[currentStdIdx - 1] : '';
  var sid = document.getElementById('tc-student') ? document.getElementById('tc-student').value : '';
  var s = sid ? (getStudents().find(function(x){return x.id===sid;}) || null) : null;
  var schoolName = (s && s.prevschool) ? s.prevschool : (getSettings().name || '');
  if (prevStd && schoolName) {
    lastSchoolEl.value = schoolName + ' — ' + prevStd;
  } else if (prevStd) {
    lastSchoolEl.value = prevStd;
  } else {
    lastSchoolEl.value = (s && s.prevschool) ? s.prevschool : '';
  }
}

function loadTC() {
  const sid = document.getElementById('tc-student').value;
  const infoPanel = document.getElementById('tc-student-info');
  const infoBody = document.getElementById('tc-student-info-body');
  // Clear fields
  ['tc-sid','tc-uid','tc-pen','tc-apaar','tc-mothertongue','tc-pob','tc-since-year'].forEach(id => {
    const el = document.getElementById(id); if(el) el.value = '';
  });
  const stdEl = document.getElementById('tc-current-std');
  if(stdEl) stdEl.value = '';
  if (!sid) { if(infoPanel) infoPanel.style.display='none'; return; }
  const s = getStudents().find(x => x.id === sid);
  if (!s) return;

  // Fill editable fields from student record
  const set = (id, val) => { const el=document.getElementById(id); if(el) el.value = val||''; };
  set('tc-sid', s.sid);
  set('tc-uid', s.uid);
  set('tc-pen', s.pen);
  set('tc-apaar', s.apaar);
  set('tc-mothertongue', s.motherTongue);
  set('tc-pob', s.placeOfBirth);

  // Calculate current standard from admission class + years elapsed since admission
  const activeYrLabel = (getActiveYear() && getActiveYear().label) || (getSettings().acyr) || '';
  const currentAcyr = s.acyr || activeYrLabel || '';

  // Try to get current class from student_year_history (most accurate if Promotion Wizard was run)
  const allHistory = getStudentYearHistory().filter(h => h.studentId === s.id);
  let computedCls = s.cls || '';
  let computedDiv = s.div || 'A';

  if (allHistory.length > 0) {
    // Use the latest history entry's promotedToClass if available, else cls
    const latestHistory = allHistory.sort((a,b) => new Date(b.recordedAt) - new Date(a.recordedAt))[0];
    if (latestHistory.promotedToClass) {
      computedCls = latestHistory.promotedToClass;
      computedDiv = latestHistory.promotedToDiv || s.div || 'A';
    } else {
      computedCls = latestHistory.cls || s.cls || '';
      computedDiv = latestHistory.div || s.div || 'A';
    }
  } else {
    // Fallback: calculate from admission year + CLASS_ORDER
    // admdate e.g. "2022-06-01", acyr e.g. "2026-27"
    const admYear = s.admdate ? parseInt(s.admdate.substring(0,4)) : null;
    const currentStartYear = currentAcyr ? parseInt(currentAcyr.split('-')[0]) : null;
    if (admYear && currentStartYear && typeof CLASS_ORDER !== 'undefined') {
      const yearsElapsed = currentStartYear - admYear;
      const admIdx = CLASS_ORDER.indexOf(s.cls);
      if (admIdx !== -1) {
        const currentIdx = Math.min(admIdx + yearsElapsed, CLASS_ORDER.length - 1);
        computedCls = CLASS_ORDER[Math.max(0, currentIdx)] || s.cls;
      }
    }
  }

  set('tc-since-year', currentAcyr);
  if(stdEl) stdEl.value = computedCls;
  const divEl = document.getElementById('tc-current-div');
  if(divEl) divEl.value = computedDiv;

  // Auto-calculate Last School & Standard: (Standard in Which Studying) - 1
  recalcTCLastSchool();

  // Show student info preview panel
  if (infoPanel && infoBody) {
    const field = (label, val) => `<div><span style="color:#555;font-size:11px;">${label}</span><br/><b style="color:${val?'#1c1c1c':'#c0392b'}">${val||'— NOT SET —'}</b></div>`;
    infoBody.innerHTML =
      field('Name', s.name) +
      field('Class/Div', (s.cls||'') + ' ' + (s.div||'')) +
      field('DOB', s.dob) +
      field('Father', s.fatherName) +
      field('Mother', s.motherName) +
      field('GR No.', s.gr) +
      field('SID', s.sid) +
      field('UID', s.uid) +
      field('PEN No.', s.pen) +
      field('APAAR ID', s.apaar) +
      field('Mother Tongue', s.motherTongue) +
      field('Place of Birth', s.placeOfBirth) +
      field('Religion', s.religion) +
      field('Caste', s.caste) +
      field('Nationality', s.nationality);
    infoPanel.style.display = 'block';
  }
}

function saveTCFieldsToStudent() {
  const sid = document.getElementById('tc-student').value;
  if (!sid) { alert('Select a student first.'); return; }
  const students = getStudents();
  const idx = students.findIndex(x => x.id === sid);
  if (idx < 0) { alert('Student not found.'); return; }
  const get = (id) => (document.getElementById(id)||{}).value || '';
  students[idx].sid = get('tc-sid');
  students[idx].uid = get('tc-uid');
  students[idx].pen = get('tc-pen');
  students[idx].apaar = get('tc-apaar');
  students[idx].motherTongue = get('tc-mothertongue');
  students[idx].placeOfBirth = get('tc-pob');
  saveStudents(students);
  alert('✅ Fields saved to student record successfully!');
  loadTC(); // refresh preview panel
}
