// ====================== AUDIT LOG ======================
function getAuditLog() { return LS.get('audit_log') || []; }
function saveAuditLog(log) { LS.set('audit_log', log); }

function addAuditEntry(actionType, details, oldValue, newValue) {
  if (!currentUser) return;
  const log = getAuditLog();
  log.unshift({
    id: Date.now().toString(),
    timestamp: new Date().toISOString(),
    username: currentUser.username || currentUser.name,
    role: currentUser.role,
    action: actionType,
    details: details || '',
    oldValue: oldValue || '',
    newValue: newValue || '',
  });
  // Keep only last 500 entries
  if (log.length > 500) log.splice(500);
  saveAuditLog(log);
}

function renderAuditLog() {
  const tbody = document.getElementById('audit-table-body');
  if (!tbody) return;
  let log = getAuditLog();
  const q = (document.getElementById('audit-search')?.value || '').toLowerCase();
  const filter = document.getElementById('audit-filter')?.value || '';
  if (q) log = log.filter(e => (e.username+e.action+e.details+e.role).toLowerCase().includes(q));
  if (filter) log = log.filter(e => e.action.startsWith(filter));
  if (!log.length) {
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:20px;color:#aaa;">No audit entries found.</td></tr>';
    return;
  }
  tbody.innerHTML = log.map(e => {
    const dt = new Date(e.timestamp);
    const dateStr = fmtDMY(dt);
    const timeStr = dt.toLocaleTimeString('en-IN', {hour:'2-digit',minute:'2-digit'});
    const actionColors = {LOGIN:'badge-green',LOGOUT:'badge-yellow',FEE:'badge-blue',RECEIPT:'badge-blue',STUDENT:'badge-yellow',DOCUMENT:'badge-yellow',USER:'badge-red'};
    const ac = Object.keys(actionColors).find(k => e.action.startsWith(k));
    const badgeCls = actionColors[ac] || 'badge-yellow';
    return `<tr>
      <td style="font-size:12px;white-space:nowrap;">${dateStr}<br/><span style="color:#888;">${timeStr}</span></td>
      <td><b>${e.username}</b></td>
      <td><span class="badge ${badgeCls === 'badge-red' ? 'role-principal' : badgeCls === 'badge-blue' ? 'role-clerk' : 'role-teacher'}" style="font-size:11px;">${e.role}</span></td>
      <td><span class="badge ${badgeCls}" style="font-size:11px;">${e.action}</span></td>
      <td style="font-size:12px;max-width:200px;overflow:hidden;text-overflow:ellipsis;">${e.details}</td>
      <td style="font-size:11px;color:#888;max-width:120px;overflow:hidden;text-overflow:ellipsis;">${e.oldValue||'—'}</td>
      <td style="font-size:11px;color:#555;max-width:120px;overflow:hidden;text-overflow:ellipsis;">${e.newValue||'—'}</td>
    </tr>`;
  }).join('');
}

function clearAuditLog() {
  if (!confirm('Clear all audit log entries? This cannot be undone.')) return;
  saveAuditLog([]);
  renderAuditLog();
}

// ====================== CLERK MANAGEMENT ======================
function getClerks() {
  const users = getUsers();
  return users.filter(u => u.role === 'clerk');
}

function renderClerkTable() {
  const tbody = document.getElementById('clerk-table-body');
  if (!tbody) return;
  const clerks = getClerks();
  if (!clerks.length) {
    tbody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:20px;color:#aaa;">No clerks added yet.</td></tr>';
    return;
  }
  tbody.innerHTML = clerks.map(c => `
    <tr>
      <td><b>${c.name}</b></td>
      <td>${c.username}</td>
      <td>${c.mobile||'—'}</td>
      <td><span class="badge ${c.disabled ? 'badge-red' : 'badge-green'}">${c.disabled ? 'Disabled' : 'Active'}</span></td>
      <td>
        <button class="btn btn-outline btn-sm" onclick="openClerkModal('${c.id}')">Edit</button>
        <button class="btn btn-sm ${c.disabled ? 'btn-green' : 'btn-outline'}" style="margin-left:4px;" onclick="toggleClerkStatus('${c.id}')">${c.disabled ? 'Enable' : 'Disable'}</button>
        <button class="btn btn-red btn-sm" style="margin-left:4px;" onclick="deleteClerk('${c.id}')">Delete</button>
      </td>
    </tr>`).join('');
}

function openClerkModal(id) {
  document.getElementById('clerk-modal-title').textContent = id ? 'Edit Clerk' : 'Add Clerk';
  document.getElementById('c-edit-id').value = id || '';
  document.getElementById('c-name').value = '';
  document.getElementById('c-mobile').value = '';
  document.getElementById('c-username').value = '';
  document.getElementById('c-password').value = '';
  document.getElementById('clerk-modal-msg').innerHTML = '';
  if (id) {
    const users = getUsers();
    const c = users.find(u => u.id === id);
    if (c) {
      document.getElementById('c-name').value = c.name || '';
      document.getElementById('c-mobile').value = c.mobile || '';
      document.getElementById('c-username').value = c.username || '';
    }
  }
  openModal('modal-clerk');
}

function saveClerk() {
  const name = document.getElementById('c-name').value.trim();
  const mobile = document.getElementById('c-mobile').value.trim();
  const username = document.getElementById('c-username').value.trim();
  const password = document.getElementById('c-password').value;
  const editId = document.getElementById('c-edit-id').value;

  if (!name || !username) {
    document.getElementById('clerk-modal-msg').innerHTML = '<span class="alert alert-error" style="display:inline-block;">Name and username are required.</span>';
    return;
  }

  const users = getUsers();
  let _syncClerkId = null;
  if (editId) {
    const idx = users.findIndex(u => u.id === editId);
    if (idx >= 0) {
      users[idx].name = name;
      users[idx].mobile = mobile;
      users[idx].username = username;
      if (password) users[idx].password = password;
    }
    _syncClerkId = editId;
    addAuditEntry('USER_EDIT', `Edited clerk account: ${username}`, '', '');
  } else {
    if (!password) {
      document.getElementById('clerk-modal-msg').innerHTML = '<span class="alert alert-error" style="display:inline-block;">Password required for new clerk.</span>';
      return;
    }
    // Check duplicate username across clerk/principal AND teacher accounts
    if (users.find(u => u.username === username) || getTeachers().some(t => t.username === username)) {
      document.getElementById('clerk-modal-msg').innerHTML = '<span class="alert alert-error" style="display:inline-block;">Username already exists.</span>';
      return;
    }
    const newClerkId = 'clerk_' + Date.now();
    users.push({ id: newClerkId, username, password, name, mobile, role: 'clerk', classes: [], viewAll: false });
    _syncClerkId = newClerkId;
    addAuditEntry('USER_CREATE', `Created clerk account: ${username}`, '', '');
  }
  // [Phase 13G-3] Migrated off direct LS.set('users', users) — now
  // writes through the Repository Layer. Same 'users' key, same
  // whole-array shape (clerks live inside the shared users array).
  Dnyanankur.Repository.clerks.replaceAll(users);

  // [Phase 16.4] Additive — same Entity Sync wiring already used by
  // saveTeacher(): record a profile-sync intent for this clerk (local-only
  // write to the Entity Sync Queue) and best-effort ask ProfileSyncService
  // to process it now. The Clerk module still never touches public.profiles
  // itself — Dnyanankur.Sync.EntityQueue / ProfileSyncService (single-owner
  // rule unchanged, both reused as-is, unmodified).
  try {
    if (_syncClerkId && window.Dnyanankur && Dnyanankur.Sync && Dnyanankur.Sync.EntityQueue) {
      const savedClerk = users.find(u => u.id === _syncClerkId) || {};
      Dnyanankur.Sync.EntityQueue.enqueue('clerk', _syncClerkId, {
        disabled: !!savedClerk.disabled
      }, currentUser ? currentUser.username : 'system');
      if (Dnyanankur.Sync.ProfileSyncService) Dnyanankur.Sync.ProfileSyncService.processPending();
    }
  } catch (e) { /* best-effort only — local save above already succeeded regardless */ }

  closeModal('modal-clerk');
  renderClerkTable();
}

function toggleClerkStatus(id) {
  const users = getUsers();
  const idx = users.findIndex(u => u.id === id);
  if (idx >= 0) {
    users[idx].disabled = !users[idx].disabled;
    addAuditEntry('USER_STATUS', `Clerk ${users[idx].username} ${users[idx].disabled ? 'disabled' : 'enabled'}`, '', '');
    // [Phase 13G-3] Migrated off direct LS.set('users', users) — now
    // writes through the Repository Layer. Same key, same shape.
    Dnyanankur.Repository.clerks.replaceAll(users);

    // [Phase 16.4] Additive — same Entity Sync wiring as saveClerk() above.
    try {
      if (window.Dnyanankur && Dnyanankur.Sync && Dnyanankur.Sync.EntityQueue) {
        Dnyanankur.Sync.EntityQueue.enqueue('clerk', id, {
          disabled: !!users[idx].disabled
        }, currentUser ? currentUser.username : 'system');
        if (Dnyanankur.Sync.ProfileSyncService) Dnyanankur.Sync.ProfileSyncService.processPending();
      }
    } catch (e) { /* best-effort only — local save above already succeeded regardless */ }

    renderClerkTable();
  }
}

function deleteClerk(id) {
  if (!confirm('Delete this clerk account permanently?')) return;
  const users = getUsers();
  const c = users.find(u => u.id === id);
  const newUsers = users.filter(u => u.id !== id);
  // [Phase 13G-3] Migrated off direct LS.set('users', newUsers) — now
  // writes through the Repository Layer. Same key, same shape.
  Dnyanankur.Repository.clerks.replaceAll(newUsers);
  if (c) addAuditEntry('USER_DELETE', `Deleted clerk account: ${c.username}`, '', '');

  // [Phase 16.4] Additive — same Entity Sync wiring as saveClerk() above.
  // EntityQueue has no delete verb (ProfileSyncService only ever performs
  // profiles UPDATE, never DELETE — untouched, per the single-owner rule),
  // so a deletion is recorded as disabled:true, the same signal already
  // used above to mean "this account should no longer have active access."
  try {
    if (c && window.Dnyanankur && Dnyanankur.Sync && Dnyanankur.Sync.EntityQueue) {
      Dnyanankur.Sync.EntityQueue.enqueue('clerk', id, {
        disabled: true
      }, currentUser ? currentUser.username : 'system');
      if (Dnyanankur.Sync.ProfileSyncService) Dnyanankur.Sync.ProfileSyncService.processPending();
    }
  } catch (e) { /* best-effort only — local delete above already succeeded regardless */ }

  renderClerkTable();
}


