// [Phase 13G-9] Migrated off direct LS.get('fee_approvals') — now reads
// through the Repository Layer. Same key, same shape, same fallback to [].
function getFeeApprovals() {
  // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.getFeeApprovals(). This
  // wrapper preserves the exact original signature/behavior for every
  // existing caller; falls back to the original inline logic below if
  // FeeService has not loaded.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
    return Dnyanankur.Services.Fee.getFeeApprovals();
  }

 return Dnyanankur.Repository.feeApprovals.getAll(); }
// [Phase 13G-9] Migrated off direct LS.set('fee_approvals', a) — now
// writes through the Repository Layer. replaceAll() persists the whole
// array exactly as LS.set did (same key, same shape).
function saveFeeApprovals(a) {
  // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.saveFeeApprovals(). This
  // wrapper preserves the exact original signature/behavior for every
  // existing caller; falls back to the original inline logic below if
  // FeeService has not loaded.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
    return Dnyanankur.Services.Fee.saveFeeApprovals(a);
  }

 Dnyanankur.Repository.feeApprovals.replaceAll(a); }

function requestFeeAction(feeId, actionType, newData) {
  // Clerk requests a modification or deletion
  const fees = getFees();
  const f = fees.find(x => x.id === feeId);
  if (!f) return;
  const approvals = getFeeApprovals();
  approvals.push({
    id: 'APR_' + Date.now(),
    feeId,
    requestedBy: currentUser.username,
    requestedByName: currentUser.name,
    requestedAt: new Date().toISOString(),
    actionType, // 'DELETE' or 'MODIFY'
    oldData: {...f},
    newData: newData || null,
    status: 'PENDING',
  });
  saveFeeApprovals(approvals);
  // Mark the receipt as pending
  f.pendingApproval = actionType;
  saveFees(fees);
  addAuditEntry('RECEIPT_' + actionType + '_REQUEST', `Clerk requested ${actionType} for receipt ${f.rcpt}`, JSON.stringify(f), '');
  alert(`✅ Request submitted. Receipt status is now "PENDING PRINCIPAL APPROVAL". Principal has been notified.`);
  renderFeeTable();
}

// A clerk granted a C1 (Teacher Child, 50%) or C2 (Sibling, 25%) concession at registration.
// It's billed at the full standard fee (Plan 1/2/3 still applies) until the Principal approves
// here — approval bypasses Plan 1/2/3 and recalculates the % off the Annual Fee.
function requestConcessionApproval(studentId, concessionType) {
  // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.requestConcessionApproval(). This
  // wrapper preserves the exact original signature/behavior for every
  // existing caller; falls back to the original inline logic below if
  // FeeService has not loaded.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
    return Dnyanankur.Services.Fee.requestConcessionApproval(studentId, concessionType);
  }

  const approvals = getFeeApprovals();
  const label = concessionType === 'teacher' ? 'C1 — Teacher Child (50% tuition concession)' : 'C2 — Sibling (25% tuition concession)';
  approvals.push({
    id: 'APR_' + Date.now(),
    studentId,
    requestedBy: currentUser ? currentUser.username : 'clerk',
    requestedByName: currentUser ? currentUser.name : 'Clerk',
    requestedAt: new Date().toISOString(),
    actionType: 'CONCESSION_GRANT',
    concessionType,
    oldData: { label: 'No Concession (Full Fee)' },
    newData: { label },
    status: 'PENDING',
  });
  saveFeeApprovals(approvals);
  addAuditEntry('CONCESSION_REQUEST', `Clerk requested ${label} for student ID ${studentId}`, 'None', label);
}

// Recalculates a student's School Fee Ledger row once their C1/C2 concession is approved:
// concession % is taken off the Annual Fee, and the student now follows the fixed
// "Concession Plan" schedule instead of Plan 1/2/3 (see getCombinedPlanStatus()).
function applyApprovedConcession(studentId, concessionType) {
  // [PHASE-20] Logic moved to Dnyanankur.Services.Fee.applyApprovedConcession(). This
  // wrapper preserves the exact original signature/behavior for every
  // existing caller; falls back to the original inline logic below if
  // FeeService has not loaded.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Fee) {
    return Dnyanankur.Services.Fee.applyApprovedConcession(studentId, concessionType);
  }

  const students = getStudents();
  const sIdx = students.findIndex(s => s.id === studentId);
  if (sIdx < 0) return;
  students[sIdx].concession = concessionType;
  students[sIdx].concessionStatus = 'approved';
  saveStudents(students);
  const student = students[sIdx];

  const masters = getFeeMaster();
  const master = masters.find(x => x.className === getFeeMasterClassName(student));
  if (!master) return;

  const ledger = getSchoolFeeLedger();
  const lIdx = ledger.findIndex(l => l.studentId === studentId);
  if (lIdx < 0) return;

  const annualFee = Number(master.annualFee || 0);
  let concessionAmt = concessionType === 'teacher' ? Math.round(annualFee * 0.5) : Math.round(annualFee * 0.25);
  const concessionLabel = concessionType === 'teacher' ? 'Teacher Child Concession (C1 – 50%)' : 'Sibling Concession (C2 – 25%)';
  concessionAmt += Number(student.customDiscount || 0);
  const payable = Math.max(0, annualFee - concessionAmt);
  const alreadyPaid = Number(ledger[lIdx].paid || 0);

  ledger[lIdx].annualFee = annualFee;
  ledger[lIdx].concession = concessionAmt;
  ledger[lIdx].concessionLabel = concessionLabel;
  ledger[lIdx].payable = payable;
  ledger[lIdx].balance = Math.max(0, payable - alreadyPaid);
  ledger[lIdx].status = ledger[lIdx].balance <= 0 ? 'Paid' : (alreadyPaid > 0 ? 'Partial' : 'Pending');
  ledger[lIdx].feePlan = 'concession';
  saveSchoolFeeLedger(ledger);

  addSchoolLedgerEntry({
    studentId,
    date: new Date().toISOString().split('T')[0],
    transactionType: 'ADJUSTMENT',
    particular: `Concession Approved — Fee Recalculated (${concessionLabel})`,
    debit: 0, credit: 0,
    remarks: 'Concession Approval — bypasses Plan 1/2/3'
  });

  // CM-1.0 — notify the Communication Engine.
  if (window.Dnyanankur && Dnyanankur.Event) {
    Dnyanankur.Event.publish('finance.concession.applied', {
      studentId: studentId, studentName: student.name, className: student.class,
      detail: concessionLabel, amount: concessionAmt
    }, { sourceModule: 'finance' });
  }
}

function renderFeeApprovals() {
  const tbody = document.getElementById('approvals-table-body');
  if (!tbody) return;
  const approvals = getFeeApprovals();
  const students = getStudents();
  const fees = getFees();
  if (!approvals.length) {
    tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;padding:20px;color:#aaa;">No pending approval requests.</td></tr>';
    return;
  }
  tbody.innerHTML = [...approvals].reverse().map(a => {
    const isConcession = a.actionType === 'CONCESSION_GRANT';
    const stu = students.find(s => s.id === (isConcession ? a.studentId : a.oldData?.stuId));
    const dt = new Date(a.requestedAt);
    const statusColors = {PENDING:'badge-yellow', APPROVED:'badge-green', REJECTED:'badge-red'};
    const actionBadgeClass = a.actionType==='DELETE' ? 'badge-red' : a.actionType==='CONCESSION_GRANT' ? 'badge-blue' : 'badge-yellow';
    return `<tr>
      <td style="font-size:12px;">${fmtDMY(dt)}<br/><span style="color:#888;">${dt.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</span></td>
      <td>${a.requestedByName||a.requestedBy}</td>
      <td>${isConcession ? '—' : (a.oldData?.rcpt||'—')}</td>
      <td>${stu ? stu.name + ' (' + stu.cls + ' ' + stu.div + ')' : '—'}</td>
      <td><span class="badge ${actionBadgeClass}" style="font-size:11px;">${isConcession ? 'CONCESSION' : a.actionType}</span></td>
      <td style="font-size:11px;">${isConcession ? (a.oldData?.label||'No Concession') : '₹'+(a.oldData?.paid||0)}</td>
      <td style="font-size:11px;">${isConcession ? (a.newData?.label||'—') : (a.newData ? '₹'+(a.newData.paid||0) : '—')}</td>
      <td><span class="badge ${statusColors[a.status]||'badge-yellow'}" style="font-size:11px;">${a.status}</span></td>
      <td>
        ${a.status === 'PENDING' ? `
        <button class="btn btn-green btn-sm" onclick="approveFeeRequest('${a.id}')">✅ Approve</button>
        <button class="btn btn-red btn-sm" style="margin-left:4px;" onclick="rejectFeeRequest('${a.id}')">❌ Reject</button>
        ` : `<span style="color:#888;font-size:12px;">${a.status}</span>`}
      </td>
    </tr>`;
  }).join('');
}

function approveFeeRequest(approvalId) {
  // Phase 16.4 Task 2 (Security fix): fee approval is a Principal-only
  // action (page-level gate on feeapprovals). Matching internal guard
  // so the function itself can't be invoked directly by a non-principal.
  if (typeof PermissionManager !== 'undefined' && !PermissionManager.hasRole('principal')) {
    alert('⛔ Only the Principal can approve fee requests.');
    return;
  }
  const approvals = getFeeApprovals();
  const a = approvals.find(x => x.id === approvalId);
  if (!a) return;
  if (a.actionType === 'CONCESSION_GRANT') {
    applyApprovedConcession(a.studentId, a.concessionType);
    addAuditEntry('CONCESSION_APPROVED', `Principal approved concession for student ID ${a.studentId}: ${a.newData?.label}`, a.oldData?.label||'', a.newData?.label||'');
    a.status = 'APPROVED';
    a.resolvedAt = new Date().toISOString();
    a.resolvedBy = currentUser.username;
    saveFeeApprovals(approvals);
    showAlert('approval-alert', 'success', '✅ Concession approved — fee recalculated and Plan 1/2/3 bypassed for this student.');
    renderFeeApprovals();
    return;
  }
  const fees = getFees();
  if (a.actionType === 'DELETE') {
    const idx = fees.findIndex(f => f.id === a.feeId);
    if (idx >= 0) fees.splice(idx, 1);
    addAuditEntry('RECEIPT_DELETE_APPROVED', `Principal approved deletion of receipt ${a.oldData?.rcpt}`, JSON.stringify(a.oldData), 'DELETED');
  } else if (a.actionType === 'MODIFY') {
    const idx = fees.findIndex(f => f.id === a.feeId);
    if (idx >= 0) {
      addAuditEntry('RECEIPT_MODIFY_APPROVED', `Principal approved modification of receipt ${a.oldData?.rcpt}`, JSON.stringify(a.oldData), JSON.stringify(a.newData));
      fees[idx] = {...fees[idx], ...a.newData, pendingApproval: null, approvedBy: currentUser.username, approvedAt: new Date().toISOString()};
    }
  }
  saveFees(fees);
  a.status = 'APPROVED';
  a.resolvedAt = new Date().toISOString();
  a.resolvedBy = currentUser.username;
  saveFeeApprovals(approvals);
  showAlert('approval-alert', 'success', '✅ Request approved and action executed.');
  renderFeeApprovals();
}

function rejectFeeRequest(approvalId) {
  // Phase 16.4 Task 2 (Security fix): see approveFeeRequest() above.
  if (typeof PermissionManager !== 'undefined' && !PermissionManager.hasRole('principal')) {
    alert('⛔ Only the Principal can reject fee requests.');
    return;
  }
  const approvals = getFeeApprovals();
  const a = approvals.find(x => x.id === approvalId);
  if (!a) return;
  if (a.actionType === 'CONCESSION_GRANT') {
    const students = getStudents();
    const sIdx = students.findIndex(s => s.id === a.studentId);
    if (sIdx > -1) { students[sIdx].concessionStatus = 'rejected'; students[sIdx].concession = 'none'; saveStudents(students); }
    a.status = 'REJECTED';
    a.resolvedAt = new Date().toISOString();
    a.resolvedBy = currentUser.username;
    saveFeeApprovals(approvals);
    addAuditEntry('CONCESSION_REJECTED', `Principal rejected concession request for student ID ${a.studentId}`, a.newData?.label||'', 'No Concession');
    showAlert('approval-alert', 'success', 'Concession request rejected — student remains on standard Plan 1/2/3 at full fee.');
    renderFeeApprovals();
    return;
  }
  // Remove pending flag from fee
  const fees = getFees();
  const f = fees.find(x => x.id === a.feeId);
  if (f) { f.pendingApproval = null; saveFees(fees); }
  a.status = 'REJECTED';
  a.resolvedAt = new Date().toISOString();
  a.resolvedBy = currentUser.username;
  saveFeeApprovals(approvals);
  addAuditEntry('RECEIPT_REQUEST_REJECTED', `Principal rejected ${a.actionType} request for receipt ${a.oldData?.rcpt}`, '', '');
  showAlert('approval-alert', 'success', 'Request rejected.');
  renderFeeApprovals();
}

// Override deleteFeeReceipt to enforce clerk approval workflow
function deleteFeeReceipt(id) {
  const role = currentUser?.role;
  if (role === 'teacher') { alert('⛔ Teachers cannot delete fee receipts.'); return; }
  if (role === 'clerk') {
    if (!confirm('You cannot delete receipts directly. Submit a deletion request to the Principal?')) return;
    requestFeeAction(id, 'DELETE', null);
    return;
  }
  // Principal can delete directly
  /* H-1 START — SOFT DELETE (item 2): a fee receipt is a financial
     document — it now moves to the Recycle Bin instead of being
     permanently erased, so it can be restored or audited later.
     Underlying ledger entries (school/transport/inventory) created
     when the receipt was collected are NOT auto-reversed here — that
     was already true before this change (deleteFeeReceipt only ever
     removed the `fees` record) and reversing ledgers automatically on
     delete is a business-logic change outside this stability sprint's
     "additive only" scope. Flagged in the Integration Summary. */
  if (!confirm('Move this fee receipt to Recycle Bin?')) return;
  const fees = getFees();
  const f = fees.find(x => x.id === id);
  if(!f){ H1.ui.toast('Receipt not found.', 'error'); return; }
  const reason = prompt('Reason for deletion (optional, shown in Recycle Bin):', '') || 'Not specified';
  H1.recycleBin.moveToBin('financeFeeReceipt', f, reason);
  addAuditEntry('RECEIPT_DELETE', `Principal moved receipt ${f?.rcpt||id} to Recycle Bin`, JSON.stringify(f), 'RECYCLE_BIN');
  saveFees(fees.filter(x => x.id !== id));
  H1.ui.toast(`Receipt ${f?.rcpt||id} moved to Recycle Bin.`, 'warn');
  /* H-1 END */
  renderFeeTable();
}

// ====================== WATERMARK SUPPORT ======================
function getWatermarkSettings() {
  const s = getSettings();
  return {
    text: s.name || 'OFFICIAL DOCUMENT',
    enableLC: s.wmLC !== false,      // default ON
    enableBon: s.wmBon !== false,    // default ON
    enableRC: s.wmRC === true,       // default OFF for report card
  };
}

function applyWatermark(htmlContent, docType) {
  const wm = getWatermarkSettings();
  const s = getSettings();
  let enabled = false;
  if (docType === 'LC') enabled = wm.enableLC;
  if (docType === 'BON') enabled = wm.enableBon;
  if (docType === 'RC') enabled = wm.enableRC;
  if (!enabled) return htmlContent;

  const wmText = s.name ? s.name.toUpperCase() : 'OFFICIAL DOCUMENT';
  const watermark = `
  <div style="position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) rotate(-35deg);
    font-size:52px;font-weight:900;color:rgba(15,34,68,0.07);pointer-events:none;
    white-space:nowrap;z-index:9999;font-family:serif;letter-spacing:4px;
    user-select:none;-webkit-print-color-adjust:exact;print-color-adjust:exact;">
    ${wmText}
  </div>
  <div style="position:fixed;top:30%;left:20%;transform:rotate(-35deg);
    font-size:28px;font-weight:700;color:rgba(15,34,68,0.05);pointer-events:none;
    white-space:nowrap;z-index:9999;font-family:serif;">
    ${wmText}
  </div>
  <div style="position:fixed;top:70%;left:40%;transform:rotate(-35deg);
    font-size:28px;font-weight:700;color:rgba(15,34,68,0.05);pointer-events:none;
    white-space:nowrap;z-index:9999;font-family:serif;">
    ${wmText}
  </div>`;
  return `<div style="position:relative;">${watermark}${htmlContent}</div>`;
}

