// ====================== ACADEMIC YEAR MANAGEMENT ======================
// Data model:
//   academic_years         -> [{id,label,startDate,endDate,status:'upcoming'|'active'|'archived',locked,createdAt,activatedAt,archivedAt}]
//   student_year_history   -> append-only ledger: [{id,studentId,academicYearId,yearLabel,cls,div,roll,result,promotedToClass,promotedToDiv,promotedToRoll,remarks,recordedAt}]
//   academic_year_archives -> { [yearId]: {yearLabel,archivedAt,studentCount,students:[...],marks:{...},fees:[...]} }
//   inactive_students      -> students who Passed Out / Transferred Out (removed from the live roster)
//
// Design notes (see migration doc for full rationale):
//   - Only one academic_years entry may have status 'active' at a time. That entry's label
//     is mirrored into school_settings.acyr so all existing print/report functions keep working untouched.
//   - "Locking" an academic year blocks: saveMarks(), saveCoScholastic(), saveFee(), registerStudent()
//     for as long as that year is the active one. Locking the active year does NOT delete data.
//   - "Archiving" snapshots that year's student roster (from student_year_history), marks/co-scholastic
//     entries (from the shared `marks` store, filtered to that year's student IDs) and fee receipts,
//     then marks the year archived + locked. Always archive AFTER all marks/attendance entry for that
//     year is complete — see migration doc.

const CLASS_ORDER = ['Nursery','Jr.KG','Sr.KG','1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th','11th','12th'];

function nextClassInOrder(cls) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.nextClassInOrder().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.nextClassInOrder(cls);
  }
  const idx = CLASS_ORDER.indexOf(cls);
  if (idx === -1 || idx === CLASS_ORDER.length - 1) return null; // null => terminal class, candidate for "Pass Out"
  return CLASS_ORDER[idx + 1];
}

function getAcademicYears() {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.getAcademicYears().
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.getAcademicYears();
  }
  return LS.get('academic_years') || [];
}
function saveAcademicYearsList(list) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.saveAcademicYearsList().
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.saveAcademicYearsList(list);
  }
  LS.set('academic_years', list);
}

function getYearArchives() {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.getYearArchives().
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.getYearArchives();
  }
  return LS.get('academic_year_archives') || {};
}
function saveYearArchives(obj) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.saveYearArchives().
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.saveYearArchives(obj);
  }
  LS.set('academic_year_archives', obj);
}

function getStudentYearHistory() { return (window.Dnyanankur && Dnyanankur.StudentService) ? Dnyanankur.StudentService.getStudentYearHistory() : (LS.get('student_year_history') || []); }
function saveStudentYearHistory(list) { if (window.Dnyanankur && Dnyanankur.StudentService) { Dnyanankur.StudentService.saveStudentYearHistory(list); } else { LS.set('student_year_history', list); } }

function getInactiveStudents() { return (window.Dnyanankur && Dnyanankur.StudentService) ? Dnyanankur.StudentService.getInactiveStudents() : (LS.get('inactive_students') || []); }
function saveInactiveStudents(list) { if (window.Dnyanankur && Dnyanankur.StudentService) { Dnyanankur.StudentService.saveInactiveStudents(list); } else { LS.set('inactive_students', list); } }

function getActiveYear() {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.getActiveYear().
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.getActiveYear();
  }
  return getAcademicYears().find(y => y.status === 'active') || null;
}

function isActiveYearLocked() {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.isActiveYearLocked().
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.isActiveYearLocked();
  }
  const y = getActiveYear();
  return y ? !!y.locked : false;
}

// One-time, idempotent migration of the existing flat (single-year) data
// into the new multi-year model. See "Migration Strategy" document for details.
function ensureAcademicYearSystem() {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.ensureAcademicYearSystem().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.ensureAcademicYearSystem();
  }
  if (LS.get('ay_migration_v1_done')) return;

  let years = getAcademicYears();
  if (!years || years.length === 0) {
    const settings = getSettings();
    const label = settings.acyr || '2026-27';
    const initialYear = {
      id: 'AY_' + Date.now(),
      label: label,
      startDate: settings.t1start || '',
      endDate: settings.t2end || '',
      status: 'active',
      locked: false,
      createdAt: new Date().toISOString(),
      activatedAt: new Date().toISOString(),
      archivedAt: null,
      migratedFromLegacyData: true,
    };
    years = [initialYear];
    saveAcademicYearsList(years);

    // Tag every existing student with the active year if they don't already carry one,
    // and seed a history row so this year can later be archived/promoted from correctly.
    const students = getStudents();
    const history = getStudentYearHistory();
    students.forEach(s => {
      if (!s.acyr) s.acyr = label;
      history.push({
        id: 'AYH_' + s.id + '_' + initialYear.id,
        studentId: s.id,
        academicYearId: initialYear.id,
        yearLabel: label,
        cls: s.cls, div: s.div, roll: s.roll,
        result: 'Active',
        promotedToClass: null, promotedToDiv: null, promotedToRoll: null,
        remarks: 'Auto-recorded during Academic Year module migration.',
        recordedAt: new Date().toISOString(),
      });
    });
    saveStudents(students);
    saveStudentYearHistory(history);
  }

  LS.set('ay_migration_v1_done', true);
}

function getNextSuggestedLabel() {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.getNextSuggestedLabel().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.getNextSuggestedLabel();
  }
  const years = getAcademicYears();
  let maxStart = null;
  years.forEach(y => {
    const m = /^(\d{4})-(\d{2})$/.exec((y.label || '').trim());
    if (m) { const startYr = parseInt(m[1], 10); if (maxStart === null || startYr > maxStart) maxStart = startYr; }
  });
  if (maxStart === null) {
    const settings = getSettings();
    const m = /^(\d{4})-(\d{2})$/.exec((settings.acyr || '').trim());
    maxStart = m ? parseInt(m[1], 10) : new Date().getFullYear();
  }
  const next = maxStart + 1;
  return `${next}-${String((next + 1) % 100).padStart(2, '0')}`;
}

// ---------------------- CRUD ----------------------
// ── TERM DATES (added per "Term 1/Term 2 dates belong in Academic Year
// Management, connected everywhere") ─────────────────────────────────────
// Term 1 Start/End are set explicitly by the Principal. Term 2 is always
// derived, never entered separately: Term 2 Start = the day immediately
// after Term 1 End (so no single date is ever double-counted in both
// terms' attendance totals), and Term 2 End = the Academic Year's own End
// Date. This is the ONLY place term dates are computed — AttEngine-driven
// Report Card attendance (attendanceCellForTerm / activeYearRangeForReportCard
// in buildReportCard/buildSemester1ReportCard) reads term1Start/term1End/
// term2Start/term2End straight off the active academic year object below,
// so Attendance, Report Cards and everywhere else that needs a Term range
// all agree with what's set here.
function ayAddDays(dateStr, days) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.ayAddDays().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.ayAddDays(dateStr, days);
  }
  if (!dateStr) return '';
  const d = new Date(dateStr + 'T00:00:00');
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}
function ayComputeTermDates(term1Start, term1End, ayEndDate) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.ayComputeTermDates().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.ayComputeTermDates(term1Start, term1End, ayEndDate);
  }
  return {
    term1Start: term1Start || '',
    term1End: term1End || '',
    term2Start: term1End ? ayAddDays(term1End, 1) : '',
    term2End: ayEndDate || '',
  };
}

function createAcademicYear(label, startDate, endDate, term1Start, term1End) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.createAcademicYear().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.createAcademicYear(label, startDate, endDate, term1Start, term1End);
  }
  label = (label || '').trim();
  if (!label) return { ok: false, msg: 'Please enter an academic year label, e.g. 2027-28.' };
  const years = getAcademicYears();
  if (years.some(y => y.label.toLowerCase() === label.toLowerCase())) {
    return { ok: false, msg: `Academic year "${label}" already exists.` };
  }
  const isFirstEver = years.length === 0;
  const terms = ayComputeTermDates(term1Start, term1End, endDate);
  const year = {
    id: 'AY_' + Date.now(),
    label, startDate: startDate || '', endDate: endDate || '',
    term1Start: terms.term1Start, term1End: terms.term1End,
    term2Start: terms.term2Start, term2End: terms.term2End,
    status: isFirstEver ? 'active' : 'upcoming',
    locked: false,
    createdAt: new Date().toISOString(),
    activatedAt: isFirstEver ? new Date().toISOString() : null,
    archivedAt: null,
  };
  years.push(year);
  saveAcademicYearsList(years);
  if (isFirstEver) {
    const settings = getSettings();
    settings.acyr = label;
    LS.set('school_settings', settings);
  }
  addAuditEntry('ACADEMIC_YEAR_CREATE', `Created academic year ${label}`, '', label);
  // Keep Examination Center year mirror in sync
  if (typeof examSyncAcademicYearsFromERP === 'function') examSyncAcademicYearsFromERP();
  return { ok: true, year };
}

// Edits an EXISTING academic year's Start/End/Term 1 dates (Term 2 is
// re-derived automatically as above). This is what lets a school add or
// fix term dates on a year that was already created before this feature
// existed, without having to delete and recreate it.
function updateAcademicYearDates(yearId, startDate, endDate, term1Start, term1End) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.updateAcademicYearDates().
  // This wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.updateAcademicYearDates(yearId, startDate, endDate, term1Start, term1End);
  }
  const years = getAcademicYears();
  const year = years.find(y => y.id === yearId);
  if (!year) return { ok: false, msg: 'Academic year not found.' };
  if (year.locked) return { ok: false, msg: 'This academic year is locked. Unlock it first to edit its dates.' };
  const terms = ayComputeTermDates(term1Start, term1End, endDate);
  year.startDate = startDate || '';
  year.endDate = endDate || '';
  year.term1Start = terms.term1Start; year.term1End = terms.term1End;
  year.term2Start = terms.term2Start; year.term2End = terms.term2End;
  saveAcademicYearsList(years);
  addAuditEntry('ACADEMIC_YEAR_DATES_UPDATE', `Updated dates for academic year ${year.label}`, '', '');
  if (typeof examSyncAcademicYearsFromERP === 'function') examSyncAcademicYearsFromERP();
  return { ok: true, year };
}

function setActiveAcademicYear(yearId) {
  const years = getAcademicYears();
  const target = years.find(y => y.id === yearId);
  if (!target) return { ok: false, msg: 'Academic year not found.' };
  if (target.status === 'active') return { ok: true, year: target };

  if (target.status === 'archived') {
    if (!confirm(`"${target.label}" is archived. Re-activating it will allow new edits again. Continue?`)) {
      return { ok: false, msg: 'Cancelled.' };
    }
  }

  const prevActive = years.find(y => y.status === 'active');
  years.forEach(y => { if (y.status === 'active') y.status = 'upcoming'; });
  target.status = 'active';
  target.activatedAt = new Date().toISOString();
  target.locked = false;
  saveAcademicYearsList(years);

  const settings = getSettings();
  settings.acyr = target.label;
  LS.set('school_settings', settings);

  addAuditEntry('ACADEMIC_YEAR_ACTIVATE', `Set academic year ${target.label} as Active${prevActive ? ' (was ' + prevActive.label + ')' : ''}`, prevActive ? prevActive.label : '', target.label);
  // Keep Examination Center year mirror in sync automatically
  if (typeof examSyncAcademicYearsFromERP === 'function') examSyncAcademicYearsFromERP();
  return { ok: true, year: target };
}

function toggleLockYear(yearId) {
  const years = getAcademicYears();
  const year = years.find(y => y.id === yearId);
  if (!year) return;
  const newState = !year.locked;
  if (newState) {
    if (!confirm(`Lock academic year "${year.label}"?\n\nWhile locked, no new marks, attendance/co-scholastic entries, fee receipts, or admissions can be recorded for this year.`)) return;
  } else {
    if (!confirm(`Unlock academic year "${year.label}"? This will allow edits again.`)) return;
  }
  year.locked = newState;
  saveAcademicYearsList(years);
  addAuditEntry(newState ? 'ACADEMIC_YEAR_LOCK' : 'ACADEMIC_YEAR_UNLOCK', `${newState ? 'Locked' : 'Unlocked'} academic year ${year.label}`, '', '');
  renderAcademicYearsPage();
}

function deleteAcademicYear(yearId) {
  const years = getAcademicYears();
  const year = years.find(y => y.id === yearId);
  if (!year) return;
  if (year.status !== 'upcoming') {
    alert('Only an "Upcoming" academic year (one that has not started yet) can be deleted.');
    return;
  }
  const hasHistory = getStudentYearHistory().some(h => h.academicYearId === yearId);
  if (hasHistory) {
    alert('This academic year already has student records linked to it and cannot be deleted.');
    return;
  }
  if (!confirm(`Delete the upcoming academic year "${year.label}"? This cannot be undone.`)) return;
  saveAcademicYearsList(years.filter(y => y.id !== yearId));
  addAuditEntry('ACADEMIC_YEAR_DELETE', `Deleted unused academic year ${year.label}`, year.label, '');
  renderAcademicYearsPage();
}

// ---------------------- ARCHIVING ----------------------
function studentIdsForYear(year) {
  // [PHASE-23] Logic moved to Dnyanankur.Services.Academic.studentIdsForYear().
  // This wrapper delegates when the service is installed; original
  // implementation below (including its own pre-existing StudentService
  // delegation) is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Academic) {
    return Dnyanankur.Services.Academic.studentIdsForYear(year);
  }
  if (window.Dnyanankur && Dnyanankur.StudentService) {
    return Dnyanankur.StudentService.studentIdsForYear(year);
  }
  const fromHistory = getStudentYearHistory().filter(h => h.academicYearId === year.id).map(h => h.studentId);
  if (fromHistory.length) return [...new Set(fromHistory)];
  // Fallback (e.g. freshly migrated year with no wizard run yet): use students currently tagged to this year label.
  return getStudents().filter(s => s.acyr === year.label).map(s => s.id);
}

function archiveAcademicYear(yearId, opts) {
  opts = opts || {};
  const years = getAcademicYears();
  const year = years.find(y => y.id === yearId);
  if (!year) return { ok: false, msg: 'Academic year not found.' };
  if (year.status === 'archived') return { ok: true, year };

  if (year.status === 'active' && !opts.silent) {
    if (!confirm(`"${year.label}" is still the Active academic year. It is recommended to run the Student Promotion Wizard (or set another year Active) before archiving.\n\nArchive it anyway?`)) {
      return { ok: false, msg: 'Cancelled.' };
    }
  }

  const studentIds = studentIdsForYear(year);
  const history = getStudentYearHistory().filter(h => h.academicYearId === year.id);
  const liveStudents = getStudents();
  const inactiveStudents = getInactiveStudents();

  const studentsSnapshot = studentIds.map(sid => {
    const histRow = history.find(h => h.studentId === sid) || {};
    const full = liveStudents.find(s => s.id === sid) || inactiveStudents.find(s => s.id === sid) || {};
    return {
      studentId: sid,
      name: full.name || '',
      cls: histRow.cls || full.cls,
      div: histRow.div || full.div,
      roll: histRow.roll || full.roll,
      result: histRow.result || 'Active',
      promotedToClass: histRow.promotedToClass || null,
      promotedToDiv: histRow.promotedToDiv || null,
      promotedToRoll: histRow.promotedToRoll || null,
      remarks: histRow.remarks || '',
      fatherName: full.fatherName || '',
      admno: full.admno || '',
    };
  });

  const allMarks = getMarks();
  const marksSnapshot = {};
  Object.keys(allMarks).forEach(key => {
    const sid = key.split('_')[0];
    if (studentIds.includes(sid)) marksSnapshot[key] = allMarks[key];
  });

  const feesSnapshot = getFees().filter(f => studentIds.includes(f.stuId));

  const archives = getYearArchives();
  archives[yearId] = {
    yearLabel: year.label,
    archivedAt: new Date().toISOString(),
    studentCount: studentIds.length,
    students: studentsSnapshot,
    marks: marksSnapshot,
    fees: feesSnapshot,
  };
  saveYearArchives(archives);

  year.status = 'archived';
  year.archivedAt = new Date().toISOString();
  year.locked = true;
  saveAcademicYearsList(years);

  addAuditEntry('ACADEMIC_YEAR_ARCHIVE', `Archived academic year ${year.label}: ${studentIds.length} student record(s), ${Object.keys(marksSnapshot).length} mark/attendance entries, ${feesSnapshot.length} fee receipts captured.`, '', '');
  return { ok: true, year, studentCount: studentIds.length, markCount: Object.keys(marksSnapshot).length };
}

// ---------------------- PAGE RENDERING ----------------------
function ayStatusBadge(year) {
  if (year.status === 'active') return `<span class="badge badge-green">● Active</span>`;
  if (year.status === 'archived') return `<span class="badge badge-blue">📦 Archived</span>`;
  return `<span class="badge badge-yellow">Upcoming</span>`;
}

function renderAcademicYearsPage() {
  ensureAcademicYearSystem();
  const years = getAcademicYears().slice().sort((a, b) => a.label.localeCompare(b.label));
  const active = getActiveYear();
  const history = getStudentYearHistory();
  const archives = getYearArchives();

  document.getElementById('ay-active-label').textContent = active ? active.label : '— none set —';
  document.getElementById('ay-active-status').innerHTML = active ? (active.locked ? '<span class="badge badge-red">🔒 Locked</span>' : '<span class="badge badge-green">🔓 Open for entry</span>') : '—';
  document.getElementById('ay-active-count').textContent = active ? getStudents().filter(s => s.acyr === active.label).length : '0';
  document.getElementById('ay-total-count').textContent = years.length;

  const tbody = document.getElementById('ay-table-body');
  tbody.innerHTML = years.map(y => {
    const studentsRecorded = new Set(history.filter(h => h.academicYearId === y.id).map(h => h.studentId)).size
      || getStudents().filter(s => s.acyr === y.label).length;
    const actions = [];
    actions.push(`<button class="btn" style="font-size:11px;padding:4px 8px;" onclick="openEditYearModal('${y.id}')">✏️ Edit Dates</button>`);
    if (y.status !== 'active') actions.push(`<button class="btn" style="font-size:11px;padding:4px 8px;" onclick="setActiveAcademicYear('${y.id}'); renderAcademicYearsPage();">Set Active</button>`);
    if (y.status !== 'archived') actions.push(`<button class="btn" style="font-size:11px;padding:4px 8px;" onclick="toggleLockYear('${y.id}')">${y.locked ? 'Unlock' : 'Lock'}</button>`);
    if (y.status !== 'archived') actions.push(`<button class="btn" style="font-size:11px;padding:4px 8px;background:#fdecea;color:#c0392b;" onclick="if(confirm('Archive academic year ${y.label}? Make sure all marks and attendance entry for this year is complete first.')){ const r=archiveAcademicYear('${y.id}'); if(r.ok){ alert('✅ Archived '+r.year.label+'. '+r.studentCount+' student record(s) and '+r.markCount+' mark/attendance entries captured.'); } renderAcademicYearsPage(); }">Archive</button>`);
    if (y.status === 'upcoming' && studentsRecorded === 0) actions.push(`<button class="btn" style="font-size:11px;padding:4px 8px;background:#f5f5f5;color:#888;" onclick="deleteAcademicYear('${y.id}')">Delete</button>`);
    return `<tr>
      <td><b>${y.label}</b></td>
      <td>${y.startDate || '—'}</td>
      <td>${y.endDate || '—'}</td>
      <td style="font-size:11.5px;">${y.term1Start && y.term1End ? (y.term1Start + ' → ' + y.term1End) : '<span style="color:#c0392b;">Not set</span>'}</td>
      <td style="font-size:11.5px;">${y.term2Start && y.term2End ? (y.term2Start + ' → ' + y.term2End) : '<span style="color:#c0392b;">Not set</span>'}</td>
      <td>${ayStatusBadge(y)}</td>
      <td>${y.locked ? '<span class="badge badge-red">🔒 Locked</span>' : '<span class="badge badge-green">Open</span>'}</td>
      <td>${studentsRecorded}</td>
      <td><div style="display:flex;gap:6px;flex-wrap:wrap;">${actions.join('')}</div></td>
    </tr>`;
  }).join('') || `<tr><td colspan="9" style="text-align:center;color:#888;">No academic years yet. Click "+ Create Academic Year" to begin.</td></tr>`;

  const archiveBody = document.getElementById('ay-archive-table-body');
  const archivedYears = years.filter(y => y.status === 'archived');
  archiveBody.innerHTML = archivedYears.map(y => {
    const snap = archives[y.id];
    if (!snap) return '';
    return `<tr>
      <td><b>${y.label}</b></td>
      <td>${fmtDMY(snap.archivedAt)}</td>
      <td>${snap.studentCount}</td>
      <td>${Object.keys(snap.marks || {}).length}</td>
      <td><button class="btn" style="font-size:11px;padding:4px 8px;" onclick="viewArchive('${y.id}')">View</button></td>
    </tr>`;
  }).join('') || `<tr><td colspan="5" style="text-align:center;color:#888;">No archived academic years yet.</td></tr>`;

  // Finance summary for active year
  try {
    const students = getStudents();
    const sfl = getSchoolFeeLedger();
    const tfl = getTransportFeeLedger();
    const routes = getTransportMaster();
    const totalCollected = sfl.reduce((s,r) => s + Number(r.paid||0), 0) + tfl.reduce((s,r) => s + Number(r.paid||0), 0);
    const totalPending = sfl.reduce((s,r) => s + Number(r.balance||0), 0) + tfl.reduce((s,r) => s + Number(r.balance||0), 0);
    const ayFinStudents = document.getElementById('ay-fin-students');
    const ayFinCollected = document.getElementById('ay-fin-collected');
    const ayFinPending = document.getElementById('ay-fin-pending');
    const ayFinRoutes = document.getElementById('ay-fin-routes');
    if (ayFinStudents) ayFinStudents.textContent = students.length;
    if (ayFinCollected) ayFinCollected.textContent = '₹' + totalCollected.toLocaleString('en-IN');
    if (ayFinPending) ayFinPending.textContent = '₹' + totalPending.toLocaleString('en-IN');
    if (ayFinRoutes) ayFinRoutes.textContent = routes.length;
  } catch(e) {}
}

// Module-level: null while creating a brand-new year, set to a year id
// while editing an existing year's dates (see openEditYearModal below).
let _ayEditingYearId = null;

function ayRecalcTermPreview() {
  const t1end = document.getElementById('ny-t1end').value;
  const ayEnd = document.getElementById('ny-end').value;
  const t2start = t1end ? ayAddDays(t1end, 1) : '';
  document.getElementById('ny-t2start-preview').textContent = t2start || '—';
  document.getElementById('ny-t2end-preview').textContent = ayEnd || '—';
}

function openCreateYearModal() {
  _ayEditingYearId = null;
  document.getElementById('ny-modal-title').textContent = 'Create Academic Year';
  document.getElementById('ny-submit-btn').textContent = 'Create Academic Year';
  document.getElementById('ny-label').disabled = false;
  document.getElementById('ny-label').value = getNextSuggestedLabel();
  document.getElementById('ny-start').value = '';
  document.getElementById('ny-end').value = '';
  document.getElementById('ny-t1start').value = '';
  document.getElementById('ny-t1end').value = '';
  document.getElementById('ny-msg').innerHTML = '';
  ayRecalcTermPreview();
  openModal('modal-create-year');
}

// Opens the same modal pre-filled with an EXISTING year's dates so Term 1/
// Term 2 (or Start/End) can be added or corrected after the year was
// already created — this is what makes term dates editable everywhere,
// not just at creation time.
function openEditYearModal(yearId) {
  const year = getAcademicYears().find(y => y.id === yearId);
  if (!year) return;
  if (year.locked) { alert('🔒 "' + year.label + '" is locked. Unlock it first (Academic Years → Lock/Unlock) to edit its dates.'); return; }
  _ayEditingYearId = yearId;
  document.getElementById('ny-modal-title').textContent = 'Edit Dates — ' + year.label;
  document.getElementById('ny-submit-btn').textContent = 'Save Dates';
  document.getElementById('ny-label').disabled = true;
  document.getElementById('ny-label').value = year.label;
  document.getElementById('ny-start').value = year.startDate || '';
  document.getElementById('ny-end').value = year.endDate || '';
  document.getElementById('ny-t1start').value = year.term1Start || '';
  document.getElementById('ny-t1end').value = year.term1End || '';
  document.getElementById('ny-msg').innerHTML = '';
  ayRecalcTermPreview();
  openModal('modal-create-year');
}

function submitCreateYear() {
  const label = document.getElementById('ny-label').value.trim();
  const start = document.getElementById('ny-start').value;
  const end = document.getElementById('ny-end').value;
  const t1start = document.getElementById('ny-t1start').value;
  const t1end = document.getElementById('ny-t1end').value;

  if (t1end && end && t1end > end) {
    document.getElementById('ny-msg').innerHTML = `<span class="alert alert-error" style="display:inline-block;">Term 1 End Date can't be after the Academic Year's End Date.</span>`;
    return;
  }
  if (t1start && start && t1start < start) {
    document.getElementById('ny-msg').innerHTML = `<span class="alert alert-error" style="display:inline-block;">Term 1 Start Date can't be before the Academic Year's Start Date.</span>`;
    return;
  }

  const result = _ayEditingYearId
    ? updateAcademicYearDates(_ayEditingYearId, start, end, t1start, t1end)
    : createAcademicYear(label, start, end, t1start, t1end);

  if (!result.ok) {
    document.getElementById('ny-msg').innerHTML = `<span class="alert alert-error" style="display:inline-block;">${result.msg}</span>`;
    return;
  }
  _ayEditingYearId = null;
  closeModal('modal-create-year');
  renderAcademicYearsPage();
}


function viewArchive(yearId) {
  const archives = getYearArchives();
  const snap = archives[yearId];
  const years = getAcademicYears();
  const year = years.find(y => y.id === yearId);
  if (!snap || !year) return;

  document.getElementById('archive-modal-title').textContent = `Archived Records — ${year.label}`;

  const resultCounts = {};
  snap.students.forEach(s => { resultCounts[s.result] = (resultCounts[s.result] || 0) + 1; });
  const summaryChips = Object.entries(resultCounts).map(([k, v]) => `<span class="badge badge-blue" style="margin-right:6px;">${k}: ${v}</span>`).join('');

  const rows = snap.students.sort((a, b) => (a.cls + a.div + String(a.roll).padStart(3, '0')).localeCompare(b.cls + b.div + String(b.roll).padStart(3, '0')))
    .map(s => `<tr>
      <td>${s.roll}</td>
      <td>${s.name}</td>
      <td>${s.cls} ${s.div}</td>
      <td>${s.result}</td>
      <td>${s.promotedToClass ? `${s.promotedToClass} ${s.promotedToDiv || ''}` : '—'}</td>
    </tr>`).join('');

  document.getElementById('archive-modal-content').innerHTML = `
    <p style="font-size:13px;color:#666;">Archived on ${new Date(snap.archivedAt).toLocaleString('en-IN')} · ${snap.studentCount} student record(s) · ${Object.keys(snap.marks || {}).length} mark/attendance entries · ${snap.fees.length} fee receipts referenced.</p>
    <div style="margin:10px 0;">${summaryChips}</div>
    <table>
      <thead><tr><th>Roll</th><th>Name</th><th>Class/Div (that year)</th><th>Result</th><th>Promoted To</th></tr></thead>
      <tbody>${rows || '<tr><td colspan="5" style="text-align:center;color:#888;">No student records captured.</td></tr>'}</tbody>
    </table>
    <button class="btn" style="margin-top:14px;" onclick='downloadArchiveJSON("${yearId}")'>⬇ Export Archive as JSON</button>
  `;
  openModal('modal-view-archive');
}

function downloadArchiveJSON(yearId) {
  const archives = getYearArchives();
  const snap = archives[yearId];
  if (!snap) return;
  const json = JSON.stringify(snap, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `Archive_${snap.yearLabel}_${new Date().toISOString().split('T')[0]}.json`;
  a.click();
  URL.revokeObjectURL(url);
}

// ---------------------- STUDENT PROMOTION WIZARD ----------------------
let promoWizardRows = [];

function openPromotionWizard() {
  if (!PermissionManager.hasRole('principal')) {
    alert('⛔ Only the Principal can perform this action.');
    return;
  }
  ensureAcademicYearSystem();
  const source = getActiveYear();
  if (!source) { alert('No active academic year is set. Create one first under Academic Years.'); return; }

  const years = getAcademicYears();
  const targets = years.filter(y => y.status === 'upcoming');
  if (targets.length === 0) {
    if (confirm(`No upcoming academic year exists to promote students into yet.\n\nCreate "${getNextSuggestedLabel()}" now?`)) {
      const r = createAcademicYear(getNextSuggestedLabel(), '', '');
      if (!r.ok) { alert(r.msg); return; }
    } else {
      return;
    }
  }
  const targetOptions = getAcademicYears().filter(y => y.status === 'upcoming');

  const students = getStudents().slice().sort((a, b) =>
    (CLASS_ORDER.indexOf(a.cls) - CLASS_ORDER.indexOf(b.cls)) || String(a.div).localeCompare(String(b.div)) || (Number(a.roll) - Number(b.roll))
  );

  promoWizardRows = students.map(s => {
    const nextCls = nextClassInOrder(s.cls);
    return {
      studentId: s.id, name: s.name, cls: s.cls, div: s.div, roll: s.roll,
      include: true,
      decision: nextCls ? 'Promote' : 'PassOut',
      newCls: nextCls || s.cls,
      newDiv: s.div,
      newRoll: s.roll,
    };
  });

  const classFilterOptions = ['All', ...new Set(students.map(s => s.cls))];

  document.getElementById('promo-wizard-body').innerHTML = `
    <div style="background:#f0f7ff;border:1px solid #c3dafb;border-radius:8px;padding:12px;margin-bottom:14px;font-size:13px;">
      Promoting from <b>${source.label}</b> (current Active year) into
      <select id="promo-target-year" style="padding:4px 8px;border-radius:6px;border:1px solid #ccc;">
        ${targetOptions.map(y => `<option value="${y.id}">${y.label}</option>`).join('')}
      </select>.
      This will record each student's result for ${source.label}, update their class/division/roll for the new year, and archive ${source.label}'s records once you confirm.
    </div>
    <div style="display:flex;gap:10px;align-items:center;margin-bottom:10px;flex-wrap:wrap;">
      <label style="font-size:12.5px;">Filter by class:
        <select id="promo-class-filter" onchange="renderPromoTable()" style="padding:4px 8px;border-radius:6px;border:1px solid #ccc;margin-left:6px;">
          ${classFilterOptions.map(c => `<option value="${c}">${c}</option>`).join('')}
        </select>
      </label>
      <button class="btn" style="font-size:12px;padding:5px 10px;" onclick="bulkSetPromoDecision('Promote')">Set visible rows → Promote</button>
      <button class="btn" style="font-size:12px;padding:5px 10px;" onclick="bulkSetPromoDecision('Retain')">Set visible rows → Retain</button>
      <button class="btn" style="font-size:12px;padding:5px 10px;" onclick="bulkSetPromoDecision('PassOut')">Set visible rows → Pass Out</button>
    </div>
    <div style="max-height:50vh;overflow-y:auto;border:1px solid #eee;border-radius:8px;">
      <table style="margin:0;">
        <thead style="position:sticky;top:0;background:#fff;">
          <tr><th>✓</th><th>Roll</th><th>Name</th><th>Current Class/Div</th><th>Decision</th><th>New Class</th><th>New Div</th><th>New Roll</th></tr>
        </thead>
        <tbody id="promo-table-body"></tbody>
      </table>
    </div>
    <div style="margin-top:16px;display:flex;justify-content:flex-end;gap:10px;">
      <button class="btn" onclick="closeModal('modal-promotion-wizard')">Cancel</button>
      <button class="btn btn-primary" onclick="confirmRunPromotion()">Run Promotion &amp; Archive ${source.label}</button>
    </div>
    <div id="promo-msg" style="margin-top:10px;"></div>
  `;
  renderPromoTable();
  openModal('modal-promotion-wizard');
}

function renderPromoTable() {
  const filter = document.getElementById('promo-class-filter') ? document.getElementById('promo-class-filter').value : 'All';
  const tbody = document.getElementById('promo-table-body');
  const divOptions = ['A', 'B', 'C', 'D'];
  tbody.innerHTML = promoWizardRows.map((r, idx) => {
    if (filter !== 'All' && r.cls !== filter) return '';
    return `<tr data-idx="${idx}">
      <td><input type="checkbox" ${r.include ? 'checked' : ''} onchange="promoWizardRows[${idx}].include=this.checked"/></td>
      <td>${r.roll}</td>
      <td>${r.name}</td>
      <td>${r.cls} ${r.div}</td>
      <td>
        <select onchange="onPromoDecisionChange(${idx}, this.value)" style="padding:3px;border:1px solid #ddd;border-radius:4px;font-size:12px;">
          ${['Promote', 'Retain', 'PassOut', 'TransferOut'].map(d => `<option value="${d}" ${r.decision === d ? 'selected' : ''}>${d === 'PassOut' ? 'Pass Out' : d === 'TransferOut' ? 'Transfer Out' : d}</option>`).join('')}
        </select>
      </td>
      <td><input type="text" value="${r.newCls}" ${r.decision === 'Promote' ? '' : 'disabled'} onchange="promoWizardRows[${idx}].newCls=this.value" style="width:70px;padding:3px;border:1px solid #ddd;border-radius:4px;font-size:12px;"/></td>
      <td>
        <select onchange="promoWizardRows[${idx}].newDiv=this.value" ${(r.decision === 'PassOut' || r.decision === 'TransferOut') ? 'disabled' : ''} style="padding:3px;border:1px solid #ddd;border-radius:4px;font-size:12px;">
          ${divOptions.map(d => `<option ${r.newDiv === d ? 'selected' : ''}>${d}</option>`).join('')}
        </select>
      </td>
      <td><input type="number" value="${r.newRoll}" ${(r.decision === 'PassOut' || r.decision === 'TransferOut') ? 'disabled' : ''} onchange="promoWizardRows[${idx}].newRoll=this.value" style="width:60px;padding:3px;border:1px solid #ddd;border-radius:4px;font-size:12px;"/></td>
    </tr>`;
  }).join('');
}

function onPromoDecisionChange(idx, value) {
  promoWizardRows[idx].decision = value;
  if (value !== 'Promote') promoWizardRows[idx].newCls = promoWizardRows[idx].cls;
  renderPromoTable();
}

function bulkSetPromoDecision(decision) {
  const filter = document.getElementById('promo-class-filter').value;
  promoWizardRows.forEach(r => {
    if (filter !== 'All' && r.cls !== filter) return;
    r.decision = decision;
    if (decision === 'Promote') r.newCls = nextClassInOrder(r.cls) || r.cls;
    else r.newCls = r.cls;
  });
  renderPromoTable();
}

function confirmRunPromotion() {
  if (!PermissionManager.hasRole('principal')) {
    alert('⛔ Only the Principal can perform this action.');
    return;
  }
  const targetYearId = document.getElementById('promo-target-year').value;
  const included = promoWizardRows.filter(r => r.include);
  if (included.length === 0) { alert('No students selected.'); return; }
  if (!confirm(`Run promotion for ${included.length} student(s)?\n\nThis will:\n• Record their result for the current academic year\n• Update class/division/roll where promoted\n• Move "Pass Out" / "Transfer Out" students off the active roster\n• Archive the current academic year's marks & attendance\n• Activate the new academic year\n\nThis action cannot be easily undone — consider exporting a backup first.`)) return;

  const result = runPromotion(targetYearId, included);
  document.getElementById('promo-msg').innerHTML = `<span class="alert alert-success" style="display:inline-block;">✓ Promoted: ${result.promoted} · Retained: ${result.retained} · Passed Out: ${result.passedOut} · Transferred Out: ${result.transferredOut}</span>`;
  setTimeout(() => { closeModal('modal-promotion-wizard'); renderAcademicYearsPage(); }, 1800);
}

function runPromotion(targetYearId, rows) {
  if (!PermissionManager.hasRole('principal')) {
    alert('⛔ Only the Principal can perform this action.');
    return;
  }
  const years = getAcademicYears();
  const sourceYear = getActiveYear();
  const targetYear = years.find(y => y.id === targetYearId);
  const students = getStudents();
  const inactive = getInactiveStudents();
  const history = getStudentYearHistory();

  // EXAM-3.1A-3: promotion flag gate (advisory-only — see compatibility
  // report). AcademicEngine.Promotion.compute() (EXAM-2.6B-3) is documented
  // as a pure, read-only wrapper — "No localStorage / examStore /
  // examMod_results writes. No console output. No DOM/UI. No other side
  // effects" — and AcademicEngine.Promotion.computeStudent (EXAM-2.6B-1)
  // states its own design intent explicitly: "runPromotion() (Core ERP) —
  // never called, never touched." Its (classResult, promotionConfig)
  // input/output shape (eligible/reasons per student) carries no
  // class/division/roll movement or Pass-Out/Transfer-Out decision — that
  // data lives only in the wizard's `rows` argument. So this gate invokes
  // compute() for its return value only when the flag is true; it never
  // reassigns rows/students/history or branches the code below. Every
  // write that follows is the unconditional, unmodified legacy path,
  // identical for both flag states — no storage schema or behavior change.
  if (typeof AcademicEngine !== 'undefined' && AcademicEngine &&
      AcademicEngine.Flags && typeof AcademicEngine.Flags.get === 'function' &&
      AcademicEngine.Flags.get().useAcademicPromotion === true &&
      AcademicEngine.Promotion && typeof AcademicEngine.Promotion.compute === 'function') {
    try { AcademicEngine.Promotion.compute(null, null); } catch (e) { /* advisory only — never affects the promotion below */ }
  }

  let promoted = 0, retained = 0, passedOut = 0, transferredOut = 0;

  rows.forEach(r => {
    const student = students.find(s => s.id === r.studentId);
    if (!student) return;

    history.push({
      id: 'AYH_' + r.studentId + '_' + sourceYear.id,
      studentId: r.studentId,
      academicYearId: sourceYear.id,
      yearLabel: sourceYear.label,
      cls: r.cls, div: r.div, roll: r.roll,
      result: r.decision === 'PassOut' ? 'PassedOut' : r.decision === 'TransferOut' ? 'TransferredOut' : r.decision,
      promotedToClass: r.decision === 'Promote' ? r.newCls : null,
      promotedToDiv: r.decision === 'Promote' ? r.newDiv : null,
      promotedToRoll: r.decision === 'Promote' ? r.newRoll : null,
      remarks: '',
      recordedAt: new Date().toISOString(),
    });

    if (r.decision === 'Promote') {
      student.cls = r.newCls; student.div = r.newDiv; student.roll = parseInt(r.newRoll) || r.newRoll;
      student.acyr = targetYear.label;
      promoted++;
    } else if (r.decision === 'Retain') {
      student.div = r.newDiv; student.roll = parseInt(r.newRoll) || r.newRoll;
      student.acyr = targetYear.label;
      retained++;
    } else if (r.decision === 'PassOut' || r.decision === 'TransferOut') {
      student.isActive = false;
      student.finalStatus = r.decision === 'PassOut' ? 'Alumni' : 'Transferred';
      student.finalYearLabel = sourceYear.label;
      inactive.push(student);
      const remainingIdx = students.findIndex(s => s.id === r.studentId);
      if (remainingIdx > -1) students.splice(remainingIdx, 1);
      if (r.decision === 'PassOut') passedOut++; else transferredOut++;
    }
  });

  saveStudents(students);
  saveInactiveStudents(inactive);
  saveStudentYearHistory(history);

  archiveAcademicYear(sourceYear.id, { silent: true });
  setActiveAcademicYear(targetYear.id);

  addAuditEntry('PROMOTION_WIZARD_RUN', `Promotion wizard run from ${sourceYear.label} → ${targetYear.label}: Promoted ${promoted}, Retained ${retained}, Passed Out ${passedOut}, Transferred Out ${transferredOut}.`, sourceYear.label, targetYear.label);

  return { promoted, retained, passedOut, transferredOut };
}

// ────────────────────────────────────────────────────────────
// EXAM-3.3 — validatePromotionReviewSelection(selection)
// ───────────────────────────────────────────────────────────
// Standalone, read-only shape check for the self-describing
// PromotionReviewSelection payload:
//   {
//     version, source, academicYear, reviewedBy, reviewedAt,
//     examId, className,
//     students: [{ studentId, finalAction, ... }]
//   }
// Checks only structural presence — it does not judge whether
// version/source/academicYear/etc. have "correct" values, so any
// future producer of this same shape (mobile app, API, Electron
// build, batch import) can stamp its own version/source and still
// pass, as long as the required fields are present. Returns
// { valid, errors } and never throws.
// ────────────────────────────────────────────────────────────
function validatePromotionReviewSelection(selection) {
  var errors = [];
  if (!selection || typeof selection !== 'object') {
    return { valid: false, errors: ['selection is missing or not an object'] };
  }
  if (selection.version === undefined || selection.version === null) {
    errors.push('selection.version is required');
  }
  if (!Array.isArray(selection.students)) {
    errors.push('selection.students must be an array');
  } else {
    selection.students.forEach(function (s, i) {
      if (!s || typeof s !== 'object') {
        errors.push('selection.students[' + i + '] is not an object');
        return;
      }
      if (s.studentId === undefined || s.studentId === null || s.studentId === '') {
        errors.push('selection.students[' + i + '] is missing studentId');
      }
      if (s.finalAction === undefined || s.finalAction === null || s.finalAction === '') {
        errors.push('selection.students[' + i + '] is missing finalAction');
      }
    });
  }
  return { valid: errors.length === 0, errors: errors };
}

// ────────────────────────────────────────────────────────────
// EXAM-3.2 — loadPromotionReviewSelection(selection)
// ───────────────────────────────────────────────────────────
// Dedicated handover point between the new Promotion Review tab
// (Exam Centre V2 → AcademicEngine.PromotionReview, EXAM-2.6D) and
// this EXISTING Student Promotion Wizard. This is a NEW function —
// openPromotionWizard(), confirmRunPromotion(), runPromotion(), and
// renderPromoTable() above/below are completely unmodified.
//
// The Review tab never reaches into promoWizardRows and never
// mutates a Wizard row object directly. Instead it hands this
// function a plain-data, self-describing payload:
//   {
//     version, source, academicYear, reviewedBy, reviewedAt,
//     examId, className,
//     students: [{ studentId, suggestedAction, finalAction,
//                  reasons, attendance, result }]
//   }
// and this function is the ONLY place that knows how to translate
// that payload into the Wizard's own row shape
// (.decision / .newCls / .include on promoWizardRows) — the exact
// same fields onPromoDecisionChange()/bulkSetPromoDecision() above
// already mutate directly, so nothing new is taught to the Wizard.
//
// EXAM-3.3 — before anything else, the payload is run through
// validatePromotionReviewSelection() (version exists, students is
// an array, every student has studentId + finalAction). If that
// fails, loading is aborted — no promoWizardRows are touched and
// renderPromoTable() is never called — and the failure is logged
// via console.error so it isn't silently swallowed like a normal
// warning. This makes the payload's shape self-describing and
// future-proof: any other producer (mobile app, API, Electron
// build, batch import) that emits this same shape is validated the
// same way, with no special-casing for who built it.
//
// Call this AFTER openPromotionWizard() has opened and populated
// promoWizardRows for the active roster — this function only
// overwrites rows for students named in the selection; every other
// student on the roster keeps the Wizard's own default decision
// (Promote/PassOut, as openPromotionWizard() already assigns)
// completely untouched.
//
// Does NOT call runPromotion() or confirmRunPromotion() — loading a
// selection only pre-fills the Wizard's own table. The Principal
// still reviews it there and still clicks "Run Promotion & Archive"
// to actually commit anything.
// ────────────────────────────────────────────────────────────
function loadPromotionReviewSelection(selection) {
  var check = validatePromotionReviewSelection(selection);
  if (!check.valid) {
    console.error('loadPromotionReviewSelection: invalid PromotionReviewSelection payload — aborting load. Errors: ' + check.errors.join('; '), selection);
    return { touched: 0, total: 0, aborted: true, errors: check.errors };
  }
  if (!Array.isArray(promoWizardRows) || !promoWizardRows.length) {
    console.warn('loadPromotionReviewSelection: the Promotion Wizard has not been opened yet — call openPromotionWizard() first.');
    return { touched: 0, total: selection.students.length };
  }

  const byStudent = {};
  selection.students.forEach(s => { if (s && s.studentId) byStudent[s.studentId] = s; });

  let touched = 0;
  promoWizardRows.forEach(row => {
    const sel = byStudent[row.studentId];
    if (!sel) return; // student not part of this selection — leave the Wizard's own default untouched
    const action = sel.finalAction || sel.suggestedAction;
    if (action === 'Promote') {
      row.decision = 'Promote';
      row.newCls = nextClassInOrder(row.cls) || row.cls;
      row.include = true;
    } else if (action === 'Repeat') {
      row.decision = 'Retain';
      row.newCls = row.cls;
      row.include = true;
    } else if (action === 'Alumni') {
      row.decision = 'PassOut';
      row.newCls = row.cls;
      row.include = true;
    } else if (action === 'Transfer') {
      row.decision = 'TransferOut';
      row.newCls = row.cls;
      row.include = true;
    } else if (action === 'Hold') {
      row.include = false; // not ready to decide — excluded from this promotion run
    } else {
      return; // unrecognized action — leave the Wizard's own default untouched
    }
    touched++;
  });

  renderPromoTable(); // unmodified — just redraws using the same promoWizardRows array

  return { touched, total: selection.students.length };
}

// ====================== ACCOUNT STATEMENTS PAGE ======================
function renderAccountStatementsPage() {
  const tbody = document.getElementById('acst-table-body');
  if(!tbody) return;
  const q = (document.getElementById('acst-search')?.value || '').toLowerCase();
  const cls = document.getElementById('acst-class')?.value || '';
  const statusFilter = document.getElementById('acst-status')?.value || '';
  
  let students = getStudents();
  if(cls) students = students.filter(s => s.cls === cls);
  if(q) students = students.filter(s => (s.name+s.admno+s.cls).toLowerCase().includes(q));
  
  students.sort((a,b) => {
    if(a.cls < b.cls) return -1;
    if(a.cls > b.cls) return 1;
    return (a.roll||0) - (b.roll||0);
  });

  // Summary bar
  const summaryDiv = document.getElementById('acst-summary-bar');
  if(summaryDiv) {
    const allStudents = getStudents();
    const sfl = getSchoolFeeLedger();
    const tfl = getTransportFeeLedger();
    const bills = getInventoryBills();
    const totalSchoolDue = sfl.reduce((s,r) => s+Number(r.payable||0), 0);
    const totalSchoolPaid = sfl.reduce((s,r) => s+Number(r.paid||0), 0);
    const totalTransportDue = tfl.reduce((s,r) => s+Number(r.annualFee||0), 0);
    const totalTransportPaid = tfl.reduce((s,r) => s+Number(r.paid||0), 0);
    const totalInvBal = bills.reduce((s,b) => s+Number(b.balance||0), 0);
    const totalBalance = (totalSchoolDue-totalSchoolPaid) + (totalTransportDue-totalTransportPaid) + totalInvBal;
    summaryDiv.innerHTML = [
      ['Total Students', allStudents.length, '#1a3a6b'],
      ['School Collected', '₹'+totalSchoolPaid.toLocaleString('en-IN'), '#1a6b3c'],
      ['Transport Collected', '₹'+totalTransportPaid.toLocaleString('en-IN'), '#1a6b3c'],
      ['Grand Balance', '₹'+totalBalance.toLocaleString('en-IN'), totalBalance>0?'#c0392b':'#1a6b3c'],
    ].map(([l,v,c]) => `<div style="background:#fff;border:1px solid #e0dcd5;border-radius:8px;padding:8px 14px;">
      <div style="font-size:16px;font-weight:700;color:${c};">${v}</div>
      <div style="font-size:11px;color:#888;">${l}</div>
    </div>`).join('');
  }

  if(!students.length) {
    tbody.innerHTML = '<tr><td colspan="12" style="text-align:center;padding:20px;color:#aaa;">No students found.</td></tr>';
    return;
  }

  const sfl = getSchoolFeeLedger();
  const tfl = getTransportFeeLedger();
  const bills = getInventoryBills();

  const rows = students.map(s => {
    const schoolLedger = sfl.find(l => l.studentId === s.id);
    const transportLedger = tfl.find(l => l.studentId === s.id);
    const invBills = bills.filter(b => b.studentId === s.id && b.status !== 'Cancelled');
    
    const schoolDue = schoolLedger ? Number(schoolLedger.payable||0) : 0;
    const schoolPaid = schoolLedger ? Number(schoolLedger.paid||0) : 0;
    const schoolBal = schoolDue - schoolPaid;
    
    const transDue = transportLedger ? Number(transportLedger.annualFee||0) : 0;
    const transPaid = transportLedger ? Number(transportLedger.paid||0) : 0;
    const transBal = transDue - transPaid;
    
    const invBal = invBills.reduce((sum,b) => sum+Number(b.balance||0), 0);
    const invPaid = invBills.reduce((sum,b) => sum+Number(b.paid||0), 0);
    
    const grandBal = schoolBal + transBal + invBal;
    const grandPaid = schoolPaid + transPaid + invPaid;
    
    let status = 'Pending';
    if(grandBal <= 0 && (schoolDue+transDue) > 0) status = 'Paid';
    else if(grandPaid > 0) status = 'Partial';
    
    if(statusFilter && status !== statusFilter) return '';
    
    const statusBadge = status === 'Paid' ? 'badge-green' : status === 'Partial' ? 'badge-yellow' : 'badge-red';
    const planStatus = getCombinedPlanStatus(s.id);
    const feePlanLabel = planStatus ? planStatus.planLabel.replace(' (Plan 1/2/3 bypassed)','').replace(' (Auto-Escalated)', planStatus.escalated ? ' ⚠️ Auto-Escalated' : '') : (s.feePlan === 'lumpsum' ? 'Plan 1 — One-Time' : s.feePlan === 'annual' ? 'Plan 3 — Full Annual' : 'Plan 2 — 2-Installment');
    
    return `<tr>
      <td><b>${s.name}</b></td>
      <td>${s.cls} ${s.div}</td>
      <td>${s.admno||'—'}</td>
      <td style="font-size:11px;">${feePlanLabel}${s.concession && s.concession!=='none' ? '<br/><span style="color:#c0392b;">'+(s.concession==='teacher'?'C1 Teacher Child':'C2 Sibling')+(s.concessionStatus==='pending'?' (Pending)':s.concessionStatus==='rejected'?' (Rejected)':'')+'</span>' : ''}</td>
      <td>₹${schoolDue.toLocaleString('en-IN')}</td>
      <td style="color:#1a6b3c;">₹${schoolPaid.toLocaleString('en-IN')}</td>
      <td>${transDue > 0 ? '₹'+transDue.toLocaleString('en-IN') : '—'}</td>
      <td style="color:#1a6b3c;">${transPaid > 0 ? '₹'+transPaid.toLocaleString('en-IN') : '—'}</td>
      <td>${invBal > 0 ? '<span style="color:#c0392b;">₹'+invBal.toLocaleString('en-IN')+'</span>' : invPaid > 0 ? '<span style="color:#1a6b3c;">Paid</span>' : '—'}</td>
      <td style="font-weight:700;color:${grandBal>0?'#c0392b':'#1a6b3c'};">₹${grandBal.toLocaleString('en-IN')}</td>
      <td><span class="badge ${statusBadge}">${status}</span></td>
      <td>
        <button class="btn btn-outline btn-sm" onclick="viewAccountStatement('${s.id}')">📒 Statement</button>
        <button class="btn btn-gold btn-sm" style="margin-left:4px;" onclick="openFeeModalForStudent('${s.id}')">💳 Collect</button>
      </td>
    </tr>`;
  }).join('');
  tbody.innerHTML = rows || '<tr><td colspan="12" style="text-align:center;padding:20px;color:#aaa;">No matching students.</td></tr>';
}

function openFeeModalForStudent(studentId) {
  openFeeModal();
  const sel = document.getElementById('fee-stu-select');
  if (sel) { sel.value = studentId; loadStudentFeeIntoModal(); }
}

// ====================== INIT ======================
window.addEventListener('load', () => {
  document.getElementById('sidebar').style.display='none';
  document.getElementById('main').style.marginLeft='0';

  // The portal chooser — not the staff login form — is the app's first
  // screen now. Two restores can beat this handler to it: a Student or
  // Parent Portal session (restored on DOMContentLoaded, which has already
  // painted its own screen) and a staff session (restored at the bottom of
  // this handler, which calls initApp()). Only fall back to the chooser when
  // no portal session is live, so neither gets clobbered.
  const portalSessionRestored = !!(window.PortalAuthEngine && PortalAuthEngine.isLoggedIn());
  if (!portalSessionRestored && typeof showPortalSelect === 'function') showPortalSelect();

  const s = getSettings();
  document.getElementById('login-school-name').textContent = s.name;
  if (s.logo) {
    const el = document.getElementById('login-logo');
    el.innerHTML = `<img src="${s.logo}" style="width:60px;height:60px;object-fit:contain;border-radius:12px;"/>`;
  }
  // NEW LINE
  loadTransportRoutesDropdown();
  // Run plan auto-switch service on every app load
  setTimeout(() => { try { runPlanAutoSwitchService(); } catch(e){} }, 1200);

  document.getElementById('login-email').addEventListener('keydown', e => { if (e.key==='Enter') doLogin(); });
  document.getElementById('login-pass').addEventListener('keydown', e => { if (e.key==='Enter') doLogin(); });

  // Session Restore (LOCAL-STORAGE AUTH MODE) — if a valid, non-expired
  // local session already exists (e.g. page refresh), skip the login
  // screen and go straight into the app instead of forcing a re-login
  // every time.
  const restoredUser = restoreLocalSession();
  if (restoredUser && !restoredUser.disabled) {
    currentUser = restoredUser;
    initApp();
  }
});

/* ── REGISTRATION APPROVALS ENGINE ── */
function getPendingStudentRegs(){ return (window.Dnyanankur && Dnyanankur.StudentService) ? Dnyanankur.StudentService.getPendingRegistrations() : (LS.get('pending_student_registrations') || []); }
function savePendingStudentRegs(d){ if (window.Dnyanankur && Dnyanankur.StudentService) { Dnyanankur.StudentService.savePendingRegistrations(d); } else { LS.set('pending_student_registrations', d); } }

function renderRegApprovals(){
  const tbody = document.getElementById('regapprovals-body');
  if(!tbody) return;
  const pending = getPendingStudentRegs().filter(x => x.status === 'pending');
  if(!pending.length){
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:20px;color:#aaa;">No pending registration requests.</td></tr>';
    return;
  }
  tbody.innerHTML = pending.map(req => {
    const s = req.student;
    const badge = req.type === 'new_registration'
      ? '<span class="badge badge-blue">New</span>'
      : '<span class="badge badge-yellow">Edit</span>';
    return `<tr>
      <td>${badge}</td>
      <td><b>${s.name}</b></td>
      <td>${s.cls} ${s.div}</td>
      <td>${req.submittedBy}</td>
      <td>${fmtDMY(req.submittedAt)}</td>
      <td style="font-size:11.5px;">Adm: ${s.admno||'—'} | DOB: ${s.dob} | Father: ${s.fatherName}</td>
      <td>
        <button class="btn btn-outline btn-sm" onclick="viewRegRequest('${req.id}')">🔍 View${req.type==='edit'?' Changes':' Details'}</button>
        <button class="btn btn-primary btn-sm" style="margin-left:4px;" onclick="approveStudentReg('${req.id}')">✅ Approve</button>
        <button class="btn btn-outline btn-sm" style="margin-left:4px;color:#c0392b;border-color:#c0392b;" onclick="rejectStudentReg('${req.id}')">❌ Reject</button>
      </td>
    </tr>`;
  }).join('');
}

function approveStudentReg(reqId){
  // Phase 16.4 Task 2 (Security fix): registration approval is a
  // Principal-only action (page-level gate on regapprovals + the diff
  // modal only shows this button to principal). This adds the matching
  // guard inside the function itself so it can't be invoked directly
  // (e.g. via console) by a non-principal.
  if (typeof PermissionManager !== 'undefined' && !PermissionManager.hasRole('principal')) {
    alert('⛔ Only the Principal can approve student registrations.');
    return;
  }
  const all = getPendingStudentRegs();
  const req = all.find(x => x.id === reqId);
  if(!req) return;

  if(req.type === 'new_registration'){
    const students = getStudents();
    students.push(req.student);
    saveStudents(students);
    assignStudentFinance(req.student);
    if (window.PortalParentEngine && typeof PortalParentEngine.onStudentAdded === 'function') {
      PortalParentEngine.onStudentAdded(req.student);
    }
    addAuditEntry('STUDENT_REGISTER', `Principal approved & registered: ${req.student.name} (${req.student.cls})`, '', currentUser.username);
    alert(`✅ Approved & Registered: ${req.student.name} (${req.student.cls} ${req.student.div})`);
    // CM-1.0 — notify the Communication Engine.
    if (window.Dnyanankur && Dnyanankur.Event) {
      Dnyanankur.Event.publish('student.admission.approved', {
        studentId: req.student.id, studentName: req.student.name, className: req.student.cls
      }, { sourceModule: 'student' });
    }
  } else {
    // Edit: apply the changes
    const students = getStudents();
    const idx = students.findIndex(x => x.id === req.originalId);
    if(idx > -1){
      students[idx] = { ...req.student };
      saveStudents(students);
      resyncStudentFeePlan(req.originalId);
      addAuditEntry('STUDENT_UPDATE', `Principal approved edit: ${req.student.name} (${req.student.cls})`, '', currentUser.username);
      alert(`✅ Edit approved & applied for: ${req.student.name}`);
      // CM-1.0 — notify the Communication Engine.
      if (window.Dnyanankur && Dnyanankur.Event) {
        Dnyanankur.Event.publish('student.updated', {
          studentId: req.student.id, studentName: req.student.name, className: req.student.cls
        }, { sourceModule: 'student' });
      }
    }
  }

  req.status = 'approved';
  req.approvedAt = new Date().toISOString();
  req.approvedBy = currentUser.username;
  req.clerkSeen = false;
  savePendingStudentRegs(all);
  renderRegApprovals();
  updateRegApprovalsBadge();
}

function rejectStudentReg(reqId){
  // Phase 16.4 Task 2 (Security fix): see approveStudentReg() above.
  if (typeof PermissionManager !== 'undefined' && !PermissionManager.hasRole('principal')) {
    alert('⛔ Only the Principal can reject student registrations.');
    return;
  }
  const reason = prompt('Reason for rejection (will be logged):');
  if(reason === null) return; // cancelled
  const all = getPendingStudentRegs();
  const req = all.find(x => x.id === reqId);
  if(!req) return;
  req.status = 'rejected';
  req.rejectedAt = new Date().toISOString();
  req.rejectedBy = currentUser.username;
  req.rejectReason = reason;
  req.clerkSeen = false;
  savePendingStudentRegs(all);
  addAuditEntry('STUDENT_REG_REJECTED', `Rejected ${req.type} for ${req.student.name}: ${reason}`, '', currentUser.username);
  renderRegApprovals();
  updateRegApprovalsBadge();
}

function updateRegApprovalsBadge(){
  const count = getPendingStudentRegs().filter(x => x.status === 'pending').length;
  // Inject badge near dash-role-badge if exists
  const existing = document.getElementById('reg-approvals-badge');
  if(existing) existing.remove();
  if(count > 0){
    const badge = document.createElement('span');
    badge.id = 'reg-approvals-badge';
    badge.className = 'badge badge-red';
    badge.style.cssText = 'cursor:pointer;margin-left:8px;';
    badge.innerHTML = `📋 ${count} Reg Approval${count>1?'s':''}`;
    badge.onclick = () => showPage('regapprovals');
    const rb = document.getElementById('dash-role-badge');
    if(rb) rb.appendChild(badge);
  }
}

/* ── REGISTRATION DIFF / DETAILS VIEWER ── */
const REG_FIELD_LABELS = {
  name:'Name', cls:'Class', div:'Division', roll:'Roll No', dob:'Date of Birth', gender:'Gender',
  blood:'Blood Group', sid:'Student ID', uid:'UID', pen:'PEN', apaar:'APAAR', placeOfBirth:'Place of Birth',
  motherTongue:'Mother Tongue', religion:'Religion', caste:'Caste', subcaste:'Sub-Caste', category:'Category',
  nationality:'Nationality', couponType:'Coupon Type', rte:'RTE', gr:'GR No', medium:'Medium',
  admno:'Admission No', admdate:'Admission Date', acyr:'Academic Year', prevschool:'Previous School',
  fatherName:'Father Name', fatherOcc:'Father Occupation', fatherMobile:'Father Mobile', fatherAadhar:'Father Aadhar',
  motherName:'Mother Name', motherOcc:'Mother Occupation', motherMobile:'Mother Mobile', guardian:'Guardian',
  income:'Income', email:'Email', addr:'Address', city:'City', taluka:'Taluka', dist:'District', state:'State',
  pin:'Pin Code', medical:'Medical Notes', emname:'Emergency Contact Name', emnum:'Emergency Contact No',
  disabled:'Disability', bus:'Transport Route', concession:'Concession',
};
const REG_FIELDS_SKIP = ['photo','id'];

function viewRegRequest(reqId){
  const req = getPendingStudentRegs().find(x => x.id === reqId);
  if(!req) return;
  const isEdit = req.type === 'edit';
  let bodyHTML = '';

  if(isEdit){
    const original = getStudents().find(s => s.id === req.originalId) || {};
    const proposed = req.student || {};
    const keys = [...new Set([...Object.keys(original), ...Object.keys(proposed)])]
      .filter(k => !REG_FIELDS_SKIP.includes(k));
    const changedRows = keys.filter(k => String(original[k]??'') !== String(proposed[k]??''));

    const photoChanged = String(original.photo||'') !== String(proposed.photo||'');

    bodyHTML = `
      <div style="margin-bottom:12px;padding:10px 14px;background:#fff8e1;border:1px solid #ffe082;border-radius:8px;font-size:13px;">
        Comparing the original record against the changes <b>${req.submittedBy}</b> submitted on ${new Date(req.submittedAt).toLocaleString('en-IN')} for <b>${proposed.name||original.name}</b> (${proposed.cls||original.cls} ${proposed.div||original.div}).
      </div>
      ${photoChanged ? `<div style="margin-bottom:10px;font-size:12.5px;color:#7c3aed;">📷 Photo was also changed.</div>` : ''}
      ${changedRows.length ? `
      <table style="width:100%;font-size:13px;border-collapse:collapse;">
        <thead>
          <tr>
            <th style="text-align:left;padding:8px;border-bottom:2px solid #e0dcd5;width:22%;">Field</th>
            <th style="text-align:left;padding:8px;border-bottom:2px solid #e0dcd5;width:39%;color:#888;">Before</th>
            <th style="text-align:left;padding:8px;border-bottom:2px solid #e0dcd5;width:39%;color:#1a6b3c;">After</th>
          </tr>
        </thead>
        <tbody>
          ${changedRows.map(k => `<tr>
            <td style="padding:7px 8px;border-bottom:1px solid #f0ede8;font-weight:600;">${REG_FIELD_LABELS[k]||k}</td>
            <td style="padding:7px 8px;border-bottom:1px solid #f0ede8;color:#c0392b;background:#fdf2f1;">${original[k]||'<i style="color:#bbb;">— empty —</i>'}</td>
            <td style="padding:7px 8px;border-bottom:1px solid #f0ede8;color:#1a6b3c;background:#f0f9f3;">${proposed[k]||'<i style="color:#bbb;">— empty —</i>'}</td>
          </tr>`).join('')}
        </tbody>
      </table>` : `<p style="color:#888;font-size:13px;">No text field changes detected${photoChanged?' besides the photo.':'.'}</p>`}
    `;
  } else {
    const s = req.student || {};
    const keys = Object.keys(s).filter(k => !REG_FIELDS_SKIP.includes(k) && s[k] !== '' && s[k] != null);
    bodyHTML = `
      <div style="margin-bottom:12px;padding:10px 14px;background:#eef3fb;border:1px solid #c3dafb;border-radius:8px;font-size:13px;">
        New registration submitted by <b>${req.submittedBy}</b> on ${new Date(req.submittedAt).toLocaleString('en-IN')}.
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px;font-size:13px;">
        ${keys.map(k => `<div style="padding:6px 0;border-bottom:1px solid #f0ede8;"><span style="color:#888;">${REG_FIELD_LABELS[k]||k}:</span> <b>${s[k]}</b></div>`).join('')}
      </div>
    `;
  }

  document.getElementById('reg-diff-title').textContent = isEdit ? '🔍 Review Edit — Before & After' : '🔍 New Registration Details';
  document.getElementById('reg-diff-content').innerHTML = bodyHTML;

  const actionsEl = document.getElementById('reg-diff-actions');
  if(req.status === 'pending' && currentUser && currentUser.role === 'principal'){
    actionsEl.style.display = '';
    actionsEl.innerHTML = `
      <button class="btn btn-primary" onclick="closeModal('modal-reg-diff'); approveStudentReg('${req.id}')">✅ Approve</button>
      <button class="btn btn-outline" style="color:#c0392b;border-color:#c0392b;" onclick="closeModal('modal-reg-diff'); rejectStudentReg('${req.id}')">❌ Reject</button>
      <button class="btn btn-outline" onclick="closeModal('modal-reg-diff')">Close</button>
    `;
  } else {
    actionsEl.style.display = '';
    actionsEl.innerHTML = `<button class="btn btn-outline" onclick="closeModal('modal-reg-diff')">Close</button>`;
  }

  openModal('modal-reg-diff');
}

/* ── CLERK: MY SUBMISSIONS ── */
function renderMySubmissions(){
  const tbody = document.getElementById('mysubmissions-body');
  if(!tbody || !currentUser) return;
  const mine = getPendingStudentRegs()
    .filter(x => x.submittedBy === currentUser.username)
    .sort((a,b) => new Date(b.submittedAt) - new Date(a.submittedAt));

  if(!mine.length){
    tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:20px;color:#aaa;">You have not submitted any registrations or edits yet.</td></tr>';
  } else {
    tbody.innerHTML = mine.map(req => {
      const s = req.student;
      const typeBadge = req.type === 'new_registration'
        ? '<span class="badge badge-blue">New</span>'
        : '<span class="badge badge-yellow">Edit</span>';
      let statusBadge, detail;
      if(req.status === 'pending'){
        statusBadge = '<span class="badge badge-yellow">⏳ Pending</span>';
        detail = 'Awaiting Principal review';
      } else if(req.status === 'approved'){
        statusBadge = '<span class="badge badge-green">✅ Approved</span>';
        detail = `Approved by ${req.approvedBy||'Principal'} on ${req.approvedAt ? fmtDMY(req.approvedAt) : ''}`;
      } else {
        statusBadge = '<span class="badge badge-red">❌ Rejected</span>';
        detail = `Reason: ${req.rejectReason || '—'}`;
      }
      return `<tr>
        <td>${typeBadge}</td>
        <td><b>${s.name}</b></td>
        <td>${s.cls} ${s.div}</td>
        <td>${fmtDMY(req.submittedAt)}</td>
        <td>${statusBadge}</td>
        <td style="font-size:11.5px;">${detail}
          <br/><button class="btn btn-outline btn-sm" style="margin-top:4px;" onclick="viewRegRequest('${req.id}')">🔍 View</button>
        </td>
      </tr>`;
    }).join('');
  }
  updateMySubmissionsBadge();
}

function updateMySubmissionsBadge(){
  const badgeEl = document.getElementById('mysub-nav-badge');
  if(!badgeEl || !currentUser) return;
  const count = getClerkNotifications().length;
  badgeEl.innerHTML = count > 0 ? `<span class="badge badge-red" style="margin-left:6px;">${count}</span>` : '';
}

/* ── CLERK: NOTIFICATIONS ON APPROVAL/REJECTION ── */
function getClerkNotifications(){
  if(!currentUser) return [];
  return getPendingStudentRegs().filter(x =>
    x.submittedBy === currentUser.username && x.status !== 'pending' && !x.clerkSeen
  );
}

function renderClerkNotifications(){
  const el = document.getElementById('dash-clerk-notifications');
  if(!el || !currentUser || (currentUser.role !== 'clerk' && currentUser.role !== 'teacher')) return;
  const notes = getClerkNotifications();
  updateMySubmissionsBadge();
  if(!notes.length){ el.innerHTML = ''; return; }

  el.innerHTML = `
    <div class="card" style="margin-bottom:20px;border-left:4px solid var(--gold);">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">
        <div class="card-title" style="margin:0;border:none;padding:0;">🔔 Updates on Your Submissions</div>
        <button class="btn btn-outline btn-sm" onclick="dismissAllClerkNotifications()">Dismiss All</button>
      </div>
      ${notes.map(req => {
        const s = req.student;
        const isApproved = req.status === 'approved';
        return `<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:9px 12px;margin-bottom:6px;border-radius:8px;background:${isApproved ? '#f0f9f3' : '#fdf2f1'};border:1px solid ${isApproved ? '#cce8d6' : '#f4d2cf'};">
          <div style="font-size:13px;">
            ${isApproved ? '✅' : '❌'} <b>${req.type==='edit' ? 'Edit for' : 'New registration:'} ${s.name}</b> (${s.cls} ${s.div}) was <b style="color:${isApproved?'#1a6b3c':'#c0392b'};">${isApproved ? 'approved' : 'rejected'}</b>${!isApproved && req.rejectReason ? ' — '+req.rejectReason : ''}.
          </div>
          <button class="btn btn-outline btn-sm" onclick="dismissClerkNotification('${req.id}')">Dismiss</button>
        </div>`;
      }).join('')}
    </div>
  `;
}

function dismissClerkNotification(reqId){
  const all = getPendingStudentRegs();
  const req = all.find(x => x.id === reqId);
  if(req) req.clerkSeen = true;
  savePendingStudentRegs(all);
  renderClerkNotifications();
  updateMySubmissionsBadge();
}

function dismissAllClerkNotifications(){
  const all = getPendingStudentRegs();
  getClerkNotifications().forEach(n => { const r = all.find(x => x.id === n.id); if(r) r.clerkSeen = true; });
  savePendingStudentRegs(all);
  renderClerkNotifications();
  updateMySubmissionsBadge();
}


