    const legacyCls = document.getElementById('m-class')?.value;
    if (legacyCls) {
      const umeCls = document.getElementById('ume-class');
      if (umeCls) { umeCls.value = legacyCls; umeLoadSubjects(); }
      const legacyDiv = document.getElementById('m-div')?.value;
      const umeDiv = document.getElementById('ume-div');
      if (legacyDiv && umeDiv) umeDiv.value = legacyDiv;
      const legacyTerm = document.getElementById('m-term')?.value;
      const umeTerm = document.getElementById('ume-term');
      if (legacyTerm && umeTerm) umeTerm.value = legacyTerm;
      const legacyAssess = document.getElementById('m-assess')?.value;
      const umeAssess = document.getElementById('ume-assess');
      if (legacyAssess && umeAssess) umeAssess.value = legacyAssess;
    }
