// ── Subject Mapping → getSubjects() sync ────────────────────
// Every time a subject map entry is saved/deleted, we rebuild
// the getSubjects() / class_subjects key so the UME form and
// Annual Report Cards always use the same subject list.
function examSyncSubjectsFromMapping() {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examSyncSubjectsFromMapping(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examSyncSubjectsFromMapping();
  }
  const maps = examRetrieve('subjectMap', []);
  const subMap = {};
  maps.forEach(m => {
    if (!m.className) return;
    if (!subMap[m.className]) subMap[m.className] = [];
    if (!subMap[m.className].includes(m.subjectName)) subMap[m.className].push(m.subjectName);
  });
  // UNION merge only — never remove/replace a class's existing subjects.
  // (Previously this did {...existing, ...subMap}, which REPLACED a class's
  // whole subject array with whatever had been mapped for exams so far. If
  // even one exam's mapping was incomplete for a class, that class's Annual
  // Report Card subject list — and every future exam auto-provisioned from
  // it — would silently shrink to just those few subjects. Union-merging
  // fixes that: mapping a subject always ADDS it, never deletes others.)
  if (Object.keys(subMap).length > 0 && typeof LS !== 'undefined') {
    const existing = (typeof getSubjects === 'function') ? getSubjects() : {};
    const merged = { ...existing };
    Object.keys(subMap).forEach(cls => {
      const unionList = [...(merged[cls] || [])];
      subMap[cls].forEach(sub => { if (!unionList.includes(sub)) unionList.push(sub); });
      merged[cls] = unionList;
    });
    LS.set('class_subjects', merged);
  }
}

function examSectionActivated(sectionId) {
  switch (sectionId) {
    case 'examMaster':        examRenderMasterTable(); break;
    case 'examTimetable':     examPopulateTTFilter(); break;
    case 'examSubjectMap':    examRenderSubjectMap(); break;
    case 'examMarksEntry':
      examMarksEntryInit();
      if (typeof qtePopulateClasses === 'function') qtePopulateClasses();
      break;
    case 'examGrades':        examRenderGradeScales(); examPopulatePFFilters(); examPopulateCRFilters(); break;
    case 'examResultProcess': examPopulateRPFilters(); break;
    case 'examAnalysis':      examPopulateAnalysisFilters(); break;
    case 'examReportCard':    examPopulateRCFilters(); break;
    case 'examMeritList':     examPopulateMLFilters(); break;
  }
}

