let examActiveYear = '';
let examActiveTerm = '';

function examSetContextYear(val) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examSetContextYear(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examSetContextYear(val);
  }
  examActiveYear = val;
  examStore('contextYear', val);
}

function examSetContextTerm(val) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examSetContextTerm(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examSetContextTerm(val);
  }
  examActiveTerm = val;
  examStore('contextTerm', val);
}

function examPopulateContextSelects() {
  const years = examRetrieve('academicYears', []);
  const terms = examRetrieve('terms', []);
  const yearSel = document.getElementById('examContextYear');
  const termSel = document.getElementById('examContextTerm');

  const savedYear = examRetrieve('contextYear', '');
  const savedTerm = examRetrieve('contextTerm', '');

  yearSel.innerHTML = '<option value="">— Academic Year —</option>' +
    years.map(y => `<option value="${y.id}" ${y.id === savedYear ? 'selected' : ''}>${examSanitize(y.name)}</option>`).join('');
  termSel.innerHTML = '<option value="">— Term —</option>' +
    terms.map(t => `<option value="${t.id}" ${t.id === savedTerm ? 'selected' : ''}>${examSanitize(t.name)}</option>`).join('');

  examActiveYear = savedYear;
  examActiveTerm = savedTerm;
}

