function examOpenAcademicYearModal(editId = null) {
  const years = examRetrieve('academicYears', []);
  const existing = editId ? years.find(y => y.id === editId) : null;

  const body = `
    <div class="exam-modal-grid-2">
      <div class="exam-form-group">
        <label class="exam-label">Year Label *</label>
        <input type="text" id="ayName" class="exam-input" placeholder="e.g. 2024-25" value="${existing ? examSanitize(existing.name) : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Status</label>
        <select id="ayStatus" class="exam-select">
          <option value="active" ${!existing || existing.status==='active' ? 'selected' : ''}>Active</option>
          <option value="closed" ${existing && existing.status==='closed' ? 'selected' : ''}>Closed</option>
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Start Date</label>
        <input type="date" id="ayStart" class="exam-input" value="${existing ? existing.startDate : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">End Date</label>
        <input type="date" id="ayEnd" class="exam-input" value="${existing ? existing.endDate : ''}"/>
      </div>
    </div>`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Cancel</button>
    <button class="exam-btn exam-btn-primary" onclick="examSaveAcademicYear('${editId || ''}')">
      ${editId ? 'Update Year' : 'Add Year'}
    </button>`;

  examOpenModal(editId ? 'Edit Academic Year' : 'Add Academic Year', body, footer);
}

function examSaveAcademicYear(editId) {
  const name = document.getElementById('ayName').value.trim();
  if (!name) { examShowToast('Year label is required', 'danger'); return; }

  const years = examRetrieve('academicYears', []);
  if (editId) {
    const idx = years.findIndex(y => y.id === editId);
    if (idx > -1) {
      years[idx] = { ...years[idx], name, status: document.getElementById('ayStatus').value,
        startDate: document.getElementById('ayStart').value, endDate: document.getElementById('ayEnd').value };
    }
  } else {
    years.push({ id: examUID(), name, status: document.getElementById('ayStatus').value,
      startDate: document.getElementById('ayStart').value, endDate: document.getElementById('ayEnd').value,
      createdAt: new Date().toISOString() });
  }
  examStore('academicYears', years);
  examCloseModal();
  examRenderAcademicYearList();
  examPopulateContextSelects();
  examShowToast(editId ? 'Academic year updated' : 'Academic year added', 'success');
}

function examDeleteAcademicYear(id) {
  if (!confirm('Delete this academic year? Associated data will remain.')) return;
  const years = examRetrieve('academicYears', []).filter(y => y.id !== id);
  examStore('academicYears', years);
  examRenderAcademicYearList();
  examPopulateContextSelects();
  examShowToast('Academic year deleted', 'warning');
}

function examRenderAcademicYearList() {
  const years = examRetrieve('academicYears', []);
  const el = document.getElementById('examAcademicYearList');
  if (!el) return;
  if (!years.length) {
    el.innerHTML = '<div class="exam-empty-state" style="padding:20px"><div class="exam-empty-icon">📅</div><div>No academic years</div></div>';
    return;
  }
  el.innerHTML = years.map(y => `
    <div class="exam-list-item">
      <div>
        <div class="exam-list-item-name">${examSanitize(y.name)}</div>
        <div class="exam-list-item-meta">${examFormatDate(y.startDate)} – ${examFormatDate(y.endDate)}</div>
      </div>
      <div style="display:flex;align-items:center;gap:8px">
        <span class="exam-badge ${y.status === 'active' ? 'exam-badge-success' : 'exam-badge-neutral'}">${y.status}</span>
      </div>
    </div>`).join('');
}

/* ═══════════════════════════════════════════════
   SECTION G — TERMS
═══════════════════════════════════════════════ */

function examOpenTermModal(editId = null) {
  const terms = examRetrieve('terms', []);
  const existing = editId ? terms.find(t => t.id === editId) : null;

  // BUGFIX: the Order/Sequence field used to hard-code its default to 1 for
  // every NEW term, regardless of how many terms already existed. A school
  // adding "Term 1" then "Term 2" got Order=1 pre-filled BOTH times — if
  // they didn't notice and manually change it to 2, both terms ended up
  // saved with order:1. The Report Card gate (examGetOrderedTerms, used by
  // examCheckResultProcessingReady/examFindSA1ExamForTerm) decides which
  // term is "Term 1" vs "Term 2" purely from this order field, sorted
  // ascending — with tied orders, which term wins that sort is decided by
  // array position, which silently shifts as terms get edited over time.
  // The exam a user correctly tagged to their "Term 2" could then resolve
  // to the WRONG term id in the gate, producing a false "Term 2 (no
  // Semester Exam found)" block even with a locked, correctly-tagged exam.
  // Fixed: default a new term's Order to (current highest order + 1) so
  // sequential terms never collide by default.
  const nextOrder = existing ? existing.order
    : (terms.reduce((max, t) => Math.max(max, Number(t.order) || 0), 0) + 1);

  const body = `
    <div class="exam-modal-grid-2">
      <div class="exam-form-group">
        <label class="exam-label">Term Name *</label>
        <input type="text" id="trmName" class="exam-input" placeholder="e.g. Term 1 / Semester 1" value="${existing ? examSanitize(existing.name) : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Term Type</label>
        <select id="trmType" class="exam-select">
          <option value="term"      ${!existing || existing.type==='term'      ? 'selected':''}>Term</option>
          <option value="semester"  ${existing && existing.type==='semester'   ? 'selected':''}>Semester</option>
          <option value="quarter"   ${existing && existing.type==='quarter'    ? 'selected':''}>Quarter</option>
          <option value="annual"    ${existing && existing.type==='annual'     ? 'selected':''}>Annual</option>
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Start Date</label>
        <input type="date" id="trmStart" class="exam-input" value="${existing ? existing.startDate : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">End Date</label>
        <input type="date" id="trmEnd" class="exam-input" value="${existing ? existing.endDate : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Order / Sequence</label>
        <input type="number" id="trmOrder" class="exam-input" min="1" value="${nextOrder}"/>
      </div>
    </div>`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Cancel</button>
    <button class="exam-btn exam-btn-primary" onclick="examSaveTerm('${editId || ''}')">
      ${editId ? 'Update Term' : 'Add Term'}
    </button>`;

  examOpenModal(editId ? 'Edit Term' : 'Add Term', body, footer);
}

function examSaveTerm(editId) {
  const name = document.getElementById('trmName').value.trim();
  if (!name) { examShowToast('Term name is required', 'danger'); return; }
  const terms = examRetrieve('terms', []);
  const obj = {
    name, type: document.getElementById('trmType').value,
    startDate: document.getElementById('trmStart').value,
    endDate: document.getElementById('trmEnd').value,
    order: parseInt(document.getElementById('trmOrder').value) || 1
  };
  if (editId) {
    const idx = terms.findIndex(t => t.id === editId);
    if (idx > -1) terms[idx] = { ...terms[idx], ...obj };
  } else {
    terms.push({ id: examUID(), ...obj, createdAt: new Date().toISOString() });
  }
  examStore('terms', terms);
  examCloseModal();
  examRenderTermList();
  examPopulateContextSelects();
  examShowToast(editId ? 'Term updated' : 'Term added', 'success');
}

function examDeleteTerm(id) {
  if (!confirm('Delete this term?')) return;
  examStore('terms', examRetrieve('terms', []).filter(t => t.id !== id));
  examRenderTermList();
  examShowToast('Term deleted', 'warning');
}

function examRenderTermList() {
  const terms = examRetrieve('terms', []).sort((a, b) => a.order - b.order);
  const el = document.getElementById('examTermList');
  if (!el) return;
  if (!terms.length) {
    el.innerHTML = '<div class="exam-empty-state" style="padding:20px"><div class="exam-empty-icon">🗓</div><div>No terms</div></div>';
    return;
  }
  el.innerHTML = terms.map(t => `
    <div class="exam-list-item">
      <div>
        <div class="exam-list-item-name">${examSanitize(t.name)}</div>
        <div class="exam-list-item-meta">${t.type} • ${examFormatDate(t.startDate)} – ${examFormatDate(t.endDate)}</div>
      </div>
      <div class="exam-list-item-actions">
        <button class="exam-list-action-btn" onclick="examOpenTermModal('${t.id}')">✎</button>
        <button class="exam-list-action-btn del" onclick="examDeleteTerm('${t.id}')">✕</button>
      </div>
    </div>`).join('');
}

