/* ═══════════════════════════════════════════════
   SECTION I — EXAMINATION MASTER (CRUD)
═══════════════════════════════════════════════ */

// Guesses which Annual Report Card slot (FA1 / FA2 / SA1 / NONE) an exam
// belongs to, from its type/name text. Used only as (a) a starting default
// when creating a new Examination — the user can always change it — and
// (b) a fallback for exams saved before this field existed.
function examInferRcSlot(text) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examInferRcSlot(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examInferRcSlot(text);
  }
  const t = (text || '').toLowerCase();
  // BUGFIX: the old regexes only matched "unit test" + whitespace + digit
  // (e.g. "Unit Test 2"). Any other real-world naming — "Unit Test-2",
  // "Unit Test2", "UT2", "UT-2", "2nd Unit Test", "Second Unit Test" — fell
  // through every check and hit the unconditional `return 'SA1'` at the
  // bottom. That silently pre-selected "Summative — Semester/Final Exam" in
  // the Report Card Slot dropdown for what was actually a Unit Test 2 exam,
  // so marks entered against it got mirrored into the SA1 (Semester Exam)
  // legacy slot instead of FA2 — corrupting the FA1+FA2+SA1 Total on the
  // report card (Unit Test 2 marks would overwrite/blend into the Semester
  // Exam figure rather than being added as their own column). Widened to
  // tolerate hyphens/no-space/"UT"/ordinal-word phrasing for both slots.
  if (/unit\s*test\s*-?\s*[13]\b|\but\s*-?\s*[13]\b|\b1st\s*unit\s*test\b|\bfirst\s*unit\s*test\b|\bfa\s*-?\s*1\b|formative\s*-?\s*1\b/.test(t)) return 'FA1';
  if (/unit\s*test\s*-?\s*[24]\b|\but\s*-?\s*[24]\b|\b2nd\s*unit\s*test\b|\bsecond\s*unit\s*test\b|\bfa\s*-?\s*2\b|formative\s*-?\s*2\b/.test(t)) return 'FA2';
  if (/semester|summative|\bsa\s*-?\s*1\b|\bsa\s*-?\s*2\b|final|annual/.test(t)) return 'SA1';
  return 'SA1';
}

// Live-updates the Report Card Slot dropdown when the Exam Type changes,
// so picking "Unit Test" style types suggests FA1/FA2 automatically.
function examAutoSuggestRcSlot() {
  const typeSel = document.getElementById('emType');
  const nameEl = document.getElementById('emName');
  const rcSel = document.getElementById('emRcSlot');
  if (!typeSel || !rcSel) return;
  const typeText = typeSel.options[typeSel.selectedIndex]?.textContent || '';
  const nameText = nameEl?.value || '';
  rcSel.value = examInferRcSlot(`${typeText} ${nameText}`);
  examAutoSetMaxMarks();
}

// Locks Theory Max Marks to the class's fixed report card structure
// (getMarkStructure) whenever a specific Applicable Class + a real
// FA1/FA2/SA1 Report Card Slot are chosen — e.g. picking "5th" + "FA1"
// auto-fills 25 and greys the field out, so it's impossible for an exam's
// max marks to drift out of sync with what the Annual/Semester 1 Report
// Card actually expects for that class. Only editable when "All Classes"
// is chosen (since different classes have different max marks) or the
// slot is "Not counted in Annual Report Card".
function examAutoSetMaxMarks() {
  const classSel = document.getElementById('emClass');
  const rcSel = document.getElementById('emRcSlot');
  const maxInput = document.getElementById('emTheoryMax');
  const hint = document.getElementById('emMaxMarksHint');
  if (!classSel || !rcSel || !maxInput) return;

  const className = classSel.value;
  const slot = rcSel.value;
  const slotKey = { FA1: 'fa1', FA2: 'fa2', SA1: 'sa1' }[slot];

  if (className && className !== 'all' && slotKey && typeof getMarkStructure === 'function') {
    const struct = getMarkStructure(className);
    const maxVal = struct[slotKey];
    const practInput = document.getElementById('emPractMax');
    const intInput = document.getElementById('emIntMax');
    if (maxVal != null) {
      maxInput.value = maxVal;
      maxInput.readOnly = true;
      maxInput.style.background = '#f1f5f9';
      if (practInput) { practInput.value = 0; practInput.readOnly = true; practInput.style.background = '#f1f5f9'; }
      if (intInput)   { intInput.value = 0;   intInput.readOnly = true;   intInput.style.background = '#f1f5f9'; }
      if (hint) hint.textContent = `Locked to ${className}'s report card format (${slot} max = ${maxVal}). This format tracks one mark per subject per slot — no separate practical/internal split.`;
      return;
    }
  }
  maxInput.readOnly = false;
  maxInput.style.background = '';
  const practInputU = document.getElementById('emPractMax');
  const intInputU = document.getElementById('emIntMax');
  if (practInputU) { practInputU.readOnly = false; practInputU.style.background = ''; }
  if (intInputU)   { intInputU.readOnly = false;   intInputU.style.background = ''; }
  if (hint) hint.textContent = className === 'all'
    ? 'Choose a specific class above to auto-lock this to the correct report card max marks.'
    : '';
}

// ── Resolves which legacy Annual Report Card slot (Term 1/2 × FA1/FA2/SA1)
// an Examination's marks should be mirrored into. Prefers the explicit
// "Report Card Slot" set on the exam in Exam Master (reliable, user-picked);
// falls back to guessing from the exam's TYPE/NAME text for older exams that
// don't have it set yet. Term number always comes from the exam's own
// Term/Semester — completely independent of the assessment-slot guess,
// since "Term 1"/"Term 2" says nothing about which of that term's exams
// (Unit Test 1, Unit Test 2, or Semester Exam) this is.
// BUGFIX: this used to detect the term number with a hard-coded literal
// text match (termName.toLowerCase().includes('2')). Term names are free
// text (Exam Setup → Terms lets a school call it "Semester II", "Sem 2",
// "Term Two", anything) — so any school whose 2nd term name didn't
// literally contain the digit "2" had ALL of its Term 2 marks silently
// mirrored into the Term 1 legacy keys (overwriting real Term 1 marks and
// leaving Term 2 empty). That produced blank/wrong Term 2 columns on the
// Annual/Final Report Card even after Result Processing was completed and
// locked for Term 2. Fixed to use the term's position (order 1 = first
// term, order 2 = second term) via termId — the same stable, name-agnostic
// method already used by examCheckResultProcessingReady/examFindSA1ExamForTerm.
function examGetLegacyTermAssess(exam) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetLegacyTermAssess(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetLegacyTermAssess(exam);
  }
  const orderedTerms = (typeof examGetOrderedTerms === 'function') ? examGetOrderedTerms() : [];
  const termIdx = orderedTerms.findIndex(t => t.id === exam?.termId);
  let termNum;
  if (termIdx !== -1) {
    termNum = String(termIdx + 1);
  } else {
    // Fallback for an exam whose term no longer exists in Exam Setup —
    // keep the old text-match as a last resort rather than failing outright.
    const termName = (exam?.termName || '').toLowerCase();
    termNum = termName.includes('2') ? '2' : '1';
  }

  if (exam?.rcSlot === 'NONE') return { termNum, assessKey: null };
  if (exam?.rcSlot === 'FA1' || exam?.rcSlot === 'FA2' || exam?.rcSlot === 'SA1') {
    return { termNum, assessKey: exam.rcSlot };
  }
  // Fallback for exams created before this field existed.
  const assessKey = examInferRcSlot(`${exam?.typeName || ''} ${exam?.name || ''}`);
  return { termNum, assessKey: assessKey === 'NONE' ? null : assessKey };
}

// DIAGNOSTIC (additive, read-only) — call examAuditRcMapping() from the
// browser console to verify every exam is correctly mapped before
// generating report cards. The Annual/Semester 1 Report Card total is only
// as accurate as this mapping: Term 1 needs exactly one exam resolving to
// FA1, one to FA2, and one to SA1 — and the same for Term 2. This prints a
// table showing, per exam, which Term Number and Report Card Slot it will
// actually be filed under (and whether that slot was explicitly set on the
// exam or guessed from its name), plus warnings for anything that looks
// misconfigured (missing/duplicate FA1/FA2/SA1 per term).
function examAuditRcMapping() {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examAuditRcMapping(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examAuditRcMapping();
  }
  const exams = examRetrieve('examinations', []);
  const orderedTerms = (typeof examGetOrderedTerms === 'function') ? examGetOrderedTerms() : [];
  const rows = exams.map(ex => {
    const resolved = examGetLegacyTermAssess(ex);
    return {
      'Exam Name': ex.name || '(unnamed)',
      'Term (as set)': orderedTerms.find(t => t.id === ex.termId)?.name || ex.termName || '(none)',
      'Resolved Term #': resolved.termNum,
      'Report Card Slot': resolved.assessKey || 'NONE',
      'Slot Source': (ex.rcSlot === 'FA1' || ex.rcSlot === 'FA2' || ex.rcSlot === 'SA1' || ex.rcSlot === 'NONE') ? 'explicit' : 'guessed from name'
    };
  });
  console.table(rows);

  const byTerm = {};
  rows.forEach(r => {
    const t = r['Resolved Term #'];
    byTerm[t] = byTerm[t] || {};
    const slot = r['Report Card Slot'];
    byTerm[t][slot] = (byTerm[t][slot] || 0) + 1;
  });
  const warnings = [];
  Object.keys(byTerm).forEach(t => {
    ['FA1', 'FA2', 'SA1'].forEach(slot => {
      const count = byTerm[t][slot] || 0;
      if (count === 0) warnings.push(`Term ${t}: no exam is mapped to ${slot} — that column will show 0 on the report card.`);
      if (count > 1) warnings.push(`Term ${t}: ${count} exams are mapped to ${slot} — the later save wins and overwrites the earlier one.`);
    });
  });
  if (warnings.length) {
    console.warn('Report Card mapping issues found:\n' + warnings.join('\n'));
  } else {
    console.log('Report Card mapping looks correct: every term has exactly one FA1, one FA2, and one SA1 exam.');
  }
  return rows;
}

// Resyncs an exam's already-saved marks into the legacy report-card store
// using the exam's CURRENT Report Card Slot (FA1/FA2/SA1). Needed because
// examMarksEngineSyncLegacyBridge only runs at the moment marks are saved
// in Marks Entry — if an exam's Report Card Slot is corrected AFTER marks
// were already entered (e.g. Unit Test 2 was wrongly set to FA1 and later
// fixed to FA2), the previously-saved marks stay mirrored under the old
// slot until they're re-synced. This reads straight from
// AcademicEngine.Marks (the actual source of truth for what was entered
// in Marks Entry) so nothing needs to be manually re-typed. Call from the
// browser console: examResyncLegacyForExam('<examId>') — get the id from
// examAuditRcMapping() or the Marks Entry exam dropdown.
function examResyncLegacyForExam(examId) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examResyncLegacyForExam(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examResyncLegacyForExam(examId);
  }
  if (typeof getMarks !== 'function' || typeof saveMarkData !== 'function') {
    console.error('Legacy report card marks store is not available on this page.');
    return null;
  }
  const AE = window.AcademicEngine;
  if (!AE || !AE.Subjects || typeof AE.Subjects.getByExam !== 'function' || !AE.Marks || typeof AE.Marks.getAll !== 'function') {
    console.error('AcademicEngine.Subjects/Marks are not loaded on this page.');
    return null;
  }
  const exam = examRetrieve('examinations', []).find(e => e.id === examId);
  if (!exam) { console.error('No exam found with id: ' + examId); return null; }

  const resolved = examGetLegacyTermAssess(exam);
  if (!resolved.assessKey) {
    console.warn('"' + exam.name + '" has Report Card Slot = "Not counted in Annual Report Card" — nothing to sync.');
    return null;
  }

  const maps = AE.Subjects.getByExam(examId) || [];
  if (!maps.length) {
    console.warn('No subjects are configured for "' + exam.name + '".');
    return null;
  }

  const legacy = getMarks();
  let studentsTouched = 0;
  const subjectsTouched = [];

  maps.forEach(function (map) {
    const className = map.className;
    const division = map.division || 'All';
    const subjectSafeKey = (map.subjectName || 'subject').replace(/[^a-z0-9]/gi, '_');
    let marksForMap;
    try { marksForMap = AE.Marks.getAll(examId, className, division, map.id) || {}; }
    catch (e) { marksForMap = {}; }

    let touchedThisSubject = false;
    Object.keys(marksForMap).forEach(function (studentId) {
      const rec = marksForMap[studentId];
      if (!rec || rec.total == null) return;
      const legacyKey = examGetLegacyMarksKey(exam, className, studentId);
      if (!legacyKey) return;
      if (!legacy[legacyKey]) legacy[legacyKey] = {};
      legacy[legacyKey][subjectSafeKey] = rec.total;
      studentsTouched++;
      touchedThisSubject = true;
    });
    if (touchedThisSubject) subjectsTouched.push(map.subjectName + ' (' + className + (division !== 'All' ? '-' + division : '') + ')');
  });

  saveMarkData(legacy);
  console.log('Resynced "' + exam.name + '" into Term ' + resolved.termNum + ' / ' + resolved.assessKey + ': ' +
    studentsTouched + ' mark(s) across ' + subjectsTouched.length + ' subject(s).');
  if (subjectsTouched.length) console.table(subjectsTouched.map(function (s) { return { Subject: s }; }));
  return { termNum: resolved.termNum, assessKey: resolved.assessKey, studentsTouched: studentsTouched, subjects: subjectsTouched };
}

function examOpenCreateExamModal(editId = null) {
  const exams   = examRetrieve('examinations', []);
  const years   = examRetrieve('academicYears', []);
  const terms   = examRetrieve('terms', []);
  const types   = examRetrieve('examTypes', []);
  const ex      = editId ? exams.find(e => e.id === editId) : null;

  const classOptions = examGetClassOptions();
  const rcSlotDefault = ex ? (ex.rcSlot || examInferRcSlot(`${ex.typeName || ''} ${ex.name || ''}`)) : examInferRcSlot('');

  const body = `
    <div class="exam-modal-grid-2">
      <div class="exam-form-group exam-col-span-2">
        <label class="exam-label">Examination Name *</label>
        <input type="text" id="emName" class="exam-input" placeholder="e.g. Unit Test 1 — Class 5" value="${ex ? examSanitize(ex.name) : ''}" oninput="examAutoSuggestRcSlot()"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Exam Type *</label>
        <select id="emType" class="exam-select" onchange="examAutoSuggestRcSlot()">
          <option value="">— Select —</option>
          ${types.map(t => `<option value="${t.id}" ${ex && ex.typeId===t.id ? 'selected':''}>${examSanitize(t.name)}</option>`).join('')}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Report Card Slot *</label>
        <select id="emRcSlot" class="exam-select" onchange="examAutoSetMaxMarks()">
          <option value="FA1" ${rcSlotDefault==='FA1' ? 'selected':''}>Formative 1 — 1st Unit Test (e.g. Unit Test 1 / Unit Test 3)</option>
          <option value="FA2" ${rcSlotDefault==='FA2' ? 'selected':''}>Formative 2 — 2nd Unit Test (e.g. Unit Test 2 / Unit Test 4)</option>
          <option value="SA1" ${rcSlotDefault==='SA1' ? 'selected':''}>Summative — Semester/Final Exam</option>
          <option value="NONE" ${rcSlotDefault==='NONE' ? 'selected':''}>Not counted in Annual Report Card</option>
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Academic Year *</label>
        <select id="emYear" class="exam-select">
          <option value="">— Select —</option>
          ${years.map(y => `<option value="${y.id}" ${ex && ex.yearId===y.id ? 'selected':''}>${examSanitize(y.name)}</option>`).join('')}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Term / Semester *</label>
        <select id="emTerm" class="exam-select">
          <option value="">— Select —</option>
          ${terms.map(t => `<option value="${t.id}" ${ex && ex.termId===t.id ? 'selected':''}>${examSanitize(t.name)}</option>`).join('')}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Applicable Class</label>
        <select id="emClass" class="exam-select" onchange="examAutoSetMaxMarks()">
          <option value="all">All Classes</option>
          ${classOptions.map(c => `<option value="${c}" ${ex && ex.applicableClass===c ? 'selected':''}>${examSanitize(c)}</option>`).join('')}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Start Date *</label>
        <input type="date" id="emStart" class="exam-input" value="${ex ? ex.startDate : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">End Date *</label>
        <input type="date" id="emEnd" class="exam-input" value="${ex ? ex.endDate : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Theory Max Marks</label>
        <input type="number" id="emTheoryMax" class="exam-input" min="0" value="${ex ? ex.theoryMax : 80}"/>
        <small id="emMaxMarksHint" class="exam-section-desc" style="display:block;margin-top:4px;"></small>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Practical Max Marks</label>
        <input type="number" id="emPractMax" class="exam-input" min="0" value="${ex ? ex.practMax : 20}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Internal Max Marks</label>
        <input type="number" id="emIntMax" class="exam-input" min="0" value="${ex ? ex.intMax : 0}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Pass Marks (%)</label>
        <input type="number" id="emPassPct" class="exam-input" min="0" max="100" value="${ex ? ex.passPct : 35}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Grace Marks Limit</label>
        <input type="number" id="emGrace" class="exam-input" min="0" value="${ex ? ex.graceLimitMarks : 5}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Result Publish Date</label>
        <input type="date" id="emPublishDate" class="exam-input" value="${ex ? ex.publishDate : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Grade Scale</label>
        <select id="emGradeScale" class="exam-select">
          ${examGetGradeScaleOptions(ex ? ex.gradeScaleId : '')}
        </select>
      </div>
      <div class="exam-form-group exam-col-span-2">
        <label class="exam-label">Remarks / Instructions</label>
        <textarea id="emRemarks" class="exam-textarea" placeholder="Optional instructions for invigilators or teachers">${ex ? examSanitize(ex.remarks) : ''}</textarea>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Exam Fee (₹)</label>
        <input type="number" id="emExamFee" class="exam-input" min="0" placeholder="0 = no separate fee" value="${ex ? (ex.examFee || 0) : 0}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Re-Exam Late Fee (₹)</label>
        <input type="number" id="emLateFee" class="exam-input" min="0" placeholder="Charged for re-exam/late entries" value="${ex ? (ex.lateFee || 0) : 0}"/>
      </div>
    </div>`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Cancel</button>
    <button class="exam-btn exam-btn-primary" onclick="examSaveExamination('${editId || ''}')">
      ${editId ? 'Update Examination' : 'Create Examination'}
    </button>`;

  examOpenModal(editId ? 'Edit Examination' : 'New Examination', body, footer, true);
  setTimeout(() => { if (typeof examAutoSetMaxMarks === 'function') examAutoSetMaxMarks(); }, 50);
}

function examSaveExamination(editId) {
  const name = document.getElementById('emName').value.trim();
  const typeId = document.getElementById('emType').value;
  const yearId = document.getElementById('emYear').value;
  const termId = document.getElementById('emTerm').value;
  const startDate = document.getElementById('emStart').value;
  const endDate = document.getElementById('emEnd').value;

  if (!name || !typeId || !yearId || !termId || !startDate || !endDate) {
    examShowToast('Please fill all required fields', 'danger'); return;
  }

  const exams = examRetrieve('examinations', []);
  const types = examRetrieve('examTypes', []);
  const years = examRetrieve('academicYears', []);
  const terms = examRetrieve('terms', []);

  const typeName = (types.find(t => t.id === typeId) || {}).name || '';
  const yearName = (years.find(y => y.id === yearId) || {}).name || '';
  const termName = (terms.find(t => t.id === termId) || {}).name || '';

  const obj = {
    name, typeId, typeName, yearId, yearName, termId, termName,
    rcSlot: document.getElementById('emRcSlot')?.value || 'SA1',
    applicableClass: document.getElementById('emClass').value,
    startDate, endDate,
    theoryMax: parseFloat(document.getElementById('emTheoryMax').value) || 80,
    practMax:  parseFloat(document.getElementById('emPractMax').value)  || 0,
    intMax:    parseFloat(document.getElementById('emIntMax').value)     || 0,
    passPct:   parseFloat(document.getElementById('emPassPct').value)    || 35,
    graceLimitMarks: parseFloat(document.getElementById('emGrace').value) || 5,
    publishDate: document.getElementById('emPublishDate').value,
    gradeScaleId: document.getElementById('emGradeScale').value,
    remarks: document.getElementById('emRemarks').value.trim(),
    examFee: parseFloat(document.getElementById('emExamFee').value) || 0,
    lateFee: parseFloat(document.getElementById('emLateFee').value) || 0,
    status: 'draft',
    isLocked: false,
    isPublished: false,
  };

  if (editId) {
    const idx = exams.findIndex(e => e.id === editId);
    if (idx > -1) exams[idx] = { ...exams[idx], ...obj };
  } else {
    exams.push({ id: examUID(), ...obj, createdAt: new Date().toISOString() });
  }

  examStore('examinations', exams);
  examCloseModal();
  examRenderMasterTable();
  examShowToast(editId ? 'Examination updated' : 'Examination created', 'success');
}

function examDeleteExamination(id) {
  if (!confirm('Delete this examination? Timetable, marks, and results linked to it will also be removed.')) return;
  examStore('examinations', examRetrieve('examinations', []).filter(e => e.id !== id));
  examStore('timetable', examRetrieve('timetable', []).filter(s => s.examId !== id));
  examStore('subjectMap', examRetrieve('subjectMap', []).filter(s => s.examId !== id));
  // Marks keyed per exam+class+div+subject — remove by exam prefix
  const allKeys = Object.keys(localStorage).filter(k => k.startsWith(EXAM_STORAGE_PREFIX + 'marks_' + id));
  allKeys.forEach(k => localStorage.removeItem(k));
  examRenderMasterTable();
  examShowToast('Examination deleted', 'danger');
}

/* ═══════════════════════════════════════════════
   SECTION I2 — EXAM FEE / RE-EXAM LATE FEE
   ↔ FINANCE CENTER LINKAGE
   Posts collected exam fees / re-exam late fees into
   the same fee_transactions + student_ledger storage
   that Finance Center → All Receipts already reads,
   tagged with ledger:'exam' so they show up there
   alongside School/Transport/Inventory receipts.
═══════════════════════════════════════════════ */

function examOpenFeeCollectionModal(examId) {
  const exam = examRetrieve('examinations', []).find(e => e.id === examId);
  if (!exam) { examShowToast('Examination not found', 'danger'); return; }

  const allStudents = (typeof getStudents === 'function') ? getStudents() : [];
  const pool = (exam.applicableClass && exam.applicableClass !== 'all')
    ? allStudents.filter(s => s.cls === exam.applicableClass)
    : allStudents;

  const body = `
    <div class="exam-form-group">
      <label class="exam-label">Student</label>
      <select id="efStudent" class="exam-select">
        <option value="">— Select Student —</option>
        ${pool.map(s => `<option value="${s.id}">${examSanitize(s.name)} — ${examSanitize(s.cls)} ${examSanitize(s.div)}</option>`).join('')}
      </select>
    </div>
    <div class="exam-modal-grid-2" style="margin-top:10px;">
      <div class="exam-form-group">
        <label class="exam-label">Fee Type</label>
        <select id="efType" class="exam-select" onchange="document.getElementById('efAmount').value = this.value==='late' ? ${exam.lateFee || 0} : ${exam.examFee || 0};">
          <option value="exam" ${exam.examFee > 0 ? 'selected' : ''}>Exam Fee (₹${exam.examFee || 0})</option>
          <option value="late" ${exam.examFee <= 0 ? 'selected' : ''}>Re-Exam Late Fee (₹${exam.lateFee || 0})</option>
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Amount (₹)</label>
        <input type="number" id="efAmount" class="exam-input" min="0" value="${exam.examFee > 0 ? exam.examFee : exam.lateFee || 0}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Payment Mode</label>
        <select id="efMode" class="exam-select">
          <option value="Cash">Cash</option>
          <option value="Online">Online</option>
          <option value="Cheque">Cheque</option>
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Date</label>
        <input type="date" id="efDate" class="exam-input" value="${new Date().toISOString().slice(0,10)}"/>
      </div>
    </div>`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Cancel</button>
    <button class="exam-btn exam-btn-primary" onclick="examCollectFee('${examId}')">💾 Collect &amp; Post to Finance Center</button>`;

  examOpenModal(`Collect Fee — ${examSanitize(exam.name)}`, body, footer);
}

function examCollectFee(examId) {
  const exam = examRetrieve('examinations', []).find(e => e.id === examId);
  const studentId = document.getElementById('efStudent').value;
  const feeType = document.getElementById('efType').value;
  const amount = Number(document.getElementById('efAmount').value || 0);
  const paymentMode = document.getElementById('efMode').value;
  const date = document.getElementById('efDate').value || new Date().toISOString().slice(0,10);

  if (!studentId) { examShowToast('Please select a student', 'danger'); return; }
  if (amount <= 0) { examShowToast('Enter a valid amount', 'danger'); return; }
  if (typeof getFeeTransactions !== 'function' || typeof saveFeeTransactions !== 'function') {
    examShowToast('Finance Center linkage unavailable', 'danger'); return;
  }

  const student = (typeof getStudents === 'function') ? getStudents().find(s => s.id === studentId) : null;
  const particular = (feeType === 'late' ? 'Re-Exam Late Fee — ' : 'Exam Fee — ') + (exam ? exam.name : '');

  // 1) Finance Center → All Receipts (fee_transactions, ledger:'exam')
  const tx = getFeeTransactions();
  tx.push({
    id: 'TX' + Date.now(),
    receiptNo: 'EX' + Date.now(),
    studentId,
    academicYear: student ? student.acyr : '',
    ledger: 'exam',
    installment: feeType === 'late' ? 'Re-Exam Late Fee' : 'Exam Fee',
    amount,
    paymentMode,
    remarks: particular,
    collectedBy: (typeof currentUser !== 'undefined' && currentUser?.username) || 'System',
    date,
    examId
  });
  saveFeeTransactions(tx);

  // 2) Per-student ledger (so it shows on the student's Account Statement too)
  if (typeof addStudentLedgerEntry === 'function') {
    addStudentLedgerEntry({
      studentId, date, head: 'Examination',
      transactionType: 'Receipt', particular,
      debit: 0, credit: amount,
      receiptNo: 'EX' + Date.now(), paymentMode, remarks: particular
    });
  }

  // 3) Track collection inside the exam module too, for the exam's own records
  const collections = examRetrieve('feeCollections', []);
  collections.push({ id: examUID(), examId, studentId, feeType, amount, paymentMode, date, createdAt: new Date().toISOString() });
  examStore('feeCollections', collections);

  examCloseModal();
  examShowToast('Fee collected and posted to Finance Center', 'success');
}

function examRenderMasterTable() {
  const exams   = examRetrieve('examinations', []);
  const query   = (document.getElementById('examMasterSearch')?.value || '').toLowerCase();
  const yearFil = document.getElementById('examMasterFilterYear')?.value || '';

  // Populate year filter
  const years = examRetrieve('academicYears', []);
  const yf = document.getElementById('examMasterFilterYear');
  if (yf) {
    const prev = yf.value;
    yf.innerHTML = '<option value="">All Years</option>' +
      years.map(y => `<option value="${y.id}" ${y.id === prev ? 'selected':''}>${examSanitize(y.name)}</option>`).join('');
  }

  const statusColors = { draft: 'exam-badge-warning', active: 'exam-badge-success', locked: 'exam-badge-danger', published: 'exam-badge-info' };
  const filtered = exams.filter(e => {
    const matchQ = !query || e.name.toLowerCase().includes(query) || e.typeName.toLowerCase().includes(query);
    const matchY = !yearFil || e.yearId === yearFil;
    return matchQ && matchY;
  });

  const tbody = document.getElementById('examMasterTableBody');
  if (!tbody) return;

  if (!filtered.length) {
    tbody.innerHTML = `<tr><td colspan="12" style="text-align:center;padding:32px;color:var(--exam-text-muted)">No examinations found</td></tr>`;
    return;
  }

  const rcSlotLabels = { FA1: 'FA1 (UT1)', FA2: 'FA2 (UT2)', SA1: 'SA1 (Sem)', NONE: '— not counted —' };
  tbody.innerHTML = filtered.map(e => {
    const totalMax = (e.theoryMax || 0) + (e.practMax || 0) + (e.intMax || 0);
    const passMarks = Math.ceil(totalMax * (e.passPct || 35) / 100);
    const status = e.isPublished ? 'published' : e.isLocked ? 'locked' : e.status || 'draft';
    const { assessKey } = examGetLegacyTermAssess(e);
    const rcSlotShown = e.rcSlot || assessKey || 'SA1';
    return `
    <tr>
      <td><strong>${examSanitize(e.name)}</strong></td>
      <td>${examSanitize(e.typeName)}</td>
      <td><span class="exam-badge exam-badge-info">${rcSlotLabels[rcSlotShown] || rcSlotShown}</span></td>
      <td>${examSanitize(e.yearName)}</td>
      <td>${examSanitize(e.termName)}</td>
      <td>${examSanitize(e.applicableClass || 'All')}</td>
      <td>${examFormatDate(e.startDate)}</td>
      <td>${examFormatDate(e.endDate)}</td>
      <td>${totalMax}</td>
      <td>${passMarks} (${e.passPct}%)</td>
      <td><span class="exam-badge ${statusColors[status] || 'exam-badge-neutral'}">${status}</span></td>
      <td>
        <div class="exam-row-gap-8">
          <button class="exam-btn exam-btn-sm exam-btn-ghost" onclick="examOpenCreateExamModal('${e.id}')">✎ Edit</button>
          ${(e.examFee > 0 || e.lateFee > 0) ? `<button class="exam-btn exam-btn-sm exam-btn-outline" onclick="examOpenFeeCollectionModal('${e.id}')">₹ Collect Fee</button>` : ''}
          <button class="exam-btn exam-btn-sm exam-btn-ghost" onclick="examDeleteExamination('${e.id}')" style="color:var(--exam-red)">✕</button>
        </div>
      </td>
    </tr>`;
  }).join('');
}

function examFilterMasterTable() { examRenderMasterTable(); }

function examExportMasterCSV() {
  const exams = examRetrieve('examinations', []);
  const rows = [['Name','Type','RC Slot','Year','Term','Class','Start','End','Max Marks','Pass%','Status']];
  exams.forEach(e => {
    const totalMax = (e.theoryMax || 0) + (e.practMax || 0) + (e.intMax || 0);
    const { assessKey } = examGetLegacyTermAssess(e);
    rows.push([e.name, e.typeName, e.rcSlot || assessKey || 'SA1', e.yearName, e.termName, e.applicableClass || 'All',
      e.startDate, e.endDate, totalMax, e.passPct,
      e.isPublished ? 'Published' : e.isLocked ? 'Locked' : e.status]);
  });
  examCSVDownload('examination_master.csv', rows);
  examShowToast('CSV exported', 'info');
}

/* ═══════════════════════════════════════════════
   SECTION J — TIMETABLE
═══════════════════════════════════════════════ */

function examPopulateTTFilter() {
  const exams = examRetrieve('examinations', []);
  const sel = document.getElementById('ttExamFilter');
  if (!sel) return;
  const prev = sel.value;
  sel.innerHTML = '<option value="">— Select Examination —</option>' +
    exams.map(e => `<option value="${e.id}" ${e.id === prev ? 'selected':''}>${examSanitize(e.name)}</option>`).join('');
  if (prev) examRenderTimetable();
}

function examOpenTimetableEntryModal(editId = null) {
  const examId = document.getElementById('ttExamFilter')?.value;
  if (!examId) { examShowToast('Select an examination first', 'warning'); return; }

  const slots = examRetrieve('timetable', []);
  const ex = editId ? slots.find(s => s.id === editId) : null;
  const subjectMaps = examRetrieve('subjectMap', []).filter(s => s.examId === examId);
  const classOptions = [...new Set(subjectMaps.map(s => s.className))];

  const body = `
    <div class="exam-modal-grid-2">
      <div class="exam-form-group">
        <label class="exam-label">Date *</label>
        <input type="date" id="ttDate" class="exam-input" value="${ex ? ex.date : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Day</label>
        <input type="text" id="ttDay" class="exam-input" placeholder="Monday" value="${ex ? ex.day : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Start Time *</label>
        <input type="time" id="ttStart" class="exam-input" value="${ex ? ex.startTime : '09:00'}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">End Time *</label>
        <input type="time" id="ttEnd" class="exam-input" value="${ex ? ex.endTime : '11:00'}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Class *</label>
        <select id="ttClass" class="exam-select" onchange="examTTPopulateSubjects()">
          <option value="">— Select —</option>
          ${classOptions.map(c => `<option value="${c}" ${ex && ex.className===c ? 'selected':''}>${examSanitize(c)}</option>`).join('')}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Subject *</label>
        <select id="ttSubject" class="exam-select">
          <option value="">— Select —</option>
          ${ex ? `<option value="${ex.subjectName}" selected>${examSanitize(ex.subjectName)}</option>` : ''}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Room / Hall</label>
        <input type="text" id="ttRoom" class="exam-input" placeholder="Hall A" value="${ex ? ex.room : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Invigilator</label>
        <input type="text" id="ttInvig" class="exam-input" placeholder="Teacher name" value="${ex ? ex.invigilator : ''}"/>
      </div>
    </div>`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Cancel</button>
    <button class="exam-btn exam-btn-primary" onclick="examSaveTimetableSlot('${editId || ''}', '${examId}')">
      ${editId ? 'Update Slot' : 'Add Slot'}
    </button>`;

  examOpenModal('Timetable Entry', body, footer);

  // Auto-fill day from date
  document.getElementById('ttDate').addEventListener('change', function () {
    const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    document.getElementById('ttDay').value = days[new Date(this.value).getDay()];
  });
}

function examTTPopulateSubjects() {
  const examId = document.getElementById('ttExamFilter')?.value;
  const className = document.getElementById('ttClass')?.value;
  if (!examId || !className) return;
  const maps = examRetrieve('subjectMap', []).filter(s => s.examId === examId && s.className === className);
  const sel = document.getElementById('ttSubject');
  if (!sel) return;
  sel.innerHTML = '<option value="">— Select —</option>' +
    maps.map(m => `<option value="${m.subjectName}">${examSanitize(m.subjectName)}</option>`).join('');
}

function examSaveTimetableSlot(editId, examId) {
  const date = document.getElementById('ttDate').value;
  const startTime = document.getElementById('ttStart').value;
  const endTime = document.getElementById('ttEnd').value;
  const className = document.getElementById('ttClass').value;
  const subjectName = document.getElementById('ttSubject').value;

  if (!date || !startTime || !endTime || !className || !subjectName) {
    examShowToast('Date, time, class, and subject are required', 'danger'); return;
  }

  const slots = examRetrieve('timetable', []);
  const obj = {
    examId, date, day: document.getElementById('ttDay').value,
    startTime, endTime, className, subjectName,
    room: document.getElementById('ttRoom').value,
    invigilator: document.getElementById('ttInvig').value,
  };

  if (editId) {
    const idx = slots.findIndex(s => s.id === editId);
    if (idx > -1) slots[idx] = { ...slots[idx], ...obj };
  } else {
    slots.push({ id: examUID(), ...obj });
  }

  examStore('timetable', slots);
  examCloseModal();
  examRenderTimetable();
  examShowToast('Timetable slot saved', 'success');
}

function examDeleteTimetableSlot(id) {
  if (!confirm('Remove this slot?')) return;
  examStore('timetable', examRetrieve('timetable', []).filter(s => s.id !== id));
  examRenderTimetable();
  examShowToast('Slot removed', 'warning');
}

function examRenderTimetable() {
  const examId = document.getElementById('ttExamFilter')?.value;
  const grid = document.getElementById('examTimetableGrid');
  if (!grid) return;

  if (!examId) {
    grid.innerHTML = '<div class="exam-empty-state"><div class="exam-empty-icon">📅</div><div>Select an examination to view or build its timetable</div></div>';
    return;
  }

  const slots = examRetrieve('timetable', []).filter(s => s.examId === examId);
  if (!slots.length) {
    grid.innerHTML = '<div class="exam-empty-state"><div class="exam-empty-icon">📅</div><div>No timetable entries yet. Click "+ Add Slot"</div></div>';
    return;
  }

  // Group by date
  const grouped = {};
  slots.sort((a, b) => a.date.localeCompare(b.date) || a.startTime.localeCompare(b.startTime));
  slots.forEach(s => {
    if (!grouped[s.date]) grouped[s.date] = [];
    grouped[s.date].push(s);
  });

  grid.innerHTML = Object.keys(grouped).map(date => {
    const daySlots = grouped[date];
    const day = daySlots[0].day || new Date(date).toLocaleDateString('en-IN', { weekday: 'long' });
    return `
      <div class="exam-tt-day-row">
        <div class="exam-tt-day-label">${day} — ${examFormatDate(date)}</div>
        <div class="exam-tt-slots">
          ${daySlots.map(s => `
            <div class="exam-tt-slot" onclick="examOpenTimetableEntryModal('${s.id}')">
              <div class="exam-tt-slot-subject">${examSanitize(s.subjectName)}</div>
              <div class="exam-tt-slot-meta">Class ${examSanitize(s.className)}${s.room ? ' • ' + examSanitize(s.room) : ''}</div>
              <div class="exam-tt-slot-time">⏰ ${s.startTime} – ${s.endTime}</div>
              ${s.invigilator ? `<div class="exam-tt-slot-meta">👤 ${examSanitize(s.invigilator)}</div>` : ''}
              <button class="exam-btn exam-btn-sm" style="margin-top:8px;font-size:10px;padding:2px 6px;background:var(--exam-red-bg);color:var(--exam-red);border-color:transparent" onclick="event.stopPropagation();examDeleteTimetableSlot('${s.id}')">Remove</button>
            </div>`).join('')}
        </div>
      </div>`;
  }).join('');
}

function examPrintTimetable() {
  const content = document.getElementById('examTimetableGrid')?.innerHTML || '';
  const win = window.open('', '', 'width=900,height=700');
  win.document.write(`<html><head><title>Exam Timetable</title>
    <style>body{font-family:sans-serif;padding:24px}
    .exam-tt-day-row{margin-bottom:24px}
    .exam-tt-day-label{font-weight:700;margin-bottom:8px;font-size:14px;text-transform:uppercase}
    .exam-tt-slots{display:flex;gap:12px;flex-wrap:wrap}
    .exam-tt-slot{border:1px solid #ddd;padding:12px;border-radius:6px;min-width:200px}
    .exam-tt-slot-subject{font-weight:700}
    button{display:none}
    </style></head><body>${content}</body></html>`);
  win.document.close();
  win.print();
}

/* ═══════════════════════════════════════════════
   SECTION K — SUBJECT MAPPING
═══════════════════════════════════════════════ */

function examGetClassOptions() {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetClassOptions(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetClassOptions();
  }
  // ERP INTEGRATION: uses Dnyanankur ERP's canonical class order
  // (matches the <select id="r-class"> options in Student Registration).
  // Falls back to deriving classes from actual student records if the
  // canonical list is ever unavailable.
  const ERP_CLASS_ORDER = ['Nursery','Jr.KG','Sr.KG','1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th','11th','12th'];
  try {
    if (typeof getStudents === 'function') {
      const students = getStudents();
      const present = new Set(students.map(s => s.cls).filter(Boolean));
      // Always offer the full canonical list (so empty classes can still be configured),
      // but order it correctly regardless of insertion order in storage.
      return ERP_CLASS_ORDER.filter(c => present.size === 0 || true);
    }
  } catch (e) {}
  return ERP_CLASS_ORDER;
}

function examGetTeacherOptions() {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetTeacherOptions(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetTeacherOptions();
  }
  // ERP INTEGRATION: reads from the ERP's own getTeachers() (includes
  // DEFAULT_TEACHERS merge logic) instead of a raw localStorage read.
  try {
    if (typeof getTeachers === 'function') {
      return getTeachers().map(t => t.name).filter(Boolean);
    }
    const teachers = new Dnyanankur.Repository.TeacherRepository().getAll();
    return teachers.map(t => t.name || (t.firstName + ' ' + t.lastName)).filter(Boolean);
  } catch (e) {}
  return [];
}

function examGetTeacherOptionsWithId() {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetTeacherOptionsWithId(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetTeacherOptionsWithId();
  }
  // [Phase 16.3] Additive — {id, name} pairs for the Subject Mapping teacher
  // dropdown, alongside the existing name-only examGetTeacherOptions() (kept
  // untouched for any other caller). Lets Subject Mapping store a real
  // teacherId instead of a free-text name, without breaking anything that
  // still reads the old `teacher` string field.
  try {
    if (typeof getTeachers === 'function') {
      return getTeachers().map(t => ({ id: t.id, name: t.name })).filter(t => t.name);
    }
  } catch (e) {}
  return [];
}

function examGetGradeScaleOptions(selectedId = '') {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetGradeScaleOptions(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetGradeScaleOptions(selectedId);
  }
  const scales = examRetrieve('gradeScales', []);
  return '<option value="">Default Scale</option>' +
    scales.map(s => `<option value="${s.id}" ${s.id === selectedId ? 'selected':''}>${examSanitize(s.name)}</option>`).join('');
}

function examOpenSubjectMapModal(editId = null, prefill = null) {
  const maps    = examRetrieve('subjectMap', []);
  const exams   = examRetrieve('examinations', []);
  const ex      = editId ? maps.find(m => m.id === editId) : null;
  const classes = examGetClassOptions();
  const teachers = examGetTeacherOptionsWithId();
  const pfExamId = ex ? ex.examId : (prefill?.examId || '');
  const pfClass  = ex ? ex.className : (prefill?.className || '');
  const pfDiv    = ex ? ex.division : (prefill?.division || 'All');

  // [Phase 16.3] Bridge (not merge): for a *new* mapping, pre-fill the
  // teacher from any existing TeacherSubjectAssignment for this
  // class+division+subject, rather than leaving the dropdown blank. The
  // Principal can still override it — this is only a convenience default.
  let pfTeacherId = ex ? (ex.teacherId || '') : '';
  if (!ex && window.AcademicEngine && AcademicEngine.TeacherAssignments && prefill) {
    try {
      const matches = AcademicEngine.TeacherAssignments.getByClassDivision(prefill.className || pfClass, prefill.division || pfDiv);
      if (matches && matches.length) pfTeacherId = matches[0].teacherId;
    } catch (e) {}
  }

  const body = `
    <div class="exam-modal-grid-2">
      <div class="exam-form-group">
        <label class="exam-label">Examination *</label>
        <select id="smExamSel" class="exam-select">
          <option value="">— Select —</option>
          ${exams.map(e => `<option value="${e.id}" ${pfExamId===e.id ? 'selected':''}>${examSanitize(e.name)}</option>`).join('')}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Class *</label>
        <select id="smClassSel" class="exam-select">
          <option value="">— Select —</option>
          ${classes.map(c => `<option value="${c}" ${pfClass===c ? 'selected':''}>${examSanitize(c)}</option>`).join('')}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Division</label>
        <input type="text" id="smDivision" class="exam-input" placeholder="A / B / All" value="${ex ? examSanitize(ex.division) : examSanitize(pfDiv)}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Subject Name *</label>
        <input type="text" id="smSubjectName" class="exam-input" placeholder="e.g. Mathematics" value="${ex ? examSanitize(ex.subjectName) : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Subject Code</label>
        <input type="text" id="smSubjectCode" class="exam-input" placeholder="e.g. MATH" value="${ex ? examSanitize(ex.subjectCode) : ''}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Teacher</label>
        <select id="smTeacher" class="exam-select">
          <option value="">— None —</option>
          ${teachers.map(t => `<option value="${t.id}" ${pfTeacherId===t.id ? 'selected':''}>${examSanitize(t.name)}</option>`).join('')}
        </select>
      </div>
      <hr class="exam-modal-divider exam-col-span-2"/>
      <div class="exam-form-group">
        <label class="exam-label">Theory Max Marks</label>
        <input type="number" id="smTheory" class="exam-input" min="0" value="${ex ? ex.theoryMax : 80}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Practical Max Marks</label>
        <input type="number" id="smPract" class="exam-input" min="0" value="${ex ? ex.practMax : 0}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Internal Max Marks</label>
        <input type="number" id="smInt" class="exam-input" min="0" value="${ex ? ex.intMax : 0}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Pass % for this Subject</label>
        <input type="number" id="smPassPct" class="exam-input" min="0" max="100" value="${ex ? ex.passPct : 35}"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Allow Grace Marks?</label>
        <select id="smGrace" class="exam-select">
          <option value="yes" ${!ex || ex.hasGrace==='yes' ? 'selected':''}>Yes</option>
          <option value="no"  ${ex && ex.hasGrace==='no'  ? 'selected':''}>No</option>
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Subject is Optional?</label>
        <select id="smOptional" class="exam-select">
          <option value="no"  ${!ex || !ex.isOptional ? 'selected':''}>No</option>
          <option value="yes" ${ex && ex.isOptional ? 'selected':''}>Yes</option>
        </select>
      </div>
    </div>`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Cancel</button>
    <button class="exam-btn exam-btn-primary" onclick="examSaveSubjectMap('${editId || ''}')">
      ${editId ? 'Update Mapping' : 'Add Mapping'}
    </button>`;

  examOpenModal('Subject Mapping', body, footer, true);
}

function examSaveSubjectMap(editId) {
  const examId = document.getElementById('smExamSel').value;
  const className = document.getElementById('smClassSel').value;
  const subjectName = document.getElementById('smSubjectName').value.trim();

  if (!examId || !className || !subjectName) {
    examShowToast('Examination, class, and subject name are required', 'danger'); return;
  }

  const exams = examRetrieve('examinations', []);
  const examName = (exams.find(e => e.id === examId) || {}).name || '';

  const maps = examRetrieve('subjectMap', []);
  // [Phase 16.3] smTeacher's value is now a teacherId (see examGetTeacherOptionsWithId());
  // resolve it back to a display name so the existing `teacher` string field stays
  // populated exactly as before for any code that still reads it — additive only.
  const smTeacherId = document.getElementById('smTeacher').value;
  let smTeacherName = '';
  if (smTeacherId) {
    try {
      const _t = (typeof getTeachers === 'function' ? getTeachers() : []).find(t => t.id === smTeacherId);
      smTeacherName = _t ? _t.name : '';
    } catch (e) {}
  }
  const obj = {
    examId, examName, className,
    division: document.getElementById('smDivision').value.trim() || 'All',
    subjectName, subjectCode: document.getElementById('smSubjectCode').value.trim().toUpperCase(),
    teacher: smTeacherName,     // legacy free-text field — unchanged shape, still authoritative for old readers
    teacherId: smTeacherId,     // [Phase 16.3] new — the real Teacher record id, additive
    theoryMax: parseFloat(document.getElementById('smTheory').value) || 0,
    practMax:  parseFloat(document.getElementById('smPract').value)  || 0,
    intMax:    parseFloat(document.getElementById('smInt').value)     || 0,
    passPct:   parseFloat(document.getElementById('smPassPct').value) || 35,
    hasGrace:  document.getElementById('smGrace').value,
    isOptional: document.getElementById('smOptional').value === 'yes',
  };

  if (editId) {
    const idx = maps.findIndex(m => m.id === editId);
    if (idx > -1) maps[idx] = { ...maps[idx], ...obj };
  } else {
    maps.push({ id: examUID(), ...obj });
  }

  examStore('subjectMap', maps);
  examSyncSubjectsFromMapping(); // keep getSubjects() / Annual Report Cards in sync
  examCloseModal();
  examRenderSubjectMap();
  // If Marks Entry is open on this same Exam/Class, refresh its Subject dropdown live.
  try {
    if (document.getElementById('meExam')?.value === examId && document.getElementById('meClass')?.value === className) {
      examMarksPopulateSubjects();
    }
  } catch (e) { /* Marks Entry not open — nothing to refresh */ }
  examShowToast('Subject mapping saved', 'success');
}

function examDeleteSubjectMap(id) {
  if (!confirm('Delete this subject mapping?')) return;
  examStore('subjectMap', examRetrieve('subjectMap', []).filter(m => m.id !== id));
  examSyncSubjectsFromMapping(); // keep getSubjects() in sync
  examRenderSubjectMap();
  examShowToast('Mapping removed', 'warning');
}

// ═══════════════════════════════════════════════
// CLASS MASTER SUBJECT LIST — direct editor
// Reads/writes getSubjects() / 'class_subjects' straight, so a school can
// fix an empty/incomplete subject dropdown (Marks Entry, Annual Report
// Card) in one place without having to fiddle with per-exam Subject
// Mapping rows. examEnsureSubjectMapForExam() auto-copies this list into
// every new Examination the first time that exam+class is opened.
// ═══════════════════════════════════════════════
// ═══════════════════════════════════════════════
// REPORT CARD MARKS SPLIT — per-class FA1/FA2/SA1 max marks override.
// Read by getMarkStructure() (used by Exam Master's max-marks auto-lock,
// Quick Term Entry, and both Report Cards), so changing it here updates
// the max marks everywhere consistently. The Total is always fixed at 100
// — this only lets a school redistribute IT across FA1/FA2/SA1.
// ═══════════════════════════════════════════════
function examRenderMarksSplitEditor() {
  const cls = document.getElementById('csClassSel')?.value;
  const wrap = document.getElementById('csMarksSplitWrap');
  if (!wrap) return;
  if (!cls) { wrap.innerHTML = '<div class="exam-empty-state" style="padding:12px 0;">Select a class above to view/edit its marks split.</div>'; return; }
  if (cls === '11th') { wrap.innerHTML = '<div class="exam-empty-state" style="padding:12px 0;">11th uses a single end-of-year exam mark — there is no FA1/FA2/SA1 split to configure.</div>'; return; }

  const struct = (typeof getMarkStructure === 'function') ? getMarkStructure(cls) : { fa1:25, fa2:25, sa1:50 };
  wrap.innerHTML = `
    <div style="display:flex;gap:14px;align-items:flex-end;flex-wrap:wrap;">
      <div class="exam-form-group">
        <label class="exam-label">FA1 (Unit Test 1/3)</label>
        <input type="number" id="msFA1" class="exam-input" min="0" max="100" value="${struct.fa1}" oninput="examRecalcMarksSplitTotal()" style="width:90px;"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">FA2 (Unit Test 2/4)</label>
        <input type="number" id="msFA2" class="exam-input" min="0" max="100" value="${struct.fa2}" oninput="examRecalcMarksSplitTotal()" style="width:90px;"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">SA1 (Semester Exam)</label>
        <input type="number" id="msSA1" class="exam-input" min="0" max="100" value="${struct.sa1}" oninput="examRecalcMarksSplitTotal()" style="width:90px;"/>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Total (fixed)</label>
        <div id="msTotalDisplay" style="font-weight:800;font-size:18px;padding:8px 0;color:#10b981;">100</div>
      </div>
      <button class="exam-btn exam-btn-primary" onclick="examSaveMarksSplit()">💾 Save Split</button>
    </div>
    <p id="msWarning" class="exam-section-desc" style="margin-top:8px;color:#ef4444;display:none;"></p>`;
}

function examRecalcMarksSplitTotal() {
  const fa1 = Number(document.getElementById('msFA1')?.value) || 0;
  const fa2 = Number(document.getElementById('msFA2')?.value) || 0;
  const sa1 = Number(document.getElementById('msSA1')?.value) || 0;
  const total = fa1 + fa2 + sa1;
  const disp = document.getElementById('msTotalDisplay');
  const warn = document.getElementById('msWarning');
  if (disp) { disp.textContent = total; disp.style.color = total === 100 ? '#10b981' : '#ef4444'; }
  if (warn) {
    if (total !== 100) { warn.style.display = ''; warn.textContent = `FA1 + FA2 + SA1 must add up to 100 — currently ${total}. Adjust before saving.`; }
    else warn.style.display = 'none';
  }
}

function examSaveMarksSplit() {
  const cls = document.getElementById('csClassSel')?.value;
  if (!cls) return;
  const fa1 = Number(document.getElementById('msFA1')?.value) || 0;
  const fa2 = Number(document.getElementById('msFA2')?.value) || 0;
  const sa1 = Number(document.getElementById('msSA1')?.value) || 0;
  if (fa1 + fa2 + sa1 !== 100) { examShowToast('FA1 + FA2 + SA1 must add up to 100 — not saved', 'danger'); return; }
  const overrides = (typeof LS !== 'undefined') ? (LS.get('class_mark_structure') || {}) : {};
  overrides[cls] = { fa1, fa2, sa1 };
  if (typeof LS !== 'undefined') LS.set('class_mark_structure', overrides);
  examShowToast(`Marks split saved for ${cls} — FA1:${fa1} + FA2:${fa2} + SA1:${sa1} = 100`, 'success');
}

function examRenderClassSubjectsEditor() {
  const cls = document.getElementById('csClassSel')?.value;
  const wrap = document.getElementById('csSubjectChips');
  if (!wrap) return;
  if (!cls) { wrap.innerHTML = '<div class="exam-empty-state" style="padding:8px 0;">Select a class to view/edit its subject list.</div>'; return; }
  const subjects = ((typeof getSubjects === 'function') ? getSubjects() : {})[cls] || [];
  if (!subjects.length) {
    wrap.innerHTML = '<div class="exam-empty-state" style="padding:8px 0;">No subjects yet for this class — add one above, or it will stay empty in Marks Entry / Report Cards.</div>';
    return;
  }
  wrap.innerHTML = subjects.map((s, i) => `
    <span class="exam-badge exam-badge-info" style="display:inline-flex;align-items:center;gap:6px;padding:6px 10px;font-size:12px;">
      ${examSanitize(s)}
      <button type="button" onclick="examRemoveClassSubject(${i})" title="Remove" style="background:none;border:none;cursor:pointer;color:inherit;font-weight:700;padding:0;line-height:1;">✕</button>
    </span>`).join('');
}

function examAddClassSubject() {
  const cls = document.getElementById('csClassSel')?.value;
  const input = document.getElementById('csNewSubject');
  const name = input?.value.trim();
  if (!cls) { examShowToast('Select a class first', 'warning'); return; }
  if (!name) { examShowToast('Enter a subject name', 'warning'); return; }
  const all = (typeof getSubjects === 'function') ? getSubjects() : {};
  const list = [...(all[cls] || [])];
  if (list.some(s => s.toLowerCase() === name.toLowerCase())) { examShowToast('Subject already in the list', 'warning'); return; }
  list.push(name);
  const merged = { ...all, [cls]: list };
  if (typeof LS !== 'undefined') LS.set('class_subjects', merged);
  input.value = '';
  examRenderClassSubjectsEditor();
  examShowToast(`"${name}" added to ${cls}`, 'success');
}

function examRemoveClassSubject(index) {
  const cls = document.getElementById('csClassSel')?.value;
  if (!cls) return;
  const all = (typeof getSubjects === 'function') ? getSubjects() : {};
  const list = [...(all[cls] || [])];
  const name = list[index];
  if (name === undefined) return;
  if (!confirm(`Remove "${name}" from ${cls}'s subject list?\n\nExisting marks already entered for this subject are NOT deleted, but it will stop appearing in new exams and report cards for this class.`)) return;
  list.splice(index, 1);
  const merged = { ...all, [cls]: list };
  if (typeof LS !== 'undefined') LS.set('class_subjects', merged);
  examRenderClassSubjectsEditor();
  examShowToast(`"${name}" removed from ${cls}`, 'warning');
}

// Subject Mapping is class-based only now (no per-exam mapping UI) — this
// just keeps the Class Master Subject List's class dropdown + chips in sync
// whenever the Subject Mapping tab is opened.
function examRenderSubjectMap() {
  const classes = examGetClassOptions();
  const cs = document.getElementById('csClassSel');
  if (cs) {
    const prev = cs.value;
    cs.innerHTML = '<option value="">— Select Class —</option>' +
      classes.map(c => `<option value="${c}" ${c === prev ? 'selected':''}>${examSanitize(c)}</option>`).join('');
    examRenderClassSubjectsEditor();
    examRenderMarksSplitEditor();
  }
}

// Exports every class's fixed subject list (the same list used by Annual
// Report Cards and every exam's Marks Entry) as a simple CSV.
function examExportClassSubjectsCSV() {
  const all = (typeof getSubjects === 'function') ? getSubjects() : {};
  const rows = [['Class','Subjects']];
  Object.keys(all).forEach(cls => rows.push([cls, (all[cls] || []).join('; ')]));
  examCSVDownload('class_subjects.csv', rows);
  examShowToast('CSV exported', 'info');
}

function examExportSubjectMapCSV() {
  const maps = examRetrieve('subjectMap', []);
  const rows = [['Class','Division','Subject','Code','Exam','Theory Max','Pract Max','Internal Max','Pass%','Grace','Teacher']];
  maps.forEach(m => rows.push([m.className,m.division,m.subjectName,m.subjectCode||'',m.examName,m.theoryMax,m.practMax,m.intMax,m.passPct,m.hasGrace,m.teacher||'']));
  examCSVDownload('subject_mapping.csv', rows);
  examShowToast('CSV exported', 'info');
}

/* ═══════════════════════════════════════════════
   SECTION L — MARKS ENTRY
═══════════════════════════════════════════════ */

function examPopulateMarksExamFilter() {
  const exams = examRetrieve('examinations', []);
  const sel = document.getElementById('meExam');
  if (!sel) return;
  sel.innerHTML = '<option value="">— Select —</option>' +
    exams.map(e => `<option value="${e.id}">${examSanitize(e.name)}</option>`).join('');
  document.getElementById('meClass').innerHTML = '<option value="">— Select —</option>';
  document.getElementById('meDivision').innerHTML = '<option value="">— Select —</option>';
  document.getElementById('meSubject').innerHTML = '<option value="">— Select —</option>';
}

function examMarksPopulateClasses() {
  const examId = document.getElementById('meExam').value;
  const maps = examRetrieve('subjectMap', []).filter(m => m.examId === examId);
  let classes = [...new Set(maps.map(m => m.className))];

  // ERP LINKAGE: teachers are locked to their classAssignments (the same
  // assignments set in Teacher Management / used to lock the Register page),
  // so they only see marks-entry for classes/divisions actually assigned to them.
  if (typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'teacher' && !currentUser.viewAll) {
    const assignments = currentUser.classAssignments || [];
    const allowedClasses = new Set(assignments.map(a => a.split('-')[0]));
    if (allowedClasses.size > 0) classes = classes.filter(c => allowedClasses.has(c));
  }

  const sel = document.getElementById('meClass');
  sel.innerHTML = '<option value="">— Select —</option>' +
    classes.sort().map(c => `<option value="${c}">${examSanitize(c)}</option>`).join('');
  document.getElementById('meDivision').innerHTML = '<option value="">— Select —</option>';
  document.getElementById('meSubject').innerHTML = '<option value="">— Select —</option>';
  document.getElementById('examMarksGridCard').style.display = 'none';
}

// Auto-provisions Subject Mapping rows for an exam+class from the Class
// Master Subject List (Subject Mapping → "Class Master Subject List" /
// getSubjects()). Runs every time this exam+class is opened in Marks Entry —
// NOT just the first time — and only ADDS whichever master-list subjects
// are still missing for that exam+class, so a partially-mapped exam keeps
// catching up as the master list grows, instead of getting stuck forever
// with whatever subset happened to exist when it was first opened.
function examEnsureSubjectMapForExam(examId, className) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examEnsureSubjectMapForExam(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examEnsureSubjectMapForExam(examId, className);
  }
  if (!examId || !className) return;
  const maps = examRetrieve('subjectMap', []);
  const existingForExamClass = maps.filter(m => m.examId === examId && m.className === className);
  const existingNames = new Set(existingForExamClass.map(m => m.subjectName));

  const subjectList = (typeof getSubjects === 'function') ? (getSubjects()[className] || []) : [];
  const missing = subjectList.filter(s => !existingNames.has(s));
  if (!missing.length) return;

  const exams = examRetrieve('examinations', []);
  const exam = exams.find(e => e.id === examId);
  const examName = exam ? exam.name : '';
  const theoryMax = exam ? (exam.theoryMax || 80) : 80;
  const practMax  = exam ? (exam.practMax  || 0)  : 0;
  const intMax    = exam ? (exam.intMax    || 0)  : 0;
  const passPct   = exam ? (exam.passPct   || 35) : 35;

  missing.forEach(subjectName => {
    maps.push({
      id: examUID(), examId, examName, className, division: 'All',
      subjectName, subjectCode: subjectName.replace(/[^a-zA-Z0-9]/g,'').substring(0,4).toUpperCase(),
      teacher: '', theoryMax, practMax, intMax, passPct, hasGrace: 'yes', isOptional: false,
      autoCreated: true
    });
  });
  examStore('subjectMap', maps);
}

// ═══════════════════════════════════════════════
// QUICK TERM ENTRY
// Since a class's subject list is fixed (Subject Mapping tab) and the same
// for every exam, this lets a teacher fill FA1 (Unit Test 1/3) + FA2 (Unit
// Test 2/4) + SA1 (Semester Exam) for one subject in a single screen,
// instead of switching the Examination dropdown 3 times. Saves are written
// straight into the legacy getMarks() store (the actual source the Annual/
// Semester 1 Report Cards read from) AND best-effort mirrored into each
// matching Exam's own per-exam records, so Result Processing/Analysis/Merit
// List keep working exactly as if marks had been entered one exam at a time.
// ═══════════════════════════════════════════════
function qtePopulateClasses() {
  const sel = document.getElementById('qteClass');
  if (!sel) return;
  const prev = sel.value;
  const classes = examGetClassOptions();
  sel.innerHTML = '<option value="">— Select —</option>' +
    classes.map(c => `<option value="${c}" ${c===prev?'selected':''}>${examSanitize(c)}</option>`).join('');
  if (prev && classes.includes(prev)) qteClassChanged();
}

function qteClassChanged() {
  const className = document.getElementById('qteClass')?.value;
  const subjSel = document.getElementById('qteSubject');
  if (!subjSel) return;
  if (!className) { subjSel.innerHTML = '<option value="">— Select Class first —</option>'; qteLoad(); return; }
  const subjects = ((typeof getSubjects === 'function') ? getSubjects() : {})[className] || [];
  subjSel.innerHTML = subjects.length
    ? subjects.map(s => `<option value="${examSanitize(s)}">${examSanitize(s)}</option>`).join('')
    : '<option value="">No subjects yet — add via Subject Mapping</option>';
  qteLoad();
}

function qteLoad() {
  const term = document.getElementById('qteTerm')?.value || '1';
  const className = document.getElementById('qteClass')?.value;
  const division = document.getElementById('qteDivision')?.value || 'All';
  const subject = document.getElementById('qteSubject')?.value;
  const table = document.getElementById('qteTable');
  const empty = document.getElementById('qteEmpty');
  const saveBtn = document.getElementById('qteSaveBtn');
  if (!table || !empty || !saveBtn) return;

  if (!className || !subject) {
    table.style.display = 'none'; empty.style.display = ''; saveBtn.style.display = 'none';
    empty.textContent = 'Select Term, Class and Subject to begin.';
    return;
  }

  const struct = (typeof getMarkStructure === 'function') ? getMarkStructure(className) : { fa1:25, fa2:25, sa1:50 };
  const fa1Head = document.getElementById('qteFA1Head');
  const fa2Head = document.getElementById('qteFA2Head');
  const sa1Head = document.getElementById('qteSA1Head');
  if (fa1Head) fa1Head.innerHTML = `FA1<br><small>Max:${struct.fa1}</small>`;
  if (fa2Head) fa2Head.innerHTML = `FA2<br><small>Max:${struct.fa2}</small>`;
  if (sa1Head) sa1Head.innerHTML = `SA1<br><small>Max:${struct.sa1}</small>`;

  const students = ((typeof getStudents === 'function') ? getStudents() : [])
    .filter(s => s.cls === className && (division === 'All' || s.div === division))
    .sort((a,b) => (Number(a.roll)||0) - (Number(b.roll)||0));

  if (!students.length) {
    table.style.display = 'none'; empty.style.display = ''; saveBtn.style.display = 'none';
    empty.textContent = 'No students found for this class/division.';
    return;
  }

  const legacy = (typeof getMarks === 'function') ? getMarks() : {};
  const safeKey = subject.replace(/[^a-z0-9]/gi,'_');
  const tbody = document.getElementById('qteBody');
  tbody.innerHTML = students.map((s,i) => {
    const fa1 = legacy[`${s.id}_T${term}_FA1`]?.[safeKey] ?? '';
    const fa2 = legacy[`${s.id}_T${term}_FA2`]?.[safeKey] ?? '';
    const sa1 = legacy[`${s.id}_T${term}_SA1`]?.[safeKey] ?? '';
    const total = (Number(fa1)||0) + (Number(fa2)||0) + (Number(sa1)||0);
    return `<tr data-sid="${s.id}">
      <td>${i+1}</td><td>${examSanitize(s.admissionNo || '—')}</td><td style="text-align:left;">${examSanitize(s.name)}</td>
      <td><input type="number" class="qte-fa1" min="0" max="${struct.fa1}" value="${fa1}" oninput="qteRecalc(this)" style="width:64px;"/></td>
      <td><input type="number" class="qte-fa2" min="0" max="${struct.fa2}" value="${fa2}" oninput="qteRecalc(this)" style="width:64px;"/></td>
      <td><input type="number" class="qte-sa1" min="0" max="${struct.sa1}" value="${sa1}" oninput="qteRecalc(this)" style="width:64px;"/></td>
      <td class="qte-total">${total}</td>
      <td class="qte-grade">${(typeof gradeFromPercent==='function') ? gradeFromPercent(total) : ''}</td>
    </tr>`;
  }).join('');

  table.style.display = ''; empty.style.display = 'none'; saveBtn.style.display = '';
  document.getElementById('qteMsg').innerHTML = '';
}

function qteRecalc(input) {
  const row = input.closest('tr');
  const fa1 = Number(row.querySelector('.qte-fa1').value) || 0;
  const fa2 = Number(row.querySelector('.qte-fa2').value) || 0;
  const sa1 = Number(row.querySelector('.qte-sa1').value) || 0;
  const total = fa1 + fa2 + sa1;
  row.querySelector('.qte-total').textContent = total;
  row.querySelector('.qte-grade').textContent = (typeof gradeFromPercent==='function') ? gradeFromPercent(total) : '';
}

function qteSaveAll() {
  const term = document.getElementById('qteTerm')?.value || '1';
  const className = document.getElementById('qteClass')?.value;
  const division = document.getElementById('qteDivision')?.value || 'All';
  const subject = document.getElementById('qteSubject')?.value;
  if (!className || !subject) { examShowToast('Select Class and Subject first', 'warning'); return; }
  if (typeof getMarks !== 'function' || typeof saveMarkData !== 'function') {
    examShowToast('Legacy marks engine not available', 'danger'); return;
  }

  const safeKey = subject.replace(/[^a-z0-9]/gi,'_');
  const legacy = getMarks();

  // Find this term's 3 exams by Report Card Slot, so we can mirror into
  // each one's own per-exam records too (Result Processing/Analysis/Merit).
  const exams = examRetrieve('examinations', []);
  const slotExam = {};
  ['FA1','FA2','SA1'].forEach(slot => {
    slotExam[slot] = exams.find(e => {
      const { termNum, assessKey } = examGetLegacyTermAssess(e);
      return termNum === term && assessKey === slot;
    });
  });

  let count = 0;
  document.querySelectorAll('#qteBody tr').forEach(row => {
    const sid = row.dataset.sid;
    const fa1 = Number(row.querySelector('.qte-fa1')?.value) || 0;
    const fa2 = Number(row.querySelector('.qte-fa2')?.value) || 0;
    const sa1 = Number(row.querySelector('.qte-sa1')?.value) || 0;
    const bySlot = { FA1: fa1, FA2: fa2, SA1: sa1 };

    Object.keys(bySlot).forEach(slot => {
      // 1) Legacy store — the actual source Report Cards read from.
      const legacyKey = `${sid}_T${term}_${slot}`;
      if (!legacy[legacyKey]) legacy[legacyKey] = {};
      legacy[legacyKey][safeKey] = bySlot[slot];

      // 2) Best-effort mirror into the matching Exam's own subjectMap-based
      // records, so Result Processing/Analysis/Merit List stay populated.
      // Repository write + grade lookup now goes through the Marks Engine
      // (bridge sync is skipped here — step 1 above already wrote the
      // legacy store directly, which is the correct behavior for Quick
      // Term Entry: it must still record marks even when no matching Exam
      // exists yet in Exam Setup, which the engine's bridge sync cannot do
      // since it needs a resolved exam to compute the legacy key).
      const exam = slotExam[slot];
      if (!exam) return;
      try {
        examEnsureSubjectMapForExam(exam.id, className);
        const maps = examRetrieve('subjectMap', []);
        const mapRow = maps.find(m => m.examId === exam.id && m.className === className &&
          m.subjectName === subject && (m.division === division || m.division === 'All'));
        if (!mapRow) return;
        // Quick Term Entry only captures a single score per slot (no
        // separate practical/internal fields), so score it against
        // theoryMax alone — matching this screen's original behavior —
        // even if the mapped subjectMap also has practMax/intMax set.
        const qteSubjectMap = { ...mapRow, practMax: 0, intMax: 0 };
        examMarksEngineSave({
          examId: exam.id, className, division: mapRow.division, mapId: mapRow.id, subjectMap: qteSubjectMap,
          students: [{ studentId: sid, theory: bySlot[slot], pract: 0, internal: 0, grace: 0, absent: false }],
          syncBridge: false, refreshResults: false
        });
      } catch (e) { /* per-exam mirror is best-effort — legacy store already has the real data */ }
    });
    count++;
  });

  saveMarkData(legacy);

  // Auto-recompute results for each of the 3 exams this save touched, so
  // Grades & Results, Result Processing, Analysis and Merit List reflect
  // it immediately — no separate manual "Compute Results" step needed.
  Object.values(slotExam).forEach(exam => {
    if (!exam) return;
    try { examRecomputeResultsForClass(exam.id, className); } catch (e) { /* best-effort */ }
  });

  examShowToast(`Saved "${subject}" — FA1+FA2+SA1 for ${count} students`, 'success');
  document.getElementById('qteMsg').innerHTML = '<span style="color:#1a6b3c;font-weight:600;">✓ Saved — reflected in Report Cards (Semester 1 &amp; Final) and Result Processing.</span>';
  setTimeout(() => { const el = document.getElementById('qteMsg'); if (el) el.innerHTML = ''; }, 6000);
}

function examMarksEntryInit() {
  const exams = examRetrieve('examinations', []);
  const examSel = document.getElementById('meExam');
  if (examSel) {
    examSel.innerHTML = '<option value="">— Select Examination —</option>' +
      exams.map(e => `<option value="${e.id}">${examSanitize(e.name)} (${examSanitize(e.typeName||'')}${e.termName ? ' · '+examSanitize(e.termName) : ''})</option>`).join('');
  }
  const classSel = document.getElementById('meClass');
  if (classSel) {
    const classes = examGetClassOptions();
    classSel.innerHTML = '<option value="">— Select Class —</option>' +
      classes.map(c => `<option value="${c}">${examSanitize(c)}</option>`).join('');
    // Teacher lock — only allow assigned classes
    if (typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'teacher' && !currentUser.viewAll) {
      const assignments = currentUser.classAssignments || [];
      const allowed = [...new Set(assignments.map(a => a.split('-')[0]))];
      if (allowed.length) {
        [...classSel.options].forEach(o => { if (o.value) o.disabled = !allowed.includes(o.value); });
      }
    }
  }
  document.getElementById('meDivision').innerHTML = '<option value="">— Select —</option>';
  document.getElementById('meSubject').innerHTML = '<option value="">— Select —</option>';
  document.getElementById('meStudent').innerHTML = '<option value="">— All Students (subject-wise entry above) —</option>';
  document.getElementById('examMarksGridCard').style.display = 'none';
  document.getElementById('meStudentViewCard').style.display = 'none';
  document.getElementById('ume-cosch-card').style.display = 'none';
}

function examMarksPopulateStudents() {
  const className = document.getElementById('meClass').value;
  const division = document.getElementById('meDivision').value;
  const sel = document.getElementById('meStudent');
  if (!sel) return;
  if (!className || !division) { sel.innerHTML = '<option value="">— All Students (subject-wise entry above) —</option>'; return; }
  const students = examGetStudentsForClass(className, division).sort((a,b)=>(a.name||'').localeCompare(b.name||''));
  sel.innerHTML = '<option value="">— All Students (subject-wise entry above) —</option>' +
    students.map(s => `<option value="${s.id}">${examSanitize(s.name)} (${examSanitize(s.admissionNo||'')})</option>`).join('');
}

function examMarksSubjectChosen() {
  document.getElementById('meStudentViewCard').style.display = 'none';
  document.getElementById('meStudent').value = '';
  examLoadMarksGrid();
}

function examMarksPopulateDivisions() {
  const examId = document.getElementById('meExam').value;
  const className = document.getElementById('meClass').value;
  examEnsureSubjectMapForExam(examId, className);
  const maps = examRetrieve('subjectMap', []).filter(m => m.examId === examId && m.className === className);
  let divs = [...new Set(maps.map(m => m.division))];

  if (typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'teacher' && !currentUser.viewAll) {
    const assignments = currentUser.classAssignments || [];
    const allowedDivs = new Set(
      assignments.filter(a => a.split('-')[0] === className).map(a => a.split('-')[1])
    );
    if (allowedDivs.size > 0) divs = divs.filter(d => allowedDivs.has(d) || d === 'All');
  }

  const sel = document.getElementById('meDivision');
  sel.innerHTML = '<option value="">— Select —</option>' +
    divs.map(d => `<option value="${d}">${examSanitize(d === 'All' ? 'All Divisions' : d)}</option>`).join('');
  document.getElementById('meSubject').innerHTML = '<option value="">— Select —</option>';
  document.getElementById('meStudent').innerHTML = '<option value="">— All Students (subject-wise entry above) —</option>';
  document.getElementById('examMarksGridCard').style.display = 'none';
  document.getElementById('meStudentViewCard').style.display = 'none';
  document.getElementById('ume-cosch-card').style.display = 'none';
}

// Quick "+ Add Subject" button on the Marks Entry screen itself. Subjects are
// fixed PER CLASS (same list for every exam of that class — Unit Test 1,
// Unit Test 2, Semester Exam, …), so this adds straight to the Class Master
// Subject List (Subject Mapping tab) and immediately re-provisions the
// currently open exam so the new subject shows up right away.
function examQuickAddSubject() {
  const className = document.getElementById('meClass')?.value;
  const examId = document.getElementById('meExam')?.value;
  if (!className) { examShowToast('Select a Class first', 'warning'); return; }
  const name = prompt(`Add a subject to ${className}'s subject list (used for every exam of this class):`);
  if (!name || !name.trim()) return;
  const all = (typeof getSubjects === 'function') ? getSubjects() : {};
  const list = [...(all[className] || [])];
  if (list.some(s => s.toLowerCase() === name.trim().toLowerCase())) { examShowToast('Subject already in the list', 'warning'); return; }
  list.push(name.trim());
  if (typeof LS !== 'undefined') LS.set('class_subjects', { ...all, [className]: list });
  if (examId) examEnsureSubjectMapForExam(examId, className);
  examMarksPopulateSubjects();
  examShowToast(`"${name.trim()}" added to ${className}'s subject list`, 'success');
}

function examMarksPopulateSubjects() {
  const examId = document.getElementById('meExam').value;
  const className = document.getElementById('meClass').value;
  const division = document.getElementById('meDivision').value;
  const maps = examRetrieve('subjectMap', []).filter(m =>
    m.examId === examId && m.className === className &&
    (m.division === division || m.division === 'All'));
  const sel = document.getElementById('meSubject');
  sel.innerHTML = '<option value="">— Select —</option>' +
    maps.map(m => `<option value="${m.id}">${examSanitize(m.subjectName)}</option>`).join('');
  const hint = document.getElementById('meSubjectEmptyHint');
  if (hint) hint.style.display = maps.length ? 'none' : '';
  document.getElementById('examMarksGridCard').style.display = 'none';
  examMarksPopulateStudents();

  // Co-scholastic (kept, KG–10th only) — derive term from the selected exam's termName.
  const struct = (typeof getMarkStructure === 'function') ? getMarkStructure(className) : {};
  const coschCard = document.getElementById('ume-cosch-card');
  if (division && struct.type !== 'college') {
    const exam = examRetrieve('examinations', []).find(e => e.id === examId);
    const termName = (exam && exam.termName || '').toLowerCase();
    const termKey = termName.includes('2') ? '2' : '1';
    _umeClass = className; _umeDiv = division; _umeTerm = termKey;
    const allStudents = (typeof getStudents === 'function') ? getStudents() : [];
    const coschStudents = allStudents.filter(s => s.cls === className && (division === 'All' || s.div === division))
      .sort((a,b) => (Number(a.roll)||0) - (Number(b.roll)||0));
    coschCard.style.display = coschStudents.length ? '' : 'none';
    if (coschStudents.length) umeRenderCosch(coschStudents, className, division, termKey);
  } else {
    coschCard.style.display = 'none';
  }
}

function examLoadMarksGrid() {
  const mapId    = document.getElementById('meSubject').value;
  const examId   = document.getElementById('meExam').value;
  const className = document.getElementById('meClass').value;
  const division  = document.getElementById('meDivision').value;

  if (!mapId || !examId || !className) return;

  const maps = examRetrieve('subjectMap', []);
  const subjectMap = maps.find(m => m.id === mapId);
  if (!subjectMap) return;

  // Get students from ERP storage (compatible)
  const allStudents = examGetStudentsForClass(className, division);

  // Load existing marks
  const marksKey = `marks_${examId}_${className}_${division}_${mapId}`;
  const savedMarks = examRetrieve(marksKey, {});

  // Check lock
  const lockKey = `marksLock_${examId}_${className}_${division}_${mapId}`;
  const subjectLocked = examRetrieve(lockKey, false);
  // BUGFIX: previously only this per-subject lock was checked here, so
  // marks stayed editable (and got silently recomputed into Result
  // Processing) even after the Principal Locked Results for the whole
  // exam. The exam-level lock now also disables this grid.
  const exams = examRetrieve('examinations', []);
  const examObj = exams.find(e => e.id === examId);
  const resultsLocked = !!(examObj && examObj.isLocked);
  const isLocked = subjectLocked || resultsLocked;

  const card = document.getElementById('examMarksGridCard');
  card.style.display = 'block';

  document.getElementById('examMarksGridTitle').textContent =
    `${subjectMap.subjectName} — Class ${className} ${division !== 'All' ? division : ''}`;

  const lockBadge = document.getElementById('examMarksLockBadge');
  lockBadge.textContent = resultsLocked ? 'Locked (Results Locked)' : (subjectLocked ? 'Locked' : 'Unlocked');
  lockBadge.className = 'exam-badge ' + (isLocked ? 'exam-badge-danger' : 'exam-badge-warning');

  const lockBtn = document.getElementById('examLockBtn');
  if (resultsLocked) {
    // Subject-level lock toggle is meaningless while the exam itself is
    // locked in Result Processing — only the Principal unlocking it there
    // can free marks entry back up, so the button is disabled with a hint
    // rather than letting a teacher "unlock" marks that are still locked.
    lockBtn.textContent = '🔒 Locked by Result Processing';
    lockBtn.disabled = true;
    lockBtn.title = 'This exam was Locked in Result Processing by the Principal. Ask them to Unlock it there before editing marks.';
    lockBtn.onclick = null;
  } else {
    lockBtn.disabled = false;
    lockBtn.title = '';
    lockBtn.textContent = subjectLocked ? '🔓 Unlock' : '🔒 Lock';
    lockBtn.onclick = () => examLockMarks();
  }

  const hasTheory   = subjectMap.theoryMax > 0;
  const hasPract    = subjectMap.practMax  > 0;
  const hasInternal = subjectMap.intMax    > 0;
  const theoryLabel = (hasPract || hasInternal) ? 'Theory' : 'Marks Obtained';

  // Build header
  const thead = document.getElementById('examMarksGridHead');
  thead.innerHTML = `<tr>
    <th style="width:40px">#</th>
    <th>Adm No</th>
    <th>Student Name</th>
    ${hasTheory   ? `<th>${theoryLabel}<br><small>Max:${subjectMap.theoryMax}</small></th>` : ''}
    ${hasPract    ? `<th>Practical<br><small>Max:${subjectMap.practMax}</small></th>` : ''}
    ${hasInternal ? `<th>Internal<br><small>Max:${subjectMap.intMax}</small></th>` : ''}
    <th>Grace</th>
    <th>Absent</th>
    <th>Total</th>
    <th>%</th>
    <th>Grade</th>
    <th>Result</th>
  </tr>`;

  // Build rows
  const tbody = document.getElementById('examMarksGridBody');
  tbody.innerHTML = '';

  if (!allStudents.length) {
    tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--exam-text-muted)">
      No students found for Class ${className}${division !== 'All' ? ' ' + division : ''}.
      Ensure students are registered in Student Management.</td></tr>`;
    examUpdateMarksStats([], subjectMap);
    return;
  }

  allStudents.forEach((student, idx) => {
    const sid = student.id || student.admissionNo || idx;
    const m = savedMarks[sid] || {};
    const isAbsent = m.absent === true;
    const row = document.createElement('tr');
    row.id = `marks_row_${sid}`;
    if (isAbsent) row.classList.add('is-absent');

    const theoryCell   = hasTheory   ? `<td><input type="number" class="marks-theory" data-sid="${sid}" min="0" max="${subjectMap.theoryMax}" value="${isAbsent ? '' : (m.theory ?? '')}" ${isLocked || isAbsent ? 'disabled' : ''} oninput="examRecalcRow('${sid}','${mapId}')"/></td>` : '';
    const practCell    = hasPract    ? `<td><input type="number" class="marks-pract"  data-sid="${sid}" min="0" max="${subjectMap.practMax}"  value="${isAbsent ? '' : (m.pract  ?? '')}" ${isLocked || isAbsent ? 'disabled' : ''} oninput="examRecalcRow('${sid}','${mapId}')"/></td>` : '';
    const internalCell = hasInternal ? `<td><input type="number" class="marks-int"    data-sid="${sid}" min="0" max="${subjectMap.intMax}"    value="${isAbsent ? '' : (m.internal ?? '')}" ${isLocked || isAbsent ? 'disabled' : ''} oninput="examRecalcRow('${sid}','${mapId}')"/></td>` : '';

    const graceMax = subjectMap.hasGrace === 'yes' ? 10 : 0;
    const graceCell = `<td><input type="number" class="marks-grace" data-sid="${sid}" min="0" max="${graceMax}" value="${isAbsent ? '' : (m.grace ?? 0)}" ${isLocked || isAbsent || graceMax===0 ? 'disabled' : ''} oninput="examRecalcRow('${sid}','${mapId}')"/></td>`;

    row.innerHTML = `
      <td style="color:var(--exam-text-muted);font-size:12px">${idx + 1}</td>
      <td><strong>${examSanitize(student.admissionNo || student.id || '—')}</strong></td>
      <td>${examSanitize(student.name || (student.firstName + ' ' + student.lastName))}</td>
      ${theoryCell}${practCell}${internalCell}${graceCell}
      <td>
        <input type="checkbox" class="exam-checkbox marks-absent" data-sid="${sid}" ${isAbsent ? 'checked' : ''} ${isLocked ? 'disabled' : ''}
          onchange="examToggleAbsent('${sid}','${mapId}')"/>
      </td>
      <td id="total_${sid}" class="marks-computed">${isAbsent ? '<span class="exam-badge exam-badge-danger">AB</span>' : (m.total ?? '—')}</td>
      <td id="pct_${sid}"   class="marks-computed">${isAbsent ? '—' : (m.pct   ? m.pct + '%' : '—')}</td>
      <td id="grade_${sid}" class="marks-computed">${isAbsent ? '—' : (m.grade  ?? '—')}</td>
      <td id="result_${sid}" class="marks-computed">
        ${isAbsent
          ? '<span class="exam-badge exam-badge-warning">Absent</span>'
          : m.result === 'Pass'
            ? '<span class="exam-badge exam-badge-success">Pass</span>'
            : m.result === 'Fail'
              ? '<span class="exam-badge exam-badge-danger">Fail</span>'
              : '—'}
      </td>`;
    tbody.appendChild(row);
  });

  // Store current context
  examCurrentMarksContext = { examId, className, division, mapId, subjectMap, marksKey, isLocked, allStudents };
  examUpdateMarksStats(allStudents.map(s => savedMarks[s.id || s.admissionNo || '']).filter(Boolean), subjectMap);
}

let examCurrentMarksContext = {};

// ─────────────────────────────────────────────────────────────
// SINGLE-STUDENT VIEW: pick one student, see/enter marks for every
// subject mapped to the selected Exam+Class at once (instead of
// scrolling through the whole class one subject at a time).
// ─────────────────────────────────────────────────────────────
let examStudentViewCtx = null;

function examLoadStudentMarksView() {
  const studentId = document.getElementById('meStudent').value;
  const examId = document.getElementById('meExam').value;
  const className = document.getElementById('meClass').value;
  const division = document.getElementById('meDivision').value;

  document.getElementById('examMarksGridCard').style.display = 'none';
  document.getElementById('meSubject').value = '';

  if (!studentId) { document.getElementById('meStudentViewCard').style.display = 'none'; return; }
  if (!examId || !className) { examShowToast('Select Examination and Class first', 'warning'); return; }

  const maps = examRetrieve('subjectMap', []).filter(m =>
    m.examId === examId && m.className === className && (m.division === division || m.division === 'All'));
  if (!maps.length) { examShowToast('No subjects mapped for this exam/class yet', 'warning'); return; }

  const students = examGetStudentsForClass(className, division);
  const student = students.find(s => s.id === studentId);
  if (!student) return;

  examStudentViewCtx = { examId, className, division, studentId, maps, student };

  document.getElementById('meStudentViewTitle').textContent =
    `${student.name} (${student.admissionNo || ''}) — ${className}${division!=='All' ? ' '+division : ''} — All Subjects`;

  const tbody = document.getElementById('meStudentViewBody');
  tbody.innerHTML = maps.map(sm => {
    const marksKey = `marks_${examId}_${className}_${sm.division}_${sm.id}`;
    const saved = examRetrieve(marksKey, {});
    const m = saved[studentId] || {};
    const isAbsent = m.absent === true;
    const hasTheory = sm.theoryMax > 0, hasPract = sm.practMax > 0, hasInt = sm.intMax > 0;
    const graceMax = sm.hasGrace === 'yes' ? 10 : 0;
    return `<tr id="msv_row_${sm.id}" data-smid="${sm.id}" class="${isAbsent?'is-absent':''}">
      <td style="font-weight:600;">${examSanitize(sm.subjectName)}</td>
      <td>${hasTheory ? `<input type="number" class="msv-theory" min="0" max="${sm.theoryMax}" value="${isAbsent?'':(m.theory??'')}" ${isAbsent?'disabled':''} data-max="${sm.theoryMax}" oninput="examRecalcStudentRow('${sm.id}')" style="width:60px;"/>` : '—'}</td>
      <td>${hasPract  ? `<input type="number" class="msv-pract"  min="0" max="${sm.practMax}"  value="${isAbsent?'':(m.pract ??'')}" ${isAbsent?'disabled':''} data-max="${sm.practMax}"  oninput="examRecalcStudentRow('${sm.id}')" style="width:60px;"/>` : '—'}</td>
      <td>${hasInt    ? `<input type="number" class="msv-int"    min="0" max="${sm.intMax}"    value="${isAbsent?'':(m.internal??'')}" ${isAbsent?'disabled':''} data-max="${sm.intMax}"    oninput="examRecalcStudentRow('${sm.id}')" style="width:60px;"/>` : '—'}</td>
      <td>${graceMax>0 ? `<input type="number" class="msv-grace"  min="0" max="${graceMax}"    value="${isAbsent?'':(m.grace??0)}" ${isAbsent?'disabled':''} data-max="${graceMax}" oninput="examRecalcStudentRow('${sm.id}')" style="width:50px;"/>` : '—'}</td>
      <td><input type="checkbox" class="msv-absent" ${isAbsent?'checked':''} onchange="examToggleStudentAbsent('${sm.id}')"/></td>
      <td id="msv_total_${sm.id}" class="marks-computed">${isAbsent?'AB':(m.total??'—')}</td>
      <td id="msv_pct_${sm.id}" class="marks-computed">${isAbsent?'—':(m.pct?m.pct+'%':'—')}</td>
      <td id="msv_grade_${sm.id}" class="marks-computed">${isAbsent?'—':(m.grade??'—')}</td>
      <td id="msv_result_${sm.id}" class="marks-computed">${isAbsent?'Absent':(m.result??'—')}</td>
    </tr>`;
  }).join('');

  document.getElementById('meStudentViewCard').style.display = '';
  document.getElementById('meStudentViewMsg').innerHTML = '';
}

function examRecalcStudentRow(smId) {
  const ctx = examStudentViewCtx;
  if (!ctx) return;
  const sm = ctx.maps.find(m => m.id === smId);
  if (!sm) return;
  const row = document.getElementById(`msv_row_${smId}`);
  const theory = row.querySelector('.msv-theory') ? examClamp(row.querySelector('.msv-theory').value, 0, sm.theoryMax) : 0;
  const pract  = row.querySelector('.msv-pract')  ? examClamp(row.querySelector('.msv-pract').value,  0, sm.practMax)  : 0;
  const intern = row.querySelector('.msv-int')    ? examClamp(row.querySelector('.msv-int').value,    0, sm.intMax)    : 0;
  const grace  = row.querySelector('.msv-grace')  ? examClamp(row.querySelector('.msv-grace').value,  0, sm.hasGrace==='yes'?10:0) : 0;
  const { total, pct, passed, grade } = examComputeSubjectResult(theory, pract, intern, grace, sm, examGetExamGradeScaleId(ctx.examId));
  document.getElementById(`msv_total_${smId}`).textContent = examRound(total,1);
  document.getElementById(`msv_pct_${smId}`).textContent = pct+'%';
  document.getElementById(`msv_grade_${smId}`).textContent = grade;
  document.getElementById(`msv_result_${smId}`).textContent = passed ? 'Pass' : 'Fail';
}

function examToggleStudentAbsent(smId) {
  const row = document.getElementById(`msv_row_${smId}`);
  const cb = row.querySelector('.msv-absent');
  const isAbsent = cb.checked;
  row.classList.toggle('is-absent', isAbsent);
  ['msv-theory','msv-pract','msv-int','msv-grace'].forEach(cls => {
    const el = row.querySelector('.'+cls);
    if (el) { el.disabled = isAbsent; if (isAbsent) el.value=''; }
  });
  document.getElementById(`msv_total_${smId}`).textContent = isAbsent ? 'AB' : '—';
  document.getElementById(`msv_pct_${smId}`).textContent = '—';
  document.getElementById(`msv_grade_${smId}`).textContent = '—';
  document.getElementById(`msv_result_${smId}`).textContent = isAbsent ? 'Absent' : '—';
}

function examSaveStudentMarksView() {
  const ctx = examStudentViewCtx;
  if (!ctx) { examShowToast('Select a student first', 'warning'); return; }
  if (typeof isActiveYearLocked === 'function' && isActiveYearLocked()) {
    examShowToast('Academic year is locked — ask Principal to unlock', 'danger'); return;
  }

  ctx.maps.forEach(sm => {
    const row = document.getElementById(`msv_row_${sm.id}`);
    if (!row) return;
    const isAbsent = row.querySelector('.msv-absent').checked;
    const theory = row.querySelector('.msv-theory') ? row.querySelector('.msv-theory').value : 0;
    const pract  = row.querySelector('.msv-pract')  ? row.querySelector('.msv-pract').value  : 0;
    const intern = row.querySelector('.msv-int')    ? row.querySelector('.msv-int').value    : 0;
    const grace  = row.querySelector('.msv-grace')  ? row.querySelector('.msv-grace').value  : 0;

    examMarksEngineSave({
      examId: ctx.examId, className: ctx.className, division: sm.division,
      mapId: sm.id, subjectMap: sm,
      students: [{
        studentId: ctx.studentId, name: ctx.student.name, admissionNo: ctx.student.admissionNo,
        theory, pract, internal: intern, grace, absent: isAbsent
      }],
      refreshResults: false // batched once below, after every subject for this student is saved
    });
  });

  // Auto-recompute results for this exam+class so Grades & Results, Result
  // Processing, Analysis and Merit List reflect this save immediately.
  try { examRecomputeResultsForClass(ctx.examId, ctx.className); } catch (e) { /* best-effort */ }

  document.getElementById('meStudentViewMsg').innerHTML = '<span style="color:#1a6b3c;font-weight:600;">✓ All subjects saved for this student — reflected in Grades, Result Processing, Analysis, Merit List and Report Cards.</span>';
  setTimeout(()=>{ const el=document.getElementById('meStudentViewMsg'); if(el) el.innerHTML=''; }, 5000);
  examShowToast('Marks saved for ' + ctx.student.name, 'success');
}

// Resolves the exact getMarks() key that an Exam+Class's marks should be
// mirrored into — matching whichever function actually reads that class's
// data (buildReportCard / build11thReportCard / build11thSemester1ReportCard).
//   • 11th uses a single end-of-year "EXAM" format with NO FA1/FA2/SA1
//     buckets, so it can't share the generic Term+slot key below:
//       - Term 1 Semester Exam  → `{studentId}_T11_SEM1_EXAM` (Semester 1 Report Card)
//       - Term 2 Semester Exam  → `{studentId}_T11_EXAM`      (Final Report Card — same
//         key the old ERP always used, kept as-is for backward compatibility)
//       - Unit Tests for 11th aren't part of either report card, so they're skipped.
//   • Every other class uses the generic `{studentId}_T{term}_{FA1|FA2|SA1}` key.
function examGetLegacyMarksKey(exam, className, studentId) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetLegacyMarksKey(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetLegacyMarksKey(exam, className, studentId);
  }
  const { termNum, assessKey } = examGetLegacyTermAssess(exam);
  if (!assessKey) return null;
  if (className === '11th') {
    if (assessKey !== 'SA1') return null; // 11th's report card only tracks the semester-end exam
    return termNum === '2' ? `${studentId}_T11_EXAM` : `${studentId}_T11_SEM1_EXAM`;
  }
  return `${studentId}_T${termNum}_${assessKey}`;
}

/* ═══════════════════════════════════════════════════════════════
   SPRINT 7.4 — MARKS ENGINE CONSOLIDATION
   ───────────────────────────────────────────────────────────────
   Every Marks Entry screen (Classic grid, Single-Student View, Quick
   Term Entry, Unified Marks Entry) used to duplicate its own copy of:
   validation/clamping, subject-total + pass/fail computation, grade
   lookup, the repository write (marks_{examId}_{class}_{div}_{mapId}),
   the legacy report-card bridge mirror, and the Result Processing
   refresh. That duplication is exactly how screens could drift out of
   sync with each other.

   examMarksEngineSave() is now the ONLY place that performs the write:
     Screen (reads its own DOM/inputs)
       → examMarksEngineSave()   [validation, totals, grade, repository]
           → examMarksEngineSyncLegacyBridge()   [bridge — kept, not removed]
           → examRecomputeResultsForClass()      [result refresh → examMod_results]

   No UI, layout, or screen behavior changes here — screens still read
   their own inputs exactly as before, they just call this instead of
   repeating the computation/write logic themselves.
═══════════════════════════════════════════════════════════════ */

/**
 * examComputeSubjectResult(theory, pract, internal, grace, subjectMap, gradeScaleId)
 *
 * SPRINT 7.4 — MARKS ENGINE CONSOLIDATION (subject-level formula)
 * ─────────────────────────────────────────────────────────────
 * The core per-subject formula (total → % → theory-pass-independently
 * → overall pass/fail → grade) was independently re-implemented in THREE
 * places: examMarksEngineSave() [the canonical save], examRecalcRow()
 * [live preview on the main Marks Entry grid], and examRecalcStudentRow()
 * [live preview on the Student View editor]. All three used the exact same
 * math, so a change to one (e.g. the theory-pass rule) could silently drift
 * from the other two. This helper is now the ONLY place that formula lives;
 * the three call sites just format/display the result for their own screen.
 * No UI, layout, or screen behavior changes — inputs/outputs are identical.
 *
 * @param {number} theory   - clamped theory marks
 * @param {number} pract    - clamped practical marks
 * @param {number} internal - clamped internal marks
 * @param {number} grace    - clamped grace marks
 * @param {object} subjectMap - {theoryMax, practMax, intMax, passPct}
 * @param {string} [gradeScaleId] - grade scale id (passed to examCalcGrade)
 * @param {boolean} [isAbsent=false]
 * @returns {{maxTotal:number, total:number, pct:number, passMarks:number, theoryPass:boolean, passed:boolean, result:string, grade:string}}
 */
function examComputeSubjectResult(theory, pract, internal, grace, subjectMap, gradeScaleId, isAbsent = false) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examComputeSubjectResult(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examComputeSubjectResult(theory, pract, internal, grace, subjectMap, gradeScaleId, isAbsent);
  }
  const sm = subjectMap || {};
  const maxTotal = (sm.theoryMax || 0) + (sm.practMax || 0) + (sm.intMax || 0);
  const total = isAbsent ? 0 : (theory || 0) + (pract || 0) + (internal || 0) + (grace || 0);
  const pct = (isAbsent || maxTotal === 0) ? 0 : examRound((total / maxTotal) * 100);
  const passMarks = maxTotal * ((sm.passPct || 0) / 100);
  const theoryPass = sm.theoryMax > 0 ? theory >= (sm.theoryMax * (sm.passPct || 0) / 100) : true;
  const passed = !isAbsent && total >= passMarks && theoryPass;
  const result = isAbsent ? 'Absent' : (passed ? 'Pass' : 'Fail');
  const grade = isAbsent ? 'AB' : examCalcGrade(pct, gradeScaleId || '');
  return { maxTotal, total, pct, passMarks, theoryPass, passed, result, grade };
}

/**
 * examMarksEngineSave(params)
 * The single write path for student marks in a subject.
 *
 * @param {string}  params.examId
 * @param {string}  params.className
 * @param {string}  params.division      - division to store under (subjectMap.division / 'All' / a specific div)
 * @param {string}  params.mapId         - subjectMap row id
 * @param {object}  params.subjectMap    - the subjectMap row (theoryMax/practMax/intMax/passPct/hasGrace/subjectName)
 * @param {Array}   params.students      - [{ studentId, name, admissionNo, theory, pract, internal, grace, absent }]
 * @param {boolean} [params.syncBridge=true]     - mirror into legacy getMarks()/saveMarkData()
 * @param {boolean} [params.refreshResults=true] - recompute examMod_results for this exam+class
 * @returns {{ savedMarks: object, marksKey: string } | null}
 */
function examMarksEngineSave(params) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examMarksEngineSave(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examMarksEngineSave(params);
  }
  const {
    examId, className, division, mapId, subjectMap,
    students, syncBridge = true, refreshResults = true
  } = params || {};

  if (!examId || !className || !mapId || !subjectMap || !Array.isArray(students)) {
    console.warn('[Marks Engine] Invalid call — missing examId/className/mapId/subjectMap/students', params);
    return null;
  }

  const sm = subjectMap;
  const scaleId = (typeof examGetExamGradeScaleId === 'function') ? examGetExamGradeScaleId(examId) : '';

  const savedMarks = {};
  students.forEach(entry => {
    const isAbsent = !!entry.absent;
    const theory   = examClamp(entry.theory   || 0, 0, sm.theoryMax || 0);
    const pract    = examClamp(entry.pract    || 0, 0, sm.practMax  || 0);
    const internal = examClamp(entry.internal || 0, 0, sm.intMax    || 0);
    const grace    = examClamp(entry.grace    || 0, 0, sm.hasGrace === 'yes' ? 10 : 0);

    const { total, pct, result, grade } = examComputeSubjectResult(theory, pract, internal, grace, sm, scaleId, isAbsent);

    savedMarks[entry.studentId] = {
      studentId: entry.studentId, name: entry.name, admissionNo: entry.admissionNo,
      theory, pract, internal, grace, total, pct, grade, result, absent: isAbsent,
      savedAt: new Date().toISOString()
    };
  });

  const marksKey = `marks_${examId}_${className}_${division}_${mapId}`;
  examStore(marksKey, savedMarks);

  if (syncBridge) {
    try {
      examMarksEngineSyncLegacyBridge(examId, className, sm.subjectName, savedMarks);
    } catch (e) {
      // Bridge failure must never be silent, and must never block the exam-module
      // save that already succeeded above — only the legacy mirror is affected.
      console.warn('[Marks Engine] Legacy report-card bridge sync failed for exam '
        + examId + ', class ' + className + '. Marks Engine save succeeded, but the '
        + 'Annual/Semester-1 report card mirror was NOT updated and may show stale data.', e);
      try { examLog('Legacy report-card bridge sync failed: ' + (e && e.message ? e.message : e), 'error'); } catch (_) {}
    }
  }

  if (refreshResults) {
    try { examRecomputeResultsForClass(examId, className); } catch (e) { /* best-effort */ }
  }

  return { savedMarks, marksKey };
}

/**
 * examMarksEngineSyncLegacyBridge(examId, className, subjectName, savedMarks)
 * The ONE place that mirrors exam-module marks into the legacy
 * getMarks()/saveMarkData() store that buildReportCard() / build11thReportCard() /
 * buildSemester1ReportCard() / build11thSemester1ReportCard() read from.
 * The bridge itself is unchanged — this just centralizes who calls it.
 */
function examMarksEngineSyncLegacyBridge(examId, className, subjectName, savedMarks) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examMarksEngineSyncLegacyBridge(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examMarksEngineSyncLegacyBridge(examId, className, subjectName, savedMarks);
  }
  if (typeof getMarks !== 'function' || typeof saveMarkData !== 'function') return;
  const exam = examRetrieve('examinations', []).find(e => e.id === examId);
  const subjectSafeKey = (subjectName || 'subject').replace(/[^a-z0-9]/gi, '_');
  const legacy = getMarks();
  Object.values(savedMarks).forEach(m => {
    const legacyKey = examGetLegacyMarksKey(exam, className, m.studentId);
    if (!legacyKey) return;
    if (!legacy[legacyKey]) legacy[legacyKey] = {};
    legacy[legacyKey][subjectSafeKey] = m.total;
  });
  saveMarkData(legacy);
}

function examGetStudentsForClass(className, division) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetStudentsForClass(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetStudentsForClass(className, division);
  }
  // ERP INTEGRATION: reads via the ERP's own getStudents() (respects its
  // in-memory Cache) and maps the ERP's real field names:
  //   s.cls   -> class            s.div    -> division
  //   s.name  -> full name        s.admno  -> admission number
  //   s.id    -> unique student id
  // Inactive/archived students (if the ERP tags them) are excluded.
  try {
    let students;
    if (typeof getStudents === 'function') {
      students = getStudents();
    } else {
      students = new Dnyanankur.Repository.StudentRepository().getAll();
    }
    return students.filter(s => {
      if (s.inactive || s.archived) return false;
      const cls = s.cls || s.class || s.className || '';
      const div = s.div || s.division || s.section || 'A';
      const matchC = cls.toString() === className.toString();
      const matchD = division === 'All' || div === division;
      return matchC && matchD;
    }).map(s => ({
      id: s.id || s.admno,
      admissionNo: s.admno || s.id,
      name: s.name || ((s.firstName || '') + ' ' + (s.lastName || '')).trim(),
      className: s.cls,
      division: s.div,
    }));
  } catch (e) {
    return [];
  }
}

function examRecalcRow(sid, mapId) {
  const ctx = examCurrentMarksContext;
  if (!ctx || !ctx.subjectMap) return;
  const sm = ctx.subjectMap;

  const theoryEl   = document.querySelector(`.marks-theory[data-sid="${sid}"]`);
  const practEl    = document.querySelector(`.marks-pract[data-sid="${sid}"]`);
  const internalEl = document.querySelector(`.marks-int[data-sid="${sid}"]`);
  const graceEl    = document.querySelector(`.marks-grace[data-sid="${sid}"]`);

  const theory   = theoryEl   ? examClamp(theoryEl.value,   0, sm.theoryMax) : 0;
  const pract    = practEl    ? examClamp(practEl.value,    0, sm.practMax)  : 0;
  const internal = internalEl ? examClamp(internalEl.value, 0, sm.intMax)    : 0;
  const grace    = graceEl    ? examClamp(graceEl.value,    0, sm.hasGrace === 'yes' ? 10 : 0) : 0;

  const { total, pct, passed, grade } = examComputeSubjectResult(theory, pract, internal, grace, sm, examGetExamGradeScaleId(ctx.examId));

  document.getElementById(`total_${sid}`).textContent  = examRound(total, 1);
  document.getElementById(`pct_${sid}`).textContent    = pct + '%';
  document.getElementById(`grade_${sid}`).textContent  = grade;
  document.getElementById(`result_${sid}`).innerHTML   = passed
    ? '<span class="exam-badge exam-badge-success">Pass</span>'
    : '<span class="exam-badge exam-badge-danger">Fail</span>';
}

function examToggleAbsent(sid, mapId) {
  const cb = document.querySelector(`.marks-absent[data-sid="${sid}"]`);
  const row = document.getElementById(`marks_row_${sid}`);
  const isAbsent = cb?.checked;

  // Disable/enable inputs
  ['marks-theory','marks-pract','marks-int','marks-grace'].forEach(cls => {
    const el = document.querySelector(`.${cls}[data-sid="${sid}"]`);
    if (el) { el.disabled = isAbsent; if (isAbsent) el.value = ''; }
  });

  if (row) row.classList.toggle('is-absent', isAbsent);

  document.getElementById(`total_${sid}`).innerHTML  = isAbsent ? '<span class="exam-badge exam-badge-danger">AB</span>' : '—';
  document.getElementById(`pct_${sid}`).textContent  = '—';
  document.getElementById(`grade_${sid}`).textContent = '—';
  document.getElementById(`result_${sid}`).innerHTML = isAbsent
    ? '<span class="exam-badge exam-badge-warning">Absent</span>' : '—';
}

function examSaveMarks() {
  const ctx = examCurrentMarksContext;
  if (!ctx || !ctx.marksKey) { examShowToast('Load a marks grid first', 'warning'); return; }
  if (ctx.isLocked) {
    const exams = examRetrieve('examinations', []);
    const examObj = exams.find(e => e.id === ctx.examId);
    if (examObj && examObj.isLocked) {
      examShowToast('Results are Locked in Result Processing. Ask the Principal to unlock before editing marks.', 'danger');
    } else {
      examShowToast('Marks are locked. Unlock first.', 'danger');
    }
    return;
  }

  const students = ctx.allStudents.map((student, idx) => {
    const sid = student.id || student.admissionNo || idx;
    const theoryEl   = document.querySelector(`.marks-theory[data-sid="${sid}"]`);
    const practEl    = document.querySelector(`.marks-pract[data-sid="${sid}"]`);
    const internalEl = document.querySelector(`.marks-int[data-sid="${sid}"]`);
    const graceEl    = document.querySelector(`.marks-grace[data-sid="${sid}"]`);
    const absentEl   = document.querySelector(`.marks-absent[data-sid="${sid}"]`);
    return {
      studentId: sid, name: student.name, admissionNo: student.admissionNo,
      theory:   theoryEl   ? theoryEl.value   : 0,
      pract:    practEl    ? practEl.value    : 0,
      internal: internalEl ? internalEl.value : 0,
      grace:    graceEl    ? graceEl.value    : 0,
      absent:   absentEl?.checked || false,
    };
  });

  const engineResult = examMarksEngineSave({
    examId: ctx.examId, className: ctx.className, division: ctx.division,
    mapId: ctx.mapId, subjectMap: ctx.subjectMap, students
  });
  if (!engineResult) { examShowToast('Marks Engine could not save — check console', 'danger'); return; }
  const { savedMarks } = engineResult;

  examUpdateMarksStats(Object.values(savedMarks), ctx.subjectMap);
  examShowToast('Marks saved successfully', 'success');
}

function examLockMarks() {
  const ctx = examCurrentMarksContext;
  if (!ctx || !ctx.marksKey) { examShowToast('Load a marks grid first', 'warning'); return; }

  const lockKey = `marksLock_${ctx.examId}_${ctx.className}_${ctx.division}_${ctx.mapId}`;
  const currentLock = examRetrieve(lockKey, false);

  if (!currentLock) {
    if (!confirm('Lock marks? Teachers will not be able to edit after locking.')) return;
    examStore(lockKey, true);
    ctx.isLocked = true;
    document.getElementById('examMarksLockBadge').textContent = 'Locked';
    document.getElementById('examMarksLockBadge').className = 'exam-badge exam-badge-danger';
    document.getElementById('examLockBtn').textContent = '🔓 Unlock';
    // Disable all inputs
    document.querySelectorAll('#examMarksGridBody input').forEach(i => i.disabled = true);
    examShowToast('Marks locked', 'danger');
  } else {
    if (!confirm('Unlock marks for editing?')) return;
    examStore(lockKey, false);
    ctx.isLocked = false;
    document.getElementById('examMarksLockBadge').textContent = 'Unlocked';
    document.getElementById('examMarksLockBadge').className = 'exam-badge exam-badge-warning';
    document.getElementById('examLockBtn').textContent = '🔒 Lock';
    // Re-enable inputs (not absent ones)
    document.querySelectorAll('#examMarksGridBody input[type="number"]').forEach(i => {
      const sid = i.dataset.sid;
      const absentEl = document.querySelector(`.marks-absent[data-sid="${sid}"]`);
      if (!absentEl?.checked) i.disabled = false;
    });
    document.querySelectorAll('#examMarksGridBody input[type="checkbox"]').forEach(i => i.disabled = false);
    examShowToast('Marks unlocked', 'success');
  }
}

function examAutoCalculateGrades() {
  const ctx = examCurrentMarksContext;
  if (!ctx || !ctx.subjectMap) return;
  ctx.allStudents.forEach((s, idx) => {
    const sid = s.id || s.admissionNo || idx;
    examRecalcRow(sid, ctx.mapId);
  });
  examShowToast('Grades auto-calculated', 'info');
}

function examUpdateMarksStats(marksArr, subjectMap) {
  const el = document.getElementById('examMarksStats');
  if (!el) return;
  const valid = marksArr.filter(m => !m.absent);
  const absent = marksArr.filter(m => m.absent).length;
  const passed = valid.filter(m => m.result === 'Pass').length;
  const failed = valid.filter(m => m.result === 'Fail').length;
  const avg = valid.length ? examRound(valid.reduce((a, m) => a + (m.pct || 0), 0) / valid.length) : 0;
  const highest = valid.length ? Math.max(...valid.map(m => m.pct || 0)) : 0;

  el.innerHTML = `
    <span class="exam-marks-stat-item">Total: <strong>${marksArr.length}</strong></span>
    <span class="exam-marks-stat-item">Present: <strong>${valid.length}</strong></span>
    <span class="exam-marks-stat-item" style="color:var(--exam-red)">Absent: <strong>${absent}</strong></span>
    <span class="exam-marks-stat-item" style="color:var(--exam-green)">Passed: <strong>${passed}</strong></span>
    <span class="exam-marks-stat-item" style="color:var(--exam-red)">Failed: <strong>${failed}</strong></span>
    <span class="exam-marks-stat-item">Avg %: <strong>${avg}%</strong></span>
    <span class="exam-marks-stat-item">Highest: <strong>${highest}%</strong></span>
    <span class="exam-marks-stat-item">Pass %: <strong>${valid.length ? examRound((passed/valid.length)*100) : 0}%</strong></span>`;
}

