const EXAM_DEFAULT_GRADE_SCALE = {
  id: 'gs_default',
  name: 'Standard 10-Grade Scale',
  grades: [
    { grade: 'A+', minPct: 90, maxPct: 100, points: 10, remark: 'Outstanding' },
    { grade: 'A',  minPct: 80, maxPct: 89,  points: 9,  remark: 'Excellent' },
    { grade: 'B+', minPct: 70, maxPct: 79,  points: 8,  remark: 'Very Good' },
    { grade: 'B',  minPct: 60, maxPct: 69,  points: 7,  remark: 'Good' },
    { grade: 'C+', minPct: 50, maxPct: 59,  points: 6,  remark: 'Above Average' },
    { grade: 'C',  minPct: 40, maxPct: 49,  points: 5,  remark: 'Average' },
    { grade: 'D',  minPct: 35, maxPct: 39,  points: 4,  remark: 'Pass' },
    { grade: 'E',  minPct: 20, maxPct: 34,  points: 2,  remark: 'Needs Improvement' },
    { grade: 'F',  minPct: 0,  maxPct: 19,  points: 0,  remark: 'Fail' },
  ]
};

function examInitGradeScales() {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examInitGradeScales(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examInitGradeScales();
  }
  const scales = examRetrieve('gradeScales', []);
  if (!scales.length) examStore('gradeScales', [EXAM_DEFAULT_GRADE_SCALE]);
}

// ── SPRINT 7.3 — GRADE ENGINE CONSOLIDATION ─────────────────────────────
// Single lookup used by every grade-calculation site in the Examination
// Center to resolve which Grade Scale an exam is configured to use (set
// via Exam Setup → Grade Scale). Falls back to the default scale ('') if
// the exam has no override or isn't found. Centralizing this here means
// a Principal's grade-scale choice for an exam is honored consistently
// everywhere in the module, instead of some screens reading it and
// others silently defaulting.
function examGetExamGradeScaleId(examId) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetExamGradeScaleId(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetExamGradeScaleId(examId);
  }
  if (!examId) return '';
  const exam = examRetrieve('examinations', []).find(e => e.id === examId);
  return (exam && exam.gradeScaleId) || '';
}

function examCalcGrade(pct, scaleId = '') {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examCalcGrade(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examCalcGrade(pct, scaleId);
  }
  // Wrapper: delegates to AcademicEngine.Calc.grade() when available,
  // falls back to original local logic otherwise.
  if (typeof AcademicEngine !== 'undefined' &&
      AcademicEngine && AcademicEngine.Calc &&
      typeof AcademicEngine.Calc.grade === 'function') {
    try {
      return AcademicEngine.Calc.grade(pct, scaleId);
    } catch (e) {
      console.warn('[examCalcGrade] AcademicEngine.Calc.grade() failed, falling back to local logic:', e);
      // fall through to legacy logic below
    }
  }

  // --- original logic (fallback) ---
  const scales = examRetrieve('gradeScales', [EXAM_DEFAULT_GRADE_SCALE]);
  const scale = (scaleId ? scales.find(s => s.id === scaleId) : null) || scales[0] || EXAM_DEFAULT_GRADE_SCALE;
  if (!scale || !scale.grades) return '—';
  const match = scale.grades.find(g => pct >= g.minPct && pct <= g.maxPct);
  return match ? match.grade : '—';
}

function examCalcGradePoints(pct, scaleId = '') {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examCalcGradePoints(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examCalcGradePoints(pct, scaleId);
  }
  // Wrapper: delegates to AcademicEngine.Calc.gradePoints() when available,
  // falls back to original local logic otherwise.
  if (typeof AcademicEngine !== 'undefined' &&
      AcademicEngine && AcademicEngine.Calc &&
      typeof AcademicEngine.Calc.gradePoints === 'function') {
    try {
      return AcademicEngine.Calc.gradePoints(pct, scaleId);
    } catch (e) {
      console.warn('[examCalcGradePoints] AcademicEngine.Calc.gradePoints() failed, falling back to local logic:', e);
      // fall through to legacy logic below
    }
  }

  // --- original logic (fallback) ---
  const scales = examRetrieve('gradeScales', [EXAM_DEFAULT_GRADE_SCALE]);
  const scale = (scaleId ? scales.find(s => s.id === scaleId) : null) || scales[0] || EXAM_DEFAULT_GRADE_SCALE;
  if (!scale || !scale.grades) return 0;
  const match = scale.grades.find(g => pct >= g.minPct && pct <= g.maxPct);
  return match ? match.points : 0;
}

function examOpenGradeScaleModal(editId = null) {
  const scales = examRetrieve('gradeScales', []);
  const existing = editId ? scales.find(s => s.id === editId) : null;
  const grades = existing ? existing.grades : EXAM_DEFAULT_GRADE_SCALE.grades;

  const gradeRows = grades.map((g, i) => `
    <tr>
      <td><input type="text"   class="exam-input exam-input-sm gs-grade"  data-i="${i}" value="${g.grade}"  style="width:60px"/></td>
      <td><input type="number" class="exam-input exam-input-sm gs-min"    data-i="${i}" value="${g.minPct}" style="width:60px"/></td>
      <td><input type="number" class="exam-input exam-input-sm gs-max"    data-i="${i}" value="${g.maxPct}" style="width:60px"/></td>
      <td><input type="number" class="exam-input exam-input-sm gs-points" data-i="${i}" value="${g.points}" style="width:60px"/></td>
      <td><input type="text"   class="exam-input exam-input-sm gs-remark" data-i="${i}" value="${g.remark}" style="width:120px"/></td>
      <td><button class="exam-btn exam-btn-sm" style="color:var(--exam-red)" onclick="this.closest('tr').remove()">✕</button></td>
    </tr>`).join('');

  const body = `
    <div class="exam-form-group" style="margin-bottom:14px">
      <label class="exam-label">Scale Name *</label>
      <input type="text" id="gsName" class="exam-input" value="${existing ? examSanitize(existing.name) : 'New Grade Scale'}"/>
    </div>
    <div class="exam-table-wrap">
      <table class="exam-table" id="gsTable">
        <thead><tr><th>Grade</th><th>Min %</th><th>Max %</th><th>Points</th><th>Remark</th><th></th></tr></thead>
        <tbody id="gsBody">${gradeRows}</tbody>
      </table>
    </div>
    <button class="exam-btn exam-btn-sm exam-btn-ghost" style="margin-top:10px" onclick="examAddGradeRow()">+ Add Row</button>`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Cancel</button>
    <button class="exam-btn exam-btn-primary" onclick="examSaveGradeScale('${editId || ''}')">
      ${editId ? 'Update Scale' : 'Save Scale'}
    </button>`;

  examOpenModal('Grade Scale Configuration', body, footer, true);
}

function examAddGradeRow() {
  const tbody = document.getElementById('gsBody');
  if (!tbody) return;
  const i = tbody.children.length;
  const tr = document.createElement('tr');
  tr.innerHTML = `
    <td><input type="text"   class="exam-input exam-input-sm gs-grade"  data-i="${i}" style="width:60px"/></td>
    <td><input type="number" class="exam-input exam-input-sm gs-min"    data-i="${i}" style="width:60px"/></td>
    <td><input type="number" class="exam-input exam-input-sm gs-max"    data-i="${i}" style="width:60px"/></td>
    <td><input type="number" class="exam-input exam-input-sm gs-points" data-i="${i}" style="width:60px"/></td>
    <td><input type="text"   class="exam-input exam-input-sm gs-remark" data-i="${i}" style="width:120px"/></td>
    <td><button class="exam-btn exam-btn-sm" style="color:var(--exam-red)" onclick="this.closest('tr').remove()">✕</button></td>`;
  tbody.appendChild(tr);
}

function examSaveGradeScale(editId) {
  const name = document.getElementById('gsName')?.value.trim();
  if (!name) { examShowToast('Scale name required', 'danger'); return; }

  const rows = document.querySelectorAll('#gsBody tr');
  const grades = [];
  rows.forEach(row => {
    const grade  = row.querySelector('.gs-grade')?.value.trim();
    const minPct = parseFloat(row.querySelector('.gs-min')?.value) || 0;
    const maxPct = parseFloat(row.querySelector('.gs-max')?.value) || 0;
    const points = parseFloat(row.querySelector('.gs-points')?.value) || 0;
    const remark = row.querySelector('.gs-remark')?.value.trim() || '';
    if (grade) grades.push({ grade, minPct, maxPct, points, remark });
  });

  if (!grades.length) { examShowToast('Add at least one grade row', 'danger'); return; }

  const scales = examRetrieve('gradeScales', []);
  if (editId) {
    const idx = scales.findIndex(s => s.id === editId);
    if (idx > -1) scales[idx] = { ...scales[idx], name, grades };
  } else {
    scales.push({ id: examUID(), name, grades });
  }

  examStore('gradeScales', scales);
  examCloseModal();
  examRenderGradeScales();
  examShowToast('Grade scale saved', 'success');
}

function examDeleteGradeScale(id) {
  if (id === 'gs_default') { examShowToast('Default scale cannot be deleted', 'warning'); return; }
  if (!confirm('Delete this grade scale?')) return;
  examStore('gradeScales', examRetrieve('gradeScales', []).filter(s => s.id !== id));
  examRenderGradeScales();
  examShowToast('Scale deleted', 'warning');
}

function examRenderGradeScales() {
  const scales = examRetrieve('gradeScales', []);
  const el = document.getElementById('examGradeScaleList');
  if (!el) return;
  el.innerHTML = scales.map(s => `
    <div style="margin-bottom:12px;border:1px solid var(--exam-border);border-radius:var(--exam-radius-sm);overflow:hidden">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:8px 12px;background:#f8fafc;border-bottom:1px solid var(--exam-border)">
        <strong style="font-size:13px">${examSanitize(s.name)}</strong>
        <div class="exam-row-gap-8">
          <button class="exam-btn exam-btn-sm exam-btn-ghost" onclick="examOpenGradeScaleModal('${s.id}')">✎ Edit</button>
          <button class="exam-btn exam-btn-sm exam-btn-ghost" onclick="examDeleteGradeScale('${s.id}')" style="color:var(--exam-red)">✕</button>
        </div>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:4px;padding:8px 12px">
        ${(s.grades || []).map(g => `<span class="exam-badge exam-badge-neutral" title="${g.remark}">${g.grade} (${g.minPct}–${g.maxPct}%)</span>`).join('')}
      </div>
    </div>`).join('') || '<div class="exam-empty-state" style="padding:20px"><div class="exam-empty-icon">📊</div><div>No grade scales</div></div>';
}

