function examPopulatePFFilters() {
  const exams = examRetrieve('examinations', []);
  const classes = examGetClassOptions();
  ['pfExam','crExam'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    const prev = sel.value;
    sel.innerHTML = '<option value="">— Exam —</option>' +
      exams.map(e => `<option value="${e.id}" ${e.id===prev?'selected':''}>${examSanitize(e.name)}</option>`).join('');
  });
  ['pfClass','crClass'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    const prev = sel.value;
    sel.innerHTML = '<option value="">— Class —</option>' +
      classes.map(c => `<option value="${c}" ${c===prev?'selected':''}>${examSanitize(c)}</option>`).join('');
  });
}

function examPopulateCRFilters() {
  const classes = examGetClassOptions();
  const divSel = document.getElementById('crDivision');
  if (divSel) divSel.innerHTML = '<option value="">All Divisions</option>' +
    ['A','B','C','D'].map(d => `<option value="${d}">${d}</option>`).join('');
  examPopulatePFFilters();
}

function examRenderPassFail() {
  const examId = document.getElementById('pfExam')?.value;
  const className = document.getElementById('pfClass')?.value;
  const el = document.getElementById('examPassFailSummary');
  if (!el) return;

  if (!examId || !className) {
    el.innerHTML = '<div class="exam-empty-state" style="padding:20px"><div class="exam-empty-icon">📊</div><div>Select exam and class</div></div>';
    return;
  }

  const stats = examComputeClassStats(examId, className, '');
  if (!stats) {
    el.innerHTML = '<div class="exam-empty-state" style="padding:20px"><div>No marks data found. Enter marks first.</div></div>';
    return;
  }

  el.innerHTML = `
    <div class="exam-pf-grid">
      <div class="exam-pf-item exam-pf-passed">
        <div class="exam-pf-val">${stats.passed}</div>
        <div class="exam-pf-label">Passed</div>
      </div>
      <div class="exam-pf-item exam-pf-failed">
        <div class="exam-pf-val">${stats.failed}</div>
        <div class="exam-pf-label">Failed</div>
      </div>
    </div>
    <div style="padding:12px 14px;font-size:12px;color:var(--exam-text-muted)">
      Total: ${stats.total} &nbsp;|&nbsp; Absent: ${stats.absent} &nbsp;|&nbsp; Pass %: <strong>${stats.passPct}%</strong> &nbsp;|&nbsp; Avg: <strong>${stats.avgPct}%</strong>
    </div>`;
}

function examComputeClassStats(examId, className, division) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examComputeClassStats(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examComputeClassStats(examId, className, division);
  }
  // ── SPRINT 7.2 — RESULT STORE CONSOLIDATION ──────────────────────────
  // Previously this re-aggregated totals/pass-fail directly from raw
  // marks_{examId}_{class}_{div}_{mapId} records (duplicate of the
  // canonical computation already done by examRecomputeResultsForClass()).
  // Now it simply reads the canonical result store (examMod_results) so
  // Statistics (Pass/Fail) always agrees with Result Processing, Merit
  // List and Report Cards. No behavior change for callers — same return
  // shape: { total, passed, failed, absent, avgPct, passPct, students }.
  const maps = examRetrieve('subjectMap', []).filter(m =>
    m.examId === examId && m.className === className &&
    (!division || m.division === division || m.division === 'All'));
  if (!maps.length) return null;

  const allStudents = examGetStudentsForClass(className, division || 'All');
  if (!allStudents.length) return null;

  const results = examRetrieve('results', {});
  const classResults = (results[examId] && results[examId][className]) || {};

  let computed = allStudents
    .map(s => classResults[s.id])
    .filter(Boolean);
  if (division) computed = computed.filter(s => s.division === division || s.division === 'All');
  if (!computed.length) return null;

  let passed = 0, failed = 0, absentCount = 0;
  computed.forEach(s => {
    if (s.result === 'Pass') passed++;
    else if (s.result === 'Fail') failed++;
    else absentCount++;
  });

  const total = computed.length;
  const countedForAvg = computed.filter(s => s.result !== 'Absent');
  const avgPct = countedForAvg.length > 0 ? examRound(countedForAvg.reduce((a, c) => a + (c.pct || 0), 0) / countedForAvg.length) : 0;
  const passPct = (passed + failed) > 0 ? examRound((passed / (passed + failed)) * 100) : 0;

  return { total, passed, failed, absent: absentCount, avgPct, passPct, students: computed };
}

function examRenderClassResult() {
  const examId = document.getElementById('crExam')?.value;
  const className = document.getElementById('crClass')?.value;
  const division = document.getElementById('crDivision')?.value || '';
  const query = (document.getElementById('crSearch')?.value || '').toLowerCase();

  const thead = document.getElementById('examClassResultHead');
  const tbody = document.getElementById('examClassResultBody');
  if (!thead || !tbody) return;

  if (!examId || !className) {
    thead.innerHTML = '';
    tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--exam-text-muted)">Select exam and class</td></tr>`;
    return;
  }

  const maps = examRetrieve('subjectMap', []).filter(m =>
    m.examId === examId && m.className === className &&
    (!division || m.division === division || m.division === 'All'));

  const subjects = maps.map(m => m.subjectName);
  thead.innerHTML = `<th>#</th><th>Adm No</th><th>Name</th>
    ${subjects.map(s => `<th>${examSanitize(s)}</th>`).join('')}
    <th>Total</th><th>%</th><th>Grade</th><th>Rank</th><th>Result</th>`;

  const students = examGetStudentsForClass(className, division || 'All');
  const rows = [];

  // ── SPRINT 7.2 — RESULT STORE CONSOLIDATION ────────────────────────────
  // Previously this re-aggregated totals/grade/rank directly from raw
  // marks_{examId}_{class}_{div}_{mapId} records and recomputed a local
  // rank from the sorted view (which could disagree with Result
  // Processing/Merit List, and would even change if the Division filter
  // changed). Now it reads the canonical result store (examMod_results,
  // written by examRecomputeResultsForClass) so Class Result always shows
  // the same total/%/grade/rank as everywhere else in the module.
  const results = examRetrieve('results', {});
  const classResults = (results[examId] && results[examId][className]) || {};

  students.forEach(student => {
    const sr = classResults[student.id];
    const subjectMarks = sr ? (sr.subjectResults || {}) : {};
    const totalMarks = sr ? (sr.totalMarks || 0) : 0;
    const maxTotal = sr ? (sr.maxTotal || 0) : 0;
    const pct = sr ? (sr.pct || 0) : 0;
    const result = sr ? sr.result : '—';
    const grade = sr ? sr.grade : '—';
    const rank = sr ? (sr.result === 'Absent' ? '—' : sr.classRank) : '—';

    rows.push({ student, subjectMarks, totalMarks, maxTotal, pct, result, grade, rank });
  });

  // Display order unchanged (highest % first); rank itself now comes from
  // the canonical store instead of being recomputed from this sorted view.
  rows.sort((a, b) => b.pct - a.pct);

  const filtered = query ? rows.filter(r =>
    (r.student.name || '').toLowerCase().includes(query) ||
    (r.student.admissionNo || '').toString().includes(query)) : rows;

  tbody.innerHTML = filtered.map((r, i) => `
    <tr>
      <td style="color:var(--exam-text-muted)">${i + 1}</td>
      <td><strong>${examSanitize(r.student.admissionNo || '—')}</strong></td>
      <td>${examSanitize(r.student.name)}</td>
      ${subjects.map(s => {
        const m = r.subjectMarks[s];
        if (!m) return '<td style="color:var(--exam-text-light)">—</td>';
        if (m.absent) return '<td><span class="exam-badge exam-badge-warning">AB</span></td>';
        const color = m.result === 'Pass' ? 'var(--exam-green)' : 'var(--exam-red)';
        return `<td><span style="color:${color};font-weight:600">${m.total}</span> <small style="color:var(--exam-text-muted)">(${m.grade})</small></td>`;
      }).join('')}
      <td><strong>${examRound(r.totalMarks)}</strong>/${r.maxTotal}</td>
      <td><strong>${r.pct}%</strong></td>
      <td>${r.grade}</td>
      <td>${r.rank}</td>
      <td>${r.result === 'Pass'
          ? '<span class="exam-badge exam-badge-success">Pass</span>'
          : r.result === 'Fail'
            ? '<span class="exam-badge exam-badge-danger">Fail</span>'
            : '<span class="exam-badge exam-badge-warning">Absent</span>'}</td>
    </tr>`).join('') || `<tr><td colspan="${subjects.length + 9}" style="text-align:center;padding:24px;color:var(--exam-text-muted)">No data found</td></tr>`;
}

function examExportClassResultCSV() {
  const examId = document.getElementById('crExam')?.value;
  const className = document.getElementById('crClass')?.value;
  const division = document.getElementById('crDivision')?.value || '';
  if (!examId || !className) { examShowToast('Select exam and class first', 'warning'); return; }

  const maps = examRetrieve('subjectMap', []).filter(m =>
    m.examId === examId && m.className === className &&
    (!division || m.division === division || m.division === 'All'));
  const subjects = maps.map(m => m.subjectName);
  const students = examGetStudentsForClass(className, division || 'All');

  // ── SPRINT 7.2 — RESULT STORE CONSOLIDATION ────────────────────────────
  // Previously this re-aggregated totals/grade/rank from raw marks records
  // AGAIN (a third copy of the same calculation, alongside examRenderClassResult
  // and examComputeClassStats). Now it reads the canonical result store
  // (examMod_results) so the exported CSV always matches what's on screen.
  const results = examRetrieve('results', {});
  const classResults = (results[examId] && results[examId][className]) || {};

  const rows = [['Adm No','Name',...subjects,'Total','Max Total','%','Grade','Rank','Result']];
  const dataRows = [];

  students.forEach(student => {
    const sr = classResults[student.id];
    const subjectMarks = sr ? (sr.subjectResults || {}) : {};
    const subjectCells = subjects.map(s => {
      const m = subjectMarks[s];
      if (!m) return '';
      return m.absent ? 'AB' : m.total;
    });
    const totalMarks = sr ? (sr.totalMarks || 0) : 0;
    const maxTotal = sr ? (sr.maxTotal || 0) : 0;
    const pct = sr ? (sr.pct || 0) : 0;
    const result = sr ? sr.result : '—';
    const grade = sr ? sr.grade : '—';
    const rank = sr ? (sr.result === 'Absent' ? '—' : sr.classRank) : '—';
    dataRows.push({ row: [student.admissionNo || '', student.name, ...subjectCells, examRound(totalMarks), maxTotal, pct, grade, rank, result], pct });
  });

  dataRows.sort((a,b) => b.pct - a.pct);
  dataRows.forEach(r => rows.push(r.row));
  examCSVDownload(`class_result_${className}.csv`, rows);
  examShowToast('CSV exported', 'info');
}

/* ═══════════════════════════════════════════════
   SECTION O — RESULT PROCESSING
═══════════════════════════════════════════════ */

function examPopulateRPFilters() {
  // Result Processing only shows the two semester-level examinations.
  // Unit Tests are formative and not processed/published here.
  const SEM_OPTIONS = [
    { id: 'sem1', name: 'Semester 1 (Term 1 Final)' },
    { id: 'sem2', name: 'Semester 2 / Annual (Term 2 Final)' },
  ];

  let classes = examGetClassOptions();

  // Teacher lock — only their own assigned classes show up.
  const isTeacherLocked = typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'teacher' && !currentUser.viewAll;
  if (isTeacherLocked) {
    const assignments = currentUser.classAssignments || [];
    const allowed = [...new Set(assignments.map(a => a.split('-')[0]))];
    if (allowed.length) classes = classes.filter(c => allowed.includes(c));
  }

  ['rpExam','rpRankExam'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    // Merge with any real exam records that are tagged as semester exams
    const allExams = examRetrieve('examinations', []);
    const semExams = allExams.filter(e => {
      const n = (e.name || '').toLowerCase();
      return n.includes('semester') || n.includes('sem ') || n.includes('sem1') || n.includes('sem2') || n.includes('annual') || n.includes('half yearly') || n.includes('final');
    });

    let options = '<option value="">— Select —</option>';
    if (semExams.length > 0) {
      // Use real exam records when they exist
      options += semExams.map(e => `<option value="${e.id}">${examSanitize(e.name)}</option>`).join('');
    } else {
      // Fallback: fixed Sem 1 / Sem 2 options
      options += SEM_OPTIONS.map(o => `<option value="${o.id}">${o.name}</option>`).join('');
    }
    sel.innerHTML = options;
  });

  ['rpClass','rpRankClass'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    sel.innerHTML = '<option value="">All Classes</option>' +
      classes.map(c => `<option value="${c}">${examSanitize(c)}</option>`).join('');
  });

  examResultProcessApplyRoleView();
}

// Result Processing looks and behaves differently for Teacher vs Principal:
//  • Principal — full control: Compute, Lock, Publish, Unlock, any class.
//  • Teacher   — can Compute/preview results ONLY for their own assigned
//    class(es); Lock/Publish/Unlock are hidden (those are administrative,
//    school-wide actions reserved for the Principal).
function examResultProcessApplyRoleView() {
  const banner = document.getElementById('rpRoleBanner');
  const adminActions = document.getElementById('rpAdminActions');
  const placeDateCard = document.getElementById('rpPlaceDateCard');
  const isTeacher = typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'teacher' && !currentUser.viewAll;

  if (adminActions) adminActions.style.display = isTeacher ? 'none' : '';
  if (placeDateCard) placeDateCard.style.display = isTeacher ? 'none' : '';

  if (!isTeacher && typeof getReportPlaceDate === 'function') {
    const pd = getReportPlaceDate();
    const placeEl = document.getElementById('rpPlace');
    const dateEl = document.getElementById('rpDate');
    if (placeEl && !placeEl.value) placeEl.value = pd.place || '';
    if (dateEl && !dateEl.value) dateEl.value = pd.date || '';
  }

  if (banner) {
    if (isTeacher) {
      banner.style.background = '#fffbeb';
      banner.style.color = '#92400e';
      banner.textContent = '👩‍🏫 Teacher View — you can compute and preview results for your own assigned class(es). Locking and publishing results is done by the Principal.';
    } else {
      banner.style.background = '#eff6ff';
      banner.style.color = '#1e3a5f';
      banner.textContent = '🏫 Principal View — full control: compute, lock, publish and unlock results for any class.';
    }
  }
}

// Saves the Place & Date shown on every report card's signature block.
function examSaveReportPlaceDate() {
  const place = document.getElementById('rpPlace')?.value.trim() || '';
  const date = document.getElementById('rpDate')?.value || '';
  if (typeof LS === 'undefined') return;
  LS.set('report_place_date', { place, date });
  const msg = document.getElementById('rpPlaceDateMsg');
  if (msg) {
    msg.innerHTML = '<span style="color:#1a6b3c;font-weight:600;">✓ Saved — will show on every report card.</span>';
    setTimeout(() => { msg.innerHTML = ''; }, 5000);
  }
  examShowToast('Report card Place & Date saved', 'success');
}

function examRPLoadStatus() {
  const examId = document.getElementById('rpExam')?.value;
  const el = document.getElementById('examRPStatus');
  if (!el) return;

  if (!examId) { el.textContent = 'Select an examination to see status.'; return; }

  const exams = examRetrieve('examinations', []);
  const exam = exams.find(e => e.id === examId);
  if (!exam) return;

  const statusLabel = exam.isPublished ? '📢 Published' : exam.isLocked ? '🔒 Locked' : '🖊 Draft';
  const deadlineLabel = exam.resultVisibleUntil
    ? ('Result visible until: ' + examFormatDate(exam.resultVisibleUntil))
    : 'Result visibility: No expiry';
  el.innerHTML = `
    <strong>${examSanitize(exam.name)}</strong><br>
    Status: ${statusLabel}<br>
    Type: ${examSanitize(exam.typeName)} &nbsp;|&nbsp; Term: ${examSanitize(exam.termName)}<br>
    Period: ${examFormatDate(exam.startDate)} – ${examFormatDate(exam.endDate)}<br>
    ${deadlineLabel}`;

  // [Result Visibility Deadline] Sync the deadline controls to this exam's
  // stored value every time the selected examination changes. Missing/null
  // means "No expiry" — checkbox checked, date input cleared and disabled.
  const dlInput = document.getElementById('rpDeadline');
  const noExpiryChk = document.getElementById('rpNoExpiry');
  const dlMsg = document.getElementById('rpDeadlineMsg');
  if (dlInput && noExpiryChk) {
    if (exam.resultVisibleUntil) {
      dlInput.value = exam.resultVisibleUntil;
      noExpiryChk.checked = false;
      dlInput.disabled = false;
    } else {
      dlInput.value = '';
      noExpiryChk.checked = true;
      dlInput.disabled = true;
    }
  }
  if (dlMsg) dlMsg.textContent = '';
}

// Recomputes Pass/Fail/Grade/Rank for ONE exam+class from whatever marks
// currently exist in subjectMap-based storage, then refreshes school-wide
// ranks across every class already computed for this exam. This is the
// core logic Result Processing's "Compute Results" button runs — pulled out
// so Marks Entry can call it automatically right after a save, instead of
// requiring a separate manual step before Grades/Result Processing/
// Analysis/Merit List pick up new marks.
function examRecomputeResultsForClass(examId, className, opts = {}) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examRecomputeResultsForClass(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examRecomputeResultsForClass(examId, className, opts);
  }
  const exams = examRetrieve('examinations', []);
  const exam = exams.find(e => e.id === examId);
  if (!exam || !className) return;

  // BUGFIX: results were silently recomputed (and could therefore silently
  // change) even after the Principal had clicked "Lock Results" for this
  // exam, because marks-entry saves only checked the per-subject marks
  // lock, never the exam-level Result Processing lock. That let a locked
  // exam's computed results drift out from under the lock, which is the
  // root cause of Result Processing showing stale/incorrect state. Unless
  // explicitly overridden (opts.force — used by examProcessResults itself,
  // which already gates on the lock before calling this), skip recompute
  // once the exam is locked.
  if (exam.isLocked && !opts.force) return;

  const maps = examRetrieve('subjectMap', []).filter(m => m.examId === examId && m.className === className);
  if (!maps.length) return;

  // ── EXAM-2.5C START — AcademicEngine safe cutover wrapper ──────────────
  // Wraps ONLY examRecomputeResultsForClass(). Nothing below this block is
  // touched — it is the ORIGINAL legacy implementation, unmodified.
  //
  // STEP 1: run the read-only comparison already built in EXAM-2.5B,
  //         AcademicEngine.Compare.compareClassResults(examId, className),
  //         which diffs AcademicEngine.computeClassResults() (EXAM-2.5A)
  //         against the current legacy examMod_results for this class.
  // STEP 2: if mismatchCount === 0, populate examMod_results using
  //         AcademicEngine.computeClassResults() instead of running the
  //         legacy per-student loop below — writing the EXACT SAME record
  //         shape (studentId/name/admissionNo/className/division/
  //         totalMarks/maxTotal/pct/grade/points/result/subjectResults/
  //         computedAt/classRank/schoolRank), so report cards, Parent
  //         Portal, Ranking, Attendance, publish flow, and snapshots all
  //         keep reading examMod_results exactly as before.
  // STEP 3: any mismatch (or the AcademicEngine APIs not being loaded, or
  //         any error along this path) falls straight through to the
  //         ORIGINAL legacy code below, unchanged.
  //
  // Does NOT rewrite Result Processing, delete legacy code, change
  // rankings math, report cards, Parent Portal, Ranking, or Attendance.
  // EXAM-3.1A-1: flag gate only — if useAcademicResultEngine is false (or
  // AcademicEngine.Flags isn't loaded), this condition is false and control
  // falls straight through to the original legacy code below, unchanged.
  if (typeof AcademicEngine !== 'undefined' && AcademicEngine &&
      AcademicEngine.Flags && typeof AcademicEngine.Flags.get === 'function' &&
      AcademicEngine.Flags.get().useAcademicResultEngine === true &&
      AcademicEngine.Compare && typeof AcademicEngine.Compare.compareClassResults === 'function' &&
      typeof AcademicEngine.computeClassResults === 'function') {
    try {
      const cmp = AcademicEngine.Compare.compareClassResults(examId, className);
      if (cmp && !cmp.issue && cmp.mismatchCount === 0) {
        const mirror = AcademicEngine.computeClassResults(examId, className);
        if (mirror && !mirror.issue && Array.isArray(mirror.students)) {
          const results = examRetrieve('results', {});
          results[examId] = results[examId] || {};
          results[examId][className] = results[examId][className] || {};

          // Division is roster metadata, not a legacy calculation — read it
          // from the SAME examGetStudentsForClass source the legacy code
          // below uses, so the schema field is populated identically.
          const divisionsAE = [...new Set(maps.map(m => m.division))];
          const divisionOfAE = {};
          divisionsAE.forEach(div => {
            examGetStudentsForClass(className, div === 'All' ? 'All' : div).forEach(stu => {
              divisionOfAE[stu.id] = div;
            });
          });

          mirror.students.forEach(s => {
            results[examId][className][s.studentId] = {
              studentId: s.studentId, name: s.name, admissionNo: s.admissionNo,
              className, division: divisionOfAE[s.studentId] || 'All',
              totalMarks: examRound(s.totalMarks), maxTotal: s.maxTotal,
              pct: s.percentage, grade: s.grade, points: s.gradePoints,
              result: s.passFail, subjectResults: s.subjectTotals,
              computedAt: new Date().toISOString()
            };
          });

          // Ranks within this class — identical logic to the legacy code
          // below, unless useAcademicRanking is true (EXAM-3.1A-2 gate below).
          const classDataAE = Object.values(results[examId][className] || {});

          // School-wide rank, recomputed across every class already processed for this exam.
          const allDataAE = [];
          Object.keys(results[examId]).forEach(cls => { Object.values(results[examId][cls] || {}).forEach(s => allDataAE.push(s)); });

          // EXAM-3.1A-2: ranking flag gate — ONLY this sub-block is gated;
          // nothing above (result mirroring) or below (examStore write) in
          // this AcademicEngine path is changed. If useAcademicRanking is
          // false (or AcademicEngine.Rank.compute isn't loaded), the exact
          // original legacy ranking math runs, unchanged. Any error on the
          // useAcademicRanking=true path naturally falls to the existing
          // outer try/catch of this EXAM-2.5C block — same fallback-to-legacy
          // behavior already in place for the rest of this wrapper.
          if (AcademicEngine.Flags && typeof AcademicEngine.Flags.get === 'function' &&
              AcademicEngine.Flags.get().useAcademicRanking === true &&
              AcademicEngine.Rank && typeof AcademicEngine.Rank.compute === 'function') {
            // useAcademicRanking = true: class-rank and school-rank values
            // come ENTIRELY from AcademicEngine.Rank.compute() — no ranking
            // math of this wrapper's own. Values are applied onto the exact
            // same stored records (same schema field names: classRank /
            // schoolRank), matched back to each record by studentId.
            const classRanked = AcademicEngine.Rank.compute(mirror).classRanks;
            const classRankById = {};
            (classRanked && Array.isArray(classRanked.students) ? classRanked.students : []).forEach(s => { classRankById[s.studentId] = s.classRank; });
            classDataAE.forEach(s => { if (classRankById[s.studentId] !== undefined) s.classRank = classRankById[s.studentId]; });

            const schoolInputMaps = Object.keys(results[examId]).map(cls => ({
              examId, className: cls,
              students: Object.values(results[examId][cls] || {}).map(s => ({ studentId: s.studentId, percentage: s.pct, passFail: s.result }))
            }));
            const schoolRanked = AcademicEngine.Rank.compute(schoolInputMaps).schoolRanks;
            const schoolRankById = {};
            (schoolRanked && Array.isArray(schoolRanked.students) ? schoolRanked.students : []).forEach(s => { schoolRankById[s.studentId] = s.schoolRank; });
            allDataAE.forEach(s => { if (schoolRankById[s.studentId] !== undefined) s.schoolRank = schoolRankById[s.studentId]; });
          } else {
            // useAcademicRanking = false (default) — exact original legacy
            // ranking math, unchanged.
            classDataAE.sort((a, b) => b.pct - a.pct);
            classDataAE.forEach((s, i) => { s.classRank = s.result === 'Absent' ? 999 : i + 1; });
            allDataAE.sort((a, b) => b.pct - a.pct);
            allDataAE.forEach((s, i) => { s.schoolRank = s.result === 'Absent' ? 999 : i + 1; });
          }

          examStore('results', results);
          console.log('[AcademicEngine] Result Processing switched successfully.');
          return;
        }
      } else if (cmp && cmp.mismatchCount > 0) {
        console.log('[AcademicEngine] Legacy Result Processing used (comparison mismatch).');
      }
    } catch (e) {
      // Any failure on the AcademicEngine path falls back to the legacy
      // implementation below — best-effort, never blocks Result Processing.
    }
  }
  // ── EXAM-2.5C END ───────────────────────────────────────────────────────

  const results = examRetrieve('results', {});
  results[examId] = results[examId] || {};

  const divisions = [...new Set(maps.map(m => m.division))];
  divisions.forEach(div => {
    const students = examGetStudentsForClass(className, div === 'All' ? 'All' : div);
    students.forEach(student => {
      let totalMarks = 0, maxTotal = 0, failAny = false, absentAny = false;
      const subjectResults = {};
      maps.forEach(sm => {
        const marksKey = `marks_${examId}_${className}_${sm.division}_${sm.id}`;
        const savedMarks = examRetrieve(marksKey, {});
        const m = savedMarks[student.id];
        if (m) {
          subjectResults[sm.subjectName] = m;
          if (m.absent) absentAny = true;
          else { totalMarks += m.total || 0; maxTotal += (sm.theoryMax + sm.practMax + sm.intMax); if (m.result === 'Fail') failAny = true; }
        }
      });
      const pct = maxTotal > 0 ? examRound((totalMarks / maxTotal) * 100) : 0;
      const result = absentAny ? 'Absent' : failAny ? 'Fail' : 'Pass';
      const grade = result === 'Absent' ? 'AB' : examCalcGrade(pct, exam.gradeScaleId || '');
      const points = result === 'Absent' ? 0 : examCalcGradePoints(pct, exam.gradeScaleId || '');

      if (!results[examId][className]) results[examId][className] = {};
      results[examId][className][student.id] = {
        studentId: student.id, name: student.name, admissionNo: student.admissionNo,
        className, division: div, totalMarks: examRound(totalMarks), maxTotal,
        pct, grade, points, result, subjectResults, computedAt: new Date().toISOString()
      };
    });
  });

  // Ranks within this class
  const classData = Object.values(results[examId][className] || {});
  classData.sort((a, b) => b.pct - a.pct);
  classData.forEach((s, i) => { s.classRank = s.result === 'Absent' ? 999 : i + 1; });

  // School-wide rank, recomputed across every class already processed for this exam
  const allData = [];
  Object.keys(results[examId]).forEach(cls => { Object.values(results[examId][cls] || {}).forEach(s => allData.push(s)); });
  allData.sort((a, b) => b.pct - a.pct);
  allData.forEach((s, i) => { s.schoolRank = s.result === 'Absent' ? 999 : i + 1; });

  examStore('results', results);
}

function examProcessResults() {
  const examId = document.getElementById('rpExam')?.value;
  if (!examId) { examShowToast('Select examination first', 'warning'); return; }

  examLog('Starting result computation...', 'info');
  const exams = examRetrieve('examinations', []);
  const exam = exams.find(e => e.id === examId);
  if (!exam) { examLog('Examination not found', 'error'); return; }

  // BUGFIX: previously this recomputed (and overwrote) results even for an
  // exam already Locked, silently contradicting the "No marks can be
  // changed after locking" promise made when Lock Results was clicked.
  if (exam.isLocked) {
    examLog('Results are locked. Unlock the exam first to recompute.', 'error');
    examShowToast('Results are locked — unlock first to recompute', 'danger');
    return;
  }

  const maps = examRetrieve('subjectMap', []).filter(m => m.examId === examId);
  let classGroups = [...new Set(maps.map(m => m.className))];

  // Respect the Class filter if one is picked.
  const rpClassFilter = document.getElementById('rpClass')?.value;
  if (rpClassFilter) classGroups = classGroups.filter(c => c === rpClassFilter);

  // Teacher lock — can only compute results for their own assigned class(es).
  if (examIsTeacherRestricted()) {
    const assignments = currentUser.classAssignments || [];
    const allowed = [...new Set(assignments.map(a => a.split('-')[0]))];
    if (allowed.length) classGroups = classGroups.filter(c => allowed.includes(c));
    if (!classGroups.length) { examShowToast('You are not assigned to this class', 'danger'); return; }
  }

  examLog(`Found ${classGroups.length} classes, ${maps.length} subject mappings`, 'info');

  let totalStudents = 0;
  classGroups.forEach(className => {
    examRecomputeResultsForClass(examId, className);
    const results = examRetrieve('results', {});
    const classData = Object.values(results[examId]?.[className] || {});
    totalStudents += classData.length;
    examLog(`Processed Class ${className}: ${classData.length} students`, 'success');
  });

  // Update exam status
  const idx = exams.findIndex(e => e.id === examId);
  if (idx > -1) { exams[idx].status = 'active'; examStore('examinations', exams); }

  examRPLoadStatus();
  examRenderRankList();
  examShowToast('Results processed successfully', 'success');
}

// Shared guard: true if the logged-in user is a class-restricted teacher
// (i.e. NOT the Principal, and not a teacher with viewAll granted).
function examIsTeacherRestricted() {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examIsTeacherRestricted(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examIsTeacherRestricted();
  }
  return typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'teacher' && !currentUser.viewAll;
}

function examLockResults() {
  if (examIsTeacherRestricted()) { examShowToast('Only the Principal can lock results', 'danger'); return; }
  const examId = document.getElementById('rpExam')?.value;
  if (!examId) { examShowToast('Select examination', 'warning'); return; }
  if (!confirm('Lock results? No marks can be changed after locking.')) return;
  const exams = examRetrieve('examinations', []);
  const idx = exams.findIndex(e => e.id === examId);
  if (idx > -1) { exams[idx].isLocked = true; exams[idx].lockedAt = new Date().toISOString(); }
  examStore('examinations', exams);
  examLog('Results LOCKED', 'warning');
  examRPLoadStatus();
  examShowToast('Results locked', 'warning');
  // ERP INTEGRATION: forward to main Audit Log if available
  if (typeof addAuditEntry === 'function' && idx > -1) {
    addAuditEntry('EXAM_RESULTS_LOCK', `Locked results for "${exams[idx].name}"`, '', 'locked');
  }
}

function examPublishResults() {
  if (examIsTeacherRestricted()) { examShowToast('Only the Principal can publish results', 'danger'); return; }
  const examId = document.getElementById('rpExam')?.value;
  if (!examId) { examShowToast('Select examination', 'warning'); return; }
  const exams = examRetrieve('examinations', []);
  const exam = exams.find(e => e.id === examId);
  if (!exam?.isLocked) { examShowToast('Lock results before publishing', 'warning'); return; }
  if (!confirm('Publish results? This makes them visible to students/parents.')) return;
  const idx = exams.findIndex(e => e.id === examId);
  if (idx > -1) { exams[idx].isPublished = true; exams[idx].publishedAt = new Date().toISOString(); }
  examStore('examinations', exams);
  examLog('Results PUBLISHED', 'success');
  examRPLoadStatus();
  examRenderMasterTable();
  examShowToast('Results published', 'success');
  // ERP INTEGRATION: forward to main Audit Log if available
  if (typeof addAuditEntry === 'function' && idx > -1) {
    addAuditEntry('EXAM_RESULTS_PUBLISH', `Published results for "${exams[idx].name}"`, '', 'published');
  }
  // CM-1.0 — notify the Communication Engine, once per student who has a
  // recorded result for this exam.
  if (window.Dnyanankur && Dnyanankur.Event) {
    const resultsForExam = examRetrieve('results', {})[examId] || {};
    const allStudents = (typeof getStudents === 'function') ? getStudents() : [];
    Object.keys(resultsForExam).forEach(function (stuId) {
      const stu = allStudents.find(s => s.id === stuId);
      const r = resultsForExam[stuId] || {};
      Dnyanankur.Event.publish('exam.result.published', {
        studentId: stuId, studentName: stu ? (stu.name || stu.studentName) : stuId,
        className: stu ? (stu.cls || stu.class) : null,
        examName: exam.name, result: r.overallResult || r.grade || 'Declared'
      }, { sourceModule: 'exam' });
    });
  }
}

function examUnlockResults() {
  if (examIsTeacherRestricted()) { examShowToast('Only the Principal can unlock results', 'danger'); return; }
  const examId = document.getElementById('rpExam')?.value;
  if (!examId) { examShowToast('Select examination', 'warning'); return; }
  if (!confirm('Unlock and unpublish results?')) return;
  const exams = examRetrieve('examinations', []);
  const idx = exams.findIndex(e => e.id === examId);
  if (idx > -1) { exams[idx].isLocked = false; exams[idx].isPublished = false; exams[idx].status = 'draft'; }
  examStore('examinations', exams);
  examLog('Results UNLOCKED & UNPUBLISHED', 'warning');
  examRPLoadStatus();
  examShowToast('Results unlocked', 'info');
  // ERP INTEGRATION: forward to main Audit Log if available
  if (typeof addAuditEntry === 'function' && idx > -1) {
    addAuditEntry('EXAM_RESULTS_UNLOCK', `Unlocked/unpublished results for "${exams[idx].name}"`, 'locked', 'draft');
  }
}

// [Result Visibility Deadline] Sets/changes/clears exam.resultVisibleUntil,
// the ONLY field this feature adds. This is a visibility-only setting —
// it never touches isPublished, publishedAt, isLocked, or status, and
// never recomputes or deletes any result data. Same authorization,
// storage, and audit pattern as examLockResults/examPublishResults/
// examUnlockResults above; no new storage mechanism, no new permission
// engine, no new audit store.
function examSetResultDeadline(examId, dateStrOrNull) {
  if (examIsTeacherRestricted()) { examShowToast('Only the Principal can change result visibility', 'danger'); return; }
  if (!examId) { examShowToast('Select examination', 'warning'); return; }

  const exams = examRetrieve('examinations', []);
  const idx = exams.findIndex(e => e.id === examId);
  if (idx === -1) { examShowToast('Examination not found', 'danger'); return; }

  const newVal = (dateStrOrNull && String(dateStrOrNull).trim()) ? String(dateStrOrNull).trim() : null;
  const oldVal = exams[idx].resultVisibleUntil || null;
  if (newVal === oldVal) return; // no-op, nothing to save/audit

  exams[idx].resultVisibleUntil = newVal;
  examStore('examinations', exams);

  const examName = exams[idx].name;
  let actionType, actionDetail, logMsg;
  if (!oldVal && newVal) {
    actionType = 'EXAM_RESULT_DEADLINE_SET';
    logMsg = 'Result visibility deadline set to ' + newVal;
    actionDetail = `Set result visibility deadline for "${examName}" to ${newVal}`;
  } else if (oldVal && !newVal) {
    actionType = 'EXAM_RESULT_DEADLINE_CLEARED';
    logMsg = 'Result visibility deadline cleared (No expiry)';
    actionDetail = `Cleared result visibility deadline for "${examName}" (was ${oldVal})`;
  } else {
    actionType = 'EXAM_RESULT_DEADLINE_CHANGED';
    logMsg = 'Result visibility deadline changed to ' + newVal;
    actionDetail = `Changed result visibility deadline for "${examName}" from ${oldVal} to ${newVal}`;
  }

  examLog(logMsg, 'info');
  examRPLoadStatus();
  examShowToast(newVal ? ('Result visibility set until ' + examFormatDate(newVal)) : 'Result visibility set to No expiry', 'success');

  // ERP INTEGRATION: forward to main Audit Log if available
  if (typeof addAuditEntry === 'function') {
    addAuditEntry(actionType, actionDetail, oldVal || '', newVal || '');
  }
}

// [Result Visibility Deadline] DOM wiring only — enables/disables the date
// input to match the "No expiry" checkbox. Does not save; Save button below
// still calls examSetResultDeadline() explicitly, same as every other
// Result Processing action in this card.
function examToggleNoExpiry() {
  const dlInput = document.getElementById('rpDeadline');
  const noExpiryChk = document.getElementById('rpNoExpiry');
  if (!dlInput || !noExpiryChk) return;
  dlInput.disabled = noExpiryChk.checked;
  if (noExpiryChk.checked) dlInput.value = '';
}

// [Result Visibility Deadline] DOM wiring for the Save button — reads the
// currently selected examination and the two new controls, then delegates
// to examSetResultDeadline() for the actual authorization/storage/audit.
function examSaveResultDeadline() {
  const examId = document.getElementById('rpExam')?.value;
  const noExpiryChk = document.getElementById('rpNoExpiry');
  const dlInput = document.getElementById('rpDeadline');
  const dlMsg = document.getElementById('rpDeadlineMsg');
  if (!examId) { examShowToast('Select examination', 'warning'); return; }
  const dateStrOrNull = (noExpiryChk && noExpiryChk.checked) ? null : (dlInput ? dlInput.value : null);
  examSetResultDeadline(examId, dateStrOrNull);
  if (dlMsg) dlMsg.textContent = 'Saved';
}

/* ═══════════════════════════════════════════════
   EXAM MODULE TERM REPORT CARD
   Generates a printable term-wise report card from
   the Examination Center's own marks storage.
   Uses getSettings() for school name/logo exactly
   like the Annual Report Card, so branding is consistent.
   (This is the "Exam Center" report card — the
   Annual Report Cards page remains unchanged.)
═══════════════════════════════════════════════ */
function examGenTermReportCard() {
  const examId = document.getElementById('rpExam')?.value;
  const className = document.getElementById('rpClass')?.value;
  if (!examId) { examShowToast('Select an examination first', 'warning'); return; }

  const exam = examRetrieve('examinations', []).find(e => e.id === examId);
  if (!exam) { examShowToast('Examination not found', 'danger'); return; }

  const subjectMaps = examRetrieve('subjectMap', []).filter(m => m.examId === examId && (!className || m.className === className));
  const results = examRetrieve('results', {})[examId] || {};
  const settings = (typeof getSettings === 'function') ? getSettings() : {};
  const schoolName = settings.name || 'School';
  const acyr = settings.acyr || '';

  const allStudents = (typeof getStudents === 'function')
    ? getStudents().filter(s => !className || s.cls === className)
    : [];

  if (!allStudents.length) { examShowToast('No students found for selected class', 'warning'); return; }

  const subjectNames = [...new Set(subjectMaps.map(m => m.subjectName))];

  const cards = allStudents.map(stu => {
    const stuResult = results[stu.id] || {};

    const rows = subjectNames.map(sub => {
      const mapForSub = subjectMaps.find(m => m.subjectName === sub);
      const marksKey = mapForSub ? `marks_${examId}_${stu.cls}_${stu.div}_${mapForSub.id}` : null;
      const savedMarks = marksKey ? examRetrieve(marksKey, {}) : {};
      const entry = savedMarks[stu.id] || {};
      const theory   = entry.theory   ?? '';
      const pract    = entry.pract    ?? '';
      const internal = entry.internal ?? '';
      const total    = entry.total    ?? '';
      const grade    = entry.grade    ?? '';
      return `<tr>
        <td style="padding:5px 8px;">${sub}</td>
        <td style="text-align:center;">${mapForSub?.theoryMax ?? ''}</td>
        <td style="text-align:center;">${theory}</td>
        ${mapForSub?.practMax > 0 ? `<td style="text-align:center;">${pract}</td>` : ''}
        ${mapForSub?.intMax   > 0 ? `<td style="text-align:center;">${internal}</td>` : ''}
        <td style="text-align:center;font-weight:700;">${total}</td>
        <td style="text-align:center;">${grade}</td>
      </tr>`;
    }).join('');

    const hasPract    = subjectMaps.some(m => m.practMax > 0);
    const hasInternal = subjectMaps.some(m => m.intMax   > 0);

    return `<div style="border:2px solid #1a3a6b;border-radius:8px;padding:18px 20px;margin-bottom:32px;font-family:serif;page-break-inside:avoid;">
      <div style="text-align:center;border-bottom:2px solid #1a3a6b;padding-bottom:10px;margin-bottom:12px;">
        <div style="font-size:20px;font-weight:bold;color:#1a3a6b;">${schoolName}</div>
        <div style="font-size:13px;color:#555;">Academic Year: ${acyr}</div>
        <div style="font-size:16px;font-weight:600;margin-top:4px;">TERM REPORT CARD — ${exam.name}</div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px 20px;font-size:13px;margin-bottom:14px;">
        <div><b>Student:</b> ${stu.name}</div>
        <div><b>Adm No:</b> ${stu.admno || '-'}</div>
        <div><b>Class:</b> ${stu.cls} — ${stu.div}</div>
        <div><b>Roll No:</b> ${stu.roll || '-'}</div>
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:12px;">
        <thead style="background:#1a3a6b;color:#fff;">
          <tr>
            <th style="padding:6px 8px;text-align:left;">Subject</th>
            <th style="text-align:center;">Max</th>
            <th style="text-align:center;">Theory</th>
            ${hasPract    ? '<th style="text-align:center;">Pract.</th>' : ''}
            ${hasInternal ? '<th style="text-align:center;">Internal</th>' : ''}
            <th style="text-align:center;">Total</th>
            <th style="text-align:center;">Grade</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
      <div style="font-size:12.5px;color:#333;border-top:1px solid #ddd;padding-top:8px;">
        <b>Remarks:</b> ${exam.remarks || '—'}
        &nbsp;&nbsp;&nbsp;<b>Overall Result:</b> ${stuResult.result || '—'}
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;margin-top:16px;font-size:12px;color:#555;">
        <div>Class Teacher Signature: ____________________</div>
        <div style="text-align:right;">Principal Signature: ____________________</div>
      </div>
    </div>`;
  }).join('<div style="page-break-after:always;"></div>');

  const win = window.open('', '_blank');
  win.document.write(`<!DOCTYPE html><html><head><title>Term Report Cards — ${exam.name}</title>
  <style>body{font-family:serif;margin:24px;}@media print{body{margin:0;}}</style></head>
  <body>${cards}
  <div style="text-align:center;margin-top:20px;"><button onclick="window.print()" style="padding:10px 24px;font-size:14px;background:#1a3a6b;color:#fff;border:none;border-radius:6px;cursor:pointer;">🖨 Print</button></div>
  </body></html>`);
  win.document.close();
}

function examRenderRankList() {
  const examId = document.getElementById('rpRankExam')?.value;
  const className = document.getElementById('rpRankClass')?.value;
  const tbody = document.getElementById('examRankTableBody');
  if (!tbody) return;

  if (!examId) { tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--exam-text-muted)">Select examination</td></tr>'; return; }

  const results = examRetrieve('results', {});
  const examResults = results[examId] || {};

  let allStudents = [];
  if (className) {
    allStudents = Object.values(examResults[className] || {});
  } else if (examIsTeacherRestricted()) {
    const assignments = currentUser.classAssignments || [];
    const allowed = [...new Set(assignments.map(a => a.split('-')[0]))];
    Object.entries(examResults).forEach(([cls, students]) => {
      if (allowed.includes(cls)) Object.values(students).forEach(s => allStudents.push(s));
    });
  } else {
    Object.values(examResults).forEach(cls => { Object.values(cls).forEach(s => allStudents.push(s)); });
  }

  allStudents.sort((a, b) => (a.schoolRank || 999) - (b.schoolRank || 999));

  if (!allStudents.length) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--exam-text-muted)">No results processed yet. Run "Compute Results" first.</td></tr>';
    return;
  }

  tbody.innerHTML = allStudents.map(s => `
    <tr>
      <td><strong style="font-size:16px;color:var(--exam-navy)">#${className ? s.classRank : s.schoolRank}</strong></td>
      <td>${examSanitize(s.admissionNo || '—')}</td>
      <td><strong>${examSanitize(s.name)}</strong></td>
      <td>Class ${examSanitize(s.className)}</td>
      <td>${examRound(s.totalMarks)}/${s.maxTotal}</td>
      <td><strong>${s.pct}%</strong></td>
      <td><span class="exam-badge exam-badge-info">${s.grade}</span></td>
      <td>${s.result === 'Pass'
          ? '<span class="exam-badge exam-badge-success">Pass</span>'
          : s.result === 'Fail'
            ? '<span class="exam-badge exam-badge-danger">Fail</span>'
            : '<span class="exam-badge exam-badge-warning">Absent</span>'}</td>
    </tr>`).join('');
}

function examExportRankListCSV() {
  const examId = document.getElementById('rpRankExam')?.value;
  if (!examId) { examShowToast('Select examination', 'warning'); return; }
  const results = examRetrieve('results', {});
  const examResults = results[examId] || {};
  const rows = [['Rank','Adm No','Name','Class','Total','Max','%','Grade','Result']];
  const all = [];
  Object.values(examResults).forEach(cls => Object.values(cls).forEach(s => all.push(s)));
  all.sort((a,b)=>(a.schoolRank||999)-(b.schoolRank||999));
  all.forEach(s => rows.push([s.schoolRank,s.admissionNo,s.name,s.className,examRound(s.totalMarks),s.maxTotal,s.pct,s.grade,s.result]));
  examCSVDownload('rank_list.csv', rows);
  examShowToast('CSV exported', 'info');
}

/* ═══════════════════════════════════════════════
   SECTION P — ANALYSIS
═══════════════════════════════════════════════ */

let examChartSubjectAvg = null;
let examChartGradeDist  = null;
let examChartPassFail   = null;

function examPopulateAnalysisFilters() {
  const exams = examRetrieve('examinations', []);
  const classes = examGetClassOptions();
  ['anExam'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    sel.innerHTML = '<option value="">— Examination —</option>' +
      exams.map(e => `<option value="${e.id}">${examSanitize(e.name)}</option>`).join('');
  });
  const anClass = document.getElementById('anClass');
  if (anClass) anClass.innerHTML = '<option value="">— Class —</option>' +
    classes.map(c => `<option value="${c}">${examSanitize(c)}</option>`).join('');
}

function examRunAnalysis() {
  const examId = document.getElementById('anExam')?.value;
  const className = document.getElementById('anClass')?.value;

  if (!examId) return;

  const maps = examRetrieve('subjectMap', []).filter(m =>
    m.examId === examId && (!className || m.className === className));

  const classGroups = className ? [className] : [...new Set(maps.map(m => m.className))];

  let totalStudents = 0, totalPassed = 0, totalFailed = 0, totalAbsent = 0;
  let totalPct = 0, counted = 0;
  const subjectStats = {};
  const gradeCount = {};
  const weakStudents = [];

  // ── SPRINT 7.2 — RESULT STORE CONSOLIDATION ──────────────────────────────
  // Previously this re-aggregated every student's total/percentage/pass-fail
  // directly from raw marks_{examId}_{class}_{div}_{mapId} records — a
  // duplicate of the canonical computation already done by
  // examRecomputeResultsForClass(). Now per-student pct/result/grade are read
  // from the canonical result store (examMod_results), so Analysis always
  // agrees with Result Processing, Class Result, Statistics, Merit List and
  // Report Cards. Per-subject breakdowns (avg/highest/lowest/pass-fail per
  // subject, used for the Subject Analysis table and charts) are built from
  // the same student's subjectResults snapshot inside that canonical record,
  // rather than a second raw-marks read.
  const allResults = examRetrieve('results', {});

  classGroups.forEach(cls => {
    const classMaps = maps.filter(m => m.className === cls);
    const students = examGetStudentsForClass(cls, 'All');
    totalStudents += students.length;
    const classResults = allResults[examId]?.[cls] || {};

    students.forEach(student => {
      const sr = classResults[student.id];

      classMaps.forEach(sm => {
        const m = sr && sr.subjectResults ? sr.subjectResults[sm.subjectName] : null;
        if (!m) return;

        // Subject stats
        if (!subjectStats[sm.subjectName]) {
          subjectStats[sm.subjectName] = { max: sm.theoryMax + sm.practMax + sm.intMax, marks: [], pass: 0, fail: 0, absent: 0 };
        }
        if (m.absent) { subjectStats[sm.subjectName].absent++; }
        else {
          subjectStats[sm.subjectName].marks.push(m.pct || 0);
          if (m.result === 'Pass') subjectStats[sm.subjectName].pass++;
          else subjectStats[sm.subjectName].fail++;
        }
      });

      // Same weak/pass/fail rule as before (Fail OR below 35%), now sourced
      // from the canonical result instead of a locally re-summed total. If
      // no canonical result exists yet for this student (Result Processing
      // hasn't run), pct defaults to 0 — matching prior "no marks found"
      // behavior, which also fell through to 0% / weak.
      const studentPct = sr ? (sr.pct || 0) : 0;
      const srResult = sr ? sr.result : null;
      const isWeak = srResult === 'Fail' || studentPct < 35;

      if (srResult === 'Absent') totalAbsent++;
      else if (isWeak) {
        totalFailed++;
        weakStudents.push({ name: student.name, className: cls, pct: studentPct, admissionNo: student.admissionNo });
      }
      else { totalPassed++; }

      if (srResult !== 'Absent') { totalPct += studentPct; counted++; }

      // Grade distribution — use the canonical grade when available, only
      // falling back to a fresh Grade Engine lookup if no result exists yet.
      const g = srResult === 'Absent' ? 'AB' : ((sr && sr.grade) || examCalcGrade(studentPct, ''));
      gradeCount[g] = (gradeCount[g] || 0) + 1;
    });
  });

  const avgPct = counted > 0 ? examRound(totalPct / counted) : 0;
  const passPct = (totalPassed + totalFailed) > 0 ? examRound((totalPassed / (totalPassed + totalFailed)) * 100) : 0;

  // KPI
  document.getElementById('kpiTotal').textContent   = totalStudents;
  document.getElementById('kpiPassed').textContent  = totalPassed;
  document.getElementById('kpiFailed').textContent  = totalFailed;
  document.getElementById('kpiAbsent').textContent  = totalAbsent;
  document.getElementById('kpiAvgPct').textContent  = avgPct + '%';
  document.getElementById('kpiPassPct').textContent = passPct + '%';

  // Weak students
  weakStudents.sort((a, b) => a.pct - b.pct);
  const weakEl = document.getElementById('examWeakStudentList');
  const weakCount = document.getElementById('weakStudentCount');
  if (weakCount) weakCount.textContent = weakStudents.length + ' students';
  if (weakEl) {
    if (!weakStudents.length) {
      weakEl.innerHTML = '<div class="exam-empty-state" style="padding:20px"><div class="exam-empty-icon">✅</div><div>No weak students found!</div></div>';
    } else {
      weakEl.innerHTML = weakStudents.slice(0, 20).map(s => `
        <div class="exam-weak-item">
          <div class="exam-weak-avatar">${(s.name || 'S')[0].toUpperCase()}</div>
          <div>
            <div class="exam-weak-name">${examSanitize(s.name)}</div>
            <div class="exam-weak-meta">${examSanitize(s.admissionNo || '')} • Class ${examSanitize(s.className)}</div>
          </div>
          <div class="exam-weak-pct">${s.pct}%</div>
        </div>`).join('');
    }
  }

  // Subject Analysis Table
  const sbodyEl = document.getElementById('examSubjectAnalysisBody');
  if (sbodyEl) {
    sbodyEl.innerHTML = Object.keys(subjectStats).map(subj => {
      const st = subjectStats[subj];
      const avg = st.marks.length ? examRound(st.marks.reduce((a,b) => a+b, 0) / st.marks.length) : 0;
      const highest = st.marks.length ? Math.max(...st.marks) : 0;
      const lowest  = st.marks.length ? Math.min(...st.marks) : 0;
      const spPass  = (st.pass + st.fail) > 0 ? examRound((st.pass / (st.pass + st.fail)) * 100) : 0;
      const trend = avg >= 70 ? '📈' : avg >= 50 ? '➡️' : '📉';
      return `<tr>
        <td><strong>${examSanitize(subj)}</strong></td>
        <td>${st.max}</td>
        <td><strong>${avg}%</strong></td>
        <td style="color:var(--exam-green)">${highest}%</td>
        <td style="color:var(--exam-red)">${lowest}%</td>
        <td style="color:var(--exam-green)">${st.pass}</td>
        <td style="color:var(--exam-red)">${st.fail}</td>
        <td><strong>${spPass}%</strong></td>
        <td style="font-size:18px">${trend}</td>
      </tr>`;
    }).join('') || '<tr><td colspan="9" style="text-align:center;padding:24px;color:var(--exam-text-muted)">No data</td></tr>';
  }

  // Charts
  examDrawSubjectAvgChart(subjectStats);
  examDrawGradeDistChart(gradeCount);
  examDrawPassFailChart(subjectStats);
}

function examDrawSubjectAvgChart(subjectStats) {
  const ctx = document.getElementById('chartSubjectAvg');
  if (!ctx) return;
  if (examChartSubjectAvg) examChartSubjectAvg.destroy();

  const labels = Object.keys(subjectStats);
  const avgs = labels.map(s => {
    const m = subjectStats[s].marks;
    return m.length ? examRound(m.reduce((a,b) => a+b,0)/m.length) : 0;
  });

  examChartSubjectAvg = new Chart(ctx, {
    type: 'bar',
    data: {
      labels,
      datasets: [{
        label: 'Average %',
        data: avgs,
        backgroundColor: avgs.map(v => v >= 70 ? 'rgba(16,185,129,0.7)' : v >= 40 ? 'rgba(245,158,11,0.7)' : 'rgba(239,68,68,0.7)'),
        borderRadius: 6,
        borderSkipped: false,
      }]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: { y: { beginAtZero: true, max: 100, ticks: { callback: v => v + '%' } } }
    }
  });
}

function examDrawGradeDistChart(gradeCount) {
  const ctx = document.getElementById('chartGradeDist');
  if (!ctx) return;
  if (examChartGradeDist) examChartGradeDist.destroy();

  const gradeOrder = ['A+','A','B+','B','C+','C','D','E','F','—'];
  const labels = gradeOrder.filter(g => gradeCount[g] > 0);
  const data   = labels.map(g => gradeCount[g] || 0);
  const colors = ['#10b981','#34d399','#3b82f6','#60a5fa','#f59e0b','#fcd34d','#f97316','#ef4444','#dc2626','#94a3b8'];

  examChartGradeDist = new Chart(ctx, {
    type: 'doughnut',
    data: {
      labels,
      datasets: [{ data, backgroundColor: colors.slice(0, labels.length), borderWidth: 2 }]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { position: 'right', labels: { boxWidth: 12, font: { size: 11 } } } }
    }
  });
}

function examDrawPassFailChart(subjectStats) {
  const ctx = document.getElementById('chartPassFail');
  if (!ctx) return;
  if (examChartPassFail) examChartPassFail.destroy();

  const labels = Object.keys(subjectStats);
  const passData = labels.map(s => subjectStats[s].pass);
  const failData = labels.map(s => subjectStats[s].fail);

  examChartPassFail = new Chart(ctx, {
    type: 'bar',
    data: {
      labels,
      datasets: [
        { label: 'Pass', data: passData, backgroundColor: 'rgba(16,185,129,0.7)', borderRadius: 4 },
        { label: 'Fail', data: failData, backgroundColor: 'rgba(239,68,68,0.7)',  borderRadius: 4 },
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { position: 'top' } },
      scales: { x: { stacked: false }, y: { beginAtZero: true, ticks: { stepSize: 1 } } }
    }
  });
}

/* ═══════════════════════════════════════════════
   SECTION Q — REPORT CARDS
═══════════════════════════════════════════════ */

function examPopulateRCFilters() {
  const classes = examGetClassOptions();
  const rcClass = document.getElementById('rcClass');
  if (rcClass) rcClass.innerHTML = '<option value="">— Select —</option>' +
    classes.map(c => `<option value="${c}">${examSanitize(c)}</option>`).join('');
  if (typeof examRCDesignChanged === 'function') examRCDesignChanged();
}

function examRCLoadStudents() {
  const className = document.getElementById('rcClass')?.value;
  const divSel = document.getElementById('rcDivision');
  const studentSel = document.getElementById('rcStudent');

  if (divSel) divSel.innerHTML = '<option value="">All Divisions</option>' +
    ['A','B','C','D'].map(d => `<option value="${d}">${d}</option>`).join('');

  if (!className) return;

  const students = examGetStudentsForClass(className, 'All');
  if (studentSel) {
    studentSel.innerHTML = '<option value="">All (Bulk Print)</option>' +
      students.map(s => `<option value="${s.id}">${examSanitize(s.name)} (${s.admissionNo || ''})</option>`).join('');
  }
  examRCRefreshStatus();
}

// Only two report card formats now — both read straight from Term marks,
// so there's nothing to toggle; this just keeps the hint text visible.
function examRCDesignChanged() {
  const hint = document.getElementById('rcDesignHint');
  if (hint) hint.style.display = '';
  examRCRefreshStatus();
}

// Live readiness check shown as soon as Class/Design are picked, so users
// see WHY report cards are locked before even hitting Preview/Bulk Print —
// rather than only finding out after clicking. Gated on Result Processing
// only here (fee-clearance is necessarily per-student, so that's reported
// after generation is attempted, per student).
function examRCRefreshStatus() {
  const className = document.getElementById('rcClass')?.value;
  const design = document.getElementById('rcDesign')?.value || 'sem1';
  if (!className) { examRCClearBlockedMessage(); return; }
  const rp = examCheckResultProcessingReady(className, design);
  if (!rp.ready) {
    examRCShowBlockedMessage(
      `⛔ Result Processing not yet complete for ${examSanitize(className)}.`,
      rp.missing.map(m => `• ${examSanitize(m)}`).join('<br>') +
      `<br><br>Report cards for this class will stay locked until results are computed and locked in <b>Result Processing</b>.`
    );
  } else {
    examRCClearBlockedMessage();
  }
}

// ── ANNUAL / SEMESTER 1 REPORT CARD BUILDER ────────────────────────
// Powers both Report Card options. Uses the same functions/data sources as
// the original school-customised report card (buildReportCard /
// build11thReportCard / buildSemester1ReportCard, unchanged) — so the
// printed report card is identical to before, just optionally showing only
// Term 1 for the "Semester 1 Report Card" option.
//
// ── GATE 1: RESULT PROCESSING ──────────────────────────────────────
// Report cards must not be generated until Result Processing has been
// completed (computed AND locked) for the term(s) that feed that design:
//   • Semester 1 Report Card → Term 1's Semester Exam (rcSlot 'SA1') must be locked.
//   • Final Report Card (Annual) → BOTH Term 1 and Term 2's Semester Exams must be locked.
// This walks the same 'examinations' records Result Processing writes to
// (isLocked / isPublished), matched by class (applicableClass) + term + rcSlot.
// BUGFIX: this used to match exams by a hard-coded literal term NAME
// ('Term 1' / 'Term 2'). Term names are free text (Exam Setup → Terms lets
// a school call it "Semester 1", "Sem I", "Term I", anything) — so any
// school that didn't name their terms exactly "Term 1"/"Term 2" always
// failed this match and got a false "no Semester Exam found" warning even
// after correctly computing and locking results. Now matched by the term's
// position (order 1 = first term, order 2 = second term) via termId, which
// is stable regardless of what the term is actually named.
function examGetOrderedTerms() {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetOrderedTerms(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetOrderedTerms();
  }
  return examRetrieve('terms', []).slice().sort((a, b) => (Number(a.order) || 0) - (Number(b.order) || 0));
}

function examFindSA1ExamForTerm(className, termId) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examFindSA1ExamForTerm(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examFindSA1ExamForTerm(className, termId);
  }
  const exams = examRetrieve('examinations', []);
  // BUGFIX: this used to require e.rcSlot === 'SA1' with no fallback, so any
  // exam saved before the Report Card Slot field existed (rcSlot left
  // undefined) was invisible to this gate — even though Result Processing
  // already treats it as the Semester/Final Exam via examInferRcSlot's
  // name-based inference (see examGetLegacyTermAssess). That mismatch let
  // people compute + lock results for Term 2 and still get a false
  // "no Semester Exam found" block on Report Cards. Now this gate applies
  // the same inference fallback so it agrees with Result Processing about
  // which exam counts as SA1.
  const candidates = exams.filter(e => {
    if (e.termId !== termId) return false;
    if (!(!e.applicableClass || e.applicableClass === 'all' || e.applicableClass === className)) return false;
    if (e.rcSlot) return e.rcSlot === 'SA1';
    return (typeof examInferRcSlot === 'function')
      ? examInferRcSlot(`${e.typeName || ''} ${e.name || ''}`) === 'SA1'
      : false;
  });
  if (!candidates.length) return null;
  // Prefer an exam matching the current academic year if we can tell; else most recently created.
  const settings = (typeof getSettings === 'function') ? getSettings() : {};
  const acyr = settings.acyr || '';
  const byYear = candidates.filter(e => e.yearName === acyr);
  const pool = byYear.length ? byYear : candidates;
  return pool.slice().sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0))[0];
}

function examCheckResultProcessingReady(className, design) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examCheckResultProcessingReady(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examCheckResultProcessingReady(className, design);
  }
  const orderedTerms = examGetOrderedTerms();
  const missing = [];

  if (!orderedTerms.length) {
    return { ready: false, missing: ['No terms configured — add terms in Exam Setup first.'] };
  }

  // Safety net: if two terms share the same Order/Sequence number, which
  // one this gate treats as "Term 1" vs "Term 2" is ambiguous and can
  // silently point at the wrong term (see examOpenTermModal bugfix notes).
  // Surface that plainly instead of just failing to find an exam.
  const orderCounts = {};
  orderedTerms.forEach(t => { const o = Number(t.order) || 0; orderCounts[o] = (orderCounts[o] || 0) + 1; });
  const dupeOrders = Object.keys(orderCounts).filter(o => orderCounts[o] > 1);
  if (dupeOrders.length) {
    const dupeNames = orderedTerms.filter(t => dupeOrders.includes(String(Number(t.order) || 0))).map(t => t.name).join(', ');
    missing.push(`Term ordering is ambiguous — these terms share the same Order/Sequence number: ${dupeNames}. Go to Exam Setup → Terms and give each term a unique Order (Term 1 = 1, Term 2 = 2, etc.) before generating report cards.`);
  }

  const termsNeededCount = design === 'sem1' ? 1 : 2;
  const termsNeeded = orderedTerms.slice(0, termsNeededCount);

  if (termsNeeded.length < termsNeededCount) {
    missing.push(`Only ${termsNeeded.length} term(s) configured — this report card needs ${termsNeededCount}. Add the missing term in Exam Setup.`);
  }

  termsNeeded.forEach(term => {
    const exam = examFindSA1ExamForTerm(className, term.id);
    if (!exam) { missing.push(`${term.name} (no Semester Exam found for ${className})`); return; }
    if (!exam.isLocked) { missing.push(`${term.name} — "${exam.name}" (results not yet locked in Result Processing)`); }
  });

  return { ready: missing.length === 0, missing };
}

// ── GATE 2: FEES CLEARED FOR THE ACADEMIC YEAR ─────────────────────
// Only students who have paid ALL their fees (school + transport + any
// inventory bills) for the year can have their report card generated.
// Reuses getStudentFinanceSummary(), the same source the Finance Center
// uses to mark a student's fee status as "Paid".
function examStudentHasClearedFees(studentId) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examStudentHasClearedFees(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examStudentHasClearedFees(studentId);
  }
  if (typeof getStudentFinanceSummary !== 'function') return true; // fail-open if module unavailable
  const summary = getStudentFinanceSummary(studentId);
  return summary.status === 'Paid';
}

function examBuildAnnualReportCards(className, division, studentId, design) {
  if (typeof getStudents !== 'function' || typeof buildReportCard !== 'function' || typeof build11thReportCard !== 'function') {
    examShowToast('Report card engine not available', 'danger');
    return;
  }

  const previewAreaEl = document.getElementById('examRCPreviewArea');
  const previewContentEl = document.getElementById('examRCPreviewContent');

  // GATE 1: block entirely if result processing isn't done for the needed term(s).
  const rp = examCheckResultProcessingReady(className, design);
  if (!rp.ready) {
    if (previewContentEl) previewContentEl.innerHTML = '';
    if (previewAreaEl) previewAreaEl.style.display = 'none';
    examShowToast('Report cards are locked until Result Processing is complete', 'danger');
    examRCShowBlockedMessage(
      `⛔ Report cards can't be generated yet for ${examSanitize(className)}.`,
      `Result Processing isn't finished:<br>` + rp.missing.map(m => `• ${examSanitize(m)}`).join('<br>') +
      `<br><br>Go to <b>Result Processing</b>, compute results for these exams, then <b>Lock Results</b>. Report cards will unlock automatically once that's done.`
    );
    return;
  }

  let students = getStudents().filter(s => s.cls === className && (!division || s.div === division));
  if (studentId) students = students.filter(s => s.id === studentId);
  students.sort((a, b) => (Number(a.roll) || 0) - (Number(b.roll) || 0));

  if (!students.length) { examShowToast('No students found for this class/division', 'warning'); return; }

  // GATE 2: only students who have cleared all fees for the year are eligible.
  // EXEMPTION: Principal can always view/generate report cards regardless of
  // fee status (e.g. to review or resolve a case) — the fee gate is meant to
  // stop parents/students from *receiving* a report card before fees are
  // settled, not to stop the principal from seeing it. Teachers remain
  // subject to the fee gate like before.
  const isPrincipalViewer = typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'principal';
  const eligible = isPrincipalViewer ? students : students.filter(s => examStudentHasClearedFees(s.id));
  const blocked = isPrincipalViewer ? [] : students.filter(s => !examStudentHasClearedFees(s.id));

  if (!eligible.length) {
    if (previewContentEl) previewContentEl.innerHTML = '';
    if (previewAreaEl) previewAreaEl.style.display = 'none';
    examShowToast('No report cards generated — fees are pending', 'danger');
    examRCShowBlockedMessage(
      `⛔ No report card(s) generated.`,
      `${blocked.length === 1 ? 'This student has' : 'All selected students have'} pending fees for this academic year. ` +
      `Report cards are only available to students who have paid all fees (school + transport + inventory bills) in full.<br><br>` +
      `Pending: ${blocked.map(s => examSanitize(s.name)).join(', ')}`
    );
    return;
  }

  const previewArea = previewAreaEl;
  const previewContent = previewContentEl;
  previewArea.style.display = 'block';

  const isSem1 = design === 'sem1';
  previewContent.innerHTML = eligible
    .map(s => {
      if (className === '11th') return isSem1 ? build11thSemester1ReportCard(s) : build11thReportCard(s);
      return isSem1 ? buildSemester1ReportCard(s) : buildReportCard(s);
    })
    .join('<div style="page-break-after:always;"></div>');

  previewArea.scrollIntoView({ behavior: 'smooth' });

  if (isPrincipalViewer) {
    const feePendingForNote = students.filter(s => !examStudentHasClearedFees(s.id));
    if (feePendingForNote.length) {
      examShowToast(`${eligible.length} report card(s) generated (principal view — fee gate bypassed)`, 'info');
      examRCShowBlockedMessage(
        `ℹ Note: ${feePendingForNote.length} student(s) shown here have pending fees for the academic year.`,
        `Parents/students won't be able to view these until fees are cleared. Shown to you as principal for review only: ${feePendingForNote.map(s => examSanitize(s.name)).join(', ')}`
      );
    } else {
      examShowToast(`${eligible.length} report card(s) generated`, 'success');
      examRCClearBlockedMessage();
    }
  } else if (blocked.length) {
    examShowToast(`${eligible.length} report card(s) generated — ${blocked.length} skipped (fees pending)`, 'warning');
    examRCShowBlockedMessage(
      `⚠ ${blocked.length} student(s) were skipped — fees pending for the academic year:`,
      blocked.map(s => examSanitize(s.name)).join(', ')
    );
  } else {
    examShowToast(`${eligible.length} report card(s) generated`, 'success');
    examRCClearBlockedMessage();
  }
}

// Small inline banner (separate from the toast) so the reason a report card
// didn't generate stays visible instead of disappearing after a few seconds.
function examRCShowBlockedMessage(title, bodyHtml) {
  let el = document.getElementById('examRCBlockedMsg');
  if (!el) {
    const anchor = document.querySelector('#examReportCard .exam-card');
    if (!anchor) return;
    el = document.createElement('div');
    el.id = 'examRCBlockedMsg';
    el.style.cssText = 'margin-top:14px;padding:12px 14px;border-radius:8px;background:#fef2f2;border:1px solid #fecaca;color:#991b1b;font-size:13px;line-height:1.6;';
    anchor.parentNode.insertBefore(el, anchor.nextSibling);
  }
  el.style.display = 'block';
  el.innerHTML = `<strong>${title}</strong><div style="margin-top:6px;">${bodyHtml}</div>`;
}

function examRCClearBlockedMessage() {
  const el = document.getElementById('examRCBlockedMsg');
  if (el) el.style.display = 'none';
}

function examGenerateReportCard() {
  const className = document.getElementById('rcClass')?.value;
  const division  = document.getElementById('rcDivision')?.value || '';
  const design    = document.getElementById('rcDesign')?.value || 'sem1';
  const studentId = document.getElementById('rcStudent')?.value || '';

  if (!className) { examShowToast('Select a class', 'warning'); return; }
  examBuildAnnualReportCards(className, division, studentId, design);
}

function examBuildReportCard(student, exam, maps, subjectMarks, sr, design) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examBuildReportCard(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examBuildReportCard(student, exam, maps, subjectMarks, sr, design);
  }
  // ERP INTEGRATION: pulls the real school name (and could pull logo/address)
  // from the ERP's getSettings() instead of a guessed localStorage key.
  let schoolName = 'Dnyanankur School';
  try {
    if (typeof getSettings === 'function') {
      schoolName = getSettings().name || schoolName;
    } else {
      schoolName = localStorage.getItem('schoolName') || schoolName;
    }
  } catch (e) {}

  // EXAM-3.2B-1: report-card DATA SOURCE flag gate. This is the smallest
  // point that sits strictly between where `sr` (the student report object)
  // arrives and where the unchanged renderer calls below receive their
  // totalMarks/maxTotal/pct/grade/result/rank arguments — same names, same
  // order, same renderer, same schema, for both flag states.
  //
  // FALSE (default): __aeStudent stays null below, so every field falls
  // through to the original `sr.<field> ?? '—'` legacy expression —
  // byte-for-byte the same as before this gate existed.
  //
  // TRUE: builds a single-student classResult from `sr` (tolerant of both
  // AcademicEngine and legacy field names, per computeStudent's documented
  // contract — no recalculation happens when sr already carries a value),
  // routes it through AcademicEngine.ReportCard.compute() (EXAM-2.7A-3) and
  // then AcademicEngine.ReportCard.Adapter.convert() (EXAM-3.2A-3, itself a
  // pure wrapper over toLegacyClass/toLegacyStudent, EXAM-3.2A-1/2) to get
  // back the exact legacy field names this function already uses. Rank has
  // no equivalent inside ReportCard.compute() by explicit design ("that is
  // AcademicEngine.Rank's job, not this function's"), so classRank is
  // supplied to the Adapter's rankingClass argument directly from `sr`,
  // unchanged — this gate does not touch ranking.
  //
  // If AcademicEngine, Flags, ReportCard.compute, or Adapter.convert are
  // unavailable, or anything throws, or the converted student comes back
  // null, __aeStudent simply stays null and every field falls back to the
  // legacy expression — no error, no partial render. Each field also falls
  // back individually if the engine path returns null for just that field,
  // so a partially-populated `sr` never produces a partially-blank card
  // that idle legacy code would otherwise have filled in.
  // EXAM-3.2B-3: single report-card data-source gate. ONE try/catch, ONE
  // fallback convergence point. __aeStudent is the single source handed to
  // the field selection below: either it holds a fully computed AND fully
  // validated adapted student, or it is null and every field falls through
  // to the legacy `sr.<field> ?? '—'` expression. There is no third state
  // and no nested fallback chain — every failure mode below (unavailable
  // AcademicEngine/Flags/compute/Adapter, an unavailable Compare, an
  // exception thrown anywhere in compute/Adapter/Compare, or a validation
  // mismatch) sets __aeStudent to null through this same single path.
  let __aeStudent = null;
  if (typeof AcademicEngine !== 'undefined' && AcademicEngine &&
      AcademicEngine.Flags && typeof AcademicEngine.Flags.get === 'function' &&
      AcademicEngine.Flags.get().useAcademicReportCard === true &&
      AcademicEngine.ReportCard && typeof AcademicEngine.ReportCard.compute === 'function' &&
      AcademicEngine.ReportCard.Adapter && typeof AcademicEngine.ReportCard.Adapter.convert === 'function') {
    try {
      const srId = (sr && sr.studentId != null) ? sr.studentId : (student && student.id);
      const srForEngine = Object.assign({}, sr, {
        studentId: srId,
        name: (sr && sr.name != null) ? sr.name : (student && student.name),
        admissionNo: (sr && sr.admissionNo != null) ? sr.admissionNo : (student && student.admissionNo),
        className: (sr && sr.className != null) ? sr.className : (student && (student.className || student.cls))
      });
      const classResultForEngine = { examId: exam && exam.id, className: srForEngine.className, students: [srForEngine] };
      const rankingClassForEngine = { students: [{ studentId: srId, classRank: sr && sr.classRank, schoolRank: sr && sr.schoolRank }] };
      const originalClassForEngine = { students: [{ studentId: srId }] };

      const computed = AcademicEngine.ReportCard.compute(classResultForEngine, null);
      const classReport = (computed && computed.classReport) || null;
      const converted = AcademicEngine.ReportCard.Adapter.convert(classReport, rankingClassForEngine, originalClassForEngine);
      const legacyStudents = converted && converted.legacyClass && Array.isArray(converted.legacyClass.students)
        ? converted.legacyClass.students : [];
      const candidate = legacyStudents.length ? legacyStudents[0] : null;

      // Validation: default to "trust the candidate" only when there's a
      // candidate at all; if Compare.compare exists, that trust must be
      // earned by matched === true. Either way this resolves to a single
      // boolean feeding the single assignment below — no separate gate.
      let validated = candidate !== null;
      if (candidate && AcademicEngine.ReportCard.Compare &&
          typeof AcademicEngine.ReportCard.Compare.compare === 'function') {
        const legacyClassReport = { students: [{
          total: sr.totalMarks ?? null,
          percentage: sr.pct ?? null,
          grade: sr.grade ?? null,
          gradePoints: sr.gradePoints ?? sr.points ?? null,
          passFail: sr.result ?? null,
          attendance: sr.attendance ?? null
        }] };
        const adaptedClassReport = { students: [{
          total: candidate.totalMarks ?? null,
          percentage: candidate.pct ?? null,
          grade: candidate.grade ?? null,
          gradePoints: candidate.gradePoints ?? candidate.points ?? null,
          passFail: candidate.result ?? null,
          attendance: candidate.attendance ?? null
        }] };
        const cmp = AcademicEngine.ReportCard.Compare.compare(legacyClassReport, adaptedClassReport);
        validated = !!(cmp && cmp.classComparison && cmp.classComparison.matched === true);
      }

      __aeStudent = validated ? candidate : null;
    } catch (e) { __aeStudent = null; }
  }

  const totalMarks = (__aeStudent && __aeStudent.totalMarks != null) ? __aeStudent.totalMarks : (sr.totalMarks ?? '—');
  const maxTotal   = (__aeStudent && __aeStudent.maxTotal   != null) ? __aeStudent.maxTotal   : (sr.maxTotal   ?? '—');
  const pct        = (__aeStudent && __aeStudent.pct        != null) ? __aeStudent.pct        : (sr.pct        ?? '—');
  const grade      = (__aeStudent && __aeStudent.grade      != null) ? __aeStudent.grade      : (sr.grade      ?? '—');
  const result     = (__aeStudent && __aeStudent.result     != null) ? __aeStudent.result     : (sr.result     ?? '—');
  const rank       = (__aeStudent && __aeStudent.classRank  != null) ? __aeStudent.classRank  : (sr.classRank  ?? '—');

  const subjectRows = maps.map(sm => {
    const m = subjectMarks[sm.subjectName];
    if (!m) return `<tr><td>${examSanitize(sm.subjectName)}</td><td colspan="6" style="text-align:center;color:var(--exam-text-muted)">—</td></tr>`;
    const maxT = (sm.theoryMax || 0) + (sm.practMax || 0) + (sm.intMax || 0);
    return `
      <tr>
        <td style="text-align:left">${examSanitize(sm.subjectName)}</td>
        <td>${sm.theoryMax || '—'}</td>
        <td>${m.absent ? 'AB' : (m.theory ?? '—')}</td>
        <td>${sm.practMax ? (m.absent ? 'AB' : (m.pract ?? '—')) : '—'}</td>
        <td>${sm.intMax ? (m.absent ? 'AB' : (m.internal ?? '—')) : '—'}</td>
        <td><strong>${m.absent ? 'AB' : (m.total ?? '—')}</strong>/${maxT}</td>
        <td><span class="exam-badge ${m.absent ? 'exam-badge-warning' : m.result==='Pass' ? 'exam-badge-success' : 'exam-badge-danger'}">${m.absent ? 'Absent' : m.grade}</span></td>
      </tr>`;
  }).join('');

  if (design === 'modern') return examRCModern(student, exam, schoolName, subjectRows, totalMarks, maxTotal, pct, grade, result, rank);
  if (design === 'minimal') return examRCMinimal(student, exam, schoolName, subjectRows, totalMarks, maxTotal, pct, grade, result, rank);
  return examRCClassic(student, exam, schoolName, subjectRows, totalMarks, maxTotal, pct, grade, result, rank);
}

function examRCClassic(student, exam, schoolName, subjectRows, totalMarks, maxTotal, pct, grade, result, rank) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examRCClassic(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examRCClassic(student, exam, schoolName, subjectRows, totalMarks, maxTotal, pct, grade, result, rank);
  }
  return `
    <div class="rc-page rc-classic">
      <div class="rc-header-classic">
        <div class="rc-school-name">☆ ${examSanitize(schoolName)} ☆</div>
        <div class="rc-report-label">PROGRESS REPORT CARD</div>
        <div style="font-size:12px;margin-top:4px;opacity:0.8">${examSanitize(exam.name)} — ${examSanitize(exam.yearName || '')}</div>
      </div>
      <div class="rc-student-info">
        <div class="rc-info-row"><span class="rc-info-label">Student Name</span><span>: <strong>${examSanitize(student.name)}</strong></span></div>
        <div class="rc-info-row"><span class="rc-info-label">Adm. No.</span><span>: ${examSanitize(student.admissionNo || '—')}</span></div>
        <div class="rc-info-row"><span class="rc-info-label">Class</span><span>: ${examSanitize(student.className || exam.applicableClass || '—')}</span></div>
        <div class="rc-info-row"><span class="rc-info-label">Term</span><span>: ${examSanitize(exam.termName || '—')}</span></div>
        <div class="rc-info-row"><span class="rc-info-label">Exam Period</span><span>: ${examFormatDate(exam.startDate)} – ${examFormatDate(exam.endDate)}</span></div>
        <div class="rc-info-row"><span class="rc-info-label">Class Rank</span><span>: <strong>${rank}</strong></span></div>
      </div>
      <table class="rc-marks-table">
        <thead><tr><th style="text-align:left">Subject</th><th>Max</th><th>Theory</th><th>Practical</th><th>Internal</th><th>Total</th><th>Grade</th></tr></thead>
        <tbody>${subjectRows}</tbody>
      </table>
      <div class="rc-summary">
        <div class="rc-summary-item"><div class="rc-summary-val">${totalMarks}/${maxTotal}</div><div class="rc-summary-label">Total Marks</div></div>
        <div class="rc-summary-item"><div class="rc-summary-val">${pct}%</div><div class="rc-summary-label">Percentage</div></div>
        <div class="rc-summary-item"><div class="rc-summary-val">${grade}</div><div class="rc-summary-label">Overall Grade</div></div>
        <div class="rc-summary-item"><div class="rc-summary-val">${rank}</div><div class="rc-summary-label">Class Rank</div></div>
        <div class="rc-summary-item"><div class="rc-summary-val" style="color:${result==='Pass'?'var(--exam-green)':'var(--exam-red)'}">${result}</div><div class="rc-summary-label">Result</div></div>
      </div>
      <div class="rc-footer">
        <span>Class Teacher's Sign: ___________________</span>
        <span>Principal's Sign: ___________________</span>
        <span>Parent's Sign: ___________________</span>
      </div>
    </div>`;
}

