function examPrintCurrentRC() {
  const content = document.getElementById('examRCPreviewContent')?.innerHTML || '';
  const win = window.open('', '', 'width=900,height=800');
  win.document.write(`<html><head><title>Report Card</title>
    <style>
      @page{size:A4;margin:8mm;}
      *{box-sizing:border-box;}
      html,body{margin:0;padding:0;font-family:sans-serif;}
      body{padding:0;}
      .rc-page{margin-bottom:40px;border:1px solid #ddd;page-break-after:always}
      .rc-header-classic,.rc-header-modern{color:#fff}
      .rc-header-classic{background:#1e3a5f;padding:20px;text-align:center}
      .rc-header-modern{background:#1e3a5f;padding:24px;display:flex;align-items:center;gap:16px}
      .rc-school-name{font-size:18px;font-weight:700}
      .rc-report-label{font-size:12px;opacity:0.8;margin-top:4px}
      .rc-student-info{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:16px;border-bottom:2px solid #e2e8f0;font-size:12px}
      .rc-info-row{display:flex;gap:6px}.rc-info-label{font-weight:600;min-width:90px;color:#64748b}
      .rc-marks-table{width:100%;border-collapse:collapse;font-size:12px}
      .rc-marks-table th{background:#1e3a5f;color:#fff;padding:8px;text-align:center}
      .rc-marks-table td{padding:6px 8px;border-bottom:1px solid #e2e8f0;text-align:center}
      .rc-marks-table tbody tr:nth-child(even){background:#f8fafc}
      .rc-summary{padding:12px;border-top:2px solid #e2e8f0;display:flex;justify-content:space-around}
      .rc-summary-val{font-size:16px;font-weight:800;text-align:center}
      .rc-summary-label{font-size:10px;text-align:center;text-transform:uppercase;color:#64748b}
      .rc-footer{padding:10px 16px;background:#f8fafc;display:flex;justify-content:space-between;font-size:11px}
      .exam-badge{padding:2px 8px;border-radius:99px;font-size:10px;font-weight:600}
      .exam-badge-success{background:#ecfdf5;color:#10b981}
      .exam-badge-danger{background:#fef2f2;color:#ef4444}
      .exam-badge-warning{background:#fffbeb;color:#f59e0b}
      .exam-badge-info{background:#eff6ff;color:#3b82f6}
      @media print{.rc-page{page-break-after:always}}
      /* Annual / Semester 1 Report Card — sized to fill one A4 page */
      .print-area.card{
        margin:0 auto;
        width:100%;
        max-width:194mm;         /* A4 (210mm) minus 2×8mm page margin */
        min-height:277mm;        /* A4 (297mm) minus 2×8mm page margin — stretches to fill the page */
        display:flex;
        flex-direction:column;
        page-break-after:always;
        box-sizing:border-box;
      }
      .print-area.card:last-child{page-break-after:avoid;}
      .rc-table{width:100%;border-collapse:collapse;margin-bottom:8px;}
      .rc-table th,.rc-table td{border:1px solid #999;padding:5px 7px;font-size:12.5px;}
      .rc-table th{background:#1a3a6b;color:#fff;font-weight:700;}
      @media print{
        .print-area.card{min-height:0;}
      }
    </style></head><body>${content}</body></html>`);
  win.document.close();
  setTimeout(() => win.print(), 500);
}

function examBulkPrintReportCards() {
  examGenerateReportCard();
  setTimeout(() => {
    const content = document.getElementById('examRCPreviewContent')?.innerHTML || '';
    if (!content.trim()) return; // blocked by result-processing/fee gates — nothing to print
    examPrintCurrentRC();
  }, 800);
}

function examCloseRCPreview() {
  document.getElementById('examRCPreviewArea').style.display = 'none';
  document.getElementById('examRCPreviewContent').innerHTML = '';
}

/* ═══════════════════════════════════════════════
   SECTION R — MERIT LIST & TOPPERS
═══════════════════════════════════════════════ */

let examCurrentMeritTab = 'school';

function examPopulateMLFilters() {
  const exams = examRetrieve('examinations', []);
  const sel = document.getElementById('mlExam');
  if (!sel) return;
  sel.innerHTML = '<option value="">— Examination —</option>' +
    exams.map(e => `<option value="${e.id}">${examSanitize(e.name)}</option>`).join('');
}

function examSwitchMeritTab(tab, btn) {
  examCurrentMeritTab = tab;
  document.querySelectorAll('.exam-merit-tab').forEach(t => t.classList.remove('active'));
  if (btn) btn.classList.add('active');
  examRenderMeritList();
}

function examRenderMeritList() {
  const examId = document.getElementById('mlExam')?.value;
  const wrap = document.getElementById('examMeritTableWrap');
  const podium = document.getElementById('examPodium');
  if (!wrap) return;

  if (!examId) {
    wrap.innerHTML = '<div class="exam-empty-state"><div class="exam-empty-icon">🏆</div><div>Select an examination to generate merit list</div></div>';
    if (podium) podium.style.display = 'none';
    return;
  }

  const results = examRetrieve('results', {});
  const examResults = results[examId] || {};

  const allStudents = [];
  Object.values(examResults).forEach(cls => Object.values(cls).forEach(s => allStudents.push(s)));

  if (!allStudents.length) {
    wrap.innerHTML = '<div class="exam-empty-state"><div class="exam-empty-icon">📊</div><div>No results processed. Run Result Processing first.</div></div>';
    if (podium) podium.style.display = 'none';
    return;
  }

  const tab = examCurrentMeritTab;

  if (tab === 'school') {
    const sorted = allStudents.filter(s => s.result !== 'Absent').sort((a, b) => b.pct - a.pct);
    examRenderPodium(sorted.slice(0, 3));
    wrap.innerHTML = examBuildMeritTable(sorted, ['Rank','Adm No','Name','Class','Total','%','Grade','Result'], s => [
      `<strong>#${s.schoolRank}</strong>`, examSanitize(s.admissionNo||'—'), examSanitize(s.name),
      `Class ${examSanitize(s.className)}`, `${examRound(s.totalMarks)}/${s.maxTotal}`,
      `<strong>${s.pct}%</strong>`, `<span class="exam-badge exam-badge-info">${s.grade}</span>`,
      `<span class="exam-badge exam-badge-success">${s.result}</span>`
    ]);
  }
  else if (tab === 'class') {
    const classes = [...new Set(allStudents.map(s => s.className))];
    let html = '';
    classes.forEach(cls => {
      const classStudents = allStudents.filter(s => s.className === cls && s.result !== 'Absent').sort((a,b) => b.pct - a.pct);
      html += `<div style="margin-bottom:24px"><div style="font-size:13px;font-weight:700;padding:8px 12px;background:#f8fafc;border-bottom:2px solid var(--exam-navy)">Class ${examSanitize(cls)}</div>`;
      html += examBuildMeritTable(classStudents, ['Class Rank','Adm No','Name','Total','%','Grade'], s => [
        `<strong>#${s.classRank}</strong>`, examSanitize(s.admissionNo||'—'), examSanitize(s.name),
        `${examRound(s.totalMarks)}/${s.maxTotal}`, `<strong>${s.pct}%</strong>`, `<span class="exam-badge exam-badge-info">${s.grade}</span>`
      ]);
      html += '</div>';
    });
    wrap.innerHTML = html;
    if (podium) podium.style.display = 'none';
  }
  else if (tab === 'division') {
    const divGroups = {};
    allStudents.forEach(s => {
      const key = `${s.className}-${s.division}`;
      if (!divGroups[key]) divGroups[key] = [];
      divGroups[key].push(s);
    });
    let html = '';
    Object.keys(divGroups).forEach(key => {
      const [cls, div] = key.split('-');
      const sorted = divGroups[key].filter(s => s.result !== 'Absent').sort((a,b) => b.pct - a.pct);
      if (!sorted.length) return;
      html += `<div style="margin-bottom:20px"><div style="font-size:13px;font-weight:700;padding:8px 12px;background:#f8fafc;border-bottom:2px solid var(--exam-navy)">Class ${examSanitize(cls)} — Division ${examSanitize(div)}</div>`;
      html += examBuildMeritTable(sorted.slice(0, 10), ['Rank','Adm No','Name','%','Grade'], s => [
        `<strong>#${s.classRank}</strong>`, examSanitize(s.admissionNo||'—'), examSanitize(s.name),
        `<strong>${s.pct}%</strong>`, `<span class="exam-badge exam-badge-info">${s.grade}</span>`
      ]);
      html += '</div>';
    });
    wrap.innerHTML = html || '<div class="exam-empty-state"><div>No data</div></div>';
    if (podium) podium.style.display = 'none';
  }
  else if (tab === 'subject') {
    const examId2 = document.getElementById('mlExam')?.value;
    const maps = examRetrieve('subjectMap', []).filter(m => m.examId === examId2);
    const subjects = [...new Set(maps.map(m => m.subjectName))];
    let html = '';

    subjects.forEach(subj => {
      const subjectToppers = [];
      allStudents.forEach(s => {
        const subjResult = s.subjectResults?.[subj];
        if (subjResult && !subjResult.absent) {
          subjectToppers.push({ ...s, subjPct: subjResult.pct || 0, subjTotal: subjResult.total, subjGrade: subjResult.grade });
        }
      });
      subjectToppers.sort((a,b) => b.subjPct - a.subjPct);
      if (!subjectToppers.length) return;

      html += `<div style="margin-bottom:20px"><div style="font-size:13px;font-weight:700;padding:8px 12px;background:#f8fafc;border-bottom:2px solid var(--exam-navy)">${examSanitize(subj)}</div>`;
      html += examBuildMeritTable(subjectToppers.slice(0, 5), ['Rank','Adm No','Name','Class','Marks','%','Grade'], (s,i) => [
        `<strong>#${i+1}</strong>`, examSanitize(s.admissionNo||'—'), examSanitize(s.name),
        `Class ${examSanitize(s.className)}`, s.subjTotal, `<strong>${s.subjPct}%</strong>`,
        `<span class="exam-badge exam-badge-info">${s.subjGrade}</span>`
      ]);
      html += '</div>';
    });

    wrap.innerHTML = html || '<div class="exam-empty-state"><div>No subject data</div></div>';
    if (podium) podium.style.display = 'none';
  }
}

function examBuildMeritTable(rows, headers, cellFn) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examBuildMeritTable(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examBuildMeritTable(rows, headers, cellFn);
  }
  if (!rows.length) return '<div class="exam-empty-state" style="padding:20px"><div>No data</div></div>';
  const thead = `<tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>`;
  const tbody = rows.map((r, i) => {
    const rowStyle = i === 0 ? 'background:rgba(240,180,41,0.12)' : i === 1 ? 'background:rgba(156,163,175,0.1)' : i === 2 ? 'background:rgba(205,124,47,0.1)' : '';
    return `<tr style="${rowStyle}">${cellFn(r, i).map(c => `<td>${c}</td>`).join('')}</tr>`;
  }).join('');
  return `<div class="exam-table-wrap"><table class="exam-table"><thead>${thead}</thead><tbody>${tbody}</tbody></table></div>`;
}

function examRenderPodium(top3) {
  const podium = document.getElementById('examPodium');
  if (!podium) return;

  if (top3.length < 1) { podium.style.display = 'none'; return; }
  podium.style.display = 'flex';

  const renderPlace = (id, s, rankLabel) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (!s) { el.innerHTML = ''; return; }
    el.innerHTML = `
      <div class="exam-podium-rank">${rankLabel}</div>
      <div style="font-size:28px">👤</div>
      <div class="exam-podium-name">${examSanitize(s.name)}</div>
      <div class="exam-podium-score">${s.pct}%</div>
      <div style="font-size:11px;opacity:0.8">Class ${examSanitize(s.className)}</div>`;
  };

  renderPlace('podium1st', top3[0], '🥇');
  renderPlace('podium2nd', top3[1], '🥈');
  renderPlace('podium3rd', top3[2], '🥉');
}

function examExportMeritCSV() {
  const examId = document.getElementById('mlExam')?.value;
  if (!examId) { examShowToast('Select examination', 'warning'); return; }
  const results = examRetrieve('results', {});
  const all = [];
  Object.values(results[examId] || {}).forEach(cls => Object.values(cls).forEach(s => all.push(s)));
  all.sort((a,b) => (a.schoolRank||999)-(b.schoolRank||999));
  const rows = [['School Rank','Class Rank','Adm No','Name','Class','Total','Max','%','Grade','Result']];
  all.forEach(s => rows.push([s.schoolRank,s.classRank,s.admissionNo,s.name,s.className,examRound(s.totalMarks),s.maxTotal,s.pct,s.grade,s.result]));
  examCSVDownload('merit_list.csv', rows);
  examShowToast('Merit list exported', 'info');
}

function examPrintMeritList() {
  const content = document.getElementById('examMeritTableWrap')?.innerHTML || '';
  const podiumHTML = document.getElementById('examPodium')?.style.display !== 'none'
    ? document.getElementById('examPodium')?.innerHTML || '' : '';
  const win = window.open('', '', 'width=900,height=700');
  win.document.write(`<html><head><title>Merit List</title>
    <style>
      body{font-family:sans-serif;padding:24px}
      table{width:100%;border-collapse:collapse;font-size:12px}
      th{background:#1e3a5f;color:#fff;padding:8px}
      td{padding:7px 8px;border-bottom:1px solid #e2e8f0}
      tr:nth-child(even){background:#f8fafc}
      .exam-badge{padding:2px 8px;border-radius:99px;font-size:10px;font-weight:600}
      .exam-badge-success{background:#ecfdf5;color:#10b981}
      .exam-badge-info{background:#eff6ff;color:#3b82f6}
      button{display:none}
    </style></head><body>
    <h2 style="color:#1e3a5f;margin-bottom:16px">Merit List — Dnyanankur School</h2>
    ${podiumHTML}${content}</body></html>`);
  win.document.close();
  win.print();
}

/* ═══════════════════════════════════════════════
   SECTION S — INITIALISATION
═══════════════════════════════════════════════ */

function examModuleInit() {
  // Seed default data
  examInitExamTypes();
  examInitGradeScales();

  // Pull Academic Years from the main ERP (page-acadyears / getAcademicYears())
  // so the Examination Center never drifts out of sync with the rest of the ERP.
  examSyncAcademicYearsFromERP();

  // Render master section (default active)
  examRenderAcademicYearList();
  examRenderTermList();
  examRenderExamTypeList();
  examRenderMasterTable();

  // Populate context selects
  examPopulateContextSelects();

  // Apply role-based tab visibility (Teacher vs Principal)
  if (typeof examApplyRoleNavVisibility === 'function') examApplyRoleNavVisibility();

  // Log ready
  console.info('[ExamModule] Initialised. All functions prefixed with exam*. Storage keys prefixed with examMod_*.');
}

// ERP INTEGRATION: auto-boot disabled. The standalone module used to call
// examModuleInit() immediately on DOMContentLoaded, but in the merged ERP
// this page is gated behind login + role check. The ERP's showPage()
// function now calls examModuleInit() lazily, exactly once, the first
// time the user navigates to the "Examination Center" page (see the
// 'examcenter' branch inside showPage() in the main ERP script).
//
// examModuleInit() and examAddendumInit() remain fully defined above/below
// and can still be called manually from the console if ever needed.



/* ===================== next inline <script> block ===================== */


/* ═══════════════════════════════════════════════════════════════════
   EXAMINATION MANAGEMENT MODULE — exam-module-addendum.js
   Dnyanankur School ERP
   
   ADDENDUM: Appended after exam-module.js — do NOT modify exam-module.js
   
   Contains:
   ┌─ T. Exam Clone / Duplicate
   ├─ U. Grace Marks Enforcement (save-time)
   ├─ V. Marks Grid Student Search / Filter
   ├─ W. Individual Student Result Modal
   ├─ X. Multi-Exam Progress Comparison Chart
   ├─ Y. Attendance % across subjects in result
   ├─ Z. Module Backup Export / Import
   ├─ AA. Demo / Test Data Seeder
   ├─ AB. Integration Notes section link
   └─ AC. Additional CSS overrides (injected via JS)
   
   All function names: exam* prefix — no conflicts with ERP.
   All storage keys:   examMod_* prefix.
═══════════════════════════════════════════════════════════════════ */

'use strict';

/* ═══════════════════════════════════════════════
   SECTION T — EXAM CLONE / DUPLICATE
   Adds "Clone" button per exam in the master table.
   Duplicates all exam metadata, subject mappings,
   and timetable — marks are NOT copied (intentional).
═══════════════════════════════════════════════ */

/**
 * examCloneExamination(sourceId)
 * Deep-clones an examination record, its subject mappings,
 * and its timetable entries into new records with new IDs.
 * Marks are intentionally excluded from cloning.
 */
function examCloneExamination(sourceId) {
  const exams = examRetrieve('examinations', []);
  const source = exams.find(e => e.id === sourceId);
  if (!source) { examShowToast('Source examination not found', 'danger'); return; }

  const newId   = examUID();
  const cloned  = {
    ...JSON.parse(JSON.stringify(source)),
    id: newId,
    name: 'Copy of ' + source.name,
    status: 'draft',
    isLocked: false,
    isPublished: false,
    createdAt: new Date().toISOString(),
  };
  delete cloned.lockedAt;
  delete cloned.publishedAt;

  exams.push(cloned);
  examStore('examinations', exams);

  // Clone subject mappings
  const maps = examRetrieve('subjectMap', []);
  const sourceMaps = maps.filter(m => m.examId === sourceId);
  const clonedMaps = sourceMaps.map(m => ({
    ...JSON.parse(JSON.stringify(m)),
    id: examUID(),
    examId: newId,
    examName: cloned.name,
  }));
  examStore('subjectMap', [...maps, ...clonedMaps]);

  // Clone timetable
  const slots = examRetrieve('timetable', []);
  const sourceSlots = slots.filter(s => s.examId === sourceId);
  const clonedSlots = sourceSlots.map(s => ({
    ...JSON.parse(JSON.stringify(s)),
    id: examUID(),
    examId: newId,
  }));
  examStore('timetable', [...slots, ...clonedSlots]);

  examRenderMasterTable();
  examShowToast(`Examination cloned: "${cloned.name}"`, 'success');

  // Open edit modal so user can rename immediately
  setTimeout(() => examOpenCreateExamModal(newId), 200);
}

/**
 * Patches the existing examRenderMasterTable to inject a Clone button.
 * Called once at addendum init — wraps the original renderer safely.
 */
function examPatchMasterTableCloneButton() {
  const origRender = window.examRenderMasterTable;
  if (!origRender || origRender._clonePatched) return;

  window.examRenderMasterTable = function () {
    origRender();
    // Inject Clone button into each action cell
    const rows = document.querySelectorAll('#examMasterTableBody tr');
    rows.forEach(row => {
      const actionCell = row.querySelector('td:last-child .exam-row-gap-8');
      if (!actionCell) return;
      // Extract exam id from existing edit button
      const editBtn = actionCell.querySelector('button[onclick*="examOpenCreateExamModal"]');
      if (!editBtn) return;
      const match = editBtn.getAttribute('onclick').match(/'([^']+)'/);
      if (!match) return;
      const examId = match[1];
      if (actionCell.querySelector('.clone-btn')) return; // already injected
      const cloneBtn = document.createElement('button');
      cloneBtn.className = 'exam-btn exam-btn-sm exam-btn-ghost clone-btn';
      cloneBtn.textContent = '⎘ Clone';
      cloneBtn.onclick = () => examCloneExamination(examId);
      actionCell.insertBefore(cloneBtn, actionCell.children[1]);
    });
  };
  window.examRenderMasterTable._clonePatched = true;
  window.examRenderMasterTable(); // re-render with clone buttons
}

/* ═══════════════════════════════════════════════
   SECTION U — GRACE MARKS ENFORCEMENT
   Validates grace marks at save-time:
   • Grace only applied when student is within
     graceLimitMarks of passing.
   • Warns teacher if grace pushes student over
     the exam's defined grace cap.
═══════════════════════════════════════════════ */

/**
 * examValidateGraceMarks(savedMarks, subjectMap, exam)
 * Returns { valid: bool, warnings: string[] }
 * Call before examSaveMarks commits to storage.
 */
function examValidateGraceMarks(savedMarksObj, subjectMap, exam) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examValidateGraceMarks(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examValidateGraceMarks(savedMarksObj, subjectMap, exam);
  }
  const warnings = [];
  const graceLimit = exam ? (exam.graceLimitMarks || 5) : 5;
  const maxTotal   = (subjectMap.theoryMax || 0) + (subjectMap.practMax || 0) + (subjectMap.intMax || 0);
  const passMark   = maxTotal * ((subjectMap.passPct || 35) / 100);

  Object.values(savedMarksObj).forEach(m => {
    if (m.absent || !m.grace || m.grace === 0) return;
    const rawTotal = (m.theory || 0) + (m.pract || 0) + (m.internal || 0);

    // Grace exceeds exam-level cap
    if (m.grace > graceLimit) {
      warnings.push(`${m.name}: Grace ${m.grace} exceeds exam limit of ${graceLimit} marks.`);
    }

    // Grace applied but student was already passing without it
    if (rawTotal >= passMark && m.grace > 0) {
      warnings.push(`${m.name}: Student was already passing — grace ${m.grace} may be unnecessary.`);
    }

    // Grace applied but still failing even with it
    if ((rawTotal + m.grace) < passMark) {
      warnings.push(`${m.name}: Even with grace ${m.grace}, student still fails.`);
    }
  });

  return { valid: warnings.length === 0, warnings };
}

/**
 * Patches examSaveMarks to run grace validation before committing.
 * Prompts user to confirm if warnings are found.
 */
function examPatchSaveMarksGraceValidation() {
  const origSave = window.examSaveMarks;
  if (!origSave || origSave._gracePatch) return;

  window.examSaveMarks = function () {
    const ctx = examCurrentMarksContext;
    if (!ctx || !ctx.subjectMap) { origSave(); return; }

    // Build a quick marks preview to validate
    const allStudents = ctx.allStudents || [];
    const sm = ctx.subjectMap;
    const exam = examRetrieve('examinations', []).find(e => e.id === ctx.examId) || {};
    const previewMarks = {};

    allStudents.forEach((student, idx) => {
      const sid = student.id || student.admissionNo || idx;
      const graceEl = document.querySelector(`.marks-grace[data-sid="${sid}"]`);
      const absentEl = document.querySelector(`.marks-absent[data-sid="${sid}"]`);
      const theoryEl = document.querySelector(`.marks-theory[data-sid="${sid}"]`);
      const practEl  = document.querySelector(`.marks-pract[data-sid="${sid}"]`);
      const intEl    = document.querySelector(`.marks-int[data-sid="${sid}"]`);
      const grace    = graceEl ? parseFloat(graceEl.value) || 0 : 0;
      const theory   = theoryEl ? parseFloat(theoryEl.value) || 0 : 0;
      const pract    = practEl  ? parseFloat(practEl.value)  || 0 : 0;
      const internal = intEl    ? parseFloat(intEl.value)    || 0 : 0;
      if (grace > 0) {
        previewMarks[sid] = { name: student.name, grace, theory, pract, internal, absent: absentEl?.checked || false };
      }
    });

    const { valid, warnings } = examValidateGraceMarks(previewMarks, sm, exam);
    if (!valid) {
      const msg = 'Grace marks warnings:\n\n' + warnings.join('\n') + '\n\nProceed with save anyway?';
      if (!confirm(msg)) return;
    }
    origSave();
  };
  window.examSaveMarks._gracePatch = true;
}

/* ═══════════════════════════════════════════════
   SECTION V — MARKS GRID STUDENT SEARCH / FILTER
   Adds a live search bar above the marks grid
   that filters the visible rows by student name
   or admission number without losing entered data.
═══════════════════════════════════════════════ */

/**
 * examInjectMarksSearchBar()
 * Inserts a search bar into the marks grid card header
 * if one doesn't already exist.
 */
function examInjectMarksSearchBar() {
  const cardHeader = document.querySelector('#examMarksGridCard .exam-card-header');
  if (!cardHeader || cardHeader.querySelector('#examMarksStudentSearch')) return;

  const searchWrap = document.createElement('div');
  searchWrap.style.cssText = 'display:flex;align-items:center;gap:8px;margin-left:auto';
  searchWrap.innerHTML = `
    <input type="text" id="examMarksStudentSearch" class="exam-input exam-input-sm"
      placeholder="🔍 Search student…" style="width:180px"
      oninput="examFilterMarksGridRows(this.value)"/>
    <select id="examMarksResultFilter" class="exam-select exam-select-sm" onchange="examFilterMarksGridRows(document.getElementById('examMarksStudentSearch').value)">
      <option value="">All</option>
      <option value="Pass">Pass</option>
      <option value="Fail">Fail</option>
      <option value="Absent">Absent</option>
      <option value="blank">Not Entered</option>
    </select>`;

  // Insert before the action buttons group
  const actionsDiv = cardHeader.querySelector('.exam-row-gap-8');
  cardHeader.insertBefore(searchWrap, actionsDiv);
}

/**
 * examFilterMarksGridRows(query)
 * Hides/shows marks table rows matching the search query.
 * Works purely on DOM — does not affect stored data.
 */
function examFilterMarksGridRows(query) {
  const q = (query || '').toLowerCase().trim();
  const resultFilter = document.getElementById('examMarksResultFilter')?.value || '';
  const rows = document.querySelectorAll('#examMarksGridBody tr');

  rows.forEach(row => {
    const nameCell = row.cells[2];
    const admCell  = row.cells[1];
    const resultCell = row.querySelector('.marks-computed:last-child');

    if (!nameCell) return;

    const nameText = nameCell.textContent.toLowerCase();
    const admText  = admCell ? admCell.textContent.toLowerCase() : '';
    const resultText = resultCell ? resultCell.textContent.trim() : '';

    const matchQ = !q || nameText.includes(q) || admText.includes(q);
    const matchR = !resultFilter
      ? true
      : resultFilter === 'blank'
        ? (resultText === '—' || resultText === '')
        : resultText.includes(resultFilter);

    row.style.display = (matchQ && matchR) ? '' : 'none';
  });
}

/**
 * Patches examLoadMarksGrid to inject search bar after grid renders.
 */
function examPatchMarksGridSearch() {
  const orig = window.examLoadMarksGrid;
  if (!orig || orig._searchPatch) return;

  window.examLoadMarksGrid = function () {
    orig();
    // Small delay to let DOM render
    setTimeout(examInjectMarksSearchBar, 60);
  };
  window.examLoadMarksGrid._searchPatch = true;
}

/* ═══════════════════════════════════════════════
   SECTION W — INDIVIDUAL STUDENT RESULT MODAL
   Full per-student result card in a modal:
   shows each subject, totals, grade, rank,
   comparison to class average, and attendance.
═══════════════════════════════════════════════ */

/**
 * examViewStudentResult(studentId, examId, className)
 * Opens a detailed modal for one student's complete result.
 * Can be called from Class Result table, Rank List, or Merit List.
 */
function examViewStudentResult(studentId, examId, className) {
  if (!studentId || !examId || !className) {
    examShowToast('Missing context for student result view', 'warning'); return;
  }

  const exams   = examRetrieve('examinations', []);
  const exam    = exams.find(e => e.id === examId);
  if (!exam) { examShowToast('Examination not found', 'danger'); return; }

  const maps    = examRetrieve('subjectMap', []).filter(m => m.examId === examId && m.className === className);
  const results = examRetrieve('results', {});
  const sr      = results[examId]?.[className]?.[studentId] || {};
  // ERP INTEGRATION: real school name via getSettings()
  let schoolName = 'Dnyanankur School';
  try {
    if (typeof getSettings === 'function') schoolName = getSettings().name || schoolName;
    else schoolName = localStorage.getItem('schoolName') || schoolName;
  } catch (e) {}

  // Build per-subject rows
  let totalPresent = 0, totalAbsent = 0;
  const subjectRows = maps.map(sm => {
    const marksKey = `marks_${examId}_${className}_${sm.division}_${sm.id}`;
    const m = examRetrieve(marksKey, {})[studentId];
    if (!m) return `<tr><td colspan="8" style="color:var(--exam-text-muted);text-align:center">${examSanitize(sm.subjectName)} — No marks entered</td></tr>`;

    const maxT = (sm.theoryMax || 0) + (sm.practMax || 0) + (sm.intMax || 0);
    if (m.absent) { totalAbsent++; }
    else { totalPresent++; }

    // Class average for this subject
    const allStudents = examGetStudentsForClass(className, sm.division === 'All' ? 'All' : sm.division);
    const savedAll    = examRetrieve(marksKey, {});
    const classAvgPct = (() => {
      const pcts = Object.values(savedAll).filter(x => !x.absent && typeof x.pct === 'number').map(x => x.pct);
      return pcts.length ? examRound(pcts.reduce((a, b) => a + b, 0) / pcts.length) : 0;
    })();

    const diff = m.absent ? null : examRound((m.pct || 0) - classAvgPct);
    const diffStr = diff === null ? '—'
      : diff > 0 ? `<span style="color:var(--exam-green)">+${diff}%</span>`
      : diff < 0 ? `<span style="color:var(--exam-red)">${diff}%</span>`
      : `<span style="color:var(--exam-text-muted)">0%</span>`;

    const resultBadge = m.absent
      ? '<span class="exam-badge exam-badge-warning">Absent</span>'
      : m.result === 'Pass'
        ? '<span class="exam-badge exam-badge-success">Pass</span>'
        : '<span class="exam-badge exam-badge-danger">Fail</span>';

    return `<tr>
      <td style="text-align:left;font-weight:500">${examSanitize(sm.subjectName)}</td>
      <td>${m.absent ? '—' : (m.theory ?? '—')}<small style="color:var(--exam-text-light)">/${sm.theoryMax||0}</small></td>
      <td>${sm.practMax ? (m.absent ? '—' : (m.pract ?? '—')) : '<span style="color:var(--exam-text-light)">N/A</span>'}</td>
      <td>${sm.intMax ? (m.absent ? '—' : (m.internal ?? '—')) : '<span style="color:var(--exam-text-light)">N/A</span>'}</td>
      <td>${m.grace || 0}</td>
      <td><strong>${m.absent ? 'AB' : (m.total ?? '—')}</strong>/${maxT}</td>
      <td>${m.absent ? '—' : (m.pct ?? '—') + '%'} ${diffStr}</td>
      <td>${resultBadge}</td>
    </tr>`;
  }).join('');

  const totalSubjects   = maps.length;
  // RENAMED (marks-entry attendance clarity fix): this is "papers appeared
  // for", i.e. how many of this exam's subjects were NOT marked absent —
  // it was previously shown under the plain label "Attendance", which
  // collided with the Report Card's completely different day-to-day school
  // attendance figure and made the two screens look like they disagreed.
  // The calculation itself is unchanged; only the variable name and the
  // label below were touched.
  const examAttendancePct = totalSubjects > 0 ? examRound((totalPresent / totalSubjects) * 100) : 0;
  const overallPct      = sr.pct ?? '—';
  const overallGrade    = sr.grade ?? '—';
  const overallResult   = sr.result ?? '—';
  const classRank       = sr.classRank ?? '—';
  const schoolRank      = sr.schoolRank ?? '—';

  // ADDITIVE (marks-entry attendance clarity fix): real day-to-day school
  // attendance for this student over the exam's term, computed via the
  // EXACT SAME path the Report Card uses (rcTermDateRange /
  // rcFullYearDateRange + AttEngine.computeRangeSummary, RECORDED days as
  // denominator — see rcAttendanceCell()) so this figure can never disagree
  // with what the Report Card shows. Wrapped defensively — if anything is
  // unavailable this silently renders nothing, exactly as rcAttendanceCell
  // already does; no existing behavior above this block is touched.
  let dailyAttendanceBadge = '';
  try {
    if (window.AttEngine && typeof getStudents === 'function') {
      const stu = getStudents().find(x => String(x.id) === String(studentId));
      if (stu) {
        const personId = String(stu.id || stu.admno || stu.rollNo || stu.name);
        const stuClassName = (stu.cls || '') + (stu.div ? (' - ' + stu.div) : '');
        const termNum = (exam && exam.termName || '').toLowerCase().includes('2') ? 2 : 1;
        const range = (typeof rcTermDateRange === 'function' ? rcTermDateRange(termNum) : null)
          || (typeof rcFullYearDateRange === 'function' ? rcFullYearDateRange() : null);
        const summary = range
          ? window.AttEngine.computeRangeSummary(personId, 'student', stu.name, stuClassName, range.startDate, range.endDate)
          : null;
        if (summary && summary.recordedDays) {
          const presentShown = Math.round(summary.effectivePresent);
          const recorded = summary.recordedDays;
          const dPct = recorded > 0 ? Math.round((presentShown / recorded) * 100) : 0;
          dailyAttendanceBadge = `<span>🏫 Daily Attendance: <strong>${dPct}%</strong> (${presentShown}/${recorded} school day(s))</span>`;
        }
      }
    }
  } catch (e) { /* cosmetic addition only — never blocks the result modal */ }

  const resultColor = overallResult === 'Pass' ? 'var(--exam-green)' : overallResult === 'Fail' ? 'var(--exam-red)' : 'var(--exam-orange)';

  const body = `
    <div style="margin-bottom:16px;padding:16px;background:linear-gradient(135deg,var(--exam-navy),var(--exam-navy-light));border-radius:var(--exam-radius);color:#fff">
      <div style="font-size:20px;font-weight:800">${examSanitize(sr.name || studentId)}</div>
      <div style="font-size:12px;opacity:0.8;margin-top:3px">
        Adm: ${examSanitize(sr.admissionNo || '—')} &nbsp;|&nbsp; Class: ${examSanitize(className)} &nbsp;|&nbsp; ${examSanitize(exam.name)}
      </div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:20px">
      ${[
        ['Total', `${sr.totalMarks !== undefined ? examRound(sr.totalMarks) : '—'}/${sr.maxTotal || '—'}`, 'var(--exam-navy)'],
        ['Percentage', overallPct !== '—' ? overallPct + '%' : '—', 'var(--exam-blue)'],
        ['Grade', overallGrade, 'var(--exam-gold-dark)'],
        ['Class Rank', '#' + classRank, 'var(--exam-purple)'],
        ['Result', overallResult, resultColor],
      ].map(([label, val, color]) => `
        <div style="text-align:center;padding:12px;background:#f8fafc;border-radius:var(--exam-radius-sm);border:1px solid var(--exam-border)">
          <div style="font-size:20px;font-weight:800;color:${color}">${val}</div>
          <div style="font-size:10px;text-transform:uppercase;color:var(--exam-text-muted);margin-top:2px">${label}</div>
        </div>`).join('')}
    </div>

    <div style="display:flex;gap:10px;margin-bottom:16px;font-size:12px;flex-wrap:wrap">
      <span>📄 Exam Attendance: <strong>${examAttendancePct}%</strong> (${totalPresent}/${totalSubjects} paper(s) appeared)</span>
      ${dailyAttendanceBadge}
      <span>🏫 School Rank: <strong>#${schoolRank}</strong></span>
      <span>📋 Term: <strong>${examSanitize(exam.termName || '—')}</strong></span>
    </div>

    <div class="exam-table-wrap" style="border:1px solid var(--exam-border);border-radius:var(--exam-radius-sm);overflow:hidden">
      <table class="exam-table" style="min-width:600px">
        <thead>
          <tr>
            <th style="text-align:left">Subject</th>
            <th>Theory</th><th>Practical</th><th>Internal</th>
            <th>Grace</th><th>Total</th>
            <th>% (vs Class Avg)</th><th>Result</th>
          </tr>
        </thead>
        <tbody>${subjectRows}</tbody>
      </table>
    </div>

    ${sr.remark ? `<div style="margin-top:16px;padding:12px;background:var(--exam-orange-bg);border-radius:var(--exam-radius-sm);font-size:12px"><strong>Remarks:</strong> ${examSanitize(sr.remark)}</div>` : ''}`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Close</button>
    <button class="exam-btn exam-btn-primary" onclick="examPrintStudentResultCard('${studentId}','${examId}','${className}')">🖨 Print Result</button>`;

  examOpenModal(`Student Result — ${examSanitize(sr.name || studentId)}`, body, footer, true);
}

/**
 * examPrintStudentResultCard(studentId, examId, className)
 * Prints a single-student result card directly.
 */
function examPrintStudentResultCard(studentId, examId, className) {
  const body = document.getElementById('examModalBody')?.innerHTML || '';
  const win  = window.open('', '', 'width=900,height=700');
  win.document.write(`<html><head><title>Student Result</title>
    <style>
      body{font-family:sans-serif;padding:24px;font-size:13px}
      table{width:100%;border-collapse:collapse}
      th{background:#1e3a5f;color:#fff;padding:8px;text-align:center}
      td{padding:7px 10px;border-bottom:1px solid #e2e8f0;text-align:center}
      .exam-badge{padding:2px 8px;border-radius:99px;font-size:10px;font-weight:600}
      .exam-badge-success{background:#ecfdf5;color:#10b981}
      .exam-badge-danger{background:#fef2f2;color:#ef4444}
      .exam-badge-warning{background:#fffbeb;color:#f59e0b}
      button{display:none}
    </style></head><body>${body}</body></html>`);
  win.document.close();
  setTimeout(() => win.print(), 400);
}

/**
 * Patches the class result table to add a View button per row.
 */
function examPatchClassResultViewButton() {
  const origRender = window.examRenderClassResult;
  if (!origRender || origRender._viewPatch) return;

  window.examRenderClassResult = function () {
    origRender();
    const examId    = document.getElementById('crExam')?.value;
    const className = document.getElementById('crClass')?.value;
    if (!examId || !className) return;

    // Add View column header if not present
    const thead = document.getElementById('examClassResultHead');
    if (thead && !thead.querySelector('.view-col')) {
      const th = document.createElement('th');
      th.className = 'view-col';
      th.textContent = 'View';
      thead.appendChild(th);
    }

    // Add View button to each body row
    const rows = document.querySelectorAll('#examClassResultBody tr');
    rows.forEach(row => {
      if (row.querySelector('.view-result-btn')) return;
      // Extract adm no from 2nd cell
      const admCell = row.cells[1];
      if (!admCell) return;
      const admNo = admCell.textContent.trim();

      // Find student id from ERP storage
      const students = examGetStudentsForClass(className, 'All');
      const student  = students.find(s => (s.admissionNo || s.id || '') === admNo);
      if (!student) {
        row.insertAdjacentHTML('beforeend', '<td>—</td>');
        return;
      }

      const td = document.createElement('td');
      td.innerHTML = `<button class="exam-btn exam-btn-sm exam-btn-outline view-result-btn"
        onclick="examViewStudentResult('${student.id}','${examId}','${className}')">👁 View</button>`;
      row.appendChild(td);
    });
  };
  window.examRenderClassResult._viewPatch = true;
}

/* ═══════════════════════════════════════════════
   SECTION X — MULTI-EXAM PROGRESS COMPARISON
   A dedicated comparison view added into the
   Analysis section. Shows how a class performs
   across multiple exams of the same academic year.
═══════════════════════════════════════════════ */

let examChartProgressComparison = null;

/**
 * examOpenProgressComparisonModal()
 * Opens a modal with a multi-exam comparison line chart.
 */
function examOpenProgressComparisonModal() {
  const exams   = examRetrieve('examinations', []);
  const classes = examGetClassOptions();

  const body = `
    <div class="exam-modal-grid-2" style="margin-bottom:16px">
      <div class="exam-form-group">
        <label class="exam-label">Academic Year</label>
        <select id="pcYear" class="exam-select" onchange="examPopulateCompareExams()">
          <option value="">— Select —</option>
          ${examRetrieve('academicYears', []).map(y => `<option value="${y.id}">${examSanitize(y.name)}</option>`).join('')}
        </select>
      </div>
      <div class="exam-form-group">
        <label class="exam-label">Class</label>
        <select id="pcClass" class="exam-select" onchange="examRenderProgressComparison()">
          <option value="">— Select —</option>
          ${classes.map(c => `<option value="${c}">${examSanitize(c)}</option>`).join('')}
        </select>
      </div>
    </div>
    <div class="exam-form-group" style="margin-bottom:16px">
      <label class="exam-label">Select Exams to Compare (hold Ctrl/Cmd for multiple)</label>
      <select id="pcExams" class="exam-select" multiple size="5" onchange="examRenderProgressComparison()" style="height:110px"></select>
    </div>
    <div style="position:relative;height:300px"><canvas id="chartProgressComp"></canvas></div>
    <div id="pcStatsTable" style="margin-top:16px"></div>`;

  const footer = `
    <button class="exam-btn exam-btn-ghost" onclick="examCloseModal()">Close</button>
    <button class="exam-btn exam-btn-primary" onclick="examExportProgressComparisonCSV()">↓ Export CSV</button>`;

  examOpenModal('Multi-Exam Progress Comparison', body, footer, true);
}

/**
 * examPopulateCompareExams()
 * Fills the exam multi-select based on chosen academic year.
 */
function examPopulateCompareExams() {
  const yearId = document.getElementById('pcYear')?.value;
  const exams  = examRetrieve('examinations', []).filter(e => !yearId || e.yearId === yearId);
  const sel    = document.getElementById('pcExams');
  if (!sel) return;
  sel.innerHTML = exams.map(e => `<option value="${e.id}">${examSanitize(e.name)}</option>`).join('');
}

/**
 * examRenderProgressComparison()
 * Renders the comparison chart for selected exams and class.
 */
function examRenderProgressComparison() {
  const className = document.getElementById('pcClass')?.value;
  const examSel   = document.getElementById('pcExams');
  if (!examSel) return;

  const selectedIds = Array.from(examSel.selectedOptions).map(o => o.value);
  if (!className || !selectedIds.length) return;

  const exams   = examRetrieve('examinations', []);
  const results = examRetrieve('results', {});

  // Build datasets: one line per subject, X axis = exam name
  const examLabels = selectedIds.map(id => {
    const ex = exams.find(e => e.id === id);
    return ex ? (ex.name.length > 20 ? ex.name.slice(0, 20) + '…' : ex.name) : id;
  });

  // Collect all subjects across selected exams for this class
  const subjectSet = new Set();
  selectedIds.forEach(examId => {
    const maps = examRetrieve('subjectMap', []).filter(m => m.examId === examId && m.className === className);
    maps.forEach(m => subjectSet.add(m.subjectName));
  });

  const subjectColors = [
    '#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6',
    '#ec4899','#06b6d4','#84cc16','#f97316','#6366f1'
  ];

  const datasets = [];
  let colorIdx = 0;

  // Class average line (overall)
  const classAvgData = selectedIds.map(examId => {
    const classResults = results[examId]?.[className] || {};
    const pcts = Object.values(classResults).filter(s => s.result !== 'Absent' && typeof s.pct === 'number').map(s => s.pct);
    return pcts.length ? examRound(pcts.reduce((a, b) => a + b, 0) / pcts.length) : null;
  });

  datasets.push({
    label: 'Class Average',
    data: classAvgData,
    borderColor: '#1e3a5f',
    backgroundColor: 'rgba(30,58,95,0.08)',
    borderWidth: 3,
    borderDash: [6, 3],
    pointRadius: 5,
    tension: 0.3,
    fill: false,
  });

  // Subject-wise average lines
  subjectSet.forEach(subj => {
    const data = selectedIds.map(examId => {
      const maps = examRetrieve('subjectMap', []).filter(m => m.examId === examId && m.className === className && m.subjectName === subj);
      if (!maps.length) return null;
      const sm = maps[0];
      const marksKey = `marks_${examId}_${className}_${sm.division}_${sm.id}`;
      const marks = Object.values(examRetrieve(marksKey, {})).filter(m => !m.absent && typeof m.pct === 'number');
      return marks.length ? examRound(marks.reduce((a, m) => a + m.pct, 0) / marks.length) : null;
    });

    datasets.push({
      label: subj,
      data,
      borderColor: subjectColors[colorIdx % subjectColors.length],
      backgroundColor: 'transparent',
      borderWidth: 2,
      pointRadius: 4,
      tension: 0.3,
      fill: false,
    });
    colorIdx++;
  });

  const ctx = document.getElementById('chartProgressComp');
  if (!ctx) return;
  if (examChartProgressComparison) examChartProgressComparison.destroy();

  examChartProgressComparison = new Chart(ctx, {
    type: 'line',
    data: { labels: examLabels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { boxWidth: 12, font: { size: 11 } } },
        tooltip: { callbacks: { label: ctx => `${ctx.dataset.label}: ${ctx.parsed.y}%` } }
      },
      scales: {
        y: { beginAtZero: false, min: 0, max: 100, ticks: { callback: v => v + '%' },
          grid: { color: 'rgba(0,0,0,0.05)' } },
        x: { grid: { display: false } }
      }
    }
  });

  // Stats summary table
  const statsEl = document.getElementById('pcStatsTable');
  if (statsEl) {
    const rows = selectedIds.map((examId, i) => {
      const classResults = results[examId]?.[className] || {};
      const vals = Object.values(classResults);
      const passed  = vals.filter(s => s.result === 'Pass').length;
      const failed  = vals.filter(s => s.result === 'Fail').length;
      const absent  = vals.filter(s => s.result === 'Absent').length;
      const pcts    = vals.filter(s => s.result !== 'Absent' && typeof s.pct === 'number').map(s => s.pct);
      const avg     = pcts.length ? examRound(pcts.reduce((a,b) => a+b, 0) / pcts.length) : '—';
      const passPct = (passed + failed) > 0 ? examRound((passed / (passed + failed)) * 100) : '—';
      return `<tr>
        <td><strong>${examSanitize(examLabels[i])}</strong></td>
        <td>${vals.length}</td>
        <td style="color:var(--exam-green)">${passed}</td>
        <td style="color:var(--exam-red)">${failed}</td>
        <td style="color:var(--exam-orange)">${absent}</td>
        <td>${avg}${avg !== '—' ? '%' : ''}</td>
        <td>${passPct}${passPct !== '—' ? '%' : ''}</td>
      </tr>`;
    }).join('');

    statsEl.innerHTML = `
      <div class="exam-table-wrap" style="border:1px solid var(--exam-border);border-radius:var(--exam-radius-sm);overflow:hidden">
        <table class="exam-table" style="min-width:500px">
          <thead><tr><th>Examination</th><th>Total</th><th>Pass</th><th>Fail</th><th>Absent</th><th>Avg%</th><th>Pass%</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>`;
  }
}

/**
 * examExportProgressComparisonCSV()
 */
function examExportProgressComparisonCSV() {
  const className = document.getElementById('pcClass')?.value;
  const examSel   = document.getElementById('pcExams');
  if (!examSel || !className) { examShowToast('Select class and exams first', 'warning'); return; }

  const selectedIds = Array.from(examSel.selectedOptions).map(o => o.value);
  const exams   = examRetrieve('examinations', []);
  const results = examRetrieve('results', {});

  const rows = [['Examination','Total Students','Passed','Failed','Absent','Avg %','Pass %']];
  selectedIds.forEach(examId => {
    const ex = exams.find(e => e.id === examId);
    const classResults = results[examId]?.[className] || {};
    const vals = Object.values(classResults);
    const passed  = vals.filter(s => s.result === 'Pass').length;
    const failed  = vals.filter(s => s.result === 'Fail').length;
    const absent  = vals.filter(s => s.result === 'Absent').length;
    const pcts    = vals.filter(s => s.result !== 'Absent' && typeof s.pct === 'number').map(s => s.pct);
    const avg     = pcts.length ? examRound(pcts.reduce((a,b)=>a+b,0)/pcts.length) : '';
    const passPct = (passed+failed) > 0 ? examRound((passed/(passed+failed))*100) : '';
    rows.push([ex?.name || examId, vals.length, passed, failed, absent, avg, passPct]);
  });
  examCSVDownload(`progress_comparison_class${className}.csv`, rows);
  examShowToast('CSV exported', 'info');
}

/**
 * Injects "Progress Comparison" button into Analysis section header.
 */
function examInjectComparisonButton() {
  const actionBar = document.querySelector('#examAnalysis .exam-section-actions');
  if (!actionBar || actionBar.querySelector('.comp-btn')) return;
  const btn = document.createElement('button');
  btn.className = 'exam-btn exam-btn-ghost comp-btn';
  btn.textContent = '📈 Compare Exams';
  btn.onclick = examOpenProgressComparisonModal;
  actionBar.appendChild(btn);
}

/* ═══════════════════════════════════════════════
   SECTION Y — ATTENDANCE % IN RESULT
   Adds attendance column to class result sheet.
   Counts how many subjects a student was present
   for and shows percentage.
═══════════════════════════════════════════════ */

/**
 * examGetStudentAttendancePct(studentId, examId, className, maps)
 * Returns { present, total, pct } for a student across all subjects.
 */
function examGetStudentAttendancePct(studentId, examId, className, maps) {
  // [PHASE-24] Logic moved to Dnyanankur.Services.Exam.examGetStudentAttendancePct(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Exam) {
    return Dnyanankur.Services.Exam.examGetStudentAttendancePct(studentId, examId, className, maps);
  }
  let present = 0, total = 0;
  maps.forEach(sm => {
    const marksKey = `marks_${examId}_${className}_${sm.division}_${sm.id}`;
    const m = examRetrieve(marksKey, {})[studentId];
    if (!m) return;
    total++;
    if (!m.absent) present++;
  });
  const pct = total > 0 ? examRound((present / total) * 100) : 0;
  return { present, total, pct };
}

/* ═══════════════════════════════════════════════
   SECTION Z — MODULE BACKUP EXPORT / IMPORT
   Exports all examMod_* keys to a single JSON
   file. Imports restore them, with a confirmation
   to prevent accidental overwrite.
═══════════════════════════════════════════════ */

/**
 * examExportFullBackup()
 * Downloads all examMod_* localStorage keys as a JSON backup file.
 */
function examExportFullBackup() {
  const backup = { _meta: { version: '1.0', exportedAt: new Date().toISOString(), module: 'ExamModule' } };
  const prefix = 'examMod_';

  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && key.startsWith(prefix)) {
      try { backup[key] = JSON.parse(localStorage.getItem(key)); }
      catch (e) { backup[key] = localStorage.getItem(key); }
    }
  }

  const json    = JSON.stringify(backup, null, 2);
  const blob    = new Blob([json], { type: 'application/json' });
  const url     = URL.createObjectURL(blob);
  const a       = document.createElement('a');
  const ts      = new Date().toISOString().slice(0, 10);
  a.href        = url;
  a.download    = `exam_module_backup_${ts}.json`;
  a.click();
  URL.revokeObjectURL(url);
  examShowToast('Full backup exported successfully', 'success');
}

/**
 * examImportFullBackup()
 * Opens a file picker and restores all examMod_* keys from JSON backup.
 * Prompts user to confirm before overwriting.
 */
function examImportFullBackup() {
  const input  = document.createElement('input');
  input.type   = 'file';
  input.accept = '.json';
  input.onchange = async (evt) => {
    const file = evt.target.files[0];
    if (!file) return;

    try {
      const text   = await file.text();
      const backup = JSON.parse(text);

      if (!backup._meta || backup._meta.module !== 'ExamModule') {
        examShowToast('Invalid backup file — not an ExamModule backup', 'danger'); return;
      }

      const keyCount = Object.keys(backup).filter(k => k.startsWith('examMod_')).length;
      if (!confirm(`This will restore ${keyCount} data sets from backup dated ${backup._meta.exportedAt}.\n\nAll current examination data will be overwritten.\n\nProceed?`)) return;

      let restored = 0;
      Object.keys(backup).forEach(key => {
        if (!key.startsWith('examMod_')) return;
        try {
          localStorage.setItem(key, JSON.stringify(backup[key]));
          restored++;
        } catch (e) {
          examLog(`Failed to restore key: ${key}`, 'error');
        }
      });

      examShowToast(`Backup restored: ${restored} data sets`, 'success');
      examLog(`Backup imported: ${restored} keys restored from ${file.name}`, 'success');

      // Re-initialise module
      setTimeout(() => {
        examModuleInit();
        examSectionActivated('examMaster');
      }, 300);
    } catch (e) {
      examShowToast('Failed to parse backup file: ' + e.message, 'danger');
    }
  };
  input.click();
}

/**
 * examClearAllModuleData()
 * Deletes every examMod_* key from localStorage.
 * Asks for typed confirmation.
 */
function examClearAllModuleData() {
  const answer = prompt('Type CONFIRM to erase all examination module data. This cannot be undone.');
  if (answer !== 'CONFIRM') { examShowToast('Cancelled — no data was deleted', 'info'); return; }

  const prefix = 'examMod_';
  const toDelete = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && key.startsWith(prefix)) toDelete.push(key);
  }
  toDelete.forEach(k => localStorage.removeItem(k));
  examShowToast(`Cleared ${toDelete.length} exam data records`, 'danger');
  examLog(`All module data cleared: ${toDelete.length} keys removed`, 'warning');
  setTimeout(examModuleInit, 300);
}

/**
 * Injects Backup / Import / Clear buttons into Exam Master section header.
 */
function examInjectBackupButtons() {
  const actionBar = document.querySelector('#examMaster .exam-section-actions');
  if (!actionBar || actionBar.querySelector('.backup-btn')) return;

  const group = document.createElement('div');
  group.className = 'exam-row-gap-8';
  group.innerHTML = `
    <button class="exam-btn exam-btn-ghost backup-btn" onclick="examExportFullBackup()" title="Export full module backup">
      ⬇ Backup
    </button>
    <button class="exam-btn exam-btn-ghost" onclick="examImportFullBackup()" title="Restore from backup file">
      ⬆ Restore
    </button>
    <button class="exam-btn exam-btn-ghost" onclick="examClearAllModuleData()" style="color:var(--exam-red)" title="Clear all exam data">
      🗑 Clear All
    </button>`;
  actionBar.appendChild(group);
}

/* ═══════════════════════════════════════════════
   SECTION AA — DEMO / TEST DATA SEEDER
   Seeds realistic test data so the module can
   be demonstrated without the main ERP's
   student/teacher data. Adds 30 students across
   2 classes, 5 subjects, 2 exams, marks, and
   computed results.
═══════════════════════════════════════════════ */

/**
 * examSeedDemoData()
 * Populates localStorage with a complete working dataset.
 * Safe: checks for existing data and confirms before overwriting.
 */
function examSeedDemoData() {
  const existingExams = examRetrieve('examinations', []);
  if (existingExams.length > 0) {
    if (!confirm(`Demo seed will add to existing data (${existingExams.length} exams already exist).\n\nProceed?`)) return;
  }

  examLog('Starting demo data seed…', 'info');

  // ── Academic Year ──────────────────────────────
  const yearId = 'demo_year_2425';
  const years  = examRetrieve('academicYears', []);
  if (!years.find(y => y.id === yearId)) {
    years.push({ id: yearId, name: '2024-25', status: 'active', startDate: '2024-06-01', endDate: '2025-03-31', createdAt: new Date().toISOString() });
    examStore('academicYears', years);
  }

  // ── Terms ─────────────────────────────────────
  const term1Id = 'demo_term_1', term2Id = 'demo_term_2';
  const terms   = examRetrieve('terms', []);
  if (!terms.find(t => t.id === term1Id)) {
    terms.push({ id: term1Id, name: 'Term 1', type: 'term', startDate: '2024-06-01', endDate: '2024-09-30', order: 1 });
    terms.push({ id: term2Id, name: 'Term 2', type: 'term', startDate: '2024-10-01', endDate: '2025-03-31', order: 2 });
    examStore('terms', terms);
  }

  // ── Exam Types ─────────────────────────────────
  examInitExamTypes();

  // ── Grade Scale ────────────────────────────────
  examInitGradeScales();

  // ── Two Examinations ───────────────────────────
  const exam1Id = 'demo_exam_ut1', exam2Id = 'demo_exam_sa1';
  const exams   = examRetrieve('examinations', []);
  if (!exams.find(e => e.id === exam1Id)) {
    exams.push({
      id: exam1Id, name: 'Unit Test 1', typeId: 'et_ut', typeName: 'Unit Test',
      yearId, yearName: '2024-25', termId: term1Id, termName: 'Term 1',
      rcSlot: 'FA1',
      applicableClass: 'all', startDate: '2024-07-15', endDate: '2024-07-20',
      theoryMax: 25, practMax: 0, intMax: 0, passPct: 35, graceLimitMarks: 3,
      status: 'active', isLocked: false, isPublished: false, gradeScaleId: 'gs_default',
      createdAt: new Date().toISOString()
    });
    exams.push({
      id: exam2Id, name: 'Semester Exam I', typeId: 'et_sa1', typeName: 'Semester Exam I',
      yearId, yearName: '2024-25', termId: term1Id, termName: 'Term 1',
      rcSlot: 'SA1',
      applicableClass: 'all', startDate: '2024-09-10', endDate: '2024-09-20',
      theoryMax: 80, practMax: 20, intMax: 20, passPct: 35, graceLimitMarks: 5,
      status: 'active', isLocked: false, isPublished: false, gradeScaleId: 'gs_default',
      createdAt: new Date().toISOString()
    });
    examStore('examinations', exams);
  }

  // ── Subjects for Class 9th and 10th (ERP class naming) ─
  const subjectDefs = [
    { name: 'Mathematics',    code: 'MATH',  theoryMax: 80, practMax: 20, intMax: 20 },
    { name: 'Science',        code: 'SCI',   theoryMax: 80, practMax: 20, intMax: 20 },
    { name: 'English',        code: 'ENG',   theoryMax: 80, practMax: 0,  intMax: 20 },
    { name: 'Social Studies', code: 'SOC',   theoryMax: 80, practMax: 0,  intMax: 20 },
    { name: 'Hindi',          code: 'HIN',   theoryMax: 80, practMax: 0,  intMax: 20 },
  ];

  const maps = examRetrieve('subjectMap', []);
  const classes = ['9th', '10th']; // ERP-correct class identifiers

  classes.forEach(cls => {
    [exam1Id, exam2Id].forEach(examId => {
      const exam = exams.find(e => e.id === examId) || {};
      subjectDefs.forEach(sd => {
        const mapId = `demo_map_${examId}_${cls}_${sd.code}`;
        if (maps.find(m => m.id === mapId)) return;
        const theoryMax = examId === exam1Id ? 25 : sd.theoryMax;
        const practMax  = examId === exam1Id ? 0  : sd.practMax;
        const intMax    = examId === exam1Id ? 0  : sd.intMax;
        maps.push({
          id: mapId, examId, examName: exam.name || '', className: cls,
          division: 'All', subjectName: sd.name, subjectCode: sd.code,
          teacher: 'Demo Teacher', theoryMax, practMax, intMax,
          passPct: 35, hasGrace: 'yes', isOptional: false,
        });
      });
    });
  });
  examStore('subjectMap', maps);

  // ── Seed Students into ERP's "students" store ──
  // ERP INTEGRATION: uses getStudents()/saveStudents() (respects the
  // ERP's in-memory Cache) and real field names: cls, div, name, admno.
  const existingStudents = (typeof getStudents === 'function')
    ? getStudents().slice()
    : (() => { try { return JSON.parse(localStorage.getItem('students') || '[]'); } catch(e) { return []; } })();
  const demoNames = [
    'Arjun Sharma','Priya Patil','Rahul Desai','Sneha Kulkarni','Vikram Mehta',
    'Neha Joshi','Amit Sawant','Pooja Naik','Suresh Pawar','Kavya Rao',
    'Rohan Malhotra','Ananya Singh','Kunal Gupta','Riya Bhosale','Siddharth Nair',
    'Tanvi Chavan','Akash Reddy','Meera Iyer','Pranav Shinde','Aishwarya More',
    'Dhruv Patel','Sakshi Gaikwad','Yash Kadam','Shreya Bapat','Nikhil Jadhav',
    'Komal Wagh','Abhishek Thakur','Devika Shirke','Manish Deshpande','Pallavi Kale',
  ];

  let admCounter = 1001;
  ['9th','10th'].forEach(cls => {
    for (let i = 0; i < 15; i++) {
      const name = demoNames[(cls === '9th' ? 0 : 15) + i] || `Student ${i+1}`;
      const id    = `demo_std_${cls}_${i}`;
      if (!existingStudents.find(s => s.id === id)) {
        existingStudents.push({
          id, admno: String(admCounter++),
          name, cls: cls, div: 'A',
          admdate: '2024-06-15',
        });
      }
    }
  });
  if (typeof saveStudents === 'function') {
    saveStudents(existingStudents);
  } else {
    localStorage.setItem('students', JSON.stringify(existingStudents));
  }

  // ── Seed Marks for Unit Test 1 ─────────────────
  classes.forEach(cls => {
    const students = existingStudents.filter(s => s.cls === cls);
    subjectDefs.forEach(sd => {
      const mapId   = `demo_map_${exam1Id}_${cls}_${sd.code}`;
      const marksKey = `marks_${exam1Id}_${cls}_All_${mapId}`;
      const saved    = examRetrieve(marksKey, {});
      students.forEach(student => {
        if (saved[student.id]) return;
        const isAbsent = Math.random() < 0.05;
        const theory   = isAbsent ? 0 : Math.floor(Math.random() * 16) + 8; // 8–23 / 25
        const grace    = (!isAbsent && theory >= 7 && theory < 9) ? 2 : 0;
        const total    = isAbsent ? 0 : theory + grace;
        const pct      = isAbsent ? 0 : examRound((total / 25) * 100);
        const result   = isAbsent ? 'Absent' : pct >= 35 ? 'Pass' : 'Fail';
        const grade    = isAbsent ? 'AB' : examCalcGrade(pct, 'gs_default');
        saved[student.id] = {
          studentId: student.id, name: student.name, admissionNo: student.admno,
          theory, pract: 0, internal: 0, grace, total, pct, grade, result,
          absent: isAbsent, savedAt: new Date().toISOString()
        };
      });
      examStore(marksKey, saved);
    });
  });

  // ── Seed Marks for Semester Exam I ────────────
  classes.forEach(cls => {
    const students = existingStudents.filter(s => s.cls === cls);
    subjectDefs.forEach(sd => {
      const mapId    = `demo_map_${exam2Id}_${cls}_${sd.code}`;
      const marksKey = `marks_${exam2Id}_${cls}_All_${mapId}`;
      const saved    = examRetrieve(marksKey, {});
      students.forEach(student => {
        if (saved[student.id]) return;
        const isAbsent  = Math.random() < 0.04;
        const theory    = isAbsent ? 0 : Math.floor(Math.random() * 50) + 28;   // 28–77/80
        const pract     = sd.practMax ? (isAbsent ? 0 : Math.floor(Math.random() * 10) + 10) : 0; // 10–19/20
        const internal  = sd.intMax   ? (isAbsent ? 0 : Math.floor(Math.random() * 8)  + 12) : 0; // 12–19/20
        const grace     = (!isAbsent && theory + pract + internal < (sd.theoryMax + sd.practMax + sd.intMax) * 0.35 + 5) ? 3 : 0;
        const total     = isAbsent ? 0 : theory + pract + internal + grace;
        const maxT      = sd.theoryMax + sd.practMax + sd.intMax;
        const pct       = isAbsent || maxT === 0 ? 0 : examRound((total / maxT) * 100);
        const theoryPass = sd.theoryMax ? theory >= (sd.theoryMax * 0.35) : true;
        const result    = isAbsent ? 'Absent' : (pct >= 35 && theoryPass) ? 'Pass' : 'Fail';
        const grade     = isAbsent ? 'AB' : examCalcGrade(pct, 'gs_default');
        saved[student.id] = {
          studentId: student.id, name: student.name, admissionNo: student.admno,
          theory, pract, internal, grace, total, pct, grade, result,
          absent: isAbsent, savedAt: new Date().toISOString()
        };
      });
      examStore(marksKey, saved);
    });
  });

  // ── Compute and store results for both exams ───
  [exam1Id, exam2Id].forEach(examId => {
    const results = examRetrieve('results', {});
    results[examId] = results[examId] || {};

    classes.forEach(cls => {
      const classMaps  = examRetrieve('subjectMap', []).filter(m => m.examId === examId && m.className === cls);
      const students   = existingStudents.filter(s => s.cls === cls);
      results[examId][cls] = results[examId][cls] || {};

      students.forEach(student => {
        let totalMarks = 0, maxTotal = 0, failAny = false, absentAny = false;
        const subjectResults = {};

        classMaps.forEach(sm => {
          const marksKey = `marks_${examId}_${cls}_${sm.division}_${sm.id}`;
          const m = examRetrieve(marksKey, {})[student.id];
          if (!m) return;
          subjectResults[sm.subjectName] = m;
          if (m.absent) absentAny = true;
          else { totalMarks += m.total || 0; maxTotal += (sm.theoryMax + sm.practMax + sm.intMax); if (m.result === 'Fail') failAny = true; }
        });

        const pct = maxTotal > 0 ? examRound((totalMarks / maxTotal) * 100) : 0;
        const result = absentAny ? 'Absent' : failAny ? 'Fail' : 'Pass';
        const grade  = result === 'Absent' ? 'AB' : examCalcGrade(pct, 'gs_default');
        const points = result === 'Absent' ? 0 : examCalcGradePoints(pct, '');

        results[examId][cls][student.id] = {
          studentId: student.id, name: student.name, admissionNo: student.admno,
          className: cls, division: 'All', totalMarks: examRound(totalMarks), maxTotal,
          pct, grade, points, result, subjectResults, computedAt: new Date().toISOString()
        };
      });

      // Assign class ranks
      const classData = Object.values(results[examId][cls]);
      classData.sort((a, b) => b.pct - a.pct);
      classData.forEach((s, i) => { s.classRank = s.result === 'Absent' ? 999 : i + 1; });
    });

    // School rank
    const allData = [];
    classes.forEach(cls => Object.values(results[examId][cls] || {}).forEach(s => allData.push(s)));
    allData.sort((a, b) => b.pct - a.pct);
    allData.forEach((s, i) => { s.schoolRank = s.result === 'Absent' ? 999 : i + 1; });
    examStore('results', results);
  });

  // ── Timetable ──────────────────────────────────
  const slots = examRetrieve('timetable', []);
  if (!slots.find(s => s.examId === exam2Id)) {
    const days = ['Monday','Tuesday','Wednesday','Thursday','Friday'];
    const dates = ['2024-09-10','2024-09-11','2024-09-12','2024-09-13','2024-09-14'];
    subjectDefs.forEach((sd, i) => {
      classes.forEach(cls => {
        slots.push({
          id: examUID(), examId: exam2Id, date: dates[i], day: days[i],
          startTime: '09:00', endTime: '12:00', className: cls,
          subjectName: sd.name, room: `Hall ${i + 1}`, invigilator: 'Demo Teacher'
        });
      });
    });
    examStore('timetable', slots);
  }

  // ── Refresh all UI ────────────────────────────
  examPopulateContextSelects();
  examRenderAcademicYearList();
  examRenderTermList();
  examRenderExamTypeList();
  examRenderMasterTable();

  examLog('Demo data seeded: 2 exams, 2 classes, 30 students, 5 subjects, marks + results computed.', 'success');
  examShowToast('Demo data loaded! Explore all sections now.', 'success');
}

/**
 * Injects the Seed Demo Data button into the Master section header.
 */
function examInjectSeedButton() {
  const actionBar = document.querySelector('#examMaster .exam-section-actions');
  if (!actionBar || actionBar.querySelector('.seed-btn')) return;
  const btn = document.createElement('button');
  btn.className = 'exam-btn exam-btn-ghost seed-btn';
  btn.innerHTML = '🌱 Seed Demo Data';
  btn.title = 'Load test data to explore the module';
  btn.onclick = examSeedDemoData;
  // Insert at beginning
  actionBar.insertBefore(btn, actionBar.firstChild);
}

