/* ══════════════════════════════════════════════════════════════════════
   CM-1.0 — COMMUNICATION ENGINE INTEGRATION
   ------------------------------------------------------------------
   The Communication Module above (Store / LSKEY / templates / history /
   WA Centre / audit / settings) is NOT rebuilt. This block only adds the
   missing piece: a central Queue that every other ERP module drops
   notifications into, plus the Principal Approval → Send → History →
   Parent Portal pipeline described in the CM-1.0 brief.

   Flow:  Module event → CommEngine.notify() → Communication Queue
          (Draft/Waiting Approval) → Principal approves/rejects →
          Approved → routed to Portal (always) + WhatsApp/SMS/Email
          queues (unless paused) → Sent → visible in Communication
          History / Parent Portal.

   No WhatsApp/SMS/Email API, no Twilio, no Meta API, no HTTP requests
   are used anywhere below — channel queues only ever reach "Ready" and
   stop there until a future sprint wires a real gateway.
   ══════════════════════════════════════════════════════════════════════ */

const CM_LSKEY = {
  QUEUE:        'dnk_cm_queue',        // the Communication Queue itself
  WA_QUEUE:     'dnk_cm_wa_queue',     // WhatsApp send queue (prep only)
  SMS_QUEUE:    'dnk_cm_sms_queue',    // SMS send queue (prep only)
  EMAIL_QUEUE:  'dnk_cm_email_queue',  // Email send queue (prep only)
};

/* Event-type → presentation mapping. `smsType`/`waCategory` point at the
   *existing* template.type / template.category values already seeded in
   Store.setTemplates()/Store.setWATemplates() above, so CommEngine reuses
   the real template library instead of inventing new copy. */
const CM_EVENT_MAP = {
  // ── Attendance ──
  'attendance.student.absent':      { module:'Attendance',   title:'Absent Student',    smsType:'Attendance',     waCategory:'Attendance',   priority:'High'   },
  'attendance.student.late':        { module:'Attendance',   title:'Late Student',      smsType:'Attendance',     waCategory:'Attendance',   priority:'Medium' },
  'attendance.student.halfday':     { module:'Attendance',   title:'Half Day',          smsType:'Attendance',     waCategory:'Attendance',   priority:'Medium' },
  'attendance.leave.approved':      { module:'Attendance',   title:'Leave Approved',    smsType:'General Notice', waCategory:'Attendance',   priority:'Low'    },
  // ── Finance ──
  'finance.fee.reminder':           { module:'Finance',      title:'Fee Reminder',      smsType:'Fee Reminder',   waCategory:'Fee Reminder', priority:'Medium' },
  'finance.fee.due':                { module:'Finance',      title:'Fee Due',           smsType:'Fee Reminder',   waCategory:'Fee Reminder', priority:'Medium' },
  'finance.fee.overdue':            { module:'Finance',      title:'Fee Overdue',       smsType:'Fee Reminder',   waCategory:'Fee Reminder', priority:'High'   },
  'finance.receipt.generated':      { module:'Finance',      title:'Receipt Generated', smsType:'Fee Received',   waCategory:'Fee Receipt',  priority:'Low'    },
  'finance.refund.processed':       { module:'Finance',      title:'Refund',            smsType:'Fee Received',   waCategory:'Fee Receipt',  priority:'Medium' },
  'finance.scholarship.granted':    { module:'Finance',      title:'Scholarship',       smsType:'General Notice', waCategory:'Fee Reminder', priority:'Medium' },
  'finance.concession.applied':     { module:'Finance',      title:'Concession',        smsType:'General Notice', waCategory:'Fee Reminder', priority:'Medium' },
  // ── Examination ──
  'exam.result.published':          { module:'Examination',  title:'Result Published',    smsType:'Result',        waCategory:'Result',       priority:'High'   },
  'exam.reportcard.published':      { module:'Examination',  title:'Report Card Published',smsType:'Result',        waCategory:'Report Card',  priority:'High'   },
  'exam.schedule.published':        { module:'Examination',  title:'Exam Schedule',       smsType:'Examination',   waCategory:'Exam Notice',  priority:'Medium' },
  'exam.reminder':                  { module:'Examination',  title:'Exam Reminder',       smsType:'Examination',   waCategory:'Exam Notice',  priority:'Medium' },
  'exam.hallticket.ready':          { module:'Examination',  title:'Hall Ticket Ready',   smsType:'Examination',   waCategory:'Hall Ticket',  priority:'High'   },
  'exam.promotion.completed':       { module:'Examination',  title:'Promotion Completed', smsType:'Result',        waCategory:'Result',       priority:'Medium' },
  // ── Inventory ──
  'inventory.book.distributed':     { module:'Inventory',    title:'Book Distribution',  smsType:'General Notice', waCategory:'Fee Receipt',  priority:'Low'    },
  'inventory.uniform.ready':        { module:'Inventory',    title:'Uniform Ready',      smsType:'General Notice', waCategory:'Fee Receipt',  priority:'Low'    },
  'inventory.stock.notice':         { module:'Inventory',    title:'Stock Notice',       smsType:'General Notice', waCategory:'Fee Receipt',  priority:'Low'    },
  // ── Transport ──
  'transport.bus.delay':            { module:'Transport',    title:'Bus Delay',          smsType:'Transport',      waCategory:'Transport',    priority:'High'   },
  'transport.route.changed':        { module:'Transport',    title:'Route Changed',      smsType:'Transport',      waCategory:'Transport',    priority:'Medium' },
  'transport.vehicle.changed':      { module:'Transport',    title:'Vehicle Changed',     smsType:'Transport',      waCategory:'Transport',    priority:'Medium' },
  // ── Student ──
  'student.admission.approved':     { module:'Student',      title:'Admission Approved', smsType:'Admission',      waCategory:'Admission',    priority:'High'   },
  'student.admission.pending':      { module:'Student',      title:'Admission Pending',  smsType:'Admission',      waCategory:'Admission',    priority:'Medium' },
  'student.tc.issued':              { module:'Student',      title:'Transfer Certificate',smsType:'General Notice',waCategory:'Admission',    priority:'Medium' },
  'student.updated':                { module:'Student',      title:'Student Updated',    smsType:'General Notice', waCategory:'Admission',    priority:'Low'    },
};

const CmQueueStore = {
  get(){ return Store.get(CM_LSKEY.QUEUE); },
  set(v){ Store.set(CM_LSKEY.QUEUE, v); },
  getById(id){ return CmQueueStore.get().find(r=>r.id===id) || null; },
  upsert(rec){
    const q = CmQueueStore.get();
    const i = q.findIndex(r=>r.id===rec.id);
    if(i>=0) q[i]=rec; else q.unshift(rec);
    CmQueueStore.set(q);
    return rec;
  },
  getWA(){ return Store.get(CM_LSKEY.WA_QUEUE); },
  setWA(v){ Store.set(CM_LSKEY.WA_QUEUE, v); },
  getSMS(){ return Store.get(CM_LSKEY.SMS_QUEUE); },
  setSMS(v){ Store.set(CM_LSKEY.SMS_QUEUE, v); },
  getEmail(){ return Store.get(CM_LSKEY.EMAIL_QUEUE); },
  setEmail(v){ Store.set(CM_LSKEY.EMAIL_QUEUE, v); },
};

function cmChannelSettings(){
  const s = Store.getSettings();
  return {
    portal:   true,               // Portal can NEVER be disabled or paused
    whatsapp: !!s.enableWA   && !s.pauseWhatsApp,
    sms:      !!s.enableSMS  && !s.pauseSMS,
    email:    !!s.enableEmail && !s.pauseEmail,
    waDisabled:    !s.enableWA,
    smsDisabled:   !s.enableSMS,
    emailDisabled: !s.enableEmail,
    waPaused:      !!s.pauseWhatsApp,
    smsPaused:     !!s.pauseSMS,
    emailPaused:   !!s.pauseEmail
  };
}

/** Renders an event payload + the matching template into a human message.
 *  Falls back to a plain sentence if no template body / student match
 *  is found — the queue entry is never left blank. */
function cmRenderMessage(map, payload){
  const student = payload && payload.studentName ? payload : {};
  const smsTemplate = Store.getTemplates().find(t=>t.type===map.smsType);
  let body = smsTemplate ? smsTemplate.body : (map.title + ' — ' + (payload.detail || ''));
  const vars = {
    '{StudentName}': payload.studentName || '', '{Class}': payload.className || '',
    '{Amount}': payload.amount != null ? payload.amount : '', '{ReceiptNo}': payload.receiptNo || '',
    '{ExamName}': payload.examName || '', '{Result}': payload.result || '',
    '{SchoolName}': Store.getSettings().schoolName || 'the School'
  };
  Object.keys(vars).forEach(k=>{ body = body.split(k).join(String(vars[k])); });
  return body;
}

/** Single public entry point every module hook calls. Never sends
 *  anything directly — always lands in the Communication Queue first. */
function cmNotify(eventType, payload){
  payload = payload || {};
  const map = CM_EVENT_MAP[eventType];
  if(!map){ Dnyanankur.Logger && Dnyanankur.Logger.warn && Dnyanankur.Logger.warn('[CommEngine] Unknown eventType: '+eventType); return null; }

  const message = cmRenderMessage(map, payload);
  const emergency = !!payload.emergency;
  const rec = {
    id: 'CQ'+commUid(),
    studentId: payload.studentId || null,
    parentId: payload.parentId || payload.studentId || null,
    type: map.title,
    module: map.module,
    title: map.title + (payload.studentName ? ' — ' + payload.studentName : ''),
    message: message,
    priority: payload.priority || map.priority,
    createdOn: commNowISO(),
    status: emergency ? 'Approved' : 'Waiting Approval',
    approvedBy: emergency ? 'System (Emergency bypass)' : null,
    approvedOn: emergency ? commNowISO() : null,
    sendChannel: payload.channels || ['Parent Portal','WhatsApp','SMS','Email'],
    scheduledOn: payload.scheduledOn || null,
    sourceEvent: eventType,
    emergency: emergency,
    className: payload.className || null
  };
  CmQueueStore.upsert(rec);
  logAudit(emergency ? 'Emergency Auto-Approved' : 'Queued (Draft)', map.module+' → '+rec.title+' for '+(payload.studentName||'—'));
  if(emergency) cmRouteApproved(rec.id);
  if(typeof refreshCMQueueBadge==='function') refreshCMQueueBadge();
  return rec;
}

/** Pushes an Approved record's non-portal channels into their queue
 *  tables (skipping any channel that is disabled or paused — those
 *  channels' messages simply remain "Approved", never "Sent", per the
 *  Manual Pause rule). Portal never needs a queue table: it is read
 *  directly out of the Communication Queue by getCommunicationHistory(). */
function cmRouteApproved(id){
  const rec = CmQueueStore.getById(id);
  if(!rec || rec.status!=='Approved') return;
  const ch = cmChannelSettings();
  const wants = (name)=> rec.sendChannel.includes(name);

  if(wants('WhatsApp') && ch.whatsapp){
    const q = CmQueueStore.getWA();
    q.unshift({ id:'WAQ'+commUid(), queueId:rec.id, studentId:rec.studentId, title:rec.title, message:rec.message, status:'Ready', createdOn: commNowISO() });
    CmQueueStore.setWA(q);
  }
  if(wants('SMS') && ch.sms){
    const q = CmQueueStore.getSMS();
    q.unshift({ id:'SMQ'+commUid(), queueId:rec.id, studentId:rec.studentId, title:rec.title, message:rec.message, status:'Ready', createdOn: commNowISO() });
    CmQueueStore.setSMS(q);
  }
  if(wants('Email') && ch.email){
    const q = CmQueueStore.getEmail();
    q.unshift({ id:'EMQ'+commUid(), queueId:rec.id, studentId:rec.studentId, title:rec.title, message:rec.message, status:'Ready', createdOn: commNowISO() });
    CmQueueStore.setEmail(q);
  }
  // Portal channel needs no queue row — it is always "sent" the instant
  // it is Approved, and is read live by getCommunicationHistory() below.
  if(typeof refreshCMQueueBadge==='function') refreshCMQueueBadge();
}

function cmApprove(id){
  const rec = CmQueueStore.getById(id);
  if(!rec) return;
  rec.status = 'Approved';
  rec.approvedBy = commUserLabel();
  rec.approvedOn = commNowISO();
  CmQueueStore.upsert(rec);
  logAudit('Approved', rec.module+' → '+rec.title+' for '+(rec.studentId||'—'));
  cmRouteApproved(id);
  if(typeof renderCMQueue==='function') renderCMQueue();
}

function cmReject(id, reason){
  const rec = CmQueueStore.getById(id);
  if(!rec) return;
  rec.status = 'Rejected';
  rec.approvedBy = commUserLabel();
  rec.approvedOn = commNowISO();
  rec.rejectReason = reason || '';
  CmQueueStore.upsert(rec);
  logAudit('Rejected', rec.module+' → '+rec.title+' for '+(rec.studentId||'—')+(reason?(' — '+reason):''));
  if(typeof renderCMQueue==='function') renderCMQueue();
}

function cmMarkEmergency(id){
  const rec = CmQueueStore.getById(id);
  if(!rec) return;
  rec.emergency = true;
  if(rec.status==='Waiting Approval'){
    rec.status='Approved'; rec.approvedBy=commUserLabel()+' (Emergency)'; rec.approvedOn=commNowISO();
    CmQueueStore.upsert(rec);
    logAudit('Emergency Bypass', rec.module+' → '+rec.title+' for '+(rec.studentId||'—'));
    cmRouteApproved(id);
  } else {
    CmQueueStore.upsert(rec);
  }
  if(typeof renderCMQueue==='function') renderCMQueue();
}

/** Marks a channel-queue row Sent/Failed (manual, no gateway — this is
 *  the boundary where a future sprint would plug in a real API). */
function cmMarkChannelStatus(channel, rowId, status, failReason){
  const map = { WhatsApp:['getWA','setWA'], SMS:['getSMS','setSMS'], Email:['getEmail','setEmail'] };
  const m = map[channel]; if(!m) return;
  const rows = CmQueueStore[m[0]]().map(r=> r.id===rowId ? Object.assign({}, r, { status, failReason: failReason||null, sentOn: status==='Sent'?commNowISO():r.sentOn }) : r);
  CmQueueStore[m[1]](rows);
  logAudit(channel+' '+status, 'Row '+rowId);
  if(status==='Sent'){
    const row = rows.find(r=>r.id===rowId);
    const rec = row && CmQueueStore.getById(row.queueId);
    if(rec){ rec.status = rec.status==='Approved' ? 'Sent' : rec.status; CmQueueStore.upsert(rec); }
  }
  if(typeof renderCMQueue==='function') renderCMQueue();
}

function cmDashboardStats(){
  const q = CmQueueStore.get();
  const today = commTodayStr();
  return {
    pendingApproval: q.filter(r=>r.status==='Waiting Approval').length,
    todaysMessages:   q.filter(r=>(r.createdOn||'').slice(0,10)===today).length,
    portalMessages:   q.filter(r=>r.status==='Approved'||r.status==='Sent').filter(r=>r.sendChannel.includes('Parent Portal')).length,
    waQueue:    CmQueueStore.getWA().filter(r=>r.status==='Ready'||r.status==='Pending').length,
    smsQueue:   CmQueueStore.getSMS().filter(r=>r.status==='Ready'||r.status==='Pending').length,
    emailQueue: CmQueueStore.getEmail().filter(r=>r.status==='Ready'||r.status==='Pending').length,
    failed:     q.filter(r=>r.status==='Failed').length + CmQueueStore.getWA().filter(r=>r.status==='Failed').length + CmQueueStore.getSMS().filter(r=>r.status==='Failed').length + CmQueueStore.getEmail().filter(r=>r.status==='Failed').length,
    scheduled:  q.filter(r=>r.status==='Scheduled').length
  };
}

/* ── EventBus wiring — subscribes CommEngine to every module namespace
   named in the CM-1.0 brief. Each module publishes a plain Dnyanankur
   Event (sourceModule + eventType + payload); CommEngine turns that into
   one Queue entry via cmNotify(). Subscribing here (rather than importing
   CommEngine into every module file) keeps the modules decoupled — any
   module can be developed/tested with zero knowledge of Communication. */
function cmInstallEventBusBridge(){
  if(!(window.Dnyanankur && Dnyanankur.Event)) { setTimeout(cmInstallEventBusBridge, 300); return; }
  if(Dnyanankur.Event.__cmBridgeInstalled) return;
  Dnyanankur.Event.__cmBridgeInstalled = true;
  Object.keys(CM_EVENT_MAP).forEach(function(eventType){
    Dnyanankur.Event.subscribe(eventType, function(evt){ cmNotify(eventType, evt.payload || {}); }, { mode:'sync' });
  });
  Dnyanankur.Logger && Dnyanankur.Logger.info && Dnyanankur.Logger.info('[CommEngine] Event Bus bridge installed — subscribed to '+Object.keys(CM_EVENT_MAP).length+' event types.');
}
if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', cmInstallEventBusBridge); } else { cmInstallEventBusBridge(); }

/* ── CM-1.0 QUEUE UI ─────────────────────────────────────────────── */
function refreshCMQueueBadge(){
  const n = CmQueueStore.get().filter(r=>r.status==='Waiting Approval').length;
  const badge = document.getElementById('navCMQueueCount');
  if(badge) badge.textContent = n>0 ? n : '';
}

function cmqTogglePause(field, val){
  if(!canEditSettings()){ toast('Only the Principal can pause channels.','err'); document.getElementById('cmqPauseWA') && renderCMQueue(); return; }
  const s = Store.getSettings();
  s[field] = val;
  Store.setSettings(s);
  logAudit('Channel Pause Changed', field+' = '+val);
  toast((val?'Paused ':'Resumed ')+field.replace('pause',''), 'ok');
}

function renderCMQueue(){
  const stats = cmDashboardStats();
  document.getElementById('cmqPending').textContent   = stats.pendingApproval;
  document.getElementById('cmqToday').textContent      = stats.todaysMessages;
  document.getElementById('cmqPortal').textContent      = stats.portalMessages;
  document.getElementById('cmqWA').textContent           = stats.waQueue;
  document.getElementById('cmqSMS').textContent          = stats.smsQueue;
  document.getElementById('cmqEmail').textContent        = stats.emailQueue;
  document.getElementById('cmqFailed').textContent       = stats.failed;
  document.getElementById('cmqScheduled').textContent    = stats.scheduled;

  const s = Store.getSettings();
  const paWA = document.getElementById('cmqPauseWA'), paSMS = document.getElementById('cmqPauseSMS'), paEmail = document.getElementById('cmqPauseEmail');
  if(paWA) paWA.checked = !!s.pauseWhatsApp;
  if(paSMS) paSMS.checked = !!s.pauseSMS;
  if(paEmail) paEmail.checked = !!s.pauseEmail;
  [paWA,paSMS,paEmail].forEach(el=>{ if(el) el.disabled = !canEditSettings(); });

  let rows = CmQueueStore.get();
  const mod = document.getElementById('cmqFilterModule').value;
  const st  = document.getElementById('cmqFilterStatus').value;
  const q   = (document.getElementById('cmqSearch').value||'').toLowerCase();
  if(mod) rows = rows.filter(r=>r.module===mod);
  if(st)  rows = rows.filter(r=>r.status===st);
  if(q)   rows = rows.filter(r=> (r.title+' '+r.type+' '+r.module+' '+(r.studentId||'')).toLowerCase().includes(q));

  const statusPill = (st)=>{
    const cls = {Draft:'pending','Waiting Approval':'pending',Approved:'sent',Rejected:'failed',Scheduled:'scheduled',Sent:'sent',Failed:'failed'}[st]||'pending';
    return `<span class="badge ${cls}">${esc(st)}</span>`;
  };

  document.getElementById('cmqTableBody').innerHTML = rows.map(r=>`
    <tr>
      <td style="font-family:var(--font-mono);font-size:12px;">${esc(formatDatetime(r.createdOn))}</td>
      <td>${esc(r.module)}</td>
      <td>${esc(r.type)}${r.emergency?' &#9888;':''}</td>
      <td>${esc(r.studentId||'—')}</td>
      <td style="max-width:280px;white-space:normal;color:var(--text-muted);font-size:12.5px;">${esc(r.message).slice(0,140)}${r.message.length>140?'…':''}</td>
      <td>${esc(r.priority)}</td>
      <td style="font-size:11.5px;">${r.sendChannel.map(esc).join(', ')}</td>
      <td>${statusPill(r.status)}</td>
      <td style="white-space:nowrap;">
        ${r.status==='Waiting Approval' && currentRole()==='Principal' ? `
          <button class="btn btn-outline btn-sm" onclick="cmApprove('${r.id}')">Approve</button>
          <button class="btn btn-outline btn-sm" onclick="(function(){var reason=prompt('Reason for rejection (optional):')||''; cmReject('${r.id}',reason);})()">Reject</button>
          <button class="btn btn-outline btn-sm" onclick="cmMarkEmergency('${r.id}')" title="Bypass approval">&#9888; Emergency</button>
        ` : (r.status==='Waiting Approval' ? '<span style="color:var(--text-muted);font-size:11.5px;">Principal only</span>' : '—')}
      </td>
    </tr>`).join('') || '<tr><td colspan="9" style="text-align:center;color:var(--text-muted);padding:24px;">No queue entries match these filters.</td></tr>';

  refreshCMQueueBadge();
}
// Keep the sidebar badge live even before the Queue view is opened.
setInterval(refreshCMQueueBadge, 4000);

