function commUid(){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.commUid(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.commUid();
  }
 return '_'+ Math.random().toString(36).substr(2,9); }

function commTodayStr(){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.commTodayStr(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.commTodayStr();
  }

  const d=new Date();
  return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());
}
function pad2(n){ return String(n).padStart(2,'0'); }
function commNowISO(){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.commNowISO(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.commNowISO();
  }
 return new Date().toISOString(); }
function nowTime(){ const d=new Date(); return pad2(d.getHours())+':'+pad2(d.getMinutes()); }

function formatDate(iso){
  if(!iso) return '—';
  const d=new Date(iso+'T00:00:00');
  return pad2(d.getDate())+'/'+pad2(d.getMonth()+1)+'/'+d.getFullYear();
}
function formatDatetime(iso){
  if(!iso) return '—';
  const d=new Date(iso);
  return pad2(d.getDate())+'/'+pad2(d.getMonth()+1)+'/'+d.getFullYear()+' '+pad2(d.getHours())+':'+pad2(d.getMinutes());
}

function currentRole(){ return document.getElementById('roleSelect').value; }
function commUserLabel(){
  const r=currentRole();
  if(r==='Principal') return 'Principal';
  if(r==='Clerk') return 'Clerk';
  const tc=document.getElementById('teacherClass').value;
  const td=document.getElementById('teacherDivision').value;
  return 'Teacher'+(tc?' (Class '+tc+(td?'-'+td:'')+')' : '');
}

