// ── TEACHER CLASS/DIVISION SCOPE ────────────────────────────────
// Security fix (remaining half of the role-lock task): the Class/Division
// selectors here must be driven by the real logged-in teacher's
// currentUser.classAssignments — the exact same field/pattern Attendance
// already uses (AttEngine.teacherAllowedClasses / canAccessClass) — instead
// of the full CLASSES/DIVISIONS list with a hardcoded '5'/'A' default.
// No new authorization system: this only reads currentUser and populates
// <option> elements, so a teacher physically cannot pick a class/division
// they aren't assigned to.
function commTeacherAssignments(){
  return (typeof currentUser !== 'undefined' && currentUser && Array.isArray(currentUser.classAssignments))
    ? currentUser.classAssignments
    : [];
}

// class -> [divisions], built once from currentUser.classAssignments
// (pairs look like "1st-A", same format Attendance/Register/Exam read).
function commTeacherClassDivMap(){
  const map = {};
  commTeacherAssignments().forEach(a=>{
    const idx = a.indexOf('-');
    const cls = idx===-1 ? a : a.slice(0,idx);
    const div = idx===-1 ? '' : a.slice(idx+1);
    if(!cls) return;
    if(!map[cls]) map[cls]=[];
    if(div && !map[cls].includes(div)) map[cls].push(div);
  });
  return map;
}

function commPopulateTeacherScope(){
  const tc=document.getElementById('teacherClass');
  const td=document.getElementById('teacherDivision');
  if(!tc || !td) return;

  const classDivMap = commTeacherClassDivMap();
  const classes = Object.keys(classDivMap);

  tc.innerHTML='';
  if(!classes.length){
    // Fail closed: a teacher with no assignments configured gets no
    // selectable class/division, same as attEngCanAccessClass() denying
    // access when there are no assignments to check against.
    tc.innerHTML='<option value="">No Class Assigned</option>';
    td.innerHTML='<option value="">—</option>';
    tc.disabled=true; td.disabled=true;
    return;
  }

  classes.forEach(c=>{ const o=document.createElement('option'); o.value=c; o.textContent='Class '+c; tc.appendChild(o); });

  const totalAssignments = commTeacherAssignments().length;
  if(totalAssignments===1){
    // Only one assignment overall — auto-select it, nothing else to choose.
    tc.value=classes[0];
    tc.disabled=true;
  } else {
    tc.disabled=false;
    tc.value=classes[0];
  }

  commPopulateTeacherDivision();
}

function commPopulateTeacherDivision(){
  const tc=document.getElementById('teacherClass');
  const td=document.getElementById('teacherDivision');
  if(!tc || !td) return;

  const classDivMap = commTeacherClassDivMap();
  const divs = classDivMap[tc.value] || [];

  td.innerHTML='';
  if(!divs.length){
    td.innerHTML='<option value="">—</option>';
    td.disabled=true;
    return;
  }

  divs.forEach(d=>{ const o=document.createElement('option'); o.value=d; o.textContent='Div '+d; td.appendChild(o); });
  td.value=divs[0];
  td.disabled = tc.disabled || (divs.length===1);
}

function commOnTeacherClassChange(){
  commPopulateTeacherDivision();
  if(currentRole()==='Teacher') refreshStudentList();
}

function esc(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

function toast(msg, type='info', dur=3000){
  const s=document.getElementById('toast-stack');
  const t=document.createElement('div');
  const ic = type==='ok'?'✓' : type==='err'?'✕' : 'ℹ';
  t.className='toast '+type;
  t.innerHTML=ic+' '+esc(msg);
  s.appendChild(t);
  setTimeout(()=>{ t.style.opacity='0'; t.style.transform='translateY(8px)'; t.style.transition='all .2s'; setTimeout(()=>t.remove(),220); }, dur);
}

function commOpenModal(id){ document.getElementById(id).classList.add('show'); }
function commCloseModal(id){ document.getElementById(id).classList.remove('show'); }

function confirmAction(title, message, cb){
  document.getElementById('confirmTitle').textContent=title;
  document.getElementById('confirmMessage').textContent=message;
  document.getElementById('btnConfirmAction').onclick=()=>{ commCloseModal('modalConfirm'); cb(); };
  commOpenModal('modalConfirm');
}

