const pageTitles = {
  commdash:   ['Dashboard','Live overview of all SMS & WhatsApp communication'],
  cmqueue:    ['Communication Queue — Approval','Every module notification, generated automatically, waiting for Principal review before it can be sent'],
  compose:     ['Compose & Send','Create and deliver messages to students & parents'],
  templates:   ['Message Templates','Create and manage reusable message templates'],
  history:     ['Message History','Complete log of all sent, pending and failed messages'],
  smsqueue:    ['SMS Queue & History','Track, resend and manage every outbound SMS'],
  bulkmsg:     ['Bulk Messaging','Send one message to many recipients at once'],
  wacentre:    ['WhatsApp Centre','Templates · Media · Documents · Report Cards · Receipts · Hall Tickets'],
  reports:     ['Reports','Analytics and export tools'],
  audit:       ['Audit Log','Every action taken in this module'],
  settings:    ['Settings','School details and channel configuration'],
  permissions: ['Permissions','Role-based access control overview'],
};

function commNavigate(viewId, opts={}){
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
  const view=document.getElementById('view-'+viewId);
  if(!view) return;
  view.classList.add('active');
  const navBtn=document.querySelector(`.nav-item[data-view="${viewId}"]`);
  if(navBtn) navBtn.classList.add('active');
  const info=pageTitles[viewId]||[viewId,''];
  document.getElementById('pageTitle').textContent=info[0];
  document.getElementById('pageSubtitle').textContent=info[1];

  if(viewId==='commdash')   refreshDashboard();
  if(viewId==='cmqueue')    renderCMQueue();
  if(viewId==='compose')     { refreshStudentList(); if(opts.mode) activateSelMode(opts.mode); }
  if(viewId==='templates')   renderTemplates();
  if(viewId==='history')     renderHistory();
  if(viewId==='smsqueue')    renderSMSQueue();
  if(viewId==='bulkmsg')     initBulkView();
  if(viewId==='wacentre')    initWACentre();
  if(viewId==='reports')     renderReports();
  if(viewId==='audit')       commRenderAudit();
  if(viewId==='settings')    commLoadSettingsForm();
  applyRoleRestrictions();
}

