/* ── bulk send target label ── */
function bulkModeLabel(){
  const fc = (document.getElementById('bulkClass')    ||{value:''}).value;
  const fd = (document.getElementById('bulkDivision') ||{value:''}).value;
  return {
    school:     'Entire School',
    class:      fc ? 'Class '+fc : 'All Classes',
    division:   (fc?'Class '+fc:'')+(fd?'-'+fd:'') || 'All Divisions',
    individual: bulkIndivSel.size+' Individual Student(s)',
    teachers:   'Teachers',
    clerks:     'Clerks',
  }[bulkMode] || bulkMode;
}

/* ── MAIN SEND ── */
function executeBulkSend(fromPreview){
  if(!bulkRecipients.length){ toast('No recipients selected.','err'); return; }
  const body = (document.getElementById('bulkMsgBody').value||'').trim();
  if(!body){ toast('Message body is empty.','err'); return; }

  const chkSMS = document.getElementById('bulkChkSMS').checked;
  const chkWA  = document.getElementById('bulkChkWA').checked;
  if(!chkSMS&&!chkWA){ toast('Select at least one channel.','err'); return; }

  const settings = Store.getSettings();
  if(chkSMS && !settings.enableSMS){ toast('SMS is disabled in Settings.','err'); return; }
  if(chkWA  && !settings.enableWA ){ toast('WhatsApp is disabled in Settings.','err'); return; }

  const sendWhen  = document.querySelector('input[name="bulkWhen"]:checked').value;
  const schedDate = document.getElementById('bulkSchedDate').value;
  const schedTime = document.getElementById('bulkSchedTime').value;
  const repeat    = document.getElementById('bulkSchedRepeat').value;
  if(sendWhen==='later' && (!schedDate||!schedTime)){ toast('Set a schedule date and time.','err'); return; }

  if(fromPreview) commCloseModal('modalBulkPreview');

  const prog = document.getElementById('bulkSendProgress');
  const fill = document.getElementById('spFill');
  const lbl  = document.getElementById('spLabel');
  const pct  = document.getElementById('spPct');
  if(prog) prog.classList.add('show');

  const total    = bulkRecipients.length;
  const channels = [chkSMS?'SMS':null, chkWA?'WhatsApp':null].filter(Boolean);
  const sentDate = sendWhen==='later' ? schedDate : commTodayStr();
  const sentTime = sendWhen==='later' ? schedTime : nowTime();
  const status   = sendWhen==='later' ? 'Pending'  : 'Sent';
  let done=0, smsSent=0, waSent=0;

  function processBatch(idx){
    const end = Math.min(idx+5, total);
    for(let i=idx; i<end; i++){
      const r   = bulkRecipients[i];
      const stu = { name:r.name, father:'', class:r.class||'', division:r.division||'', admNo:'', balance:0, mobile:r.mobile };
      const msg = generateMessage(body, stu);
      const sig = settings.smsSignature ? '\n- '+settings.smsSignature : '';
      const fullMsg = msg + sig;

      channels.forEach(ch => {
        Store.addToQueue({ id:commUid(), date:sentDate, time:sentTime, recipient:r.name,
          mobile:r.mobile, message:fullMsg, module:'Bulk', status, createdBy:commUserLabel(),
          sentAt:status==='Sent'?new Date().toISOString():'', failReason:'', repeat:repeat||'None' });
        Store.addHistory({ id:commUid(), date:sentDate, time:sentTime, student:r.name,
          mobile:r.mobile, channel:ch, message:fullMsg, status, createdBy:commUserLabel() });
        if(ch==='SMS') smsSent++;
        if(ch==='WhatsApp') waSent++;
      });
      done++;
    }
    const p = Math.round((done/total)*100);
    if(fill) fill.style.width = p+'%';
    if(lbl)  lbl.textContent  = (status==='Pending'?'Queuing':'Sending')+' '+done+' / '+total+'...';
    if(pct)  pct.textContent  = p+'%';
    if(done<total){ requestAnimationFrame(()=>processBatch(end)); }
    else { finalizeBulkSend(smsSent, waSent, total, channels, sentDate, sentTime, status, repeat, body); }
  }
  requestAnimationFrame(()=>processBatch(0));
}

function finalizeBulkSend(smsSent, waSent, total, channels, sentDate, sentTime, status, repeat, body){
  Store.addBulkHistory({
    id:commUid(), date:sentDate, time:sentTime,
    group:bulkModeLabel(), recipientCount:total,
    channels:channels.join('+'), message:body,
    status, repeat:repeat||'None', createdBy:commUserLabel()
  });
  logAudit('Bulk Send', `${total} recipient(s) via ${channels.join('+')} (${bulkModeLabel()}) — ${status}`);

  const prog = document.getElementById('bulkSendProgress');
  if(prog) setTimeout(()=>prog.classList.remove('show'), 2000);

  const summary = [smsSent?smsSent+' SMS':'', waSent?waSent+' WhatsApp':''].filter(Boolean).join(' + ');
  const verb    = status==='Pending' ? 'queued' : 'sent';
  showBulkResult('ok', `\u2713 ${summary} ${verb} to ${total} recipient(s).`);
  toast(`Bulk send complete: ${total} message(s) ${verb}.`, 'ok');
  renderBulkHistory();
}

function showBulkResult(type, msg){
  const b = document.getElementById('bulkResultBanner');
  if(!b) return;
  b.className = 'result-banner show '+(type==='ok'?'ok':'warn');
  b.textContent = msg;
  setTimeout(()=>b.classList.remove('show'), 7000);
}

/* ── Bulk History table ── */
function renderBulkHistory(){
  const all = Store.getBulkHistory();
  const pill = document.getElementById('bulkHistCountPill');
  if(pill) pill.textContent = all.length;

  const q = bulkHistSearch.toLowerCase();
  const rows = q
    ? all.filter(r=>(r.group||'').toLowerCase().includes(q)||(r.message||'').toLowerCase().includes(q)||(r.channels||'').toLowerCase().includes(q)||(r.date||'').includes(q))
    : all;

  const tbody = document.getElementById('bulkHistTableBody');
  if(!tbody) return;
  if(!rows.length){
    tbody.innerHTML='<tr class="empty-row"><td colspan="8">No bulk send history yet.</td></tr>';
    return;
  }
  tbody.innerHTML = rows.map(r => {
    const chCls = (r.channels||'').includes('WhatsApp') ? 'wa' : 'sms';
    const stCls = {Sent:'sent',Pending:'pending',Failed:'failed',Cancelled:'cancelled'}[r.status]||'';
    return `<tr>
      <td style="font-size:12px;white-space:nowrap;">${esc(formatDate(r.date))}</td>
      <td style="font-size:12px;white-space:nowrap;">${esc(r.time)}</td>
      <td style="font-weight:600;">${esc(r.group)}</td>
      <td><span class="badge sent">${esc(r.recipientCount)}</span></td>
      <td><span class="badge ${chCls}">${esc(r.channels)}</span></td>
      <td class="cell-msg">${esc(r.message)}</td>
      <td><span class="badge ${stCls}">${esc(r.status)}</span></td>
      <td style="font-size:12px;color:var(--text-muted);">${esc(r.createdBy)}</td>
    </tr>`;
  }).join('');
}

function exportBulkHistoryCSV(){
  const rows = Store.getBulkHistory();
  if(!rows.length){ toast('No bulk history to export.','err'); return; }
  const cols = ['Date','Time','Group/Target','Recipients','Channels','Message','Status','Created By'];
  const data = rows.map(r=>[r.date,r.time,r.group,r.recipientCount,r.channels,
    '"'+String(r.message||'').replace(/"/g,'""')+'"',r.status,r.createdBy]);
  const csv  = [cols.join(','),...data.map(r=>r.join(','))].join('\r\n');
  const blob = new Blob([csv],{type:'text/csv'});
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href=url; a.download='bulk_history_'+commTodayStr()+'.csv'; a.click();
  URL.revokeObjectURL(url);
  logAudit('Bulk CSV Export',rows.length+' records');
  toast('CSV exported.','ok');
}

