/* ── module state ── */
let waCurTab         = 'send';
let waSendStudentId  = null;
let waMediaStudentId = null;
let waDocTypeId      = '';
let waChosenFile     = null;
let watActiveCategory= '';
let watSearchTerm    = '';
let waHistSearch     = '';
let waHistCat        = '';

/* ════════════════════════════
   FUTURE API HOOK
   ════════════════════════════
   When WhatsApp Business API is ready:
   1. Replace waOpenLink() with waAPISend()
   2. waAPISend() POSTs to Meta Cloud API:
      POST https://graph.facebook.com/v18.0/{phone_number_id}/messages
      Headers: { Authorization: Bearer {token}, Content-Type: application/json }
      Body for text:    { messaging_product:'whatsapp', to:mobile, type:'text', text:{body:msg} }
      Body for document:{ messaging_product:'whatsapp', to:mobile, type:'document',
                          document:{ link:docUrl, caption:caption, filename:filename } }
      Body for template:{ messaging_product:'whatsapp', to:mobile, type:'template',
                          template:{ name:templateName, language:{code:'en'}, components:[...] } }
   3. All template variable tokens {{StudentName}} map to components[].parameters array
   4. No other code changes needed — templates, UI, history all remain identical.
*/
function waOpenLink(mobile, message){
  const num = (mobile||'').replace(/\D/g,'');
  if(!num){ toast('Invalid mobile number.','err'); return false; }
  const url = `https://wa.me/${WA_COUNTRY_CODE}${num}?text=${encodeURIComponent(message)}`;
  window.open(url,'_blank');
  return true;
}

/* FUTURE: replace waOpenLink with this when API is live */
async function waAPISend(mobile, message, mediaUrl='', mediaType=''){
  /* stub — swap implementation only; callers are unchanged */
  return waOpenLink(mobile, message);
}

/* ── WA message generator (resolves WA_VARIABLES) ── */
function generateWAMessage(template, student, extra={}){
  const s = Store.getSettings();
  const today = fmtDMY(new Date());
  let msg = template;
  if(student){
    msg=msg.replace(/\{\{StudentName\}\}/g, student.name||'');
    msg=msg.replace(/\{\{FatherName\}\}/g,  student.father||'');
    msg=msg.replace(/\{\{Class\}\}/g,       student.class||'');
    msg=msg.replace(/\{\{Division\}\}/g,    student.division||'');
    msg=msg.replace(/\{\{AdmissionNo\}\}/g, student.admNo||'');
    msg=msg.replace(/\{\{Balance\}\}/g,     student.balance!=null?student.balance:'');
    msg=msg.replace(/\{\{ReceiptNo\}\}/g,   student.receiptNo||extra.receiptNo||'');
    msg=msg.replace(/\{\{ExamName\}\}/g,    extra.examName||'');
    msg=msg.replace(/\{\{Result\}\}/g,      extra.result||'');
  }
  msg=msg.replace(/\{\{SchoolName\}\}/g,    s.schoolName||'');
  msg=msg.replace(/\{\{PrincipalName\}\}/g, s.principalName||'');
  msg=msg.replace(/\{\{Date\}\}/g,          today);
  msg=msg.replace(/\{\{DocumentType\}\}/g,  extra.docType||'');
  msg=msg.replace(/\{\{DocLink\}\}/g,       extra.docLink||'');
  /* resolve single-brace tokens too */
  if(student){
    msg=msg.replace(/\{StudentName\}/g, student.name||'');
    msg=msg.replace(/\{Class\}/g,       student.class||'');
    msg=msg.replace(/\{Amount\}/g,      extra.amount!=null?extra.amount:(student.balance!=null?student.balance:''));
    msg=msg.replace(/\{ReceiptNo\}/g,   student.receiptNo||extra.receiptNo||'');
  }
  msg=msg.replace(/\{SchoolName\}/g,    s.schoolName||'');
  return msg;
}

/* ── render WA variable buttons ── */
function renderWAVarButtons(containerId, targetId){
  const c = document.getElementById(containerId);
  if(!c) return;
  c.innerHTML = WA_VARIABLES.map(v =>
    `<span class="wa-var-tag" onclick="insertMergeField('${esc(targetId)}','${esc(v)}')">${esc(v)}</span>`
  ).join('');
}

/* ── WA phone bubble builder ── */
function buildWABubbleHTML(msg, file, docTypeId){
  const dt = WA_DOC_TYPES.find(d=>d.id===docTypeId);
  let docHTML = '';
  if(file && dt && dt.id!=='image'){
    docHTML = `<div class="wa-doc-preview">
      <div class="wdp-icon">${dt.icon}</div>
      <div><div class="wdp-name">${esc(file.name)}</div>
           <div class="wdp-type">${esc(file.type||'document')} · ${fmtFileSize(file.size)}</div></div>
    </div>`;
  } else if(file && dt && dt.id==='image'){
    docHTML = `<div class="wa-doc-preview" style="background:transparent;padding:0;">
      <img class="wa-img-preview" src="${URL.createObjectURL(file)}" alt="preview">
    </div>`;
  }
  const time = new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});
  return `<div class="wa-bubble">${docHTML}${esc(msg).replace(/\n/g,'<br>').replace(/\*(.*?)\*/g,'<b>$1</b>').replace(/_(.*?)_/g,'<i>$1</i>')}
    <div class="wa-time">${time} ✓✓</div></div>`;
}

function fmtFileSize(bytes){
  if(!bytes) return '';
  if(bytes<1024) return bytes+'B';
  if(bytes<1048576) return Math.round(bytes/1024)+'KB';
  return (bytes/1048576).toFixed(1)+'MB';
}

