/* ──────────────────────────────────────────────
   ENFORCEMENT — wraps handleSend() so the new settings actually apply
────────────────────────────────────────────── */
function commEnforceSendRules(){
  const cs=commGetSettings();
  const sendWhen=[...document.querySelectorAll('input[name="sendWhen"]')].find(r=>r.checked)?.value||'now';
  const role=currentRole();

  if(cs.principalApprovalRequired && role!=='Principal'){
    toast('Principal approval is required to send or schedule messages. Please ask the Principal to send this.','err');
    return false;
  }

  if(sendWhen==='now'){
    if(commIsWithinQuietHours(cs.quietHoursStart, cs.quietHoursEnd)){
      toast(`Sending is paused during Quiet Hours (${cs.quietHoursStart}–${cs.quietHoursEnd}). Use "Schedule Later" instead.`,'err');
      return false;
    }
    if(cs.maxDailyLimit>0){
      const already=commTodaySentCount();
      const channelsCount=(document.getElementById('chkSMS').checked?1:0)+(document.getElementById('chkWA').checked?1:0);
      const attempting=selectedStudentIds.size*Math.max(channelsCount,1);
      if(already+attempting>cs.maxDailyLimit){
        toast(`Daily message limit reached (${already}/${cs.maxDailyLimit} sent today). This send would exceed the limit.`,'err');
        return false;
      }
    }
    if(cs.duplicateProtection){
      const body=document.getElementById('messageBody').value.trim();
      const students=Store.getStudents();
      const dupNames=[];
      selectedStudentIds.forEach(id=>{
        const s=students.find(x=>x.id===id);
        if(s && commIsDuplicate(s.mobile, body, cs.duplicateProtectionWindow||30)) dupNames.push(s.name);
      });
      if(dupNames.length){
        toast(`Duplicate protection: ${dupNames.slice(0,3).join(', ')}${dupNames.length>3?` +${dupNames.length-3} more`:''} already received this exact message recently.`,'err');
        return false;
      }
    }
  }
  return true;
}

const commOriginalHandleSend=handleSend;
handleSend=function(){
  if(!commEnforceSendRules()) return;

  const sendWhen=[...document.querySelectorAll('input[name="sendWhen"]')].find(r=>r.checked)?.value||'now';
  if(sendWhen==='now'){
    const cs=commGetSettings();
    if(cs.duplicateProtection){
      const body=document.getElementById('messageBody').value.trim();
      const students=Store.getStudents();
      selectedStudentIds.forEach(id=>{
        const s=students.find(x=>x.id===id);
        if(s) commLogDup(s.mobile, body);
      });
    }
  }
  commOriginalHandleSend();
};

/* ──────────────────────────────────────────────
   MESSAGE FOOTER / WHATSAPP SIGNATURE — wraps sendSMS()/sendWhatsApp()
   so the new text is actually appended to outgoing messages, in
   addition to the existing SMS Signature / WhatsApp Footer.
────────────────────────────────────────────── */
const commOriginalSendSMS=sendSMS;
sendSMS=function(student, message, options={}){
  const cs=commGetSettings();
  let m=message;
  if(cs.messageFooter) m=m+'\n'+cs.messageFooter;
  return commOriginalSendSMS(student, m, options);
};

const commOriginalSendWhatsApp=sendWhatsApp;
sendWhatsApp=function(student, message, options={}){
  const cs=commGetSettings();
  let m=message;
  if(cs.messageFooter) m=m+'\n'+cs.messageFooter;
  if(cs.waSignature) m=m+'\n'+cs.waSignature;
  return commOriginalSendWhatsApp(student, m, options);
};

