/* ════════════════════════════════════════════════════════════════
   INFRASTRUCTURE ↔ ERP LOCALSTORAGE BRIDGE  v1.0
   Maps  dnyanankur_erp.<module>  →  ERP native LS keys
   so Backup Engine, Import/Export, and Universal Search always
   operate on live ERP data without duplicating storage.
════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var APP_NS = 'dnyanankur_erp';
  var KEY_MAP = {
    students:       'students',
    teachers:       'teachers',
    finance:        'fees',
    inventory:      'inventory_items',
    transport:      'transport_master',
    examination:    'marks',
    communication:  'clerk_notifications',
    admissions:     'pending_student_registrations',
    attendance:     'attendance',
    fees_school:    'school_fee_ledger',
    fees_transport: 'transport_fee_ledger',
    users:          'users',
    settings:       'school_settings',
  };
  function resolveKey(k) {
    if (typeof k !== 'string' || !k.startsWith(APP_NS + '.')) return k;
    var sub = k.slice(APP_NS.length + 1);
    return KEY_MAP.hasOwnProperty(sub) ? KEY_MAP[sub] : k;
  }
  if (!localStorage.__erpBridgeInstalled) {
    var proto = Object.getPrototypeOf(localStorage);
    var _gi = proto.getItem, _si = proto.setItem, _ri = proto.removeItem;
    proto.getItem    = function (k)    { return _gi.call(this, resolveKey(k)); };
    proto.setItem    = function (k, v) { return _si.call(this, resolveKey(k), v); };
    proto.removeItem = function (k)    { return _ri.call(this, resolveKey(k)); };
    try { Object.defineProperty(localStorage, '__erpBridgeInstalled', { value: true, configurable: false }); } catch(e) {}
  }
  // Write version record so Backup Engine detects ERP correctly
  try {
    var raw = localStorage.getItem(APP_NS + '.version');
    if (!raw) {
      var s = JSON.parse(localStorage.getItem('school_settings') || '{}');
      localStorage.setItem(APP_NS + '.version',
        JSON.stringify({ version: '15.0.0', build: 'Alpha', edition: 'Standard',
                         school: s.schoolName || 'Dnyanankur ERP' }));
    }
  } catch (e) {}
  console.log('[ERP-Bridge] LocalStorage bridge active.');
})();



