/* ─────────────────────────────────────────
   10. UI CONTROLLER
───────────────────────────────────────── */

// ── Navigation ──
function ieNav(page) {
  document.querySelectorAll('#ie-root .page').forEach(p => p.classList.remove('active'));
  const el = document.getElementById('page-'+page);
  if (el) el.classList.add('active');

  // Page init
  if (page === 'stats')   renderStatsPage();
  if (page === 'audit')   renderAuditPage();
  if (page === 'schema')  renderSchemaPage();
  if (page === 'adapter') refreshLsInspector();
}
// Bridge used by the unified sidebar (Backup Engine's navigate()) to drive
// this engine's internal page switching without duplicating nav state.
window.IEBridge = { showPage: ieNav };

// ── Steps ──
const STEP_IDS = ['import-step-file','import-step-validate','import-step-preview','import-step-result'];
function goStep(n) {
  STEP_IDS.forEach((id, i) => {
    const el = document.getElementById(id);
    if (el) el.style.display = i === n ? 'block' : 'none';
  });
  document.querySelectorAll('#ie-root .step').forEach((s, i) => {
    s.className = 'step' + (i < n ? ' done' : i === n ? ' active' : '');
    const num = s.querySelector('.step-num');
    if (num) num.textContent = i < n ? '✓' : (i+1);
  });
}

// ── File select ──
function onDragOver(e) {
  e.preventDefault();
  document.getElementById('upload-zone').classList.add('drag-over');
}
function onDragLeave(e) {
  document.getElementById('upload-zone').classList.remove('drag-over');
}
function onDrop(e) {
  e.preventDefault();
  document.getElementById('upload-zone').classList.remove('drag-over');
  const file = e.dataTransfer.files[0];
  if (file) processFile(file);
}
function onFileSelect(e) {
  const file = e.target.files[0];
  if (file) processFile(file);
}

async function processFile(file) {
  const entity = document.getElementById('import-entity').value;
  if (!entity) {
    showInfo('file-info','error','⚠ Please select an entity type first.');
    return;
  }
  if (file.size > 10 * 1024 * 1024) {
    showInfo('file-info','error','⚠ File too large. Max 10 MB.');
    return;
  }
  showInfo('file-info','info', `📄 <b>${file.name}</b> — ${(file.size/1024).toFixed(1)} KB — Parsing…`);
  try {
    const result = await ImportOrchestrator.loadFile(file);
    showInfo('file-info','success',
      `✅ Parsed <b>${result.rows.length} rows</b> from <b>${file.name}</b> (${result.format})`);
    // auto-proceed to validate
    setTimeout(runValidation, 300);
  } catch(e) {
    showInfo('file-info','error', '❌ Parse error: ' + e.message);
  }
}

function showInfo(id, type, html) {
  const el = document.getElementById(id);
  if (!el) return;
  el.style.display = 'flex';
  el.className = 'alert alert-'+type;
  el.innerHTML = html;
}

function onEntityChange() {
  const entity = document.getElementById('import-entity').value;
  if (!entity) return;
  // show field hint
  const schema = SchemaRegistry.get(entity);
  if (schema) {
    const req = schema.fields.filter(f => f.required).map(f => `<span class="field-chip required">${f.name}*</span>`);
    const opt = schema.fields.filter(f => !f.required).map(f => `<span class="field-chip">${f.name}</span>`);
    showInfo('file-info','info',
      `<div><b>${schema.icon} ${schema.label}</b> — Required: ${req.join('')} Optional: ${opt.join('')}</div>`);
    document.getElementById('file-info').style.display = 'block';
  }
}

// ── Validation ──
async function runValidation() {
  const entity = document.getElementById('import-entity').value;
  goStep(1);
  document.getElementById('import-step-file').style.display = 'block';
  document.getElementById('import-step-validate').style.display = 'block';

  const bar  = document.getElementById('val-progress-bar');
  const lbl  = document.getElementById('val-progress-lbl');
  const rows = ImportOrchestrator.getState().rawRows;

  // Animate progress
  let pct = 0;
  const interval = setInterval(() => {
    pct = Math.min(pct + 15, 85);
    bar.style.width = pct + '%';
  }, 80);

  const validated = await ImportOrchestrator.runValidation(entity);
  clearInterval(interval);
  bar.style.width = '100%';

  const total    = validated.length;
  const valid    = validated.filter(r => r.valid).length;
  const invalid  = validated.filter(r => !r.valid).length;
  const dupes    = validated.filter(r => r.isDupe).length;
  const intDupes = validated.filter(r => r.isInternalDupe).length;

  lbl.textContent = `Validation complete — ${total} records processed`;

  // Summary stats
  document.getElementById('val-summary').innerHTML = [
    [total,    'Total Rows',         '#1d4ed8'],
    [valid,    'Valid',              '#059669'],
    [invalid,  'Invalid (Errors)',   '#dc2626'],
    [dupes,    'Existing Duplicates','#d97706'],
  ].map(([n,l,c]) => `<div class="stat-box" style="border-left-color:${c}">
    <div class="stat-num" style="color:${c}">${n}</div>
    <div class="stat-lbl">${l}</div>
  </div>`).join('');

  // Issues list
  const issuesEl = document.getElementById('val-issues');
  const allIssues = validated.flatMap(r => r.issues.map(iss => ({...iss, rowIndex: r.index})));
  if (allIssues.length === 0 && intDupes === 0) {
    issuesEl.innerHTML = '<div class="alert alert-success">✅ All records passed validation. No issues found.</div>';
  } else {
    const topIssues = allIssues.slice(0,25);
    issuesEl.innerHTML = `
      ${intDupes > 0 ? `<div class="alert alert-warn">⚠ ${intDupes} duplicate IDs within the file — extra rows will be skipped.</div>` : ''}
      <div style="font-weight:700;font-size:12.5px;margin-bottom:8px;">Issues (showing first ${topIssues.length} of ${allIssues.length})</div>
      <ul class="val-list">
        ${topIssues.map(iss => `<li class="val-item">
          <div class="val-dot ${iss.severity === 'error' ? 'err' : 'warn'}"></div>
          <div>Row ${iss.rowIndex}: <b>${iss.field}</b> — ${iss.msg}</div>
        </li>`).join('')}
      </ul>`;
  }

  const proceedBtn = document.getElementById('proceed-btn');
  if (valid > 0) {
    proceedBtn.disabled = false;
    proceedBtn.textContent = `Preview ${valid} valid records →`;
  } else {
    proceedBtn.disabled = true;
    proceedBtn.textContent = 'No valid records to import';
  }
}

// ── Preview ──
async function goPreview() {
  const strategy = document.getElementById('import-dedup').value;
  const {toImport, toUpdate, skipped} = await ImportOrchestrator.prepareDedup(strategy);
  const state = ImportOrchestrator.getState();

  goStep(2);
  document.getElementById('import-step-file').style.display = 'none';
  document.getElementById('import-step-validate').style.display = 'none';
  document.getElementById('import-step-preview').style.display = 'block';

  // Banner
  document.getElementById('preview-banner').innerHTML = `
    <div class="alert alert-info" style="margin-bottom:14px;">
      <span>ℹ️</span>
      <span>
        <b>${toImport.length}</b> new records will be inserted &nbsp;·&nbsp;
        <b>${toUpdate.length}</b> existing records will be ${strategy === 'skip' ? '— (skipped)' : strategy === 'replace' ? 'replaced' : 'merged'} &nbsp;·&nbsp;
        <b>${skipped.length}</b> duplicates skipped &nbsp;·&nbsp;
        <b>${state.validated.filter(r=>!r.valid).length}</b> invalid rejected
      </span>
    </div>`;

  renderPreviewTable('valid');
}

let _currentPreviewTab = 'valid';
function switchPreviewTab(tab) {
  _currentPreviewTab = tab;
  document.querySelectorAll('#ie-root .tab-btn').forEach((b,i) => {
    b.classList.toggle('active', ['valid','invalid','dupes'][i] === tab);
  });
  renderPreviewTable(tab);
}

function renderPreviewTable(tab) {
  const state = ImportOrchestrator.getState();
  let rows;
  if (tab === 'valid') {
    rows = [...state.toImport, ...state.toUpdate];
  } else if (tab === 'invalid') {
    rows = state.validated.filter(r => !r.valid).map(r => r.row);
  } else {
    rows = state.skipped.map(r => r.row);
  }

  const wrap = document.getElementById('preview-table-wrap');
  const countEl = document.getElementById('preview-row-count');
  countEl.textContent = `Showing ${Math.min(rows.length,100)} of ${rows.length} records${rows.length > 100 ? ' (first 100 only)' : ''}`;

  if (!rows.length) {
    wrap.innerHTML = '<div style="padding:24px;text-align:center;color:var(--muted);">No records in this category.</div>';
    return;
  }
  const cols = Object.keys(rows[0]);
  const display = rows.slice(0,100);
  wrap.innerHTML = `<table>
    <thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}<th>Status</th></tr></thead>
    <tbody>${display.map((r,i) => {
      const v = state.validated.find(x => x.row === r || JSON.stringify(x.row) === JSON.stringify(r));
      const badge = tab === 'valid' 
        ? (state.toImport.includes(r) ? '<span class="badge badge-green">NEW</span>' : '<span class="badge badge-blue">UPDATE</span>')
        : tab === 'invalid' ? '<span class="badge badge-red">REJECTED</span>'
        : '<span class="badge badge-yellow">SKIP</span>';
      return `<tr>${cols.map(c=>`<td class="td-mono">${r[c]??''}</td>`).join('')}<td>${badge}</td></tr>`;
    }).join('')}</tbody>
  </table>`;
}

function confirmImport() {
  const state = ImportOrchestrator.getState();
  const schema = SchemaRegistry.get(state.entity);
  document.getElementById('modal-confirm-body').innerHTML = `
    <div class="alert alert-warn" style="margin-bottom:14px;">
      ⚠ You are about to write data to storage. This action can be rolled back immediately after.
    </div>
    <table style="width:100%;font-size:13px;">
      <tr><td style="padding:6px;color:var(--muted);">Entity</td><td><b>${schema?.icon} ${schema?.label}</b></td></tr>
      <tr><td style="padding:6px;color:var(--muted);">New Records</td><td><b style="color:#059669">${state.toImport.length}</b></td></tr>
      <tr><td style="padding:6px;color:var(--muted);">Updated Records</td><td><b style="color:#2563eb">${state.toUpdate.length}</b></td></tr>
      <tr><td style="padding:6px;color:var(--muted);">Rejected</td><td><b style="color:#dc2626">${state.validated.filter(r=>!r.valid).length}</b></td></tr>
      <tr><td style="padding:6px;color:var(--muted);">Strategy</td><td>${document.getElementById('import-dedup').value}</td></tr>
    </table>`;
  ieOpenModal('modal-confirm');
}

async function executeImport() {
  ieCloseModal('modal-confirm');
  try {
    const stats = await ImportOrchestrator.execute();
    goStep(3);
    document.getElementById('import-step-preview').style.display = 'none';
    document.getElementById('import-step-result').style.display = 'block';

    document.getElementById('result-stats').innerHTML = [
      [stats.total,    'Total Rows',    '#1d4ed8'],
      [stats.imported, 'Imported',      '#059669'],
      [stats.updated,  'Updated',       '#2563eb'],
      [stats.skipped,  'Skipped',       '#d97706'],
      [stats.rejected, 'Rejected',      '#dc2626'],
    ].map(([n,l,c]) => `<div class="stat-box" style="border-left-color:${c}">
      <div class="stat-num" style="color:${c}">${n}</div>
      <div class="stat-lbl">${l}</div>
    </div>`).join('');

    document.getElementById('result-detail').innerHTML =
      `<div class="alert alert-success">✅ Import complete! Session ID: <code>${stats.sessionId}</code>
       — ${new Date(stats.ts).toLocaleString()}</div>
       <div class="alert alert-info">↩ Use "Rollback" to undo this import if needed. The rollback option will disappear when you import another file.</div>`;
  } catch(e) {
    document.getElementById('result-detail').innerHTML =
      `<div class="alert alert-error">❌ Import failed: ${e.message}</div>`;
  }
}

async function rollbackImport() {
  if (!confirm('Rollback this import? All imported/updated records will be restored to their previous state.')) return;
  try {
    await ImportOrchestrator.rollback();
    alert('✅ Rollback successful. Data restored to pre-import state.');
    resetImport();
  } catch(e) {
    alert('❌ Rollback failed: ' + e.message);
  }
}

function resetImport() {
  ImportOrchestrator.reset();
  goStep(0);
  STEP_IDS.forEach((id,i) => {
    const el = document.getElementById(id);
    if (el) el.style.display = i === 0 ? 'block' : 'none';
  });
  document.getElementById('file-input').value = '';
  document.getElementById('import-entity').value = '';
  document.getElementById('file-info').style.display = 'none';
  document.getElementById('val-progress-bar').style.width = '0%';
}

function downloadTemplate() {
  const entity = document.getElementById('import-entity').value;
  if (!entity) { alert('Select an entity first.'); return; }
  TemplateGenerator.download(entity);
}

// ── Export UI ──
function onExportEntityChange() {
  const entity = document.getElementById('export-entity').value;
  if (!entity) return;
  document.getElementById('export-filters').style.display = 'block';

  const schema = SchemaRegistry.get(entity);
  const chips  = document.getElementById('export-chips');
  if (!schema) return;
  chips.innerHTML = schema.fields.map(f =>
    `<div class="chip selected" data-field="${f.name}" onclick="toggleChip(this)">${f.label}</div>`
  ).join('');

  StorageEngine.getAll(entity).then(data => {
    document.getElementById('export-preview-info').innerHTML =
      `<div class="alert alert-info" style="display:inline-flex;">ℹ️ &nbsp; <b>${data.length}</b> records available for ${schema.label}</div>`;
  });
}

document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('export-fields-mode').addEventListener('change', function() {
    const custom = document.getElementById('export-field-picker');
    custom.style.display = this.value === 'custom' ? 'block' : 'none';
  });
});

function toggleChip(el) { el.classList.toggle('selected'); }

async function runExport() {
  const entity = document.getElementById('export-entity').value;
  const format = document.getElementById('export-format').value;
  if (!entity) { alert('Select an entity first.'); return; }

  const mode = document.getElementById('export-fields-mode').value;
  let fields = null;
  if (mode === 'custom') {
    fields = [...document.getElementById('export-chips').querySelectorAll('.chip.selected')]
               .map(c => c.dataset.field);
    if (!fields.length) { alert('Select at least one field.'); return; }
  }

  let filterFn = null;
  const filterExpr = document.getElementById('export-filter-expr')?.value?.trim();
  if (filterExpr) {
    try {
      const filterObj = JSON.parse(filterExpr);
      filterFn = row => Object.entries(filterObj).every(([k,v]) => String(row[k]) === String(v));
    } catch(e) { alert('Invalid filter JSON: ' + e.message); return; }
  }

  const count = await ExportEngine.run(entity, format, fields, filterFn);
  if (format !== 'pdf') {
    document.getElementById('export-preview-info').innerHTML =
      `<div class="alert alert-success">✅ Exported <b>${count}</b> records as ${format.toUpperCase()}</div>`;
  }
}

async function previewExportData() {
  const entity = document.getElementById('export-entity').value;
  if (!entity) { alert('Select an entity first.'); return; }
  const data = await StorageEngine.getAll(entity);
  const card  = document.getElementById('export-preview-card');
  const table = document.getElementById('export-preview-table');
  const lbl   = document.getElementById('export-preview-lbl');

  card.style.display = 'block';
  const display = data.slice(0,30);
  lbl.textContent = `Showing ${display.length} of ${data.length} records`;

  if (!display.length) {
    table.innerHTML = '<div style="padding:20px;text-align:center;color:var(--muted);">No records found in storage for this entity.</div>';
    return;
  }
  const cols = Object.keys(display[0]);
  table.innerHTML = `<table>
    <thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead>
    <tbody>${display.map(r=>`<tr>${cols.map(c=>`<td class="td-mono">${r[c]??''}</td>`).join('')}</tr>`).join('')}</tbody>
  </table>`;
}

// ── Stats Page ──
async function renderStatsPage() {
  const log = AuditLogger.getLog();
  const imports = log.filter(e => e.type === 'IMPORT');
  const exports = log.filter(e => e.type === 'EXPORT');

  const totalImported = imports.reduce((s,e) => s + ((e.data||{}).imported||0), 0);
  const totalUpdated  = imports.reduce((s,e) => s + ((e.data||{}).updated||0), 0);
  const totalRejected = imports.reduce((s,e) => s + ((e.data||{}).rejected||0), 0);
  const totalExported = exports.reduce((s,e) => s + ((e.data||{}).count||0), 0);

  document.getElementById('global-stats').innerHTML = [
    [imports.length, 'Import Sessions',    '#1d4ed8'],
    [totalImported,  'Records Imported',   '#059669'],
    [totalUpdated,   'Records Updated',    '#2563eb'],
    [totalRejected,  'Records Rejected',   '#dc2626'],
    [exports.length, 'Export Sessions',    '#c9973a'],
    [totalExported,  'Records Exported',   '#c9973a'],
  ].map(([n,l,c]) => `<div class="stat-box" style="border-left-color:${c}">
    <div class="stat-num" style="color:${c};font-size:24px;">${n}</div>
    <div class="stat-lbl">${l}</div>
  </div>`).join('');

  // History table
  const tbody = document.getElementById('ops-history-body');
  if (!log.length) {
    tbody.innerHTML = '<tr><td colspan="10" style="text-align:center;color:var(--muted);padding:20px;">No operations recorded yet.</td></tr>';
  } else {
    tbody.innerHTML = log.slice(0,50).map(e => {
      const d = e.data || {};
      const badge = e.type === 'IMPORT' ? 'badge-blue' : e.type === 'EXPORT' ? 'badge-gold' : 'badge-red';
      return `<tr>
        <td class="td-mono" style="font-size:11px;">${e.ts ? new Date(e.ts).toLocaleString() : '—'}</td>
        <td><span class="badge ${badge}">${e.type}</span></td>
        <td>${d.entity||'—'}</td>
        <td>${(d.format||'').toUpperCase()||'—'}</td>
        <td>${d.total||d.count||'—'}</td>
        <td>${d.imported??'—'}</td>
        <td>${d.rejected??'—'}</td>
        <td>${d.updated??'—'}</td>
        <td>${d.skipped??'—'}</td>
        <td><span class="badge badge-green">Done</span></td>
      </tr>`;
    }).join('');
  }

  // Entity counts
  const entities = Object.keys(SchemaRegistry.getAll());
  const counts = await Promise.all(entities.map(async e => {
    const schema = SchemaRegistry.get(e);
    const data = await StorageEngine.getAll(e);
    return {label: schema.icon + ' ' + schema.label, count: data.length};
  }));
  document.getElementById('entity-counts').innerHTML = counts.map(({label,count}) =>
    `<div class="stat-box">
      <div class="stat-num" style="font-size:22px;">${count}</div>
      <div class="stat-lbl">${label}</div>
    </div>`
  ).join('');
}

