// ── Adapter Page ──
function onAdapterChange() {
  const val = document.getElementById('adapter-select').value;
  const extra = document.getElementById('adapter-config-extra');
  extra.style.display = val === 'restApi' ? 'block' : 'none';
}
function saveAdapterConfig() {
  const prefix = document.getElementById('adapter-prefix').value || (window.ERPCore.APP_NS + '.');
  localStorage.setItem('ie_adapter_prefix', prefix);
  const indicator = document.getElementById('storage-indicator');
  if (indicator) indicator.textContent = 'LocalStorage (prefix: ' + prefix + ')';
  StorageEngine.setPrefix(prefix);
  refreshLsInspector();
  alert('✅ Adapter config saved.');
}
function refreshLsInspector() {
  const el = document.getElementById('ls-inspector');
  if (!el) return;
  const prefix = document.getElementById('adapter-prefix')?.value || (window.ERPCore.APP_NS + '.');
  const rows = [];
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    if (k.startsWith(prefix) || k.startsWith('ie_')) {
      const v = localStorage.getItem(k);
      let count = '—';
      try { const parsed = JSON.parse(v); count = Array.isArray(parsed) ? parsed.length + ' records' : '1 object'; } catch{}
      rows.push({key:k, count, bytes: v.length + ' B'});
    }
  }
  if (!rows.length) {
    el.innerHTML = '<div style="color:var(--muted);font-size:13px;">No ERP data found in localStorage yet. Import or load sample data first.</div>';
    return;
  }
  el.innerHTML = `<div class="table-wrap"><table>
    <thead><tr><th>Key</th><th>Records</th><th>Size</th></tr></thead>
    <tbody>${rows.map(r => `<tr><td class="td-mono">${r.key}</td><td>${r.count}</td><td class="td-mono">${r.bytes}</td></tr>`).join('')}</tbody>
  </table></div>`;
}

