document.addEventListener('DOMContentLoaded', () => {
  AuditLogger.updateAuditBadge();
  tickClock();
  setInterval(tickClock, 1000);
  goStep(0);

  // Click outside modal to close
  document.querySelectorAll('.ie-modal-bg').forEach(bg => {
    bg.addEventListener('click', e => {
      if (e.target === bg) bg.classList.remove('open');
    });
  });

  // Seed demo data hint
  const students = localStorage.getItem(window.ERPCore.APP_NS + '.students');
  if (!students || students === '[]') {
    AuditLogger.log('SYSTEM', {msg: 'Engine initialized. No ERP data found. Use Import or Load Sample Data.'});
  }

  // Wire audit search
  const auditSearch = document.getElementById('audit-search-input');
  if (auditSearch) {
    auditSearch.addEventListener('input', function() {
      const q = this.value.toLowerCase();
      const log = AuditLogger.getLog().filter(e => JSON.stringify(e).toLowerCase().includes(q));
      AuditLogger.renderList(document.getElementById('audit-log-list'), log);
    });
  }
  const auditTypeFilter = document.getElementById('audit-type-filter');
  if (auditTypeFilter) {
    auditTypeFilter.addEventListener('change', function() {
      const t = this.value;
      const log = t ? AuditLogger.getLog().filter(e => e.type === t) : AuditLogger.getLog();
      AuditLogger.renderList(document.getElementById('audit-log-list'), log);
    });
  }
});

/* =====================================================================
   CONTINUATION BLOCK — Column Mapper, Seeder, Batch Export,
   Relationship Audit, Health Check, Bundle Import/Export
===================================================================== */

/* ── COLUMN MAPPING ENGINE ── */
const ColumnMapper = (() => {
  const aliases = {
    admno:['adm_no','adm no','admission_number','admission no','rollno','id'],
    name:['full_name','fullname','student_name','pupil name','sname'],
    cls:['class','std','standard','grade','class_name'],
    div:['division','section','batch'],
    roll:['roll','roll_no'],
    dob:['date_of_birth','birth_date','birthdate','born'],
    gender:['sex'],
    phone:['mobile','mobile_no','contact','contact_no','cell'],
    email:['email_address','mail','e-mail'],
    address:['addr','location','residence'],
    admdate:['admission_date','joining_date','join_date'],
    mother:['mother_name','mname'],
    father:['father_name','fname','parent'],
    fphone:['father_phone','parent_phone','parent_mobile'],
    feePlan:['fee_plan','plan','payment_plan'],
    concession:['discount','conc'],
    transportRequired:['transport','bus','needs_transport'],
    transportRoute:['route','bus_route'],
    status:['active','is_active','state'],
    empid:['emp_id','employee_id','staff_id','teacher_id'],
    subject:['subjects','dept','department'],
    doj:['date_of_joining','joining_date'],
    salary:['pay','ctc','wages'],
    appldate:['apply_date','application_date'],
    studentId:['student_id','stud_id','adm_no','admno'],
    payable:['total_fee','total','fee_payable','annual_fee'],
    paid:['amount_paid','fee_paid','payment'],
    balance:['due','pending','remaining'],
    paydate:['payment_date','pay_date'],
    mode:['payment_mode','payment_method'],
    rcpt:['receipt','receipt_no'],
    route:['bus_route','transport_route','stop'],
    annualFee:['annual_transport_fee','transport_annual'],
    qty:['quantity','stock','units','count'],
    price:['rate','cost','unit_price','mrp'],
    supplier:['vendor','company','brand'],
    expiry:['expiry_date','expire','expiration'],
    examName:['exam','examination','test_name'],
    marks:['score','obtained','marks_obtained'],
    maxMarks:['total_marks','out_of','maximum'],
    grade:['result','performance'],
    date:['exam_date','test_date'],
    to:['recipient','to_number','to_email'],
    from:['sender','from_number'],
    body:['message','content','text','sms'],
    sentAt:['sent_at','sent_on','timestamp'],
    channel:['type','via','platform'],
    username:['user','login','userid'],
    role:['user_role','access','permission'],
    key:['setting_key','config_key','param'],
    value:['setting_value','config_value','val'],
    group:['category','section','module'],
  };

  function autoMap(fileHeaders, schemaFields) {
    const mapping = {};
    const used    = new Set();
    const lc = h => h.toLowerCase().replace(/[\s_\-]/g,'');
    schemaFields.forEach(field => {
      const exact = fileHeaders.find(h => lc(h) === lc(field));
      if (exact && !used.has(exact)) { mapping[field] = exact; used.add(exact); return; }
      const myAliases = (aliases[field] || []).map(lc);
      const aliasMatch = fileHeaders.find(h => myAliases.includes(lc(h)) && !used.has(h));
      if (aliasMatch) { mapping[field] = aliasMatch; used.add(aliasMatch); return; }
      const partial = fileHeaders.find(h => !used.has(h) && (lc(h).includes(lc(field)) || lc(field).includes(lc(h))));
      if (partial) { mapping[field] = partial; used.add(partial); }
    });
    return mapping;
  }

  function applyMapping(rows, mapping) {
    return rows.map(row => {
      const out = {};
      Object.entries(mapping).forEach(([sf, fh]) => { if (fh) out[sf] = row[fh] ?? ''; });
      return out;
    });
  }

  function showMappingUI(fileHeaders, entity, onConfirm) {
    const schema = SchemaRegistry.get(entity);
    if (!schema) { onConfirm(null); return; }
    const fields        = schema.fields.map(f => f.name);
    const autoMapping   = autoMap(fileHeaders, fields);
    const requiredFields= schema.fields.filter(f => f.required).map(f => f.name);
    const unmappedCount = fields.filter(f => !autoMapping[f]).length;

    // If everything mapped cleanly, skip the UI
    if (requiredFields.every(f => autoMapping[f]) && unmappedCount === 0) {
      onConfirm(autoMapping); return;
    }

    const modal = document.getElementById('modal-mapping');
    const body  = document.getElementById('modal-mapping-body');
    body.innerHTML = `
      <div class="alert alert-warn" style="margin-bottom:12px;">
        ⚠ <b>${unmappedCount}</b> column(s) could not be auto-matched.
        Map your file headers to schema fields below.
      </div>
      <div class="table-wrap"><table>
        <thead><tr><th>Schema Field</th><th>Type</th><th>Required</th><th>Map to File Column</th><th>Sample Value</th></tr></thead>
        <tbody>
          ${schema.fields.map(f => {
            const mapped = autoMapping[f.name] || '';
            const opts = ['(skip)', ...fileHeaders]
              .map(h => `<option value="${h}" ${h === mapped ? 'selected' : ''}>${h || '(skip)'}</option>`)
              .join('');
            return `<tr>
              <td><code>${f.name}</code></td>
              <td style="font-size:11px;color:var(--muted)">${f.type}</td>
              <td>${f.required ? '<span class="badge badge-red">Required</span>' : '<span style="opacity:.4;font-size:11px;">optional</span>'}</td>
              <td><select class="mapping-sel" data-field="${f.name}"
                    onchange="updateMappingPreview('${f.name}',this.value)"
                    style="width:100%;padding:6px;border:1.5px solid #ddd;border-radius:5px;font-size:12px;">${opts}</select></td>
              <td id="map-preview-${f.name}" style="font-size:11px;color:var(--muted);font-family:monospace;">—</td>
            </tr>`;
          }).join('')}
        </tbody>
      </table></div>`;

    window._mappingRows = ImportOrchestrator.getState().rawRows;
    schema.fields.forEach(f => { if (autoMapping[f.name]) updateMappingPreview(f.name, autoMapping[f.name]); });

    document.getElementById('modal-mapping-confirm').onclick = () => {
      const finalMapping = {};
      document.querySelectorAll('#ie-root .mapping-sel').forEach(sel => {
        if (sel.value && sel.value !== '(skip)') finalMapping[sel.dataset.field] = sel.value;
      });
      const missing = requiredFields.filter(f => !finalMapping[f]);
      if (missing.length) { alert('Required fields not mapped: ' + missing.join(', ')); return; }
      ieCloseModal('modal-mapping');
      onConfirm(finalMapping);
    };
    ieOpenModal('modal-mapping');
  }

  return { autoMap, applyMapping, showMappingUI };
})();

function updateMappingPreview(field, header) {
  const el = document.getElementById('map-preview-' + field);
  if (!el) return;
  const rows = window._mappingRows || [];
  const sample = rows[0] ? (rows[0][header] ?? '—') : '—';
  el.textContent = String(sample).slice(0, 28);
  el.title = String(sample);
}

/* ── Override processFile to include column mapping ── */
window.processFile = async function processFile(file) {
  const entity = document.getElementById('import-entity').value;
  if (!entity) { showInfo('file-info','error','⚠ Please select an entity type first.'); return; }
  if (file.size > 10*1024*1024) { showInfo('file-info','error','⚠ File too large. Max 10 MB.'); return; }
  showInfo('file-info','info', `📄 <b>${file.name}</b> — ${(file.size/1024).toFixed(1)} KB — Parsing…`);
  try {
    const result = await ImportOrchestrator.loadFile(file);
    showInfo('file-info','success', `✅ Parsed <b>${result.rows.length} rows</b> from <b>${file.name}</b> (${result.format})`);
    if (!result.rows.length) { showInfo('file-info','error','❌ File contains no data rows.'); return; }
    const fileHeaders = Object.keys(result.rows[0]);
    ColumnMapper.showMappingUI(fileHeaders, entity, async (mapping) => {
      if (!mapping) { showInfo('file-info','error','❌ Column mapping cancelled.'); return; }
      ImportOrchestrator.getState().rawRows = ColumnMapper.applyMapping(result.rows, mapping);
      showInfo('file-info','success', `✅ Mapped ${ImportOrchestrator.getState().rawRows.length} rows. Validating…`);
      setTimeout(runValidation, 200);
    });
  } catch(e) {
    showInfo('file-info','error', '❌ Parse error: ' + e.message);
  }
};

