function ssGoTo(page, el) {
  if (state.hasChanges) {
    if (!confirm('You have unsaved changes. Leave this section without saving?')) return;
    state.hasChanges = false;
    document.getElementById('unsaved-indicator').style.display = 'none';
  }
  document.querySelectorAll('#ss-root .page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('#ss-root .sb-item').forEach(s => s.classList.remove('active'));
  // 'dashboard' and 'inventory' collide with the main ERP's own #page-dashboard /
  // #page-inventory, so this engine's copies were given distinct infra-pg-* ids.
  // 'communication' collided with the main ERP's real SMS & WhatsApp Communication
  // Center (#page-communication) — that module was silently unreachable from the
  // main sidebar because getElementById('page-communication') always resolved to
  // THIS settings placeholder instead. Given its own id so both pages work.
  const SS_ID_OVERRIDES = { dashboard: 'infra-pg-dashboard', inventory: 'infra-pg-inventory', communication: 'page-communication-settings' };
  const pageEl = document.getElementById(SS_ID_OVERRIDES[page] || ('page-' + page));
  if (pageEl) pageEl.classList.add('active');
  if (el) el.classList.add('active');
  else {
    const sbEl = document.querySelector(`[data-page="${page}"]`);
    if (sbEl) sbEl.classList.add('active');
  }
  // Re-hydrate this section's fields from whatever was last saved via
  // saveSection(). Previously saveSection() persisted correctly but nothing
  // ever read it back on page view, so a saved section looked reset to
  // defaults every time you left and returned (or reloaded) — the "changes
  // aren't really saved" symptom. Same id-matching logic as resetSection().
  if (pageEl) {
    const savedForPage = SettingsStore.get(page);
    if (savedForPage) {
      Object.keys(savedForPage).forEach(id => {
        const fieldEl = pageEl.querySelector('#' + id);
        if (!fieldEl) return;
        if (fieldEl.type === 'checkbox') fieldEl.checked = savedForPage[id];
        else fieldEl.value = savedForPage[id];
      });
    }
  }
  state.currentPage = page;
  const [title, breadcrumb] = TITLES[page] || ['Settings','Settings'];
  document.getElementById('ss-topbar-title').textContent = title;
  document.getElementById('ss-topbar-breadcrumb').textContent = breadcrumb;
  // Scroll to top
  document.getElementById('ss-content').scrollTop = 0;
  // Page-specific renders
  if (page === 'audit-settings') ssRenderAuditLog();
  if (page === 'permissions') renderPermissions();
  if (page.startsWith('search-')) srchRenderPage(page);
  if (page === 'attendance' && typeof attP2Init === 'function') attP2Init();
  if (page === 'attendance' && typeof attMarkInit === 'function') attMarkInit();
  if (page === 'attendance' && typeof attRptInit === 'function') attRptInit();
}
// Bridge used by the unified sidebar (Infrastructure Master's navigate())
// to drive this engine's internal page switching.
window.SettingsSearchBridge = {
  showPage: (page) => ssGoTo(page, null)
};

