function togglePerm(el) {
  const seq = ['✅','👁','—'];
  const idx = seq.indexOf(el.textContent);
  el.textContent = seq[(idx+1)%3];
  const colors = {'✅':'#15803D','👁':'#2563EB','—':'#d1d5db'};
  el.style.color = colors[el.textContent];
  markChanged();
}

// ═══════════════════════════════════════════
//  CHANGE TRACKING
// ═══════════════════════════════════════════
function markChanged() {
  state.hasChanges = true;
  document.getElementById('unsaved-indicator').style.display = 'inline';
}

function saveSection() {
  // Collect all inputs in current page
  const page = document.getElementById('page-' + state.currentPage);
  if (!page) return;
  const data = {};
  page.querySelectorAll('input,select,textarea').forEach(el => {
    if (el.id) data[el.id] = el.type === 'checkbox' ? el.checked : el.value;
  });
  SettingsStore.set(state.currentPage, data);
  state.hasChanges = false;
  document.getElementById('unsaved-indicator').style.display = 'none';
  ssShowToast(`${TITLES[state.currentPage]?.[0] || 'Settings'} saved successfully ✅`, 'success');
  // Add to audit
  SAMPLE_AUDIT.unshift({ ts: new Date().toLocaleString('en-IN').replace(',',''), user:'principal', module: TITLES[state.currentPage]?.[0]||'Settings', action:'UPDATE', detail:'Section settings saved', ip:'127.0.0.1' });
  if (window.ERPCore && window.ERPCore.AuditLog) {
    window.ERPCore.AuditLog.log('Settings: Section Saved', `${TITLES[state.currentPage]?.[0] || state.currentPage} settings updated`, 'ok');
  }
}

function resetSection() {
  if (!confirm('Reset this section to last saved values?')) return;
  const saved = SettingsStore.get(state.currentPage);
  if (saved) {
    const page = document.getElementById('page-' + state.currentPage);
    Object.keys(saved).forEach(id => {
      const el = page.querySelector('#'+id);
      if (!el) return;
      if (el.type === 'checkbox') el.checked = saved[id];
      else el.value = saved[id];
    });
  }
  state.hasChanges = false;
  document.getElementById('unsaved-indicator').style.display = 'none';
  ssShowToast('Reset to last saved values', '');
}

