// ═══════════════════════════════════════════
function ssShowToast(msg, type='') {
  const t = document.getElementById('ss-toast');
  t.textContent = msg;
  t.style.borderLeftColor = type==='success' ? 'var(--success)' : type==='danger' ? 'var(--danger)' : 'var(--accent)';
  t.style.display = 'block';
  clearTimeout(window._ssToastTimer);
  window._ssToastTimer = setTimeout(() => t.style.display='none', 3000);
}

