function confirmRestore() {
  if (confirm('⚠️ DANGER: This will overwrite ALL current data with the backup file.\n\nAre you absolutely sure you want to continue?')) {
    ssShowToast('Restore cancelled — create a backup file first', 'danger');
  }
}

function exportSettings() {
  const all = {};
  Object.keys(TITLES).forEach(k => { const v = SettingsStore.get(k); if (v) all[k] = v; });
  const blob = new Blob([JSON.stringify(all, null, 2)], {type:'application/json'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
  a.download = 'erp_settings_export_' + new Date().toISOString().slice(0,10) + '.json';
  a.click();
  ssShowToast('Settings exported to JSON', 'success');
  if (window.ERPCore && window.ERPCore.AuditLog) {
    window.ERPCore.AuditLog.log('Settings: Exported', `${Object.keys(all).length} setting group(s) exported to JSON`, 'info');
  }
}

function importSettings() {
  const input = document.createElement('input'); input.type = 'file'; input.accept = '.json';
  input.onchange = e => {
    const file = e.target.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const data = JSON.parse(ev.target.result);
        Object.keys(data).forEach(k => SettingsStore.set(k, data[k]));
        ssShowToast('Settings imported successfully', 'success');
        if (window.ERPCore && window.ERPCore.AuditLog) {
          window.ERPCore.AuditLog.log('Settings: Imported', `${Object.keys(data).length} setting group(s) imported from ${file.name}`, 'warn');
        }
      } catch(e) { ssShowToast('Invalid settings file', 'danger'); }
    };
    reader.readAsText(file);
  };
  input.click();
}

