function srchPick(arr){ return arr[Math.floor(Math.random()*arr.length)]; }
function srchFullName(){ return srchPick(SRCH_FIRST)+" "+srchPick(SRCH_LAST); }
function srchPad(n,len){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchPad(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchPad(n, len);
  }
  return String(n).padStart(len,"0");
}
function srchRandInt(a,b){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchRandInt(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchRandInt(a, b);
  }
  return a + Math.floor(Math.random()*(b-a+1));
}
function srchRandDate(daysBack){ const d=new Date(); d.setDate(d.getDate()-srchRandInt(0,daysBack)); return d.toISOString().slice(0,10); }
function srchFuzzyDate(daysRange){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchFuzzyDate(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchFuzzyDate(daysRange);
  }
  const d=new Date(); d.setDate(d.getDate()+srchRandInt(-daysRange,daysRange)); return d.toISOString().slice(0,10);
}

