/* ---------------- LIVE SETTINGS INDEX ----------------
   Global Search must search all Settings: this walks every
   .page in the DOM (all 26 settings sections) and indexes their
   field labels, card titles and toggle labels — not just page
   names — so a query like "SMS Gateway" or "Late Fee" finds the
   exact setting and jumps straight to its page.
------------------------------------------------------------- */
let SRCH_SETTINGS_RECORDS = [];
function srchBuildSettingsIndex(){
  SRCH_SETTINGS_RECORDS = [];
  document.querySelectorAll('#ss-root .page').forEach(pageEl=>{
    const pageKey = pageEl.id.replace(/^page-/,'');
    if(pageKey.startsWith('search-')) return; // don't index the search tool's own pages
    const titleInfo = TITLES[pageKey] || [pageKey, pageKey];
    const seen = new Set();
    const labelNodes = pageEl.querySelectorAll('.form-label, .toggle-label, .card-title, .section-hero-title, .section-hero-desc');
    labelNodes.forEach(node=>{
      const text = node.textContent.trim();
      if(!text || text.length<3) return;
      const dedupeKey = pageKey+"::"+text.toLowerCase();
      if(seen.has(dedupeKey)) return;
      seen.add(dedupeKey);
      SRCH_SETTINGS_RECORDS.push({
        id: "SET-" + srchPad(SRCH_SETTINGS_RECORDS.length+1, 3),
        settingName: text,
        page: pageKey,
        pageTitle: titleInfo[0],
        status: "Configured",
      });
    });
    // Always add a page-level record too, so searching the section name works even with no fields matched.
    SRCH_SETTINGS_RECORDS.push({
      id: "SET-PAGE-" + pageKey, settingName: titleInfo[0], page: pageKey, pageTitle: titleInfo[0], status:"Section",
    });
  });
}

/* ---------------- SEARCH INDEX / TOKENIZE / SCORE ---------------- */
let SRCH_INDEX_BUILT_AT = null;
function srchTokenize(str){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchTokenize(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchTokenize(str);
  }
  return String(str||"").toLowerCase().match(/[a-z0-9]+/g) || [];
}
function srchBuildBlobs(){
  SRCH_MODULES.forEach(mod=>{
    (SRCH_RECORDS[mod.key]||[]).forEach(rec=>{
      rec._blob = (mod.fields.map(f=>rec[f]).join(" ") + " " + rec.id).toLowerCase();
    });
  });
  SRCH_SETTINGS_RECORDS.forEach(rec=>{
    rec._blob = (rec.settingName + " " + rec.pageTitle + " " + rec.id).toLowerCase();
  });
}
function srchBuildIndex(){
  srchBuildSettingsIndex();
  srchBuildBlobs();
  SRCH_INDEX_BUILT_AT = new Date();
  srchUpdateIndexBadge();
}
function srchLevenshtein(a,b,max){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchLevenshtein(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchLevenshtein(a, b, max);
  }
  max = max || 3;
  if(Math.abs(a.length-b.length) > max) return max+1;
  const dp = [];
  for(let i=0;i<=a.length;i++) dp.push([i]);
  for(let j=0;j<=b.length;j++) dp[0][j]=j;
  for(let i=1;i<=a.length;i++){
    for(let j=1;j<=b.length;j++){
      dp[i][j] = a[i-1]===b[j-1] ? dp[i-1][j-1] : 1 + Math.min(dp[i-1][j-1], dp[i-1][j], dp[i][j-1]);
    }
  }
  return dp[a.length][b.length];
}
function srchScoreRecord(rec, queryTokens, fuzzy){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchScoreRecord(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchScoreRecord(rec, queryTokens, fuzzy);
  }
  let score = 0;
  const words = (rec._blob||"").split(/[^a-z0-9]+/);
  queryTokens.forEach(qt=>{
    if(!qt) return;
    let best = 0;
    words.forEach(w=>{
      if(!w) return;
      if(w===qt) best = Math.max(best,3);
      else if(w.startsWith(qt)) best = Math.max(best,2.2);
      else if(w.includes(qt)) best = Math.max(best,1.4);
      else if(fuzzy && qt.length>=3){
        const d = srchLevenshtein(w, qt, SRCH_CONFIG.fuzzyTolerance);
        if(d<=SRCH_CONFIG.fuzzyTolerance) best = Math.max(best, 1.6 - d*0.3);
      }
    });
    score += best;
  });
  return score;
}
function srchGetTitle(rec, sourceKey){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchGetTitle(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchGetTitle(rec, sourceKey);
  }
  if(sourceKey==="settings") return rec.settingName;
  return rec[SRCH_MODULE_MAP[sourceKey].titleField] || rec.id;
}
function srchGetDate(rec){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchGetDate(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchGetDate(rec);
  }
  return rec.date || rec.admissionDate || rec.joinDate || rec.appliedDate || rec.issueDate || rec.timestamp || rec.lastLogin || "";
}

/* Future-SettingsStore-ready adapter: swap the body for a real fetch()/cloud
   search call. Everything else (UI, state, persistence) is unaffected. */
function srchQuerySource(sourceKey){
  // [PHASE-25B] Logic moved to Dnyanankur.Services.Search.srchQuerySource(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchQuerySource(sourceKey);
  }
  if(SRCH_CONFIG.indexMode === "cloud" && SRCH_CONFIG.cloudEndpoint){
    // return fetch(SRCH_CONFIG.cloudEndpoint + "/" + sourceKey).then(r=>r.json());
  }
  if(sourceKey === "documents"){
    // Real data (not mock) - reads live from the Document Management Engine.
    if(!window.DocumentsBridge || typeof window.DocumentsBridge.getDocuments !== "function") return [];
    return window.DocumentsBridge.getDocuments().map(d=>{
      const rec = {
        id: d.id, title: d.title, category: d.category, status: d.status,
        uploadedDate: d.uploadedDate ? new Date(d.uploadedDate).toISOString().slice(0,10) : "",
        date: d.uploadedDate ? new Date(d.uploadedDate).toISOString().slice(0,10) : "",
      };
      rec._blob = [rec.title, rec.category, rec.status, rec.id].join(" ").toLowerCase();
      return rec;
    });
  }
  return sourceKey === "settings" ? SRCH_SETTINGS_RECORDS : (SRCH_RECORDS[sourceKey]||[]);
}

function srchRunSearch(query, opts){
  // [PHASE-25B] Logic moved to Dnyanankur.Services.Search.srchRunSearch(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchRunSearch(query, opts);
  }
  opts = opts || {};
  const sources = (opts.sources && opts.sources.length) ? opts.sources : srchAllSourceKeys();
  const fuzzy = opts.fuzzy !== undefined ? opts.fuzzy : SRCH_CONFIG.fuzzy;
  const statusFilter = opts.status || "";
  const dateFrom = opts.dateFrom || "";
  const dateTo = opts.dateTo || "";
  const conditions = opts.conditions || [];
  const sortBy = opts.sortBy || "relevance";
  const qTokens = srchTokenize(query);
  const start = performance.now();

  return new Promise(resolve=>{
    setTimeout(()=>{
      let results = [];
      sources.forEach(src=>{
        srchQuerySource(src).forEach(rec=>{
          if(statusFilter && rec.status !== statusFilter) return;
          const dv = srchGetDate(rec);
          if(dateFrom && dv && dv < dateFrom) return;
          if(dateTo && dv && dv > dateTo) return;
          if(conditions.length){
            const ok = conditions.every(c=>{
              const val = String(rec[c.field]||"").toLowerCase();
              const target = String(c.value||"").toLowerCase();
              if(!target) return true;
              if(c.operator==="equals") return val===target;
              if(c.operator==="starts") return val.startsWith(target);
              if(c.operator==="not") return !val.includes(target);
              return val.includes(target);
            });
            if(!ok) return;
          }
          let score = 1;
          if(qTokens.length){
            score = srchScoreRecord(rec, qTokens, fuzzy);
            if(score<=0) return;
          }
          results.push({ source:src, record:rec, score });
        });
      });
      if(sortBy==="relevance") results.sort((a,b)=>b.score-a.score);
      else if(sortBy==="date-desc") results.sort((a,b)=> String(srchGetDate(b.record)).localeCompare(String(srchGetDate(a.record))));
      else if(sortBy==="date-asc") results.sort((a,b)=> String(srchGetDate(a.record)).localeCompare(String(srchGetDate(b.record))));
      else if(sortBy==="az") results.sort((a,b)=> srchGetTitle(a.record,a.source).localeCompare(srchGetTitle(b.record,b.source)));

      const duration = Math.round(performance.now()-start);
      const sourceCounts = {};
      results.forEach(r=> sourceCounts[r.source] = (sourceCounts[r.source]||0)+1);
      resolve({ query, results, duration, sourceCounts });
    }, SRCH_CONFIG.simulatedLatencyMs);
  });
}

function srchGetSuggestions(prefix, limit){
  // [PHASE-25B] Logic moved to Dnyanankur.Services.Search.srchGetSuggestions(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchGetSuggestions(prefix, limit);
  }
  limit = limit || 8;
  prefix = prefix.toLowerCase().trim();
  if(!prefix) return [];
  const out = [];
  SRCH_MODULES.forEach(m=>{ if(m.label.toLowerCase().includes(prefix)) out.push({ type:"module", label:m.label, value:m.label, source:m.key }); });
  if(SRCH_SETTINGS_META.label.toLowerCase().includes(prefix)) out.push({ type:"module", label:"Settings", value:"Settings", source:"settings" });
  const seen = new Set();
  SRCH_SETTINGS_RECORDS.forEach(rec=>{
    if(out.length>=limit*2) return;
    const t = rec.settingName.toLowerCase();
    if(t.startsWith(prefix) && !seen.has(t)){ seen.add(t); out.push({ type:"setting", label:rec.settingName, value:rec.settingName, source:"settings", page:rec.page }); }
  });
  SRCH_MODULES.forEach(m=>{
    srchQuerySource(m.key).slice(0,50).forEach(rec=>{
      if(out.length>=limit*3) return;
      const title = srchGetTitle(rec, m.key).toLowerCase();
      if(title.startsWith(prefix) && !seen.has(title)){ seen.add(title); out.push({ type:"record", label:srchGetTitle(rec,m.key), value:srchGetTitle(rec,m.key), source:m.key }); }
    });
  });
  return out.slice(0, limit);
}

/* ---------------- STATE + PERSISTENCE (reuses the host SettingsStore adapter) ---------------- */
state.search = {
  selectedSources: new Set(srchAllSourceKeys()),
  saved: SettingsStore.get('search_saved') || [],
  recent: SettingsStore.get('search_recent') || [],
  favs: SettingsStore.get('search_favs') || [],
  history: SettingsStore.get('search_history') || [],
  presets: SettingsStore.get('search_presets') || [
    { id:"p1", name:"Overdue Fee Payments", source:"finance", status:"Overdue" },
    { id:"p2", name:"Pending Admissions", source:"admissions", status:"Pending" },
    { id:"p3", name:"Low Stock Items", source:"inventory", status:"Low Stock" },
  ],
  lastUniversal: null,
  lastAdvanced: null,
  uniPage: 1,
  advPage: 1,
  saveContext: "universal",
};

function srchPersist(key){
  // [PHASE-25B] Logic moved to Dnyanankur.Services.Search.srchPersist(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchPersist(key);
  }
  SettingsStore.set('search_'+key, state.search[key]);
}
function srchUid(){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchUid(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchUid();
  }
  return "s"+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
}
function srchEsc(s){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchEsc(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchEsc(s);
  }
  return String(s==null?"":s).replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}
function srchHighlight(text, tokens){
  text = srchEsc(text);
  if(!tokens || !tokens.length) return text;
  let out = text;
  tokens.forEach(t=>{ if(!t||t.length<2) return; const re = new RegExp("("+t.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")","ig"); out = out.replace(re, "<mark>$1</mark>"); });
  return out;
}
function srchFmtDateTime(iso){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchFmtDateTime(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchFmtDateTime(iso);
  }
  try{ const d=new Date(iso); return fmtDMYTime(d); }catch(e){ return iso; }
}
function srchTimeAgo(iso){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchTimeAgo(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchTimeAgo(iso);
  }
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.round(diff/60000);
  if(m<1) return "just now";
  if(m<60) return m+"m ago";
  const h = Math.round(m/60);
  if(h<24) return h+"h ago";
  return Math.round(h/24)+"d ago";
}
function srchDebounce(fn, ms){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchDebounce(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchDebounce(fn, ms);
  }
  let t; return function(...a){ clearTimeout(t); t=setTimeout(()=>fn.apply(this,a), ms); };
}
function srchStatusBadgeClass(status){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchStatusBadgeClass(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchStatusBadgeClass(status);
  }
  const good=["Active","Present","Paid","Completed","Approved","Issued","Sent","In Stock","Success","Configured","Section","Alumni"];
  const warn=["Pending","Low Stock","Scheduled","Draft","Waitlisted","On Leave","Late","Maintenance","Warning","Invited"];
  const bad=["Inactive","Absent","Overdue","Cancelled","Rejected","Revoked","Suspended","Failed","Out of Stock","Resigned","Excused"];
  if(good.includes(status)) return "badge-green";
  if(warn.includes(status)) return "badge-gold";
  if(bad.includes(status)) return "badge-red";
  return "badge-gray";
}
function srchSourceMeta(key){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchSourceMeta(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchSourceMeta(key);
  }
  return key==="settings" ? SRCH_SETTINGS_META : SRCH_MODULE_MAP[key];
}
function srchTotalRecords(){ return SRCH_MODULES.reduce((s,m)=>s+(SRCH_RECORDS[m.key]||[]).length,0) + SRCH_SETTINGS_RECORDS.length; }

function srchLogSearch(query, sources, resultCount, duration, source){
  // [PHASE-25B] Logic moved to Dnyanankur.Services.Search.srchLogSearch(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchLogSearch(query, sources, resultCount, duration, source);
  }
  const entry = { id:srchUid(), query: query && query.trim() ? query : "(all records)", sources: sources.slice(), resultCount, duration, timestamp:new Date().toISOString(), source: source||"universal" };
  state.search.history.unshift(entry);
  if(state.search.history.length>250) state.search.history.length = 250;
  srchPersist('history');
  if(query && query.trim()){
    state.search.recent = state.search.recent.filter(r=>r.query.toLowerCase()!==query.toLowerCase());
    state.search.recent.unshift({ id:srchUid(), query, sources: sources.slice(), timestamp:new Date().toISOString(), resultCount });
    if(state.search.recent.length>20) state.search.recent.length = 20;
    srchPersist('recent');
  }
  srchUpdateSidebarBadges();
}

/* ---------------- GLOBAL SEARCH BOX (sidebar) ---------------- */
function srchUpdateIndexBadge(){
  const el = document.getElementById('srch-index-badge');
  if(el) el.textContent = (SRCH_CONFIG.indexMode==="cloud"?"Cloud Search":"Local Index") + " · " + srchTotalRecords() + " records";
}
function srchUpdateSidebarBadges(){
  const savedBadge = document.getElementById('sb-count-saved');
  if(savedBadge){
    if(state.search.saved.length){ savedBadge.style.display=''; savedBadge.textContent = state.search.saved.length; }
    else savedBadge.style.display = 'none';
  }
}
let srchSuggestHl = -1;
function srchOnGlobalInput(v){ srchDebouncedSidebarSuggest(v); }
const srchDebouncedSidebarSuggest = srchDebounce((v)=>{
  const dd = document.getElementById('srch-suggest-dropdown');
  const list = srchGetSuggestions(v);
  if(!list.length){ dd.classList.remove('open'); dd.innerHTML=''; return; }
  srchSuggestHl = -1;
  dd.innerHTML = `<div class="srch-suggest-group">Suggestions</div>` + list.map((s,i)=>`
    <div class="srch-suggest-item" data-idx="${i}" data-value="${srchEsc(s.value)}" data-source="${s.source||''}" data-page="${s.page||''}">
      <span>${s.type==='module'?'◆':(s.type==='setting'?'⚙️':'🔎')}</span><span>${srchEsc(s.label)}</span>
      <span class="si-tag">${s.source ? (srchSourceMeta(s.source)?srchSourceMeta(s.source).label:'') : ''}</span>
    </div>`).join('');
  dd.classList.add('open');
  dd.querySelectorAll('.srch-suggest-item').forEach(item=>{
    item.addEventListener('click', ()=>{
      dd.classList.remove('open');
      const page = item.dataset.page;
      document.getElementById('sb-search-input').value = item.dataset.value;
      if(page){ ssGoTo(page, document.querySelector(`[data-page="${page}"]`)); }
      else { ssGoTo('search-universal', document.querySelector('[data-page="search-universal"]')); srchRunUniversal(item.dataset.value); }
    });
  });
}, 150);
function srchOnGlobalKeydown(e){
  const dd = document.getElementById('srch-suggest-dropdown');
  const items = Array.from(dd.querySelectorAll('.srch-suggest-item'));
  if(e.key==='ArrowDown'){ e.preventDefault(); srchSuggestHl = Math.min(items.length-1, srchSuggestHl+1); srchHlItems(items); }
  else if(e.key==='ArrowUp'){ e.preventDefault(); srchSuggestHl = Math.max(0, srchSuggestHl-1); srchHlItems(items); }
  else if(e.key==='Enter'){
    dd.classList.remove('open');
    const v = (srchSuggestHl>=0 && items[srchSuggestHl]) ? items[srchSuggestHl].dataset.value : e.target.value;
    ssGoTo('search-universal', document.querySelector('[data-page="search-universal"]'));
    srchRunUniversal(v);
  } else if(e.key==='Escape'){ dd.classList.remove('open'); }
}
function srchHlItems(items){ items.forEach((it,i)=>it.classList.toggle('hl', i===srchSuggestHl)); }
document.addEventListener('click', e=>{
  if(!e.target.closest('.sb-search')) document.getElementById('srch-suggest-dropdown').classList.remove('open');
});

/* ---------------- RENDER: RESULT CARDS ---------------- */
function srchRenderCard(item, tokens){
  const meta = srchSourceMeta(item.source);
  const rec = item.record;
  if(item.source === 'settings'){
    return `
    <div class="srch-card" style="--tab-color:${meta.color}">
      <div class="srch-tab"></div>
      <div class="srch-body">
        <div class="srch-top">
          <div>
            <span class="badge badge-gold" style="margin-bottom:6px;display:inline-block;">${meta.icon} Settings</span>
            <div class="srch-title">${srchHighlight(rec.settingName, tokens)}</div>
          </div>
          <div style="text-align:right;flex-shrink:0;">
            <div class="srch-id">${srchEsc(rec.id)}</div>
            <span class="badge ${srchStatusBadgeClass(rec.status)}" style="margin-top:6px;display:inline-block;">${srchEsc(rec.status)}</span>
          </div>
        </div>
        <div class="srch-fields">
          <span><b>Section</b>${srchHighlight(rec.pageTitle, tokens)}</span>
        </div>
        <div style="margin-top:10px;"><button class="btn btn-outline btn-sm" onclick="ssGoTo('${rec.page}', document.querySelector('[data-page=${rec.page}]'))">Open Section →</button></div>
      </div>
    </div>`;
  }
  const title = srchGetTitle(rec, item.source);
  const metaFields = meta.fields.filter(f=> f!==meta.titleField && f!=="status").slice(0,4);
  const metaHtml = metaFields.map(f=>{
    const label = f.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase());
    let val = rec[f];
    if(f==="amount") val = "₹"+Number(val).toLocaleString("en-IN");
    return `<span><b>${srchEsc(label)}</b>${srchHighlight(val, tokens)}</span>`;
  }).join('');
  return `
  <div class="srch-card" style="--tab-color:${meta.color}">
    <div class="srch-tab"></div>
    <div class="srch-body">
      <div class="srch-top">
        <div>
          <span class="badge badge-blue" style="margin-bottom:6px;display:inline-block;">${meta.icon} ${meta.label}</span>
          <div class="srch-title">${srchHighlight(title, tokens)}</div>
        </div>
        <div style="text-align:right;flex-shrink:0;">
          <div class="srch-id">${srchEsc(rec.id)}</div>
          <span class="badge ${srchStatusBadgeClass(rec.status)}" style="margin-top:6px;display:inline-block;">${srchEsc(rec.status||'')}</span>
        </div>
      </div>
      <div class="srch-fields">${metaHtml}</div>
    </div>
  </div>`;
}
function srchPaginated(arr, page){ return arr.slice(0, page*SRCH_CONFIG.resultsPerPage); }
function srchRenderResultsInto(containerId, metaId, bundle, page, onMore){
  const container = document.getElementById(containerId);
  const metaEl = document.getElementById(metaId);
  if(!bundle){ container.innerHTML=''; metaEl.style.display='none'; return; }
  const { query, res } = bundle;
  const tokens = srchTokenize(query);
  metaEl.style.display = 'flex';
  const chips = Object.entries(res.sourceCounts).map(([k,c])=>{
    const m = srchSourceMeta(k);
    return `<span class="srch-chip" style="color:${m.color};"><span class="dot"></span>${m.label} ${c}</span>`;
  }).join(' ');
  metaEl.innerHTML = `<div><span class="mono">${res.results.length}</span> results in <span class="mono">${res.duration}ms</span> · ${SRCH_CONFIG.indexMode==='cloud'?'cloud index':'local index'}</div><div style="display:flex;gap:6px;flex-wrap:wrap;">${chips}</div>`;
  if(!res.results.length){
    container.innerHTML = `<div class="srch-empty"><div class="em">∅</div>No records matched this search. Try a broader term or enable fuzzy matching.</div>`;
    return;
  }
  const slice = srchPaginated(res.results, page);
  let html = `<div class="srch-list">` + slice.map(it=>srchRenderCard(it, tokens)).join('') + `</div>`;
  if(slice.length < res.results.length){
    html += `<div style="text-align:center;margin-top:16px;"><button class="btn btn-outline btn-sm" id="${containerId}-more">Show More (${res.results.length - slice.length} remaining)</button></div>`;
  }
  container.innerHTML = html;
  const moreBtn = document.getElementById(containerId+"-more");
  if(moreBtn) moreBtn.addEventListener('click', onMore);
}

/* ---------------- UNIVERSAL SEARCH PAGE ---------------- */
function srchRenderModuleChips(){
  const el = document.getElementById('srch-module-chips');
  if(!el) return;
  const all = SRCH_MODULES.concat([SRCH_SETTINGS_META]);
  el.innerHTML = all.map(m=>{
    const on = state.search.selectedSources.has(m.key);
    return `<span class="srch-chip ${on?'':'off'}" style="color:${m.color};" data-src="${m.key}" onclick="srchToggleSource('${m.key}')"><span class="dot"></span>${m.label}</span>`;
  }).join('');
}
function srchToggleSource(key){
  if(state.search.selectedSources.has(key)) state.search.selectedSources.delete(key);
  else state.search.selectedSources.add(key);
  srchRenderModuleChips();
}
function srchToggleFuzzy(v){ SRCH_CONFIG.fuzzy = v; }
const srchDebouncedUniInput = srchDebounce((v)=>{ /* live-as-you-type is optional; Enter/blur triggers full run */ }, 200);
async function srchRunUniversal(query){
  document.getElementById('srch-uni-input').value = query;
  document.getElementById('sb-search-input').value = query;
  const sources = Array.from(state.search.selectedSources);
  const res = await srchRunSearch(query, { sources, fuzzy: SRCH_CONFIG.fuzzy });
  state.search.lastUniversal = { query, sources, res };
  state.search.uniPage = 1;
  srchRenderUniversal();
  srchLogSearch(query, sources, res.results.length, res.duration, "universal");
}
function srchRenderUniversal(){
  srchRenderModuleChips();
  srchRenderResultsInto('srch-uni-results','srch-uni-meta', state.search.lastUniversal, state.search.uniPage, ()=>{ state.search.uniPage++; srchRenderUniversal(); });
}

/* ---------------- ADVANCED SEARCH PAGE ---------------- */
function srchPopulateAdvSelectors(){
  const modSel = document.getElementById('srch-adv-module');
  modSel.innerHTML = `<option value="">All Sources</option><option value="settings">⚙️ Settings</option>` + SRCH_MODULES.map(m=>`<option value="${m.key}">${m.icon} ${m.label}</option>`).join('');
  srchOnAdvModuleChange();
  const repSel = document.getElementById('srch-rep-module');
  if(repSel) repSel.innerHTML = `<option value="">All Sources</option><option value="settings">Settings</option>` + SRCH_MODULES.map(m=>`<option value="${m.key}">${m.label}</option>`).join('');
}
function srchOnAdvModuleChange(){
  const key = document.getElementById('srch-adv-module').value;
  const statusSel = document.getElementById('srch-adv-status');
  let statuses = [];
  if(key === 'settings') statuses = ["Configured","Section"];
  else if(key) statuses = SRCH_MODULE_MAP[key].statuses;
  else { const set = new Set(); SRCH_MODULES.forEach(m=>m.statuses.forEach(s=>set.add(s))); statuses = Array.from(set); }
  statusSel.innerHTML = `<option value="">Any</option>` + statuses.map(s=>`<option value="${s}">${s}</option>`).join('');
  srchRefreshFilterFieldOptions();
}
function srchAddFilterRow(){
  const wrap = document.getElementById('srch-adv-filter-builder');
  const key = document.getElementById('srch-adv-module').value;
  const fields = key==='settings' ? ['settingName','pageTitle','status'] : (key ? SRCH_MODULE_MAP[key].fields : Array.from(new Set(SRCH_MODULES.flatMap(m=>m.fields))));
  const row = document.createElement('div');
  row.className = 'srch-filter-row';
  row.innerHTML = `
    <select class="sf-field">${fields.map(f=>`<option value="${f}">${f.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())}</option>`).join('')}</select>
    <select class="sf-op"><option value="contains">contains</option><option value="equals">equals</option><option value="starts">starts with</option><option value="not">does not contain</option></select>
    <input type="text" class="sf-val" placeholder="value"/>
    <button class="btn btn-outline btn-sm btn-icon" onclick="this.closest('.srch-filter-row').remove()">✕</button>`;
  wrap.appendChild(row);
}
function srchRefreshFilterFieldOptions(){
  const key = document.getElementById('srch-adv-module').value;
  const fields = key==='settings' ? ['settingName','pageTitle','status'] : (key ? SRCH_MODULE_MAP[key].fields : Array.from(new Set(SRCH_MODULES.flatMap(m=>m.fields))));
  document.querySelectorAll('#srch-adv-filter-builder .sf-field').forEach(sel=>{
    const cur = sel.value;
    sel.innerHTML = fields.map(f=>`<option value="${f}">${f.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())}</option>`).join('');
    if(fields.includes(cur)) sel.value = cur;
  });
}
function srchCollectConditions(){
  const rows = document.querySelectorAll('#srch-adv-filter-builder .srch-filter-row');
  const out = [];
  rows.forEach(row=>{
    const field = row.querySelector('.sf-field').value;
    const operator = row.querySelector('.sf-op').value;
    const value = row.querySelector('.sf-val').value.trim();
    if(field && value) out.push({ field, operator, value });
  });
  return out;
}
async function srchRunAdvanced(){
  const key = document.getElementById('srch-adv-module').value;
  const keyword = document.getElementById('srch-adv-keyword').value.trim();
  const status = document.getElementById('srch-adv-status').value;
  const dateFrom = document.getElementById('srch-adv-from').value;
  const dateTo = document.getElementById('srch-adv-to').value;
  const sortBy = document.getElementById('srch-adv-sort').value;
  const sources = key ? [key] : srchAllSourceKeys();
  const conditions = srchCollectConditions();
  document.getElementById('srch-adv-meta').style.display = 'none';
  document.getElementById('srch-adv-results').innerHTML = '<div class="srch-empty">Searching…</div>';
  const res = await srchRunSearch(keyword, { sources, status, dateFrom, dateTo, conditions, sortBy, fuzzy: SRCH_CONFIG.fuzzy });
  state.search.lastAdvanced = { query: keyword, sources, res };
  state.search.advPage = 1;
  srchRenderAdvanced();
  srchLogSearch(keyword || (key?("source:"+key):""), sources, res.results.length, res.duration, "advanced");
}
function srchRenderAdvanced(){
  srchRenderResultsInto('srch-adv-results','srch-adv-meta', state.search.lastAdvanced, state.search.advPage, ()=>{ state.search.advPage++; srchRenderAdvanced(); });
}
function srchResetAdvanced(){
  document.getElementById('srch-adv-module').value = '';
  document.getElementById('srch-adv-keyword').value = '';
  document.getElementById('srch-adv-from').value = '';
  document.getElementById('srch-adv-to').value = '';
  document.getElementById('srch-adv-sort').value = 'relevance';
  document.getElementById('srch-adv-filter-builder').innerHTML = '';
  srchOnAdvModuleChange();
}

/* ---------------- SAVE SEARCH MODAL ---------------- */
function srchOpenSaveModal(context){
  state.search.saveContext = context;
  const bundle = context==='universal' ? state.search.lastUniversal : state.search.lastAdvanced;
  document.getElementById('srch-save-preview').textContent = bundle ? ('Query: ' + (bundle.query || '(all records)')) : 'Run a search first.';
  document.getElementById('srch-save-name').value = '';
  ssOpenModal('modal-save-search');
}
function srchConfirmSave(){
  const bundle = state.search.saveContext==='universal' ? state.search.lastUniversal : state.search.lastAdvanced;
  const name = document.getElementById('srch-save-name').value.trim();
  if(!name){ ssShowToast('Give this search a name','danger'); return; }
  if(!bundle){ ssShowToast('Run a search first','danger'); ssCloseModal('modal-save-search'); return; }
  state.search.saved.unshift({ id:srchUid(), name, query:bundle.query, sources:bundle.sources, createdAt:new Date().toISOString() });
  srchPersist('saved');
  srchUpdateSidebarBadges();
  ssCloseModal('modal-save-search');
  ssShowToast('Search saved','success');
}

/* ---------------- FILTER PRESETS ---------------- */
function srchOpenPresetModal(){
  const sel = document.getElementById('srch-preset-module');
  sel.innerHTML = `<option value="settings">⚙️ Settings</option>` + SRCH_MODULES.map(m=>`<option value="${m.key}">${m.icon} ${m.label}</option>`).join('');
  srchUpdatePresetStatusOptions();
  document.getElementById('srch-preset-name').value = '';
  ssOpenModal('modal-preset');
}
function srchUpdatePresetStatusOptions(){
  const key = document.getElementById('srch-preset-module').value;
  const statuses = key==='settings' ? ["Configured","Section"] : SRCH_MODULE_MAP[key].statuses;
  document.getElementById('srch-preset-status').innerHTML = `<option value="">Any</option>` + statuses.map(s=>`<option value="${s}">${s}</option>`).join('');
}
function srchConfirmPreset(){
  const name = document.getElementById('srch-preset-name').value.trim();
  if(!name){ ssShowToast('Name the preset first','danger'); return; }
  state.search.presets.unshift({ id:srchUid(), name, source:document.getElementById('srch-preset-module').value, status:document.getElementById('srch-preset-status').value });
  srchPersist('presets');
  ssCloseModal('modal-preset');
  srchRenderPresets();
  ssShowToast('Preset created','success');
}
function srchRenderPresets(){
  const el = document.getElementById('srch-presets-list');
  if(!el) return;
  if(!state.search.presets.length){ el.innerHTML = '<div class="srch-empty">No presets yet.</div>'; return; }
  el.innerHTML = state.search.presets.map(p=>{
    const m = srchSourceMeta(p.source);
    return `<div class="srch-card" style="--tab-color:${m?m.color:'var(--accent)'};margin-bottom:10px;">
      <div class="srch-tab"></div>
      <div class="srch-body">
        <div class="srch-top">
          <div><div class="srch-title" style="font-size:14px;">${srchEsc(p.name)}</div>
            <div class="srch-fields" style="margin-top:6px;">${m?`<span class="badge badge-blue">${m.icon} ${m.label}</span>`:''} ${p.status?`<span><b>Status</b>${srchEsc(p.status)}</span>`:''}</div></div>
          <div style="display:flex;gap:6px;">
            <button class="btn btn-outline btn-sm" onclick="srchApplyPreset('${p.id}')">Apply →</button>
            <button class="btn btn-outline btn-sm btn-icon" onclick="srchDeletePreset('${p.id}')">🗑</button>
          </div>
        </div>
      </div>
    </div>`;
  }).join('');
}
function srchApplyPreset(id){
  const p = state.search.presets.find(x=>x.id===id);
  if(!p) return;
  ssGoTo('search-advanced', document.querySelector('[data-page="search-advanced"]'));
  document.getElementById('srch-adv-module').value = p.source;
  srchOnAdvModuleChange();
  document.getElementById('srch-adv-status').value = p.status || '';
  srchRunAdvanced();
}
function srchDeletePreset(id){
  state.search.presets = state.search.presets.filter(p=>p.id!==id);
  srchPersist('presets');
  srchRenderPresets();
  ssShowToast('Preset deleted','');
}

/* ---------------- SAVED / RECENT / FAVOURITES ---------------- */
function srchSourceChipsHtml(sources){
  return (sources||[]).slice(0,4).map(k=>{ const m=srchSourceMeta(k); return m ? `<span class="badge badge-blue" style="margin-right:4px;">${m.icon} ${m.label}</span>` : ''; }).join('');
}
function srchRunFromRow(query, sourcesJson){
  const sources = JSON.parse(sourcesJson||'[]');
  if(sources.length) state.search.selectedSources = new Set(sources);
  ssGoTo('search-universal', document.querySelector('[data-page="search-universal"]'));
  srchRunUniversal(query);
}
function srchRenderSaved(){
  const el = document.getElementById('srch-saved-list');
  if(!state.search.saved.length){ el.innerHTML = '<div class="srch-empty">No saved searches yet. Run a search and click “Save this Search”.</div>'; return; }
  el.innerHTML = state.search.saved.map(s=>`
    <div class="srch-card" style="--tab-color:var(--accent);margin-bottom:10px;">
      <div class="srch-tab"></div>
      <div class="srch-body">
        <div class="srch-top">
          <div><div class="srch-title" style="font-size:14px;">${srchEsc(s.name)}</div>
            <div class="srch-fields" style="margin-top:6px;"><span><b>Query</b>${srchEsc(s.query||'(all)')}</span>${srchSourceChipsHtml(s.sources)}</div></div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span style="font-size:11px;color:var(--muted);">${fmtDMY(s.createdAt)}</span>
            <button class="btn btn-outline btn-sm" onclick='srchRunFromRow(${JSON.stringify(s.query)}, ${JSON.stringify(JSON.stringify(s.sources))})'>Run →</button>
            <button class="btn btn-outline btn-sm btn-icon" onclick="srchDeleteSaved('${s.id}')">🗑</button>
          </div>
        </div>
      </div>
    </div>`).join('');
}
function srchDeleteSaved(id){
  state.search.saved = state.search.saved.filter(s=>s.id!==id);
  srchPersist('saved');
  srchUpdateSidebarBadges();
  srchRenderSaved();
  ssShowToast('Saved search removed','');
}
function srchRenderRecent(){
  const el = document.getElementById('srch-recent-list');
  if(!state.search.recent.length){ el.innerHTML = '<div class="srch-empty">Nothing searched yet this session.</div>'; return; }
  el.innerHTML = state.search.recent.map(r=>{
    const isFav = state.search.favs.some(f=>f.query===r.query);
    return `<div class="srch-card" style="--tab-color:var(--gold);margin-bottom:10px;">
      <div class="srch-tab"></div>
      <div class="srch-body">
        <div class="srch-top">
          <div><div class="srch-title" style="font-size:13.5px;">${srchEsc(r.query)}</div>
            <div class="srch-fields" style="margin-top:6px;">${srchSourceChipsHtml(r.sources)}</div></div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span style="font-size:11px;color:var(--muted);">${srchTimeAgo(r.timestamp)}</span>
            <button class="btn btn-outline btn-sm btn-icon ${isFav?'':''}" style="${isFav?'color:var(--gold);border-color:var(--gold);':''}" onclick="srchToggleFav(${JSON.stringify(r.query)})" title="Favourite">⭐</button>
            <button class="btn btn-outline btn-sm" onclick='srchRunFromRow(${JSON.stringify(r.query)}, ${JSON.stringify(JSON.stringify(r.sources))})'>Run →</button>
          </div>
        </div>
      </div>
    </div>`;
  }).join('');
}
function srchToggleFav(query){
  const idx = state.search.favs.findIndex(f=>f.query===query);
  if(idx>=0) state.search.favs.splice(idx,1);
  else {
    const rec = state.search.recent.find(r=>r.query===query);
    state.search.favs.unshift({ id:srchUid(), query, sources: rec?rec.sources:[], timestamp:new Date().toISOString() });
  }
  srchPersist('favs');
  srchRenderRecent();
  srchRenderFavs();
}
function srchRenderFavs(){
  const el = document.getElementById('srch-favs-list');
  if(!el) return;
  if(!state.search.favs.length){ el.innerHTML = '<div class="srch-empty">Star any recent search to pin it here.</div>'; return; }
  el.innerHTML = state.search.favs.map(f=>`
    <div class="srch-card" style="--tab-color:var(--gold);margin-bottom:10px;">
      <div class="srch-tab"></div>
      <div class="srch-body">
        <div class="srch-top">
          <div><div class="srch-title" style="font-size:13.5px;">${srchEsc(f.query)}</div>
            <div class="srch-fields" style="margin-top:6px;">${srchSourceChipsHtml(f.sources)}</div></div>
          <div style="display:flex;gap:8px;">
            <button class="btn btn-outline btn-sm btn-icon" style="color:var(--gold);border-color:var(--gold);" onclick="srchToggleFav(${JSON.stringify(f.query)})">⭐</button>
            <button class="btn btn-outline btn-sm" onclick='srchRunFromRow(${JSON.stringify(f.query)}, ${JSON.stringify(JSON.stringify(f.sources))})'>Run →</button>
          </div>
        </div>
      </div>
    </div>`).join('');
}
function srchClearRecent(){
  if(!confirm('Clear all recent searches?')) return;
  state.search.recent = [];
  srchPersist('recent');
  srchRenderRecent();
}

/* ---------------- HISTORY ---------------- */
function srchRenderHistory(){
  const tbody = document.getElementById('srch-history-body');
  if(!state.search.history.length){ tbody.innerHTML = `<tr><td colspan="6" style="text-align:center;color:var(--muted);padding:30px;">No search activity recorded yet.</td></tr>`; return; }
  tbody.innerHTML = state.search.history.slice(0,150).map(h=>`
    <tr>
      <td>${srchEsc(h.query)}</td>
      <td><span class="badge badge-purple">${srchEsc(h.source)}</span></td>
      <td>${srchSourceChipsHtml(h.sources)}</td>
      <td class="mono">${h.resultCount}</td>
      <td class="mono">${h.duration}ms</td>
      <td class="mono">${srchFmtDateTime(h.timestamp)}</td>
    </tr>`).join('');
}
function srchClearHistory(){
  if(!confirm('Clear the entire search history log?')) return;
  state.search.history = [];
  srchPersist('history');
  srchRenderHistory();
}
function srchCsvEsc(v){
  // [PHASE-25A] Logic moved to Dnyanankur.Services.Search.srchCsvEsc(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Search) {
    return Dnyanankur.Services.Search.srchCsvEsc(v);
  }
  v=String(v==null?'':v); if(/[",\n]/.test(v)) v = '"'+v.replace(/"/g,'""')+'"'; return v;
}
function srchExportCsv(rows, filename){
  const header = ["Query","Source","Modules","Results","Duration(ms)","Timestamp"];
  const lines = [header.join(",")].concat(rows.map(h=>[srchCsvEsc(h.query), srchCsvEsc(h.source), srchCsvEsc((h.sources||[]).join("|")), h.resultCount, h.duration, h.timestamp].join(",")));
  const blob = new Blob([lines.join("\n")], {type:"text/csv"});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
}
function srchExportHistory(){ srchExportCsv(state.search.history, 'search-history.csv'); ssShowToast('Search history exported','success'); }

/* ---------------- STATISTICS ---------------- */
function srchRenderStats(){
  const total = state.search.history.length;
  const avgDur = total ? Math.round(state.search.history.reduce((s,h)=>s+h.duration,0)/total) : 0;
  const uniqueQ = new Set(state.search.history.map(h=>h.query.toLowerCase())).size;
  const today = state.search.history.filter(h=> new Date(h.timestamp).toDateString()===new Date().toDateString()).length;
  document.getElementById('srch-stats-cards').innerHTML = `
    <div class="card" style="padding:16px;margin:0;text-align:center;"><div style="font-size:26px;font-weight:800;color:var(--accent);font-family:'Plus Jakarta Sans',sans-serif;">${total}</div><div style="font-size:12px;color:var(--muted);margin-top:2px;">Total Searches</div></div>
    <div class="card" style="padding:16px;margin:0;text-align:center;"><div style="font-size:26px;font-weight:800;color:var(--success);font-family:'Plus Jakarta Sans',sans-serif;">${today}</div><div style="font-size:12px;color:var(--muted);margin-top:2px;">Searches Today</div></div>
    <div class="card" style="padding:16px;margin:0;text-align:center;"><div style="font-size:26px;font-weight:800;color:var(--purple);font-family:'Plus Jakarta Sans',sans-serif;">${uniqueQ}</div><div style="font-size:12px;color:var(--muted);margin-top:2px;">Unique Queries</div></div>
    <div class="card" style="padding:16px;margin:0;text-align:center;"><div style="font-size:26px;font-weight:800;color:var(--gold2);font-family:'Plus Jakarta Sans',sans-serif;">${avgDur}ms</div><div style="font-size:12px;color:var(--muted);margin-top:2px;">Avg Response Time</div></div>
  `;
  const days = []; for(let i=6;i>=0;i--){ const d=new Date(); d.setDate(d.getDate()-i); days.push(d); }
  const counts = days.map(d=> state.search.history.filter(h=> new Date(h.timestamp).toDateString()===d.toDateString()).length);
  const max = Math.max(1, ...counts);
  document.getElementById('srch-stats-bars').innerHTML = days.map((d,i)=>`<div class="col"><div class="bar" style="height:${(counts[i]/max*100)||2}%"></div><div class="lbl">${d.toLocaleDateString(undefined,{weekday:'short'})}</div></div>`).join('');

  const srcCounts = {};
  state.search.history.forEach(h=> (h.sources||[]).forEach(s=> srcCounts[s]=(srcCounts[s]||0)+1));
  const maxS = Math.max(1, ...Object.values(srcCounts), 0);
  const entries = srchAllSourceKeys().map(k=>[k, srcCounts[k]||0]).sort((a,b)=>b[1]-a[1]);
  document.getElementById('srch-stats-module-bars').innerHTML = entries.map(([k,c])=>{
    const m = srchSourceMeta(k);
    return `<div class="srch-hbar-row"><div class="lb">${m.icon} ${m.label}</div><div class="srch-hbar-track"><div class="srch-hbar-fill" style="width:${(c/maxS*100)||0}%;background:${m.color}"></div></div><div class="srch-hbar-val">${c}</div></div>`;
  }).join('');

  const freq = {};
  state.search.history.forEach(h=>{ if(h.query){ const k=h.query.toLowerCase(); freq[k]=(freq[k]||0)+1; } });
  const top = Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,6);
  document.getElementById('srch-stats-top-queries').innerHTML = top.length ? top.map(([q,c],i)=>`<div class="srch-hbar-row"><div class="lb" style="width:20px;font-family:'JetBrains Mono',monospace;color:var(--muted);">${i+1}</div><div class="lb" style="width:220px;">${srchEsc(q)}</div><div class="srch-hbar-track"><div class="srch-hbar-fill" style="width:${(c/top[0][1]*100)}%"></div></div><div class="srch-hbar-val">${c}</div></div>`).join('') : '<div class="srch-empty">No queries logged yet.</div>';
}

/* ---------------- REPORTS ---------------- */
function srchGenerateReport(){
  const from = document.getElementById('srch-rep-from').value;
  const to = document.getElementById('srch-rep-to').value;
  const src = document.getElementById('srch-rep-module').value;
  let rows = state.search.history.slice();
  if(from) rows = rows.filter(h=> h.timestamp.slice(0,10) >= from);
  if(to) rows = rows.filter(h=> h.timestamp.slice(0,10) <= to);
  if(src) rows = rows.filter(h=> (h.sources||[]).includes(src));
  const totalResults = rows.reduce((s,h)=>s+h.resultCount,0);
  const avgDur = rows.length ? Math.round(rows.reduce((s,h)=>s+h.duration,0)/rows.length) : 0;
  const freq = {};
  rows.forEach(h=>{ if(h.query){ const k=h.query.toLowerCase(); freq[k]=(freq[k]||0)+1; } });
  const top = Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,8);
  window.__srchLastReportRows = rows;
  document.getElementById('srch-report-output').innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0;">
      <div class="card" style="padding:16px;margin:0;text-align:center;"><div style="font-size:24px;font-weight:800;color:var(--accent);">${rows.length}</div><div style="font-size:12px;color:var(--muted);">Searches In Range</div></div>
      <div class="card" style="padding:16px;margin:0;text-align:center;"><div style="font-size:24px;font-weight:800;color:var(--success);">${totalResults}</div><div style="font-size:12px;color:var(--muted);">Total Results</div></div>
      <div class="card" style="padding:16px;margin:0;text-align:center;"><div style="font-size:24px;font-weight:800;color:var(--gold2);">${avgDur}ms</div><div style="font-size:12px;color:var(--muted);">Avg Duration</div></div>
      <div class="card" style="padding:16px;margin:0;text-align:center;"><div style="font-size:24px;font-weight:800;color:var(--purple);">${Object.keys(freq).length}</div><div style="font-size:12px;color:var(--muted);">Distinct Queries</div></div>
    </div>
    <div class="card">
      <div class="card-title" style="margin-bottom:12px;">Top Queries In Range</div>
      ${top.length ? top.map(([q,c])=>`<div class="srch-hbar-row"><div class="lb" style="width:220px;">${srchEsc(q)}</div><div class="srch-hbar-track"><div class="srch-hbar-fill" style="width:${(c/top[0][1]*100)}%"></div></div><div class="srch-hbar-val">${c}</div></div>`).join('') : '<div class="srch-empty">No searches match this range.</div>'}
    </div>
    <div class="card" style="overflow-x:auto;">
      <div class="card-title" style="margin-bottom:12px;">Search Log (${rows.length})</div>
      <table><thead><tr><th>Query</th><th>Source</th><th>Modules</th><th>Results</th><th>Duration</th><th>Timestamp</th></tr></thead>
      <tbody>${rows.slice(0,100).map(h=>`<tr><td>${srchEsc(h.query)}</td><td><span class="badge badge-purple">${srchEsc(h.source)}</span></td><td>${srchSourceChipsHtml(h.sources)}</td><td class="mono">${h.resultCount}</td><td class="mono">${h.duration}ms</td><td class="mono">${srchFmtDateTime(h.timestamp)}</td></tr>`).join('')}</tbody></table>
    </div>
  `;
  ssShowToast('Report generated for '+rows.length+' search entries','success');
}
function srchExportReport(){ srchExportCsv(window.__srchLastReportRows||[], 'search-report.csv'); }

/* ---------------- QUICK SEARCH (Ctrl+K) ---------------- */
const srchDebouncedQuickInput = srchDebounce(async (v)=>{
  const el = document.getElementById('srch-quick-results');
  if(!v.trim()){ el.innerHTML=''; return; }
  const res = await srchRunSearch(v, { sources: srchAllSourceKeys(), fuzzy: SRCH_CONFIG.fuzzy });
  const tokens = srchTokenize(v);
  el.innerHTML = res.results.slice(0,8).map(it=>srchRenderCard(it, tokens)).join('') || '<div class="srch-empty">No matches.</div>';
}, 200);
document.addEventListener('keydown', e=>{
  if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='k'){
    e.preventDefault();
    ssOpenModal('modal-quick-search');
    const inp = document.getElementById('srch-quick-input');
    inp.value=''; document.getElementById('srch-quick-results').innerHTML='';
    setTimeout(()=>inp.focus(), 30);
  }
});

/* ---------------- DASHBOARD CARD ---------------- */
function srchRenderDashCard(){
  const el = document.getElementById('srch-dash-stats');
  if(!el) return;
  const total = state.search.history.length;
  el.innerHTML = `
    <div style="background:rgba(255,255,255,0.08);border-radius:10px;padding:14px;text-align:center;"><div style="font-size:22px;font-weight:800;color:#fff;font-family:'Plus Jakarta Sans',sans-serif;">${srchTotalRecords().toLocaleString()}</div><div style="font-size:11px;color:rgba(255,255,255,0.6);margin-top:2px;">Indexed Records</div></div>
    <div style="background:rgba(255,255,255,0.08);border-radius:10px;padding:14px;text-align:center;"><div style="font-size:22px;font-weight:800;color:#fff;font-family:'Plus Jakarta Sans',sans-serif;">${SRCH_MODULES.length+1}</div><div style="font-size:11px;color:rgba(255,255,255,0.6);margin-top:2px;">Sources Searched</div></div>
    <div style="background:rgba(255,255,255,0.08);border-radius:10px;padding:14px;text-align:center;"><div style="font-size:22px;font-weight:800;color:#fff;font-family:'Plus Jakarta Sans',sans-serif;">${total}</div><div style="font-size:11px;color:rgba(255,255,255,0.6);margin-top:2px;">Searches Logged</div></div>
    <div style="background:rgba(255,255,255,0.08);border-radius:10px;padding:14px;text-align:center;"><div style="font-size:22px;font-weight:800;color:#fff;font-family:'Plus Jakarta Sans',sans-serif;">${state.search.saved.length}</div><div style="font-size:11px;color:rgba(255,255,255,0.6);margin-top:2px;">Saved Searches</div></div>
  `;
}

/* ---------------- PAGE DISPATCH (called from goTo) ---------------- */
function srchRenderPage(page){
  if(page==='search-universal') srchRenderUniversal();
  else if(page==='search-advanced'){ srchRenderAdvanced(); }
  else if(page==='search-filters') srchRenderPresets();
  else if(page==='search-saved') srchRenderSaved();
  else if(page==='search-recent') srchRenderRecent();
  else if(page==='search-favs') srchRenderFavs();
  else if(page==='search-history') srchRenderHistory();
  else if(page==='search-stats') srchRenderStats();
  else if(page==='search-reports'){ /* rendered on demand via Generate Report */ }
}

/* ---------------- INIT ---------------- */
function srchInit(){
  srchGenerateAllRecords();
  srchBuildIndex();
  srchPopulateAdvSelectors();
  srchRenderModuleChips();
  srchUpdateSidebarBadges();
  srchRenderDashCard();
  srchRenderPresets();
}

