function sleep(ms){ return new Promise(r=>setTimeout(r,ms)); }
function fmtNum(n){ return new Intl.NumberFormat('en-IN').format(n); }
function fmtCurrency(n){ return '₹' + new Intl.NumberFormat('en-IN').format(n); }
