const NAMES_M = ['Aarav','Vivaan','Aditya','Sai','Om','Rohan','Yash','Kunal','Siddharth','Rahul','Prathamesh','Aniket','Tanmay','Sanket','Nikhil'];
const NAMES_F = ['Saanvi','Ananya','Diya','Isha','Sneha','Pooja','Anjali','Riya','Neha','Priya','Sakshi','Shreya','Manasi','Pallavi','Kajal'];
const SURNAMES = ['Deshmukh','Kulkarni','Joshi','Patil','Kale','Shinde','Pawar','Jadhav','More','Chavan','Bhosale','Gaikwad','Sawant','Naik','Kadam'];
const SUBJECTS = ['Mathematics','Science','English','Marathi','Hindi','Social Studies','Computer Science','Physical Education'];
const rpRand = (arr)=>arr[Math.floor(Math.random()*arr.length)];
const rpRandInt = (a,b)=>Math.floor(Math.random()*(b-a+1))+a;
function randomName(){
  const isM = Math.random()>0.5;
  return `${rpRand(isM?NAMES_M:NAMES_F)} ${rpRand(SURNAMES)}`;
}

const MockData = {
  build(reportId, filters){
    const rows = MockData.generators[reportId] ? MockData.generators[reportId](filters) : [];
    return MockData.applyFilters(reportId, rows, filters);
  },
  applyFilters(reportId, rows, filters){
    if(!filters) return rows;
    return rows.filter(r=>{
      if(filters.className && filters.className!=='All' && r.className && String(r.className)!==String(filters.className)) return false;
      if(filters.division && filters.division!=='All' && r.division && r.division!==filters.division) return false;
      if(filters.gender && filters.gender!=='All' && r.gender && r.gender!==filters.gender) return false;
      if(filters.category && filters.category!=='All' && r.category && r.category!==filters.category) return false;
      if(filters.route && filters.route!=='All' && r.route && r.route!==filters.route) return false;
      if(filters.teacher && filters.teacher!=='All' && r.teacherName && r.teacherName!==filters.teacher) return false;
      if(filters.exam && filters.exam!=='All' && r.exam && r.exam!==filters.exam) return false;
      if(filters.feeType && filters.feeType!=='All' && r.feeType && r.feeType!==filters.feeType) return false;
      if(filters.status && filters.status!=='All' && r.status && r.status!==filters.status) return false;
      const d = r.date || r.timestamp;
      if(d){
        if(filters.dateFrom && d < filters.dateFrom) return false;
        if(filters.dateTo && d > filters.dateTo) return false;
      }
      return true;
    });
  },
  generators: {
    students(){
      const out=[];
      for(let i=0;i<160;i++){
        const gender = Math.random()>0.5?'Male':'Female';
        out.push({
          admissionNo:'DA'+(2400+i), name: `${rpRand(gender==='Male'?NAMES_M:NAMES_F)} ${rpRand(SURNAMES)}`,
          className:String(rpRandInt(1,10)), division: rpRand(['A','B','C','D']), gender,
          category: rpRand(['General','OBC','SC','ST','EWS']),
          guardian: rpRand(SURNAMES)+' '+rpRand(['Rajesh','Suresh','Mahesh','Ganesh','Vijay']),
          contact:'9'+rpRandInt(100000000,999999999),
          status: rpRand(['Active','Active','Active','Inactive','Alumni'])
        });
      }
      return out;
    },
    teachers(){
      const out=[];
      for(let i=0;i<48;i++){
        out.push({
          empId:'DT'+(100+i), name: randomName(), subject: rpRand(SUBJECTS),
          qualification: rpRand(['B.Ed','M.Ed','M.A, B.Ed','M.Sc, B.Ed','Ph.D']),
          experience: rpRandInt(1,22)+' yrs',
          classes: rpRandInt(2,6)+' sections',
          status: rpRand(['Active','Active','Active','On Leave','Resigned'])
        });
      }
      return out;
    },
    attendance(){
      const out=[];
      for(let d=0; d<14; d++){
        const date = daysAgoISO(d);
        for(let i=0;i<24;i++){
          out.push({
            date, className:String(rpRandInt(1,10)), division: rpRand(['A','B','C','D']),
            name: randomName(),
            status: rpRand(['Present','Present','Present','Present','Absent','Late','Half Day']),
            remarks: rpRand(['-','-','-','Informed','Medical','Late arrival'])
          });
        }
      }
      return out;
    },
    finance(){
      const out=[];
      const types=['Tuition Fee','Transport Fee','Exam Fee','Library Fee','Hostel Fee'];
      for(let i=0;i<130;i++){
        const feeType = rpRand(types);
        out.push({
          date: daysAgoISO(rpRandInt(0,60)), name: randomName(), className:String(rpRandInt(1,10)),
          feeType, amount: feeType==='Tuition Fee'? rpRandInt(8000,25000): rpRandInt(500,6000),
          mode: rpRand(['Online','Cash','Cheque','UPI']),
          status: rpRand(['Paid','Paid','Paid','Due','Overdue'])
        });
      }
      return out;
    },
    transport(){
      const out=[];
      const routes=['Route 1 - Chinchwad','Route 2 - Nigdi','Route 3 - Akurdi','Route 4 - Pimpri','Route 5 - Ravet'];
      routes.forEach((route,ri)=>{
        for(let i=0;i<22;i++){
          out.push({
            route, vehicleNo:'MH-14-'+String(2100+ri).slice(-4)+rpRand(['A','B','C']),
            driver: rpRand(SURNAMES)+' '+rpRand(['Kaka','Bhau','Anna']),
            name: randomName(), className:String(rpRandInt(1,10)),
            pickup: route.split(' - ')[1]+' Stop '+rpRandInt(1,6),
            status: rpRand(['Active','Active','Active','Suspended'])
          });
        }
      });
      return out;
    },
    inventory(){
      const items = [
        ['INV-001','Notebooks (200pg)','Stationery'],['INV-002','Whiteboard Markers','Stationery'],
        ['INV-003','Lab Beakers 250ml','Science Lab'],['INV-004','Microscopes','Science Lab'],
        ['INV-005','Basketballs','Sports'],['INV-006','Cricket Kits','Sports'],
        ['INV-007','Desktop Computers','IT'],['INV-008','Projectors','IT'],
        ['INV-009','First Aid Kits','Medical'],['INV-010','Chart Papers','Stationery'],
        ['INV-011','Football Sets','Sports'],['INV-012','Printer Toner','IT']
      ];
      return items.map(([itemCode,itemName,category])=>{
        const quantity = rpRandInt(0,240);
        return {
          itemCode,itemName,category,quantity,unit: category==='IT'?'units':'pcs',
          status: quantity===0?'Out of Stock': quantity<20?'Low Stock':'In Stock'
        };
      });
    },
    communication(){
      const out=[];
      for(let i=0;i<90;i++){
        out.push({
          date: daysAgoISO(rpRandInt(0,30)), channel: rpRand(['SMS','Email','Notice','WhatsApp']),
          recipientGroup: rpRand(['All Parents','Class 5 Parents','Class 10 Parents','Teaching Staff','Transport Users']),
          subject: rpRand(['Fee Reminder','PTM Notice','Holiday Circular','Exam Schedule','Transport Update','Result Declared']),
          status: rpRand(['Sent','Sent','Sent','Failed','Pending'])
        });
      }
      return out;
    },
    examination(){
      const out=[];
      const exams=['Unit Test 1','Unit Test 2','Mid Term','Final Term','Pre-Board'];
      for(let i=0;i<180;i++){
        const maxMarks = 100;
        const marks = rpRandInt(18,100);
        const grade = marks>=90?'A+':marks>=75?'A':marks>=60?'B':marks>=40?'C':'D';
        out.push({
          exam: rpRand(exams), name: randomName(), className:String(rpRandInt(1,10)),
          subject: rpRand(SUBJECTS), marks, maxMarks, grade,
          status: marks>=35 ? (marks===18?'Absent':'Pass') : 'Fail'
        });
      }
      return out;
    },
    admissions(){
      const out=[];
      for(let i=0;i<100;i++){
        out.push({
          date: daysAgoISO(rpRandInt(0,90)), name: randomName(), className:String(rpRandInt(1,10)),
          gender: rpRand(['Male','Female']), category: rpRand(['General','OBC','SC','ST','EWS']),
          status: rpRand(['Enquiry','Enquiry','Applied','Applied','Admitted','Admitted','Admitted','Waitlisted','Rejected'])
        });
      }
      return out;
    },
    audit(){
      const out=[];
      const modules=['Students','Finance','Attendance','Examination','Transport','Inventory','Admin Settings'];
      const actions=['Record Created','Record Updated','Record Deleted','Report Exported','Login','Permission Changed'];
      for(let i=0;i<110;i++){
        out.push({
          timestamp: daysAgoISO(rpRandInt(0,20)), user: randomName(), module: rpRand(modules), action: rpRand(actions),
          ip: `192.168.${rpRandInt(0,5)}.${rpRandInt(2,254)}`,
          status: rpRand(['Success','Success','Success','Warning','Failed'])
        });
      }
      return out;
    },
    useractivity(){
      const out=[];
      const roles=['Admin','Teacher','Accountant','Front Desk','Transport Manager'];
      for(let i=0;i<110;i++){
        out.push({
          timestamp: daysAgoISO(rpRandInt(0,15)), user: randomName(), role: rpRand(roles),
          module: rpRand(['Dashboard','Students','Finance','Attendance','Reports Engine']),
          duration: rpRandInt(2,95),
          status: rpRand(['Active','Idle','Logged Out'])
        });
      }
      return out;
    }
  }
};



