/* ---------------------------- DataStore --------------------------------
   Simulated database. Every method returns a Promise so callers already
   code against an async contract — swapping localStorage for `fetch()`
   calls to a real API later requires no change at the call sites.
   ------------------------------------------------------------------------ */
const DB_KEY = 'dnyanankur_print_engine_v1';

const DEFAULT_SCHOOL = {
  name: 'Dnyanankur Vidyalaya & Junior College',
  affiliation: 'Affiliated to State Board of Secondary & Higher Secondary Education',
  address: 'Survey No. 24, Near Civil Court, Pune - 411038, Maharashtra, India',
  phone: '+91 20 2345 6789',
  email: '[email protected]',
  website: 'www.dnyanankurschool.edu.in',
  udiseNo: '27130400123',
  logoData: '',
  principalName: 'Dr. R. S. Kulkarni',
  principalSignature: '',
  registrar: 'Mrs. A. V. Deshpande',
  primaryColor: '#12213b',
  accentColor: '#b8863b',
  bodyFont: 'Lora',
  pageSize: 'A4',
  orientation: 'portrait',
  margins: {top:18, right:16, bottom:16, left:16},
  watermarkEnabled: true,
  watermarkText: 'DNYANANKUR',
  watermarkOpacity: 0.06,
  qrEnabled: true,
  barcodeEnabled: false,
  showPrincipalSignature: true,
  showSeal: true
};

function loadDB(){
  try{
    const raw = localStorage.getItem(DB_KEY);
    if(raw) return JSON.parse(raw);
  }catch(e){ console.warn('ReportsDB parse failed, reinitializing', e); }
  const fresh = { school: {...DEFAULT_SCHOOL}, templates:{}, log:[], customDocTypes:[] };
  localStorage.setItem(DB_KEY, JSON.stringify(fresh));
  return fresh;
}
let ReportsDB = loadDB();
function persist(){ localStorage.setItem(DB_KEY, JSON.stringify(ReportsDB)); }

const DataStore = {
  getSchool: () => Promise.resolve({...DEFAULT_SCHOOL, ...ReportsDB.school}),
  saveSchool: (patch) => { ReportsDB.school = {...ReportsDB.school, ...patch}; persist(); return Promise.resolve(ReportsDB.school); },

  getTemplate: (docKey) => Promise.resolve(ReportsDB.templates[docKey] ? {...ReportsDB.templates[docKey]} : null),
  saveTemplate: (docKey, tpl) => { ReportsDB.templates[docKey] = {...(ReportsDB.templates[docKey]||{}), ...tpl}; persist(); return Promise.resolve(ReportsDB.templates[docKey]); },
  resetTemplate: (docKey) => { delete ReportsDB.templates[docKey]; persist(); return Promise.resolve(true); },

  // [Phase 13G-9] logDocument()/getLog() migrated from direct ReportsDB.log +
  // persist()/localStorage access onto the existing (previously unused)
  // Dnyanankur.Repository.reports singleton (ReportRepository, arrayPath:'log'
  // over the same 'dnyanankur_print_engine_v1' key — see Sprint 3). Same key,
  // same object shape, same cap/order logic; only the storage-access calls
  // changed. getSchool/saveSchool/getTemplate/saveTemplate/resetTemplate/
  // getCustomDocTypes/addCustomDocType/exportAll/importAll are intentionally
  // NOT touched here — see migration report (they address the sibling
  // school/templates/customDocTypes fields at this key, which are not
  // array-shaped and have no existing Repository method to reach them
  // without adding a new method to BaseRepository or a new subclass, both
  // out of scope for this sprint).
  logDocument: (entry) => {
    const arr = Dnyanankur.Repository.reports.getAll();
    arr.unshift({...entry, id:uid('log'), ts: Date.now()});
    Dnyanankur.Repository.reports.replaceAll(arr.slice(0,200));
    return Promise.resolve(true);
  },
  getLog: () => Promise.resolve(Dnyanankur.Repository.reports.getAll()),

  getCustomDocTypes: () => Promise.resolve([...ReportsDB.customDocTypes]),
  addCustomDocType: (cfg) => { ReportsDB.customDocTypes.push(cfg); persist(); return Promise.resolve(cfg); },

  exportAll: () => Promise.resolve(JSON.stringify(ReportsDB, null, 2)),
  importAll: (json) => { ReportsDB = JSON.parse(json); persist(); return Promise.resolve(true); }
};

/* ------------------------- Mini template engine -------------------------
   Supports {{field}} interpolation and {{#each arrField}}...{{this.col}}...{{/each}}
   loops for table-type schema fields. Intentionally dependency-free.
   ------------------------------------------------------------------------ */
function renderTpl(str, data){
  str = str.replace(/{{#each\s+(\w+)}}([\s\S]*?){{\/each}}/g, (m, key, inner) => {
    const arr = Array.isArray(data[key]) ? data[key] : [];
    return arr.map((item,i) => inner
        .replace(/{{this\.(\w+)}}/g, (m2,k)=> escapeHtml(item[k] ?? ''))
        .replace(/{{@index1}}/g, i+1)
      ).join('');
  });
  str = str.replace(/{{{(\w+)}}}/g, (m,key)=> data[key] ?? ''); // raw (unescaped)
  str = str.replace(/{{(\w+)}}/g, (m,key)=> escapeHtml(data[key] ?? ''));
  return str;
}

/* ============================== DOC TYPE REGISTRY =======================
   Every certificate / printable document ERP-wide is declared here once:
   its data schema (drives the auto-generated form) and its body markup
   (drives the printed output). Modules elsewhere in the ERP should NOT
   hardcode this list — they call PrintEngine.listDocTypes()/renderDocument()
   so new document types added here (or registered at runtime via
   PrintEngine.registerDocType) become available everywhere instantly.
   ========================================================================= */
