/* Build the inner .paper element HTML for a given doc type + data + effective template/settings */
function buildPaperHTML(docType, data, school, tpl){
  const size = PAGE_SIZES[tpl.pageSize || docType.pageSize || school.pageSize] || PAGE_SIZES.A4;
  const landscape = (tpl.orientation || school.orientation) === 'landscape';
  const wmm = landscape ? size.h : size.w;
  const hmm = landscape ? size.w : size.h;
  const margins = tpl.margins || school.margins;
  const mmToPx = mm => (mm * 3.7795).toFixed(1); // 96dpi

  const codesHtml = [];
  if(tpl.qrEnabled ?? school.qrEnabled){
    codesHtml.push(`<div class="code-box"><span class="qr-slot" data-qr="${escapeHtml(data.__qrValue || (docType.name+' | '+ (data.certNo||data.receiptNo||data.studentName||'')))}"><div class="qr-placeholder"></div></span><div class="code-label">Scan to Verify</div></div>`);
  }
  if(tpl.barcodeEnabled ?? school.barcodeEnabled){
    codesHtml.push(`<div class="code-box"><span class="bc-slot" data-barcode="${escapeHtml(data.__barcodeValue || (data.certNo||data.receiptNo||uid('BC')))}"><div class="barcode-placeholder"></div></span><div class="code-label">${escapeHtml(data.certNo||data.receiptNo||'')}</div></div>`);
  }

  const watermarkOn = tpl.watermarkEnabled ?? school.watermarkEnabled;
  const watermarkHtml = watermarkOn ? `<div class="doc-watermark" style="font-size:${wmm>150?70:34}px;opacity:${tpl.watermarkOpacity ?? school.watermarkOpacity}">${escapeHtml(tpl.watermarkText || school.watermarkText)}</div>` : '';

  const logoHtml = school.logoData ? `<img src="${school.logoData}" alt="logo">` : `<span style="font-family:'Sora',sans-serif;font-weight:800;color:#8a6529;">${escapeHtml((school.name||'S').split(' ').map(w=>w[0]).slice(0,2).join(''))}</span>`;

  const showSig = tpl.showPrincipalSignature ?? school.showPrincipalSignature;
  const sigImg = (showSig && school.principalSignature) ? `<img src="${school.principalSignature}">` : '';

  const bodyRendered = renderTpl(tpl.body || docType.body, data);
  const docTitle = renderTpl(tpl.title || docType.title, data);

  const isCard = (tpl.pageSize || docType.pageSize) === 'ID-CARD';

  return `<div class="paper" style="width:${mmToPx(wmm)}px;min-height:${mmToPx(hmm)}px;
      padding:${mmToPx(margins.top)}px ${mmToPx(margins.right)}px ${mmToPx(margins.bottom)}px ${mmToPx(margins.left)}px;
      font-family:'${tpl.bodyFont || school.bodyFont}',Georgia,serif;">
    ${watermarkHtml}
    ${isCard ? `
      <div style="text-align:center;position:relative;z-index:1;">
        <div class="logo-box" style="margin:0 auto 6px;">${logoHtml}</div>
        <div class="school-name" style="font-size:13px;">${escapeHtml(school.name)}</div>
        <div class="doc-title-bar" style="margin:8px 0;"><span class="dt" style="font-size:12px;">${escapeHtml(docTitle)}</span></div>
      </div>
      <div class="doc-body" style="font-size:11.5px;">${bodyRendered}</div>
      <div class="doc-footer" style="padding-top:10px;">
        ${codesHtml.join('')}
      </div>
    ` : `
      <div class="doc-header">
        <div class="logo-box">${logoHtml}</div>
        <div>
          <div class="school-name">${escapeHtml(school.name)}</div>
          <div class="school-meta">${escapeHtml(school.address)}<br>Ph: ${escapeHtml(school.phone)} &middot; ${escapeHtml(school.email)} &middot; ${escapeHtml(school.website)}</div>
          ${school.affiliation ? `<div class="school-affil">${escapeHtml(school.affiliation)}</div>` : ''}
        </div>
        <div class="doc-codes">${codesHtml.join('')}</div>
      </div>
      <div class="doc-title-bar">
        <span class="dt">${escapeHtml(docTitle)}</span>
        <div class="ds">Generated on ${todayStr()}</div>
      </div>
      <div class="doc-body">${bodyRendered}</div>
      <div class="doc-footer">
        <div class="issue-meta">UDISE No: ${escapeHtml(school.udiseNo||'-')}<br>This is a system-generated document.</div>
        ${(tpl.showSeal ?? school.showSeal) ? `<div class="seal">School<br>Seal</div>` : `<div></div>`}
        <div class="sig-block">
          ${sigImg}
          <div class="sig-line">${escapeHtml(school.principalName)}</div>
          <div>Principal</div>
        </div>
      </div>
      <div class="doc-strip">${escapeHtml(school.name)} &middot; Printed via Universal Print &amp; Certificate Engine</div>
    `}
  </div>`;
}

/* After HTML is inserted into the DOM, replace QR/barcode placeholder slots with real
   generated codes using the CDN libraries (falls back silently to the CSS placeholder
   if the library failed to load, e.g. offline). */
function hydrateCodes(container){
  container.querySelectorAll('[data-qr]').forEach(slot=>{
    const val = slot.getAttribute('data-qr');
    slot.innerHTML='';
    try{
      if(window.QRCode){ new QRCode(slot, {text: val, width:64, height:64, correctLevel: QRCode.CorrectLevel.M}); }
      else { slot.innerHTML = '<div class="qr-placeholder"></div>'; }
    }catch(e){ slot.innerHTML = '<div class="qr-placeholder"></div>'; }
  });
  container.querySelectorAll('[data-barcode]').forEach(slot=>{
    const val = slot.getAttribute('data-barcode');
    slot.innerHTML='';
    try{
      if(window.JsBarcode){
        const svg = document.createElementNS('http://www.w3.org/2000/svg','svg');
        slot.appendChild(svg);
        JsBarcode(svg, val || '000000', {height:34, width:1.4, displayValue:false, margin:0});
      } else { slot.innerHTML = '<div class="barcode-placeholder"></div>'; }
    }catch(e){ slot.innerHTML = '<div class="barcode-placeholder"></div>'; }
  });
}

/* Sample/demo data generator so every doc type has an instant preview */
function sampleDataFor(docType){
  const d = {};
  docType.schema.forEach(f=>{
    if(f.type==='table'){ d[f.key] = f.defaultRows || []; return; }
    if(f.type==='date'){ d[f.key] = new Date().toISOString().slice(0,10); return; }
    switch(f.key){
      case 'studentName': d[f.key]='Aarav Sharma'; break;
      case 'fatherName': d[f.key]='Rajesh Sharma'; break;
      case 'motherName': d[f.key]='Sunita Sharma'; break;
      case 'className': d[f.key]='X'; break;
      case 'division': d[f.key]='A'; break;
      case 'academicYear': d[f.key]='2026-27'; break;
      case 'teacherName': case 'empName': case 'holderName': case 'candidateName': d[f.key]='Priya Joshi'; break;
      case 'parentName': d[f.key]='Rajesh Sharma'; break;
      default:
        if(f.type==='number') d[f.key] = 5000;
        else if(f.type==='select') d[f.key] = (f.options||[''])[0];
        else d[f.key] = f.label;
    }
  });
  ['certNo','receiptNo','hallTicketNo','admitNo','grnNo','passNo','refNo','idNo'].forEach(k=>{ if(k in d) d[k] = d[k] && d[k]!==k ? d[k] : ('DES/'+new Date().getFullYear()+'/'+Math.floor(1000+Math.random()*9000)); });
  return d;
}

/* Merge: doc-type defaults  <-  saved custom template overrides */
async function getEffectiveTemplate(docKey){
  const docType = DOC_MAP[docKey];
  const saved = await DataStore.getTemplate(docKey);
  return { ...{}, ...(saved||{}) , _docType: docType };
}

/* ================================ PrintEngine ============================
   PUBLIC, REUSABLE API — every other ERP module (Admissions, Fees, Exams,
   HR, Transport, Library...) integrates with printing/certificates solely
   through this object. Example:

     PrintEngine.preview('feereceipt', { studentName:'...', items:[...] });
     PrintEngine.print('bonafide', dataFromAdmissionsModule);
     PrintEngine.renderDocument('idcard', data).then(html => ...);
   ========================================================================= */
const PrintEngine = {
  listDocTypes(category){
    return DOC_TYPES.filter(d => !category || d.category===category)
      .map(({key,name,desc,icon,category})=>({key,name,desc,icon,category}));
  },
  getSchema(docKey){ return (DOC_MAP[docKey]||{}).schema || []; },
  getSampleData(docKey){ const dt = DOC_MAP[docKey]; return dt ? sampleDataFor(dt) : {}; },

  async getTemplate(docKey){ return getEffectiveTemplate(docKey); },
  async saveTemplate(docKey, patch){ rpToast('Template saved for '+ (DOC_MAP[docKey]?.name||docKey)); return DataStore.saveTemplate(docKey, patch); },
  async resetTemplate(docKey){ rpToast('Template reset to default'); return DataStore.resetTemplate(docKey); },

  async getSchoolBranding(){ return DataStore.getSchool(); },
  async setSchoolBranding(patch){ return DataStore.saveSchool(patch); },

  /* Registers a brand-new document type at runtime, e.g. from another module:
     PrintEngine.registerDocType({key:'library_card', category:'printing', name:'Library Card', schema:[...], body:'...', title:'Library Card'}); */
  registerDocType(cfg){
    if(!cfg.key) throw new Error('registerDocType requires a unique key');
    DOC_MAP[cfg.key] = cfg;
    if(!DOC_TYPES.find(d=>d.key===cfg.key)) DOC_TYPES.push(cfg);
    DataStore.addCustomDocType(cfg);
    return true;
  },

  /* Returns the full inner HTML (a .paper element) for the given doc + data */
  async renderDocument(docKey, data){
    const docType = DOC_MAP[docKey];
    if(!docType) throw new Error('Unknown document type: '+docKey);
    const school = await DataStore.getSchool();
    const tpl = await getEffectiveTemplate(docKey);
    return buildPaperHTML(docType, data, school, tpl);
  },

  /* Opens the in-app preview modal */
  async preview(docKey, data){
    const docType = DOC_MAP[docKey];
    const html = await this.renderDocument(docKey, data);
    document.getElementById('previewModalTitle').textContent = docType.name + ' — Preview';
    const body = document.getElementById('previewModalBody');
    body.innerHTML = html;
    hydrateCodes(body);
    document.getElementById('previewModal').classList.remove('hidden');
    document.getElementById('previewModal').dataset.docKey = docKey;
    body.dataset.lastData = JSON.stringify(data);
    DataStore.logDocument({docKey, docName:docType.name, action:'preview'});
  },

  /* Sends straight to the browser print dialog */
  async print(docKey, data){
    const html = await this.renderDocument(docKey, data);
    const area = document.getElementById('printArea');
    area.innerHTML = html;
    hydrateCodes(area);
    DataStore.logDocument({docKey, docName:(DOC_MAP[docKey]||{}).name, action:'print'});
    setTimeout(()=>window.print(), 60);
  },

  /* Returns a fully self-contained HTML string (own <style>) suitable for
     download, emailing, or archiving. */
  async exportStandaloneHtml(docKey, data){
    const docType = DOC_MAP[docKey];
    const paper = await this.renderDocument(docKey, data);
    return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>${escapeHtml(docType.name)}</title>
      <script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\/script>
      <script src="https://cdnjs.cloudflare.com/ajax/libs/JsBarcode/3.11.5/JsBarcode.all.min.js"><\/script>
      <style>${STANDALONE_CSS}</style></head><body>${paper}
      <script>
        document.querySelectorAll('[data-qr]').forEach(function(slot){var v=slot.getAttribute('data-qr');slot.innerHTML='';try{new QRCode(slot,{text:v,width:64,height:64});}catch(e){}});
        document.querySelectorAll('[data-barcode]').forEach(function(slot){var v=slot.getAttribute('data-barcode');slot.innerHTML='';try{var svg=document.createElementNS('http://www.w3.org/2000/svg','svg');slot.appendChild(svg);JsBarcode(svg,v||'000000',{height:34,width:1.4,displayValue:false,margin:0});}catch(e){}});
      <\/script>
      </body></html>`;
  }
};
window.PrintEngine = PrintEngine; // exposed globally for every other ERP module


/* ================================ REPORTS ENGINE — Render Functions ======== */

function renderFilterBar(){
  const meta = ReportById[State.currentReportId];
  const bar = document.getElementById('filterbar');
  let fieldsHtml = '';
  meta.filters.forEach(fkey=>{
    const def = FilterMaster[fkey];
    if(!def) return;
    const val = State.filters[fkey] ?? '';
    if(def.type==='date'){
      fieldsHtml += `<div class="filter-field"><label>${def.label}</label>
        <input type="date" data-fkey="${fkey}" value="${val}"></div>`;
    } else {
      const opts = fkey==='status' ? meta.statusOptions : def.options;
      fieldsHtml += `<div class="filter-field"><label>${def.label}</label>
        <select data-fkey="${fkey}">
          ${opts.map(o=>`<option value="${o}" ${val===o?'selected':''}>${o}</option>`).join('')}
        </select></div>`;
    }
  });

  bar.innerHTML = `
    ${fieldsHtml}
    <div class="filter-field" style="min-width:auto;">
      <label>Chart</label>
      <div class="chart-toggle" id="chartToggle">
        ${['bar','line','pie','area'].map(t=>`<button data-chart="${t}" class="${State.chartType===t?'active':''}" title="${t}"><svg><use href="#i-${t}"/></svg></button>`).join('')}
      </div>
    </div>
    <div class="filterbar-actions">
      <button class="btn btn-ghost btn-sm" id="btnClearFilters">Clear</button>
      <button class="btn btn-primary btn-sm" id="btnApplyFilters"><svg><use href="#i-check"/></svg>Apply</button>
    </div>
  `;

  bar.querySelectorAll('[data-fkey]').forEach(el=>{
    el.addEventListener('change', ()=>{ State.filters[el.dataset.fkey]=el.value; });
  });
  bar.querySelectorAll('[data-chart]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      State.chartType = btn.dataset.chart;
      bar.querySelectorAll('[data-chart]').forEach(b=>b.classList.toggle('active', b===btn));
      renderChart();
    });
  });
  document.getElementById('btnClearFilters').onclick = ()=>{ State.filters={}; renderFilterBar(); loadAndRenderReport(); };
  document.getElementById('btnApplyFilters').onclick = loadAndRenderReport;
}

