function renderSummaryStats(){
  const meta = ReportById[State.currentReportId];
  const rows = State.currentRows;
  const box = document.getElementById('summaryStats');
  const agg = aggregateRows(rows, meta.chart);
  const total = rows.length;
  const topEntry = agg.labels.length ? agg.labels.map((l,i)=>[l,agg.values[i]]).sort((a,b)=>b[1]-a[1])[0] : ['—',0];
  let statusCount = null;
  if(rows.length && 'status' in rows[0]){
    const good = rows.filter(r=>['Present','Paid','Active','Admitted','Pass','Success','Sent','In Stock'].includes(r.status)).length;
    statusCount = Math.round((good/rows.length)*100);
  }
  box.innerHTML = `
    <div class="widget-list">
      <div class="widget-row" style="cursor:default;">
        <div class="w-icon"><svg><use href="#i-bar"/></svg></div>
        <div><div class="w-title">${fmtNum(total)} total records</div><div class="w-meta">matching current filters</div></div>
      </div>
      <div class="widget-row" style="cursor:default;">
        <div class="w-icon"><svg><use href="#i-star"/></svg></div>
        <div><div class="w-title">${topEntry[0]}</div><div class="w-meta">leading group · ${fmtNum(topEntry[1])} ${meta.chart.agg==='sum'?'total':meta.chart.agg==='avg'?'avg':'records'}</div></div>
      </div>
      ${statusCount!==null?`<div class="widget-row" style="cursor:default;">
        <div class="w-icon"><svg><use href="#i-check"/></svg></div>
        <div><div class="w-title">${statusCount}% healthy status</div><div class="w-meta">based on positive status values</div></div>
      </div>`:''}
    </div>
  `;
}

/* ---------- Aggregation for charts ---------- */
function aggregateRows(rows, chartMeta){
  const groups = {};
  rows.forEach(r=>{
    const key = r[chartMeta.group] ?? 'Unknown';
    if(!groups[key]) groups[key] = { sum:0, count:0 };
    groups[key].count += 1;
    if(chartMeta.valueKey) groups[key].sum += Number(r[chartMeta.valueKey])||0;
  });
  let labels = Object.keys(groups);
  // Natural sort for numeric-like labels (e.g. class 1..10)
  labels.sort((a,b)=> (isNaN(a)||isNaN(b)) ? a.localeCompare(b) : Number(a)-Number(b));
  const values = labels.map(l=>{
    const g = groups[l];
    if(chartMeta.agg==='sum') return g.sum;
    if(chartMeta.agg==='avg') return g.count ? Math.round((g.sum/g.count)*10)/10 : 0;
    return g.count;
  });
  return { labels, values };
}

let chartInstance = null;
function renderChart(){
  const meta = ReportById[State.currentReportId];
  const canvas = document.getElementById('reportChart');
  if(!canvas) return;
  const { labels, values } = aggregateRows(State.currentRows, meta.chart);
  const palette = ['#E5883A','#171B3D','#2E9E6C','#6D729A','#CE9A26','#8A4413','#3F4570','#D8494C'];

  if(chartInstance){ chartInstance.destroy(); }
  const isPie = State.chartType==='pie';
  const isArea = State.chartType==='area';
  const chartJsType = isArea ? 'line' : State.chartType;

  chartInstance = new Chart(canvas.getContext('2d'), {
    type: chartJsType,
    data: {
      labels,
      datasets: [{
        label: meta.chart.label,
        data: values,
        backgroundColor: isPie ? palette : (isArea ? 'rgba(229,136,58,0.22)' : '#E5883A'),
        borderColor: isPie ? '#fff' : '#E5883A',
        borderWidth: isPie ? 2 : 2,
        fill: isArea,
        tension: 0.35,
        borderRadius: chartJsType==='bar' ? 6 : 0,
        pointRadius: chartJsType==='line' ? 3 : 0
      }]
    },
    options: {
      responsive:true, maintainAspectRatio:false,
      plugins:{
        legend:{ display:isPie, position:'bottom', labels:{ boxWidth:10, font:{ family:'Inter', size:11 } } },
        tooltip:{ backgroundColor:'#171B3D', padding:10, titleFont:{family:'Inter'}, bodyFont:{family:'Inter'} }
      },
      scales: isPie ? {} : {
        x:{ grid:{ display:false }, ticks:{ font:{ family:'Inter', size:10.5 }, color:'#6D729A' } },
        y:{ grid:{ color:'#EEEFF7' }, ticks:{ font:{ family:'JetBrains Mono', size:10 }, color:'#6D729A' }, beginAtZero:true }
      }
    }
  });
}

/* ---------- Table ---------- */
function renderTable(){
  const meta = ReportById[State.currentReportId];
  const table = document.getElementById('dataTable');
  let rows = [...State.currentRows];
  if(State.sortKey){
    rows.sort((a,b)=>{
      const va = a[State.sortKey], vb = b[State.sortKey];
      if(typeof va === 'number' && typeof vb === 'number') return (va-vb)*State.sortDir;
      return String(va).localeCompare(String(vb)) * State.sortDir;
    });
  }
  const shown = rows.slice(0,60);

  const thead = `<thead><tr>${meta.columns.map(c=>`<th data-key="${c.key}">${c.label}</th>`).join('')}</tr></thead>`;
  const tbody = `<tbody>${shown.map(r=>`<tr>${meta.columns.map(c=>`<td>${formatCell(r[c.key], c.fmt)}</td>`).join('')}</tr>`).join('')}</tbody>`;
  table.innerHTML = thead + tbody;

  table.querySelectorAll('th').forEach(th=>{
    th.addEventListener('click', ()=>{
      const key = th.dataset.key;
      State.sortDir = (State.sortKey===key) ? -State.sortDir : 1;
      State.sortKey = key;
      renderTable();
    });
  });

  document.getElementById('tableFootNote').textContent =
    `Showing ${shown.length} of ${rows.length} rows${rows.length>60?' (export for full data)':''}`;
}

function formatCell(value, fmt){
  if(value===undefined || value===null) return '';
  if(fmt==='date') return rpFmtDate(value);
  if(fmt==='currency') return fmtCurrency(value);
  const statusClasses = {
    Present:'good', Paid:'good', Active:'good', Admitted:'good', Pass:'good', Success:'good', Sent:'good', 'In Stock':'good',
    Absent:'bad', Overdue:'bad', Failed:'bad', Rejected:'bad', Fail:'bad', 'Out of Stock':'bad', Inactive:'bad', Resigned:'bad', Suspended:'bad',
    Late:'warn', Due:'warn', Pending:'warn', Waitlisted:'warn', 'Low Stock':'warn', 'On Leave':'warn', Warning:'warn', 'Half Day':'warn', Idle:'warn'
  };
  if(statusClasses[value]) return `<span class="status-chip ${statusClasses[value]}">${value}</span>`;
  return String(value);
}

/* ============================================================
   11. EXPORTS
============================================================ */
function currentExportData(){
  const meta = ReportById[State.currentReportId];
  const cols = meta.columns;
  const header = cols.map(c=>c.label);
  const body = State.currentRows.map(r=>cols.map(c=>r[c.key]));
  return { header, body, filename: `${meta.id}-report-${todayISO()}` };
}

function downloadBlob(content, filename, type){
  const blob = new Blob([content], {type});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href=url; a.download=filename; document.body.appendChild(a); a.click();
  document.body.removeChild(a); URL.revokeObjectURL(url);
}

function rpExportCSV(){
  const { header, body, filename } = currentExportData();
  const esc = v => `"${String(v??'').replace(/"/g,'""')}"`;
  const csv = [header.map(esc).join(','), ...body.map(row=>row.map(esc).join(','))].join('\n');
  downloadBlob(csv, filename+'.csv', 'text/csv;charset=utf-8;');
  rpToast('CSV export ready');
}

function exportJSON(){
  const meta = ReportById[State.currentReportId];
  const filename = `${meta.id}-report-${todayISO()}.json`;
  downloadBlob(JSON.stringify(State.currentRows, null, 2), filename, 'application/json');
  rpToast('JSON export ready');
}

function exportExcel(){
  const { header, body, filename } = currentExportData();
  const ws = XLSX.utils.aoa_to_sheet([header, ...body]);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, ReportById[State.currentReportId].name.slice(0,28));
  XLSX.writeFile(wb, filename+'.xlsx');
  rpToast('Excel export ready');
}


