/* ── Workflow Engine ── */


'use strict';
/* =========================================================================
   WORKFLOW & APPROVAL ENGINE — School ERP
   Modular vanilla JS. Layers:
     UTIL   -> generic helpers
     WorkflowDB     -> async data-access layer (LocalStorage adapter today;
               swap-in target for Firebase / Supabase / MySQL-REST later)
     WF_SEED   -> first-run sample data
     ENGINE -> workflow business rules (state machine, permissions, stats)
     AUDIT  -> immutable action log
     STATE  -> in-memory app/session state (acting user, filters, route)
     UI     -> rendering + event wiring, split into per-view render fns
   No module depends on the DOM existing at load time except UI.
   ========================================================================= */

/* ============================== UTIL ================================== */
const UTIL = (() => {
  function uid(prefix){
    return prefix + '-' + Math.random().toString(36).slice(2,7).toUpperCase();
  }
  function pad(n,l){ return String(n).padStart(l,'0'); }
  function seqId(prefix, n){ return `${prefix}-${new Date().getFullYear()}-${pad(n,4)}`; }
  function wfFmtDate(d){
    const dt = new Date(d);
    return fmtDMY(dt);
  }
  function wfFmtDateTime(d){
    const dt = new Date(d);
    return fmtDMYTime(dt);
  }
  function wfTimeAgo(d){
    const s = Math.floor((Date.now() - new Date(d).getTime())/1000);
    if(s<60) return 'just now';
    const m = Math.floor(s/60); if(m<60) return m+'m ago';
    const h = Math.floor(m/60); if(h<24) return h+'h ago';
    const days = Math.floor(h/24); if(days<30) return days+'d ago';
    return wfFmtDate(d);
  }
  function wfEscapeHtml(str){
    return String(str??'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  function debounce(fn, wait){
    let t; return (...a) => { clearTimeout(t); t = setTimeout(()=>fn(...a), wait); };
  }
  function daysBetween(a,b){ return Math.max(0,(new Date(b)-new Date(a))/86400000); }
  function clamp(n,min,max){ return Math.min(max,Math.max(min,n)); }
  function wfRandInt(min,max){ return Math.floor(Math.random()*(max-min+1))+min; }
  function pick(arr){ return arr[wfRandInt(0,arr.length-1)]; }
  return { uid, seqId, fmtDate: wfFmtDate, fmtDateTime: wfFmtDateTime, timeAgo: wfTimeAgo, escapeHtml: wfEscapeHtml, debounce, daysBetween, clamp, randInt: wfRandInt, pick };
})();

/* ================================ WorkflowDB ===================================
   Generic repository shared by BOTH the Workflow/Approval engine and the
   Notification Center engine. Swap ADAPTER internals to point at a real
   backend without touching ENGINE/UI code:
     - Firebase:  replace get/put/del with Firestore collection() calls
     - Supabase:  replace with supabase.from(collection).select()/upsert()
     - MySQL:     replace with fetch('/api/'+collection) REST calls
   Methods are synchronous (a real backend adapter would return Promises;
   every call site in this file already uses `await WorkflowDB.x(...)`, which
   resolves a non-Promise value immediately, so the async call sites work
   unchanged against this synchronous in-memory/localStorage adapter).
   ========================================================================= */
const WorkflowDB = (() => {
  const STORAGE_KEY = 'schoolerp_workflow_engine_v1';
  const EMPTY_SHAPE = () => ({
    // Workflow & Approval Engine collections
    workflowTypes: [], roles: [], users: [], requests: [], templates: [], auditLog: [],
    // Notification Center Engine collections
    notifications: [], notifTemplates: [], rules: [], schedule: [], reminders: [], escalations: [],
    integrations: {
      sms:{enabled:false,provider:"Twilio",accountSid:"",authToken:"",senderId:"",status:"off"},
      whatsapp:{enabled:false,provider:"Twilio WhatsApp",accountSid:"",authToken:"",senderId:"",status:"off"},
      email:{enabled:false,provider:"SMTP / SendGrid",apiKey:"",fromAddress:"",status:"off"},
      push:{enabled:false,provider:"Web Push (VAPID)",publicKey:"",privateKey:"",status:"off"},
      fcm:{enabled:false,provider:"Firebase Cloud Messaging",serverKey:"",projectId:"",status:"off"},
      onesignal:{enabled:false,provider:"OneSignal",appId:"",apiKey:"",status:"off"}
    }
  });
  let mem = null;

  function _loadFromStorage(){
    try{
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : null;
    }catch(e){ return null; }
  }
  function _persist(){
    try{ localStorage.setItem(STORAGE_KEY, JSON.stringify(mem)); }catch(e){ /* storage unavailable, memory-only */ }
  }
  function _ensure(){
    if(mem) return;
    const loaded = _loadFromStorage();
    mem = loaded ? { ...EMPTY_SHAPE(), ...loaded } : EMPTY_SHAPE();
  }

  // ---- ADAPTER (LocalStorage / in-memory today) ----
  const Adapter = {
    uid(prefix){ return prefix + '_' + Math.random().toString(36).slice(2,9) + Date.now().toString(36).slice(-4); },
    getAll(collection){ _ensure(); return JSON.parse(JSON.stringify(mem[collection] || [])); },
    get(collection, id){ _ensure(); const row = (mem[collection]||[]).find(r=>r.id===id); return row ? JSON.parse(JSON.stringify(row)) : null; },
    add(collection, obj){
      _ensure();
      if(!obj.id) obj.id = this.uid(collection.slice(0,3));
      mem[collection] = mem[collection]||[];
      mem[collection].push(obj);
      _persist();
      return obj;
    },
    update(collection, id, patch){
      _ensure();
      const list = mem[collection]||[];
      const idx = list.findIndex(r=>r.id===id);
      if(idx===-1) return null;
      list[idx] = { ...list[idx], ...patch };
      _persist();
      return JSON.parse(JSON.stringify(list[idx]));
    },
    remove(collection, id){
      _ensure();
      mem[collection] = (mem[collection]||[]).filter(r=>r.id!==id);
      _persist();
      return true;
    },
    replaceAll(collection, rows){ _ensure(); mem[collection] = rows; _persist(); return rows; },
    isEmpty(){ _ensure(); return (mem.workflowTypes||[]).length === 0 && (mem.notifications||[]).length === 0; },
    wipe(){ mem = EMPTY_SHAPE(); _persist(); },
    // ---- compatibility aliases for the ported Notification Center code ----
    list(collection){ return this.getAll(collection); },
    persist(){ _ensure(); _persist(); },
    get data(){ _ensure(); return mem; }
  };

  return Adapter;
})();

/* =============================== WF_SEED ================================== */
const WF_SEED = (() => {
  const ROLES = [
    'Super Admin','Director','Principal','Registrar','Admission Officer','HR Manager',
    'Accountant','Finance Manager','Store Manager','Admin Officer','Transport Manager',
    'Exam Controller','Class Teacher'
  ];

  const WORKFLOW_TYPES = [
    { code:'STU-ADM', name:'Student Admission', category:'Academics',
      description:'New student admission requests routed through admissions to leadership.',
      levels:[ {role:'Admission Officer'}, {role:'Principal'}, {role:'Director'} ] },
    { code:'STU-EDT', name:'Student Edit', category:'Academics',
      description:'Corrections to existing student records (class, guardian, contact details).',
      levels:[ {role:'Class Teacher'}, {role:'Registrar'} ] },
    { code:'TCH-REG', name:'Teacher Registration', category:'Human Resources',
      description:'Onboarding of new teaching staff into the school system.',
      levels:[ {role:'HR Manager'}, {role:'Principal'}, {role:'Director'} ] },
    { code:'TCH-EDT', name:'Teacher Edit', category:'Human Resources',
      description:'Updates to teacher employment records, subjects, or grade assignments.',
      levels:[ {role:'HR Manager'}, {role:'Principal'} ] },
    { code:'FEE-CON', name:'Fee Concession', category:'Finance',
      description:'Discretionary discounts or waivers against student fee ledgers.',
      levels:[ {role:'Accountant'}, {role:'Finance Manager'}, {role:'Principal'} ] },
    { code:'INV-APR', name:'Inventory Approval', category:'Operations',
      description:'Purchase or issue of school inventory and stock items.',
      levels:[ {role:'Store Manager'}, {role:'Admin Officer'}, {role:'Principal'} ] },
    { code:'TRN-APR', name:'Transport Approval', category:'Operations',
      description:'New transport route allocation or vehicle assignment requests.',
      levels:[ {role:'Transport Manager'}, {role:'Admin Officer'} ] },
    { code:'EXM-APR', name:'Examination Approval', category:'Academics',
      description:'Exam schedules, question papers, and result sheets sign-off.',
      levels:[ {role:'Exam Controller'}, {role:'Principal'} ] },
    { code:'CRT-APR', name:'Certificate Approval', category:'Academics',
      description:'Issuance of transfer, bonafide, or completion certificates.',
      levels:[ {role:'Registrar'}, {role:'Principal'} ] },
    { code:'LVE-APR', name:'Leave Approval', category:'Human Resources',
      description:'Staff leave requests routed to reporting authority.',
      levels:[ {role:'Class Teacher'}, {role:'Principal'} ] },
  ];

  // [PHASE-21 FOLLOW-UP] buildTemplates()/buildRequests() were moved out of
  // WF_SEED into Dnyanankur.Services.Communication, but this table stayed
  // behind in WF_SEED's closure — so the moved copy threw
  // "TEMPLATE_FIELDS is not defined" on every call, which surfaced as an
  // unhandled rejection out of `await WF_SEED.run()`. Publishing it on the
  // namespace gives the moved code a legitimate way to reach it without
  // duplicating the table in two places that could drift apart.
  const TEMPLATE_FIELDS = {
    'STU-ADM': [ ['studentName','Student Name','text'], ['dob','Date of Birth','date'], ['classApplied','Class Applied For','text'], ['guardianName','Guardian Name','text'], ['contact','Contact Number','text'], ['previousSchool','Previous School','text'] ],
    'STU-EDT': [ ['studentId','Student ID','text'], ['fieldToChange','Field To Change','text'], ['newValue','New Value','text'], ['reason','Reason','textarea'] ],
    'TCH-REG': [ ['teacherName','Teacher Name','text'], ['subject','Subject Specialization','text'], ['qualification','Qualification','text'], ['contact','Contact Number','text'], ['joiningDate','Proposed Joining Date','date'] ],
    'TCH-EDT': [ ['teacherId','Teacher ID','text'], ['fieldToChange','Field To Change','text'], ['newValue','New Value','text'] ],
    'FEE-CON': [ ['studentId','Student ID','text'], ['concessionPercent','Concession %','text'], ['reason','Reason for Concession','textarea'] ],
    'INV-APR': [ ['itemName','Item Name','text'], ['quantity','Quantity','text'], ['estimatedCost','Estimated Cost (₹)','text'], ['vendor','Preferred Vendor','text'] ],
    'TRN-APR': [ ['studentOrStaff','Student / Staff Name','text'], ['route','Route Requested','text'], ['pickupPoint','Pickup Point','text'] ],
    'EXM-APR': [ ['examName','Examination Name','text'], ['class','Class / Grade','text'], ['scheduledDate','Scheduled Date','date'] ],
    'CRT-APR': [ ['studentId','Student ID','text'], ['certificateType','Certificate Type','text'], ['purpose','Purpose','textarea'] ],
    'LVE-APR': [ ['staffName','Staff Name','text'], ['leaveType','Leave Type','text'], ['fromDate','From Date','date'], ['toDate','To Date','date'], ['reason','Reason','textarea'] ],
  };

  // Published for the [PHASE-21] copies of buildTemplates()/buildRequests()
  // that now live in Dnyanankur.Services.Communication, which cannot see this
  // closure. Single definition, two readers.
  //
  // randomFormData is a function declaration, so it is hoisted and already
  // callable here even though it appears further down. Exporting the function
  // itself (rather than re-implementing it) keeps its own closure over UTIL
  // and fullName intact.
  try {
    window.Dnyanankur = window.Dnyanankur || {};
    Dnyanankur.WorkflowSeed = Dnyanankur.WorkflowSeed || {};
    Dnyanankur.WorkflowSeed.TEMPLATE_FIELDS = TEMPLATE_FIELDS;
    Dnyanankur.WorkflowSeed.randomFormData = randomFormData;
  } catch (e) { /* namespace unavailable — the fallbacks at the use sites handle it */ }

  const FIRST = ['Aarav','Isha','Kabir','Meera','Rohan','Ananya','Vihaan','Diya','Aditya','Sara','Reyansh','Priya','Arjun','Neha','Karan','Tanya','Yash','Riya','Devansh','Simran','Nikhil','Pooja','Rahul','Kritika'];
  const LAST = ['Sharma','Verma','Iyer','Gupta','Nair','Kapoor','Reddy','Joshi','Menon','Chatterjee','Bose','Malhotra','Rao','Pillai','Agarwal'];
  const DEPARTMENTS = ['Primary Wing','Middle School','Senior Secondary','Administration','Finance Office','Transport Dept.','Examination Cell','HR Dept.'];

  function fullName(){ return `${UTIL.pick(FIRST)} ${UTIL.pick(LAST)}`; }

  function buildUsers(){
    const users = [{ id:'U-000', name:'System Administrator', role:'Super Admin', department:'Administration' }];
    ROLES.filter(r=>r!=='Super Admin').forEach((role, i) => {
      users.push({ id:'U-'+String(i+1).padStart(3,'0'), name: fullName(), role, department: UTIL.pick(DEPARTMENTS) });
    });
    // a couple of extra staff who only ever *submit* requests
    users.push({ id:'U-090', name: fullName(), role:'Class Teacher', department:'Primary Wing' });
    users.push({ id:'U-091', name: fullName(), role:'Class Teacher', department:'Middle School' });
    return users;
  }

  function buildWorkflowTypes(){
    return WORKFLOW_TYPES.map((wt,i) => ({
      id: 'WT-'+String(i+1).padStart(2,'0'),
      code: wt.code,
      name: wt.name,
      category: wt.category,
      description: wt.description,
      active: true,
      levels: wt.levels.map((lv,li) => ({ level: li+1, name: `Level ${li+1} — ${lv.role}`, role: lv.role })),
      createdAt: new Date(Date.now() - UTIL.randInt(120,400)*86400000).toISOString(),
    }));
  }

  function buildTemplates(workflowTypes){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.buildTemplates(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.buildTemplates(workflowTypes);
  }

    return workflowTypes.map(wt => ({
      id: 'TPL-'+wt.code,
      workflowTypeId: wt.id,
      name: wt.name + ' — Standard Form',
      fields: (TEMPLATE_FIELDS[wt.code]||[]).map(([key,label,type]) => ({key,label,type})),
      updatedAt: new Date().toISOString()
    }));
  }

  function randomFormData(wt){
    const fields = TEMPLATE_FIELDS[wt.code] || [];
    const data = {};
    fields.forEach(([key,label,type]) => {
      if(type==='date'){ data[key] = new Date(Date.now()+UTIL.randInt(-30,60)*86400000).toISOString().slice(0,10); }
      else if(key.toLowerCase().includes('name')) data[key] = fullName();
      else if(key==='concessionPercent') data[key] = String(UTIL.pick([10,15,20,25,50]));
      else if(key==='estimatedCost') data[key] = String(UTIL.randInt(2000,80000));
      else if(key==='quantity') data[key] = String(UTIL.randInt(1,50));
      else data[key] = UTIL.pick(['General','Standard','Requested','Pending Review','N/A']);
    });
    return data;
  }

  function buildRequests(workflowTypes, users){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.buildRequests(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.buildRequests(workflowTypes, users);
  }

    const requests = [];
    const teachers = users.filter(u=>u.role==='Class Teacher');
    const requesterPoolByRole = {}; // helper to find a plausible level-1 requester
    let counter = 1;
    const statuses = ['pending','pending','pending','approved','approved','rejected','returned','draft'];

    workflowTypes.forEach(wt => {
      const n = UTIL.randInt(3,5);
      for(let i=0;i<n;i++){
        const status = UTIL.pick(statuses);
        const createdAt = new Date(Date.now() - UTIL.randInt(1,55)*86400000 - UTIL.randInt(0,86399)*1000);
        const requester = UTIL.pick(users.filter(u=>u.role!=='Super Admin'));
        const id = UTIL.seqId('WF', counter++);
        const history = [{
          ts: createdAt.toISOString(), level:0, levelName:'Submission',
          role: requester.role, actor: requester.name, action:'created', comment:'Request created.'
        }];

        let currentLevelIndex = 0;
        let finalStatus = status;
        let returnedFromLevel = null;

        if(status !== 'draft'){
          history.push({
            ts: new Date(createdAt.getTime()+3600000).toISOString(), level:0, levelName:'Submission',
            role: requester.role, actor: requester.name, action:'submitted', comment:'Submitted for approval.'
          });
        }

        if(status==='pending'){
          currentLevelIndex = UTIL.randInt(0, wt.levels.length-1);
          for(let L=0; L<currentLevelIndex; L++){
            const lv = wt.levels[L];
            const approver = users.find(u=>u.role===lv.role) || users[0];
            const ts = new Date(createdAt.getTime() + (L+1)*UTIL.randInt(4,20)*3600000);
            history.push({ ts: ts.toISOString(), level:lv.level, levelName:lv.name, role: lv.role, actor: approver.name, action:'approved', comment: UTIL.pick(['Looks good, forwarding.','Verified, approved.','Documents in order.','Approved as per policy.']) });
          }
        } else if(status==='approved'){
          currentLevelIndex = wt.levels.length;
          for(let L=0; L<wt.levels.length; L++){
            const lv = wt.levels[L];
            const approver = users.find(u=>u.role===lv.role) || users[0];
            const ts = new Date(createdAt.getTime() + (L+1)*UTIL.randInt(4,20)*3600000);
            history.push({ ts: ts.toISOString(), level:lv.level, levelName:lv.name, role: lv.role, actor: approver.name, action:'approved', comment: UTIL.pick(['Approved.','All checks passed.','Confirmed, approving.']) });
          }
        } else if(status==='rejected'){
          const rejectAt = UTIL.randInt(0, wt.levels.length-1);
          for(let L=0; L<rejectAt; L++){
            const lv = wt.levels[L];
            const approver = users.find(u=>u.role===lv.role) || users[0];
            const ts = new Date(createdAt.getTime() + (L+1)*UTIL.randInt(4,20)*3600000);
            history.push({ ts: ts.toISOString(), level:lv.level, levelName:lv.name, role: lv.role, actor: approver.name, action:'approved', comment:'Approved, forwarding.' });
          }
          const lv = wt.levels[rejectAt];
          const approver = users.find(u=>u.role===lv.role) || users[0];
          const ts = new Date(createdAt.getTime() + (rejectAt+1)*UTIL.randInt(4,20)*3600000);
          history.push({ ts: ts.toISOString(), level:lv.level, levelName:lv.name, role: lv.role, actor: approver.name, action:'rejected', comment: UTIL.pick(['Incomplete documentation.','Does not meet policy criteria.','Budget not available.','Duplicate request.']) });
          currentLevelIndex = rejectAt;
        } else if(status==='returned'){
          const retAt = UTIL.randInt(0, wt.levels.length-1);
          for(let L=0; L<retAt; L++){
            const lv = wt.levels[L];
            const approver = users.find(u=>u.role===lv.role) || users[0];
            const ts = new Date(createdAt.getTime() + (L+1)*UTIL.randInt(4,20)*3600000);
            history.push({ ts: ts.toISOString(), level:lv.level, levelName:lv.name, role: lv.role, actor: approver.name, action:'approved', comment:'Approved, forwarding.' });
          }
          const lv = wt.levels[retAt];
          const approver = users.find(u=>u.role===lv.role) || users[0];
          const ts = new Date(createdAt.getTime() + (retAt+1)*UTIL.randInt(4,20)*3600000);
          history.push({ ts: ts.toISOString(), level:lv.level, levelName:lv.name, role: lv.role, actor: approver.name, action:'returned', comment: UTIL.pick(['Please attach missing documents and resubmit.','Clarify guardian contact details.','Amend budget figure and resend.']) });
          currentLevelIndex = retAt;
          returnedFromLevel = retAt;
        }

        requests.push({
          id, workflowTypeId: wt.id,
          title: `${wt.name} — ${requester.name}`,
          requestedBy: { id:requester.id, name:requester.name, role:requester.role },
          department: requester.department,
          priority: UTIL.pick(['Low','Normal','Normal','High','Urgent']),
          createdAt: createdAt.toISOString(),
          updatedAt: (history[history.length-1]||{ts:createdAt.toISOString()}).ts,
          status: finalStatus,
          currentLevelIndex,
          returnedFromLevel,
          data: randomFormData(wt),
          history
        });
      }
    });
    return requests;
  }

  function buildAuditLog(requests, users){
    const log = [];
    let n=1;
    requests.forEach(r => {
      r.history.forEach(h => {
        log.push({
          id: UTIL.uid('AUD'),
          ts: h.ts,
          actor: h.actor,
          role: h.role,
          action: h.action,
          entity: 'Request',
          entityId: r.id,
          details: `${h.action.toUpperCase()} on ${r.id} (${r.title}) — ${h.comment||''}`.trim()
        });
      });
    });
    log.sort((a,b)=> new Date(b.ts)-new Date(a.ts));
    return log;
  }

  async function run(){
    const empty = await WorkflowDB.isEmpty();
    if(!empty) return;
    const users = buildUsers();
    const workflowTypes = buildWorkflowTypes();
    const templates = buildTemplates(workflowTypes);
    const requests = buildRequests(workflowTypes, users);
    const auditLog = buildAuditLog(requests, users);
    const notify = buildNotifySeed(); // Notification Center seed (templates, rules, scheduler, reminders, escalations, notifications, audit)

    const combinedAudit = auditLog.concat(notify.auditEntries).sort((a,b)=> new Date(b.ts)-new Date(a.ts));

    await WorkflowDB.replaceAll('roles', ROLES.map((r,i)=>({id:'R-'+i, name:r})));
    await WorkflowDB.replaceAll('users', users);
    await WorkflowDB.replaceAll('workflowTypes', workflowTypes);
    await WorkflowDB.replaceAll('templates', templates);
    await WorkflowDB.replaceAll('requests', requests);
    await WorkflowDB.replaceAll('auditLog', combinedAudit);
    await WorkflowDB.replaceAll('notifTemplates', notify.notifTemplates);
    await WorkflowDB.replaceAll('rules', notify.rules);
    await WorkflowDB.replaceAll('schedule', notify.schedule);
    await WorkflowDB.replaceAll('reminders', notify.reminders);
    await WorkflowDB.replaceAll('escalations', notify.escalations);
    await WorkflowDB.replaceAll('notifications', notify.notifications);
  }

  return { run, ROLES };
})();

/* =============================== AUDIT ================================= */
const AUDIT = (() => {
  async function log(actor, role, action, entity, entityId, details){
    const entry = { id: UTIL.uid('AUD'), ts: new Date().toISOString(), actor, role, action, entity, entityId, details };
    await WorkflowDB.add('auditLog', entry);
    if (window.ERPCore && window.ERPCore.AuditLog) {
      window.ERPCore.AuditLog.log(`Workflow: ${action}`, `${entity} ${entityId} by ${actor} (${role})${details ? ' — ' + details : ''}`, 'info');
    }
    return entry;
  }
  async function all(){
    const rows = await WorkflowDB.getAll('auditLog');
    return rows.sort((a,b)=> new Date(b.ts)-new Date(a.ts));
  }
  return { log, all };
})();

/* ======================= SHARED UI HELPERS ==============================
   Promoted out of the UI module so both the Workflow engine and the
   ported Notification Center engine (which lives at module scope, not
   inside the UI closure) can call the same toast/modal primitives.
   ========================================================================= */
function wfToast(msg, kind){
  const wrap = document.getElementById('wf-toast-wrap');
  const known = ['success','error','info'];
  const cls = known.includes(kind) ? kind : 'info';
  const el = document.createElement('div');
  el.className = 'wf-toast ' + cls;
  el.textContent = msg;
  wrap.appendChild(el);
  setTimeout(()=>{ el.style.opacity='0'; el.style.transition='opacity .25s'; setTimeout(()=>el.remove(),250); }, 3200);
}
function wfCloseModal(){ document.getElementById('wf-modal-root').innerHTML = ''; }
function wfOpenModal(html, opts){
  const root = document.getElementById('wf-modal-root');
  root.innerHTML = `<div class="wf-modal-overlay" id="modal-overlay"><div class="wf-modal ${opts&&opts.lg?'wf-modal-lg':''}">${html}</div></div>`;
  root.querySelector('#modal-overlay').addEventListener('click', (e) => { if(e.target.id==='modal-overlay') wfCloseModal(); });
}
function escapeAttr(s){ return (s||"").replace(/"/g,"&quot;"); }
function wfEscapeHtml(s){ return (s||"").replace(/[&<>]/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[c])); }
function downloadJSON(obj, filename){
  const blob = new Blob([JSON.stringify(obj,null,2)], {type:"application/json"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
}

/* =========================================================================
   NOTIFICATION CENTER ENGINE (ported from NotifyCore)
   Reads/writes exclusively through the shared WorkflowDB.* API above. Runs its own
   lightweight background engines (scheduler / reminders / escalation) and
   is bridged to the Workflow & Approval engine via notifyFromWorkflow(),
   so every approve/reject/return/submit automatically raises a matching
   in-app notification (see the ENGINE hooks further below).
   ========================================================================= */
const WF_MODULES = ["Admissions","Attendance","Finance","Transport","Inventory","Examinations","Teachers","Students","Communication","Approvals"];
const PRIORITIES = ["Low","Medium","High","Critical"];
const CHANNELS = ["In-App","SMS","WhatsApp","Email","Push","FCM","OneSignal"];
const MODULE_ICON = {
  Admissions:"🎓",Attendance:"🗓",Finance:"💳",Transport:"🚌",Inventory:"📦",
  Examinations:"📝",Teachers:"🍎",Students:"🧑‍🎓",Communication:"📣",Approvals:"✅"
};
const MODULE_COLOR = {
  Admissions:"#5b5ff0",Attendance:"#0fb5a6",Finance:"#e0722c",Transport:"#3b82c4",
  Inventory:"#8a5cf6",Examinations:"#e14f4f",Teachers:"#2fa66a",Students:"#e6a319",
  Communication:"#c2489a",Approvals:"#4b5563"
};
function nowISO(offsetMin){ return new Date(Date.now() + (offsetMin||0)*60000).toISOString(); }
function rand(arr){ return arr[Math.floor(Math.random()*arr.length)]; }
function wfRandInt(a,b){ return Math.floor(Math.random()*(b-a+1))+a; }

function addAudit(actor, action, details, entity, entityId){
  AUDIT.log(actor, '', action, entity||'Notification', entityId||'', details);
}

/* ---------- Workflow → Notification bridge ----------
   Called by ENGINE (workflow/approval logic) whenever a request is
   submitted, approved, rejected, returned, or resubmitted. Raises a
   matching "Approvals" module notification and an audit entry — this is
   what satisfies "workflow actions automatically generate notifications". */
function notifyFromWorkflow(event, req, wt, actor, extra){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.notifyFromWorkflow(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.notifyFromWorkflow(event, req, wt, actor, extra);
  }

  const priorityMap = { Low:'Low', Normal:'Medium', High:'High', Urgent:'Critical' };
  const priority = priorityMap[req.priority] || 'Medium';
  const nextLevel = wt.levels[req.currentLevelIndex];
  let title, message;
  if(event === 'submitted'){
    title = `New ${wt.name} Request Submitted`;
    message = `${req.id} — "${req.title}" submitted by ${actor.name}. Awaiting ${nextLevel? nextLevel.name : 'approval'}.`;
  } else if(event === 'approved'){
    title = req.status==='approved' ? `${wt.name} Fully Approved` : `${wt.name} Approved — Next Level`;
    message = req.status==='approved'
      ? `${req.id} has been approved at every level and is now complete.`
      : `${req.id} approved by ${actor.name} (${actor.role}). Now awaiting ${nextLevel? nextLevel.name : 'the next level'}.`;
  } else if(event === 'rejected'){
    title = `${wt.name} Request Rejected`;
    message = `${req.id} was rejected by ${actor.name} (${actor.role}).${extra? ' Reason: '+extra:''}`;
  } else if(event === 'returned'){
    title = `${wt.name} Request Returned for Correction`;
    message = `${req.id} was returned by ${actor.name} (${actor.role}).${extra? ' Note: '+extra:''}`;
  } else if(event === 'resubmitted'){
    title = `${wt.name} Request Resubmitted`;
    message = `${req.id} was resubmitted by ${actor.name} after corrections.`;
  } else {
    title = `${wt.name} Update`; message = `${req.id} was updated.`;
  }
  WorkflowDB.add('notifications', {
    title, message, category:'Approvals', module:'Approvals', priority, channel:'In-App',
    status:'unread', pinned:false, archived:false, createdAt: nowISO(0), readAt:null,
    recipientType: nextLevel ? nextLevel.role : 'Requester', source:'workflow', linkRequestId: req.id
  });
}

