function generateNotificationForModule(mod){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.generateNotificationForModule(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.generateNotificationForModule(mod);
  }

  const sample = MODULE_SAMPLES[mod]();
  const channel = rand(CHANNELS.filter(c=>c!=="FCM" && c!=="OneSignal"));
  WorkflowDB.add("notifications", {
    title: sample.title, message: sample.message, category: mod, module: mod,
    priority: sample.priority, channel, status:"unread", pinned:false, archived:false,
    createdAt: nowISO(0), readAt:null, recipientType:"Role / Guardian", source:"generated"
  });
  addAudit("System","Notification Generated",`${mod}: ${sample.title}`);
}

/* ---------- background engines: scheduler / reminders / escalation ---------- */
function checkScheduler(){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.checkScheduler(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.checkScheduler();
  }

  const due = WorkflowDB.list("schedule").filter(s=> s.status==="pending" && new Date(s.runAt) <= new Date());
  due.forEach(s=>{
    const tpl = WorkflowDB.get("notifTemplates", s.templateId);
    WorkflowDB.add("notifications", {
      title: s.title, message: tpl ? tpl.body.replace(/{{.*?}}/g,"—") : "Scheduled dispatch executed.",
      category: s.category, module: s.category, priority: s.priority, channel: (s.channels&&s.channels[0])||"In-App",
      status:"unread", pinned:false, archived:false, createdAt: nowISO(0), readAt:null,
      recipientType:"Role / Guardian", source:"scheduler"
    });
    addAudit("System","Scheduler Executed", `"${s.title}" dispatched via ${s.channels.join(", ")}`);
    if(s.recurrence === "once"){
      WorkflowDB.update("schedule", s.id, {status:"sent"});
    } else {
      const step = {daily:1440, weekly:1440*7, monthly:1440*30}[s.recurrence] || 1440;
      WorkflowDB.update("schedule", s.id, {runAt: nowISO(step), status:"pending"});
    }
  });
}
function checkReminders(){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.checkReminders(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.checkReminders();
  }

  const due = WorkflowDB.list("reminders").filter(r=> r.status==="pending" && new Date(r.remindAt) <= new Date());
  due.forEach(r=>{
    addAudit("System","Reminder Fired", `${r.title} — ${r.message}`);
    if(r.repeat === "none"){
      WorkflowDB.update("reminders", r.id, {status:"done"});
    } else {
      const step = {daily:1440, weekly:1440*7}[r.repeat] || 1440;
      WorkflowDB.update("reminders", r.id, {remindAt: nowISO(step)});
    }
  });
}
function checkEscalations(){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.checkEscalations(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.checkEscalations();
  }

  const rules = WorkflowDB.list("escalations").filter(e=>e.active);
  if(!rules.length) return;
  const notifs = WorkflowDB.list("notifications").filter(n=> n.status==="unread" && !n.archived && !n.escalated);
  notifs.forEach(n=>{
    const rule = rules.find(r=> r.category===n.category && r.priority===n.priority);
    if(!rule) return;
    const ageMin = (Date.now() - new Date(n.createdAt).getTime())/60000;
    if(ageMin >= rule.thresholdMinutes){
      const bumped = PRIORITIES[Math.min(PRIORITIES.indexOf(n.priority)+1, PRIORITIES.length-1)];
      WorkflowDB.update("notifications", n.id, {priority:bumped, escalated:true});
      addAudit("System","Escalation Applied", `${n.title} bumped to ${bumped} (${rule.escalateTo} notified) — ${rule.action}`);
    }
  });
}

/* ---------- seed data (message templates, rules, scheduler, reminders, escalations, notifications) ---------- */
function buildNotifySeed(){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.buildNotifySeed(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.buildNotifySeed();
  }

  const notifTemplates = [];
  const T = (name,category,priority,channels,subject,body) => notifTemplates.push({
    id: "tpl_"+Math.random().toString(36).slice(2,8), name, category, priority, channels, subject, body,
    variables: (body.match(/{{(.*?)}}/g)||[]).map(v=>v.replace(/[{}]/g,"")),
    createdAt: nowISO(-60*24*10)
  });
  T("Fee Due Reminder","Finance","High",["SMS","Email","In-App"],"Fee Payment Due","Dear {{parentName}}, the fee of ₹{{amount}} for {{studentName}} ({{grade}}) is due on {{dueDate}}. Please pay at the earliest to avoid late fees.");
  T("Attendance Shortage Alert","Attendance","High",["SMS","Email"],"Attendance Below Threshold","{{studentName}}'s attendance has dropped to {{percent}}%, below the required 75% in {{grade}}.");
  T("Admission Confirmation","Admissions","Medium",["Email","WhatsApp"],"Admission Confirmed","Congratulations! {{studentName}} has been admitted to {{grade}} for AY {{year}}. Welcome to our school family.");
  T("Exam Result Published","Examinations","Medium",["Push","Email","In-App"],"Results Declared","Results for {{examName}} have been published. {{studentName}} can view the report card in the parent portal.");
  T("Bus Delay Alert","Transport","Medium",["SMS","Push"],"Bus Running Late","Route {{route}} is delayed by {{minutes}} minutes today due to traffic. Estimated arrival {{eta}}.");
  T("Low Stock Alert","Inventory","Low",["In-App","Email"],"Reorder Level Reached","{{item}} has reached the reorder threshold ({{qty}} units left) in {{store}}.");
  T("Leave Approval Request","Approvals","Medium",["In-App","Email"],"Leave Awaiting Your Approval","{{requester}} has requested {{days}} day(s) leave from {{startDate}}. Please review and approve.");
  T("Circular Published","Communication","Low",["In-App","Push","Email"],"New Circular","A new circular '{{title}}' has been published for {{audience}}.");
  T("Substitute Teacher Assigned","Teachers","Low",["In-App","SMS"],"Substitution Notice","{{teacher}} has been assigned as substitute for {{subject}} in {{grade}} on {{date}}.");
  T("New Student Enrolled","Students","Low",["In-App"],"Welcome New Student","{{studentName}} has been enrolled into {{grade}}, section {{section}}.");

  const rules = [];
  const R = (name,event,category,condition,templateId,channels,active) => rules.push({
    id:"rul_"+Math.random().toString(36).slice(2,8), name, event, category, condition, templateId, channels, active, createdAt: nowISO(-60*24*8)
  });
  R("Auto fee reminder 3 days before due","Fee Due Date -3 Days","Finance","daysBeforeDue == 3", notifTemplates.find(t=>t.name==="Fee Due Reminder").id, ["SMS","Email"], true);
  R("Attendance drop trigger","Attendance % Recalculated","Attendance","percent < 75", notifTemplates.find(t=>t.name==="Attendance Shortage Alert").id, ["SMS","Email"], true);
  R("New admission welcome","Admission Status = Confirmed","Admissions","status == 'confirmed'", notifTemplates.find(t=>t.name==="Admission Confirmation").id, ["Email","WhatsApp"], true);
  R("Result publish broadcast","Exam Result Published","Examinations","resultStatus == 'published'", notifTemplates.find(t=>t.name==="Exam Result Published").id, ["Push","Email"], true);
  R("Low stock watcher","Inventory Qty <= Reorder Level","Inventory","qty <= reorderLevel", notifTemplates.find(t=>t.name==="Low Stock Alert").id, ["In-App"], false);

  const schedule = [
    {id:"sch_1", templateId: notifTemplates.find(t=>t.name==="Fee Due Reminder").id, title:"Monthly fee reminder — Grade 6", runAt: nowISO(45), recurrence:"monthly", status:"pending", category:"Finance", priority:"High", channels:["SMS","Email"]},
    {id:"sch_2", templateId: notifTemplates.find(t=>t.name==="Circular Published").id, title:"Weekly newsletter dispatch", runAt: nowISO(120), recurrence:"weekly", status:"pending", category:"Communication", priority:"Low", channels:["Email","Push"]},
    {id:"sch_3", templateId: notifTemplates.find(t=>t.name==="Attendance Shortage Alert").id, title:"End-of-day attendance sweep", runAt: nowISO(-15), recurrence:"daily", status:"sent", category:"Attendance", priority:"High", channels:["SMS"]}
  ];

  const reminders = [
    {id:"rem_1", title:"Follow up with pending admission enquiries", message:"12 enquiries awaiting document verification.", remindAt: nowISO(90), repeat:"none", status:"pending"},
    {id:"rem_2", title:"Quarterly transport maintenance", message:"Schedule maintenance check for bus fleet.", remindAt: nowISO(-200), repeat:"none", status:"done"},
    {id:"rem_3", title:"Weekly fee collection summary", message:"Send collection summary to Finance Head.", remindAt: nowISO(300), repeat:"weekly", status:"pending"}
  ];

  const escalations = [
    {id:"esc_1", category:"Finance", priority:"High", thresholdMinutes:1440, escalateTo:"Finance Head", action:"Bump to Critical + Email", active:true},
    {id:"esc_2", category:"Approvals", priority:"Medium", thresholdMinutes:720, escalateTo:"Principal", action:"Bump priority + In-App", active:true},
    {id:"esc_3", category:"Transport", priority:"High", thresholdMinutes:60, escalateTo:"Transport Coordinator", action:"SMS escalation", active:false}
  ];

  const notifications = [];
  const seedNotifs = [
    ["Admissions","New Admission Enquiry","Enquiry received from Riya Sharma's parent for Grade 3, session 2026-27.","Medium","In-App",-12,"unread"],
    ["Attendance","Attendance Below 75% Alert","Aarav Mehta (Grade 8-B) attendance has dropped to 68% this term.","High","SMS",-40,"unread"],
    ["Finance","Fee Payment Received","₹18,500 received from Kavya Nair (Grade 5-A) via UPI.","Low","Email",-55,"read"],
    ["Finance","Fee Overdue — Escalation","Fee for Ishaan Verma (Grade 10-C) is 15 days overdue. Escalated to Finance Head.","Critical","SMS",-70,"unread"],
    ["Transport","Bus Delayed on Route 4","Route 4 delayed 20 minutes due to road works near Sector 12.","Medium","Push",-90,"read"],
    ["Inventory","Stock Below Reorder Level","Lab chemistry kits below reorder threshold (4 left) in Central Store.","Low","In-App",-150,"unread"],
    ["Examinations","Result Declared — Mid Term","Mid-term results for Grade 9 published to the parent portal.","Medium","Push",-200,"read"],
    ["Teachers","Leave Request Submitted","Mr. Rohan Kulkarni requested 2 days casual leave from 08 Jul.","Medium","In-App",-30,"unread"],
    ["Students","Disciplinary Note Added","A disciplinary note was logged for a Grade 7-A student by the class teacher.","High","In-App",-260,"read"],
    ["Communication","Circular Published — Annual Day","Annual Day circular published for all parents and staff.","Low","Email",-340,"read"],
    ["Approvals","Purchase Order Awaiting Approval","PO #2291 for sports equipment (₹64,200) awaiting Principal approval.","High","In-App",-800,"unread"],
    ["Admissions","Document Verification Pending","3 admission files pending document verification for Grade 1.","Medium","Email",-500,"archived"],
    ["Finance","Fee Due Reminder","Term 2 fee due in 3 days for 42 students across Grade 6.","High","SMS",-15,"unread"],
    ["Transport","Vehicle Maintenance Due","Bus KA-05-AK-4471 due for scheduled service on 06 Jul.","Medium","In-App",-600,"read"],
    ["Examinations","Hall Ticket Generated","Hall tickets generated for Board Practical Exams, Grade 12.","Medium","Push",-1000,"archived"],
    ["Approvals","Leave Approval Pending","Substitute teacher leave request pending Vice Principal review.","Medium","In-App",-1200,"read"],
  ];
  seedNotifs.forEach((n,i)=>{
    const [category,title,message,priority,channel,offsetMin,state] = n;
    notifications.push({
      id: "not_seed_"+i,
      title, message, category, module:category, priority, channel,
      status: state==="archived" ? "read" : state,
      pinned: i===3 || i===10,
      archived: state==="archived",
      createdAt: nowISO(offsetMin),
      readAt: state==="unread" ? null : nowISO(offsetMin+2),
      recipientType: "Role / Guardian",
      source: "seed"
    });
  });

  const auditEntries = [];
  const A = (actor,action,details,offsetMin) => auditEntries.push({ id: UTIL.uid('AUD'), ts: nowISO(offsetMin), actor, role:'', action, entity:'Notification', entityId:'', details });
  A("System","Rule Triggered","Auto fee reminder 3 days before due → 42 recipients queued",-15);
  A("Priya Menon (Admin)","Notification Archived","Archived: Document Verification Pending",-500);
  A("System","Scheduler Executed","End-of-day attendance sweep dispatched to 6 recipients",-16);
  A("System","Escalation Applied","Fee Overdue — Ishaan Verma bumped to Critical (Finance Head notified)",-70);
  A("Admin","Template Updated","Edited template: Fee Due Reminder",-1440);
  A("System","Integration Test","Twilio SMS test connection succeeded",-2000);

  return { notifTemplates, rules, schedule, reminders, escalations, notifications, auditEntries };
}

/* =============================== ENGINE =================================
   Pure workflow/business logic. Knows nothing about the DOM.
   ========================================================================= */
const ENGINE = (() => {

  async function getWorkflowType(id){ return WorkflowDB.get('workflowTypes', id); }

  function statusOf(req){ return req.status; }

  // Which role is allowed to act on this request right now?
  function requiredRole(req, wt){
    if(req.status !== 'pending') return null;
    const lv = wt.levels[req.currentLevelIndex];
    return lv ? lv.role : null;
  }

  function canAct(req, wt, actingUser){
    if(!actingUser) return false;
    if(actingUser.role === 'Super Admin') return true;
    return requiredRole(req, wt) === actingUser.role;
  }

  async function createRequest({ workflowTypeId, title, data, requestedBy, department, priority, asDraft }){
  // [PHASE-21] Logic moved to Dnyanankur.Services.Communication.createRequest(). This
  // wrapper delegates when the Service has loaded and falls back to the
  // original inline body below otherwise (same pattern as Phase 18/19/20).
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Communication) {
    return Dnyanankur.Services.Communication.createRequest({ workflowTypeId, title, data, requestedBy, department, priority, asDraft });
  }

    const all = await WorkflowDB.getAll('requests');
    const id = UTIL.seqId('WF', all.length + 1);
    const now = new Date().toISOString();
    const req = {
      id, workflowTypeId, title,
      requestedBy: { id:requestedBy.id, name:requestedBy.name, role:requestedBy.role },
      department: department || requestedBy.department,
      priority: priority || 'Normal',
      createdAt: now, updatedAt: now,
      status: asDraft ? 'draft' : 'pending',
      currentLevelIndex: 0,
      returnedFromLevel: null,
      data: data || {},
      history: [{ ts: now, level:0, levelName:'Submission', role: requestedBy.role, actor: requestedBy.name, action:'created', comment: asDraft ? 'Saved as draft.' : 'Request created.' }]
    };
    if(!asDraft){
      req.history.push({ ts: now, level:0, levelName:'Submission', role: requestedBy.role, actor: requestedBy.name, action:'submitted', comment:'Submitted for approval.' });
    }
    await WorkflowDB.add('requests', req);
    await AUDIT.log(requestedBy.name, requestedBy.role, asDraft ? 'draft_saved' : 'submitted', 'Request', id, `${asDraft?'Saved draft':'Submitted'} ${id} — ${title}`);
    if(!asDraft){
      const wt = await getWorkflowType(workflowTypeId);
      notifyFromWorkflow('submitted', req, wt, requestedBy);
    }
    return req;
  }

  async function submitDraft(requestId, actingUser){
    const req = await WorkflowDB.get('requests', requestId);
    if(!req || req.status!=='draft') throw new Error('Only draft requests can be submitted.');
    const now = new Date().toISOString();
    req.history.push({ ts: now, level:0, levelName:'Submission', role: actingUser.role, actor: actingUser.name, action:'submitted', comment:'Submitted for approval.' });
    await WorkflowDB.update('requests', requestId, { status:'pending', currentLevelIndex:0, updatedAt: now, history: req.history });
    await AUDIT.log(actingUser.name, actingUser.role, 'submitted', 'Request', requestId, `Submitted draft ${requestId}`);
    const wtSub = await getWorkflowType(req.workflowTypeId);
    notifyFromWorkflow('submitted', await WorkflowDB.get('requests', requestId), wtSub, actingUser);
    return WorkflowDB.get('requests', requestId);
  }

  async function resubmit(requestId, actingUser){
    const req = await WorkflowDB.get('requests', requestId);
    if(!req || req.status!=='returned') throw new Error('Only returned requests can be resubmitted.');
    const now = new Date().toISOString();
    req.history.push({ ts: now, level:req.currentLevelIndex, levelName:'Resubmission', role: actingUser.role, actor: actingUser.name, action:'resubmitted', comment:'Resubmitted after corrections.' });
    await WorkflowDB.update('requests', requestId, { status:'pending', updatedAt: now, history: req.history, returnedFromLevel:null });
    await AUDIT.log(actingUser.name, actingUser.role, 'resubmitted', 'Request', requestId, `Resubmitted ${requestId}`);
    const wtResub = await getWorkflowType(req.workflowTypeId);
    notifyFromWorkflow('resubmitted', await WorkflowDB.get('requests', requestId), wtResub, actingUser);
    return WorkflowDB.get('requests', requestId);
  }

  async function act(requestId, action, actingUser, comment){
    const req = await WorkflowDB.get('requests', requestId);
    if(!req) throw new Error('Request not found.');
    const wt = await getWorkflowType(req.workflowTypeId);
    if(!canAct(req, wt, actingUser)) throw new Error(`${actingUser.role} is not authorised to act on this request at its current level.`);

    const now = new Date().toISOString();
    const lv = wt.levels[req.currentLevelIndex];
    let patch = { updatedAt: now };

    if(action === 'approve'){
      req.history.push({ ts:now, level:lv.level, levelName:lv.name, role:actingUser.role, actor:actingUser.name, action:'approved', comment: comment || 'Approved.' });
      const nextIndex = req.currentLevelIndex + 1;
      if(nextIndex >= wt.levels.length){
        patch.status = 'approved';
        patch.currentLevelIndex = nextIndex;
      }else{
        patch.currentLevelIndex = nextIndex;
      }
    } else if(action === 'reject'){
      req.history.push({ ts:now, level:lv.level, levelName:lv.name, role:actingUser.role, actor:actingUser.name, action:'rejected', comment: comment || 'Rejected.' });
      patch.status = 'rejected';
    } else if(action === 'return'){
      req.history.push({ ts:now, level:lv.level, levelName:lv.name, role:actingUser.role, actor:actingUser.name, action:'returned', comment: comment || 'Returned for correction.' });
      patch.status = 'returned';
      patch.returnedFromLevel = req.currentLevelIndex;
    } else {
      throw new Error('Unknown action: ' + action);
    }
    patch.history = req.history;
    await WorkflowDB.update('requests', requestId, patch);
    await AUDIT.log(actingUser.name, actingUser.role, action, 'Request', requestId, `${action.toUpperCase()} ${requestId} at ${lv.name}${comment?(' — '+comment):''}`);
    const updatedReq = await WorkflowDB.get('requests', requestId);
    const notifyEvent = action === 'approve' ? 'approved' : action === 'reject' ? 'rejected' : 'returned';
    notifyFromWorkflow(notifyEvent, updatedReq, wt, actingUser, comment);
    return updatedReq;
  }

  async function stats(){
    const requests = await WorkflowDB.getAll('requests');
    const types = await WorkflowDB.getAll('workflowTypes');
    const byStatus = { pending:0, approved:0, rejected:0, returned:0, draft:0 };
    requests.forEach(r => { byStatus[r.status] = (byStatus[r.status]||0) + 1; });

    const byType = types.map(t => ({
      id:t.id, name:t.name,
      count: requests.filter(r=>r.workflowTypeId===t.id).length
    })).sort((a,b)=>b.count-a.count);

    const approvedReqs = requests.filter(r=>r.status==='approved');
    let avgTurnaroundDays = 0;
    if(approvedReqs.length){
      const total = approvedReqs.reduce((sum,r) => sum + UTIL.daysBetween(r.createdAt, r.updatedAt), 0);
      avgTurnaroundDays = total / approvedReqs.length;
    }
    const slaBreaches = requests.filter(r => r.status==='pending' && UTIL.daysBetween(r.createdAt, new Date()) > 3).length;

    const byRole = {};
    requests.forEach(r => {
      r.history.forEach(h => {
        if(['approved','rejected','returned'].includes(h.action)){
          byRole[h.role] = (byRole[h.role]||0)+1;
        }
      });
    });

    const notifList = await WorkflowDB.getAll('notifications');
    const notif = {
      total: notifList.length,
      unread: notifList.filter(n=>n.status==='unread' && !n.archived).length,
      read: notifList.filter(n=>n.status==='read' && !n.archived).length,
      pinned: notifList.filter(n=>n.pinned && !n.archived).length,
      archived: notifList.filter(n=>n.archived).length,
      critical: notifList.filter(n=>n.priority==='Critical' && !n.archived).length,
    };

    return { total: requests.length, byStatus, byType, avgTurnaroundDays, slaBreaches, byRole, notif };
  }

  return { getWorkflowType, requiredRole, canAct, createRequest, submitDraft, resubmit, act, stats };
})();

/* =============================== STATE ================================== */
