  /* ================= ROLE BASED APPROVAL ================= */
  async function renderRoleApproval(){
    const view = document.getElementById('view');
    const types = await WorkflowDB.getAll('workflowTypes');
    const roles = await WorkflowDB.getAll('roles');
    view.innerHTML = `
      <div class="view-header"><div><h2>Role Based Approval</h2><div class="wf-sub">Which roles are authorised to approve at each workflow type. "Super Admin" can act at any level.</div></div></div>
      <div class="panel matrix-wrap">
        <table class="matrix">
          <thead><tr><th>Role</th>${types.map(t=>`<th title="${UTIL.escapeHtml(t.name)}">${t.code}</th>`).join('')}</tr></thead>
          <tbody>
            ${roles.map(r => `
              <tr>
                <td>${UTIL.escapeHtml(r.name)}</td>
                ${types.map(t => {
                  const on = r.name==='Super Admin' || t.levels.some(lv=>lv.role===r.name);
                  return `<td><span class="matrix-dot ${on?'on':''}" title="${on?'Authorised':'Not involved'}"></span></td>`;
                }).join('')}
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
      <div class="panel">
        <h3>Roles</h3>
        <div class="panel-sub">All roles known to the workflow engine</div>
        <div class="level-chip-row">${roles.map(r=>`<span class="level-chip"><span class="idx">${ICONS.role}</span>${UTIL.escapeHtml(r.name)}</span>`).join('')}</div>
      </div>
    `;
  }

