const INT_META = {
  sms:{name:"SMS Gateway", icon:"💬", color:"#0fb5a6", fields:[["provider","Provider"],["accountSid","Account SID"],["authToken","Auth Token"],["senderId","Sender ID"]]},
  whatsapp:{name:"WhatsApp Business", icon:"🟢", color:"#25d366", fields:[["provider","Provider"],["accountSid","Account SID"],["authToken","Auth Token"],["senderId","Sender / Phone ID"]]},
  email:{name:"Email (SMTP/SendGrid)", icon:"✉️", color:"#e0722c", fields:[["provider","Provider"],["apiKey","API Key"],["fromAddress","From Address"]]},
  push:{name:"Web Push", icon:"📱", color:"#5b5ff0", fields:[["provider","Provider"],["publicKey","VAPID Public Key"],["privateKey","VAPID Private Key"]]},
  fcm:{name:"Firebase Cloud Messaging", icon:"🔥", color:"#e6a319", fields:[["provider","Provider"],["serverKey","Server Key"],["projectId","Project ID"]]},
  onesignal:{name:"OneSignal", icon:"🅾️", color:"#8a5cf6", fields:[["provider","Provider"],["appId","App ID"],["apiKey","REST API Key"]]},
};
async function wfRenderIntegrations(){
  const view = document.getElementById('view');
  const cfg = WorkflowDB.data.integrations;
  view.innerHTML = `
    <div class="view-header"><div><h2>Integrations</h2><div class="wf-sub">Connect delivery channels. Credentials are stored locally for this demo — wire up real secrets when integrating with a backend.</div></div></div>
    <div class="grid g3">
      ${Object.keys(INT_META).map(key => {
        const meta = INT_META[key]; const c = cfg[key];
        const status = c.enabled ? (c.status==='on' ? 'on' : 'cfg') : 'off';
        const statusLabel = status==='on' ? 'Connected' : status==='cfg' ? 'Needs Test' : 'Disabled';
        return `
        <div class="card int-card">
          <div class="int-head">
            <div class="int-icon" style="background:${meta.color}">${meta.icon}</div>
            <div><div class="int-name">${meta.name}</div><span class="int-status ${status}">${statusLabel}</span></div>
            <span class="toggle ${c.enabled?'on':''}" style="margin-left:auto;" onclick="toggleIntegration('${key}')"></span>
          </div>
          <div class="int-desc">Provider used for ${meta.name.toLowerCase()} delivery across templates, rules, and the scheduler.</div>
          <div class="int-fields">
            ${meta.fields.map(([f,label]) => `<input type="text" placeholder="${label}" data-int="${key}" data-field="${f}" value="${escapeAttr(c[f]||'')}">`).join('')}
          </div>
          <div class="int-foot">
            <button class="btn btn-sm" onclick="saveIntegration('${key}')">Save</button>
            <button class="btn btn-sm btn-ghost" onclick="testIntegration('${key}')">Test Connection</button>
          </div>
        </div>`;
      }).join('')}
    </div>
  `;
}
function toggleIntegration(key){
  const cfg = WorkflowDB.data.integrations;
  cfg[key].enabled = !cfg[key].enabled;
  if(!cfg[key].enabled) cfg[key].status = 'off';
  WorkflowDB.persist();
  addAudit("Admin", cfg[key].enabled?"Integration Enabled":"Integration Disabled", INT_META[key].name);
  UI.route('integrations');
}
function saveIntegration(key){
  const cfg = WorkflowDB.data.integrations;
  document.querySelectorAll(`[data-int="${key}"]`).forEach(inp => { cfg[key][inp.dataset.field] = inp.value; });
  if(cfg[key].enabled && cfg[key].status==='off') cfg[key].status = 'cfg';
  WorkflowDB.persist();
  addAudit("Admin","Integration Settings Saved", INT_META[key].name);
  wfToast(INT_META[key].name + " settings saved","success");
}
function testIntegration(key){
  const cfg = WorkflowDB.data.integrations;
  if(!cfg[key].enabled){ wfToast("Enable the integration before testing","error"); return; }
  cfg[key].status = 'on';
  WorkflowDB.persist();
  addAudit("System","Integration Test", INT_META[key].name + " test connection succeeded");
  wfToast(INT_META[key].name + " test connection succeeded","success");
  UI.route('integrations');
}

