function daysUntil(d){
  // [PHASE-28A] Logic moved to Dnyanankur.Services.Documents.daysUntil(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Documents) {
    return Dnyanankur.Services.Documents.daysUntil(d);
  }
  if(!d) return null;
  const dt = (d instanceof Date) ? d : new Date(d);
  return Math.ceil((dt - new Date()) / 86400000);
}
function dmsTimeAgo(d){
  // [PHASE-28A] Logic moved to Dnyanankur.Services.Documents.dmsTimeAgo(). This
  // wrapper delegates when the service is installed; original
  // implementation below is preserved as the fallback.
  if (window.Dnyanankur && Dnyanankur.Services && Dnyanankur.Services.Documents) {
    return Dnyanankur.Services.Documents.dmsTimeAgo(d);
  }
  const dt = (d instanceof Date) ? d : new Date(d);
  const diff = Math.floor((new Date() - dt)/60000);
  if(diff < 1) return "just now";
  if(diff < 60) return diff+"m ago";
  if(diff < 1440) return Math.floor(diff/60)+"h ago";
  return Math.floor(diff/1440)+"d ago";
}

