/* ================================================================
   CSV EXPORT
================================================================ */
function dmsExportCSV(rows, filename){
  if(!rows.length){ dmsToast("Nothing to export","warn"); return; }
  const isDoc = rows[0].hasOwnProperty("title") && rows[0].hasOwnProperty("category");
  let data = rows;
  let headers;
  if(isDoc){
    headers = ["id","title","category","owner","ownerType","status","tags","expiryDate","currentVersion","uploadedDate"];
    data = rows.map(d=>({
      id:d.id, title:d.title, category:(DB.getCategory(d.category)||{}).label, owner:d.owner, ownerType:d.ownerType,
      status:d.status, tags:(d.tags||[]).join("|"), expiryDate: d.expiryDate?dmsFmtDate(d.expiryDate):"", currentVersion:d.currentVersion, uploadedDate: dmsFmtDate(d.uploadedDate)
    }));
  } else {
    headers = Object.keys(rows[0]);
  }
  const csv = [headers.join(",")].concat(data.map(r=>headers.map(h=>`"${String(r[h]??"").replace(/"/g,'""')}"`).join(","))).join("\n");
  const blob = new Blob([csv], {type:"text/csv"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
}

