      generatedAt: new Date().toISOString(),
      generatedBy: opts.generatedBy || ((typeof currentUser !== 'undefined' && currentUser) ? (currentUser.name || currentUser.username) : 'system'),
      deliberateRegeneration: !!opts.deliberate
