/* ═══════════════════════════════════════════════════════════════
   EXAM-2.36 — AcademicEngine.Calculation
   ───────────────────────────────────────────────────────────────
   Purely additive, read-only computation helpers. Does NOT touch
   any UI, does NOT modify report cards / Parent Portal / Examination
   Centre pages, does NOT replace or monkey-patch any existing
   function, and does NOT save/write anything to storage.

   Reads ONLY from: examMod_marks_* (per subjectMap-row marks),
   examMod_subjectMap, examMod_examinations, examMod_gradeScales.
   (Student roster is intentionally NOT read from 'students' — the
   set of students for a class/exam is derived from whichever
   studentIds already have saved marks, keeping this module scoped
   to exactly the four permitted stores.)

   Formulas below are copied verbatim from examComputeSubjectResult,
   examRecomputeResultsForClass and examCalcGrade/examCalcGradePoints
   (Section — Marks Engine / Grade Scales) so results are identical
   to what the Examination Centre itself computes. Nothing here
   changes those formulas.
═══════════════════════════════════════════════════════════════ */
(function (global) {
  'use strict';

  var PREFIX = 'examMod_';

  var AC_DEFAULT_GRADE_SCALE = {
    id: 'gs_default',
    name: 'Standard 10-Grade Scale',
    grades: [
      { grade: 'A+', minPct: 90, maxPct: 100, points: 10, remark: 'Outstanding' },
      { grade: 'A',  minPct: 80, maxPct: 89,  points: 9,  remark: 'Excellent' },
      { grade: 'B+', minPct: 70, maxPct: 79,  points: 8,  remark: 'Very Good' },
      { grade: 'B',  minPct: 60, maxPct: 69,  points: 7,  remark: 'Good' },
      { grade: 'C+', minPct: 50, maxPct: 59,  points: 6,  remark: 'Above Average' },
      { grade: 'C',  minPct: 40, maxPct: 49,  points: 5,  remark: 'Average' },
      { grade: 'D',  minPct: 35, maxPct: 39,  points: 4,  remark: 'Pass' },
      { grade: 'E',  minPct: 20, maxPct: 34,  points: 2,  remark: 'Needs Improvement' },
      { grade: 'F',  minPct: 0,  maxPct: 19,  points: 0,  remark: 'Fail' }
    ]
  };

  // Read-only fetch from one of the four permitted stores. Prefers the
  // module's own examRetrieve() (identical read path) so behavior can
  // never drift; falls back to a direct, equivalent read if unavailable.
  function acRetrieve(key, fallback) {
    if (typeof global.examRetrieve === 'function') {
      try { return global.examRetrieve(key, fallback); } catch (e) { /* fall through */ }
    }
    try {
      if (global.Dnyanankur && global.Dnyanankur.Storage && typeof global.Dnyanankur.Storage.get === 'function') {
        var v = global.Dnyanankur.Storage.get(PREFIX + key);
        return (v === null || v === undefined) ? fallback : v;
      }
      var raw = localStorage.getItem(PREFIX + key);
      if (raw === null || raw === undefined) return fallback;
      return JSON.parse(raw);
    } catch (e) { return fallback; }
  }

  function acRound(n, places) {
    places = places === undefined ? 2 : places;
    return Math.round(n * Math.pow(10, places)) / Math.pow(10, places);
  }

  function acGradeScale(scaleId) {
    var scales = acRetrieve('gradeScales', [AC_DEFAULT_GRADE_SCALE]);
    var scale = (scaleId ? scales.find(function (s) { return s.id === scaleId; }) : null)
      || scales[0] || AC_DEFAULT_GRADE_SCALE;
    return (scale && scale.grades) ? scale : AC_DEFAULT_GRADE_SCALE;
  }

  // Mirrors examCalcGrade() exactly.
  function computeOverallGrade(pct, scaleId) {
    var scale = acGradeScale(scaleId || '');
    var match = scale.grades.find(function (g) { return pct >= g.minPct && pct <= g.maxPct; });
    return match ? match.grade : '—';
  }

  // Mirrors examCalcGradePoints() exactly.
  function acGradePoints(pct, scaleId) {
    var scale = acGradeScale(scaleId || '');
    var match = scale.grades.find(function (g) { return pct >= g.minPct && pct <= g.maxPct; });
    return match ? match.points : 0;
  }

  function acExam(examId) {
    return acRetrieve('examinations', []).find(function (e) { return e.id === examId; }) || null;
  }

  function acSubjectMaps(examId, className) {
    return acRetrieve('subjectMap', []).filter(function (m) {
      return m.examId === examId && m.className === className;
    });
  }

  // Mirrors the per-student block inside examRecomputeResultsForClass()
  // exactly (same total/max/pct/pass-fail/grade/points logic), returning
  // the computed object instead of writing it to examMod_results.
  function computeStudentResult(examId, className, studentId) {
    var exam = acExam(examId);
    if (!exam || !className || !studentId) return null;
    var maps = acSubjectMaps(examId, className);
    if (!maps.length) return null;

    var totalMarks = 0, maxTotal = 0, failAny = false, absentAny = false, foundAny = false;
    var subjectResults = {}, name = null, admissionNo = null;

    maps.forEach(function (sm) {
      var marksKey = 'marks_' + examId + '_' + className + '_' + sm.division + '_' + sm.id;
      var savedMarks = acRetrieve(marksKey, {});
      var m = savedMarks[studentId];
      if (!m) return;
      foundAny = true;
      if (name === null) { name = m.name || null; admissionNo = m.admissionNo || null; }
      subjectResults[sm.subjectName] = m;
      if (m.absent) { absentAny = true; }
      else {
        totalMarks += m.total || 0;
        maxTotal += (sm.theoryMax || 0) + (sm.practMax || 0) + (sm.intMax || 0);
        if (m.result === 'Fail') failAny = true;
      }
    });

    if (!foundAny) return null;

    var pct = maxTotal > 0 ? acRound((totalMarks / maxTotal) * 100) : 0;
    var result = absentAny ? 'Absent' : (failAny ? 'Fail' : 'Pass');
    var grade = result === 'Absent' ? 'AB' : computeOverallGrade(pct, exam.gradeScaleId || '');
    var points = result === 'Absent' ? 0 : acGradePoints(pct, exam.gradeScaleId || '');

    return {
      studentId: studentId, name: name, admissionNo: admissionNo,
      examId: examId, className: className,
      totalMarks: acRound(totalMarks), maxTotal: maxTotal, pct: pct,
      grade: grade, points: points, result: result, subjectResults: subjectResults
    };
  }

  // Mirrors examRecomputeResultsForClass()'s per-class computation +
  // within-class ranking exactly, scoped to one exam+class, returned
  // (not written to examMod_results).
  function computeClassResults(examId, className) {
    var exam = acExam(examId);
    if (!exam || !className) return { examId: examId, className: className, students: [] };
    var maps = acSubjectMaps(examId, className);

    var studentIds = {};
    maps.forEach(function (sm) {
      var marksKey = 'marks_' + examId + '_' + className + '_' + sm.division + '_' + sm.id;
      var savedMarks = acRetrieve(marksKey, {});
      Object.keys(savedMarks).forEach(function (sid) { studentIds[sid] = true; });
    });

    var students = Object.keys(studentIds)
      .map(function (sid) { return computeStudentResult(examId, className, sid); })
      .filter(Boolean);

    students.sort(function (a, b) { return b.pct - a.pct; });
    students.forEach(function (s, i) { s.classRank = s.result === 'Absent' ? 999 : i + 1; });

    return { examId: examId, className: className, studentCount: students.length, students: students };
  }

  // Lightweight diagnostics — presence/read checks + one sample
  // computation if any real data is available. Does not write anything.
  function test() {
    var checks = {
      'examMod_marks_* readable':  true,
      'examMod_subjectMap readable': true,
      'examMod_examinations readable': true,
      'examMod_gradeScales readable': true,
      'computeStudentResult is a function': typeof computeStudentResult === 'function',
      'computeClassResults is a function': typeof computeClassResults === 'function',
      'computeOverallGrade is a function': typeof computeOverallGrade === 'function'
    };
    var sample = null;
    try {
      var maps = acRetrieve('subjectMap', []);
      checks['examMod_subjectMap readable'] = Array.isArray(maps);
      checks['examMod_examinations readable'] = Array.isArray(acRetrieve('examinations', []));
      checks['examMod_gradeScales readable'] = Array.isArray(acRetrieve('gradeScales', [AC_DEFAULT_GRADE_SCALE]));
      if (maps.length) {
        var first = maps[0];
        var cr = computeClassResults(first.examId, first.className);
        sample = { examId: first.examId, className: first.className, studentCount: cr.studentCount };
      }
    } catch (e) {
      checks['no exceptions thrown'] = false;
    }
    return {
      checkedAt: new Date().toISOString(),
      module: 'AcademicEngine.Calculation',
      checks: checks,
      allPass: Object.keys(checks).every(function (k) { return checks[k]; }),
      sample: sample,
      note: 'Read-only diagnostics. Computes but never saves.'
    };
  }

  global.AcademicEngine = global.AcademicEngine || {};
  global.AcademicEngine.Calculation = {
    computeStudentResult: computeStudentResult,
    computeClassResults: computeClassResults,
    computeOverallGrade: computeOverallGrade,
    test: test
  };

})(window);


