/* ═══════════════════════════════════════════════════════════════
   EXAM-2.37 — AcademicEngine.Ranking
   ───────────────────────────────────────────────────────────────
   Purely additive, read-only ranking helpers. Does NOT touch any
   UI, does NOT modify report cards / Parent Portal / Examination
   Centre pages, does NOT save/write anything to storage, does NOT
   monkey-patch or wrap any existing function, and does NOT replace
   the legacy classRank/schoolRank already written by
   examRecomputeResultsForClass, nor the EXAM-2.3 AcademicEngine.Rank
   shadow namespace — both are left completely untouched.

   Reads ONLY from: examMod_marks_* (per subjectMap-row marks),
   examMod_subjectMap, examMod_examinations, examMod_gradeScales —
   via AcademicEngine.Calculation (EXAM-2.36), which already owns
   those reads and the underlying result formulas, plus one direct
   read of examMod_subjectMap here (a permitted store) to group
   students by division for computeDivisionRank. No formula is
   duplicated: every percentage/grade/result value used below comes
   straight from AcademicEngine.Calculation's own output.
═══════════════════════════════════════════════════════════════ */
(function (global) {
  'use strict';

  var PREFIX = 'examMod_';

  function acRetrieve(key, fallback) {
    if (typeof global.examRetrieve === 'function') {
      try { return global.examRetrieve(key, fallback); } catch (e) { /* fall through */ }
    }
    try {
      if (global.Dnyanankur && global.Dnyanankur.Storage && typeof global.Dnyanankur.Storage.get === 'function') {
        var v = global.Dnyanankur.Storage.get(PREFIX + key);
        return (v === null || v === undefined) ? fallback : v;
      }
      var raw = localStorage.getItem(PREFIX + key);
      if (raw === null || raw === undefined) return fallback;
      return JSON.parse(raw);
    } catch (e) { return fallback; }
  }

  function calc() { return global.AcademicEngine && global.AcademicEngine.Calculation; }

  function subjectMapsFor(examId, className) {
    return acRetrieve('subjectMap', []).filter(function (m) {
      return m.examId === examId && (!className || m.className === className);
    });
  }

  function classesForExam(examId) {
    var maps = acRetrieve('subjectMap', []).filter(function (m) { return m.examId === examId; });
    return Array.from(new Set(maps.map(function (m) { return m.className; })));
  }

  function slim(s) {
    return { studentId: s.studentId, name: s.name, admissionNo: s.admissionNo, pct: s.pct, result: s.result };
  }

  function rankByPct(list) {
    list.sort(function (a, b) { return b.pct - a.pct; });
    list.forEach(function (s, i) { s.rank = s.result === 'Absent' ? 999 : i + 1; });
    return list;
  }

  // Within-class rank. Mirrors AcademicEngine.Calculation.computeClassResults's
  // own ranking exactly (that function already sorts + assigns classRank) —
  // this simply reads and reshapes that read-only output.
  function computeClassRank(examId, className) {
    var c = calc();
    if (!c || !examId || !className) return { examId: examId, className: className, students: [] };
    var res = c.computeClassResults(examId, className);
    var students = (res.students || []).map(function (s) {
      var out = slim(s); out.classRank = s.classRank; return out;
    });
    return { examId: examId, className: className, studentCount: students.length, students: students };
  }

  // Within-division rank (new — no legacy equivalent). Division membership
  // is derived from which subjectMap-row division a student's marks were
  // saved under; the student's overall pct/result still comes from
  // computeStudentResult (all their subjects, every division).
  function computeDivisionRank(examId, className, division) {
    var c = calc();
    if (!c || !examId || !className) return { examId: examId, className: className, divisions: {} };
    var byDiv = {};
    subjectMapsFor(examId, className).forEach(function (sm) {
      var d = sm.division || 'All';
      if (division && d !== division) return;
      var marksKey = 'marks_' + examId + '_' + className + '_' + d + '_' + sm.id;
      Object.keys(acRetrieve(marksKey, {})).forEach(function (sid) {
        (byDiv[d] = byDiv[d] || {})[sid] = true;
      });
    });
    var divisions = {};
    Object.keys(byDiv).forEach(function (d) {
      var list = Object.keys(byDiv[d])
        .map(function (sid) { return c.computeStudentResult(examId, className, sid); })
        .filter(Boolean).map(slim);
      rankByPct(list).forEach(function (s) { s.divisionRank = s.rank; delete s.rank; });
      divisions[d] = list;
    });
    return { examId: examId, className: className, division: division || null, divisions: divisions };
  }

  // Across-school rank (new — no legacy equivalent). Defaults to every
  // class found for the exam in examMod_subjectMap if classNames omitted.
  function computeSchoolRank(examId, classNames) {
    var c = calc();
    if (!c || !examId) return { examId: examId, classes: [], students: [] };
    var classes = (classNames && classNames.length) ? classNames : classesForExam(examId);
    var all = [];
    classes.forEach(function (cls) {
      (c.computeClassResults(examId, cls).students || []).forEach(function (s) {
        var out = slim(s); out.className = cls; all.push(out);
      });
    });
    rankByPct(all).forEach(function (s) { s.schoolRank = s.rank; delete s.rank; });
    return { examId: examId, classes: classes, studentCount: all.length, students: all };
  }

  // Lightweight diagnostics — presence/read checks + one sample computation
  // if any real data is available. Does not write anything.
  function test() {
    var checks = {
      'AcademicEngine.Calculation loaded': !!calc(),
      'computeClassRank is a function': typeof computeClassRank === 'function',
      'computeDivisionRank is a function': typeof computeDivisionRank === 'function',
      'computeSchoolRank is a function': typeof computeSchoolRank === 'function'
    };
    var sample = null;
    try {
      var maps = acRetrieve('subjectMap', []);
      if (maps.length && calc()) {
        var first = maps[0];
        sample = {
          examId: first.examId, className: first.className,
          classRank: computeClassRank(first.examId, first.className).studentCount,
          divisionRank: Object.keys(computeDivisionRank(first.examId, first.className).divisions).length,
          schoolRank: computeSchoolRank(first.examId, [first.className]).studentCount
        };
      }
    } catch (e) {
      checks['no exceptions thrown'] = false;
    }
    return {
      checkedAt: new Date().toISOString(),
      module: 'AcademicEngine.Ranking',
      checks: checks,
      allPass: Object.keys(checks).every(function (k) { return checks[k]; }),
      sample: sample,
      note: 'Read-only diagnostics. Computes but never saves; never touches AcademicEngine.Rank or legacy ranks.'
    };
  }

  global.AcademicEngine = global.AcademicEngine || {};
  global.AcademicEngine.Ranking = {
    computeClassRank: computeClassRank,
    computeDivisionRank: computeDivisionRank,
    computeSchoolRank: computeSchoolRank,
    test: test
  };

})(window);


