/* ═══════════════════════════════════════════════════════════════
   EXAM-2.6B-1 — AcademicEngine.Promotion.computeStudent(studentResult, promotionConfig)
   ───────────────────────────────────────────────────────────────
   Purely additive, pure-function promotion evaluator.

   Does NOT modify:
     - runPromotion() (Core ERP) — never called, never touched
     - any existing AcademicEngine.Promotion member — .suggest
       (EXAM-2.3) is untouched; this only adds .computeStudent
       alongside it
     - AcademicEngine.PromotionEngine (EXAM-2.38) — separate,
       untouched module
     - students, report cards, examMod_results — never written

   This is a PURE function: its only inputs are the two arguments.
   Unlike AcademicEngine.Promotion.suggest() (EXAM-2.3) or
   AcademicEngine.PromotionEngine.computePromotionSuggestion()
   (EXAM-2.38) — both of which look up examId/className/studentId
   in storage and call AttEngine themselves — computeStudent() reads
   nothing from storage, calls no other engine, and does not accept
   IDs to look anything up with. It only evaluates the two objects
   it is handed. See compatibility report for the field-shape
   assumptions this required, since no existing function has this
   exact (studentResult, promotionConfig) pure signature to mirror.

   No localStorage / examStore / examMod_results writes.
   No console output. No DOM/UI. No other side effects.
═══════════════════════════════════════════════════════════════ */
(function (global) {
  'use strict';

  function computeStudent(studentResult, promotionConfig) {
    // Spec: "If config missing, return eligible:true."
    if (!promotionConfig) {
      return {
        eligible: true,
        reasons: ['No promotion configuration supplied — nothing to evaluate against.'],
        attendanceOk: true,
        marksOk: true,
        compulsorySubjectsOk: true,
        graceApplied: false
      };
    }

    var sr = studentResult || {};
    var cfg = promotionConfig;
    var reasons = [];

    // Tolerant of either the EXAM-2.5A computeClassResults field names
    // (percentage / passFail / subjectTotals) or the legacy field names
    // (pct / result / subjectResults) — never reads storage either way.
    var pct = (typeof sr.percentage === 'number') ? sr.percentage
             : (typeof sr.pct === 'number' ? sr.pct : null);
    var passFail = sr.passFail || sr.result || null;
    var isAbsent = passFail === 'Absent';

    var subjectMap = sr.subjectTotals || sr.subjectResults || {};
    var subjectNames = Object.keys(subjectMap);
    var failSubjectCount = (typeof sr.failSubjectCount === 'number')
      ? sr.failSubjectCount
      : subjectNames.filter(function (n) { return subjectMap[n] && subjectMap[n].result === 'Fail'; }).length;

    // --- marks rule: minPercent + maxFailSubjectCount, with grace ---
    // Grace is applied only when it is the reason a below-minimum
    // percentage crosses the line — graceApplied is only ever true
    // when grace marks actually changed the outcome, not just because
    // graceMarks > 0 was configured.
    var graceApplied = false;
    var pctOk = true;
    if (cfg.minPercent != null && pct != null) {
      pctOk = pct >= cfg.minPercent;
      if (!pctOk && cfg.graceMarks) {
        var withGrace = pct + cfg.graceMarks;
        if (withGrace >= cfg.minPercent) { pctOk = true; graceApplied = true; }
      }
      if (!pctOk) {
        reasons.push('Percentage ' + pct + '% is below the configured minimum of ' + cfg.minPercent + '%' +
          (cfg.graceMarks ? ' even after ' + cfg.graceMarks + ' grace mark(s).' : '.'));
      }
    }

    var failOk = (cfg.maxFailSubjectCount == null) || (failSubjectCount <= cfg.maxFailSubjectCount);
    if (!failOk) {
      reasons.push('Failed ' + failSubjectCount + ' subject(s), exceeding the configured limit of ' + cfg.maxFailSubjectCount + '.');
    }

    var marksOk = pctOk && failOk;

    // --- compulsory subjects ---
    var compulsorySubjectsOk = true;
    (cfg.compulsorySubjects || []).forEach(function (subName) {
      var rec = subjectMap[subName];
      if (rec && rec.result === 'Fail') {
        compulsorySubjectsOk = false;
        reasons.push('Failed compulsory subject: ' + subName + '.');
      }
    });

    // --- attendance: pure function, so this ONLY reads
    // studentResult.attendancePct if the caller supplied it. It never
    // calls AttEngine or any date-range helper itself (that would not
    // be a pure function of the two arguments given).
    var attendanceOk = true;
    if (cfg.minAttendancePct != null) {
      if (typeof sr.attendancePct === 'number') {
        attendanceOk = sr.attendancePct >= cfg.minAttendancePct;
        if (!attendanceOk) {
          reasons.push('Attendance ' + sr.attendancePct + '% is below the configured minimum of ' + cfg.minAttendancePct + '%.');
        }
      } else {
        reasons.push('minAttendancePct is configured but studentResult.attendancePct was not supplied — attendance rule skipped (pure function, does not read AttEngine).');
      }
    }

    if (isAbsent) reasons.push('Student result is Absent for this examination.');

    var eligible = !isAbsent && marksOk && compulsorySubjectsOk && attendanceOk;
    if (reasons.length === 0) reasons.push('Meets all configured promotion criteria.');

    return {
      eligible: eligible,
      reasons: reasons,
      attendanceOk: attendanceOk,
      marksOk: marksOk,
      compulsorySubjectsOk: compulsorySubjectsOk,
      graceApplied: graceApplied
    };
  }

  // ============================================================
  // INSTALL — additive only. Adds ONE new method, .computeStudent,
  // to AcademicEngine.Promotion without touching .suggest (EXAM-2.3)
  // or AcademicEngine.PromotionEngine (EXAM-2.38).
  // ============================================================
  function install() {
    global.AcademicEngine = global.AcademicEngine || {};
    global.AcademicEngine.Promotion = global.AcademicEngine.Promotion || {};
    if (typeof global.AcademicEngine.Promotion.computeStudent === 'function') return true; // never overwrite
    global.AcademicEngine.Promotion.computeStudent = computeStudent;
    return true;
  }

  install();

})(window);


