/* ═══════════════════════════════════════════════════════════════
   Marks Store V1 — AcademicEngine.Marks
   ───────────────────────────────────────────────────────────────
   Purely additive module. Creates the new namespace
   AcademicEngine.Marks (does not exist anywhere else in this file)
   as a clean, modular read/write API over the SAME per-subject
   marks records the Marks Entry screens already create — the
   `marks_{examId}_{className}_{division}_{mapId}` keys written by
   examMarksEngineSave() (Sprint 7.4 — the one canonical write path
   already shared by the Classic grid, Single-Student View and
   Quick Term Entry's per-exam mirror). Same pattern already used
   by AcademicEngine.Exams / AcademicEngine.Subjects: no new storage
   key, no duplicate copy of data, just a proper API surface over
   the array that already exists.

   Does NOT change examMarksEngineSave()'s validation, totals,
   pass/fail or grade formula (examComputeSubjectResult) — that
   canonical logic is deliberately left untouched to avoid the exact
   kind of "three independent re-implementations drift apart" bug
   Sprint 7.4 already fixed once. AcademicEngine.Marks is a read/
   write proxy over the same records, not a second engine.

   Public API (AcademicEngine.Marks):
     keyFor(examId, className, division, mapId)      → string
     lockKeyFor(examId, className, division, mapId)  → string
     getAll(examId, className, division, mapId)      → { studentId: record }
     get(examId, className, division, mapId, studentId) → record|null
     saveAll(examId, className, division, mapId, recordsObj) → boolean
     saveEntry(examId, className, division, mapId, studentId, patch) → record
     isLocked(examId, className, division, mapId)    → boolean
     setLocked(examId, className, division, mapId, locked) → boolean
═══════════════════════════════════════════════════════════════ */
(function (global) {
  'use strict';

  function readKey(key, fallback) {
    if (typeof global.examRetrieve === 'function') {
      try { return global.examRetrieve(key, fallback); } catch (e) { /* fall through */ }
    }
    if (global.Dnyanankur && global.Dnyanankur.Storage && typeof global.Dnyanankur.Storage.get === 'function') {
      try {
        var v = global.Dnyanankur.Storage.get('examMod_' + key);
        return v === undefined || v === null ? fallback : v;
      } catch (e) { /* fall through */ }
    }
    try {
      var raw = global.localStorage.getItem('examMod_' + key);
      return raw ? JSON.parse(raw) : fallback;
    } catch (e) { return fallback; }
  }

  function writeKey(key, value) {
    if (typeof global.examStore === 'function') {
      try { global.examStore(key, value); return true; } catch (e) { /* fall through */ }
    }
    if (global.Dnyanankur && global.Dnyanankur.Storage && typeof global.Dnyanankur.Storage.set === 'function') {
      try { global.Dnyanankur.Storage.set('examMod_' + key, value); return true; } catch (e) { /* fall through */ }
    }
    try { global.localStorage.setItem('examMod_' + key, JSON.stringify(value)); return true; }
    catch (e) { return false; }
  }

  function keyFor(examId, className, division, mapId) {
    return 'marks_' + examId + '_' + className + '_' + division + '_' + mapId;
  }
  function lockKeyFor(examId, className, division, mapId) {
    return 'marksLock_' + examId + '_' + className + '_' + division + '_' + mapId;
  }

  function getAll(examId, className, division, mapId) {
    var data = readKey(keyFor(examId, className, division, mapId), {});
    // Return a shallow clone (per Exams/Subjects convention) so callers
    // cannot mutate the underlying store without going through saveAll/saveEntry.
    var clone = {};
    Object.keys(data || {}).forEach(function (k) { clone[k] = Object.assign({}, data[k]); });
    return clone;
  }

  function get(examId, className, division, mapId, studentId) {
    var all = getAll(examId, className, division, mapId);
    return all[studentId] || null;
  }

  function saveAll(examId, className, division, mapId, recordsObj) {
    return writeKey(keyFor(examId, className, division, mapId), recordsObj || {});
  }

  function saveEntry(examId, className, division, mapId, studentId, patch) {
    var all = getAll(examId, className, division, mapId);
    all[studentId] = Object.assign({}, all[studentId] || {}, patch || {}, { studentId: studentId });
    saveAll(examId, className, division, mapId, all);
    return all[studentId];
  }

  function isLocked(examId, className, division, mapId) {
    return !!readKey(lockKeyFor(examId, className, division, mapId), false);
  }

  function setLocked(examId, className, division, mapId, locked) {
    return writeKey(lockKeyFor(examId, className, division, mapId), !!locked);
  }

  global.AcademicEngine = global.AcademicEngine || {};
  global.AcademicEngine.Marks = {
    keyFor: keyFor,
    lockKeyFor: lockKeyFor,
    getAll: getAll,
    get: get,
    saveAll: saveAll,
    saveEntry: saveEntry,
    isLocked: isLocked,
    setLocked: setLocked
  };

})(window);


/* ===================== next inline <script> block ===================== */


/* ═══════════════════════════════════════════════════════════════
   Marks Entry Upgrade V1
   ───────────────────────────────────────────────────────────────
   1) DROPDOWN SOURCING — meExam / meClass / meDivision / meSubject
      (and qteClass / qteSubject) now resolve their option lists via
      AcademicEngine.Exams and AcademicEngine.Subjects instead of the
      raw examRetrieve('examinations'/'subjectMap') calls. Because
      those namespaces are themselves thin proxies over the exact
      same 'examMod_examinations' / 'examMod_subjectMap' arrays (see
      EXAM-EXAMSTORE-V2 / EXAM-SUBJECTMAP-V2 above), the option lists
      rendered are byte-for-byte identical to before — this changes
      the DATA PATH only, never the markup, order, or values shown.

   2) GRID READS — examLoadMarksGrid now loads existing marks and
      lock state via AcademicEngine.Marks.getAll()/isLocked() instead
      of calling examRetrieve() directly for those two lookups. Same
      key, same shape, same rendered table — only the read path
      changes.

   3) UX LAYER (new capability, event-delegated, zero HTML changes):
        - Autosave: 1.2s after the last edit inside a marks grid, the
          screen's own existing Save function is invoked automatically
          (examSaveMarks / qteSaveAll / examSaveStudentMarksView — the
          exact same canonical write path a manual click already used).
        - Keyboard navigation: Arrow Up/Down move to the same column in
          the previous/next row; Enter behaves like Arrow Down (Excel-
          style); native Tab/Shift+Tab already works and is untouched.
        - Bulk paste from Excel: pasting a block of cells (tab/newline
          separated) into any marks input fills the matrix rightward/
          downward from that cell, exactly like pasting into a
          spreadsheet, then recalculates every touched row.
        - Undo/Redo: Ctrl+Z / Ctrl+Y (or Ctrl+Shift+Z) walk backward/
          forward through committed edits for the grid currently in
          focus.
        - Validation: any value outside the input's own min/max is
          flagged with a red outline the moment the field is left
          (existing clamping inside examRecalcRow/examMarksEngineSave
          already protects the STORED total; this simply gives the
          teacher immediate visual feedback before they even save).

   Nothing here duplicates the total/grade/pass-fail formula, the
   repository write, or the report-card bridge — every save still
   flows through the exact same examMarksEngineSave()/getMarks()+
   saveMarkData() paths already in place. This module only (a) swaps
   read sources for the AcademicEngine.* namespaces where a dropdown
   or grid was reading raw storage directly, and (b) adds editing
   ergonomics on top of the untouched, already-rendered DOM.

   Installed via the same "preserve as *_legacy, then override"
   pattern used by SUBJECTMAP-UI-V3 / EXAM-MASTER-UI-V3 above, so a
   console rollback (`window.examLoadMarksGrid = window.examLoadMarksGrid_legacy`)
   is always available.
═══════════════════════════════════════════════════════════════ */
(function (global) {
  'use strict';

  function engineExams()    { return global.AcademicEngine && global.AcademicEngine.Exams; }
  function engineSubjects() { return global.AcademicEngine && global.AcademicEngine.Subjects; }
  function engineMarks()    { return global.AcademicEngine && global.AcademicEngine.Marks; }

  function allExams() {
    var eng = engineExams();
    if (eng && typeof eng.getAll === 'function') { try { return eng.getAll(); } catch (e) {} }
    return (typeof global.examRetrieve === 'function') ? global.examRetrieve('examinations', []) : [];
  }

  function allSubjectMaps() {
    var eng = engineSubjects();
    if (eng && typeof eng.getAll === 'function') { try { return eng.getAll(); } catch (e) {} }
    return (typeof global.examRetrieve === 'function') ? global.examRetrieve('subjectMap', []) : [];
  }

  function subjectMapsForExam(examId) {
    var eng = engineSubjects();
    if (eng && typeof eng.getByExam === 'function') { try { return eng.getByExam(examId); } catch (e) {} }
    return allSubjectMaps().filter(function (m) { return m.examId === examId; });
  }

  // ── 1) DROPDOWN SOURCING — same option markup/order as the legacy
  //       versions, only the array they read from changes. ────────
  function examPopulateMarksExamFilter_v2() {
    var exams = allExams();
    var sel = document.getElementById('meExam');
    if (!sel) return;
    sel.innerHTML = '<option value="">— Select —</option>' +
      exams.map(function (e) { return '<option value="' + e.id + '">' + global.examSanitize(e.name) + '</option>'; }).join('');
    document.getElementById('meClass').innerHTML = '<option value="">— Select —</option>';
    document.getElementById('meDivision').innerHTML = '<option value="">— Select —</option>';
    document.getElementById('meSubject').innerHTML = '<option value="">— Select —</option>';
  }

  function examMarksPopulateClasses_v2() {
    var examId = document.getElementById('meExam').value;
    var maps = subjectMapsForExam(examId);
    var classes = maps.map(function (m) { return m.className; })
      .filter(function (v, i, a) { return v && a.indexOf(v) === i; });

    if (typeof global.currentUser !== 'undefined' && global.currentUser && global.currentUser.role === 'teacher' && !global.currentUser.viewAll) {
      var assignments = global.currentUser.classAssignments || [];
      var allowedClasses = {};
      assignments.forEach(function (a) { allowedClasses[a.split('-')[0]] = true; });
      if (Object.keys(allowedClasses).length) classes = classes.filter(function (c) { return allowedClasses[c]; });
    }

    var sel = document.getElementById('meClass');
    sel.innerHTML = '<option value="">— Select —</option>' +
      classes.sort().map(function (c) { return '<option value="' + c + '">' + global.examSanitize(c) + '</option>'; }).join('');
    document.getElementById('meDivision').innerHTML = '<option value="">— Select —</option>';
    document.getElementById('meSubject').innerHTML = '<option value="">— Select —</option>';
    document.getElementById('examMarksGridCard').style.display = 'none';
  }

  function examMarksPopulateDivisions_v2() {
    var examId = document.getElementById('meExam').value;
    var className = document.getElementById('meClass').value;
    if (typeof global.examEnsureSubjectMapForExam === 'function') global.examEnsureSubjectMapForExam(examId, className);
    var maps = subjectMapsForExam(examId).filter(function (m) { return m.className === className; });
    var divs = maps.map(function (m) { return m.division; }).filter(function (v, i, a) { return v && a.indexOf(v) === i; });

    if (typeof global.currentUser !== 'undefined' && global.currentUser && global.currentUser.role === 'teacher' && !global.currentUser.viewAll) {
      var assignments = global.currentUser.classAssignments || [];
      var allowedDivs = {};
      assignments.forEach(function (a) { var p = a.split('-'); if (p[0] === className) allowedDivs[p[1]] = true; });
      if (Object.keys(allowedDivs).length) divs = divs.filter(function (d) { return allowedDivs[d] || d === 'All'; });
    }

    var sel = document.getElementById('meDivision');
    sel.innerHTML = '<option value="">— Select —</option>' +
      divs.map(function (d) { return '<option value="' + d + '">' + global.examSanitize(d === 'All' ? 'All Divisions' : d) + '</option>'; }).join('');
    document.getElementById('meSubject').innerHTML = '<option value="">— Select —</option>';
    document.getElementById('meStudent').innerHTML = '<option value="">— All Students (subject-wise entry above) —</option>';
    document.getElementById('examMarksGridCard').style.display = 'none';
    document.getElementById('meStudentViewCard').style.display = 'none';
    var cosch = document.getElementById('ume-cosch-card');
    if (cosch) cosch.style.display = 'none';
  }

  function examMarksPopulateSubjects_v2() {
    var examId = document.getElementById('meExam').value;
    var className = document.getElementById('meClass').value;
    var division = document.getElementById('meDivision').value;
    var maps = subjectMapsForExam(examId).filter(function (m) {
      return m.className === className && (m.division === division || m.division === 'All');
    });
    var sel = document.getElementById('meSubject');
    sel.innerHTML = '<option value="">— Select —</option>' +
      maps.map(function (m) { return '<option value="' + m.id + '">' + global.examSanitize(m.subjectName) + '</option>'; }).join('');
    var hint = document.getElementById('meSubjectEmptyHint');
    if (hint) hint.style.display = maps.length ? 'none' : '';
    document.getElementById('examMarksGridCard').style.display = 'none';
    if (typeof global.examMarksPopulateStudents === 'function') global.examMarksPopulateStudents();

    var struct = (typeof global.getMarkStructure === 'function') ? global.getMarkStructure(className) : {};
    var coschCard = document.getElementById('ume-cosch-card');
    if (division && struct.type !== 'college') {
      var exam = allExams().filter(function (e) { return e.id === examId; })[0];
      var termName = ((exam && exam.termName) || '').toLowerCase();
      var termKey = termName.indexOf('2') !== -1 ? '2' : '1';
      global._umeClass = className; global._umeDiv = division; global._umeTerm = termKey;
      var allStudents = (typeof global.getStudents === 'function') ? global.getStudents() : [];
      var coschStudents = allStudents.filter(function (s) { return s.cls === className && (division === 'All' || s.div === division); })
        .sort(function (a, b) { return (Number(a.roll) || 0) - (Number(b.roll) || 0); });
      if (coschCard) coschCard.style.display = coschStudents.length ? '' : 'none';
      if (coschStudents.length && typeof global.umeRenderCosch === 'function') global.umeRenderCosch(coschStudents, className, division, termKey);
    } else if (coschCard) {
      coschCard.style.display = 'none';
    }
  }

  function qtePopulateClasses_v2() {
    var sel = document.getElementById('qteClass');
    if (!sel) return;
    var prev = sel.value;
    var classes = (typeof global.examGetClassOptions === 'function') ? global.examGetClassOptions() : [];
    sel.innerHTML = '<option value="">— Select —</option>' +
      classes.map(function (c) { return '<option value="' + c + '" ' + (c === prev ? 'selected' : '') + '>' + global.examSanitize(c) + '</option>'; }).join('');
    if (prev && classes.indexOf(prev) !== -1 && typeof global.qteClassChanged === 'function') global.qteClassChanged();
  }

  // ── 2) GRID READS via AcademicEngine.Marks — identical DOM output,
  //       only the two direct examRetrieve() lookups are swapped. ──
  function examLoadMarksGrid_v2() {
    var mapId = document.getElementById('meSubject').value;
    var examId = document.getElementById('meExam').value;
    var className = document.getElementById('meClass').value;
    var division = document.getElementById('meDivision').value;
    if (!mapId || !examId || !className) return;

    var maps = allSubjectMaps();
    var subjectMap = maps.filter(function (m) { return m.id === mapId; })[0];
    if (!subjectMap) return;

    var allStudents = global.examGetStudentsForClass(className, division);
    var marksKey = 'marks_' + examId + '_' + className + '_' + division + '_' + mapId;
    var em = engineMarks();
    var savedMarks = em ? em.getAll(examId, className, division, mapId) : global.examRetrieve(marksKey, {});

    var lockKey = 'marksLock_' + examId + '_' + className + '_' + division + '_' + mapId;
    var subjectLocked = em ? em.isLocked(examId, className, division, mapId) : global.examRetrieve(lockKey, false);

    var exams = allExams();
    var examObj = exams.filter(function (e) { return e.id === examId; })[0];
    var resultsLocked = !!(examObj && examObj.isLocked);
    var isLocked = subjectLocked || resultsLocked;

    var card = document.getElementById('examMarksGridCard');
    card.style.display = 'block';
    document.getElementById('examMarksGridTitle').textContent =
      subjectMap.subjectName + ' — Class ' + className + ' ' + (division !== 'All' ? division : '');

    var lockBadge = document.getElementById('examMarksLockBadge');
    lockBadge.textContent = resultsLocked ? 'Locked (Results Locked)' : (subjectLocked ? 'Locked' : 'Unlocked');
    lockBadge.className = 'exam-badge ' + (isLocked ? 'exam-badge-danger' : 'exam-badge-warning');

    var lockBtn = document.getElementById('examLockBtn');
    if (resultsLocked) {
      lockBtn.textContent = '🔒 Locked by Result Processing';
      lockBtn.disabled = true;
      lockBtn.title = 'This exam was Locked in Result Processing by the Principal. Ask them to Unlock it there before editing marks.';
      lockBtn.onclick = null;
    } else {
      lockBtn.disabled = false;
      lockBtn.title = '';
      lockBtn.textContent = subjectLocked ? '🔓 Unlock' : '🔒 Lock';
      lockBtn.onclick = function () { global.examLockMarks(); };
    }

    var hasTheory = subjectMap.theoryMax > 0;
    var hasPract = subjectMap.practMax > 0;
    var hasInternal = subjectMap.intMax > 0;
    var theoryLabel = (hasPract || hasInternal) ? 'Theory' : 'Marks Obtained';

    var thead = document.getElementById('examMarksGridHead');
    thead.innerHTML = '<tr>' +
      '<th style="width:40px">#</th><th>Adm No</th><th>Student Name</th>' +
      (hasTheory ? '<th>' + theoryLabel + '<br><small>Max:' + subjectMap.theoryMax + '</small></th>' : '') +
      (hasPract ? '<th>Practical<br><small>Max:' + subjectMap.practMax + '</small></th>' : '') +
      (hasInternal ? '<th>Internal<br><small>Max:' + subjectMap.intMax + '</small></th>' : '') +
      '<th>Grace</th><th>Absent</th><th>Total</th><th>%</th><th>Grade</th><th>Result</th></tr>';

    var tbody = document.getElementById('examMarksGridBody');
    tbody.innerHTML = '';

    if (!allStudents.length) {
      tbody.innerHTML = '<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--exam-text-muted)">' +
        'No students found for Class ' + className + (division !== 'All' ? ' ' + division : '') +
        '. Ensure students are registered in Student Management.</td></tr>';
      global.examUpdateMarksStats([], subjectMap);
      return;
    }

    allStudents.forEach(function (student, idx) {
      var sid = student.id || student.admissionNo || idx;
      var m = savedMarks[sid] || {};
      var isAbsent = m.absent === true;
      var row = document.createElement('tr');
      row.id = 'marks_row_' + sid;
      if (isAbsent) row.classList.add('is-absent');

      var theoryCell = hasTheory ? '<td><input type="number" class="marks-theory" data-sid="' + sid + '" min="0" max="' + subjectMap.theoryMax + '" value="' + (isAbsent ? '' : (m.theory != null ? m.theory : '')) + '" ' + (isLocked || isAbsent ? 'disabled' : '') + ' oninput="examRecalcRow(\'' + sid + '\',\'' + mapId + '\')"/></td>' : '';
      var practCell = hasPract ? '<td><input type="number" class="marks-pract" data-sid="' + sid + '" min="0" max="' + subjectMap.practMax + '" value="' + (isAbsent ? '' : (m.pract != null ? m.pract : '')) + '" ' + (isLocked || isAbsent ? 'disabled' : '') + ' oninput="examRecalcRow(\'' + sid + '\',\'' + mapId + '\')"/></td>' : '';
      var internalCell = hasInternal ? '<td><input type="number" class="marks-int" data-sid="' + sid + '" min="0" max="' + subjectMap.intMax + '" value="' + (isAbsent ? '' : (m.internal != null ? m.internal : '')) + '" ' + (isLocked || isAbsent ? 'disabled' : '') + ' oninput="examRecalcRow(\'' + sid + '\',\'' + mapId + '\')"/></td>' : '';

      var graceMax = subjectMap.hasGrace === 'yes' ? 10 : 0;
      var graceCell = '<td><input type="number" class="marks-grace" data-sid="' + sid + '" min="0" max="' + graceMax + '" value="' + (isAbsent ? '' : (m.grace != null ? m.grace : 0)) + '" ' + (isLocked || isAbsent || graceMax === 0 ? 'disabled' : '') + ' oninput="examRecalcRow(\'' + sid + '\',\'' + mapId + '\')"/></td>';

      row.innerHTML =
        '<td style="color:var(--exam-text-muted);font-size:12px">' + (idx + 1) + '</td>' +
        '<td><strong>' + global.examSanitize(student.admissionNo || student.id || '—') + '</strong></td>' +
        '<td>' + global.examSanitize(student.name || ((student.firstName || '') + ' ' + (student.lastName || ''))) + '</td>' +
        theoryCell + practCell + internalCell + graceCell +
        '<td><input type="checkbox" class="exam-checkbox marks-absent" data-sid="' + sid + '" ' + (isAbsent ? 'checked' : '') + ' ' + (isLocked ? 'disabled' : '') + ' onchange="examToggleAbsent(\'' + sid + '\',\'' + mapId + '\')"/></td>' +
        '<td id="total_' + sid + '" class="marks-computed">' + (isAbsent ? '<span class="exam-badge exam-badge-danger">AB</span>' : (m.total != null ? m.total : '—')) + '</td>' +
        '<td id="pct_' + sid + '" class="marks-computed">' + (isAbsent ? '—' : (m.pct ? m.pct + '%' : '—')) + '</td>' +
        '<td id="grade_' + sid + '" class="marks-computed">' + (isAbsent ? '—' : (m.grade || '—')) + '</td>' +
        '<td id="result_' + sid + '" class="marks-computed">' +
          (isAbsent ? '<span class="exam-badge exam-badge-warning">Absent</span>' :
            (m.result === 'Pass' ? '<span class="exam-badge exam-badge-success">Pass</span>' :
              (m.result === 'Fail' ? '<span class="exam-badge exam-badge-danger">Fail</span>' : '—'))) +
        '</td>';
      tbody.appendChild(row);
    });

    global.examCurrentMarksContext = { examId: examId, className: className, division: division, mapId: mapId, subjectMap: subjectMap, marksKey: marksKey, isLocked: isLocked, allStudents: allStudents };
    global.examUpdateMarksStats(allStudents.map(function (s) { return savedMarks[s.id || s.admissionNo || '']; }).filter(Boolean), subjectMap);
  }

  // ── 3) UX LAYER — event-delegated, works on whatever grid is
  //       currently rendered without needing to be re-bound. ──────
  var GRID_DEFS = [
    { container: 'examMarksEntry', selector: '.marks-theory,.marks-pract,.marks-int,.marks-grace', save: function () { if (typeof global.examSaveMarks === 'function') global.examSaveMarks(); } },
    { container: 'examMarksEntry', selector: '.qte-fa1,.qte-fa2,.qte-sa1', save: function () { if (typeof global.qteSaveAll === 'function') global.qteSaveAll(); } },
    { container: 'examMarksEntry', selector: '.msv-theory,.msv-pract,.msv-int,.msv-grace', save: function () { if (typeof global.examSaveStudentMarksView === 'function') global.examSaveStudentMarksView(); } }
  ];

  function defFor(el) {
    for (var i = 0; i < GRID_DEFS.length; i++) {
      if (el.matches(GRID_DEFS[i].selector)) return GRID_DEFS[i];
    }
    return null;
  }

  function isTrackedInput(el) {
    return !!(el && el.tagName === 'INPUT' && el.type === 'number' && defFor(el));
  }

  // Undo/redo — one shared stack; each entry remembers which input it
  // belongs to, so switching grids doesn't corrupt history.
  var undoStack = [];
  var redoStack = [];
  var MAX_HISTORY = 200;

  function commitChange(input, oldVal, newVal) {
    if (oldVal === newVal) return;
    undoStack.push({ input: input, oldVal: oldVal, newVal: newVal });
    if (undoStack.length > MAX_HISTORY) undoStack.shift();
    redoStack.length = 0;
  }

  function applyValue(input, val) {
    input.value = val;
    validateInput(input);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function undo() {
    var entry = undoStack.pop();
    if (!entry || !document.body.contains(entry.input)) return;
    redoStack.push(entry);
    applyValue(entry.input, entry.oldVal);
  }

  function redo() {
    var entry = redoStack.pop();
    if (!entry || !document.body.contains(entry.input)) return;
    undoStack.push(entry);
    applyValue(entry.input, entry.newVal);
  }

  // Validation — purely visual; the authoritative clamp already happens
  // server-side (well, store-side) in examComputeSubjectResult/examClamp.
  function validateInput(input) {
    var min = input.min !== '' ? Number(input.min) : null;
    var max = input.max !== '' ? Number(input.max) : null;
    var val = input.value === '' ? null : Number(input.value);
    var invalid = val !== null && ((min !== null && val < min) || (max !== null && val > max));
    input.classList.toggle('marks-invalid', invalid);
    if (invalid) input.title = 'Value must be between ' + min + ' and ' + max;
    else input.removeAttribute('title');
  }

  // Autosave — debounced per grid definition.
  var autosaveTimers = {};
  function scheduleAutosave(def) {
    var key = def.selector;
    clearTimeout(autosaveTimers[key]);
    autosaveTimers[key] = setTimeout(function () {
      try { def.save(); } catch (e) { /* best-effort — manual Save button still works */ }
    }, 1200);
  }

  // Keyboard navigation — Up/Down move within the same column across
  // rows; Enter behaves like Down. Tab/Shift+Tab are left to the browser.
  function trackedInputsIn(container, selector) {
    return Array.prototype.slice.call(container.querySelectorAll(selector))
      .filter(function (el) { return !el.disabled; });
  }

  function moveFocus(input, def, dir) {
    var container = document.getElementById(def.container);
    if (!container) return;
    var group = input.className.split(' ').filter(function (c) { return def.selector.indexOf(c) !== -1; })[0];
    var column = trackedInputsIn(container, '.' + group);
    var idx = column.indexOf(input);
    if (idx === -1) return;
    var next = column[idx + dir];
    if (next) { next.focus(); next.select && next.select(); }
  }

  // Bulk paste from Excel — fills the matrix of same-group inputs
  // starting at the pasted cell, row-wise then column-wise, matching
  // how a spreadsheet paste behaves.
  function handlePaste(e, input, def) {
    var text = (e.clipboardData || window.clipboardData).getData('text');
    if (!text || text.indexOf('\t') === -1 && text.indexOf('\n') === -1) return; // single value — let default paste happen
    e.preventDefault();

    var container = document.getElementById(def.container);
    var rows = text.replace(/\r/g, '').split('\n').filter(function (r, i, arr) { return !(i === arr.length - 1 && r === ''); });
    var grid = rows.map(function (r) { return r.split('\t'); });

    // Column group for the pasted-into field, and the row it started on.
    var thisRow = input.closest('tr');
    var group = input.className.split(' ').filter(function (c) { return def.selector.indexOf(c) !== -1; })[0];
    var allRows = Array.prototype.slice.call(container.querySelectorAll('tr'))
      .filter(function (tr) { return tr.querySelector('.' + group); });
    var startRowIdx = allRows.indexOf(thisRow);
    if (startRowIdx === -1) return;

    // All tracked columns present in this row, in DOM order, starting
    // from the pasted-into column — so a multi-column paste (e.g. Theory
    // + Practical copied together from Excel) fills sideways too.
    var rowGroups = Array.prototype.slice.call(thisRow.querySelectorAll('input[type="number"]'))
      .map(function (el) { return el.className.split(' ').filter(function (c) { return def.selector.indexOf(c) !== -1; })[0]; })
      .filter(Boolean);
    var startColIdx = rowGroups.indexOf(group);
    if (startColIdx === -1) startColIdx = 0;

    grid.forEach(function (cols, r) {
      var targetRow = allRows[startRowIdx + r];
      if (!targetRow) return;
      cols.forEach(function (val, c) {
        var g = rowGroups[startColIdx + c];
        if (!g) return;
        var el = targetRow.querySelector('.' + g);
        if (!el || el.disabled) return;
        var trimmed = val.trim();
        if (trimmed === '') return;
        var old = el.value;
        el.value = trimmed;
        validateInput(el);
        el.dispatchEvent(new Event('input', { bubbles: true }));
        commitChange(el, old, trimmed);
      });
    });
    scheduleAutosave(def);
  }

  function installUX() {
    var pendingOldValue = new WeakMap();

    document.addEventListener('focusin', function (e) {
      if (isTrackedInput(e.target)) pendingOldValue.set(e.target, e.target.value);
    });

    document.addEventListener('input', function (e) {
      if (!isTrackedInput(e.target)) return;
      validateInput(e.target);
    });

    document.addEventListener('change', function (e) {
      if (!isTrackedInput(e.target)) return;
      var def = defFor(e.target);
      var old = pendingOldValue.has(e.target) ? pendingOldValue.get(e.target) : e.target.value;
      commitChange(e.target, old, e.target.value);
      pendingOldValue.set(e.target, e.target.value);
      validateInput(e.target);
      scheduleAutosave(def);
    });

    // Absent checkboxes also trigger autosave, even though they aren't
    // part of the undo/redo number-input tracking above.
    document.addEventListener('change', function (e) {
      if (!e.target.matches('.marks-absent,.msv-absent')) return;
      var container = e.target.closest('#examMarksEntry');
      if (!container) return;
      scheduleAutosave(GRID_DEFS[e.target.classList.contains('msv-absent') ? 2 : 0]);
    });

    document.addEventListener('paste', function (e) {
      if (!isTrackedInput(e.target)) return;
      var def = defFor(e.target);
      handlePaste(e, e.target, def);
    });

    document.addEventListener('keydown', function (e) {
      var target = e.target;
      if (isTrackedInput(target)) {
        var def = defFor(target);
        if (e.key === 'ArrowDown') { e.preventDefault(); moveFocus(target, def, 1); }
        else if (e.key === 'ArrowUp') { e.preventDefault(); moveFocus(target, def, -1); }
        else if (e.key === 'Enter') { e.preventDefault(); target.blur(); moveFocus(target, def, 1); }
      }
      var ctrl = e.ctrlKey || e.metaKey;
      if (ctrl && !e.altKey && e.key.toLowerCase() === 'z' && !e.shiftKey) {
        if (isTrackedInput(document.activeElement) || undoStack.length) { e.preventDefault(); undo(); }
      } else if (ctrl && !e.altKey && (e.key.toLowerCase() === 'y' || (e.shiftKey && e.key.toLowerCase() === 'z'))) {
        if (isTrackedInput(document.activeElement) || redoStack.length) { e.preventDefault(); redo(); }
      }
    });
  }

  // ============================================================
  // INSTALL — additive only, identical guarded pattern to the Exam
  // Master V3 / Subject Mapping V3 blocks above: preserves every
  // original as *_legacy, then reassigns the live window.<name> to
  // this module's implementation.
  // ============================================================
  function install() {
    var map = {
      examPopulateMarksExamFilter: examPopulateMarksExamFilter_v2,
      examMarksPopulateClasses: examMarksPopulateClasses_v2,
      examMarksPopulateDivisions: examMarksPopulateDivisions_v2,
      examMarksPopulateSubjects: examMarksPopulateSubjects_v2,
      qtePopulateClasses: qtePopulateClasses_v2,
      examLoadMarksGrid: examLoadMarksGrid_v2
    };

    Object.keys(map).forEach(function (name) {
      var legacyName = name + '_legacy';
      if (typeof window[legacyName] !== 'function' && typeof window[name] === 'function') {
        window[legacyName] = window[name];
      }
      window[name] = map[name];
    });

    installUX();
    return true;
  }

  install();

})(window);


/* ===================== next inline <script> block ===================== */


/* ═══════════════════════════════════════════════════════════════
   Result Processing Upgrade V1
   ───────────────────────────────────────────────────────────────
   This file already contains a complete, self-verifying staged
   cutover for Result Processing (EXAM-2.5A through EXAM-3.4A-4):
     - AcademicEngine.computeClassResults()   — the results engine
     - AcademicEngine.Rank.compute()          — class/school ranking
     - AcademicEngine.Promotion.*             — promotion (advisory)
     - AcademicEngine.ReportCard.compute()    — report cards
     - AcademicEngine.Compare                 — diffs the engine's
       output against the legacy calculation before ever trusting it
     - AcademicEngine.Flags                   — four booleans that
       gate each module, all defaulting to false ("shadow mode")
     - AcademicEngine.Rollout.canEnable*()    — the built-in readiness
       check for each module (self-test + integration-test + a
       migration-safety check), already wired to those same flags

   Every call site that matters — examRecomputeResultsForClass()
   (EXAM-2.5C, the ONE function every Result Processing screen funnels
   through), runPromotion() (EXAM-3.1A-3), and the report-card builder
   (EXAM-2.7A/3.2A) — already branches on these flags and ALREADY
   falls back to the legacy math automatically, per-call, whenever
   AcademicEngine disagrees with it (EXAM-2.5B comparison) or isn't
   ready. Nothing about that branching logic is duplicated or
   rewritten here.

   "Remove old calculations — everything calls AcademicEngine" is
   therefore accomplished by turning ON the switches this file's own
   Rollout module was built to control — never by re-deriving totals,
   ranks, pass/fail or grades a second time in yet another location
   (which is exactly the kind of drift Sprint 7.4 fixed once already).
   Because Ranking (examRenderRankList), the Analysis KPI cards
   (Statistics/Failures), and Merit List/Report Cards all read the
   ONE examMod_results store that examRecomputeResultsForClass writes,
   flipping the flags here makes every one of those *downstream*
   without touching their code at all.

   What this module does, concretely:
     1. CUTOVER — on load (and again after DOMContentLoaded, in case
        AcademicEngine finishes registering after this script runs),
        calls AcademicEngine.Rollout.canEnableResultEngine() /
        canEnableRanking() / canEnablePromotion() / canEnableReportCard()
        and sets AcademicEngine.Flags accordingly — ONLY for modules
        that pass their own readiness check. AcademicEngine.Flags is
        documented as pure in-memory state ("never persisted anywhere"),
        so this re-runs every page load — it is the permanent switch,
        not a one-off toggle.
     2. LOGS — every cutover decision is written to the existing
        "Processing Log" panel (#examProcessingLog, via the existing
        examLog() function) so it's visible without adding any new UI.
     3. DISPLAY: STATISTICS / FAILURES / GRACE — after "Compute Results"
        runs, this reads the just-computed examMod_results (now
        AcademicEngine-sourced whenever the flag is live) and logs a
        pass/fail/absent breakdown and total grace marks applied —
        again into the existing log panel, not a new one.
     4. DISPLAY: PROMOTION — when useAcademicPromotion is live, logs
        that AcademicEngine's promotion advisory is available for this
        class. Deliberately does NOT let it decide or move a single
        student — runPromotion()'s own EXAM-3.1A-3 gate already
        documents why that must stay a human decision in the Promotion
        Wizard, and this module does not change that.
     5. RANKING — no code change needed/made: examRenderRankList()
        already reads only examMod_results, so it automatically shows
        AcademicEngine-computed ranks the moment useAcademicRanking is
        live, with zero layout change.

   Installed via the same "preserve as *_legacy, then override" pattern
   used throughout this file (SUBJECTMAP-UI-V3, EXAM-MASTER-UI-V3,
   MARKS-ENTRY-UPGRADE-V1): examProcessResults is the only function
   reassigned, and only to call its own legacy body first, unchanged,
   then append the AcademicEngine-sourced log summary.
═══════════════════════════════════════════════════════════════ */
(function (global) {
  'use strict';

  function ae() { return global.AcademicEngine || {}; }

  function logSafe(msg, level) {
    if (typeof global.examLog === 'function') {
      try { global.examLog(msg, level || 'info'); return; } catch (e) { /* fall through */ }
    }
    try { console.log('[Result Processing Upgrade] ' + msg); } catch (e) { /* no-op */ }
  }

  // ── 1) CUTOVER — flip only the flags whose own Rollout.canEnable*()
  //       readiness check currently passes. Never forces a flag true
  //       against its own governance. ─────────────────────────────
  var CUTOVER_MAP = [
    { flag: 'useAcademicResultEngine', can: 'canEnableResultEngine', label: 'Result Engine (totals, %, grade, pass/fail)' },
    { flag: 'useAcademicRanking',      can: 'canEnableRanking',      label: 'Ranking (class & school rank)' },
    { flag: 'useAcademicPromotion',    can: 'canEnablePromotion',    label: 'Promotion (advisory)' },
    { flag: 'useAcademicReportCard',   can: 'canEnableReportCard',   label: 'Report Cards' }
  ];

  var lastCutoverSignature = null;

  function runCutover(silent) {
    var rollout = ae().Rollout;
    var flags = ae().Flags;
    if (!rollout || !flags || typeof flags.set !== 'function' || typeof flags.get !== 'function') {
      if (!silent) logSafe('AcademicEngine.Rollout/Flags not loaded yet — Result Processing stays on legacy calculations for now.', 'warning');
      return;
    }

    var enabled = [], blocked = [];
    CUTOVER_MAP.forEach(function (c) {
      var canFn = rollout[c.can];
      var ready = false;
      try { ready = (typeof canFn === 'function') && canFn() === true; } catch (e) { ready = false; }
      if (ready) {
        var patch = {}; patch[c.flag] = true;
        flags.set(patch);
        enabled.push(c.label);
      } else {
        blocked.push(c.label);
      }
    });

    // Only log when the outcome actually changed, so re-checks on every
    // "Compute Results" click don't spam the panel with repeats.
    var signature = enabled.join('|') + '::' + blocked.join('|');
    if (signature === lastCutoverSignature) return;
    lastCutoverSignature = signature;

    if (enabled.length) logSafe('AcademicEngine live for: ' + enabled.join(', ') + '.', 'success');
    if (blocked.length) logSafe('Still legacy (readiness check not passed yet) for: ' + blocked.join(', ') + '.', 'warning');
  }

  runCutover(true);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { runCutover(false); });
  } else {
    runCutover(false);
  }

  // ── 2/3/4) POST-COMPUTE SUMMARY — Statistics / Failures / Grace /
  //       Promotion, read (never recalculated) from the exact
  //       examMod_results records examRecomputeResultsForClass just
  //       wrote, and logged into the existing Processing Log panel.
  //       Ranking needs no equivalent here — examRenderRankList reads
  //       the same store directly. ────────────────────────────────
  function logResultSummary(examId) {
    try {
      if (!examId || typeof global.examRetrieve !== 'function') return;
      var resultsForExam = global.examRetrieve('results', {})[examId] || {};
      var all = [];
      Object.keys(resultsForExam).forEach(function (cls) {
        Object.values(resultsForExam[cls] || {}).forEach(function (s) { all.push(s); });
      });
      if (!all.length) return;

      var passed = all.filter(function (s) { return s.result === 'Pass'; }).length;
      var failed = all.filter(function (s) { return s.result === 'Fail'; }).length;
      var absent = all.filter(function (s) { return s.result === 'Absent'; }).length;

      var graceUsed = 0;
      all.forEach(function (s) {
        Object.keys(s.subjectResults || {}).forEach(function (subName) {
          var sub = s.subjectResults[subName];
          if (sub && sub.grace) graceUsed += Number(sub.grace) || 0;
        });
      });

      var flags = (ae().Flags && typeof ae().Flags.get === 'function') ? ae().Flags.get() : {};
      var engineNote = flags.useAcademicResultEngine ? 'AcademicEngine' : 'legacy formula';

      logSafe('Statistics (' + engineNote + '): ' + all.length + ' students — ' + passed + ' passed, ' + failed + ' failed, ' + absent + ' absent.', 'info');
      if (failed > 0) logSafe(failed + ' student(s) currently failing — review before locking results.', 'warning');
      if (graceUsed > 0) logSafe('Grace marks applied: ' + graceUsed + ' total mark(s) across all subjects/students.', 'info');

      if (flags.useAcademicRanking) {
        logSafe('Ranking (AcademicEngine): class & school ranks recomputed — see Rank & Merit Preview below.', 'info');
      }
      if (flags.useAcademicPromotion && ae().Promotion) {
        logSafe('Promotion advisory (AcademicEngine.Promotion) available for this class — actual promotion is still decided in Academic Years → Promotion Wizard.', 'info');
      }
    } catch (e) {
      // Summary logging is best-effort only — must never block or alter
      // Result Processing itself.
    }
  }

  // ============================================================
  // INSTALL — additive only, identical guarded pattern to
  // MARKS-ENTRY-UPGRADE-V1 / SUBJECTMAP-UI-V3 above: preserve the
  // original as *_legacy (called first, unmodified, so every existing
  // behavior — including its own AcademicEngine cutover calls inside
  // examRecomputeResultsForClass — runs exactly as before), then
  // append the read-only AcademicEngine-sourced log summary.
  // ============================================================
  function install() {
    if (typeof window.examProcessResults === 'function' && typeof window.examProcessResults_legacy !== 'function') {
      window.examProcessResults_legacy = window.examProcessResults;
    }
    if (typeof window.examProcessResults_legacy === 'function') {
      window.examProcessResults = function () {
        window.examProcessResults_legacy();
        runCutover(true); // pick up any readiness change since page load
        var examId = document.getElementById('rpExam') ? document.getElementById('rpExam').value : '';
        logResultSummary(examId);
      };
    }
    return true;
  }

  install();

})(window);


/* ===================== next inline <script> block ===================== */


/* ═══════════════════════════════════════════════════════════════
   Result Processing Upgrade V2
   ───────────────────────────────────────────────────────────────
   V1 (above) already gates Result Processing, Ranking and Promotion
   through AcademicEngine and logs a one-line summary after each
   "Compute Results" run. What V1 does NOT do is expose that summary
   logic as reusable, independently-testable public APIs — it's all
   inlined inside one private function. This module fixes that,
   per project rules 5 ("every module exposes public APIs through
   AcademicEngine") and 15 ("every feature must be testable
   independently"), WITHOUT touching a single line of V1 or any
   legacy function:

     AcademicEngine.Statistics.compute(examId, className)
     AcademicEngine.Failures.compute(examId, className)
     AcademicEngine.Grace.compute(examId, className)
     AcademicEngine.Logs.{add,get,clear,exportCSV}
     AcademicEngine.Display.{renderStatistics,renderFailures,renderGrace}

   All five read ONLY the existing 'results' store written by
   examRecomputeResultsForClass (the same store V1 and the Analysis/
   Ranking screens already read) — no data is recalculated, no
   LocalStorage schema is touched, and a brand-new key
   ('academicEngineLogs') is used for the persistent log so nothing
   existing is modified (rule 14).

   Installed via the same "preserve as *_legacy, then override"
   pattern as every other upgrade in this file. Because V1 already
   reassigned window.examProcessResults once, this wrapper preserves
   THAT version (not the original) under a new name so both layers
   keep running, in order, forever.
═══════════════════════════════════════════════════════════════ */
(function (global) {
  'use strict';

  function ae() { return global.AcademicEngine || {}; }

  function logSafe(msg, level) {
    if (typeof global.examLog === 'function') {
      try { global.examLog(msg, level || 'info'); return; } catch (e) { /* fall through */ }
    }
    try { console.log('[Result Processing V2] ' + msg); } catch (e) { /* no-op */ }
  }

  // ── shared helper: flatten the 'results' store for one exam,
  //    optionally filtered to one class. Never mutates the store. ──
  function collectStudents(examId, className) {
    if (!examId || typeof global.examRetrieve !== 'function') return [];
    var resultsForExam = global.examRetrieve('results', {})[examId] || {};
    var all = [];
    Object.keys(resultsForExam).forEach(function (cls) {
      if (className && cls !== className) return;
      Object.keys(resultsForExam[cls] || {}).forEach(function (sid) {
        var rec = resultsForExam[cls][sid];
        if (rec) all.push(Object.assign({ _studentId: sid, _class: cls }, rec));
      });
    });
    return all;
  }

  function numeric(v) { var n = Number(v); return isFinite(n) ? n : 0; }

  function studentPercent(s) {
    if (s.percentage != null) return numeric(s.percentage);
    if (s.pct != null) return numeric(s.pct);
    if (s.totalMarks != null && s.maxTotal) return (numeric(s.totalMarks) / numeric(s.maxTotal)) * 100;
    return 0;
  }

  // ══════════════════════════════════════════════════════════════
  // AcademicEngine.Statistics — class/subject-wise summary, computed
  // fresh from whatever engine (AcademicEngine or legacy) actually
  // wrote the results this run.
  // ══════════════════════════════════════════════════════════════
  function computeStatistics(examId, className) {
    var all = collectStudents(examId, className);
    var out = {
      examId: examId, className: className || 'All Classes',
      total: all.length, passed: 0, failed: 0, absent: 0,
      passPercent: 0, avgPercent: 0, highest: null, lowest: null,
      subjectWise: {}
    };
    if (!all.length) return out;

    var pctSum = 0;
    all.forEach(function (s) {
      if (s.result === 'Pass') out.passed++;
      else if (s.result === 'Fail') out.failed++;
      else if (s.result === 'Absent') out.absent++;

      var pct = studentPercent(s);
      pctSum += pct;
      if (!out.highest || pct > out.highest.pct) out.highest = { studentId: s._studentId, name: s.name || s.studentName || s._studentId, pct: pct };
      if (!out.lowest || pct < out.lowest.pct) out.lowest = { studentId: s._studentId, name: s.name || s.studentName || s._studentId, pct: pct };

      Object.keys(s.subjectResults || {}).forEach(function (subName) {
        var sub = s.subjectResults[subName];
        if (!sub) return;
        var bucket = out.subjectWise[subName] || (out.subjectWise[subName] = {
          marksSum: 0, count: 0, high: null, low: null, passCount: 0, failCount: 0
        });
        var marks = numeric(sub.total != null ? sub.total : sub.marks);
        bucket.marksSum += marks;
        bucket.count++;
        if (bucket.high == null || marks > bucket.high) bucket.high = marks;
        if (bucket.low == null || marks < bucket.low) bucket.low = marks;
        // A subject is "failed" if its own grade/flag says so, else fall
        // back to the subject passing mark convention used elsewhere in
        // this file (>=35% of that subject's max, when max is known).
        var subFailed = sub.fail === true || sub.result === 'Fail' ||
          (sub.max ? marks < 0.35 * numeric(sub.max) : false);
        if (subFailed) bucket.failCount++; else bucket.passCount++;
      });
    });

    out.avgPercent = Math.round((pctSum / all.length) * 100) / 100;
    out.passPercent = Math.round((out.passed / all.length) * 10000) / 100;

    Object.keys(out.subjectWise).forEach(function (subName) {
      var b = out.subjectWise[subName];
      out.subjectWise[subName] = {
        avg: Math.round((b.marksSum / b.count) * 100) / 100,
        highest: b.high, lowest: b.low,
        passCount: b.passCount, failCount: b.failCount,
        passPercent: b.count ? Math.round((b.passCount / b.count) * 10000) / 100 : 0
      };
    });

    return out;
  }

  // ══════════════════════════════════════════════════════════════
  // AcademicEngine.Failures — per-student, per-subject failure list.
  // Read-only advisory data; never alters a student's result.
  // ══════════════════════════════════════════════════════════════
  function computeFailures(examId, className) {
    var all = collectStudents(examId, className);
    var out = [];
    all.forEach(function (s) {
      var failedSubjects = [];
      Object.keys(s.subjectResults || {}).forEach(function (subName) {
        var sub = s.subjectResults[subName];
        if (!sub) return;
        var marks = numeric(sub.total != null ? sub.total : sub.marks);
        var subFailed = sub.fail === true || sub.result === 'Fail' ||
          (sub.max ? marks < 0.35 * numeric(sub.max) : false);
        if (subFailed) failedSubjects.push(subName);
      });
      if (s.result === 'Fail' || s.result === 'Absent' || failedSubjects.length) {
        out.push({
          studentId: s._studentId,
          name: s.name || s.studentName || s._studentId,
          className: s._class,
          overallResult: s.result || 'Unknown',
          failedSubjects: failedSubjects,
          percent: studentPercent(s)
        });
      }
    });
    return out;
  }

  // ══════════════════════════════════════════════════════════════
  // AcademicEngine.Grace — grace-mark usage summary. Reads the same
  // sub.grace field V1's inline logger already reads; does not
  // invent a new grace schema and does not apply/award grace itself
  // (that stays wherever result computation already handles it).
  // ══════════════════════════════════════════════════════════════
  function computeGrace(examId, className) {
    var all = collectStudents(examId, className);
    var totalGrace = 0;
    var byStudent = [];
    all.forEach(function (s) {
      Object.keys(s.subjectResults || {}).forEach(function (subName) {
        var sub = s.subjectResults[subName];
        var g = sub && Number(sub.grace) || 0;
        if (g > 0) {
          totalGrace += g;
          byStudent.push({
            studentId: s._studentId,
            name: s.name || s.studentName || s._studentId,
            subject: subName,
            grace: g
          });
        }
      });
    });
    return { examId: examId, className: className || 'All Classes', totalGrace: totalGrace, byStudent: byStudent };
  }

  // ══════════════════════════════════════════════════════════════
  // AcademicEngine.Logs — small persistent audit trail, separate
  // LocalStorage key so it can never collide with or migrate any
  // existing schema (rule 14). Capped at 500 entries (FIFO) so it
  // can't grow unbounded.
  // ══════════════════════════════════════════════════════════════
  var LOG_KEY = 'academicEngineLogs';
  var LOG_CAP = 500;

  function readLogs() {
    try {
      var raw = global.localStorage.getItem(LOG_KEY);
      var arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr : [];
    } catch (e) { return []; }
  }

  function writeLogs(arr) {
    try { global.localStorage.setItem(LOG_KEY, JSON.stringify(arr.slice(-LOG_CAP))); } catch (e) { /* storage full/unavailable — best effort only */ }
  }

  function addLog(entry) {
    var arr = readLogs();
    arr.push(Object.assign({
      ts: new Date().toISOString(),
      module: 'General',
      level: 'info',
      message: ''
    }, entry || {}));
    writeLogs(arr);
    return arr[arr.length - 1];
  }

  function getLogs(filter) {
    var arr = readLogs();
    if (!filter) return arr;
    return arr.filter(function (e) {
      if (filter.module && e.module !== filter.module) return false;
      if (filter.level && e.level !== filter.level) return false;
      if (filter.examId && e.examId !== filter.examId) return false;
      return true;
    });
  }

  function clearLogs() { writeLogs([]); return true; }

  function exportLogsCSV() {
    var arr = readLogs();
    var header = 'Timestamp,Module,Level,ExamId,Message';
    var rows = arr.map(function (e) {
      var msg = String(e.message || '').replace(/"/g, '""');
      return [e.ts, e.module, e.level, e.examId || '', '"' + msg + '"'].join(',');
    });
    return [header].concat(rows).join('\n');
  }

  // ══════════════════════════════════════════════════════════════
  // AcademicEngine.Display — renders the above into the EXISTING
  // page elements only (no new panels, no layout change, rule 10):
  //   - Processing Log panel (#examProcessingLog, via examLog)
  //   - Analysis KPI cards (#kpiTotal / #kpiPassed / #kpiFailed /
  //     #kpiAbsent / #kpiAvgPct / #kpiPassPct) — same IDs the
  //     existing Analysis screen already fills in, ONLY updated
  //     here when the exam/class the caller asked for matches what
  //     the Analysis filters currently show, so this can never
  //     silently overwrite a KPI card with numbers for a different
  //     exam/class than the one the user is looking at.
  // Every render also appends one entry to AcademicEngine.Logs so
  // the summary survives a page refresh (unlike the DOM log panel).
  // ══════════════════════════════════════════════════════════════
  function kpiMatchesSelection(examId, className) {
    var anExam = document.getElementById('anExam');
    var anClass = document.getElementById('anClass');
    if (!anExam || !anClass) return false;
    var classOk = !className || anClass.value === className || anClass.value === '';
    return anExam.value === examId && classOk;
  }

  function setText(id, val) {
    var el = document.getElementById(id);
    if (el) el.textContent = val;
  }

  function renderStatistics(examId, className) {
    var stats = computeStatistics(examId, className);
    logSafe('Statistics: ' + stats.total + ' students in ' + stats.className +
      ' — avg ' + stats.avgPercent + '%, pass ' + stats.passPercent + '%.', 'info');
    addLog({ module: 'Statistics', level: 'info', examId: examId, message: JSON.stringify({
      className: stats.className, total: stats.total, passed: stats.passed,
      failed: stats.failed, absent: stats.absent, avgPercent: stats.avgPercent, passPercent: stats.passPercent
    }) });
    if (kpiMatchesSelection(examId, className)) {
      setText('kpiTotal', stats.total);
      setText('kpiPassed', stats.passed);
      setText('kpiFailed', stats.failed);
      setText('kpiAbsent', stats.absent);
      setText('kpiAvgPct', stats.avgPercent + '%');
      setText('kpiPassPct', stats.passPercent + '%');
    }
    return stats;
  }

  function renderFailures(examId, className) {
    var failures = computeFailures(examId, className);
    if (failures.length) {
      logSafe(failures.length + ' student(s) with failing subjects/overall — see Failures for detail.', 'warning');
    }
    addLog({ module: 'Failures', level: failures.length ? 'warning' : 'info', examId: examId,
      message: failures.length + ' failing student(s) in ' + (className || 'All Classes') });
    return failures;
  }

  function renderGrace(examId, className) {
    var grace = computeGrace(examId, className);
    if (grace.totalGrace > 0) {
      logSafe('Grace marks applied: ' + grace.totalGrace + ' total mark(s) across ' + grace.byStudent.length + ' subject entr' + (grace.byStudent.length === 1 ? 'y' : 'ies') + '.', 'info');
    }
    addLog({ module: 'Grace', level: 'info', examId: examId,
      message: 'Total grace marks: ' + grace.totalGrace + ' (' + grace.byStudent.length + ' entries)' });
    return grace;
  }

  // ── INSTALL public APIs — never overwrite if something with the
  //    same name is already loaded (defensive, per rule 2/4). ─────
  global.AcademicEngine = global.AcademicEngine || {};
  if (!global.AcademicEngine.Statistics) global.AcademicEngine.Statistics = { compute: computeStatistics };
  if (!global.AcademicEngine.Failures) global.AcademicEngine.Failures = { compute: computeFailures };
  if (!global.AcademicEngine.Grace) global.AcademicEngine.Grace = { compute: computeGrace };
  if (!global.AcademicEngine.Logs) global.AcademicEngine.Logs = { add: addLog, get: getLogs, clear: clearLogs, exportCSV: exportLogsCSV };
  if (!global.AcademicEngine.Display) {
    global.AcademicEngine.Display = { renderStatistics: renderStatistics, renderFailures: renderFailures, renderGrace: renderGrace };
  } else {
    // Display namespace already claimed by something else — attach ours
    // under a safe sub-key instead of clobbering it (rule 2).
    global.AcademicEngine.Display.resultProcessing = { renderStatistics: renderStatistics, renderFailures: renderFailures, renderGrace: renderGrace };
  }

  // ── INSTALL — wrap whatever examProcessResults is RIGHT NOW (V1's
  //    wrapped version, if V1 loaded first) so this layer stacks on
  //    top instead of replacing it. ───────────────────────────────
  function install() {
    if (typeof window.examProcessResults === 'function' && typeof window.examProcessResults_legacyV2 !== 'function') {
      window.examProcessResults_legacyV2 = window.examProcessResults;
    }
    if (typeof window.examProcessResults_legacyV2 === 'function') {
      window.examProcessResults = function () {
        window.examProcessResults_legacyV2();
        try {
          var examId = document.getElementById('rpExam') ? document.getElementById('rpExam').value : '';
          var className = document.getElementById('rpClass') ? document.getElementById('rpClass').value : '';
          if (examId) {
            renderStatistics(examId, className);
            renderFailures(examId, className);
            renderGrace(examId, className);
          }
        } catch (e) {
          // Display/Logs are best-effort only — must never block or alter
          // Result Processing itself.
        }
      };
    }
    return true;
  }

  install();

})(window);


