     AcademicEngine.LegacyBridge.saveExam(editId)
     AcademicEngine.LegacyBridge.saveSubject(editId)
     AcademicEngine.LegacyBridge.saveMarks(ctx)
     AcademicEngine.LegacyBridge.processResults(examId, className)
     AcademicEngine.LegacyBridge.generateReportCards(examId, className)
