    let present = 0, total = 0;
    maps.forEach(sm => {
      const marksKey = `marks_${examId}_${className}_${sm.division}_${sm.id}`;
      const m = examRetrieve(marksKey, {})[studentId];
      if (!m) return;
      total++;
      if (!m.absent) present++;
    });
    const pct = total > 0 ? examRound((present / total) * 100) : 0;
    return { present, total, pct };
