(function(){

  function dnkEsc(str){
    return String(str==null?'':str).replace(/[&<>"']/g, function(c){
      return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];
    });
  }

  function dnkApplyCollapseState(){
    var collapsed = false;
    try{ collapsed = localStorage.getItem('dnk_sidebar_collapsed') === '1'; }catch(e){}
    document.body.classList.toggle('dnk-collapsed', collapsed);
  }
  window.dnkToggleCollapse = function(){
    var collapsed = !document.body.classList.contains('dnk-collapsed');
    document.body.classList.toggle('dnk-collapsed', collapsed);
    try{ localStorage.setItem('dnk_sidebar_collapsed', collapsed ? '1' : '0'); }catch(e){}
  };

  var dnkPageTitles = {};
  var dnkPageSections = {};
  function dnkBuildPageTitleMap(){
    var items = document.querySelectorAll('#sidebar .nav-item[onclick*="showPage("]');
    items.forEach(function(el){
      var m = el.getAttribute('onclick').match(/showPage\('([^']+)'\)/);
      if(m){
        var label = el.textContent.trim();
        dnkPageTitles[m[1]] = label;
        el.setAttribute('data-label', label);
        var section = el.closest('.nav-section');
        var sectionLabelEl = section ? section.querySelector('.nav-label') : null;
        dnkPageSections[m[1]] = sectionLabelEl ? sectionLabelEl.textContent.trim() : '';
      }
    });
  }
  function dnkFormatPageKey(key){
    return key.replace(/-/g, ' ').replace(/\b\w/g, function(c){ return c.toUpperCase(); });
  }
  function dnkUpdateModuleTitle(){
    var el = document.getElementById('dnk-module-title');
    if(!el) return;
    var activePage = document.querySelector('#main .page.active');
    if(!activePage || !activePage.id) return;
    var key = activePage.id.replace(/^page-/, '');
    el.textContent = dnkPageTitles[key] || dnkFormatPageKey(key);
  }
  function dnkUpdateBreadcrumb(){
    var el = document.getElementById('dnk-breadcrumb');
    if(!el) return;
    var activePage = document.querySelector('#main .page.active');
    if(!activePage || !activePage.id) return;
    var key = activePage.id.replace(/^page-/, '');
    var title = dnkPageTitles[key] || dnkFormatPageKey(key);
    var section = dnkPageSections[key] || '';
    var parts = ['<span class="dnk-bc-home" onclick="showPage(\'dashboard\')" role="link">🏠 Home</span>'];
    if(section && section.toLowerCase() !== title.toLowerCase()){
      parts.push('<span class="dnk-bc-sep">›</span><span class="dnk-bc-section">'+dnkEsc(section)+'</span>');
    }
    if(key !== 'dashboard'){
      parts.push('<span class="dnk-bc-sep">›</span><span class="dnk-bc-current">'+dnkEsc(title)+'</span>');
    }
    el.innerHTML = parts.join('');
  }
  function dnkObservePages(){
    var main = document.getElementById('main');
    if(!main) return;
    var obs = new MutationObserver(function(){ dnkUpdateModuleTitle(); dnkUpdateBreadcrumb(); });
    main.querySelectorAll('.page').forEach(function(p){
      obs.observe(p, { attributes: true, attributeFilter: ['class'] });
    });
  }

  var dnkLastActiveYearId = null;
  function dnkPopulateAcademicYear(){
    var sel = document.getElementById('dnk-ay-select');
    if(!sel || typeof getAcademicYears !== 'function') return;
    var years = [];
    try{ years = getAcademicYears() || []; }catch(e){}
    var active = null;
    try{ active = (typeof getActiveYear === 'function') ? getActiveYear() : null; }catch(e){}
    if(!years.length){ sel.innerHTML = '<option>—</option>'; return; }
    sel.innerHTML = years.map(function(y){
      var sel2 = (active && active.id === y.id) ? ' selected' : '';
      var dot = y.status === 'active' ? ' ●' : '';
      return '<option value="'+dnkEsc(y.id)+'"'+sel2+'>'+dnkEsc(y.label)+dot+'</option>';
    }).join('');
    // Brief highlight flash whenever the active year actually changed (e.g. someone
    // else switched it from the Academic Years admin page or the Promotion Wizard),
    // so the "live" update in the header is noticeable rather than a silent redraw.
    var activeId = active ? active.id : null;
    if(dnkLastActiveYearId !== null && activeId !== dnkLastActiveYearId){
      sel.style.transition = 'background-color .8s ' + 'ease';
      sel.style.backgroundColor = '#fef3c7';
      setTimeout(function(){ sel.style.backgroundColor = ''; }, 900);
    }
    dnkLastActiveYearId = activeId;
  }
  window.dnkSetActiveYear = function(id){
    if(!id || typeof setActiveAcademicYear !== 'function') return;
    var res = null;
    try{ res = setActiveAcademicYear(id); }catch(e){ res = { ok:false, msg:'Could not switch academic year.' }; }
    if(res && res.ok){
      if(typeof refreshDashboard === 'function'){ try{ refreshDashboard(); }catch(e){} }
    } else if(res && res.msg){
      alert(res.msg);
    }
    dnkPopulateAcademicYear();
  };
  // Academic Year can also be changed directly from the Academic Years admin
  // page (Set Active button) or the Promotion Wizard, bypassing this header's
  // own dropdown entirely. Watch that page for re-renders so the header select
  // reflects the change immediately instead of waiting on the polling interval.
  function dnkObserveAcademicYearPage(){
    var page = document.getElementById('page-acadyears');
    if(!page) return;
    var obs = new MutationObserver(function(){ dnkPopulateAcademicYear(); });
    obs.observe(page, { childList: true, subtree: true });
  }

  var dnkRoleChipColors = { principal:'#c9973a', clerk:'#3b82c4', teacher:'#2fa66a' };
  function dnkRenderProfile(){
    var nameEl = document.getElementById('dnk-profile-name');
    var roleEl = document.getElementById('dnk-profile-role');
    var avatarEl = document.getElementById('dnk-avatar');
    var menuNameEl = document.getElementById('dnk-profile-menu-name');
    var menuRoleEl = document.getElementById('dnk-profile-menu-role');
    var avatarLgEl = document.getElementById('dnk-avatar-lg');
    if(!nameEl) return;
    var user = (typeof currentUser !== 'undefined') ? currentUser : null;
    var name = (user && (user.name || user.username)) || 'User';
    var role = (user && user.role) || '';
    var initial = (name.trim().charAt(0) || 'U').toUpperCase();
    nameEl.textContent = name;
    roleEl.textContent = role;
    if(avatarEl) avatarEl.textContent = initial;
    if(menuNameEl) menuNameEl.textContent = name;
    if(avatarLgEl) avatarLgEl.textContent = initial;
    if(menuRoleEl){
      menuRoleEl.textContent = role || 'User';
      menuRoleEl.style.background = dnkRoleChipColors[role] || '#6b7280';
    }
  }

  // ── Role-aware Quick Actions: hide any action the signed-in role can't use,
  // reusing the same PermissionManager.hasRole(...) check the sidebar's own
  // data-roles filtering already relies on (see initApp's nav-item loop). ──
  function dnkApplyQuickActionRoles(){
    var items = document.querySelectorAll('#dnk-qa-grid .dnk-qa-item[data-roles]');
    var visibleCount = 0;
    items.forEach(function(elm){
      var allowed = elm.getAttribute('data-roles').split(',');
      var ok = true;
      try{
        if(typeof PermissionManager !== 'undefined' && PermissionManager && typeof PermissionManager.hasRole === 'function'){
          ok = PermissionManager.hasRole.apply(PermissionManager, allowed);
        }
      }catch(e){ ok = true; }
      elm.style.display = ok ? '' : 'none';
      if(ok) visibleCount++;
    });
    var emptyEl = document.getElementById('dnk-qa-empty');
    if(emptyEl) emptyEl.style.display = visibleCount ? 'none' : 'block';
  }

  var dnkPrevUnreadCount = -1;
  window.dnkRenderNotifications = async function(){
    var listEl = document.getElementById('dnk-notif-list');
    var badgeEl = document.getElementById('dnk-notif-badge');
    if(!listEl) return;
    try{
      if(typeof WorkflowDB === 'undefined' || typeof WorkflowDB.getAll !== 'function'){
        listEl.innerHTML = '<div class="dnk-notif-empty">Notification Center not available.</div>';
        if(badgeEl) badgeEl.style.display = 'none';
        return;
      }
      var all = await WorkflowDB.getAll('notifications');
      var unread = (all || []).filter(function(n){ return !n.archived && n.status === 'unread'; })
        .sort(function(a,b){ return new Date(b.createdAt) - new Date(a.createdAt); });

      if(badgeEl){
        if(unread.length){
          badgeEl.textContent = unread.length > 99 ? '99+' : String(unread.length);
          badgeEl.style.display = 'flex';
          // Pulse only when unread count has actually gone up since we last
          // checked, so it reads as "something new arrived" rather than firing
          // on every routine poll/re-render.
          if(dnkPrevUnreadCount !== -1 && unread.length > dnkPrevUnreadCount){
            badgeEl.classList.remove('dnk-badge-pulse');
            void badgeEl.offsetWidth; // restart animation
            badgeEl.classList.add('dnk-badge-pulse');
          }
        } else {
          badgeEl.style.display = 'none';
        }
      }
      dnkPrevUnreadCount = unread.length;

      if(!unread.length){
        listEl.innerHTML = '<div class="dnk-notif-empty">🎉 You are all caught up.</div>';
        return;
      }

      // Category-grouped: cluster unread notifications by their existing
      // .category (Admissions/Attendance/Finance/… — see WF_MODULES), most
      // recently active category first, each group internally most-recent-first.
      var byCategory = {};
      var categoryOrder = [];
      unread.forEach(function(n){
        var cat = n.category || 'General';
        if(!byCategory[cat]){ byCategory[cat] = []; categoryOrder.push(cat); }
        byCategory[cat].push(n);
      });
      categoryOrder.sort(function(a,b){
        return new Date(byCategory[b][0].createdAt) - new Date(byCategory[a][0].createdAt);
      });

      var MAX_SHOWN = 10, shown = 0, html = '';
      categoryOrder.forEach(function(cat){
        if(shown >= MAX_SHOWN) return;
        var rows = byCategory[cat].slice(0, MAX_SHOWN - shown);
        shown += rows.length;
        var groupColor = (typeof MODULE_COLOR !== 'undefined' && MODULE_COLOR[cat]) || '#4b5563';
        html += '<div class="dnk-notif-group-label" style="color:'+groupColor+';"><span>'+dnkEsc(cat)+'</span>'
          + '<span class="dnk-notif-group-count">'+byCategory[cat].length+'</span></div>';
        html += rows.map(function(n){
          var icon = (typeof MODULE_ICON !== 'undefined' && MODULE_ICON[n.category]) || '🔔';
          var color = (typeof MODULE_COLOR !== 'undefined' && MODULE_COLOR[n.category]) || '#4b5563';
          var when = (typeof UTIL !== 'undefined' && UTIL.timeAgo) ? UTIL.timeAgo(n.createdAt) : fmtDMY(n.createdAt);
          return '<div class="dnk-notif-row">'
            + '<div class="dnk-notif-icon" style="background:'+color+'22;color:'+color+';">'+icon+'</div>'
            + '<div><div class="dnk-notif-title">'+dnkEsc(n.title || 'Notification')+'</div>'
            + '<div class="dnk-notif-meta">'+dnkEsc(when)+'</div></div>'
            + '</div>';
        }).join('');
      });
      listEl.innerHTML = html;
    }catch(e){
      listEl.innerHTML = '<div class="dnk-notif-empty">Could not load notifications.</div>';
    }
  };

  var dnkSearchGroups = [];
  var dnkSearchGroupColor = { Students:'#e6a319', Teachers:'#2fa66a', Inventory:'#8a5cf6', Suppliers:'#3b82c4', GRN:'#0fb5a6' };
  window.dnkRunGlobalSearch = function(term){
    var box = document.getElementById('dnk-search-results');
    if(!box) return;
    term = (term || '').trim().toLowerCase();
    if(!term){ box.classList.remove('open'); box.innerHTML = ''; return; }
    var groups = [];

    try{
      var students = (typeof getStudents === 'function' ? getStudents() : []).filter(function(s){
        return (s.name||'').toLowerCase().indexOf(term) > -1 ||
               (s.admno||'').toLowerCase().indexOf(term) > -1 ||
               (s.gr||'').toLowerCase().indexOf(term) > -1;
      }).slice(0,5);
      if(students.length) groups.push({ label:'Students', rows: students.map(function(s){
        return { icon:'🎓', title:s.name, sub:'Adm No '+(s.admno||'—')+' · GR '+(s.gr||'—'),
          tag:'Class '+(s.cls||'—')+(s.div?('-'+s.div):''),
          action:function(){ showPage('students'); if(typeof viewStudent === 'function') viewStudent(s.id); } };
      })});
    }catch(e){}

    try{
      var teachers = (typeof getTeachers === 'function' ? getTeachers() : []).filter(function(t){
        return (t.name||'').toLowerCase().indexOf(term) > -1;
      }).slice(0,5);
      if(teachers.length) groups.push({ label:'Teachers', rows: teachers.map(function(t){
        return { icon:'👩‍🏫', title:t.name, sub:t.designation || 'Teacher',
          tag:t.subject || '', action:function(){ showPage('teachers'); } };
      })});
    }catch(e){}

    try{
      var items = (typeof getInventoryItems === 'function' ? getInventoryItems() : []).filter(function(i){
        return (i.name||'').toLowerCase().indexOf(term) > -1 || (i.code||'').toLowerCase().indexOf(term) > -1;
      }).slice(0,5);
      if(items.length) groups.push({ label:'Inventory', rows: items.map(function(i){
        return { icon:'📦', title:i.name, sub:(i.category||'—')+' · Code '+(i.code||'—'),
          tag:'Stock '+(i.stock!=null?i.stock:'—'), action:function(){ showPage('inventory'); } };
      })});
    }catch(e){}

    try{
      var sups = (typeof getSuppliers === 'function' ? getSuppliers() : []).filter(function(s){
        return (s.name||'').toLowerCase().indexOf(term) > -1;
      }).slice(0,5);
      if(sups.length) groups.push({ label:'Suppliers', rows: sups.map(function(s){
        return { icon:'🚚', title:s.name, sub:s.phone || 'Supplier',
          tag:s.gst ? 'GST' : '', action:function(){ showPage('inventory'); } };
      })});
    }catch(e){}

    try{
      var grns = (typeof getGRNs === 'function' ? getGRNs() : []).filter(function(g){
        return (g.id||'').toLowerCase().indexOf(term) > -1;
      }).slice(0,5);
      if(grns.length) groups.push({ label:'GRN', rows: grns.map(function(g){
        return { icon:'📥', title:'GRN '+g.id, sub:'Goods Receipt Note',
          tag:g.date || '', action:function(){ showPage('inventory'); } };
      })});
    }catch(e){}

    dnkSearchGroups = groups;

    if(!groups.length){
      box.innerHTML = '<div class="dnk-search-empty">No matches for "'+dnkEsc(term)+'". Try a name, admission no, or code.</div>';
      box.classList.add('open');
      return;
    }

    var html = '';
    groups.forEach(function(g, gi){
      var color = dnkSearchGroupColor[g.label] || '#4b5563';
      html += '<div class="dnk-search-group-label">'+dnkEsc(g.label)+'</div>';
      g.rows.forEach(function(r, ri){
        html += '<div class="dnk-search-row" data-gi="'+gi+'" data-ri="'+ri+'">'
          + '<div class="dnk-sr-icon" style="background:'+color+'22;color:'+color+';">'+r.icon+'</div>'
          + '<div class="dnk-sr-main"><div class="dnk-sr-title">'+dnkEsc(r.title||'')+'</div>'
          + '<div class="dnk-sr-sub">'+dnkEsc(r.sub||'')+'</div></div>'
          + (r.tag ? '<div class="dnk-sr-tag">'+dnkEsc(r.tag)+'</div>' : '')
          + '<div class="dnk-sr-arrow">›</div>'
          + '</div>';
      });
    });
    html += '<div class="dnk-search-footer">Press Esc to close</div>';
    box.innerHTML = html;
    box.classList.add('open');
    box.querySelectorAll('.dnk-search-row').forEach(function(row){
      row.addEventListener('click', function(){
        var gi = +row.getAttribute('data-gi'), ri = +row.getAttribute('data-ri');
        var r = dnkSearchGroups[gi] && dnkSearchGroups[gi].rows[ri];
        if(r && typeof r.action === 'function') r.action();
        window.dnkCloseSearch();
      });
    });
  };
  window.dnkCloseSearch = function(){
    var box = document.getElementById('dnk-search-results');
    if(box) box.classList.remove('open');
  };

  window.dnkCloseAllDropdowns = function(except){
    ['dnk-qa-dropdown','dnk-notif-dropdown','dnk-profile-dropdown'].forEach(function(id){
      if(id === except) return;
      var el = document.getElementById(id);
      if(el) el.classList.remove('open');
    });
  };
  window.dnkToggleDropdown = function(id){
    if(!id) return;
    var el = document.getElementById(id);
    if(!el) return;
    var willOpen = !el.classList.contains('open');
    window.dnkCloseAllDropdowns(willOpen ? id : null);
    el.classList.toggle('open', willOpen);
    if(willOpen && id === 'dnk-notif-dropdown') window.dnkRenderNotifications();
  };

  document.addEventListener('click', function(e){
    if(!e.target.closest || !e.target.closest('.dnk-hdr-relative')) window.dnkCloseAllDropdowns();
    if(!e.target.closest || !e.target.closest('.dnk-search')) window.dnkCloseSearch();
  });
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape'){ window.dnkCloseAllDropdowns(); window.dnkCloseSearch(); }
    if((e.ctrlKey || e.metaKey) && (e.key === 'k' || e.key === 'K')){
      var input = document.getElementById('dnk-search-input');
      if(input){ e.preventDefault(); input.focus(); }
    }
  });

  function dnkInit(){
    dnkApplyCollapseState();
    dnkBuildPageTitleMap();
    dnkPopulateAcademicYear();
    dnkRenderProfile();
    dnkApplyQuickActionRoles();
    dnkUpdateModuleTitle();
    dnkUpdateBreadcrumb();
    dnkObservePages();
    dnkObserveAcademicYearPage();
  }
  function dnkStart(){
    dnkInit();
    // Re-init the topbar once the pre-login overlay is dismissed (i.e.
    // someone signed in). Both the portal chooser and the staff login form
    // are watched: which of the two is on screen at that moment depends on
    // whether the session was restored or typed in, and on a restore the
    // login form may never be shown at all.
    ['page-login', 'page-portal-select'].forEach(function(id){
      var el = document.getElementById(id);
      if(!el) return;
      var mo = new MutationObserver(function(){
        if(el.style.display === 'none') dnkInit();
      });
      mo.observe(el, { attributes: true, attributeFilter: ['style'] });
    });
    // Academic Year: polled more often (was 20s) so the header stays "live" even
    // in the rare case the mutation observer above misses a change. Notifications
    // are now polled too, so the bell badge (incl. the 99+ pulse) updates without
    // requiring the user to open the dropdown first.
    setInterval(function(){
      dnkPopulateAcademicYear();
      dnkRenderProfile();
      if(typeof window.dnkRenderNotifications === 'function') window.dnkRenderNotifications();
    }, 8000);
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', dnkStart);
  } else {
    dnkStart();
  }

})();
